INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Älsken rättfärdigheten, I som styren på jorden, tänken på Herren med rättskaffens sinne, och söken honom med uppriktigt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ty han låter sig finnas av dem som icke fresta honom, och han uppenbarar sig för dem som ej vägra honom sin tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Vrånga tankar skilja ju människor från Gud, och när hans makt sättes på prov, näpser den de dåraktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Ty i en illfundig själ träder icke visheten in, den tager ej sin boning i en kropp som är gäldbunden under synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Nej, tuktens helige ande undflyr falskheten och håller sig på avstånd från oförnuftiga tankar; den skrämmes bort, när orättfärdigheten nalkas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Ty visheten är en människoälskande ande, och den låter ej hädaren bliva ostraffad för vad hans läppar tala, eftersom Gud är vittne till hans innersta känslor och en sannskyldig väktare över hans hjärta och en som hör hans tungas tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Herrens Ande uppfyller ju världen, och det väsen som sammanhåller allt vet vad som säges.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Därför kan ingen bliva obemärkt, som talar vad orätt är; rättvisan skall icke gå honom förbi med sin näpst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Nej, den ogudaktiges anslag skola komma under prövning, och hans ord skola nå fram till Herrens öron, för att hans överträdelser skola bliva näpsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Ty ett nitälskande öra hör allt, och de knorrandes mummel bliver icke förborgat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Så tagen eder då till vara för onyttigt knorrande, och avhållen eder tunga från smädelse. Ty icke ens en hemlig viskning bliver utan påföljd, och en lögnaktig mun dräper själen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Faren icke så efter döden genom edert förvillade leverne, och dragen ej fördärv över eder genom edra händers verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Ty det är icke Gud som har gjort döden, och han har ej lust till de levandes undergång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Han har ju skapat allt för att vara till, och allt som har blivit till i världen tjänar livet. Intet förstörelsens gift finnes däri; nej, döden har icke väldet på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Ty rättfärdigheten är odödlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Ty de säga vid sig själva i sina förvända tankar: »Kort och eländigt är vårt liv; när en människa skall dö, gives det ingen bot för henne, och någon befriare från dödsriket har aldrig blivit funnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Genom en slump hava vi ju kommit till, och efter detta skola vi vara som om vi aldrig hade funnits. Ty en rök är andedräkten i vår näsa, och tanken en gnista, tänd vid vårt hjärtas slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'När den har slocknat, skall kroppen varda till aska och anden förspridas såsom tunnaste luft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Och vårt namn skall förgätas med tiden, och ingen skall vidare komma ihåg våra verk; vårt liv skall försvinna såsom spåren efter en sky, det skall förflyktigas likasom en dimma som drives undan av solens strålar och bringas att sjunka av dess värme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Ja, vår levnadstid är lik ens skugga som far förbi, och det gives ingen återgång, när vårt slut har kommit; ty detta är beseglat, och ingen kan göra någon ändring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Välan, låt oss då fägna oss med det goda vi hava, låt oss njuta världen med iver, såsom i ungdomsåren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Må vi icke spara på ädelt vin och på salvor och icke låta någon vårens blomma undgå oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Vi vilja bekransa oss med rosenknoppar, förrän de vissna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'ingen av oss må hålla sig borta från våra yppiga gillen, överallt må vi kvarlämna tecken av vår festgädje. Ty detta är vår del och vår lott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Låt oss förtrycka den som är rättfärdig och fattig och icke visa skonsamhet mot änkan eller försyn för den gamles av ålder grånade hår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Nej, må vår styrka vara lagen för det rätta, ty det svaga bevisar sig duga till intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Låt oss lägga försåt för den rättfärdige, eftersom han är oss besvärlig och sätter sig emot våra gärningar och bannar oss för våra försyndelser mot lagen och förevitar oss våra försyndelser mot god tukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Han utgiver sig för att äga kunskap om Gud, och han kallar sig själv ett Herrens barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Han är likasom en anklagelse mot våra tankar, han är oss motbjudande redan till att se på,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'därför att hans leverne är så olikt andras och hans stigar äro så främmande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Såsom falskt mynt äro vi räknade af honom, och han håller sig borta från våra vägar såsom från orenlighet. De rättfärdigas ände prisar han salig och skryter med att Gud är hans fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Låt oss då se om hans ord äro sanna, och pröva hurudan utgången bliver för honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Ty om den rättfärdige är Guds son, skall ju Gud taga sig an honom och frälsa honom ur hans motståndares hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Genom kvalfull misshandling vilja vi utforska honom, för att så lära känna huru tålig han är och pröva huru ståndaktig han är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Till neslig död vilja vi döma honom; Gud skall ju se till honom, efter vad han själv har sagt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Så tänka de, men de fara vilse, ty deras ondska har förblindat dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'de känna icke Guds hemligheter och hoppas icke på någon fromhetens lön och tro icke på någon äreskänk för obefläckade själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Gud skapade ju människan till oförgänglighet och gjorde henne till en avbild av sitt eget väsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Men genom djävulens avund kom döden in i världen, och de som höra honom till, få erfara den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Men de rättfärdigas själar äro i Guds hand, och ingen plåga kan nå dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Väl synas de i de dåraktigas ögon vara döda, och såsom ofärd räknas deras hädanfärd, Mack 7,33; Hebr 12,7.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'och deras bortgång från oss såsom undergång; men de äro i frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Ty om de än, efter vad människor mena, bliva straffade, så är dock deras hopp fyllt av odödlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'och sedan de hava agats något litet, få de röna mycken godhet; Gud satte dem på prov och befann dem sig värdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Såsom guld i degeln prövade han dem, och såsom en heloffergåva mottog han dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'I den stund då han ser till dem skola de framträda i glans, och såsom gnistor bland strå skola de ila fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'De skola döma hedningarna och råda över folken, och Herren skall vara deras konung till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'De som förtrösta på honom, de skola förstå sanningen, och de trogna skola i kärlek förbliva hos honom. Ty nåd och barmhärtighet skall vederfaras hans utvalda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Men de ogudaktiga skola få den näpst deras tankar förtjäna, då de aktade den rättfärdige för intet och avföllo från Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Ty den som föraktar vishet och tukt är ömkansvärd. Ja, fåfängt är deras hopp och deras ävlan gagnlös, och deras gärningar äro till intet nyttiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Deras hustrur äro dåraktiga, och deras barn äro onda; förbannad är deras avkomma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Dock, salig är den ofruktsamma som är obefläckad, som icke vet av syndfullt umgänge; hon skall undfå frukt, när själarna få sin vedergällning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Salig är ock den snöpte som ej har förövat syndiga gärningar eller har haft onda tankar mot Herren; ty han skall få en utvald nådelön för sin trohet och den ljuvligaste lott i Herrens tempel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Ja, dygdens mödor bära härlig frukt, och visheten är en telning som icke förvissnar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Men äktenskapsbrytares barn skola ej nå sin mognad, och avkomma efter syndigt umgänge skall utrotas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Ty om de än få länge leva, skola de dock räknas för intet, och deras ålderdom skall på sistone bliva utan heder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Om de dö tidigt, skola de vara utan hopp och utan tröst på avgörelsens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Ty ett orättfärdigt släkte tager en ond ände.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Nej, bättre är att vara barnlös, men hava dygd; ty odödlighet ligger i dygdens åminnelse, eftersom denna bliver aktad av både Gud och människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Medan hon är här tillstädes, vill man efterlikna henne, och man saknar henne, när hon är borta; och i evigheten bär hon ärekransen i triumf såsom segervinnare i obesmittad tävlingskamp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Men de ogudaktigas talrika avkomma är till intet gagnelig; då de ju äro av oäkta skott, slå de ej djup rot och få icke något säkert fäste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Ty om sådana än till en tid skjuta frodiga grenar, skakas de dock av vädret, eftersom de stå så ostadigt, och ryckas upp med roten av vindarnas våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Deras grenskott brytas av runtom, medan de ännu äro späda, och deras frukt är oduglig, onjutbar kart, till intet nyttig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Ty barn som födas av syndig förbindelse äro vittnen mot sina föräldrar om deras ondska, när rannsakning en gång sker med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Men den rättfärdige skall, om han än går tidigt bort, få njuta ro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Ty en vördnadsvärd ålder är ej detsamma som en hög; den mätes icke efter årens tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Nej, vishet är för en människa de rätta grå håren, och ett liv utan fläck den rätta ålderdomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Eftersom han var Gud till behag, blev han älskad av honom, och eftersom han levde mitt ibland syndare, togs han bort:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'han rycktes undan, för att ondskan ej skulle förvilla hans förstånd eller falskheten dåra hans själ.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Ty det ondas tjusning gör dygden vanmäktig, och begärelsens yra förvänder ett oskyldigt sinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Han blev tidigt mogen och hade så fullbordat en lång levnad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'ty hans själ behagade Herren. Därför fick den ock skynda bort ur den onda världen. Och människorna se det, men de förstå dock icke och lägga icke sådant på hjärtat,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'att nåd och barmhärtighet vederfares hans fromma, och hans utvalda nådefull besökelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Men den rättfärdige skall, fästän död, döma de ogudaktiga som leva, och ungdom, som snart blev mogen, den orättfärdiges höga ålder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Ja, de se väl den vises slut, men förstå dock ej vad Herren har beslutit om honom, och varför han har satt honom i säkerhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'De se det och akta det för intet; men Herren ler åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Och därefter skola de bliva till föraktliga as och till bespottelse bland de döda evinnerligen. Ty han skall störta dem huvudstupa ned, förrän de hinna öppna munnen; han skall rycka dem loss ifrån deras grundvalar, och de skola helt förgöras. De skola dväljas i kval, och deras åminnelse skall förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Då skall den rättfärdige stå där med stor frimodighet inför dem som förtryckte honom, och som föraktade hans mödor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'När de få se detta, skola de gripas av stor förskräckelse och betagas av häpnad över hans oväntade frälsning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'De skola ångra sig och säga vid sig själva, de skola sucka i sin själs ångest: »Det var denne som vi en gång hade till åtlöje och till ett smädligt ordspråk, vi dårar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Hans leverne aktade vi såsom förryckthet och hans slut såsom någonting nesligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Huru har han nu kunnat bliva räknad bland Guds barn, och huru har han fått sin lott bland de heliga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Så hava vi då gått vilse från sanningens väg; rättfärdighetens ljus har icke lyst för oss, och dess sol har icke gått upp för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Vi mättade vårt begär på orättfärdighetens och fördärvets stigar, vi vandrade genom väglösa ödemarker, men Herrens väg lärde vi icke känna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Vad har nu vårt övermod gagnat oss? Och vad har rikedom, i förening med högfärd, gjort oss för nytta?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Försvunnet är allt detta såsom en skugga och såsom ett budskap som snabbt går vidare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Det är med oss såsom med skeppet som far över det svallande havet: icke ett spår kan man finna därav, där det gick fram, ej en väg efter dess köl bland vågorna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'eller såsom med fågeln som flyger genom rymden: den lämnar icke kvar något intryck däri av sin färd, den piskar med vingpennornas slag den lätta luften och klyver den under sin vinande fart, där den genomilar den på svängda vingar, intet märke skönjes sedan däri efter flykten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'eller såsom med pilen som skjutes mot målet: den delade luften flyter strax åter tillsammans, så att man icke kan märka vilken väg den gick —');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'på samma sätt blevo vi knappt födda, förrän vi togo en ände, och något tecken av dygd kunna vi icke visa på, nej, mitt i vår ondska hava vi blivit förtärda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Ty den ogudaktiges hopp är såsom agnar som vinden bortför, såsom lätt skum som en stormil jagar undan, såsom rök som försprides av vinden, såsom det förbleknade minnet av en gäst som stannade en enda dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Men de rättfärdiga leva evinnerligen, och i Herren hava de sin lön, och den Högste bär omsorg om dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Därför skola de få mottaga det härliga konungadömet och den sköna kronan ur Herrens hand. Ty med sin högra hand skall han skydda dem, och med sin arm skall han beskärma dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Han skall taga på sig sin nitälskan såsom en krigsrustning och bruka skapelsen såsom ett hämndvapen mot sina fiender.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Han skall ikläda sig rättfärdigheten såsom ett pansar och sätta på sig omutlig rätt såsom en hjälm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Han skall taga heligheten såsom en oövervinnlig sköld');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'och vässa sin stränga vrede till ett svärd. Och tillsammans med honom skall hela världen strida mot de vanvettiga:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'träffsäkra skola ljungeldarnas pilar fara åstad, ja, från molnen skola de flyga mot sitt mål såsom från en väl spänd båge,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'vredesfyllda skola hagelstenar kastas såsom från en stenslunga, och havets vatten skall rasa mot dem, och floderna skola med hast fördränka dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Maktens ande skall resa sig upp mot dem, och såsom en stormvind skall den rensa bort dem. Så skall orättfärdigheten lägga hela jorden öde och brottsligheten kullstörta härskares troner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Hören nu, I konungar, och kommen till förstånd, tagen emot lärdom, I som domen jordens ändar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'lyssnen, I som råden över många, och som yvens över folkens skaror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Ty av Herren är makten eder given och väldet av den Högste; han skall ock pröva edra gärningar och utrannsaka edra rådslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'I ären väl tjänare i hans rike, men haven icke styrt rättrådigt; I haven ej tagit lagen i akt och icke vandrat efter Guds vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Fruktansvärd skall han med hast komma över eder, ty högt uppsatta få sträng dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Den ringe kan ju få tillgift och nåd, men de mäktige skola med maktens stränghet prövas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Ty han som är herre över allting har ej anseende till personen och har icke någon försyn för storhet. Han har ju själv skapat både små och stora, och han bär lika omsorg om alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Men de väldige förestår en sträng rannsakning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Till eder, I härskare, ställas därför mina ord, för att I skolen lära eder vishet och undgå att falla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Ty de som hålla det heliga i helgd, de skola aktas heliga, och de som hava vunnit insikt däri skola finna försvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Så haven då begär efter mina ord; längten efter dem, så skolen I bliva undervisade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Strålande och ovansklig är visheten, och hon varsnas lätt av dem som älska henne; hon låter sig finnas av dem som söka henne,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'ja, hon skyndar att själv göra sig känd av dem som åtrå henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Den som bittida söker henne behöver icke möda sig, ty han skall finna henne sittande vid sin dörr.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Ja, att hava henne i tankarna är höjden av förstånd; och den som vakar för hennes skull, han bliver snart fri ifrån bekymmer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Hon går ju själv omkring och söker dem som äro henne värdiga och uppenbarar sig hult för dem på deras stigar och kommer dem till mötes i alla deras planer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Ty vishetens rätta begynnelse är begär efter undervisning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'men åstundan efter undervisning är kärlek till henne, och kärlek är att hålla hennes bud; men att akta på buden är att försäkra sig om oförgänglighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'oförgänglighet åter leder till att man får vara nära Gud:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'alltså för begär efter vishet upp till konungavälde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Därför, I folkens härskare, om I finnen behag i troner och spiror, ären då visheten, så skolen I få regera evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Men vad visheten är, och huru hon blev till, det skall jag förkunna; jag skall icke dölja hennes hemligheter för eder. Nej, ända ifrån det hon först blev till skall jag utrannsaka henne och lägga kunskapen om henne i dagen. Jag skall ingalunda gå på sidan om sanningen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'ej heller sida vid sida med den hålögda avunden, ty denna har ingen gemenskap med visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'När de vise äro många, går det världen väl, och en förståndig konung är folkets välfärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Låten därför undervisa eder genom mina ord, så skall det lända eder till gagn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Också jag är en dödlig människa, lik alla andra, och en avkomling av den stoftvarelse som först blev danad. Under tio månaders förlopp fick jag kroppslig gestalt, i en moders liv;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'den bildade sig i blod ur en mans säd och genom njutningsfylld omfamning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Och när jag föddes, begynte jag andas samma luft som alla andra, jag föll ned på den jord som bär oss alla, och mitt första ljud var en gråt, lik alla andras;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'i linda blev jag uppfödd under trägna omsorger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Ty ingen konung har på annat sätt begynt sin tillvaro;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'nej, enahanda är allas ingång i livet och lika deras utgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Därför bad jag, och förstånd blev mig givet; jag åkallade, och vishetens ande kom till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Jag höll visheten förmer än spira och tron; rikedom räknade jag för intet i jämförelse med henne,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'och oskattbar ädelsten aktade jag ej lika med henne. Allt guld är ju bredvid henne en handfull grus, och såsom ler är emot henne silver att akta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Högre än hälsa och fägring älskade jag henne, och jag ville hellre äga henne än solens ljus, ty det sken som hon sprider slocknar aldrig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Dock, med henne kom mig allt annat gott till del och omätlig rikedom genom hennes hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Jag fröjdade mig vid allt detta, då ju visheten regerar däröver, men jag visste icke ännu att hon också är dess alstrarinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Utan listig beräkning tog jag emot hennes lärdomar, utan missunnsamhet delar jag ock med mig av dem; jag gömmer icke undan hennes rikedomar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Ty hon är en outtömlig skatt för människorna, och om de bruka den, förvärva de sig Guds vänskap, välbehagliga inför honom för de gåvor som komma av undervisningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Men mig give Gud att kunna tala såsom jag ville, och att tänka på ett sätt som är hans gåvor värdigt. Han är ju den som både vägleder visheten själv och för de visa på rätta vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Ty av honom bero både vi själva och vårt tal, allt vad förstånd heter och all kunskap i livets värv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Ja, det är han som har givit mig osvikligt vetande om tingen, så att jag känner världens byggnad och elementens verkningskraft,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'tidernas begynnelse och slut och mitt, solståndens växlingar och tidsavdelningarnas skiften,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'årens kretslopp och stjärnornas ställningar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'varelsernas egenskaper och de vilda djurens skaplynnen, andarnas makt och människornas tankar, växternas olika arter och rötternas krafter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Vad som är fördolt och vad som är uppenbart, allt har jag lärt känna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Ty visheten, hon som är mästare i allt, har undervisat mig därom. Ty i henne finnes en ande som är förnuftig, helig, ensam i sitt slag, mångfaldig, fin, rörlig, genomträngande, obesmittlig, klar, okränkbar, vän till det goda, skarp, ohämbar, välgörande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'människoälskande, fast, orubblig, obekymrad, en som förmår allt och övervakar allt, och som går in i alla andra andar vilka äro förnuftiga, rena och av fullkomlig finhet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ja, visheten är det rörligaste av allt rörligt och tränger igenom och går in i allt, till följd av sin renhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Ty hon är en fläkt av Guds kraft och ett ogrumlat utflöde av den Allsmäktiges härlighet; därför kan intet besmittat komma vid henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Ja, hon är ett återsken av det eviga ljuset och en klar spegel, som återspeglar Guds verksamhet, och en avbild av hans godhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Fastän hon är en, förmår hon dock allt, och fastän hon själv förbliver den hon är, förnyar hon allt annat. Från släkte till släkte flyttar hon in i fromma själar och gör människor till Guds vänner och till profeter;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'ty Gud älskar allenast den som bor samman med visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ja, hon är skönare än solen och förmer än hela stjärnhimmelen. Jämföres hon med dagsljuset, är det hon som får företrädet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'ty detta avlöses av natten, men över visheten har ondskan ingen makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Hon sträcker sig i full kraft från världens ena ända till den andra, och hon styr allting väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Henne fick jag kär, och jag eftersträvade henne allt ifrån min ungdom; jag åstundade att hemföra henne såsom min brud, och jag blev betagen av hennes skönhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Sin höga börd gör hon kunniga genom sitt samliv med Gud; ja, han som är herre över allting älskar henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Ty hon är invigd i Guds kunskap och väljer åt honom ut vad han skall göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Om rikedom är något värdefullt att äga här i livet, vad är väl rikare än visheten, som frambringar allt!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Men om det kommer an på förstånd, vem är väl i hela världen en större mästare än hon!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Och om någon älskar rättfärdighet, så består hennes mödors frukt just i dygder. Ty hon lär ut besinning och förstånd, rättrådighet och mod, och intet är här i livet gagneligare för människor än dessa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Men om någon jämväl längtar efter mångkunnighet, så känner visheten det förgångna och förmår sluta sig till vad som skall komma; hon förstår sig på sinnrika ordvändningar och kan lösa gåtor, hon vet på förhand tecken och under och tiders och stunders slutliga utgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Så beslöt jag då att hemföra henne till att leva samman med mig, viss om att i henne få en rådgiverska i vad gott är och en tröst i sorger och bekymmer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'För hennes skull — så tänkte jag — skall jag vinna anseende bland mängden och heder hos de gamla, om jag än själv är ung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Jag skall befinnas skarpsinnig i i domslut, och hos de mäktige skall jag bliva beundrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'När jag tiger, skola de vänta på mig, och när jag höjer min röst, skola de giva akt, och när jag ordar något längre, skola de lägga handen på sin mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'För hennes skull skall jag vinna odödlighet och lämna kvar åt eftervärlden en evig åminnelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jag skall regera över folk, och folkslag skola bliva mig underlagda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Fruktansvärda härskare skola förskräckas, när de få höra om mig; bland folket skall jag visa mig god, och i krig tapper.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'När jag träder in i mitt hus, skall jag vila ut hos henne; ty samvaron med henne har ej någon bitterhet med sig eller samlivet med henne någon smärta, utan idel glädje och fröjd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'När jag nu tänkte detta vid mig själv, och när jag besinnade i mitt hjärta att i gemenskapen med visheten ligger odödlighet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'och i vänskapen med henne ädel njutning och i hennes händers mödor outtömlig rikedom och i träget umgänge med henne förstånd och gott rykte i att taga del av vad hon säger, då gick jag omkring och sökte efter huru jag skulle kunna vinna henne');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Och väl var jag en yngling med goda anlag och hade fått en god själ på min lott,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'eller fastmer: därför att jag var god, hade jag kommit i besittning av en obesmittad kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Men jag förstod att jag allenast så kunde förvärva henne, att jag fick henne såsom gåva av Gud — och redan det krävde förstånd, att veta vems nådegåva hon är — därför vände jag mig ock till Herren och bad till honom; jag talade så ur djupet av mitt hjärta:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Mina fäders Gud, du barmhärtighetens Herre, du som har gjort allt genom ditt ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'och som genom din vishet har danat människan till att råda över dina skapade verk');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'och till att styra världen med helighet och rättfärdighet och till att döma med rättvisa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'giv mig visheten, som tronar vid din sida, och uteslut mig icke ur dina barns tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Jag är ju din tjänare och din tjänarinnas son, en svag människa, som lever allenast en kort tid, och som föga förstår lag och rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ty om än någon gäller såsom fullkomlig inför människors barn, så är han dock att räkna för intet, om han saknar den vishet som kommer från dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Du har själv utvalt mig till konung över ditt folk och till domare över dina söner och döttrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Du har befallt mig att bygga ett tempel på ditt heliga berg och ett altare i den stad där du har din boning, såsom en avbild av det heliga tabernakel som du har berett redan från begynnelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Men hos dig är visheten, som känner dina verk, och som var med, när du skapade världen, hon som vet vad som är dig välbehagligt, och vad som är rätt efter dina bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Sänd ut henne från din heliga himmel, och skicka henne från din härlighets tron, för att hon må bistå mig i arbetet, och för att jag må lära känna vad som är dig till behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Ty hon vet och förstår allt, och hon skall visligt vägleda mig i mina gärningar och beskydda mig med sin härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Så skola mina verk täckas dig, och jag skall kunna styra ditt folk med rättfärdighet och bliva min faders tron värdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ty vilken människa kan känna Guds råd? Eller vem kan utgrunda vad Herren vill?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'De dödligas tankar äro ju vanmäktiga, och våra beräkningar äro osäkra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Ty den förgängliga kroppen tynger ned själen, och stofthyddan är en börda för den mångtänkande anden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Allenast med svårighet sluta vi oss till det som är på jorden, och det som är nära till hands finna vi med möda. Vem kan då utrannsaka det som är i himmelen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Och vem har lärt känna ditt råd, om ej du först gav vishet och sände din helige Ande från höjden?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'På sådant sätt hava jordens bebyggare förts på rätta stigar och människorna lärt det som är välbehagligt för dig; ja, genom visheten hava de blivit frälsta. 1 Kor 2,16.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Det var hon som beskyddade honom som först blev danad, världens fader, vilken skapades allena, och som ryckte honom ur hans fall');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'och gav honom kraft till att råda över allting.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Men när därefter en orättfärdig man i sin vrede avföll från henne, gick han själv under på grund av den hätskhet varmed han dräpte sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'När sedan för hans skull jorden översvämmades, då var det åter visheten som frälste den, i det hon med hjälp av några skröpliga plankor lotsade den rättfärdige genom vattnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Det var ock hon, som när folken hade blivit förbistrade till följd av sin endräkt i ondska, lät sig vårda om den rättfärdige och behöll honom ostrafflig inför Gud och bevarade honom ståndaktig mot fadershjärtats känslor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Det var hon, som när de ogudaktiga förgingos, räddade en rättfärdig man, då denne sökte fly undan elden som föll ned över de fem städerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Om dessas ondska vittna ännu alltjämt en rykande ödemark och växter som bära frukt i otid och saltstoden som reser sig till åminnelse av ett tvivlande sinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Ty när dessa vände sig ifrån visheten, gingo de icke allenast förlustiga kännedomen om det rätta, utan måste ock åt världen efterlämna ett minnesmärke av sin dårskap, för att deras förvillelser icke ens skulle kunna råka i glömska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Visheten räddade ock ur farorna dem som tjänade henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Det var hon som ledde den rättfärdige på jämna stigar, när han måste fly för sin broders vrede. Hon visade honom Guds rike och gav honom kunskap om heliga ting; hon skänkte honom välstånd under hans mödor och gav honom riklig lön för hans arbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Mot deras vinningslystnad, som förtryckte honom, stod hon honom bi, och hon gjorde honom rik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Hon beskyddade honom mot fiender och tryggade honom mot sådana som lade försåt för honom. En svår kamp avgjorde hon till hans förmån, på det att han skulle förstå att gudsfruktan förmår mer än något annat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Det var hon som icke övergav den rättfärdige som hade blivit såld, utan räddade honom från synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Hon steg ned med honom i fängelsehålan och övergav honom icke i hans bojor, till dess hon hade förlänat honom en härskarspira och makt över dem som voro hans herrar. Hon visade ock att hans belackare voro lögnare och skänkte honom evärdlig ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Det var hon som räddade det heliga folket och det ostraffliga släktet från ett folk av förtryckare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Hon gick in i Herrens tjänares själ och trädde upp mot fruktansvärda konungar med under och tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Hon lät de heliga undfå lön för deras mödor; hon vägledde dem på en underbar färd och tjänade dem till skygd om dagen och till stjärnljus om natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Hon ledde dem genom Röda havet och förde dem fram genom stora vatten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'men deras fiender fördränkte hon och lät dem sedan kastas upp ur det bottenlösa djupet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Fördenskull fingo de rättfärdiga taga vapnen från de ogudaktiga. De lovsjöngo ditt heliga namn, o Herre, och prisade endräktigt din värnande hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Ty visheten öppnade de stummas mun och lärde dem som voro lika barn att tala med redig tunga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Hon gjorde deras företag lyckosamma genom den helige profeten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'De tågade fram genom en obebodd öken, och i väglösa trakter slogo de upp sina tält. Därför straffar du först efter hand dem som falla och varnar dem, därmed att du påminner dem om det vari de synda, på det att de skola skilja sig ifrån sin ondska och tro på dig, o Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'De gjorde motstånd mot fiender och försvarade sig mot ovänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'När de ledo törst, åkallade de dig; då gavs dem vatten ur kala klippan och läkedom mot törsten ur hårda stenen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Ty det som för deras fiender blev ett medel till straff, det blev för dem själva ett medel till hjälp i nöden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'I stället för att floden, som kommer ur en aldrig sinande källa, för de andra blev grumlad genom vedervärdigt blod,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'till straff för påbudet att de späda barnen kulle dödas, gav du oförväntat åt dessa friskt vatten i ymnighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'sedan du genom den törst som de då kände hade visat dem på vad sätt du hade straffat deras motståndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Ty då de sattes på prov, fastän genom tuktan i all mildhet, kunde de förstå huru de ogudaktiga plågades, när dessa blevo dömda i vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Dem själva varnade och prövade du nämligen såsom en fader, men de andra dömde och straffade du såsom en sträng konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Och lika väl frånvarande som närvarande kvaldes de,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'ja, en dubbel plåga träffade dem, och vånda vid åtanken av det förflutna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Ty när de hörde att det som hade länt dem själva till straff lände de andra till hjälp, då förnummo de att det var Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Ty honom som de en gång hade förkastat och satt ut, och som de sedan med hån hade avvisat, honom måste de vid den slutliga utgången förundra sig över, i det att de hade fått törsta på helt annat sätt än de rättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Och till straff för deras orättfärdighets oförståndiga tankar, genom vilka de hade blivit vilseförda, så att de dyrkade oskäliga kräldjur och föraktliga småkryp, sände du ut mot dem en mängd oskäliga varelser till näpst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Så skulle de lära sig förstå, att vad någon brukar såsom medel till synd, det bliver också medel till hans straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Lätt hade din allsmäktiga hand, som förmådde skapa världen av formlöst ämne, kunnat sända emot dem björnar i mängd eller vilda lejon');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'eller nyskapade ilskna odjur, aldrig förut sedda, som antingen hade frustat ut en eldsprutande andedräkt eller spritt väsande rök omkring sig eller ur gnistrande ögon sänt fruktansvärda ljungeldar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'odjur som hade mäktat icke allenast att genom sitt anfall alldeles förinta dem, utan ock att tillintetgöra dem redan genom sin skräckinjagande anblick.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Och jämväl sådana förutan skulle de hava kunnat falla för en enda fläkt, förföljda av den hämnande rättfärdigheten och förströdda av din makts ande. Dock, du har ordnat allt efter mått och tal och vikt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Ja, övermäktig styrka står dig städse till buds; och vem kan stå emot kraften av din arm?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Såsom ett grand på vågskålen är ju hela världen inför dig, och såsom en droppe dagg, som om morgonen faller på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Men du är barmhärtig mot alla, därför att du förmår allt; och du har fördrag med människornas synder, för att de skola bättra sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Ty du älskar allt som är till, och du håller intet för styggelse av vad du har skapat. Du skulle heller icke hava danat något som du hatade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Och huru skulle något hava kunnat bestå, om icke du hade velat det? Eller huru skulle något hava kunnat bliva bevarat, som du icke hade kallat till liv?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Men du är skonsam mot allt, därför att det är ditt, o Herre, du det levandes vän. 12,1 Ty din oförgänglige ande bor i allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Så hatade du ju visserligen de forna inbyggarna i ditt heliga land,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'därför att de övade avskyvärda trolldomsverk och skändliga gudstjänstbruk');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'och utan förbarmande dräpte sina barn och höllo offergillen där de förtärde människokött och blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Ja, du ville genom våra fäders hand förgöra de invigda mitt under deras offermåltider, dessa föräldrar som med egen hand dräpte sina värnlösa små.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Ty du ville ju att det land som hos dig stod högst i ära av alla skulle få mottaga en befolkning av Guds barn, som var det värdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Men dock visade du dig skonsam jämväl mot dessa, eftersom de voro människor; du sände ut getingar såsom förelöpare till din här, för att dessa först så småningom skulle utrota dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Icke som om du hade varit ur stånd att i öppen strid giva de ogudaktiga i de rättfärdigas hand, eller att genom fruktansvärda vilddjur eller ett enda befallande ord med ens tillintetgöra dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'men genom att så småningom gå till doms med dem ville du giva dem rådrum till bättring, fastän du väl visste att deras ursprung var ont, och att deras ondska var inrotad hos dem, och att deras tänkesätt aldrig någonsin skulle förändras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Ty de voro ett förbannat släkte från begynnelsen. Det var ej heller av rädsla för någon som du gav dem en tids strafflöshet för deras synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Ty vem vågar säga: »Vad gör du?» Eller vem skulle kunna sätta sig emot din dom? Och vem skulle drista att anklaga dig för att du har förgjort folk som du själv har skapat? Eller vem skulle våga att träda upp emot dig såsom sakförare för orättfärdiga människor?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Utom dig finnes det ju icke någon Gud som bär omsorg om alla, så att du skulle behöva bevisa för honom att du icke har dömt orättfärdigt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'ej heller förmår någon konung eller härskare träda dig under ögonen, till försvar för dem som du har straffat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Nej, eftersom du är rättfärdig, styr du ock allting rättfärdigt; och du anser det oförenligt med din makt att döma också den skyldig, som icke har gjort sig förtjänt av straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Just din starkhet är ju grunden till din rättfärdighet; och att du råder över alla, det gör dig skonsam mot alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Ty din starkhet visar du, när någon betvivlar din makts fullkomlighet; och om någon känner den, då bestraffar du hans förmätenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Men du är herre över din styrka och dömer med mildhet och regerar över oss med mycken skonsamhet. Ty makten står dig till buds, närhelst du vill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Genom att så handla har du velat lära ditt folk att den rättfärdige bör hava människokärlek; och du har givit dina barn gott hopp om att du vill förläna dem tillfälle till bättring, när de synda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Ty om du med så stor varsamhet och fördragsamhet straffade dina barns fiender, som dock förtjänade döden, i det att du lämnade dem tid och rådrum till att skilja sig ifrån sin ondska,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'med vilken aktsamhet har du då icke dömt dina barn, vilkas fäder du genom edliga försäkringar och förbund hade givit så härliga löften!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Oss fostrar du alltså genom tuktan, medan du tiotusenfalt slår våra fiender, på det att vi, när vi själva döma, må betänka din godhet, och när vi bliva dömda, må kunna vänta förbarmande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Därför plågade du ock genom deras egna styggelser de orättfärdiga, som framlevde sitt liv i dårskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'De hade ju ock förirrat sig långt bort på villfarelsens vägar, i det att de höllo för gudar de till och med bland djuren själva mest föraktade odjur och läto bedraga sig i likhet med oförnuftiga småbarn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Fördenskull sände du domen över dem likasom på lek, som om de hade varit oförståndiga barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Men de som icke låta varna sig, när de så bliva näpsta likasom på lek, de få erfara en dom som är Gud värdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Ty när dessa blevo straffade genom dem som de vid sina plågor harmades på, dessa samma som de höllo för gudar, då fingo de, just genom dem, lära känna den sanne Guden, när de nu med egna ögon sågo honom som de förut hade förnekat sig veta något om. Därför kom ock den strängaste dom över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Ja, dåraktiga till sin natur voro alla de människor som saknade kunskap om Gud, och som icke av de härliga ting som synas förmådde känna honom »som är», och icke, när de gåvo akt på hans verk, kände igen mästaren,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'utan höllo för gudar antingen elden eller vinden eller den snabba luften eller stjärnringen eller de mäktiga vattnen eller himlaljusen, som styra världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Om de nu än tjusades så av dessa tings skönhet, att de antogo dem vara gudar, så hade de dock bort förstå huru mycket förmer han är, som är herre över dem; han som är all skönhets upphov har ju skapat dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Om det åter var därför att de hade intagits av häpnad över deras makt och verkningskraft, så hade de genom dessa bort inse huru mycket mäktigare han är, som har danat dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Ty av de skapade tingens storhet och skönhet kan man sluta sig till och föreställa sig hurudan deras upphovsman är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Och dock äro dessa icke så mycket att tadla, ty det är kanske så med dem, att de, fastän de fara vilse, ändå söka Gud och gärna vilja finna honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Medan de nämligen sysselsätta sig med hans verk, forska de noga i dem och bliva betagna vid deras anblick, eftersom det de se är så skönt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Men å andra sidan äro icke ens dessa helt ursäktade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Ty om de förmådde fatta så mycket att de kunde utgrunda världen, huru kom det sig då att de icke mycket förr funno honom som är herre över dessa ting?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Ömkansvärda äro de, och till döda ting sätta de sitt hopp, alla de som kalla verk av människohänder för gudar, något av guld och silver, alster av konst, avbildningar av djur eller ett uselt stenbeläte, ett verk av forntida hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Huru gör till exempel timmermannen? Jo, han avsågar ett lätthanterligt trästycke och skalar med van hand av all barken därpå; han bearbetar det sedan med skicklighet och förfärdigar så något nyttigt redskap för det dagliga livets behov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Och avfallet vid arbetet använder han till att koka sin mat över; och därefter äter han sig mätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Men det avfall som till sist bliver kvar, och som icke duger till något nyttigt, ett vint och kvistigt trästycke, det tager han sedan och täljer på, till sysselsättning på lediga stunder, och formar det med vårdslös händighet. Så tillskapar han därav en människobild');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'eller giver det likhet med något oansenligt djur, i det han bestryker bilden med mönja och färgar dess yta röd med smink och stryker över alla dess fläckar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Sedan förfärdigar han åt den en boning som är den värdig och sätter fast den vid väggen med spikar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Han söker nämligen så hindra att den skall falla omkull, eftersom han väl vet att den är ur stånd att hjälpa sig själv. Den är ju ock allenast en bild och har behov av hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Men när han därefter vill bedja för sina ägodelar och sitt äktenskap och sina barn, då blyges han icke för att tala till detta livlösa ting. Om hälsa åkallar han det kraftlösa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'om liv anropar han det döda, om bistånd bönfaller han hos det som alls intet förmår, om lyckosam färd hos det som icke ens kan röra en fot;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'och i fråga om förvärv och yrke och framgång i sina händers verk utbeder han sig kraft av det som icke har den minsta kraft i sina händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'När åter någon bereder sig till en sjöresa och ärnar färdas genom de vilda vågorna, då anropar han ett trästycke som är bräckligare än skeppet som bär honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Ty skeppet har förvärvsbegäret tänkt ut, och den konstskickliga visheten har timrat det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Men det är din försyn, o Fader, som styr dess färd. Du beredde ju en väg jämväl i havet och en säker stig bland vågorna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'för att visa att du förmår frälsa ur all fara, så att man kan våga gå ombord, om man ock är utan insikt i konsten att segla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Och du vill att din vishets verk icke skola bliva utan verkan. Därför anförtro ock människorna sina liv åt några obetydliga plankor och komma i en bräcklig farkost välbehållna fram genom havets svall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Så var det ock i forntiden, då de övermodiga jättarna förgingos: han som var världens hopp undkom i en bräcklig farkost och lämnade så kvar åt världen fröet till en ny släkt, i det att din hand styrde hans färd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Ja, välsignat är det trä genom vilket sådant sker, som är rättfärdigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Men träbelätet är förbannat, både det och han som har gjort det: denne, därför att han har förfärdigat det, och det förra, därför att det, fastän ett förgängligt ting, har fått namn av gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Ty den ogudaktige och hans ogudaktiga verk äro båda lika förhatliga för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Också skall verket bliva straffat tillsammans med den som har förfärdigat det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Fördenskull skall en hemsökelse komma jämväl över hedningarnas avgudabilder, därför att de, fastän de tillhöra Guds skapelse, hava blivit till en styggelse och till en snara för människornas själar och till ett giller för de oförståndigas fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Ty tanken på att göra bilder är begynnelsen till trolöst avfall, och att uppfinna sådana är ett fördärv för levernet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'De funnos nämligen icke av begynnelsen, och de skola ej heller för beständigt finnas till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Det är ju genom människors tomma inbillning som de hava kommit in i världen; därför är ock ett brått slut bestämt för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Ty kvald av en alltför tidig sorg, lät en fader göra en bild av sin så hastigt bortryckte son, och begynte sedan att nu såsom gud ära den som nyss var allenast en död människa, och instiftade för dem som lydde under honom hemliga ceremonier och gudstjänstbruk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Därefter befäste sig med tiden en sådan gudlös sed och blev iakttagen såsom en lag. Jämväl i följd av härskares påbud dyrkades bildstoder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Då människorna nämligen icke kunde hylla dem ansikte mot ansikte, därför att de bodde långt i fjärran, läto de avbilda dens ansikte, som var så långt borta, och göra en synlig bild av konungen som de ville hylla, för att genom sitt nit smickra den frånvarande, som om han hade varit närvarande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Och till en ännu ivrigare dyrkan drevos de genom konstnärens ärelystnad, och det till och med sådana som icke kände den som bilden föreställde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Ty då konstnären till äventyrs ville vara härskaren till behag, ansträngde han sig att genom sin konst åstadkomma en förskönad likhet; och så begynte mängden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'som fängslades genom konstverkets skönhet, att nu se ett föremål för tillbedjan i honom som man kort förut hade ärat såsom människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Och detta blev en snara för levernet, ty under olyckans eller härskarviljans tvingande makt kommo människor så att tillägga stock och sten det namn som tillhör en enda och ingen annan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Men det var icke nog med att de foro vilse i fråga om Guds kunskap, utan än mer: fastän okunnigheten gör deras liv till en oavlåtlig strid, säga de mitt under i sitt elände att allt står väl till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Ty under det att de fira offerfester vid vilka de dräpa barn eller utföra hemliga ceremonier, utan vittnen, eller vilda upptåg med sällsamma bruk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'akta de icke längre andras liv eller äktenskap heliga, utan den ene undanröjer den andre genom försåt eller tillskyndar honom lidande genom att förföra hans maka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Överallt råder om vartannat blodsutgjutelse och dråp, stöld och svek, sedefördärv, trolöshet, osäkerhet, falsk edgång, förföljelse av rättrådiga människor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'glömska av välgärningar, själars besmittelse, onaturligt umgänge, äktenskaplig oordning, otukt och utsvävningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Ja, dyrkan av dessa avgudabilder, som icke äro värda att nämnas vid namn, är begynnelsen och orsaken till allt ont, så ock fulländningen därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ty antingen giva de sig hän åt vilt festrus, eller spå de lögn, eller leva de orättrådigt, eller svärja de lättsinnigt falska eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Eftersom de förlita sig på livlösa bilder, vänta de sig ju icke att få lida något ont, när de hava svurit falskt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Dock skall rättvisan förfölja dem för bådadera: både för att de hava tänkt vrångt om Gud genom att hålla sig till avgudabilder, och för att de svikligt hava begått mened under förakt för det heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Ty det är icke makten hos dem vid vilka man svär, utan det är det rättvisa straffet över dem som synda, som alltid drabbar de orättfärdigas överträdelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Men du, vår Gud, är god och sannfärdig; du är långmodig och styr allt med barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Ja, om vi än synda, tillhöra vi likväl dig, eftersom vi känna din makt. Dock, vi vilja icke synda, eftersom vi veta att vi äro räknade såsom dina.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Att äga kunskap om dig är ju full och hel rättfärdighet, och att känna din makt är roten till odödlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Ty vi hava icke låtit oss föras vilse genom det som människor illfundigt hava tänkt ut, ej heller genom den onyttiga frukten av målares möda: en gestalt bestruken med olika färger,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'vilkas anblick väcker åtrå hos den dåraktige, så att han får lust till den livlösa gestalten av en död bild.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'De älska vad ont är och äro värda att hava sådana föremål för sitt hopp, både de som förfärdiga dem och de som hava sin lust i dem och de som dyrka dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Krukmakaren till exempel knådar mödosamt den mjuka jorden och formar var särskild sak till vår tjänst. Men det är av samma ler som han utformar både de kärl som tjäna rena syften och dem som tjäna till motsatsen, alla på samma vis; och vilkendera användningen vart och ett skall få, det bestämmer han som arbetar med leret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Och så formar han med illa använd möda av samma ler en vanmäktig gud, han som själv icke långt förut föddes av jord och inom kort, när den själ som han har fått till låns utkräves av honom, vänder åter till jorden, varav han är tagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Men därom bekymrar han sig icke, att han snart skall skiljas hädan, eller att hans liv är så kortvarigt; utan han tager upp tävlan med guldsmeder och silverarbetare och söker efterhärma koppargjutare och sätter en ära i att forma oäkta bilder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Aska är hans hjärta, och hans hopp mindre värt än mull, och hans liv värdelösare än lera.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Ty han känner icke den som har danat honom själv och ingjutit i honom en verksam själ och inblåst i honom en levande ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'utan han räknar vår levnad för en lek och vårt liv för en inbringande marknad; »ty» — så säger han — »man bör skaffa sig vinst av vad det vara må, jämväl av det som är dåligt».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Han vet ju själv bättre än någon annan att han begår synd, när han av samma lerämne tillverkar sköra kärl och gudabilder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Men övermåttan dåraktiga och ömkligare i förstånd än späda barn äro de alla, ditt folks fiender, de som hava förtryckt det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ty de gå så långt att de räkna alla avgudabilder hos hednafolken för gudar, dessa som varken hava ögon som de kunna se med, eller näsa för att andas genom, eller öron till att höra med, eller fingrar på händerna till att känna sig för med, och vilkas fötter icke duga till att gå på.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ty det är en människa som har gjort dem, och en som har fått sin ande till låns, som har format dem. Och ingen människa förmår ens att forma en gud som vore lik henne själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Nej, såsom hon själv är dödlig, så tillverkar hon med syndiga händer allenast ett dött ting. Hon är ju ock själv förmer än föremålen för sin dyrkan, eftersom hon själv är levande, medan dessa aldrig hava varit det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Därtill dyrka de ock de värsta odjur; ty om dessa djur jämföras med andra, äro de värre än dessa i fråga om oförnuftighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Och icke äro de heller, bredvid andra djur, så sköna att man kan få lust till dem. Nej, de hava gått miste både om berömmelse och om välsignelse från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Fördenskull blevo ock dessa i människor straffade efter förtjänst genom det som var likartat, i det att de plågades genom en mängd smådjur. Medan dessa så blevo straffade, gjorde du i stället väl mot ditt folk och beredde åt dem, för att stilla deras lystna begär, en ovanlig kost, vaktlar såsom föda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Du ville nämligen att de andra, när de kände begär efter föda, skulle genom vämjeligheten hos de djur som sändes ut mot dem förlora jämväl den naturliga matlusten, men att de själva, efter allenast en kort tids brist, skulle undfå till och med en ovanlig kost.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ty de förra, förtryckarna, skulle drabbas av en brist som icke stod att avvända, men de andra skulle allenast få se huru svårt deras fiender blevo plågade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Så var det ock, när skadedjurens raseri drabbade dem och de höllo på att förgås genom ringlande ormars bett. Då varade icke din vrede ända till det yttersta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'utan till varning höllos de allenast en kort tid i skräck och hade därvid ett räddningstecken. De skulle nämligen så påminnas om buden i din lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Ty var och en som vände sig till detta blev räddad, icke genom vad han såg, utan genom dig, du som är allas räddare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Och jämväl härigenom bevisade du för våra fiender att du är den');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'som frälsar ifrån allt ont. Ty dessa omkommo genom bett av gräshoppor och flugor, och någon läkedom för deras liv stod icke att finna, eftersom de voro värda att straffas av sådana djur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Men dina barn kunde icke ens giftsprutande drakars tänder skada, ty din barmhärtighet trädde emellan och helade dem. Ty för att de skulle på-n minnas om dina budord, blevo de stungna och åter hastigt räddade ur faran; du ville nämligen att de icke skulle förfalla till djup glömska av dina välgärningar, utan med sina tankar vara stadigt fästa vid dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'begynta jämförelsen mellan egyptiernas och israeliternas olika lotter: Skadedjuren och vaktlarna, haglet och mannat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Det var ju ock varken någon ört eller något plåster som botade dem, utan ditt ord, o Herre, vilket helar allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Ty du är den som har makt över liv och död; du för ned till dödsrikets portar och för åter upp därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'En människa däremot kan väl i sin ondska döda en annan, men när anden har flytt, förmår hon icke att hämta den tillbaka, och hon kan icke befria en själ som döden har fått i sitt våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Nej, att undkomma din hand är omöjligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Ty de ogudaktiga, som förnekade att de kände dig, de blevo gisslade genom kraften av din arm, i det att de förföljdes genom osedvanliga skyfall och hagelskurar och genom slagregn som icke stodo att avvända, och förtärdes genom eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Ja, vad som var underbarast av allt: elden hade större verkan i vattnet, som annars plägar utsläcka allt; ty hela skapelsen strider för de rättfärdigas sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Stundom mildrades nämligen lågan, för att den icke skulle bränna upp de djur som hade blivit utsända mot de ogudaktiga, utan dessa skulle själva tydligt skönja att det var genom Guds dom som de förföljdes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Stundom åter brann lågan jämväl mitt i vattnet med större styrka än eldens vanliga, för att den skulle förstöra det orättfärdiga landets alster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'I stället gav du ditt folk änglaspis att äta och sände dem, utan att förtröttas, färdigt bröd från himmelen, ett bröd som förmådde skänka allt slags njutning och svarade emot vars och ens smak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Ty din gåvas art uppenbarade sötman av din godhet mot dina barn. I det att brödet fogade sig efter begäret hos den som njöt det, förvandlade det sig till vad var och en ville.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Men snö och is uthärdade elden och smälte icke. På det sättet skulle de förnimma att elden visserligen förstörde fiendernas gröda, när den brann ibland haglet och ljungade mitt ibland regnskurarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'men att den å andra sidan hade förgätit jämväl sin naturliga kraft, för att de rättfärdiga skulle få näring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Ty i det att naturen tjänar dig, som har skapat den, stegrar den sin styrka mot de orättfärdiga, för att straffa dem, men dämpar den mot dem som förtrösta på dig, för att göra dem gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Fördenskull förvandlade den sig ock på den tiden till vad som helst, såsom din gåva, som tjänade dem alla till föda, krävde, alltefter de behövandes önskan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Så skulle dina barn, vilka du älskade, o Herre, få lära sig att det icke är de olika alstren av jordens frukt, som nära människorna, utan att det är ditt ord som uppehåller dem som tro på dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Ty detta, som icke fördärvades av eld, det smälte utan vidare, när det uppvärmdes av en flyktig solstråle.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Så skulle de lära sig att man bör stå upp före solen för att tacka dig, och att man i gryningen bör vända sig till dig i bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ty den otacksammes hopp skall smälta såsom vinterns rimfrost och rinna bort såsom odugligt vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Stora och svårbegripliga äro ju dina domar; därför fara ock de vilse, som icke hava velat låta undervisa sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Så var det med dessa orättfärdiga: de menade sig väl vara herrar över det heliga folket, men i stället fingo de själva ligga där fångna i mörker och fjättrade genom en lång natt, instängda inomhus, förvisade ifrån den eviga försynen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Ty under det att de med sina lönnliga synder trodde sig vara dolda under glömskans dunkla täckelse, blevo de försänkta i mörker; de voro slagna av svår skräck, och de skrämdes genom spöksyner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Icke ens den vrå som gömde dem kunde skydda dem för fruktan, utan dån såsom av vattenfall kringbrusade dem, och dystra skepnader med bistra drag uppenbarade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Och ingen eld var stark nog till att kunna sprida ljus; ej heller de klart strålande st järnlågorna hade kraft att lysa upp denna hemska natt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Det enda sken som visade sig för dem var en självlysande eld, full av fasa. Och storligen förfärade över denna syn, som de icke tydligt uppfattade, höllo de det som de sågo för värre än själva mörkret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Och trolldomskonstens gyckelverk lågo slagna till marken, och vishetsskrytet fick en snöplig vederläggning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Ty de som gåvo sig ut för att kunna fördriva all skräck och bävan från sjuka sinnen, de voro själva angripna av en rädsla värd att le åt:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'också utan att något verkligt farligt fanns där, som kunde väcka deras fruktan, jagades de upp, när smådjur kröpo förbi och ormar väste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'De höllo på att förgås av skräck, ja, de vågade icke ens att se upp i luften, som man dock ingenstädes kan undkomma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Ty ondskan är i sig själv feg; den vittnar därom, i det att den dömer sig själv, och anfäktad av samvetet gör den alltid det svåra värre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Fruktan är nämligen intet annat än att man uppgiver de hjälpmedel som eftertanken erbjuder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'och när tilliten till dem inne i hjärtat är försvagad, räknar man rådvillheten för värre än den sak som vållar plågan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Så var det ock med dessa, när de under denna natt, som i verkligheten var vanmäktig, och som hade kommit över dem från det vanmäktiga dödsrikets gömslen, voro försänkta i samma sömn:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'än jagades de genom vidunderliga spöksyner, än höllos de förlamade av den yttersta förtvivlan. Ty en plötslig och Oförtänkt förskräckelse hade fallit över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Så sjönk nu var och en, vem han än månde vara, ned på stället och hölls under bevakning, innesluten i ett fängelse utan lås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Ty vare sig det var en åkerman eller en herde, eller en dagakarl som hade sitt arbete långt borta på marken, så blev han överraskad och måste underkasta sig det oundvikliga nödtvånget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Ja, med en och samma kedja av mörker blevo de alla bundna. En susande vindfläkt eller välljudande fågelsång bland lummiga grenar eller bruset av våldsamt forsande vatten');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'eller det vilda dånet av nedstörtande klippblock eller hoppande djurs osynliga lopp eller rytande vilda rovdjurs läten eller genljudet som återkastades från bergsklyftorna - allt gjorde dem förlamade av skräck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Hela den övriga världen låg belyst av klart solsken och ägnade sig ostörd åt sina sysslor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Allenast över dessa låg en tung natt utbredd, en avbild av det mörker som en gång skulle taga emot dem. Dock voro de sig själva en tyngre börda än mörkret var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Men dina heliga hade det fullaste solljus. Då nu de andra väl hörde deras röster, men icke sågo deras gestalter, prisade de dem lyckliga, därför att icke också dessa hade måst lida sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'De tackade dem, därför att de nu icke gjorde dem någon skada, fastän de förut hade blivit förorättade, och bådo om tillgift för sin fientlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'I stället gav du dessa en lågande eldstod såsom vägvisare på den okända färden och såsom en mild sol under den ärorika vandringen genom främmande land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Ty de andra voro värda att bliva berövade ljuset och hållas fängslade genom mörker, eftersom de hade hållit dina barn i fängsligt förvar, dessa genom vilka lagens oförgängliga ljus skulle skänkas åt världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Och när de hade lagt råd om att dräpa de heligas späda barn och ett barn hade blivit utsatt - fastän det dock blev räddat - då berövade du dem till straff deras egna barn i stort antal och lät dem själva allasammans omkomma i ett väldigt vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Den natten hade på förhand blivit kungjord för våra fäder, för att de skulle säkert veta huru vissa de edliga löften voro, som de förtröstade på, och så vara vid gott mod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Så väntade då ditt folk de rättfärdigas räddning och fiendernas undergång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Ty genom det som du straffade våra motståndare med, genom detsamma kallade du oss till dig och förhärligade oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'I det fördolda framburo de rättsinnigas heliga söner sitt offer, och de förbundo sig endräk-tigt till att följa den gudomliga lagen att de skulle lika deltaga i samma både förmåner och faror; och därvid uppstämde de, redan då, fädernas heliga sånger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Men därunder ljöd skärande fiendernas skri, och ömkansvärt spridde sig ljudet av deras veklagan över sina barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Och av lika straff drabbades tjänare och husbonde, och undersåten fick lida detsamma som konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Och alla tillhopa hade de genom enahanda dödssätt oräkneliga döda, så att de levande icke ens räckte till att begrava dem, eftersom deras ädlaste avkomma med ett enda slag hade blivit förgjord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Fastän de, för sina hemliga konsters skull, trots allt icke hade velat tro, måste de nu, vid sina förstföddas undergång, vidgå att detta folk var Guds son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Ty medan djup tystnad omslöt allt och natten under sitt snabba lopp hade nått mitten av sin bana,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'for ditt allsmäktiga ord med hast ned från din konungatron i himmelen och begav sig mitt in i det tillspillogivna landet, en bister krigare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'väpnad med din oryggliga befällning såsom med ett skarpt svärd. Och han stannade där och uppfyllde allt med död; och han nådde upp till himmelen, medan han stod på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Då skrämdes de plötsligt upp av hemska drömsyner, och oförmodade fasor kommo över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Och de störtade halvdöda omkull, den ene här, den andre där, och yppade därvid vad orsaken var till att de nu måste dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Ty drömmarna, som hade oroat dem, hade på förhand röjt detta, för att de icke skulle omkomma utan att veta anledningen till sitt lidande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Väl undgingo ej heller de rättfärdiga att få pröva på döden, och hemsökelse drabbade en stor hop i öknen; dock varade vreden icke länge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Ty med hast trädde en ostrafflig man upp såsom deras förkämpe; han rustade sig med sitt ämbetes vapen, bön och försoning genom rökelse, och ställde sig till motvärn mot förtörnelsen och satte en gräns för olyckan och visade därmed att han var din tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Och han övervann vreden, men icke genom kroppsstyrka, ej heller genom vapenmakt; nej, genom sitt ord kuvade han honom som plågade dem, i det han påminde om de edliga löftena till fäderna och förbunden med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Ja, medan de döda redan lågo hoptals fallna över varandra, ställde han sig emellan och slog tillbaka vreden och spärrade för den vägen till de levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Ty på hans kåpa fanns hela världen framställd, så ock fädernas ärorika namn på de fyra raderna av graverade stenar, och ditt majestät på hans huvudbindel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'För allt detta måste Fördärvaren vika, och för detta greps han av fruktan. Ty det var nog med att de allenast något litet fingo pröva på vreden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Men över de ogudaktiga kom skoningslös förtörnelse till deras undergång. Gud visste ju på förhand jämväl vad de skulle komma att göra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'nämligen att de väl först skulle nödga dem att begiva sig bort, och att de med hast skulle sända dem i väg, men att de efteråt skulle ångra sig och förfölja dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Ty medan de ännu voro upptagna av sin sorg och jämrade Sigvid de dödas gravar, kommo de på en ny, en dåraktig plan: de som de under böner hade drivit bort, dem förföljde de nu såsom rymmare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Ja, ända därhän drev dem deras välförtjänta ödes nödtvång, och det kom dem att glömma vad som förut hade övergått dem. De skulle ju så fylla ut det mått av straff, som ännu fattades i deras plågor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'och medan ditt folk skulle få fullborda en underbar vandring, skulle de andra finna en osedvanlig död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Ty hela naturen omgestaltades på nytt till sin beskaffenhet, i det den fogade sig efter dina befallningar, på det att dina barn skulle bevaras oskadda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Man såg molnskyn överskygga. lägret och torr mark dyka upp där det förut stod vatten; man såg en öppen väg framträda i Röda havet, och där vågorna hade rasat, en gräsbevuxen slätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Över den drogo de nu fram i samlad skara, dessa som beskyddades genom din hand, och därvid fingo de skåda sällsamma under.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Ty såsom hästar fördes de i bet, och såsom lamm hoppade de omkring, och de prisade dig, o Herre, som frälsade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'De kommo också ännu ihåg vad som hade hänt i det land där de hade bott såsom främlingar, huru jorden, i stället för att alstra fyrfotadjur, frambragte mygg, och huru floden, i stället för fisk, gav ifrån sig en stor hop paddor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Sedan fingo de också se fåglar alstras på ett nytt sätt, när de, drivna av sin lystnad, bådo om läcker kost.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Ty till deras hugnad uppstego åt dem vaktlar från havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Men straffdomarna kommo över syndarna, sedan de dock på förhand hade fått mottaga förebud genom våldsamma ljungeldar; ja, rättvist fingo de lida för sina onda gärningar. De hade ju ock visat ett bittrare hat mot främlingar än andra hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Andra kunde väl vägra att taga emot obekanta som kommo till dem; dessa däremot gjorde främlingar som hade bevisat dem godhet till trälar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Men därutöver gjorde de något som skall ådraga dem ytterligare hemsökelser medan nämligen de andra strax mottogo de främmande männen fientligt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'togo dessa först emot främlingarna med festligheter, men plågade dem sedan genom tunga arbeten, fastän de ju redan hade fått medborgarrätt hos dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Men så blevo dessa ock slagna med blindhet, likasom de andra utanför den rättfärd iges dörr, när de, höljda av ett gapande mörker, var för sig sökte efter ingången till hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Ty såsom på ett stränginstrument tonernas taktart växlar, medan de själva alltid förbliva sig lika till sitt ljud, på samma sätt kunna ock elementen ändra sitt inbördes förhållande. Och detta kan man tydligt finna, om man betraktar det som då skedde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Ty lantdjur förvandlades till vattendjur, och djur som plägade simma gingo i stället på land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Elden fick i vattnet ökad kraft, och vattnet glömde sin kraft till att släcka eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Å andra sidan förtärde lågorna icke köttet på ömtåliga djur, när dessa rörde sig däri, och den gudomliga födan smälte icke trots sin lättsmälta, isartade natur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Ja, på allt sätt, o Herre, har du upphöjt och förhärligat ditt folk och har icke försmått det, utan alltid och allestädes har du stått det bi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Jesu Syraks sonson berättar om tillkomsten av sin farfaders bok och av sin egen översättning av boken från hebreiska till grekiska. Genom lagen och profeterna och de övriga som följde efter dessa hava många stora gåvor kommit oss till del; och för deras skull må man med rätta berömma Israel för tukt och vishet. Nu är det ju tillbörligt att de som läsa dem icke allenast själva skaffa sig insikt därigenom, utan att dessa, som söka kunskap för egen del, också finna möjlighet att både genom tal och skrift bliva de utomstående till gagn. Det var därför som också min farfader Jesus, vilken med stor iver hade ägnat sig åt studiet av lagen och profeterna och de övriga fäderneärvda böckerna och så gjort sig synnerligen förtrogen med dem, kände sig manad att författa en skrift som hade avseende på tukt och vishet. Och detta gjorde han, för att de som söka kunskap skulle inhämta också vad han hade skrivit, och så ännu mycket mer kunna göra framsteg i livet efter lagen. Vi bedja eder nu att med välvilja och uppmärksamhet läsa detta och att hava överseende med oss, om vi någon gång, trots all den möda vi hava gjort oss med översättningen, tyckas hava misslyckats med några enskilda uttryck. Ty något som ursprungligen är avfattat på hebreiska förbliver icke längre alldeles detsamma, när det överflyttas till ett annat språk. Och icke allenast om denna bok, utan också om själva lagen och profetskrifterna och de övriga böckerna gäller det att de på grundspråket taga sig ganska annorlunda ut. När jag under det trettioåttonde året av konung Evergetes’ regering kom till Egypten och sedan uppehöll mig där en tid, fann jag därstädes tecken på en ganska hög bildning. Själv ansåg jag det då vara högeligen nödvändigt att nedlägga en viss iver och flit på att utföra en översättning av denna bok. Jag använde också verkligen, under den tid som stod mig till buds, mycken möda och skicklighet för att få boken färdig och så giva ut den, till gagn jämväl för dem som, där de leva i främmande land, gärna söka vinna ökad kunskap, allt under det att de redan förut sträva att inrätta sitt liv till en vandel efter lagen. All vishet kommer från Herren, och hos honom förbliver hon till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Vem kan räkna havets sand och regnets droppar och evighetens dagar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Vem kan utrannsaka himmelens höjd och jordens bredd och havets djup — eller visheten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Före allting är visheten skapad; insikt och förstånd äro till av evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'För vem har vishetens rot blivit blottad, och vem har lärt känna hennes kloka rådslag? [');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, ']');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'En finnes, som är vis, en övermåttan fruktansvärd, han som sitter på sin tron, Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Det var han som skapade henne, han såg och mätte henne och utgöt henne över alla sina verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Hos allt levande finnes hon, efter det mått som honom täcktes; men rikligen gav han henne åt dem som älska honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Herrens fruktan är ära och berömmelse och glädje och en fröjdekrans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Herrens fruktan förnöjer hjärtat och giver glädje och fröjd och långt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Den som fruktar Herren, honom skall det på sistone gå väl, och i sin dödsstund skall han varda välsignad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Vishetens begynnelse är att frukta Gud, och de trogna är hon medfödd allt ifrån moderlivet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Bland människor har hon byggt sig en evigt grundad boning, och i deras släkte sätter man sin lit till henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Vishetens fullhet är att frukta Herren, och av sina frukters saft giver hon de sina rikligen att dricka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Hela sitt hus uppfyller hon med ljuvliga ting och förrådshusen med sina håvor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Herrens fruktan är vishetens ärekrans, och den låter lycka och hälsa uppblomstra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Ja, Herren såg och mätte henne; han lät förstånd och insiktsfylld kunskap flöda och gjorde deras ära stor, som hålla fast vid henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Vishetens rot är att frukta Herren, och hennes grenar äro långt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Orättfärdig vrede kan icke bliva ostraffad, ty när vreden tager överhand, bringar den en människa på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Den tålmodige härdar ut, till dess tiden är inne; därefter kommer honom glädje till del.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Till dess tiden är inne, håller han sina ord tillbaka, och mångas läppar skola förtälja om hans förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Bland vishetens skatter finnas sinnrika ordspråk, men för syndaren är gudsfruktan en styggelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Åstundar du visheten, håll då buden, så skall Herren förläna dig henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 27, 'Ty Herrens fruktan är vishet och tukt, och vad han har behag till är trohet och ödmjukhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 28, 'Var icke gensträvig mot Herrens fruktan, och slut dig ej till den med delat hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 29, 'Skrymta icke inför människorna, och hav akt på dina läppar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 30, 'Upphöj icke dig själv, på det att du ej må falla och så draga vanära över dig. Herren kan ju uppenbara dina hemliga tankar och nedslå dig mitt i församlingen; ty du slöt dig icke till Herrens fruktan, och ditt hjärta var fullt av svek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Min son, om du vill ägna dig åt Herrens tjänst, gör då din själ beredd för frestelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Håll ditt hjärta ståndaktigt, och härda ut, och överila dig icke i hemsökelsens stund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Håll dig till Herren, och vik ej bort ifrån honom, så skall du på sistone bliva upphöjd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Tag emot vadhelst som vederfares dig, och var tålig i lidandets skiften.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Ty i elden prövas guldet, och i lidandets smältugn de människor som täckas Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Förtrösta på honom, så skall han taga sig an dig; gå raka vägar, och hoppas på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'I som frukten Herren, förbiden hans barmhärtighet, och viken ej av, på det att I icke mån falla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'I som frukten Herren, förtrösten på honom, så skall eder lön icke utebliva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'I som frukten Herren, vanten eder lycka och evig glädje och förbarmande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Sen på förgångna släkten och given akt: vem satte sin lit till Herren och kom på skam? Eller vem stod fast i hans fruktan och blev övergiven? Eller vem åkallade honörn och blev försmådd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Nej, barmhärtig och nådig är Herren; han förlåter synder och frälsar i nödens tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Ve över försagda hjärtan och maktlösa händer och över syndaren som går fram på dubbla stigar!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Ve över det maktlösa hjärtat, eftersom det ingen förtröstan har! Därför skall det ej heller bliva beskärmat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Ve eder som haven uppgivit hoppet! Vad viljen I väl göra, när Herren kommer med sin hemsökelse?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'De som frukta Herren äro icke ohörsamma mot hans ord, och de som älska honom, de hålla sig på hans vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'De som frukta Herren söka efter vad han har behag till, och de som älska honom, de mätta sig av lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'De som frukta Herren göra sina hjärtan beredda och ödmjuka sina sinnen inför honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, '»Låt oss falla i Herrens hand och icke i människohand.» Ty så stor som han själv är, så stor är hans barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Hören, I barn, vad som är en faders rätt, och gören härefter, för att det må gå eder väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Ty Herren har bestämt att en fader skall äras av sina barn, och vad som är en moders rätt har han fastställt för hennes söner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Den som hedrar sin fader, han skaffar försoning för sina synder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'och den som ärar sin moder, han är lik en som samlar en skatt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Den som hedrar sin fader skall själv få glädje av sina barn; och när han beder, skall han bliva hörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Den som ärar sin fader får länge leva, och den som är hörsam mot Herren, han bliver sin moder till hugnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Den som fruktar Herren hedrar sin fader och tjänar sina föräldrar såsom tjänare sina herrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Hedra din fader i ord och gärning, för att välsignelse från honom må komma över dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Ty en faders välsignelse bygger barnens hus, men en moders förbannelse river ned det till grunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Sök icke din ära i din faders vanheder, ty din faders vanheder är ingen ära för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Nej, en mans ära kommer av hans faders heder, men en smälek för barnen är en vanryktad moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Min son, tag dig an din fader på hans ålderdom, och gör honom icke någon sorg, så länge han lever.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Och om hans förstånd bliver svagt, så överse med honom, och visa honom icke vanvördnad, därför att du själv står i din fulla kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Ty barmhärtighet mot din fader skall icke bliva förgäten i stället för att straffas för dina synder skall du vinna välstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'På din nöds dag skall du bliva ihågkommen; likasom frost för solen skola dina synder smälta bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Lik en gudsförsmädare är den som övergiver sin fader, och förbannad av Herren är den som förtörnar sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Min son, utför i ödmjukhet vad dig åligger, så skall du bliva älskad av envar som täckes Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Ju större du är, desto mer må du ödmjuka dig; då skall du finna nåd inför Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Ty stor är Herrens makt, och av de ödmjuka bliver han ärad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Sök icke efter det som är dig för svårt, och forska ej efter det som övergår dina krafter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Det som har blivit dig förelagt, det må du begrunda, ty det förborgade angår dig icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Syssla icke förvetet med det som ligger utanför din uppgift, ty mer än en människa kan fatta har dock blivit dig givet att känna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Många hava ju av egna meningar förts vilse, och dåraktig inbillning har kommit deras tankar på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ett förmätet hjärta går det på sistone illa, och den som gärna giver sig i fara, han förgås däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Ett förmätet hjärta bliver nedtyngt av vedermödor, och syndaren hopar synd på synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 27, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 28, 'För den övermodiges ofärd finnes ingen bot, ty ondskans planta är djupt rotad hos honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 29, 'Den förståndiges hjärta begrundar tänkespråk, och den vises lust är ett lyssnande öra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 30, 'Vatten släcker brinnande eld, och barmhärtighet bringar försoning för synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 31, 'Den som återgäldar välgärningar, han tänker på framtiden, och då han är nära att falla, skall han finna stöd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Min son, undanhåll ej den fattige hans uppehälle, och låt bedjande blickar icke vänta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Bedröva icke den som hungrar, och gör ej den nödställde förbittrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Reta icke ytterligare upp ett förbittrat sinne, och låt ej den behövande vänta på din gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Avvisa icke den bönfallande i hans betryck, och vänd ej ditt ansikte bort ifrån den fattige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Vänd icke ditt öga bort ifrån en bedjande, och giv ingen tillfälle till att förbanna dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Ty när någon förbannar dig i sitt sinnes bitterhet, skall han som har skapat honom höra hans bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Gör dig omtyckt i församlingen, och sänk ditt huvud inför den mäktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Böj ditt öra till den fattige, och giv honom i saktmod vänligr svar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Rädda den som lider orätt från den som kränker hans rätt, och var oförskräckt, när du fäller dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Var för de faderlösa såsom en fader, och i makes ställe för deras moder. Då skall du vara likasom en son till den Högste, och han skall älska dig mer än din egen moder älskar dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Visheten upphöjer sina barn och tager sig an dem som fara efter henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Den som har henne kär, han har livet kärt, och de som bittida söka henne skola bliva mättade med glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Den som håller fast vid henne, han får ära till arvedel, och där hon träder in, där giver Herren sin välsignelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'De som tjäna henne göra prästtjänst inför den Helige, och dem som älska henne älskar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Den som är hörsam mot henne skall få döma folken, och den som aktar på henne skall få bo i trygghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Om någon sätter sin lit till henne, skall han få henne till arvedel, och hans efterkommande skola förbliva i besittning av henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'I begynnelsen vandrar hon väl svåra omvägar med honom; hon låter fruktan och räddhåga komma över honom och plågar honom med sin tuktan, till dess hon kan lita på honom och har fått pröva honom genom sina krav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Men sedan vänder hon raka vägen tillbaka till honom och bereder honom glädje och uppenbarar för honom sina hemligheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Men viker han av på orätt stig, så lämnar hon honom och giver honom till pris åt det fall som väntar honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Giv akt på vad stunden kräver, och tag dig till vara för vad ont är, och blygs sedan icke över dig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Ty det finnes en blygsel som drager synd med sig; det finnes ock en blygsel som medför ära och ynnest.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Hav icke anseende till personen, därmed skadar du dig själv; och visa ej falsk försyn, därmed kommer du själv på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Håll icke ditt ord tillbaka, när du kan hjälpa, och fördölj icke din vishet av fåfänga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Ty genom ord bliver vishet kunnig, och tukt genom tungans tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Motsäg icke sanningen; fastmer må du skämmas över din egen fåkunnighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Blygs icke för att bekänna dina synder, nej, kämpa icke mot strömmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Fall icke till föga för en dåraktig man, och hav ej anseende till den mäktiges person.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Kämpa för sanningen intill döden, så skall Herren Gud strida för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Var icke käck i tungan och trög och slapp i handlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Var icke såsom ett lejon i ditt hus eller en misstänksam tyrann bland dina tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Förlita dig ej på dina ägodelar, och säg icke: »Jag har nog.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Låt icke din åtrå och din kraft leda dig, så att du vandrar efter ditt hjärtas begärelser;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'och säg icke: »Vem kan befalla över mig?» Ty Herren skall förvisso straffa dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Säg icke: »Väl har jag syndat, men vad ont har hänt mig?» Ty Herren är långmodig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Gör dig icke säker om förlåtelse, så att du hopar synd på synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Och säg icke: »Hans misskundsamhet är stor, mina många synder skall han förlåta.» Ty barmhärtighet finnes hos honom, men också vrede, och över syndarna vilar hans förtörnelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Dröj icke med att omvända dig till Herren, och skjut ej upp det dag efter dag. Ty plötsligt skall Herrens vrede bryta ut, och i straffdomens stund skall du förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Förlita dig icke på orättfångna ägodelar, ty de skola ej gagna dig på hemsökelsens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Kasta icke säd vid vilken vind som helst, och gå ej på vilken stig som helst; så gör den tvetungade syndaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Var fast i din övertygelse, och ett vare ditt tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Var snar till att höra, men giv ditt svar med betänksamhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Förstår du saken, svara då din nästa; varom icke, så lägg handen på munnen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Ära eller vanheder kan ligga i en människas tal, och tungan kan bringa henne på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Akta dig för att få heta örontasslare, och lägg icke försåt med din tunga. Ty tjuven drager över sig skam, och den tvetungade en hård dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Varken i stort eller i smått må du fela,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'och bliv icke en fiende i stället för en vän. Ty ett dåligt namn får skam och smälek på sin lott; så går det den tvetungade syndaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Förhäv dig icke i ditt hjärtas rådslag, på det att du ej må föröda din kraft, lik en rasande tjur:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'dina löv skall du förtära, och dina frukter skall du fördärva och själv stå där kvar såsom ett förtorkat träd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'En ond själ fördärvar den som har en sådan och gör honom till ett ämne för fiendernas skadeglädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'En len strupe gör vännernas antal stort, och en tunga som talar milt framkallar mycken vänlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Må de vara många, som du lever i frid med, men till förtrogen hav en på tusen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Om du vill skaffa dig en vän, så sätt honom först på prov, och förtro dig icke för snart åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Ty mången är vän, så länge han har gagn därav, men håller icke ut, när du kommer i trångmål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Och mången vän förvandlas till fiende och omtalar sedan osämjan på sådant sätt att du får skam därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Mången är vän, så länge han sitter vid ditt bord, men håller icke ut, när du kommer i trångmål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Medan det går dig väl, vill han vara lik dig och uppträder med myndighet mot ditt husfolk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'men råkar du i betryck, så bliver han din motståndare och gömmer sig undan för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Håll dig på avstånd från dina fiender, och tag dig till vara för dina vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'En trogen vän är ett starkt beskärm; den som har funnit en sådan, han har funnit en skatt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'En trogen vän kan med intet betalas; nej, hans värde kan icke vägas upp på våg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 16, 'En trogen vän är en livgivande balsam; de som frukta Herren finna en sådan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 17, 'Den som fruktar Herren, han är vän på det rätta sättet, ty sådan han själv är, sådan är hans förtrogne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 18, 'Min son, hav tuktan kär allt ifrån din ungdom, så skall du intill grånad ålder finna vishet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 19, 'Var såsom plöjaren och såningsmannen, när du nalkas henne, och vänta på hennes goda frukter. Ty arbetet på hennes åker skall kosta dig en kort stunds möda, men sedan skall du snart få njuta av hennes alster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 20, 'Huru svårtillgänglig är icke visheten för dem som ej vilja låta undervisa sig! Ja, den oförståndige härdar icke ut med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 21, 'Lik en tung lyftesten bliver hon för honom; det dröjer icke länge, förrän han kastar henne ifrån sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 22, 'Ty visheten gör skäl för sitt namn; hon är icke uppenbar för många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 23, 'Hör, min son, och tag emot mina lärdomar, och förkasta icke mitt råd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 24, 'Stick dina fötter i hennes bojor, och ditt huvud i hennes halsjärn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 25, 'Böj din rygg och bär henne, och knota icke över hennes band.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 26, 'Slut dig till henne med hela din själ, och håll dig på hennes vägar av all din kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 27, 'Spana och sök, så skall hon göra sig känd för dig; och när du har fått henne fatt, så släpp henne icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 28, 'Ty på sistone skall du få erfara den vederkvickelse hon giver, och hon skall vändas i glädje för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 29, 'Då skola bojorna bliva till ett fast beskärm för dig, och hennes halsjärn till en äreskrud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 30, 'Ty ett gyllene smycke bär hon, och hennes huvudbindel är vävd av purpur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 31, 'Du skall ikläda dig henne såsom en äreskrud och pryda dig med henne såsom med en fröjdekrans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 32, 'Min son, om du så vill, skall du bliva undervisad, och du skall bliva klok, om du vinnlägger dig därom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 33, 'Om du gärna hör, så skall du ock få inhämta något, och om du böjer ditt öra till, så skall du bliva vis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 34, 'Ställ dig där gamla män äro församlade; och där någon vis finnes, slut dig till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 35, 'Var ivrig att höra, närhelst det talas om gudomliga ting, och låt djupsinniga tänkespråk icke undgå dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 36, 'Finner du en förståndig man, så begiv dig bittida till honom, och låt din fot nöta tröskeln till hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 37, 'Begrunda Herrens befallningar, och tänk beständigt på hans bud. Han skall göra ditt hjärta fast, och ditt begär efter visheten skall bliva stillat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Gör intet ont, så skall ej heller något ont drabba dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Håll dig fjärran ifrån missgärning, så skall ock den vika bort ifrån dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Min son, så icke i orättfärdighetens fåror; du skall då slippa att skörda sjufalt igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Begär icke av Herren en härskarställning eller av konungen en äreplats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Håll dig icke för rättfärdig inför Herren, och gör dig ej vis inför konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Begär icke att bliva en domare. Kanhända skulle du ej förmå avskaffa all orättfärdighet. Du skulle måhända rädas för den mäktige och sätta en anstötlig fläck på din rättrådighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Förgå dig icke mot menigheten i staden, och bered ej själv ditt fall bland folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Belasta dig icke två gånger med synd, ty redan för en synd skall du ej bliva osträffad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Säg icke: »Gud, den Högste, skall se till mängden av mina offergåvor, och när jag frambär dem till honom, skall han nådigt taga emot dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Var icke klentrogen, när du beder; och försumma ej att öva barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Håna icke den som är bedrövad i sitt sinne, ty det finnes en som både ödmjukar och upphöjer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Smid icke ihop lögn mot din broder; gör ej heller så mot din vän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Akta dig noga för att tala osanning, ty vanan att ljuga leder icke till något gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Var icke talträngd där gamla män äro församlade, och upprepa ej samma ord, när du beder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Sky icke mödosamt arbete, nej, sky icke åkerbruket, ty det är inrättat av den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Låt dig ej bliva räknad bland syndares skara; kom ihåg att vredesdomen icke dröjer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Ödmjuka dig av hjärtat; ty den ogudaktiges straff är eld och mask.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Byt icke bort en vän mot penningar, eller en sannskyldig broder mot guld från Sufir.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Missakta icke en vis och god hustru, ty hennes ljuvhet är mer värd än guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Behandla icke en tjänare illa, som arbetar troget, eller en daglönare som ägnar sig helt åt din tjänst,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Nej, älska av hjärtat en god tjänare, och undanhåll honom icke friheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Har du boskapsdjur, vårda dig då om dem; och äro de dig nyttiga, så gör dig ej av med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Har du barn, håll dem då i tukt, och böj deras nacke allt iirån ungdomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Har du döttrar, vaka då över deras kyskhet, och visa dem icke en alltför blid uppsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Gift bort din dotter; då har du fullgjort ett viktigt värv. Men giv henne åt en förståndig man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Har du en hustru efter ditt sinne, så förskjut henne icke, men förtro dig ej åt en som har blivit försmådd av dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Ära din fader av allt ditt hjärta, och förgät icke din moders födslovåndor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Kom ihåg att du är född av dem. Varmed kan du väl återgälda dem vad de hava gjort för dig?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Frukta Herren av all din själ, och håll hans präster i ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Älska din Skapare av all din kraft, och glöm icke bort hans tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Frukta Herren och ära prästen, och giv denne hans del, såsom det har blivit dig bjudet: förstlingsgåva och skuldoffer och offergärdslår, heligt slaktoffer och förstlingen av det heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Räck också ut din hand åt den fattige, för att den välsignelse du får må bliva fullkomlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'En gåva är välkommen för var levande; men jämväl när det gäller en död, må du ej hålla din välvilja tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Drag dig icke undan dem som gråta, utan sörj med dem som sörja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Var icke sen till att besöka sjuka, ty för sådana gärningar skall du bliva älskad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Tänk på änden vid allt vad du förehar; då skall du aldrig synda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Strid icke med en mäktig man, på det att du ej må falla i hans händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Tvista icke med en rik man, på det att han ej må uppväga dig med sitt guld. Ty guldet har förstört många, jämväl konungars hjärtan har det fört på avvägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Strid icke med en munvig man, och lägg ej bränsle på hans eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Skämta icke med en ouppfostrad man, på det att dina förfäder icke må bliva vanärade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Tala ej hårda ord till någon som vill omvända sig från sin synd; tänk därpå att vi alla förtjäna straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Visa icke vanvördnad mot någon på hans ålderdom; ty också bland oss skola somliga bliva åldringar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Triumfera icke över någon död; tänk därpå att vi alla måste skiljas hädan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Ringakta icke vad de vise tala, utan sysselsätt dig med deras tänkespråk. Ty av dem kan du lära dig tukt, och huru du’; skall tjäna de mäktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Missakta icke vad gamla män tala; också de hava ju lärt av sina fäder. Ty av dem kan du lära dig insikt, och huru du skall svara, när så behöves.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Blås icke eld i en syndig mans kol, på det att du ej må brinna upp i lågan av hans eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Förlora icke besinningen inför den övermodige; han kunde ju lägga sig i bakhåll för dina ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Låna icke åt någon som är mäktigare än du; men om du lånar något åt en sådan, anse det då såsom förlorat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Gå icke i borgen över din förmåga; men om du går i borgen, så var beredd på att få betala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'För icke rättegång mot en domare, ty för hans anseendes skull kommer man att giva honom rätt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Gör icke någon resa tillsammans med en våghals, på det att du icke må drabbas av svår ofärd. Ty han gör vad han får i sinnet, och genom hans oförnuft skall du dragas med i fördärvet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Giv dig icke i strid med den som lätt vredgas, och färdas ej genom öknen i hans sällskap. Ty blod aktas såsom intet i hans ögon, och där ingen hjälp står att få slår han dig till marken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Gå icke till råds med en dåre, ty han kan icke hålla tyst med saken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Gör ej i en främmandes närvaro något som skall hållas hemligt, ty du vet icke vad han kommer att bringa å bane.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Öppna icke ditt hjärta för vem som helst; du kunde annars få skörda otack därför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Var icke svartsjuk på hustrun i din famn, och giv henne ej en dålig lärdom, dig själv till skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Giv dig icke så hän åt en kvinna, att hon helt tager väldet över dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Sök ej en lättfärdig kvinnas umgänge, på det att du icke må falla i hennes snaror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Var ej för mycket tillsammans med en harpospelerska, på det att du icke må fångas genom hennes konster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Tag dig till vara för att betrakta en jungfru, ty du kunde råka illa ut och få betala böter för hennes skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Giv dig icke hän åt skökor, på det att du ej må förspilla ditt arv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Gå icke omkring och speja på gatorna i staden, och stryk ej omkring på dess ensliga platser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Vänd ditt öga bort ifrån en fager kvinna, och betrakta ej en främmande kvinnas skönhet. Genom kvinnoskönhet hava många blivit förvillade, och genom den bliver älskog upptänd såsom eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Sitt alls icke tillsammans med en gift kvinna, och håll inga dryckesgillen i sällskap med en sådan, på det att icke ditt hjärta må vända sig till henne och du i ditt blod fara ned i fördärvet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Övergiv icke en gammal vän, ty en ny kan ej förliknas vid honom. En ny vän är såsom nytt vin: när det bliver gammalt, dricker du det med förnöjelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Avundas icke en syndare hans härlighet, ty du vet icke vilken ände det skall taga med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Finn ej heller ditt behag i de ogudaktigas välgång; tänk därpå att de ej skola gå fria ända till sin grav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Håll dig fjärran ifrån den som har makt att döda, så skall du icke behöva känna fruktan för ditt liv. Men kommer du i hans närhet, så förgå dig ej, på det att han icke må beröva dig livet. Besinna väl att du går fram mitt ibland snaror och vandrar omkring på fästningstinnar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Sök lära känna din nästa så mycket du förmår, och gå till råds med dem som äro visa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Allenast med de förståndiga må du giva dig i samtal, och allt vad du talar om må gälla den Högstes lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Rättfärdiga män vare dina bordskamrater, och i Herrens fruktan må du hava din berömmelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Konstnärens hand gör verket prisat, och fursten aktas vis för sina ords skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'En munvig man är fruktad i sin stad, och den som är obetänksam i sina ord, han gör sig förhatlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'En vis furste håller sitt folk i tukt, och där en förståndig man styr, där råder god ordning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Sådan fursten är, sådana äro hans tjänare, och sådan styresmannen i en stad är, sådana äro alla dess inbyggare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'En ovis konung bereder sitt folks fördärv, men en stad bliver folkrik genom de mäktiges insikt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'I Herrens hand ligger makten över jorden, och när tiden är inne, sätter han rätte mannen till härskare över den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'I Herrens hand ligger en mans framgång, och han förlänar ämbetsmannen hans ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Vredgas ej på din nästa, vad orätt som än sker dig; och när våldsgärningar begås mot dig, så håll dig stilla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Både inför Herren och inför människor är övermod förhatligt, och att kränka någons rätt är synd inför både honom och dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Herradömet flyttas över från ett folk till ett annat för missgärningars och våldshandlingars och vinningslystnads skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Varför förhäver sig den som stoft och aska, ja, den vilkens inälvor kunna giva sig ut, medan han ännu lever?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Långvarig är sjukdomen; den gäckar läkarens konst: i dag är han konung, i morgon är han död!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Ty när en människa dör, då bliva kryp, smådjur och maskar hennes lott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Övermodet begynner med att en människa avfaller från Herren, och med att hennes hjärta viker av ifrån hennes Skapare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Ty synden är övermodets begynnelse, och den som håller fast vid synden, av honom flödar styggelse. Fördenskull har Herren låtit underliga hemsökelser drabba de övermodiga, och han har förgjort dem i grund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Härskares troner har Herren störtat omkull och uppsatt ödmjuka män i deras ställe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Folk har Herren ryckt upp med rötterna och i deras ställe planterat dem som voro ringa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Befolkade länder har Herren förhärjat, han har förgjort dem ända ned till jordens grundvalar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Han har bortryckt deras inbyggare från människors tal och förgjort dem, och han har utplånat deras åminnelse på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Icke är övermodet skapat för människor eller häftig vrede för dem som äro födda av kvinnor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Vilket släkte är ärofullt? Människors släkte. Vilket släkte är ärofullt? Deras som frukta Herren. Vilket släkte är ärelöst? Människors släkte. Vilket släkte är ärelöst? Deras som överträda buden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Bland bröder är den ärad, som är deras hövding, så ock i Herrens ögon de som frukta honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Den rike, den ansedde, den fattige - allas berömmelse är Herrens fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Det är icke rätt att förakta en fattig man som är vis, ej heller höves det att ära en syndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Stormannen, domaren och den mäktige bliva ärade; men ingen bland dem är större än den som fruktar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'En träl som är vis få fria män tjäna, och den som är förståndig knorrar icke däröver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Ställ dig icke vis, när du skall utföra ditt arbete, och håll dig ej förnäm, när du är i trångmål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Bättre är den som arbetar och har allting i överflöd än den som håller sig förnäm och lider brist på bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Min son, ära dig själv i all ödmjukhet, och tillräkna dig själv heder efter förtjänst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Vem skall skaffa den rätt, som gör orätt mot sig själv, och vem skall ära den som missaktar sitt eget liv?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Den fattige bliver ärad på grund av sitt förstånd, och den rike bliver ärad på grund av sin rikedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Men om någon bliver ärad såsom fattig, huru mycket mer då såsom rik! Och om någon är ärelös såsom rik, huru mycket mer då såsom fattig!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Den ödmjukes vishet upplyfter hans huvud och giver honom en plats ibland stormän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Prisa ingen för hans skönhets skull, och fatta ej motvilja mot någon för hans utseendes skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Bland bevingade varelser är biet en av de minsta, men vad det frambringar är det yppersta av allt sött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Yvs icke över kläderna som du bär, och förhäv dig ej på din äras dag Ty underbara äro Herrens gärningar, och vad han gör är förborgat för människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Många furstar hava måst sätta sig nere på marken, rnen den som ingen tänkte på, han har fått bära en krona.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Många härskare hava blivit höljda med vanära, och ansedda män hava blivit givna i andras våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Klandra icke, förrän du har undersökt saken; överväg först, och straffa sedan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Svara icke, förrän du har hört till slut, och fall ej en annan i talet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Tvista icke om en sak som ej kommer dig vid, och när syndare gå till rätta med varandra, så håll dig undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Min son, syssla icke med mångahanda; om du tager dig mycket före, så skall du ej bliva ostraffad. Om du jagar efter mycket, så skall du icke nå det, och om du vill fly därifrån, så skall du ej komma undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Den ene arbetar och mödar sig och avlas, och dess mer går det tillbaka för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Den andre är trög och behöver andras hjälp, lider brist på kraft och har överflöd på fattigdom; men Herrens ögon skåda på honom till hans bästa, och han upprättar honom ur hans förnedring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Ja, han upplyfter hans huvud, så att många måste förundra sig över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Lycka och olycka, liv och död, fattigdom och rikedom - alltsammans kommer från Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Vad Herren giver, det få de fromma behålla, och vad han vill, det har alltid framgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Mången bliver rik genom sin månhet och gnidighet, men detta är den lön som beskäres honom:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'medan han säger: »Jag har kommit till ro, nu vill jag njuta av mitt goda», vet han icke huru lång tid skall förlida, förrän han måste lämna det åt andra och själv dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Stå fast i din uppgift, och lev i den, ja, åldras i ditt värv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Förundra dig icke över syndarens gärningar, förtrösta på Herren, och förbliv vid ditt arbete. Ty det är lätt i Herrens ögon att hastigt och oväntat göra den fattige rik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Herrens välsignelse är den frommes lön, och på kort tid låter han sin välsignelse blomstra upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Säg icke: »Vad nytta kan jag väl göra, och vad gott kan jag vänta härefter?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Säg ej heller: »Jag har nog, och vad ont kan härefter drabba mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'På lyckans dag glömmer man olyckan, och på olyckans dag minnes man icke lyckan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Ty det är lätt för Herren att på dödsdagen vedergälla en människa efter hennes vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'En kort stunds ofärd bringar det förra överflödet i glömska, och vid en människas slut komma hennes gärningar i dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Prisa ingen lycklig före hans död. Hurudan en man har varit, det kan man se på hans efterkommande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'För icke vem som helst in i ditt hus, ty mångfaldiga äro den listiges försåt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Likt en lockfågel i sin bur är den övermodiges hjärta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 31, 'och lik spejaren spanar han efter ditt fall. Försåtligt vänder han gott tills ont, och på det allra bästa sätter han en fläck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 32, 'Av en enda gnista bliver en stor eld, och syndaren ligger i försåt för att få utgjuta blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 33, 'Tag dig i akt för den illasinnade, ty han stämplar ont; låt honom icke sätta en fläck på dig för evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 34, 'Tag en främling i ditt hus, och han skall där komma förvirring och oro åstad och göra dig själv till en främling för dina egna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Om du vill göra gott, så se till, mot vem du gör det; då skall du få tack för dina välgärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Gör den fromme gott, så skall du undfå vedergällning, om icke av honom, så dock av den Högste. Välgärningar må ej bevisas den som framhärdar i det onda eller den som icke själv övar välgörenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Giv åt den som är god, men tag dig ej an syndaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Gör den ödmjuke gott, men giv intet åt den ogudaktige. Undanhåll denne ditt bröd; nej, giv det icke åt honom, på det att han icke därigenom må få makt över dig. Ty i dubbelt mått skall du få ont igen för allt gott som du har gjort mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Också den Högste hatar ju syndare, och de ogudaktiga låter han få sitt straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'I medgången lär man icke känna vännen, och i motgången bliver ej ovännen fördold.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'När en man har medgång, hava hans ovänner sorg; och när han har motgång, drager sig också vännen undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Tro aldrig någonsin din ovän; ty såsom kopparen höljer sig med ärg, så ock hans ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Om han än ödmjukar sig och går där med nedböjt huvud, så giv dock noga akt och tag dig till vara för honom. Det skall då gå dig, såsom när man polerar en metallspegel: du skall märka att han ej till slutet kan behålla sin ärg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Ställ honom icke vid din sida, på det att han ej må stöta omkull dig och intaga din plats. Sätt honom ej på din högra sida, på det att han icke må fika efter din stol. Du kunde då på sistone få sanna mina ord och med bitter smärta tänka på vad jag har sagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Vem har väl medlidande med en ormtjusare som bliver biten eller med någon av dem som befatta sig med vilda djur?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Lika litet har man medlidande med den som umgås med en syndare och invecklar sig i hans synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Han stannar väl hos dig till en tid, men om du slår in på en annan väg, så håller han icke ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Med sina läppar talar väl ovännen söta ord, men i sitt hjärta lägger han råd om att störta dig i gropen. Med sina ögon fäller väl ovännen tårar, men om han finner tillfälle, bliver han ej mätt på blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Om en olycka träffar dig, finner du honom före dig på platsen, och under sken av att vilja hjälpa slår han benen undan dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Han skakar huvudet och klappar i händerna, han tisslar och tasslar och visar dig en ny uppsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Den som kommer vid tjära, han bliver orenad, och den som umgås med den övermodige bliver honom lik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Tag icke på dig en börda som är för tung för dig, och umgås ej med en som är mäktigare och rikare än du. Vad har lerkrukan att göra med kitteln? Han stöter till, och hon går sönder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Den rike gör orätt och bannar därjämte, den fattige lider orätt och får dessutom göra avbön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Om du kan vara honörn till nytta, så brukar han dig, men om du intet förmår, då frågar han icke efter dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Om du har något, så lever han gärna samman med dig; han tömmer din pung, utan att göra sig några betänkligheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Behöver han dig, så leder han dig vilse; han ler mot dig och ingiver dig förhoppningar. Han talar vackra ord till dig och säger: »Varmed kan jag stå dig till tjänst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Han kommer dig att skämmas genom sina gästabud, till dess han har tömt din pung både två och tre gånger; och sedan, på sistone, gör han narr av dig. När han därefter får se dig, frågar han ej mer efter dig, utan skakar huvudet mot dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Var på din vakt, så att du icke bliver vilseledd och förödmjukad i din fåkunnighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Om en mäktig man kallar på dig, så håll dig tillbaka; så mycket ivrigare skall han då kalla på dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Var ej påträngande, på det att du icke må stötas tillbaka; håll dig ej heller för långt borta, på det att du icke rnå bliva glömd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Stå ej efter att få tala med honom såsom med din like, och tro icke hans många ord. Ty genom sitt myckna ordflöde frestar han dig, och under sken av vänlighet utforskar han dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Obarmhärtig är han som ej tiger med vad som har blivit sagt; icke skall han spara på misshandling och bojor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Var på din vakt och se dig noga för, ty du går på branten av ditt fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Vart levande väsen älskar sin like, och var människa den som står henne närmast. Alla varelser sluta sig samman: efter sina släkten; så bör ock en man hålla sig till sin like.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Icke kan vargen hava någon gemenskap med lammet; lika litet syndaren med den gudfruktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Icke kan frid råda mellan hyenan och hunden, och icke kunna rik och fattig leva i frid med varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Vildåsnorna i öknen äro lejonens jaktbyte; så äro ock de fattiga de rikas bete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Ödmjukhet är en styggelse för den övermodige; likaså är den fattige en styggelse för den rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Om en rik man förlorar fästet, så stödes han av sina vann er, men om en ringa man faller, får han ytterligare en stöt av sina vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Om en rik man vacklar, så finnas många som hålla honom uppe; talar han än otillbörliga ord, så giver man honom dock rätt. Om en ringa man vacklar, så bannar man honom därjämte; säger han något tänkvärt, så lånar man honom dock ej sitt öra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'När en rik man talar, tiga alla stilla, och man höjer hans ord till skyarna. När en fattig talar, då säger man: »Vern är denne?», och snavar han, så slår man därtill omkull honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Något gott är rikedomen, när synd icke låder därvid; ett ont är fattigdomen efter den ogudaktiges mening.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'En människas ansikte skiftar alltefter hennes sinnesstämning, så att hon än visar en ljus uppsyn, än en mörk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Ett glatt ansikte är tecken på ett förnöjt sinne; men att utfinna tänkespråk kräver mödosam eftertanke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Säll är den man som icke felar med sin mun och ej gnages av sorg över någon synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Säll är den som icke fördömes av sin egen själ, och som ej har förlorat sitt hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'För gnidaren passar det icke att vara rik. Och vad har den snåle för gagn av penningar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Den som samlar, men ej unnar sig själv något, han samlar åt andra, och av hans goda skola andra frossa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Den som är hård mot sig själv, vem skulle han vara god emot? En sådan får aldrig någon glädje av sina penningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Ingen är värre än den som är missunnsam mot sig själv; just detta är straffet för hans ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Gör han än något gott, så gör han det av glömska, och på sistone röjer han sin ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'En ond människa är den som har ett missunnsamt öga, den som vänder bort sitt ansikte och icke frågar efter andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Den giriges öga låter sig ej nöja med det som har blivit honom tilldelat, och usel orättfärdighet kommer själen att förtorka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Ett ont öga ser missunnsamt på själva brödet och lider brist vid det egna bordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Min son, gör dig själv gott, efter måttet av vad du äger, och frambär åt Herren värdiga offergåvor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Kom ihåg att döden icke fördröjer sig. Vad dödsriket har beslutit har ej blivit yppat för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Gör din vän gott, förrän du går hädan; räck ut din hand och giv honom, efter din förmåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Försumma icke en glad dag, och försaka ej din del i en oskyldig njutning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Måste du icke åt en annan lämna dina mödors lön, och ditt arbetes frukt till att fördelas genom lott?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Giv och tag, och gör dig inga betänkligheter; ty i dödsriket söker man förgäves goda dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Allt levande åldras såsom en klädnad; sedan urminnes tid är ju så förordnat: »Du skall döden dö.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Likt lövverket som grönskan på ett lummigt träd - en del faller av, och en annan del spricker ut - är det släkte som består av kött och blod: ett släkte dör bort, och ett annat födes till liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Vart människoverk multnar och tager en ände, och den som utförde det, han går bort med det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Säll är den man som tänker på visheten, och som överlägger med sig själv i sitt förstånd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'den som begrundar hennes vägar i sitt hjärta och eftersinnar hennes hemligheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Begiv dig ut efter henne såsom en spanare, och ställ dig på lur där hon träder in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Ja, säll är den som blickar in genom hennes fönster och lyssnar vid hennes dörrar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'som rastar nära hennes hus och slår ned sina tältpluggar vid hennes väggar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'som reser sitt tält invid henne och tager in i ett sådant ljuvligt härbärge;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'som ställer sina barn under hennes skygd och tager sin viloplats under hennes grenar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'som söker skygd hos henne undan hettan och vilar ut i hennes härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Så gör den som fruktar Herren; ja, den som håller fast vid lagen, han vinner henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Hon kommer honom till mötes likasom en moder, och likasom en ung maka tager hon emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Hon giver honom förståndets bröd att äta och vishetens vatten att dricka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Han stöder sig vid henne och vacklar icke, han förlitar sig på henne och kommer ej på skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Hon upphöjer honom över hans närmaste och upplåter hans mun i församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Glädje får han till arvedel, ja, en fröjdekrahs och ett evärdligt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Oförståndiga människor kunna aldrig vinna henne, och syndiga män få icke skåda henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Fjärran är hon från de övermodiga, och lögnare hava henne icke i sina tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Lovsång ljuder icke väl i syndarens mun, ty den är honom ej ingiven av Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Nej, ur ett vist hjärta må lovprisning frambäras, och där är den en gåva av Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Säg icke: »Det är Herren som är skulden till mitt avfall»; ty det han hatar, det får du icke göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Säg icke: »Han själv har förlett mig»; ty han behöver ingen syndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Allt vad styggelse heter, det hatar Herren, och de som frukta honom hava icke behag därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Han skapade människan i begynnelsen och överlämnade henne åt hennes fria vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Om du vill, så kan du hålla buden, och att öva trohet står i ditt eget val.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Han har satt framför dig eld och vatten; efter vilket du vill kan du räcka ut din hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Framför människan ligga liv och död; och vilket hon väljer skall varda henne givet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Ty stor är Herrens vishet; väldig är han i makt, och allting ser han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Och hans ögon äro vända till dem som frukta honom, och han känner allt vad en människa har för händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Men ingen bjöd han att vara ogudaktig, och ingen gav han lov till att synda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Åstunda icke en stor skara dåliga barn, och gläd dig ej över ogudaktiga söner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Får du än många barn, så gläd dig ej över dem, om icke Herrens fruktan finnes hos dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Lita icke på att de skola få leva, och gör dig ej säker om att de skola bestå. Ty ett enda barn kan vara bättre än tusen, och att dö barnlös är bättre än att hava ogudaktiga barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'En enda förståndig man kan bliva fader till en folkrik stad, men en hel stam av orättfärdiga varder utrotad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Mycket sådant har jag skådat med mina ögon; ja, om ännu märkligare ting har mitt öra hört.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'I en församling av syndare uppflammar eld, och över ett gensträvigt folk uppflammar vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Herren hade ingen misskund med forntidens jättar, när de i sin väldighet reste sig upp emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Han skonade icke det folk som Löt bodde ibland; han höll dem för en styggelse för deras fräckhets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Han hade ej förbarmande med det folk som var hemfallet åt fördärv, dem som blevo utrotade i sina synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Så gick det ock med skaran av de sex hundra tusen som hade gaddat sig samman i sina hjärtans hårdhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Ja, gällde det allenast en enda hårdnackad man, förunderligt vore, om han bleve ostraffad. Ty barmhärtighet finnes hos Herren, men också vrede; han är mäktig i att förlåta, men han utgjuter ock vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Så stor som hans barmhärtighet är, så stor är hans tuktan; envar dömer han efter hans gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Icke kan syndaren undkomma med sitt rov, och den frommes förväntan sviker han ej.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'All god gärning skall han främja; envar skall få efter vad han har gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Säg icke: »Jag är fördold för Herren, icke tänker väl någon på mig i höjden. Bland så många människor kan jag ej bliva ihågkommen. Ja, vad är min själ i den oändliga skapelsen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Se, himmelen och himlarnas himmel bäva, så ock havsdjupet och jorden, när han låter sin hemsökelse drabba.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Ja, bergen och jordens grundvalar skälva och darra, när han ser på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Och sådant begrundar man icke i sitt hjärta! Nej, vem besinnar hans vägar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Likasom stormvinden, som människan icke kan se, så äro de flesta av hans verk förborgade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, '»Vem kan kungöra hans rättfärdighets gärningar? Eller vem kan vänta ut dem? Nej, länge dröjer det, till dess han fullbordar sitt beslut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Så tänker den som har ringa förstånd; ja, en oförnuftig och förvillad man tänker sådan dårskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Hör mig, min son, och lär dig förstånd, och akta i ditt hjärta på mina ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Jag vill yppa en lära, vägd på våg, och med noggrannhet meddela förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'När Herren skapade sina verk i begynnelsen, ja, redan då han danade dem, bestämde han deras särskilda lotter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Han ordnade för evig tid sina verk och fastställde deras herradömen för alla tider. De bliva icke hungriga eller trötta, och de höra ej upp med att utföra sina värv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'De stöta icke emot varandra, och aldrig äro de ohörsamma mot hans befallningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Därefter skådade Herren på jorden och uppfyllde den med sitt goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Med allahanda levande väsen betäckte han den, och dit vända de åter tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Herren skapade människan av jord, och han lät henne åter vända tillbaka till jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Några få dagar, noga avmätta, beskärde han dem, och han gav dem makt över allt som är på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Han beklädde dem med kraft efter det mått som anstod dem, och till sin avbild skapade han dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Han lät fruktan för dem komma över allt levande och gav dem makt att råda över fyrfotadjur och fåglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Förnuft och tunga och ögon gav han dem; han gav dem öron, och ett hjärta, så att de skulle kunna tänka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Med förstånd och insikt uppfyllde han dem, och han lärde dem vad gott och ont är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Han satte sitt öga i deras hjärtan, för att kunna visa dem huru stora hans verk äro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Så skulle de kunna förtälja hans väldiga gärningar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'och prisa hans heliga namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Därtill förlänade han dem kunskap, och en lag till liv gav han dem till besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Ett evigt förbund upprättade han med dem, och sina rätter lärde han dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Deras ögon fingo skåda hans härlighets majestät, o,ch hans rösts härlighet hörde deras öra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Han sade till dem: »Tagen eder till vara för allt vad orätt är», och gav dem befallning, envar angående hans nästa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Deras vägar ligga alltid uppenbara inför honom, de äro icke fördolda för hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, '(Över vart och ett av de andra folken har han insatt en furste, men Israel är Herrens egen besittning.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Alla deras gärningar ligga inför honom klara såsom solen, och hans ögon äro oavvänt riktade på deras vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Deras missgärningar äro icke fördolda för Herren, och alla deras synder ligga uppenbara inför honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'En mans barmhärtighet förvarar han såsom en signetring, och en människas godhet aktar han noga såsom sin ögonsten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'En gång skall han stå upp och vedergälla dern och låta vedergällningen komma över vars och ens huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Men dem som vilja bättra sig tillstädjer han att vända om, och han uppmuntrar dem som äro nära att uppgiva hoppet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Så omvänd dig nu till Herren, och hör upp med att.synda; bönfall inför hans ansikte, och undvik det som kan komma dig på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Kom tillbaka till den Högste, och vänd om från orättfärdigheten, och hata av hjärtat allt vad styggelse heter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Vem prisar den Högste i dödsriket? Allenast de som leva hembära honom lov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Hos den döde tystnar tacksägelsen - han är ju icke ens mer till; den som har liv och hälsa, han prisar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Huru stor är icke Herrens barmhärtighet och hans förlåtande nåd mot dem som omvända sig till honom!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Ty människorna kunna icke vara fullkomliga; människors barn äro ju icke odödliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Vad är väl klarare än solen? Och ändå sviker dess sken. Huru mycket mer då människan, vilkens sinne är vänt till kött och blod!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Herren mönstrar himlahöjdens härskaror, men människorna äro allasammans stoft och aska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Han som lever i evighet, han har skapat det alltsammans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Herren allena har rätten på sin sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Åt ingen har han givit makt att förkunna hans verk. Och vem kan väl utrannsaka hans väldiga gärningar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Vem kan mäta hans väldiga makt? Och vem kan därjämte skildra hans nådesbevis?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Intet kan tagas bort och intet läggas till; och ingen kan utrannsaka Herrens underbara verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'När någon menar sig vara färdig därmed, då är han allenast vid begynnelsen; och när han menar sig hava kommit till slutet, då står han där rådlös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Vad är väl människan, och vad duger hon till? Vad gott eller vad ont kan hon komma åstad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Talet av en människas dagar är, när det når högt, hundra år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Såsom en vattendroppe i havet eller såsom ett sandkorn, så äro hennes få år i den oändliga tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Fördenskull är Herren långmodig mot dem och utgjuter över dem sin barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Han ser och vet huru svår deras ände är; fördenskull giver han sin förlåtelse i rikt mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'En människas barmhärtighet sträcker sig till hennes nästa, men Herrens barmhärtighet till allt levande. Han agar och tuktar och undervisar; han för till rätta, såsom en herde sin hjord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Han förbarmar sig över dem som taga emot tuktan och över dem som med iver följa hans rätter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Min son, när du gör gott, så gör det utan förebråelser; och fäll aldrig sårande ord, när du giver en gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Daggen mildrar ju den brännande hettan; likaså kan ett ord vara förmer än gåvan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Ja, ett ord kan vara mer värt än en god gåva, men bådadera finnas hos den som gärna gör gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'En dåre talar ovänligt hårda ord, och den missunnsammes gåva kommer ögon att försmäkta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Lär först själv, innan du talar, och sörj för din hälsa, förrän sjukdomen kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Rannsaka dig själv, förrän dom fälles; då skall du i hemsökelsens stund finna förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Ödmjuka dig, innan du har blivit sjuk, och visa ånger i samma stund som du syndar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Låt ej hindra dig från att i rätt tid infria ditt löfte, och vänta icke till din dödsstund med att göra dig fri ifrån det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Överväg noga, innan du gör ett löfte, och var icke lik en som frestar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Tänk på vreden under dina sista dagar, och på domens stund, när Herren vänder sitt ansikte ifrån dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Tänk på hungerns tid, medan du ännu har allt tillfyllest, på fattigdom och brist, under rikedomens dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Från morgonen till aftonen ändrar sig tiden, så skiftar allting hastigt om inför Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'En vis man är på sin vakt i allt, och i frestelsens stund tager han sig till vara för felsteg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Var och en som är förståndig känner visheten; och den som har funnit henne, honom giver han sitt lov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 29, 'De som förstå visa ord, de lägga ock själva vishet i dagen och låta träffande ordspråk flöda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 30, 'Följ icke dina begärelser, utan hejda dina lustar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 31, 'Om du giver medhåll åt din själs begärelse, så skall den göra dig till ett ämne för dina fienders skadeglädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 32, 'Hav icke din glädje i yppig vällevnad, på det att du ej må bliva utarmad genom att taga del i sådant liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 33, 'Bliv ej en tiggare genom att hålla dryckesgillen för lånade penningar, medan du själv intet har i din pung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'En arbetare som är hemfallen åt dryckenskap bliver icke rik; den som föraktar det ringa, han kommer inom kort på obestånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Vin och kvinnor leda förståndiga män på avvägar, och den som håller sig till skökor, han är besinningslös mer än dessa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Han skall bliva ett byte för förruttnelse och maskar, ja, en besinningslös människa skall ryckas bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Den som är för snartrogen, han är lättsinnig, och den som så försyndar sig, han felar mot sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Den som glades över ondskan drager över sig dom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'men den som hatar skvaller, han slipper mycket ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'För aldrig vidare vad någon har sagt; du skall alls intet förlora därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Omtala det icke, vare sig för vän eller ovän; håll det dolt, såframt du därmed icke begår synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Ty när man väl har hört dig, tager man sig i akt för dig, och vid lägligt tillfälle skall man låta dig känna sitt hat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Har du hört ett rykte, låt det då dö med dig; var lugn, du kommer icke att sprängas sönder därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'För ett ryktes skull gripes en dåre av födslovåndor, såsom en barnaföderska för fostrets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Likt en pil som har fastnat i låret är ett rykte som har kommit in i en dåres inre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Tag din vän i förhör; kanhända är han icke skyldig. Men om han är skyldig, så tillrättavisa honom, för att han icke må fela på nytt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Tag din nästa i förhör; kanhända har han icke sagt det. Men om han har sagt det, så tillrättavisa honom, för att han icke må göra det en gång till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Tag din vän i förhör; ty ofta är förtalet framme. Och tro icke allt vad som säges.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Mången förgår sig, men utan ond avsikt. Och vem har icke syndat med sin tunga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Tag din nästa i förhör, innan du talar strängt till honom, och lämna rum för den Högstes lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Ingen vishet finnes utan Herrens fruktan, och till visheten hör alltid att man gör efter lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Men vishet är ej att vara förfaren i ondska, och syndares rådklokhet är icke förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Mången gång är vishet styggelse, och mången dåre har föga av ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Bättre är att vara gudfruktig, om ock underlägsen i insikt, än att vara rik på förstånd, men tillika överträda lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Mången gång är skarpsinnig klokskap orättfärdig, och mången handlar vrångt för att bringa rätten i dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Mången går nedböjd i sorgdräkt, medan hans inre är fullt av svek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Han hänger huvudet och låtsar sig vara döv på ena örat, men när han är obemärkt, överraskar han dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Och om han hindras att försynda sig mot dig av brist på kraft, skall han dock göra dig illa, så snart han får tillfälle.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'På utseendet kännes mannen, och den vise kännes på sitt sätt att skicka sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Klädseln och skrattet och gången, de röja vem och hurudan en människa är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Mången gång sker tillrättavisning i otid, och mången gång är den klok, som tiger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Långt bättre är att tillrättavisa än att bära agg; och den som erkänner sitt fel, han bliver besparad mycket ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Lik en snöpt man som trånar efter att beröva en jungfru hennes oskuld är den som vill skipa rätt genom våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Mången som tiger befinnes vara vis, men mången gör sig förhatlig genom mycket ordande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Mången tiger, eftersom han intet har att svara; men mången tiger, därför att han vet sin tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'En vis man tiger, till dess tiden är inne; men skrävlaren och dåren taga ej den rätta tiden i akt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Den som har överflöd på ord bliver avskydd, och den som uppträder med maktspråk, han gör sig förhatlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Mången gång ligger lycka i en människas olycka, och av vinning bliver mången gång förlust.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mången gåva bliver för givaren utan gagn, men mången gåva vedergälles dubbelt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'För mången leder hans anseende till förödmjukelse, men mången får ur förnedringen upplyfta huvudet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Mången köper mycket för en ringa penning, men får dock betala det sjufalt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Den vise gör sig omtyckt genom sitt tal, men dårars fagra ord äro förspillda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'En dåres gåva länder dig icke till gagn, ty med giriga blickar ser han efter vedergällning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Knappa äro hans gåvor, men många hans hårda ord, och han spärrar upp munnen såsom en utropare. I dag lånar han ut, i morgon kräver han igen; förhatlig är en sådan människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Dåren säger: »Jag har ingen vän, och jag får ingen tack för mina välgärningar. De som äta mitt bröd hava onda tungor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Huru ofta och av huru många bliver ej en sådan förhånad!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Bättre är att falla på marken än att komma på fall genom tungan; på det sättet komma de onda på fall med hast.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Ord i orätt stund röja en obehaglig människa; i de ouppfostrades mun äro sådana ord vanliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Ett tänkespråk från en dåres mun vinner intet bifall, ty han uttalar det icke i rätta stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Mången hindras av sin fattigdom ifrån att synda; så slipper han att få sin vila störd av samvetskval.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Mången bereder sitt eget fördärv genom blyghet, ja, fördärvar sig själv genom att skicka sig såsom en fåkunnig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Mången giver för skams skull löften åt en vän och skaffar sig därmed oförskyllt en fiende i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'En svår fläck på en människa är lögnen; i de ouppfostrades mun är den vanlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Bättre är en tjuv än en som har till vana att ljuga; men båda skola de få fördärv till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'En lögnaktig människas sinnesart är en vanheder för henne, och hennes skam följer henne beständigt åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Den vise främjar sitt eget bästa genom sina ord, och en förståndig man vinner ynnest hos de store.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'För den som brukar sin jord stiger säden i bingen, och den som äger stormäns ynnest, han får orättfärdighet överskyld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Skänker och gåvor förblinda de vises ögon, och såsom en munkavle hindra de dem att tala bestraffande ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Dold vishet och förborgad skatt, vartill gagna de båda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Bättre är den som döljer sin dårskap än den som döljer sin vishet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Min son, har du syndat, så gör det icke mer, och bed om förlåtelse för vad du förut har brutit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Fly för synden såsom för en orm; ty om du kommer den för nära, så stinger den dig. Dess tänder äro såsom lejontänder, och de dräpa människors själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'All orättfärdighet är såsom ett tveeggat svärd; för det sår som den giver finnes ingen läkedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Tyranni och våld föröda rikedom; på det sättet bliver den övermodiges hus förött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Bönen från den fattiges mun når fram till Herrens öron, och med hast får han sin rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Den som hatar bestraffning, han är inne på syndarens väg; men den som fruktar Herren, han omvänder sig av hjärtat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'På långt håll gör sig storskrävlaren känd, men den förståndige märker när han tager miste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Den som bygger sitt hus med andras penningar, han är lik en som samlar sten till sin egen gravhög.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'De orättfärdigas hop är såsom en packe blår, och deras ände är att förtäras av eldslåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Syndarens väg är jämn och väl stenlagd, men vid dess slut öppnar sig dödsrikets djup.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Den som håller lagen, han är herre över sitt sinne; och fulländningen av Herrens fruktan är visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Den som icke är klok, han kan icke mottaga tuktan, men det finnes en klokhet som är rik på bittra följder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'En vis mans kunskap väller fram såsom en översvämmande flod, och hans rådklokhet är såsom en flödande källa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'En dåres inre är såsom ett sprucket krus; ingen kunskap kan han hålla kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Om den förståndige får höra ett vist ord, så prisar han det och fogar ett annat därtill. Om den lättfärdige hör det, så misshagar det honom, och han kastar det bakom ryggen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Dårens tal är såsom en börda på en vandring, men på den insiktsfulles läppar bor behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Till den förståndiges mun lyssnar man gärna i församlingen, och hans ord begrundar man i sitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Lik ett hus som ligger i spillror är visheten för dåren, och den oförståndiges kunskap visar sig i ord utan mening.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Såsom bojor om fötterna gäller tukt för de oförnuftiga, och såsom handbojor på högra handen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Dåren brister ut i gapskratt, men en klok man småler på sin höjd helt stilla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Såsom ett gyllene smycke aktas tukt av den förståndige, och såsom en prydnad på högra armen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Dåren skyndar med ilande steg in i ett hus, men den väl förfarne dröjer försynt vid ingången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Den vettlöse spejar från dörren in i huset, men den väluppfostrade stannar därutanför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Att lyssna vid dörren visar brist på uppfostran, och den förståndige skulle känna sådant såsom tryckande skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Pratmakarnas läppar orda om det som icke angår dem, men de förståndiga väga sina ord på våg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Dårarna hava hjärtat i munnen, men de visas hjärta är deras mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'När den ogudaktige förbannar vedersakaren, då förbannar han sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Örontasslaren sätter fläckar på sig själv, och han gör sig hatad där han bor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Den late kan liknas vid en smutsad sten; envar visslar åt den för dess föraktlighets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Den late kan liknas vid en gödselklump; envar som tager upp den skakar smutsen av handen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Det är en skam för en fader att hava fött en vanartig son, och att få en sådan dotter, det för skada med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'En förståndig dotter får sig en man, men den som drager skam över de sina, hon bliver sin fader till sorg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Den fräcka drager skam över både sin fader och sin man och bliver föraktad av båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Såsom musik i sorgetid är att tala i orätt stund; men aga och tukt äro alltid vishet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Att undervisa en dåre är såsom att limma ihop en lerkruka, såsom att väcka en sovande ur djup sömn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Att tala för en dåre är såsom att tala för en som håller på att somna; när man har slutat, säger han: »Vad var det?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Gråt över en död, ty hans ljus är slocknat; gråt ock över en dåre, ty hans förstånd är slocknat. Gråt mindre bittert över en död, ty han har kommit till ro; men dårens liv är värre än döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Sorgen efter en död varar i sju dagar, men över en dåre och en ogudaktig i alla hans livsdagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Tala icke mycket med den oförnuftige, och sök ej den fåkunniges umgänge. Tag dig till vara för honom, så att du ej ådrager dig förtret. Då skall du ej heller bliva nedsmutsad, när han skakar på sig. Undvik honom, så skall du finna ro och slippa att plågas av hans galenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Vad finnes, som är tyngre än bly? Vilket namn skulle det väl bära annat än »dåre»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Sand och salt och en klump järn, sådant är lättare att bära än en fåkunnig människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Ett bjälkverk, infogat i en byggnad, går icke isär vid en jordstöt. Sådant är det sinne som har sitt fäste i välbetänkta rådslag; i farans stund rädes det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Ett sinne som stadigt vilar på klok eftertanke, det är såsom sandblandad puts på en slät vägg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Grus som ligger fritt uppe på en hög plats kan icke stå emot vinden. Sådant är det sinne som är försagt genom dåraktigt tänkesätt; det kan icke stå emot någon förskräckelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'En stöt i ögat driver fram tårar, en stöt mot hjärtat framkallar smärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Kastar man sten på fåglar, så skrämmer man bort dem; och skymfar man en vän, så upplöser man vänskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Om du drager ditt svärd mot en vän, så uppgiv ej hoppet; ty återgång är möjlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Om du upplåter din mun mot en vän, så var icke rädd; ty förlikning är möjlig. Men skymf och övermod, röjd hemlighet och svekfullt angrepp — är sådant på färde, då flyr var vän sin kos.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Sök att vinna förtroende hos din nästa, medan han är fattig, på det att du må få dela hans överflöd, när det går honom väl. Stanna kvar hos honom i nödens tid, så skall du, när han får ärva, dela arvet med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Före elden kommer dunst från ugnen och rök; så gå smädelser före blodsutgjutelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Jag vill icke blygas för att skydda min vän, och jag vill ej gömma mig undan för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Och om något ont skulle hända mig för hans skull, så skall envar som får höra därom taga sig i akt för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'O Herre, min fader, du som härskar över mitt liv, låt mig icke komma på fall genom dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Ack att ett gissel vore berett för min tanke och ett vishetens tuktoris för mitt hjärta, så att skonsamhet icke övades, när jag felar, eller överseende, när jag syndar med dem!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Då skulle icke mina felsteg bliva: så många och mina synder så talrika. Då skulle jag ej komma på fall i mina motståndares åsyn, och min fiende skulle icke få glädja sig över mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'O Herre, min fader och mitt livs Gud, giv mig icke till pris åt deras rådslag. Låt icke mina ögon se efter vad högt är,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'och håll begärelsen borta ifrån mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Låt ej bukens begär och köttets lust få makt över mig, och låt mig icke hemfalla åt ett skamlöst sinnelag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Hören, I barn, om munnens tukt; den som aktar härpå skall icke låta sig fångas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Genom sina läppar snärjes syndaren; smädaren och den övermodige komma genom dem på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Vänj icke din mun vid att svärja, och tag ej till vana att nämna den Heliges namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'En tjänare som man oavlåtligen måste tukta bliver ju aldrig fri ifrån blånader; så bliver den som ständigt svär och nämner det namnet aldrig någonsin ren från synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'En man som ofta svär begår mycken synd, och plågan skall icke vika från hans hus. Om han försyndar sig, så vilar hans skuld på honom; och frågar han ej därefter, så har han ådragit sig dubbel skuld. Och om han svär i onödan, så skall han ej bliva ostraffad, nej, hemsökelser i mängd skola drabba hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Det finnes ett talesätt som är att akta lika med döden. Må det aldrig bliva hört i Jakobs arvedel! Nej, allt sådant må vara fjärran ifrån de fromma, och de må icke inveva sig i synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Vänj icke din mun vid ohyfsad råhet, ty sådan för med sig syndiga ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Tänk på din fader och din moder, när du sitter i en krets av stormän, så att du icke glömmer dem i dessas närvaro och genom din onda vana bevisar dig såsom en dåre. Du kunde då komma att önska att du aldrig hade blivit till och förbanna den dag då du föddes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'En människa som vänjer sig vid smädligt tal låter icke tukta sig under hela sitt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Två slags människor begå mycken synd, och det tredje drager över sig vrede. Likt en brinnande eld är ett sinne som är upptänt av begär; det slocknar icke, förrän det har blivit förtärt. En människa som övar otukt på sitt eget kött hör icke upp, förrän elden har förbränt henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'En lösaktig människa smakar allt bröd sött; hon tröttnar icke, förrän hennes liv är till ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'En man som går åstad för att begå äktenskapsbrott säger vid sig själv: »Vem ser mig? Mörker omgiver mig, och väggarna skyla mig, och ingen ser mig; vad har jag att frukta? Mina synder skall den Högste icke komma ihåg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Människoögon allenast är vad han fruktar. Men han betänker icke att Herrens ögon äro tiotusenfalt klarare än solen, och att de blicka ned på människors alla vägar och skåda in i de hemligaste vrår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Allting är känt av honom, redan innan det blev till, så ock sedan det har blivit fullbordat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'En sådan man skall få sitt straff på gatorna i staden, och han skall bliva gripen där han minst förmodar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Likaså går det ock en kvinna som har övergivit sin make och skaffar en arvinge i huset med en främmande man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Ty först och främst har hon varit ohörsam mot den Högstes lag; vidare har hon förbrutit sig mot sin man; för det tredje har hon i otukt begått äktenskapsbrott och med en främmande man skaffat barn i huset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'En sådan kvinna skall föras fram inför menigheten, och över hennes barn skall hemsökelse komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Hennes barn skola icke slå rot, och hennes grenar icke bära frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Det minne hon efterlämnar skall förbannas, och hennes skam skall icke utplånas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Och så skola de efterlevande lära sig att intet är bättre än Herrens fruktan, och intet ljuvare än att akta på Herrens bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Visheten prisar sig själv och berömmer sig mitt ibland sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'I den Högstes församling upplåter hon sin mun och berömmer sig inför hans härskara:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Jag utgick från den Högstes mun, och såsom en dimma övertäckte jag jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Jag tog min boning i himlahöjderna, och min tron stod på en molnpelare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Jag allena genomfor himlarunden och hade min väg genom avgrundsdjupet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Bland havets vågor och över hela jorden, bland alla folk och folkslag härskade jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Hos alla dessa sökte jag en vilostad. I vems arvedel skulle jag väl finna ett hem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Då fick jag en befallning från alltings skapare; han som hade skapat mig lät mig finna en varaktig boning. Han sade: »Slå upp din boning i Jakob; i Israel skall du hava din arvedel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Före all tid, i begynnelsen skapade han mig, och aldrig någonsin skall jag upphöra att finnas till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'I det heliga tabernaklet gjorde jag tjänst inför honom; likaså fick jag en fast boning på Sion.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'I den stad som han älskar lät han mig sammalunda finna ro, och i Jerusalem är nu mitt herradöme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Och jag slog rot hos ett ärat folk, i Herrens ägolott, i hans arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Jag sköt i höjden såsom en ceder på Libanon, såsom en cypress på Hermons berg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Jag sköt i höjden såsom en palm i Engedi, såsom en rosenbuske i Jeriko, såsom ett skönt olivträd på fältet; såsom en lönn sköt jag i höjden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Jag spridde doft såsom kanel och välluktande aspalatus; såsom finaste myrra utsände jag vällukt, såsom galban, sjönagel och stakte och såsom rökelsemolnet i tabernaklet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Jag sträckte ut mina grenar såsom en terebint; präktiga och sköna voro mina grenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Jag slog ut i fägring såsom ett vinträd, och mina blommor gåvo präktig frukt i myckenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Så kommen då till mig, I som haven åstundan efter mig, och matten eder med mina håvor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ty att tänka på mig är sötare än honung, och att hava mig till besittning är förmer än renaste honung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'De som äta av mig, de skola hungra efter mer, och de som dricka av mig skola törsta efter mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Den som lyssnar till mig, han skall icke komma på skam, och de som beflita sig om mig skola icke synda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Allt detta gäller Guds, den Högstes, förbunds bok, den lag som Moses gav åt oss, en arvedel för Jakobs menighet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'den lag som låter vishet flöda såsom Fison och såsom Tigris i förstlingsfruktens tid;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'som låter insikt rikligen strömma såsom Eufrat och såsom Jordan vid skördetiden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'som låter tukt stråla fram såsom ljuset, såsom Geon vid tiden för fruktskörden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 28, 'Den förste lärde icke känna henne till fullo, ej heller den siste har utrannsakat henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 29, 'Ty djupare än havet är hennes tanke, ja, än det stora havsdjupet hennes rådslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 30, 'Men jag var såsom en kanal från en flod och såsom en vattenledning som ledde ut i lustgården.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 31, 'Jag sade: »Jag vill vattna min örtagård och rikligen fukta mina trädgårdssängar.» Men se, då blev kanalen för mig till en flod, och min flod blev till ett hav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 32, 'Alltfort vill jag låta tukt stråla fram såsom morgonrodnaden och låta den lysa vida omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 33, 'Alltfort vill jag låta min lära strömma fram såsom profetiskt tal och lämna den efter mig till alla kommande släktled.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 34, 'Så sen då att jag icke har mödat mig för mig själv allena, utan för alla dem som fara efter visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Tre ting behaga mig väl och äro sköna inför Herren och inför människor: endräkt mellan bröder och vänskap mellan grannar, och att man och hustru komma väl överens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Men tre slags människor hatar min själ, och jag harmas högeligen över att sådana skola få leva: en fattig som är övermodig, en rik som är en lögnare och en oförnuftig åldring som är en äktenskapsbrytare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Har du underlåtit att samla i din ungdom, huru skulle du då kunna finna något på din ålderdom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Huru väl anstår det icke gråhårsman att fälla rättsutslag och gamla män att veta råd!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Huru väl anstår icke vishet åldringar och eftertanke och rådklokhet män i ärad ställning!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Rik erfarenhet är åldringars ärekrans, och Herrens fruktan är deras berömmelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Nio ting som hava kommit i mina tankar prisar jag i mitt hjärta, och om det tionde vill jag tala med min tunga: en man som har glädje av sina barn; den som, medan han lever, får se sina fienders fall;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'säll är ock den som får levas samman med en förståndig hustru, den som icke felar med sin tunga och den som ej behöver tjäna en som icke är honom värdig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'säll är den som har undfått förstånd och den som får tala för lyssnande öron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Huru stor är icke den som har funnit visheten! Dock är han ej förmer än den som fruktar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Herrens fruktan övergår allt annat; den som håller fast vid den, vem kan han förliknas vid?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Vilka sår som helst, blott icke hjärtesår! Vilken ondska som helst, blott icke kvinnoondska!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Vilken hemsökelse som helst, blott icke hemsökelse genom ovänner! Och vilken hämnd som helst, blott icke mina fienders hämnd!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Intet huvud är farligare än ormens huvud, och ingen vrede är värre än fiendens vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Hellre ville jag bo tillsammans med ett lejon eller en drake än bo samman med en ond kvinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'En kvinnas ondska förvandlar hennes utseende och gör hennes uppsyn mörk såsom en björns.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'I kretsen av sina grannar sätter hennes man sig ned, och ofrivilligt suckar han bittert.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Ringa är all elakhet i jämförelse med en kvinnas elakhet. Må syndarens lott drabba en sådan!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Såsom en sandig backe för en gammal mans fötter är en munvig hustru för en stillsam man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Låt ej förleda dig av en kvinnas skönhet, och fatta icke åtrå till en kvinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Vrede och oförsynthet och stor smälek vållas av att en hustru försörjer sin man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Nedslaget sinne och dyster uppsyn och hjärtesår vållas av en ond hustru. Maktlösa händer och vacklande knän vållas av en hustru som icke gör sin man lycklig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Med en kvinna tog synden sin begynnelse, och för hennes skull måste vi alla dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Låt icke vattnet taga sig fritt lopp, och låt ej en ond hustru få någon makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Om hon icke vill gå vid din hand, så skär av bandet mellan dig och henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Säll är den man som har en god hustru; hans dagars tal varder fördubblat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'En dugande hustru gör sin man glädje, och han får fullborda sina år i frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'En god hustru är en god lott, och hon kommer på dens lott, som fruktar Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Evad han är rik eller fattig, är hans hjärta förnöjt, och hans uppsyn är alltid glad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'För tre ting rädes mitt hjärta, och för det fjärde fruktar jag storligen: förtal i staden och folkskockning och falsk angivelse - alltsammans värre än döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Hjärtesorg och grämelse vållas av en kvinna som är svartsjuk på en annan, så ock av en stingande tunga som omtalar saken för alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'En ond hustru är såsom ett bångstyrigt par oxar; att taga en sådan är såsom att fatta i en skorpion.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'En drucken kvinna väcker stor harm, och hon döljer icke sin skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'En kvinnas lösaktighet röjes av hennes ögonkast och märkes på hennes blickar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Håll sträng vakt över en tuktlös dotter; finge hon för stor frihet, kunde hon bruka den till självsvåld,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Följ med vaksamhet en kvinna som har oblyga ögon, och förvånas icke, om hon förbryter sig mot dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Såsom en törstig vandrare öppnar sin mun och dricker av närmaste vatten, hurudant det än är, så sätter hon sig ned framför var tältplugg och öppnar sitt koger för var pil.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'En hustrus behag bereder hennes man fägnad, och hennes förstånd fyller hans ben med märg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'En tystlåten hustru är en Herrens gåva, och ett väl tuktat sinne kan med intet betalas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'En blygsam hustru är en ljuvlighet utan mått, och ingenting kan uppväga ett återhållsamt sinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Lik solen, när den går upp på Herrens himmel, är en god hustrus skönhet i hennes välordnade hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Lik lampan som skiner på den heliga ljusstaken är ansiktets skönhet på en välväxt gestalt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Lika gyllene pelare på fotstycken av silver äro välformade ben på stadiga hälar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Över två ting är mitt hjärta bedrövat, och över det tredje gripes jag av harm: när en krigsman får lida nöd till följd av fattigdom, och när förståndiga män bliva ringaktade, och när någon vänder om från rättfärdighet till synd; en sådan må Herren bereda för svärdet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'För penningars skull hava många syndat, och den som far efter mycket vänder blicken från rätta hållet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Såsom en plugg tränger in i fogen mellan stenar, så skjuter synden sig in mellan säljaren och köparen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Den som icke med allvar håller fast vid Herrens fruktan, hans hus bliver med hast omstörtat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'När ett såll skakas, stannar orenligheten kvar; likaså stannar smutsen hos människan kvar i hennes tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Såsom lerkärl prövas i ugnen, så lär man känna en människa genom hennes tänkesätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Frukten röjer trädets skötsel, likaså tänkandet en människas sinnelag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Prisa ingen, förrän du har hört hans tankar, ty på det sättet lär man känna människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Om du far efter rättfärdigheten, så skall du vinna den och ikläda dig den såsom en praktskrud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Fåglarna slå ned bland sina likar, och sanningen vänder åter till dem som öva den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Såsom lejonet lurar på sitt byte, så lurar synden på dem som göra vad orätt är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Vad den gudfruktige talar är alltid vishet, men den oförnuftige skiftar såsom månen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Var sparsam med tiden, när du är bland oförståndiga människor, men dröj länge kvar bland de eftertänksamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Dårars tal är en styggelse, och deras skratt är en syndig utsvävning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Storsvärjarens tal kommer håren att resa sig, och när sådana kiva, måste man stoppa till öronen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Kiv mellan övermodiga vållar blodsutgjutelse, och deras otidigheter äro leda att höra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Den som röjer hemligheter förlorar allt förtroende; han finner aldrig en hjärtevän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Älska din vän, och visa dig trofast mot honom; men har du röjt hans hemligheter, så löp ej vidare efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Ty såsom man dödar sin fiende, så har du dödat vänskapen mellan dig och din broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Och såsom man släpper en fågel ur handen, så har du låtit din broder fara och kan ej mer infånga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Skynda icke efter honom, ty han är redan långt borta; han har kommit undan likasom hinden ur snaran.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Ty ett sår kan man förbinda, och efter smädelse är förlikning möjlig, men för den som har röjt hemligheter finnes ej något hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Den som blinkar med ögonen, han stämplar ont, och ingen kan fria sig för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'I din närvaro är han söt i munnen och kan icke nog beundra vad du säger, men efteråt ändrar han sitt språk och gör så, att man stöter sig på dina ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Mycket hatar jag, men intet så mycket som en sådan; också Herren hatar en dylik människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Den som kastar en sten i höjden, han träffar sitt eget huvud, och ett försåtligt hugg sårar åt olika håll.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Den som gräver en grop, han faller själv däri, och den som lägger ut en snara, han fångas själv i den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Om någon gör något ont, så faller det tillbaka på honom själv, men han förstår icke varifrån det kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'De övermodiga håna och smäda, men straffet lurar såsom ett lejon på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'De som glädjas över de frommas fall, de skola fångas i snaran, och grämelse skall förtära dem, förrän de dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Den som hämnas skall få erfara Herrens hämnd; hans synder skall Herren tillräkna honom utan försköning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Förlåt din nästa den orätt han har gjort; då skall ock du få tillgift för dina synder, när du beder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'En människa behåller vrede mot en annan, och ändå begär hon läkedom av Herren!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Med en människa, som är hennes like, har hon intet förbarmande, och ändå beder hon om förlåtelse för sina egna synder!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Om den som själv är kött behåller agg mot andra, vem skall då bringa försoning för hans synder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Tänk på änden, och hör upp med att hysa fiendskap, på förgängelse och död, och förbliv vid budorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Tänk på budorden, och hys icke agg mot din nästa, på den Högstes förbund, och överse med andras fel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Avhåll dig från strid, så skall du synda mindre; ty en häftig människa upptänder strid,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'och en syndare vållar split mellan vänner och utsår förtal bland dem som leva l frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Ju mer bränsle där är, dess häftigare brinner det; och ju större stridskrafterna äro, dess hetare bliver striden. Ju mäktigare någon är, dess starkare bliver hans förtörnelse; och ju rikare någon är, dess högre stiger hans vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'En tvist som hastigt bryter lös upptänder eld, och en strid som hastigt bryter lös kommer blodsutgjutelse åstad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Om du blåser på en gnista, så flammar den upp, och om du spottar på den, så slocknar den; och det ena såväl som det andra kommer från din mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Förbannen örontasslaren och den tvetungade, ty många som levde i frid hava de störtat i fördärvet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Tredje mans tunga har kommit många på fall och drivit dem ifrån folk till folk. Fasta städer har hon rivit ned, och mäktiga herrars hus har hon omstörtat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Tredje mans tunga har jagat dugande hustrur från deras hem och berövat dem deras mödors lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Den som aktar på henne, han finner aldrig någon ro och får icke bo i lugn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Gisselslag framkalla blånader, men tungans slag krossa ben.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Många hava fallit för svärdsegg, dock icke så många som för tungans skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Säll är den som har blivit beskärmad för henne, och som icke har råkat ut för hennes raseri, som icke har måst släpa på hennes ok och icke har varit bunden med hennes fjättrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Ty hennes ok är ett ok av järn, och hennes fjättrar äro koppar-fjättrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'En ond död är den död som hon tillskyndar; ja, själva dödsriket är att föredraga framför henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Över de fromma får hon dock aldrig någon makt, och de skola icke brännas av hennes låga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'De som övergiva Herren, de falla i hennes våld; i dem får hon bränsle, så att hon icke slocknar. Hon slappes lös mot dem såsom ett lejon, och såsom en panter sliter hon sönder dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Upp, hägna in dina ägor med törnhäck, och sätt dörr och rigel för din mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Sätt lås för ditt silver och ditt guld, och skaffa dig våg och vikt för dina ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Var på din vakt, så att du icke slinter genom tungan och faller omkull i dens åsyn, som ligger i försåt för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 1, 'Den som vill öva barmhärtighet, han lånar åt sin nästa; och den som stöder honom med sin hand håller buden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 2, 'Låna åt din nästa, när han är i nöd; och betala igen åt din nästa på utsatt tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 3, 'Stå fast vid ditt ord, och visa dig trofast mot honom, så skall du städse få vad du behöver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 4, 'Mången anser ett lån för ett fynd och bereder så den förtret, som hjälpte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 5, 'Till dess han får det, kysser han sin nästas hand och talar i ödmjuk ton om hans penningar. Men när tiden att betala är inne, då gör han uppskov och betalar med jämrande ord och skyller på dåliga tider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 6, 'Kan han betala, får den andre med knapp nöd hälften igen och måste räkna till och med det såsom ett fynd. Kan han det icke, har han berövat den andre hans penningar, och denne har oförskyllt fått sig en fiende i honom. Förbannelser och skymford giver han i betalning, och i stället för med ära betalar han med vanheder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 7, 'För sådan ondskas skull draga sig många undan; de frukta för att oförskyllt bliva berövade vad de äga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 8, 'Men gäller det en betryckt, så hav tålamod med honom, och låt honom icke vänta på din välgärning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 9, 'Tag dig an den fattige för budordets skull, och låt honom icke i sin fattigdom gå tomhänt bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 10, 'Förlora hellre ditt silver på en broder och en vän, än du låter det rosta bort under stenen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 11, 'Samla din skatt efter den Högstes bud, så skall den gagna dig mer än guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 12, 'Slut in välgörenhet i dina förrådskamrar, så skall den rädda dig ur all ofärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 13, 'Bättre än en stark sköld och än ett fast spjut skall den strida för dig mot ovännen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 14, 'Den som är god går i borgen för sin nästa, men den som har mist all skam lämnar honom utan hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 15, 'Förgät icke en borgensmans välgärningar; han har ju givit sig själv för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 16, 'Syndaren föröder sin borgensmans egendom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 17, 'och den som är otacksam i sitt sinne lämnar sin räddare i sticket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 18, 'Borgen har störtat många i fördärvet, som levde i välmåga, och vräkt dem omkring såsom vågen i havet. Mäktiga män har den drivit från hus och hem, så att de hava måst irra omkring bland främmande folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 19, 'Syndaren råkar i borgensförbindelser, och den som far efter vinning, han råkar inför domstol.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 20, 'Tag dig an din nästa, allt efter vad du förmår, men var på din vakt, så att du ej själv råkar illa ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 21, 'Det viktigaste för livet är mat och dryck och kläder och hus till att skyla nakenheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 22, 'Bättre är den fattiges liv under eget brädskjul än läckra rätter i främmande hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 23, 'Har du litet eller mycket, låt dig nöja därmed; så skall du slippa att höra dig skymfas för din härkomsts skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 24, 'Det är ett uselt liv att gå från hus till hus; och där man lever såsom främling, får man ej öppna sin mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 25, 'Utan tack får du bjuda på mat. och dryck, och därtill får du höra sårande ord:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 26, '»Träd hitfram, främling, red till bordet, och om du har något, så giv mig att äta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 27, '»Gå din väg, främling, och giv rum för förnämt folk. Min frände har kommit på besök; här måste övas gästvänskap.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 28, 'Tungt är sådant för en man med förstånd: bannor för härkomsts skull och hårda ord av borgenärer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 1, 'Den som älskar sin son, han spar icke på riset, på det att han till slut må få glädje av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 2, 'Den som håller sin son i tukt, han får gagn av honom, och bland sina bekanta skall han få berömma sig av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 3, 'Den som undervisar sin son kommer att väcka avund hos sin fiende, och inför sina vänner får han fröjda sig över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 4, 'När en sådan fader har gått hädan, är det såsom vore han ej död, ty han har lämnat efter sig en som är honom lik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 5, 'Medan han levde, såg han honom och gladdes; och när han gick hädan, kände han ingen bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 6, 'För sina fiender har han lämnat efter sig en hämnare och åt sina vänner en som återgäldar välgärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 7, 'Den som klemar med sin son plåstrar om hans skråmor, och så snart han höres gråta, fylles han av ängslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 8, 'En häst som icke tämjes bliver bångstyrig, och en son som ej hålles efter bliver självsvåldig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 9, 'Kela med din son, och han skall bliva en skräck för dig; lek tillsammans med honom, och han skall göra dig sorg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 10, 'Glamma ej med honom, på det att du icke sedan må bedrövas med honom och på sistone få »ömma tänder» för hans skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 11, 'Låt honom ej få sin vilja fram, medan han är ung, och överse icke med hans fel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 12, 'Böj hans nacke, medan han är ung, och gör hans länder mjuka, medan han är liten. Han kunde annars bliva styvsint och visa dig olydnad, och så kunde du få komma att utstå hjärtekval.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 13, 'Tukta din son, och håll honom till arbete, för att han ej i sin vanartighet må begå något anstötligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 14, 'Bättre vara fattig, men frisk och stark, än vara rik, men plågad av sjukdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 15, 'Hälsa och välbefinnande är bättre än allt guld i världen, och en stark kropp är bättre än omätlig rikedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 16, 'Ingen större rikedom finnes än kroppens hälsa, och ingen glädje övergår hjärtats glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 17, 'Bättre är att dö än att leva ett kvalfyllt liv, bättre är den eviga ron än långvarig sjukdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 18, 'Läckerheter, uppdukade inför den som ej kan öppna munnen, äro såsom maträtter, framsatta vid en grav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 19, 'Vad nytta har en avgudabild av offret? Den kan ju varken äta eller känna lukt. Så är det ock med den som bliver hemsökt av Herren:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 20, 'han ser på maten och suckar, lik den snöpte som omfamnar en jungfru och suckar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 21, 'Överlämna dig icke åt sorgen, och plåga ej dig själv med ditt grubbel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 22, 'Glädje i hjärtat är liv för en människa, och fröjd förökar en mans dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 23, 'Gör dig inga betänkligheter, utan uppmuntra ditt hjärta; och håll sorgen långt borta ifrån dig. Ty sorgen har dödat många, och den har ingen nytta med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 24, 'Avund och vrede förkorta livet, och bekymmer gör gammal i förtid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 25, 'Den som är frikostig och fägnar sig åt läckra rätter, han sörjer ock för att mat icke skall fattas honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 1, 'Vaka för rikedoms skull tär på hullet, och bekymmer för sådan driver sömnen på flykten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 2, 'Näringsbekymmer förjaga slummern, likasom svår sjukdom håller människan vaken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 3, 'Den rike mödar sig, under det han hopar ägodelar; och när han vilar sig, mättar han sig med sina läckerheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 4, 'Den fattige mödar sig och har därvid knappt sitt uppehälle; och när han vilar sig, infinner sig nöden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 5, 'Den som älskar guldet går icke fri ifrån synd, och den som jagar efter penningar, han far vilse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 6, 'Många hava kommit på fall för guldets skull; ja, deras fördärv stod plötsligt mitt framför dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 7, 'Ett giller är guldet för dem som bliva dårade därav, och varhelst en oförnuftig finnes, fångas han därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 8, 'Säll är den rike som är befunnen ostrafflig, och som icke har låtit sig förledas av guldet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 9, 'Var finnes han, så att vi få prisa honom säll? Ty något underbart har han gjort bland sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 10, 'Vem blev prövad i sådant och befunnen fullkomlig? Han vore berömmelse värd. Var finnes den som ej förbröt sig, fastän han hade kunnat det, den som ej gjorde vad ont var, fastän han hade förmått det?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 11, 'Den mannens lycka skall fast bestå, och om hans välgörenhet skall man förtälja i församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 12, 'Sitter du vid ett rikt bord, så gapa icke över vad där bjudes, och säg ej: »Här var mycket att få!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 13, 'Betänk att ett missunnsamt öga är ett ont ting. Intet har blivit skapat, som är värre än ögat; fördenskull måste det fälla tårar på vart ansikte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 14, 'När någon annan ser efter något, så sträck ej din hand därefter, och stöt icke ihop med honom i fatet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 15, 'Bedöm din nästas önskningar efter dina egna, och tänk dig noga för i var sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 16, 'Ät såsom en människa av det som är framsatt för dig, och ät ej glupskt, på det att du icke må väcka motvilja.\"');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 17, 'Var den förste som slutar, såsom höviskt är; och var ej omättlig, på det att du icke må väcka anstöt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 18, 'Och om du sitter i lag med flera, så sträck icke ut din hand före de andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 19, 'Med huru litet låter icke den väluppfostrade sig nöja! Han slipper ock att ligga och pusta på sitt läger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 20, 'Sömnlöshet, äckel och bukrev, av sådant plågas en omättlig man. Man får sund sömn, när magen är måttligt fylld; bittida står man upp, och med friska själskrafter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 21, 'Men om du har fått för mycket av läckerheterna, gå då och kasta upp, så skall du få lugn igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 22, 'Hör mig, min son, och förakta mig icke, så skall du på sistone få sanna mina ord. Var flink i allt vad du företager dig, så skall du aldrig träffas av någon sjukdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 23, 'Den som håller ett gästfritt bord, han bliver prisad av alla, och vittnesbördet om hans förträfflighet är sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 24, 'Över den som håller ett njuggt bord knorrar man i hela staden, och vittnesbördet om hans njugghet är riktigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 25, 'Var icke en hjälte i att dricka vin, ty många äro de\"som vinet har fördärvat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 26, 'Ugnen prövar stålet, sedan det har doppats i vatten; likaså prövar vinet hjärtan, när övermodiga män strida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 27, 'Vin är såsom liv för människan, om man dricker det i tillbörligt mått. Hurudant bliver väl livet för den som är utan vin? Det är ju skapat till glädje för människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 28, 'En fröjd för hjärtat och en glädje for sinnet är vinet, när det drickes i rätt tid och i lagom mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 29, 'Men bitterhet i sinnet vållar vinet, när det drickes i myckenhet, under upphetsning och slagsmål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 30, 'Ruset ökar dårens hetsighet och driver honom till försyndelser; det försvagar hans kraft och ådrager honom därtill sår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 31, 'Gå icke till rätta med din nästa vid ett dryckeslag, och visa honom ej förakt, när han är upprymd. Säg intet skymfande ord till honom, och ansätt honom icke med skuldfordran.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 1, 'Har man valt dig till värd, så förhäv dig icke; var bland gästerna såsom en av dem. Sörj först för dem, och sätt dig sedan själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 2, 'När du har fullgjort ditt värv, så intag själv din plats, för att sedan få glädja dig för de andras skull och för de goda anordningarna mottaga ärekransen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 3, 'Tala, du åldring, ty det höves dig, med noggrann insikt, men hindra ej musiken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 4, 'Där öronfägnad bjudes må du ej låta ditt tal flöda, och bär icke fram din vishet i otid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 5, 'Såsom en signetsten av karbunkel på ett smycke av guld är skön musik vid ett festligt lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 6, 'Såsom en signetsten av smaragd i en infattning av guld är vacker sång till sött vin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 7, 'Tala, du yngling, när det är av nöden, två gånger högst, om du bliver tillspord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 8, 'Fatta dig kort, säg mycket i få ord; visa att du kan tiga, om du också vet något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 9, 'Är du bland stormän, sök då ej att hålla dig lika med dem; och när en annan talar, så prata icke vitt och brett,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 10, 'Före dundret kommer ljungelden farande, och före den blygsamme går bevågenheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 11, 'Bryt upp i tid, och dröj icke bland de sista; skynda dig hem, och glöm dig ej kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 12, 'Därhemma må du förlusta dig och göra vad dig lyster, men försynda dig icke med övermodigt tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 13, 'Och prisa under allt detta din Skapare, honom som rikligen mättar dig med sitt goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 14, 'Den som fruktar Herren tager emot tukt, och de som bittida söka honom, de skola vinna hans välbehag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 15, 'Den som forskar i lagen, han skall finna mättnad i den, men för skrymtaren bliver den till en stötesten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 16, 'De som frukta Herren finna det rätta och låta domslut lysa fram såsom ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 17, 'En syndig man avböjer tillrättavisning, och efter eget behag finner han ut rättsgrunder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 18, 'En klok man lämnar aldrig en tanke obeaktad, men främlingen och den övermodige sky icke för något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 19, 'Gör intet utan eftertanke; och när du så har gjort något, ångra dig då icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 20, 'Gå icke på en förfallen väg, på det att du ej må snäva på steniga ställen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 21, 'Känn dig icke säker ens på en jämn väg;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 22, 'tag dig till vara till och med för dina egna barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 23, 'Förlita dig på dig själv i allt vad du företager dig, ty också det är att hålla buden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 24, 'Den som förlitar sig på lagen, han aktar på dess bud, och den som förtröstar på Herren, han skall ej lida något men.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 1, 'Den som fruktar Herren, honom vederfares intet ont, och kommer han än i frestelse, hjälper Herren honom ut igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 2, 'En vis man hatar icke lagen, men den som skrymtar med den, han är såsom ett skepp i storm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 3, 'Den förståndige sätter sin lit till lagen; ja, lagen synes honom tillförlitlig såsom ett svar från urim.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 4, 'Bered dig på vad du skall säga; då skall man lyssna till dig. Rusta dig med vishet, och svara sedan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 5, 'En dåres hjärta är såsom hjulet på en vagn, och hans tanke såsom hjulnavet, som vrider sig runt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 6, 'En vän som är en gycklare liknar en brunstig hingst; den gnäggar under envar som rider på den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 7, 'Varför har den ena dagen företrade framför den andra, då likväl var dag i året får sitt ljus från solen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 8, 'Genom Herrens vishet hava de åtskilts från varandra, och han har inrättat olika tider och högtider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 9, 'Somliga har han upphöjt och helgat, och andra har han satt bland vanliga dagars tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 10, 'Och människorna — de äro allasammans av stoft, och av jord blev Adam danad;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 11, 'men i sin stora vishet har Herren gjort åtskillnad mellan dem och för dem utstakat olika vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 12, 'Somliga har han välsignat och upphöjt, och somliga har han helgat och låtit komma sig nära. Men andra har han förbannat och ödmjukat och störtat från deras plats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 13, 'Såsom leret är i krukmakarens hand, så att han formar det efter sitt behag, så äro ock människorna i hans hand, som har skapat dem, så att han giver dem efter vad honom rätt synes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 14, 'Det onda har sin motsats i det goda, och döden har sin motsats i livet; sammalunda har den fromme sin motsats i syndaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 15, 'Se på alla den Högstes verk: de té sig sammalunda två och två; det ena har sin motsats i det andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 16, 'Och jag - såsom den siste har jag mödat mig, såsom en som gör efterskörd efter vinbärgarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 17, 'Genom Herrens välsignelse har jag hunnit framom de andra, och såsom en vinbärgare har jag fyllt pressen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 18, 'Veten att jag icke har strävat för mig själv allena, utan för alla dem som söka undervisning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 19, 'Så hören mig då, I stormän bland folket; lyssnen, I hövdingar i menigheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 20, 'Låt icke son eller hustru, broder eller vän taga väldet över dig, så länge du lever. Och giv icke bort dina ägodelar åt en annan; du kunde ju få ångra dig och nödgas bedja att få dem igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 21, 'Medan du ännu lever och livsande är kvar i dig, må du icke avstå din plats åt någon människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 22, 'Ty det är bättre att dina barn få bedja dig om hjälp, än att du måste se dina söner i händerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 23, 'Var den bestämmande i allt vad du gör, och låt ingen fläck komma på din ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 24, 'När dina levnadsdagar hava nått sitt slut och din sista stund är inne, då må du skifta arvet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 25, 'Foder och piska och börda äro för åsnan, bröd och tuktan och arbete äro för tjänaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 26, 'Håll din tjänare till arbete, så får du själv ro; låt hans händer vila, och han skall fika efter friheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 27, 'Ok och töm böja nacken; hugg och slag passa för en illvillig tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 28, 'Driv honom till arbete, så att han icke går fåfäng;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 29, 'ty fåfäng gå lär mycket ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 30, 'Sätt honom till att arbeta, såsom det höves honom; och lyder han icke, så belägg honom med tunga bojor. Men driv det icke för långt med någon människa, och gör intet utan rätt och skäl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 31, 'Har du en enda tjänare, så håll honom såsom dig själv; ty för ditt blod har du köpt honom. Har du en enda tjänare, så behandla honom såsom en broder; ty du behöver honom såsom dig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 32, 'Om du behandlar honom illa, så att han löper bort ifrån dig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 33, 'på vilken väg vill du då söka efter honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 1, 'Den fåkunnige gör sig tomma och bedrägliga förhoppningar, och de oförnuftiga låta sig oroas av drömmar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 2, 'Lik en som griper efter skuggan och jagar efter vinden är den som förlitar sig på drömmar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 3, 'En drömsyn är såsom en spegelbild, såsom avbilden av ett ansikte gent emot ansiktet självt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 4, 'Vad rent kan det finnas i det som är orent? Vad sant i det som är lögn?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 5, 'Spådomar, järtecken och drömmar äro fåfängliga; de äro yrselbilder i själen, lika en kvinnas i barnsnöd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 6, 'Såframt de ej äro dig sända med bud från den Högste, så lägg dem icke på hjärtat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 7, 'Många hava låtit sig ledas vilse av sina drömmar och svikits i sitt hopp till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 8, 'Lagen går osvikligen i fullbordan, och vishet från tillförlitliga läppar vinner uppfyllelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 9, 'En väiuppfostrad man vet mycket, och den mångförfarne har visa ting att förkunna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 10, 'Den som intet har erfarit vet föga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 11, 'men den som har farit vida omkring, han är rik på visdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 12, 'Mycket har jag sett under mina irrfärder, och min insikt är större, än mina ord låta förstå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 13, 'Ofta har jag varit i dödsfara, men blev räddad, tack vare allt som jag hade lärt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 14, 'De som frukta Herren, deras ande skall förbliva vid liv,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 15, 'ty deras hopp står till honom som räddar dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 16, 'Den som fruktar Herren förfaras alls icke; han rädes alls icke, ty Herren är hans hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 17, 'Den som fruktar Herren - salig är hans själ.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 18, 'På vem förlitar han sig? Och vem är hans stöd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 19, 'Herrens ögon äro vända till dem som älska honom; ett mäktigt beskärm och ett fast stöd är han, ett skygd rnot den brännande vinden och ett skygd mot middagshettan. Han bevarar dem för att stöta emot och hjälper dem, så att de icke falla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 20, 'Han höjer deras mod och upplyser deras ögon; han giver läkedom och liv och välsignelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 21, 'Den som offrar av orättfånget gods, hans gåva är en bespottelse;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 22, 'och de orättfärdigas bespottelser äro ej Gud till behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 23, 'Icke har den Högste behag till de ogudaktigas offergåvor, ej heller förlåter han synder för mängden av offer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 24, 'Att frambära offer av fattigas ägodelar är såsom att slakta en son i hans faders åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 25, 'Av armodets bröd beror de fattigas liv; den som berövar dem det, han är en blodsman.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 26, 'Att avhända någon hans livsuppehälle är detsamma som att dräpa sin nästa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 27, 'och att förhålla dagakarlen hans lön, det är att utgjuta blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 28, 'Den ene bygger upp, och den andre river ned - vad hava de vunnit därpå annat än mödor?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 29, 'Den ene beder, och den andre förbannar - vilkenderas röst skall Herren höra?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 30, 'Den som tvår sig efter beröring med en död och kommer vid honom igen, vad har han vunnit genom sin tvagning?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 31, 'Så är det ock med den som fastar för sina synders skull, men sedan går och gör samma synder igen: vem skall väl höra hans bön, och vad har han vunnit genom att ödmjuka sig?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 1, 'Att hålla lagen är att frambära rikliga offergåvor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 2, 'att akta på buden är att offra tackoffer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 3, 'Att återgälda välgärningar är att frambära spisoffer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 4, 'och att öva barmhärtighet är att offra lovoffer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 5, 'Det som täckes Herren är att man avhåller sig från ondska, och försoningsoffer är att avhålla sig från orättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 6, 'Träd icke fram inför Herrens ansikte med tomma händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 7, 'Ty allt sådant bör man göra för budordets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 8, 'Den rättfärdiges offer gör altaret fett, och dess vällukt stiger upp inför den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 9, 'En rättfärdig mans spisoffer täckes Gud, och det som därav offras till åminnelseoffer skall ej bliva förgätet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 10, 'Med frikostigt öga må du ära Herren, och var ej njugg med den förstling dina händer bära fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 11, 'Närhelst du frambär en gåva, så gör det med glatt ansikte, och helga din tionde under glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 12, 'Giv åt den Högste, efter vad han har givit åt dig, och med frikostigt öga, efter vad du med dina händer har förvärvat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 13, 'Ty Herren är en som vedergäller; ja, sjufalt skall han vedergälla dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 14, 'Försök ej att muta honom, ty mutor tager han icke emot;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 15, 'och förlita dig icke på orättfärdigt offer. Ty Herren är en rätt domare, och han har icke anseende till personen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 16, 'Han tager icke parti mot den fattige, utan han hör den förorättades bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 17, 'Han föraktar icke den faderlöses rop, ej heller änkan, när hon utgjuter sin klagan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 18, 'Flyta icke änkans tårar ned över hennes kind,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 19, 'och anklagar hon ej med sitt rop den som frampressade dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 20, 'Den som tjänar Gud, såsom honom behagar, han täckes honom, och hans bön når upp till skyarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 21, 'Den betrycktes bön tränger genom skyarna, och han giver sig icke till freds, förrän den har hunnit ända fram; han slutar ej, förrän den Högste kommer med hjälpen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 22, 'Ja, Herren skall fälla rättvis dom och skall skipa rätt. Sannerligen, han skall icke dröja, ej heller skall han visa långmodighet mot de obarmhärtiga, till dess han har krossat deras länd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 23, 'och utkrävt hämnd på hednafolken; till dess han har förgjort våldsmännens hop och brutit sönder de orättfärdigas spiror;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 24, 'till dess han har vedergällt envar efter hans gärningar, och människorna deras verk alltefter deras uppsåt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 25, 'till dess han har skaffat sitt folk rätt och berett det glädje genom sin barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 26, 'Ljuvligt kommer hans barmhärtighet i nödens stund, såsom regnmoln i torkans tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 1, 'Förbarma dig över oss, du som är Gud över allting, och se till oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 2, 'och låt fruktan för dig komma över alla hednafolk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 3, 'Lyft din hand mot de främmande folken, och låt dem få skåda din makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 4, 'Såsom du inför deras ögon har bevisat dig helig på oss, så bevisa dig nu ock härlig på dem inför våra ögon,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 5, 'och låt dem få lära känna, såsom ock vi hava fått, att ingen Gud finnes förutom dig, o Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 6, 'Gör nya tecken, och utför åter undergärningar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 7, 'förhärliga din hand och din högra arm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 8, 'Väck upp din förtörnelse, och Utgjut din vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 9, 'Röj undan motståndaren, och tillintetgör fienden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 10, 'Påskynda tiden, och tänk på att änden må komma, för att man må förtälja dina väldiga gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 11, 'I den glödande vreden må de förtäras till sista man; ja, låt fördärvet drabba dem som förtrycka ditt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 12, 'Krossa huvudet på fiendernas furstar, på dem som säga: »Ingen finnes förutom oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 13, 'Församla alla Jakobs stammar, så att de få taga sin arvedel i besittning såsom i forna dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 14, 'Förbarma dig, Herre, över det folk som är uppkallat efter ditt namn, över Israel, som du har räknat likt en förstfödd son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 15, 'Hav misskund med din helgedoms stad, med Jerusalem, den stad där du har din viloplats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 16, 'Uppfyll Sion med jubel över dig, och ditt tempel med din härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 17, 'Avlägg ett vittnesbörd för dem som du skapade i begynnelsen, och låt de profetior gå i uppfyllelse, som uttalades i ditt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 18, 'Låt dem som förbida dig få sin lön, och låt dina profeter befinnas sannfärdiga. Hör, o Herre, dina tjänares bön,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 19, 'efter din nåd mot ditt folk; och låt så alla dem som bo på jorden förnimma att du är Herren, den evige Guden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 20, 'Allt slags mat kan buken mottaga, men somlig mat smakar bättre än annan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 21, 'Såsom gommen urskiljer smaken på vilt, så urskiljer ett förståndigt hjärta lögnaktigt tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 22, 'En vrångsint man kommer bedrövelse åstad, men den mångförfarne låter den falla tillbaka på honom själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 23, 'En kvinna får hålla till godo med vilken man som helst, men den ena dottern är att föredraga framför den andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 24, 'En kvinnas skönhet gör mannens uppsyn glad och övergår allt annat som han kan åstunda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 25, 'Om mildhet och saktmod bo på hennes tunga, så har hennes man icke sin like bland människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 26, 'Den som förvärvar sig en hustru, han begynner väl sitt förvärv, han får en hjälp som honom höves och ett fast stöd att vila vid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 27, 'Där hägnad icke finnes, där bliva ägorna skövlade; och där ingen hustru finnes, där går mannen omkring och suckar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 28, 'Vem vågar väl lita på den lättrustade stråtrövaren, som ilar från den ena staden till den andra? Så är det ock med en man som icke har eget bo, utan tager in, varhelst natten överfaller honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 30, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 31, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 1, 'Alla vänner säga: »Också jag ar vän»; men mången vän är vän allenast till namnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 2, 'Måste man icke gräma sig till döds, när en kamrat och vän förvandlas till ovän?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 3, 'O du onda sinnelag, varifrån har da vällt fram för att översvämma jorden med falskhet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 4, 'Mången kamrat fröjdar sig med sin vän i glädjens tid, men bliver i nödens stund hans motståndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 5, 'Mången kamrat delar sin väns mödor för magens skull, men när strid hotar, griper han till skölden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 6, 'Förgät icke din vän i ditt hjärta, och glöm ej bort honom mitt i ditt välstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 7, 'Alla rådgivare bjuda väl på råd, men mången giver råd till sin egen fördel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 8, 'Tag dig i akt för en rådgivare, och sök först att få veta vad som göres honom själv behov - han kan ju giva råd till sin egen fördel - så att han icke lämnar dig till pris åt slumpen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 9, 'och säger till dig: »Lyckosam är din väg», men sedan ställer sig ett stycke ifrån, för att se huru det skall gå dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 10, 'Gå icke till råds med den som ser snett på dig, och håll ditt rådslag hemligt för dina avundsmän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 11, 'Gå icke till råds med en kvinna om hennes medtävlerska eller med den fege om krig; med en köpman om varubyte eller med en köpare om försäljning; med den missunnsamme om tacksamhetsbevisning eller med den obarmhärtige om givmildhet; med den tröge om något som skall uträttas eller med en för år lejd arbetare om vad som skall göras vid årets slut, eller med en lat tjänare om strängt arbete. Lita aldrig på sådana, när det gäller att taga råd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 12, 'Nej, håll dig i stället alltid till den gudfruktige, till den om vilken du vet att han håller buden, den som i sitt hjärta är så sinnad som du och vill lida med dig, om du kommer på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 13, 'Låt ock det råd gälla, som ditt eget hjärta giver; du har ju ingen trognare vän än ditt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 14, 'Ja, en människas själ plägar stundom giva bättre besked än sju väktare som sitta högt uppe i ett vakttorn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 15, 'Men, förutom allt detta, bed till den Högste att han i trofasthet leder din väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 16, 'Överläggning må vara begynnelsen till vart företag, och var handling må föregås av rådslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 17, 'Såsom följder av sinnets om-skiftningar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 18, 'komma fyra ting i dagen: gott och ont, liv och död; men det som beständigt råder över dessa är tungan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 19, 'Mången klok man är en lärare för många andra, men förstår icke att gagna sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 20, 'Mången som synes vis gör sig förhatlig genom sina ord; en sådan går helt miste om livets njutningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 21, 'Ty han har icke av Herren fått gåvan att behaga; ja, han är i saknad av all verklig vishet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 22, 'Mången är vis allenast till sin egen nytta, och frukterna av hans insikt äro synliga på hans kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 23, 'Den verkligt vise är en lärare för sitt folk, och frukterna av hans insikt äro osvikliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 24, 'Den verkligt vise får skörda rik välsignelse, och alla som se honom prisa honom säll.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 25, 'En mans liv utgöres av några få dagar, men Israels dagar kunna icke räknas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 26, 'Den som är vis bland sitt folk vinner ära, och hans namn skall leva evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 27, 'Min son, pröva under ditt leverne vad du tål, ocn lägg märke till vad som är dig skadligt, och avhåll dig från sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 28, 'Ty vad som helst är ej nyttigt för vem som helst, och vem som helst finner sig icke väl av vad som helst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 29, 'Var aldrig omåttlig i någon njutning, och var ej glupsk, när det bjudes på läckerheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 30, 'Ty mycket mat vållar ohälsa, och omåttlighet leder ända till dödlig sjukdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 31, 'För omåttlighets skull hava många mist livet, men den som tager sig i akt, han förlänger sitt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 1, 'Visa läkaren tillbörlig heder, ty du kan komma att behöva honom; också honom har ju Herren skapat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 2, 'Ja, från den Högste kommer läkedomen, och av konungen får läkaren mottaga skänker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 3, 'Läkarens konst upplyfter hans huvud, och bland stormän är han hedrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 4, 'Herren har låtit jorden frambringa läkemedel, och den som är förståndig föraktar dem icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 5, 'Gjordes icke vattnet sött genom ett stycke trä, för att hans makt skulle bliva känd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 6, 'Och han själv har förlänat människor insikt, för att han skulle bliva förhärligad genom de underbara ting han har skapat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 7, 'Genom dem skaffar läkaren bot och tager bort den sjukes plåga;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 8, 'salvoberedaren tillreder genom dem en konstmässig blandning. Ja, Guds verk taga aldrig slut, och från honom kommer välsignelse över hela jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 9, 'Min son, om du bliver sjuk, så var icke försumlig, utan bed till Herren, så skall han göra dig frisk igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 10, 'Avhåll dig ifrån felsteg, och bevara dina händer ostraffliga, och rena ditt hjärta från allt slags synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 11, 'Frambär välluktande offer och åminnelseoffer av fint mjöl, och låt din offergåva vara fet, likasom vore det ute med dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 12, 'Men jämväl för läkaren må du lämna rum, och håll honom ej på avstånd, ty också honom behöver du.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 13, 'Understundom ligger ock en god utgång i läkarnas händer;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 14, 'ty också de bedja till Herren att han skall hjälpa dem att skaffa lindring och bot till den sjukes vederfående.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 15, 'Den som syndar mot sin Skapare, han falle i läkarehänder!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 16, 'Min son, när någon är död, så fäll tårar över honom, och stäm upp en klagosång, såsom det höves under djup sorg. Sköt om hans dödakropp, såsom honom tillkommer, och anse ej hans begravning såsom något likgiltigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 17, 'Bitter vare din klagan och heta dina tårar; sörj honom, såsom kan förtjänar, en dag eller två, för att undgå förtal, och låt sedan trösta dig i sorgen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 18, 'Ty av sorg kommer död, och hjärtesorg bryter ned livskraften.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 19, 'I hemsökelsens tid giver ej heller sorgen vika, och fattigmans liv tär på sinnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 20, 'Överlämna dig icke åt sorgen; slå den ifrån dig, och tänk på änden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 21, 'Förgät icke detta, ty en död vänder aldrig åter; honom gagnar du icke, men väl skadar du dig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 22, 'Betänk, att såsom det har gått honom, så skall det ock gå dig: »I går mig, och i dag dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 23, 'När den döde har kommit till ro, må du ock låta hans minne hava ro; och låt trösta dig över honom, då nu hans ande har flytt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 24, 'Den skriftlärdes vishet vinnes genom lämplig ledighet, och den som är fri ifrån sysslor, han kan bliva vis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 25, 'Huru kan den bliva vis, som går bakom plogen och har sin berömmelse i att hantera oxpiken, som kör oxar och är upptagen med vad de uträtta, och vilkens tal rör sig om tjurkalvar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 26, 'Han tänker allenast på att draga fram fårorna, och hans oavlåtliga omsorg är att skaffa kvigorna foder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 27, 'Så är det ock med alla hantverkare och byggmästare, vilka om natten äro i verksamhet såsom om dagen; så ock med dem som gravera signetringar, och som tålmodigt utföra omväxlande figurer. De tänka allenast på att göra bilden lik, och deras oavlåtliga omsorg är att fullborda arbetet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 28, 'Så är det ock med smeden, där han sitter invid städet och noga synar sitt smide. Hettan från elden pressar fram hans svett, och han kämpar med värmen från ässjan. Till släggans dån lyssnar hans öra, och hans blick är fäst på mönsterbilden till det redskap han förfärdigar. Han tänker allenast på huru han skall fullborda sina arbeten, och hans oavlåtliga omsorg är att till slut giva dem ett prydligt utseende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 29, 'Så är det ock med krukmakaren, där han sitter vid sitt arbete och driver skivan med fötterna. Han är ständigt i bekymmer för sitt arbete, och i hans yrke går allt ut på antalet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 30, 'Med sin hand formar han leret, och med fötterna arbetar han det mjukt. Han tänker allenast på att fullborda glaseringen, och hans oavlåtliga omsorg är att hålla ugnen ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 31, 'Alla dessa förlita sig på sina händer, och envar lägger i sitt arbete vishet i dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 32, 'Dem förutan kan ingen stad byggas, och de behöva icke leva såsom främlingar eller vandra omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 33, 'Men till folkets rådplägningar hämtas de icke, och i folkförsamlingen vinna de ingen utmärkelse. På domarsätet sitta de icke, och förbundet med dess stadgar begrunda de ej. De framlägga icke lära och domslut, och där ordspråk uttänkas, där äro de ej att finna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 34, 'Men livets timliga ordning stödja de, och deras bön gäller utövningen av deras yrke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 1, 'Han forskar i alla de gamles visdom och sysselsätter sig ivrigt med profeternas utsagor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 2, 'Han aktar noga på vad namnkunniga män förtälja och tränger in i tänkespråkens ordvändningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 3, 'Han forskar efter ordspråkens förborgade mening och fördjupar sig i tänkespråkens gåtor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 4, 'Bland stormän gör han tjänst, och inför fursten träder han fram. Han färdas genom främmande folks länder, ty med både gott och ont bland människor gör han sig förtrogen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 5, 'Med all sin håg söker han Herren, sin Skapare, och inför den Högste bönfaller han. Han upplåter sin mun i åkallan och beder om tillgift för sina synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 6, 'Om Herren, den Store, det vill, så varder han uppfylld med förstånds ande. Han låter visdomsord rikligen flöda, och i sin bön prisar han Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 7, 'Han använder rätt sin rådklokhet och sitt förstånd, och Herrens hemligheter begrundar han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 8, 'Han framlägger sin lära och undervisning, och av Herrens förbunds lag berömmer han sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 9, 'Många prisa hans insikt, och aldrig någonsin skall den varda förgäten. Hans åminnelse skall icke upphöra, och hans namn skall leva från släkte till släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 10, 'Om hans vishet skola folken förtälja, och hans lov skall man förkunna i församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 11, 'Om han får leva, skall han efterlämna ett namn, större än tusendens; och om han får gå till ro, ökar han än mer sin berömmelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 12, 'Ytterligare vill jag med eftertänksamhet uttala mig; full, såsom fullmånen, är jag av tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 13, 'Lyssnen till mig, I mina fromma barn, så skolen I grönska såsom rosenbusken, där den växer vid vattenbäcken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 14, 'I skolen sprida ljuvlig vällukt såsom rökelsen och skjuta blomster såsom liljan. Låten eder doft utströmma, och stämmen upp en lovsång. Loven Herren för alla hans gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 15, 'Given hans namn ära, och tacken honom med lovprisning, med edra läppars sånger och med harpospel. Ja, så skolen I sjunga i eder lovsång:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 16, 'Övermåttan härliga äro alla Herrens verk, och allt vad han bjuder, det sker på sin rätta tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 17, 'Icke må man säga: »Vad är detta?», »Vartill är detta?» Ty allt bliver efterfrågat i sin tid. På hans ord reste sig vattnet upp såsom i en hög, och på hans muns befallning samlades det i sina förvaringsrum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 18, 'På hans bud sker allt vad han har beslutit, och ingen finnes, som kan hindra hans frälsning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 19, 'Alla människors gärningar äro uppenbara inför honom, och intet kan fördöljas för hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 20, 'Hans blickar gå från den ena tidsåldern till den andra, och intet är underbart i hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 21, 'Icke må man säga: »Vad är detta?», »Vartill är detta?» Ty allting är skapat för sin särskilda uppgift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 22, 'Hans välsignelse övertäcker jorden såsom en ström och vattnar den såsom en översvämmande flod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 23, 'Likaledes bliva ock folken rov för hans vrede, såsom, när han en gång förvandlade vattenrikt land till salthed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 24, 'För de fromma äro hans vägar jämna, men för de orättfärdiga äro de fulla av stötestenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 25, 'Vad gott är har från begynnelsen blivit berett för de goda, men vad ont är för syndarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 26, 'Det förnämsta av allt som är nödigt för en människas liv är vatten, eld, järn och salt, vetemjöl, honung och mjölk, druvans blod, olja och kläder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 27, 'Allt detta bliver för de gudfruktiga till något gott, men för syndarna vändes det till något ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 28, 'Det finnes vindar som äro skapade till straffdom, och som i sitt raseri låta sina gisselslag drabba hårt. I tillintetgörelsens stund utgjuta de sin kraft och stilla så hans vrede, som har skapat dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 29, 'Eld och hagel, hungersnöd och pest, alltsammans är det skapat till straffdom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 30, 'så ock vilddjurs tänder, skorpioner och ormar och svärdet som straffar och förgör de ogudaktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 31, 'De fröjda sig över hans bud och hålla sig redo för sina olika uppgifter på jorden; och när deras tid kommer, lyda de villigt hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 32, 'Fördenskull har jag från begynnelsen varit fast i min övertygelse och har begrundat det och upptecknat det:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 33, 'alla Herrens verk äro fullkomliga och utföra i rätt tid alla sina olika uppgifter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 34, 'Icke må man säga: »Det ena är sämre än det andra», ty allting varder gillat, när dess tid kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 35, 'Så sjungen då av allt hjärta och med hög röst, och loven Herrens namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 1, 'Stor möda är beredd för alla människor, och ett tungt ok vilar på Adams barn. Från den dag då de utgå ur sin moders liv, intill den dag då de vända åter till allas moder:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 2, 'tunga tankar och hjärteoro, framtidsomsorg, dödens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 3, 'Från den som tronar i härlighet till den som sitter djupt nere i stoft och aska,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 4, 'från den som bär purpur och krona till den som är höljd i grovt säcktyg:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 5, 'vrede och avund, oro och bävan, fruktan för döden, agg och kiv. Till och med när man vilar på sitt läger, förvirrar sömnen om natten ens tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 6, 'Man njuter liten eller ingen vila; sedan är det i drömmen, såsom när man står på vakt. Ja, man skrämmes genom sin själs syner, lik en som är stadd på flykt ur en strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 7, 'Just när det gäller ens räddning, vaknar man upp och förundrar sig över att ingen fara var på färde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 8, 'Bland allt levande, från människan till boskapen - och över syndarna i ytterligare sjufalt mått -');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 9, 'råda pest och blodsutgjutelse, strid och svärd, olyckor och hungersnöd, förödelse och plåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 10, 'För de orättfärdiga är allt sådant berett; för deras skull kom ju ock den stora floden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 11, 'Allt som är av jord vänder åter till jorden, och allt som är vatten flyter tillbaka till havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 12, 'Mutor och orättfånget gods bliva alltid om intet, men redlighet består evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 13, 'De orättfärdigas skatter äro såsom en vinterbäck, som torkar ut, och såsom ett starkt tordön, vars dunder dör bort, när regnet kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 14, 'Den redlige gläder sig över att upplåta sin hand, men lagöverträdarna tyna bort och bliva till intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 15, 'De ogudaktigas avkomlingar skjuta icke grenar i mängd, och orena rotskott växa på kala klippan. De likna vassen vid var vattensamling och vid var flodbrädd, vilken ryckes bort före allt annat gräs.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 17, 'Men godhet är lik en välsignad lustgård, och barmhärtighet förbliver evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 18, 'Ljuvt är livet för den förnöjsamme och arbetsamme, men den som finner en skatt, han är förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 19, 'Att få barn och att bygga en stad, det giver namnet bestånd, men en hustru utan tadel aktas förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 20, 'Vin och musik fröjda hjärtat, men kärlek till visheten är förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 21, 'Flöjt och psaltare frambringa ljuva toner, men en mild tunga är förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 22, 'Behag och skönhet äro en lust för ögat, men åkerfältets grönska är det mer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 23, 'En vän och en kamrat infinna sig i rätta stunden, men hustrun vid mannens sida är förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 24, 'En broder och en hjälpare infinna sig i nödens stund, men barmhärtigheten är en frälsare som är förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 25, 'Guld och silver göra foten stadig, men rådklokhet är i anseende förmer än båda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 26, 'Rikedom och styrka höja modet, men Herrens fruktan är förmer än båda. Där Herrens fruktan finnes, fattas intet, ja, där den finnes, behöver man icke söka hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 27, 'Herrens fruktan är såsom en välsignad lustgård, och han har omgivit den med en oförliknelig härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 28, 'Min son, akta dig för att leva ett tiggarliv; ty bättre är att dö än att tigga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 29, 'Den som ser efter en annans bord, hans leverne är icke att räkna såsom liv. Han besmittar sin själ med den andres rätter, men den som är förståndig och väluppfostrad, han tager sig till vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 30, 'I den skamlöses mun ljuder tiggarbönen söt, men i hans inre brinner en eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 1, 'O död, huru bitter är icke tanken på dig för en människa som lever i ro bland sina ägodelar, för en man som njuter ostört lugn och har framgång i allt, och som ännu förmår göra sig till godo bordets läckerheter!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 2, 'O död, huru ljuv är icke din lott för en människa som är behövande och orkeslös, för den som är utgammal och bekymrar sig för allting, och för den som är missmodig och har uppgivit hoppet!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 3, 'Räds icke för dödens lott; tänk på dem som voro före dig och dem som komma efter dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 4, 'Denna lott är av Herren bestämd för allt levande. Varför skulle du då vara gensträvig mot den Högstes beslut? Du må få leva tio år eller hundra eller tusen - i dödsriket höres intet klander över levnadens längd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 5, 'Vederstyggliga barn äro syndarnas barn, sådana som dväljas i de ogudaktigas boningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 6, 'För syndarnas barn går deras arv om intet, och vid deras avkomma låder beständig skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 7, 'En ogudaktig fader bliver bannad av sina barn, därför att de få utstå skam för hans skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 8, 'Ve eder, I ogudaktige, I som haven övergivit den Högstes lag!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 9, 'Ty när I föröken eder, sker det till fördärv, och när I själva bliven födda, sker det till förbannelse; och när I dön, bliver förbannelse eder del.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 10, 'Såsom allt som är av jord vänder åter till jorden, så gå de ogudaktiga ifrån förbannelse till fördärv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 11, 'Människors sorg gäller de dödas kroppar, men ett gott namn varder icke utplånat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 12, 'Var rädd om ditt namn, ty det får du längre behålla än rika gyllene skatter i tusental.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 13, 'Ett gott livs dagar äro lätt räknade, men ett gott namn förbliver evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 14, 'Mina barn, bevaren stilla min undervisning. Men dold vishet och förborgad skatt, vartill gagna de båda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 15, 'Bättre är den som döljer sin dårskap än den som döljer sin vishet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 16, 'Alltså, kännen blygsel i enlighet med mina ord. Ty icke all blygsel är berättigad, och icke allt bliver av alla med rätta ansett för gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 17, 'Blygens inför fader och moder för otukt, inför styresman och makthavande för lögn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 18, 'inför domare och överhetsperson för förseelser, inför menighet och folkförsamling för lagbrott, inför medbröder och vän för orättrådighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 19, 'inför folket på den ort där du vistas, för stöld; blygs för att bryta ed och fördrag och för att stödja dig på armbågen, när du äter, och för att ställa dig skymfligt avvisande, när det gäller att taga eller giva;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 20, 'blygs inför den som hälsar för att icke hälsa igen, för att se på en lösaktig kvinna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 21, 'och för att vända ansiktet bort ifrån en frände; för att undandraga någon hans andel och lott och för att beskåda en annan mans hustru;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 22, 'för att hava för mycket att skaffa med din tjänstekvinna - ställ dig icke vid hennes bädd -; blygs inför vänner för hårt tilltal - tala ej hårda ord, sedan du har givit en gåva -;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 1, 'för att sprida ett rykte som du har hört och för att yppa vad som borde hållas hemligt. Om du så gör, visar du dig verkligt blygsam och skall finna nåd inför var man. För följande ting må du icke blygas, och ej må du av anseende till personen försynda dig häri:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 2, 'för den Högstes lag och förbundet eller för rätten, så att du skulle frikänna den ogudaktige;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 3, 'för att göra upp med följeslagare och reskamrat, för att skifta arv med fränder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 4, 'för noggrannhet i fråga om våg och vikt eller för förvärv, vare sig det gäller mycket eller litet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 5, 'för penningar, förtjänade genom handel och köpenskap, för att med stränghet tukta barnen eller för att hudstryka en elak tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 6, 'Där en ond hustru finnes, där är det gott att hava ett signet, och där många händer finnas, där må du låsa väl till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 7, 'Räkna och väg det som du vill anförtro i någons förvar, och skriv upp alla utgifter och inkomster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 8, 'Blygs icke för att tillrättavisa den oförnuftige och dåren eller en utlevad åldring som är anklagad för otukt. Därigenom visar du dig vara verkligt fostrad, och så skall du vinna gillande bland alla människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 9, 'En dotter är sin fader en anledning till hemligt nattvak, och oron för henne förjagar hans sömn: medan hon är ung, för att hon skall bliva överårig, och när hon har blivit gift, för att hon skall bliva försmådd av sin man;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 10, 'medan hon är jungfru, för att hon skall bliva Vanärad och i sin faders hus bliva havande; när hon har man, för att hon skall begå något felsteg eller i sitt äktenskap bliva ofruktsam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 11, 'Håll sträng vakt över en tuktlös dotter, så att hon ej gör dig till ett ämne för dina fienders skadeglädje, och vållar att du bliver omtalad i staden och instämd inför folket och sålunda bliver utskämd bland den stora hopen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 12, 'Se icke på någon människa för hennes skönhets skull, och sitt ej i kvinnors sällskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 13, 'Ty från kläder kommer mal och från en kvinna kvinnoondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 14, 'Bättre är en obehaglig man än en behagsjuk kvinna; och en kvinna som är de sina till skam vållar nesa. -');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 15, 'Nu vill jag tänka på Herrens verk, och vad jag har sett vill jag förtälja. Genom Herrens ord hava hans verk blivit danade, och efter hans behag har hans beslut blivit fullbordat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 16, 'Den strålande solen skådar ned på allt, och vad han har gjort är uppfyllt av hans härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 17, 'Icke har Herren givit de heliga makt till att förtälja alla de underbara ting som han, Herren, den Allsmäktige, har gjort till att fast bestå, för att världsalltet skulle äga säkert bestånd genom hans härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 18, 'Djupet utrannsakar han, så ock människohjärtat, och han utgrundar deras listiga anslag. Ty Herren besitter all kunskap, och han skådar in i tidernas tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 19, 'Det förgångna och det tillkommande gör han kunnigt, och han uppdagar spåren av det förborgade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 20, 'Ingen tanke undgår honom, och icke ett enda ord är fördolt för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 21, 'Sin vishets storverk har han inrättat väl, och från evighet till evighet äro de sig lika. De kunna varken ökas eller minskas, och av någon rådgivare har han icke behov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 22, 'Huru härliga äro icke alla hans verk! Och dock kan man ej se mer än en gnista därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 23, 'Allt detta lever och förbliver till evig tid, och alltsammans står honom till tjänst, alltefter sina olika uppgifter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 24, 'Allt är tvåfaldigt, det ena svarar mot det andra, och intet har han skapat, som sviker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 25, 'Det ena främjar det andras bästa. Ja, vem kan se sig mätt på hans härlighet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 1, 'Himlahöjdens stolthet är det klara fästet; himmelens gestalt erbjuder en härlig anblick.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 2, 'När solen visar sig vid sin uppgång, kommer den såsom en budbärare, ett underbart redskap, ett verk av den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 3, 'När den är i sin middagshöjd, uttorkar den jorden; ja, vem kan bestå för dess hetta?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 4, 'Man hettar upp ugnen vid arbeten som fordra värme, men trefalt starkare bränner solen bergen. Den sprider glödande ångor, den sänder ut ljusstrålar och bländar så ögat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 5, 'Stor är Herren, som har danat den; och efter hans bud ilar den fram på sin färd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 6, 'Och månen - i allt tager den sin tid i akt, den utvisar tidsskiftena och är ett tidsåldrarnas tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 7, 'Det är månen som giver tecken till när högtiderna skola firas, himlaljuset, som avtager i sken, sedan det har nått sin fullhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 8, 'Månaden har efter den sitt namn; den ökar sig underbart under sin växling. Den är en signaleld för härskarorna i höjden, där den sprider sitt sken på himmelens fäste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 9, 'Skön på himlavalvet är stjärnornas glans, ett strålande smycke på Herrens himmel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 10, 'På den Heliges bud ställa de upp sig i ordning och förtröttas icke på sina poster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 11, 'Se på regnbågen, och lova honom som har danat den. övermåttan skön är den i sin glans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 12, 'Den välver sig över himmelen med sin strålande ring; den Högstes händer hava spänt den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 13, 'Genom sin befallning kommer han plötsligt snön att falla, och han sänder med hast ut sina hämnande ljungeldar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 14, 'Fördenskull upplåta sig förrådshusen, så att molnen flyga ut såsom fåglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 15, 'Genom sin väldiga makt giver han molnen styrka, så att hagelstenar falla ned i sönderbrutna stycken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 16, 'Ljudet av hans dunder kommer jorden att skälva, och vid hans anblick bäva bergen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 17, 'Efter hans vilja blåser sunnanvinden och nordanstormen och virvelvinden. Snöflingorna strör han ut lika nedsvävande fåglar, och lika en gräshoppssvärm som slår ned äro de, där de falla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 18, 'Över skönheten av snöns vita färg förundrar sig ögat, och över flingornas fall råkar sinnet i häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 19, 'Rimfrosten strör han ut över jorden såsom salt; och när den fryser samman, bliver den till vassa taggar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 20, 'Kall blåser nordanvinden; då fryser vattnet till is. Den sänker sig över var vattensamling; då beklädes vattnet såsom med pansar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 21, 'Ja, han föröder bergen och förbränner heden och avsveder grönskan såsom med eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 22, 'Till läkedom för allt kommer dimman med hast; daggen faller och friskar upp allt efter hettan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 23, 'Genom sitt rådslut bragte han havsdjupet till vila och lät öar växa upp däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 24, 'De som segla på havet förtälja om dess farlighet, och vi förundra oss över vad våra öron få höra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 25, 'Där finnas sällsamma och underbara ting, en brokig mångfald av allahanda varelser, havsvidundrens värld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 26, 'Genom hans makt bliver hans budbärares väg lyckosam, och genom hans ord äger allting bestånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 27, 'Mycket kunna vi väl säga, och dock nå vi aldrig slutet. Summan av våra ord är: Han är allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 28, 'Om vi vilja prisa honom, huru skola vi mäkta det? Ty han är den Store, ja, han är större än alla sina verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 29, 'Fruktansvärd är Herren och högeligen stor, och underbar är hans makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 30, 'Prisen och upphöjen Herren, så mycket I förmån; han övergår dock allt edert lov. Ja, upphöjen honom, och uppbjuden all eder kraft; förtröttens icke, ty I kunnen dock aldrig nå slutet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 31, 'Vem har sett honom, så att han skulle kunna beskriva honom? Och vem kan prisa honom, såsom han är värd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 32, 'Mycket förborgat finnes, som är ännu större än allt detta, ty endast föga hava vi sett av hans verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 33, 'Ja, allting har Herren gjort, men de fromma har han förlänat visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 1, 'Nu vilja vi prisa ärorika män, våra fäder efter deras tidsföljd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 2, 'Stor härlighet har Herren berett genom dem; sitt majestät har han uppenbarat från uråldrig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 3, 'Män som hava härskat i sina riken, och män som hava vunnit ett namn genom sin makt; som hava givit råd genom sin insikt, och som hava framburit förkunnelse genom profetior;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 4, 'som hava varit folkets ledare genom sina rådslag och genom sin insikt i dess skriftlärdom, och som med visa ord hava meddelat sin undervisning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 5, 'som hava uppfunnit visor till att sjunga och författat och upptecknat diktverk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 6, 'rika män, utrustade med ägodelar, som hava levat fredligt i sina boningsorter -');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 7, 'alla dessa hava i sin tid hållits i ära och åtnjutit berömmelse, medan de levde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 8, 'Somliga bland dem hava lämnat efter sig ett namn, så att man förkunnar deras lov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 9, 'Av andra har icke någon aminnelse blivit bevarad, utan de hava försvunnit, som om de aldrig hade funnits till. Ja, det är med dem, som om de aldrig hade varit födda, och likaså med deras barn efter dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 10, 'Men de som nu följa äro fromma män, vilkas rättfärdiga gärningar icke hava blivit förgätna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 11, 'Hos deras släkt förbliver det goda de hava efterlämnat, och deras kvarlåtenskap förbliver i deras efterkommandes besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 12, 'Deras släkt står fast i förbundet, och deras barn för deras skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 13, 'Till evig tid bliver deras släkt beståndande, och deras ära skall icke utplånas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 14, 'Deras kroppar ligga begravna i frid, och deras namn lever från släkte till släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 15, 'Om deras vishet förtälja folken, och deras lov förkunnar man i församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 16, 'Henok var välbehaglig för Herren och blev tagen bort, ett föredöme i bättring för kommande släkten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 17, 'Noa blev befunnen ostrafflig och rättfärdig; i vredens tid tjänade han såsom en lösepenning. Fördenskull blev en kvarleva lämnad på jorden vid den tid då floden kom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 18, 'Ett evigt förbund blev slutet med honom, att allt levande icke vidare skulle utplånas genom någon flod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 19, 'Abraham var en stor fader till många folk, och på hans ära blev icke någon fläck funnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 20, 'Han höll den Högstes lag och trädde i förbund med honom. På sitt kött fullbordade han förbundet, och i prövningen blev han befunnen trogen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 21, 'Fördenskull fastställde Herren åt honom genom ed att folken skulle varda välsignade i hans säd, och att han skulle göra honom tallös såsom jordens stoft och upphöja hans säd så högt som stjärnorna och giva dem en besittning från hav till hav, och ifrån floden intill jordens ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 22, 'Också åt Isak fastställde han på samma sätt, för Abrahams, hans faders, skull, välsignelsen för alla människor, och förbundet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 23, 'Han lät den ock vila på Jakobs huvud; han utmärkte honom med sin välsignelse och förlänade honom arvet. Han utskiftade hans arvslotter och fördelade dem bland de tolv stammarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 1, 'och var älskad av både Gud och människor, Moses, vilkens minne vare välsignat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 2, 'Han gjorde honom i härlighet lik de heliga och gjorde honom stor genom den skräck han injagade hos fienderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 3, 'Genom dennes ord lät han tecken inträffa med hast; han förhärligade honom inför konungar och gav honom befallning till hans folk och lät honom se en skymt av sin härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 4, 'För hans trohets och saktmods skull avskilde han honom till heligt värv; han utvalde honom bland alla levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 5, 'Han lät honom höra sin röst och lät honörn träda in i töcknet. Och han gav honom sina bud med egen hand, livets och kunskapens lag, för att han skulle undervisa Jakob om förbundet och Israel om hans rätter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 6, 'Han upphöjde Aron, en helig man, den förres like, dennes broder av Levi stam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 7, 'Han upprättade i hans person ett evigt förbund och gav honom prästadöme bland folket. Han hugnade honom med en skön skrud och omgjordade honom med en härlig dräkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 8, 'Ja, han beklädde honom med den högsta ståt och prydde honom med präktiga kläder, med benkläder och kåpa och efod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 9, 'Och han hängde omkring honom en krans av granatäpplen, så ock en mängd av gyllene bjällror runt omkring, för att det skulle klinga, när han gick, så att klangen hördes i templet, till en påminnelse för hans folks barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 10, 'Han utrustade honom med den heliga klädnaden, med guld och mörkblått och purpurrött garn i konstvävnad, med domsskölden, med urim och tummim,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 11, 'med tvinnat rosenrött garn, ett konstrikt arbete, med dyrbara stenar, graverade såsom signetringar, i infattning av guld, ett verk av stensnidarkonst, till åminnelse försedda med inristad skrift, efter antalet av Israels stammar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 12, 'På huvudbindeln satte han ett gyllene diadem, varpå den heliga inskriften var ingraverad, ett härligt praktstycke, ett präktigt arbete. Alltsammans var en lust för ögonen, en skön prydnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 13, 'Före honom har aldrig något sådant funnits, och aldrig har någon av annan släkt fått bära en sådan klädnad; det få allenast hans egna söner och hans avkomlingar i alla tider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 14, 'Hans offer förbrännas helt och hållet, två gånger om dagen, för beständigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 15, 'Moses företog handfyllning med honom och smorde honom med helig olja. Och till en evärdlig förordning blev det fastställt för honom och för hans efterkommande, så länge himmelen består, att de skulle göra tjänst inför Herren, och att de skulle vara hans präster och välsigna hans folk i hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 16, 'Han utvalde honom bland alla levande till att frambära brännoffer åt Herren, rökelse och vällukt till åminnelse, och till att bringa försoning för folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 17, 'Och han gav honom sina bud och makt över sina rättsförordningar, för att han skulle lära Jakob hans vittnesbörd och undervisa Israel i hans lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 18, 'Mot honom rotade sig främmande män samman, och de grepos av avund mot honom, i öknen, Datan och Abiron och deras folk och Koras hop, i förtörnelse och vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 19, 'Herren såg det, och det behagade honom icke, och de blevo tillintetgjorda genom svår förtörnelse. Han lät under ske med dem, så att han lät dem förtäras genom sin eldslåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 20, 'Och han förlänade Aron ännu större härlighet, och han beskärde honom hans arvedel: förstlingen av alla förstlingsfrukter tilldelade han honom; främst beredde han honom bröd till att mätta sig med.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 21, 'Ja, av Herrens offer skulle de hava sitt underhåll, de offer som han hade bestämt åt honom och hans efterkommande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 22, 'Men i folkets land skulle han icke hava någon arvedel, och ingen lott skulle han hava bland folket: »Ty jag själv», sade Herren, »skall vara din lott och arvedel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 23, 'Och Finees, Eleasars son, är den tredje i ära, därför att han nitälskade i Herrens fruktan och grep in vid folkets avfall, i sitt hjärtas redliga nit, och bragte försoning för Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 24, 'Fördenskull blev ock ett fridsförbund upprättat med honom, att han skulle vara en föreståndare för helgedomen och för sitt folk, så att prästadömets högsta värdighet skulle tillhöra honom och hans efterkommande, till evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 25, 'Och såsom ett förbund blev upprättat med David, Jessais son, av Juda stam, att konungavärdigheten skulle gå i arv från son till son allenast, på samma sätt skulle det ock vara med Arons och hans efterkommandes arvsrätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 26, 'Herren give eder vishet i edra hjärtan till att styra hans folk med rättfärdighet, på det att dess lycka aldrig måtte gå om intet, ej heller dess härlighet, släkte efter släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 1, 'En hjälte i strid var Josua, Nuns son, Moses’ efterföljare såsom profet, han som, enligt vad hans namn utsäger, blev stor såsom frälsare för Herrens utvalda. Ja, han utkrävde hämnd på de fiender som reste sig upp, för att så förhjälpa Israel till sin besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 2, 'Huru härlig tedde han sig icke, när han lyfte sin hand och sträckte ut sitt svärd mot städerna!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 3, 'Vem före honom stod stark såsom han? Ja, Herrens krig förde han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 4, 'Var det icke genom honom som solen gick tillbaka, så att en dag blev så lång som två?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 5, 'Han åkallade den högste härskaren, när fienderna trängde honom på alla sidor. Och den store Herren bönhörde honom genom att sända tunga, väldiga hagelstenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 6, 'Han slungade dem mot det fientliga folket och förgjorde motståndarna på sluttningen. Så skulle hedningarna få pröva på hans vapen och förnimma att han inför Herrens ansikte förde sin strid; också efterföljde han ju den Allsmäktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 7, 'Redan i Moses’ tid bevisade han sin fromhet, han och Kaleb, Jefonnes son, i det att de sökte stå menigheten emot och hindra folket ifrån synd och tysta ned dess onda knorrande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 8, 'Och så blevo dessa två allena räddade bland skaran av de sex hundra tusen, till att föra folket in i dess arvedel, in i det land som flöt av mjölk och honung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 9, 'Och Herren förlänade Kaleb kraft; ja, ända till hans ålderdom förblev den hos honom, så att han kunde draga upp till Bergsbygden. Och jämväl hans efterkommande fingo en besittning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 10, 'för att alla Israels barn skulle få se att det är gott att efterfölja Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 11, 'Domarna, envar med sitt namn, så många av dem, som ej trolöst avföllo i sina hjärtan, och så många som icke vände sig bort ifrån Herren - deras minne vare välsignat!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 12, 'Deras ben skjute skott ur deras gravar, och må deras namn gå i arv på deras söner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 13, 'Älskad av sin Herre var Samuel, en Herrens profet, som grundade konungadömet och smorde furstar över hans folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 14, 'Efter Herrens lag dömde han menigheten; och Herren såg till Jakob.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 15, 'I följd av sin trohet blev han prövad tillförlitlig såsom profet, och på grund av sina ord blev han befunnen sannfärdig såsom siare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 16, 'Och han åkallade Herren, den Allsmäktige, när hans fiender trängde honom på alla sidor; han frambar därvid ett dilamm såsom offer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 17, 'Och Herren dundrade från himmelen, han lät sin röst höras med starkt dån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 18, 'Och han slog i grund tyriernas hövdingar och filistéernas alla furstar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 19, 'Och förrän han somnade in i den eviga sömnen, betygade han inför Herren och hans smorde: »Intet, icke så mycket som ett par skor, har jag tagit från någon människa.» Det fanns ej heller någon som kunde anklaga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 20, 'Jämväl sedan han hade avsomnät, profeterade han och förutsade för konungen hans död. Och han lät sin röst höras ur jordens djup för att genom sitt profetiska ord utplåna folkets orättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 1, 'Och efter denne uppstod Natan och verkade såsom profet i Davids dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 2, 'Såsom det feta avskiljes från tackoffret, så var David avskild från andra israeliter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 3, 'Han lekte med lejon såsom med killingar och med björnar såsom med lamm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 4, 'Slog han icke i sin ungdom ihjäl jätten och tog så bort försmädelsen ifrån folket, i det han lyfte sin hand med slungstenen och slog Goljats stolta skryt till marken? Ja, han åkallade Herren, dens Högste, och Herren lade styrka i hans högra hand, till att nedgöra den starke kämpen och till att upphöja hans folks horn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 5, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 6, 'Så ärade man honom för de tio tusens skull och prisade honom för den välsignelse han hade undfått av Herren, under det man hembjöd åt honom ärans krona.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 7, 'Ty han slog i grund fienderna runt omkring och tillintetgjorde filistéerna, som stodo honom emot; ja, ända till denna dag har han krossat deras horn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 8, 'Vid allt vad han företog sig hembar han tacksägelse åt den helige Högste med sköna ord. Av allt sitt hjärta sjöng han, och han hade sin Skapare kär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 9, 'Sångare ställde han upp framför altaret och lät genom deras röster ljuvliga sånger klinga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 10, 'Han förlänade glans åt festerna och inrättade välordnade högtider året igenom; man prisade vid dem Herrens heliga namn, så att helgedomen genljöd därav ända ifrån morgonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 11, 'Herren borttog hans synder och upphöjde för evigt hans horn; han slöt med honom ett förbund angående konungadömet och förlänade honom ärans tron i Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 12, 'Efter honom uppstod hans vise son, som för hans skull fick hava ro vida omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 13, 'Salomo fick vara konung under en tid av fred, och Gud gav honom ro på alla sidor, för att han skulle uppföra ett hus i hans namn och grunda en helgedom för evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 14, 'Huru vis var du icke i din ungdom! Fylld, såsom en flod, var du av insikt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 15, 'Din ande omfattade hela jorden, och du uppfyllde den med sinnrika ordspråk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 16, 'Till avlägsna öar nådde ditt rykte, och du blev älskad för den fred som du beredde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 17, 'Genom dina sånger, liknelser och ordspråk och genom din uttydningskonst väckte du beundran i länderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 18, 'I Herren Guds namn, hans som kallas Israels Gud, samlade du guld såsom tenn och hopade silver såsom bly.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 19, 'Men du skänkte din kraft åt kvinnor och lät dem få väldet över din kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 20, 'Du satte en fläck på din ära och vanhelgade din säd. Så drog du vrede över dina barn och vållade bitter grämelse för din dårskaps skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 21, 'Därför blev nu väldet delat, och ur Efraim framgick ett gensträvigt rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 22, 'Men Herren låter aldrig sin barmhärtighet fara, och aldrig låter han något av sina verk bliva till intet. Aldrig utplånar han sin utvaldes avkomma; nej, han utrotar aldrig dens barn, som älskar honom. Så gav han ock åt Jakob en kvarleva och åt David en telning, som utgick från honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 23, 'Och Salomo gick till vila hos sina fäder och lämnade efter sig sin son, stor i dårskap och liten i förstånd, Roboam, som genom sitt rådslut bragte folket till att avfalla. Så kom ock Jeroboam, Nabats son, som förledde Israel till synd och öppnade för Efraim syndens väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 24, 'Och folkets synder förökades storligen, så att de blevo bortförda från sitt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 25, 'Ja, de foro efter allt slags ondska, intill dess straffdomen kom över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 1, 'Därefter uppstod Elias, en profet lik en eld, vilkens ord brann såsom en fackla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 2, 'Han lät hungersnöd drabba folket, och genom sin nitälskan kom han deras antal att förminskas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 3, 'Genom Herrens ord tillslöt han himmelen; likaså lät han eld tre gånger falla ned.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 4, 'Huru härlig tedde du dig icke, Elias, i dina undergärningar! Ja, vem är dig lik, så att han skulle kunna berömma sig därav,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 5, 'du som uppväckte en död från de döda, från dödsriket, genom den Högstes ord;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 6, 'du som störtade konungar ned i fördärvet, och höga herrar från deras sjukläger;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 7, 'du som på Sina förnam straffförkunnelsen, och på Koreb hämndens domar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 8, 'du som smorde konungar till att öva vedergällning, och profeter till efterföljare åt dig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 9, 'du som blev upptagen i en stormvind av eld, i en vagn, dragen av eldshästar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 10, 'du som står redo för kommande tider, såsom det är skrivet, till att stilla vreden, innan den bryter ut, och till att vända fädernas hjärtan till barnen och upprätta Jakobs stammar!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 11, 'Saliga äro de som skola få se dig; ja, saliga äro ock de som redan hava insomnat i ro. Ty också vi skola förvisso få leva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 12, 'Sedan Elias hade överskyggts av stormvinden, blev Elisa uppfylld av hans ande. Så länge denne levde, kunde ingen furste få honom att vackla, och ingen fick makt över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 13, 'Ingenting översteg hans förmåga, och ännu i graven hade hans kropp profetisk kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 14, 'Medan han levde, gjorde han tecken, och när han var död, voro hans gärningar underbara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 15, 'Trots allt detta bättrade folket sig icke och avstod ej från sina synder, till dess de blevo bortförda såsom byte från sitt land och förskingrades över hela jorden; allenast en ringa del av folket lämnades kvar, så ock en furste åt Davids hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 16, 'Några av dessa gjorde det som var välbehagligt för Herren, men andra begingo synder i myckenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 17, 'Esekias befäste sin stad och drog in en vattenledning i den. Han högg igenom den hårda klippan med järn och byggde dammar för vattnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 18, 'I hans dagar drog Sennakerim ditupp, och han sände Rabsake åstad. Denne lyfte sin hand mot Sion och for i sitt övermod ut i hädelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 19, 'Då skälvde deras hjärtan och deras händer, de våndades såsom barnaföderskor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 20, 'De åkallade Herren, den barmhärtige, och uträckte sina händer mot honom. Och den Helige hörde dem snarligen från himmelen och förlossade dem genom Esaias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 21, 'Han slog assyriernas läger, och hans ängel förgjorde dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 22, 'Ty Esekias gjorde det som var välbehagligt för Herren och höll sig stadigt på sin fader Davids vägar; och dessa förelades honom av Esaias, profeten, den store och i sina syner sannfärdige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 23, 'I hans dagar gick solen tillbaka, och han förlängde konungens liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 24, 'Med mäktig ande skådade han det tillkommande och tröstade de sörjande på Sion.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 25, 'Han uppenbarade vad som skulle komma, intill en avlägsen framtid, och det förborgade, förrän det ännu hade inträffat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 1, 'Josias’ åminnelse är såsom en fin rökelseblandning, tillagad med salvoberedarens konst. I vars och ens mun är den söt såsom honung, och den är såsom musik vid ett festligt lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 2, 'Rätt handlade han, då när folket omvände sig, och han skaffade bort laglöshetens styggelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 3, 'Han riktade sitt hjärta till Herren, i de laglösas dagar befäste han Guds fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 4, 'Förutom David och Esekias och Josias försyndade de sig allasammans, ty de övergåvo den Högstes lag; så blevo Juda konungar till intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 5, 'Ja, de måste överlåta sitt horn åt andra och sin ära åt ett främmande folk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 6, 'och det satte eld på den utvalda, heliga staden och ödelade dess gator.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 7, 'Detta skedde genom Jeremias, ty honom hade de misshandlat. Och dock hade han redan i moderlivet blivit helgad till profet, till att upprycka och förgöra och fördärva, såsom ock till att uppbygga och plantera.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 8, 'Hesekiel fick i en syn skåda Herrens härlighet, som han visade honom på kerubernas vagn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 9, 'Också hotade han fienderna med slagregn, men lovade dem gott, som vandrade på rätta vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 10, 'Och de tolv profeterna — må deras ben skjuta skott ur deras gravar. Ty de tröstade Jakob och ingåvo dem ett fast hopp om förlossning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 11, 'Huru skola vi väl prisa Sorobabel? Han var såsom en signetring på högra handen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 12, 'Och huru prisa Josua, Josedeks son? I sin tid byggde de upp Guds hus och uppförde ett tempel, helgat åt Herren, berett till evig härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 13, 'Och Neemias - hans minne är ärat; han byggde upp åt oss de fallna murarna och lät sätta in portar och bommar och åter bebygga våra boningsplatser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 14, 'Aldrig har någon blivit skapad på jorden, som var Henok lik; också han blev ju levande borttagen från jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 15, 'Ej heller har någon annan man sådan som Josef blivit född; en hövding var han över sina bröder, en stödjepelare för folket. Till och med hans ben vårdade sig Herren om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 16, 'Sem och Set åtnjöto ära bland människor, men över alla levande varelser i skapelsen står Adam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 1, 'Simon, Onias’ son, översteprästen, satte under sin levnad Guds hus i stånd och befäste templet i sin tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 2, 'Av honom uppfördes muren, den höga ringmuren omkring helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 3, 'I hans tid blev en vattenbehållare uthuggen, en damm, lik ett hav i omfång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 4, 'Han sörjde för sitt folk, så att det ej skulle komma på fall, och gjorde staden stark mot belägringar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 5, 'Huru härlig tedde han sig icke, när han vände sig mot folket, när han trädde fram ur rummet bakom förlåten:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 6, 'lik morgonstjärnan mellan skyar, lik fullmånen under högtidsdagarna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 7, 'lik solen, när den lyser på den Högstes tempel, och lik bågen, när den skimrar bland glänsande skyar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 8, 'lik rosor i förstlingsfruktens tid, lik liljor vid vattenkällor, lik Libanons grönska under sommarens dagar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 9, 'lik brinnande rökelse i fyrfatet, lik ett kärl av gediget guld, prytt med allahanda dyrbara stenar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 10, 'lik ett olivträd med rildig frukt och lik en cypress som höjer sig mot molnen!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 11, 'När han tog på sig sin äreskrud och iklädde sig sin fulla ståt, när han steg upp på det heliga brännoffersaltaret, då spred han glans över helgedomens förgård.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 12, 'Och när han tog emot offerstyckena ur prästernas händer, medan han själv stod invid altarets härd, då omgåvo hans bröder honom såsom en krans, lika unga cedrar på Libanon; runt omkring honom stodo de lika palmstammar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 13, 'Ja, alla Arons söner stodo där i sin härlighet, med Herrens offer i sina händer, inför Israels hela menighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 14, 'Och till att avsluta tjänsten vid altaret och för att skönt fullända offret åt den Högste och Allsmäktige');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 15, 'sträckte han ut sin hand efter kannan och utgöt drickoffer av druvans blod; vid brännoffersaltarets fot utgöt han det, den Högste, alltings konung, till välbehaglig lukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 16, 'Då stötte Arons söner i basun och blåste i trumpeterna av drivet silver. De läto en stark trumpetklang ljuda för att bringa folket i åminnelse inför den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 17, 'Då skyndade på en gång allt folket att falla ned till jorden på sina ansikten för att tillbedja sin Herre, den allsmäktige Guden, den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 18, 'Och sångarna prisade honom med sina röster, och över de täta skarorna ljöd ljuvligt deras sång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 19, 'Och folket bad till Herren, den Högste, och tillbad inför den Barmhärtige, till dess hyllningen åt Herren var fullbordad och de hade avslutat gudstjänsten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 20, 'Sedan steg han ned och upplyfte sina händer över Israels barns hela menighet, för att utdela Herrens välsignelse med sina läppar och berömma sig av hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 21, 'Och ännu en gång föllo de ned för att mottaga välsignelsen från den Högste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 22, 'Och nu, prisen honom som är Gud över allting, honom som allestädes gör stora ting, som från moderlivet leder vår levnad uppåt, och som handlar med oss efter sin barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 23, 'Give han eder glädje i edra hjärtan, och låte han frid råda under våra dagar i Israel, likasom i fordom tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 24, 'Låte han sin barmhärtighet vila över oss, och när hans tid kommer, förlosse han oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 25, 'Över två folk harmas min själ, och det tredje är icke något folk:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 26, 'de sorn äro bosatta på Seirs berg och filistéerna och det dåraktiga folk som bor i Sikem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 27, 'Insiktsfylld och förståndig undervisning har jag upptecknat i denna bok, jag, Jesus, son till Eleasar, son till Syrak, från Jerusalem; och vishet har jag låtit flöda ur mitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 28, 'Säll är den som sysselsätter sig härmed; ja, den som lägger det på hjärtat, han varder vis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 29, 'Ty om han gör därefter, så skall han få kraft till allt, eftersom Herrens fruktan skall leda hans fjät.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 1, 'Jag vill tacka dig, Herre, konung, och prisa dig, Gud, min frälsare. Ja, jag tackar ditt namn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 2, 'därför att du har blivit min beskärmare och hjälpare och har förlossat mitt liv ifrån fördärvet och från den förtalande tungans snara, från deras läppar, som fara med lögn. Och inför mina motståndare har du bevisat dig såsom min hjälpare;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 3, 'du har förlossat mig, efter din stora barmhärtighet och enligt ditt stora namn, från deras rytande, som voro färdiga att uppsluka mig, från deras våld, som traktade efter mitt liv, från det myckna betryck som hade kommit över mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 4, 'från att kvävas av branden som omvärvde mig, och mitt ur den eld som jag icke själv hade tänt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 5, 'ur dödsrikets djupa svalg och från den orena tungan och det lögnaktiga talet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 6, 'från den orättfärdiga tungans pilar. Min själ nalkades döden, och mitt liv var nära dödsrikets djup.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 7, 'De omgåvo mig på alla sidor, och ingen fanns, som kunde hjälpa. Jag såg mig om efter bistånd från människor, men jag fann intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 8, 'Då tänkte jag på din barmhärtighet, o Herre, och på allt vad du har gjort av ålder, huru du befriar dem som förbida dig och frälsar dem ifrån fiendernas våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 9, 'Och jag lät mitt bönerop uppstiga från jorden och bad om räddning från döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 10, 'Jag anropade Herren, min fader och herre, att han icke skulle övergiva mig i nödens tid, i en stund då jag stod hjälplös mot övermodet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 11, 'Jag sade: »Jag vill prisa ditt namn beständigt och lovsjunga dig under tacksägelse.» Då blev min bön hörd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 12, 'ty du frälste mig ifrån fördärvet och befriade mig ifrån den onda tiden. Fördenskull vill jag tacka och prisa dig, ja, jag vill lova Herrens namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 13, 'Medan jag ännu var ung, och förrän jag hade begynt mina irrfärder, sökte jag, öppet inför alla, vishet i min bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 14, 'I min ungdom bad jag om henne, och intill mitt yttersta vill jag söka efter henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 15, 'Hon prunkade likasom en mognande druvklase; mitt hjärta fröjdade sig över henne. Min fot trädde in på en jämn väg; allt ifrån min ungdom har jag följt hennes spår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 16, 'Något litet böjde jag mitt öra till henne och mottog hennes ord, och jag inhämtade mycken lärdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 17, 'Mer och mer förkovrades Jag däri; ära vill jag giva honom som förlänade mig visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 18, 'Jag tänkte efter, huru jag skulle handla enligt hennes bud, jag nitälskade för det goda; och jag skall aldrig komma på skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 19, 'Min själ har kämpat med henne, och noggrannhet iakttog jag i allt vad jag gjorde. Jag uträckte mina händer mot höjden och sörjde över mina förseelser mot henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 20, 'Jag vände min håg till henne och fann henne i hennes renhet. Förstånd förvärvade jag hos henne allt ifrån begynnelsen; fördenskull skall jag icke bliva övergiven av henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 21, 'Ja, i mitt innersta var jag upptänd av iver att söka efter henne; fördenskull förvärvade jag mig ock en dyrbar skatt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 22, 'Herren gav mig min tungas konst såsom min lön, och med den vill jag prisa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 23, 'Så kommen då hit till mig, I olärde, och dväljens i mitt lärohus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 24, 'Sägen, varför stån I ännu tillbaka i dessa stycken, och varför skola edra själar plågas av så svår törst?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 25, 'Jag har upplåtit min mun och talat; förvärven eder nu vishet utan penningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 26, 'Bojen eder hals under hennes ok, och låten eder själ mottaga undervisning. Nära är hon, så att I kunnen finna henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 27, 'Sen med egna ögon att jag har gjort mig allenast ringa möda, men att jag dock har vunnit mycken ro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 28, 'Om I än köpen undervisning för en stor summa silver, så skolen I dock förvärva guld i myckenhet med den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 29, 'Eder själ fröjde sig över Guds barmhärtighet; och blygens icke för att prisa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 30, 'Utfören edert verk, medan tid är; när hans tid kommer, skall han då låta eder undfå eder lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Detta är vad som stod i den bok som Baruk, son till Nerias, son till Maaseas, son till Sedekias, son till Hasadias, son till Kelkias, skrev i Babylonien');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'i det femte året, på sjunde dagen i månaden, vid den tid då kaldéerna hade intagit Jerusalem och uppbränt det i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Och Baruk läste upp det som stod i denna bok inför Jekonias, Joakims son, Juda konung, och inför allt folket, så många som kommo för att höra därpå,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'och inför de mäktige och konungasönerna och inför de äldste och inför allt folket, både små och stora, alla dem som bodde i Babylonien, vid floden Sud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Och de gräto och fastade och bådo inför Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Och de samlade in penningar, efter som var och en förmådde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'och sände dem till Jerusalem, till översteprästen Joakim, son till Kelkias, son till Salom, och till prästerna och till allt folket, så många som med honom befunno sig i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Och samtidigt, på tionde dagen i månaden Sivan, lät Baruk hämta de kärl som hade tillhört Herrens hus, men som hade blivit bortförda från templet, och sände dem tillbaka till Juda land, nämligen ett antal silverkärl som Sedekias, Josias\' son, Juda konung, hade låtit göra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'sedan Nebukadnessar, konungen i Babylonien, hade fört bort ifrån Jerusalem Jekonias, så ock furstarna och fångarna och de mäktige och det meniga folket, och låtit dem komma till Babylonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Och de skrevo följande: Här sända vi till eder penningar; köpen nu för dessa penningar djur till brännoffer och syndoffer, så ock rökelse, och reden till spisoffer, och frambären så offer på Herrens, vår Guds, altare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'och bedjen för den babyloniske konungen Nebukadnessars liv och för hans son Baltasars liv, att deras levnad må räcka lika länge som himmelen välver sig över jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Då skall Herren giva oss styrka och låta ljus gå upp för våra ögon; och vi skola få leva under den babyloniske konungen Nebukadnessars skugga och under hans son Baltasars skugga och skola tjäna dem i lång tid och finna nåd inför dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Och bedjen för oss till Herren, vår Gud, ty vi hava syndat mot Herren, vår Gud; och Herrens förtörnelse och vrede har icke vänt sig ifrån oss ända till denna dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Och den skrivelse som vi nu här sända eder mån I läsa upp i Herrens hus, såsom en syndabekännelse, på högtidsdagen och på övriga festdagar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'sägen så: »Herren, vår Gud, är rättfärdig, men vi måste blygas, såsom vi ock nu göra, vi, Juda män och Jerusalems invånare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'våra konungar och våra furstar, våra präster och våra profeter och våra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Ty vi hava syndat mot Herren');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'och varit olydiga mot honom och hava icke hört Herrens, vår Guds, röst, så att vi hava vandrat efter de stadgar som Herren har förelagt oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Nej, ända ifrån den dag då Herren förde våra fäder ut ur Egyptens land och intill denna dag hava vi varit olydiga mot Herren, vår Gud, och varit svårt försumliga i att höra hans röst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Så har nu ock den olycka och den förbannelse kommit att vila på oss, som Herren förkunnade för sin tjänare Moses, på den dag då han förde våra fäder ut ur Egyptens land, för att giva oss ett land som flöt av mjölk och honung, såsom ock nu har skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Ja, vi hava icke hört Herrens, vår Guds, röst i enlighet med allt vad de profeter hava talat, som han har sänt till oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'utan vi hava gått bort, var och en i sitt onda hjärtas tankar, till att tjäna andra gudar och göra vad ont är i Herrens, vår Guds, ögon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Och så lät Herren det ord gå i uppfyllelse, som han hade talat mot oss och mot våra domare, dem som dömde Israel, och mot våra konungar och mot våra furstar och mot Israels och Juda män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Han lät nämligen en så stor olycka komma över oss, att ingenstädes under himmelen något sådant har skett, som det som nu har skett i Jerusalem, i enlighet med vad som står skrivet i Moses\' lag,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'att vi skulle nödgas äta, den ene sin sons och den andre sin dotters kött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ja, han gav dem i alla de rikens våld, som lågo runt omkring oss, och gjorde dem till ett föremål för smälek och till ett exempel på förödelse bland alla de folk som bodde runt omkring oss, bland vilka Herren förströdde dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Och de måste’ligga under’ och fingo icke’ligga över’, eftersom vi hade syndat mot Herren, vår Gud, och icke hört hans röst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Herren, vår Gud, är rättfärdig, men vi och våra fäder måste blygas, såsom vi ock nu göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'All den olycka som Herren lät förkunna mot oss, den har nu kommit över oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Och vi bönföllo icke inför Herren och vände icke om, var och en från sitt onda hjärtas tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Därför vakade ock Herren över att olyckan drabbade oss; ty Herren är rättfärdig i alla de gärningar som han har beslutit att göra med oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Men vi hörde icke Herrens röst, så att vi vandrade efter de stadgar som han har förelagt oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Och nu, Herre, du Israels Gud, du som förde ditt folk ut ur Egyptens land med stark hand och med tecken och under och med stor kraft och upplyft arm och så gjorde dig ett namn, som är detsamma än i dag!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Vi hava syndat, vi hava varit ogudaktiga, vi hava varit orättfärdiga, o Herre, vår Gud, i fråga om allt vad du har stadgat såsom rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Låt nu din förtörnelse vända sig ifrån oss, ty vi äro allenast några få som hava lämnats kvar bland de folk bland vilka du har förstrött oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Hör, o Herre, vår åkallan och vår bön, och befria oss för din egen skull, och låt oss finna nåd för deras ögon, som hava fört oss bort i fångenskap,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'på det att hela jorden må få lära känna att du är Herren, vår Gud, eftersom ju Israel och hans ätt äro uppkallade efter ditt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Herre, skåda ned från din heliga boning, och akta på oss; böj, o Herre, ditt öra härtill och hör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Öppna, Herre, dina ögon och se; ty de döda i dödsriket, de vilkas ande är tagen bort ur deras bröst, giva ju icke Herren ära och erkänna icke hans rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Men den själ som är djupt bedrövad, den som går där nedböjd och maktlös, och de ögon som förtvina, och den själ som hungrar, de giva dig ära och erkänna din rättfärdighet, o Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Det är ju icke i förlitande på vad rättfärdigt våra fäder och våra konungar hava gjort, som vi bönfalla inför dig, Herre, vår Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Ty du har släppt lös din vrede och förtörnelse över oss, i enlighet med vad du har talat genom dina tjänare profeterna. Du sade ju:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, '\'Så säger Herren: Bojen edra skuldror och tjänen konungen i Babylonien, så skolen 1 få bo kvar i det land som jag har givit åt edra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Men om I icke hören Herrens röst och tjänen konungen i Babylonien,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'så skall jag i Juda städer och i Jerusalem göra slut på fröjderop och glädjerop, på rop för brudgum och rop för brud, och hela landet skall bliva ödelagt, så att ingen mer bor däri.’');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Men vi hörde icke din röst och tjänade icke konungen i Babylonien; och då lät du de ord gå i uppfyllelse, som du hade talat genom dina tjänare profeterna, nämligen att våra konungars ben och våra fäders ben skulle kastas ut ur deras gravar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Och se, nu ligga de kringströdda, prisgivna åt hettan om dagen och åt kölden om natten. Och de hade omkommit genom svåra plågor, genom hunger och svärd och andra hemsökelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Och du har gjort det hus som är uppkallat efter ditt namn till vad det nu är, för Israels hus’ och Juda hus’ ondskas skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Men med oss har du, Herre, vår Gud, handlat efter all din mildhet och efter all din stora barmhärtighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'i enlighet med vad du har talat genom din tjänare Moses, på den tid då du bjöd honom att uppteckna din lag inför Israels barn, i det att du sade: 29’Om I icke hören min röst, så skall förvisso denna stora och talrika brusande folkskara varda till en ringa hop bland de folk bland vilka jag skall förströ dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 30, 'Ty jag vet att de icke skola höra mig, eftersom det är ett hårdnackat folk. Men de skola besinna sig i det land där de leva i fångenskap,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 31, 'och de skola förnimma att jag är Herren, deras Gud. Och jag skall giva dem hjärtan, och öron som höra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 32, 'och de skola prisa mig i det land där de leva i fångenskap och skola tänka på mitt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 33, 'Och de skola omvända sig från sin hårdnackenhet och från sina onda gärningar, ty de skola komma ihåg huru det gick deras fäder, när dessa syndade mot Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 34, 'Då skall jag låta dem komma tillbaka till det land som jag med ed har lovat deras fäder, Abraham, Isak och Jakob; och de skola bemäktiga sig det. Och jag skall föröka dem, och de skola icke vidare förminskas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 35, 'Och jag skall med dem upprätta ett evigt förbund, att jag skall vara deras Gud, och att de skola vara mitt folk; och jag skall icke vidare låta mitt folk Israel flytta bort ifrån det land som jag har givit dem.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Herre, du Allsmäktige, du Israels Gud, ett betryckt sinne och en bedrövad ande ropar till dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Hör, o Herre, och förbarma dig, ty du är en barmhärtig Gud; ja, förbarma dig, ty vi hava syndat mot dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Du tronar ju till evig tid, men vi förgås till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Herre, du Allsmäktige, du Israels Gud, hör den bön som uppsändes av de döda bland Israel och av barnen till dem som syndade mot dig, dessa som icke hörde på vad du, deras Gud, hade talat, varför ock olyckan nu vilar på oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Tänk icke på våra fäders missgärningar, utan tänk nu i denna tid på din arm och på ditt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Ty du är Herren, vår Gud, och vi vilja prisa dig, o Herre;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'det är ju därför som du har ingivit din fruktan i våra hjärtan, så ock förmågan att åkalla ditt namn. Ja, vi vilja prisa dig i det land där vi leva i fångenskap, ty vi hava från våra hjärtan skilt all den orättfärdighet som våra fäder begingo, de som syndade mot dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Se, ännu i denna dag leva vi här i vår fångenskap, i det land dit du har fördrivit oss, till att vara ett föremål för smälek och förbannelse, och till att göra bot för alla de missgärningar som våra fäder hava begått, de som avföllo från Herren, vår Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Hör, o Israel, livets bud, lyssnen, så att I lären förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Varav kommer det, Israel, varav kommer det att du är i fiendeland, att du har åldrats i främmande land, att du har blivit oren likasom de döda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'att du har blivit aktad lik dem som hava farit ned i dödsriket?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Jo, du har övergivit vishetens källa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Om du hade vandrat på Guds väg, så skulle du hava fått bo i trygghet för alltid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Så låt nu lära dig var man finner förstånd, var man finner styrka och insikt, för att du tillika må förnimma var man finner lång levnad och liv, var ljus för ögonen och var frid äro att finna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Vem har funnit den plats där visheten bor, och vem har trätt in i hennes förrådshus?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Var äro folkens furstar och de som härskade över markens djur?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Var äro de som lekte med himmelens fåglar och samlade silver och guld, som människorna satte sin lit till? Ja, det fanns icke någon gräns för deras förvärv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Var äro de som arbetade i silver med sådan omsorg att man icke kan utgrunda deras verk?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'De hava försvunnit och farit ned i dödsriket, och andra hava uppstått i deras ställe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Yngre släkten fingo se ljuset, och de fingo bo på jorden, men vishetens väg lärde de icke känna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'och förstodo icke hennes stigar; ej heller deras barn vinnlade sig om henne, utan de höllo sig fjärran ifrån hennes väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Icke hörde man om henne i Kanaan, och ej skådade man henne i Teman.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Och Hagars barn, som sökte efter insikt på jorden, köpmännen från Merran och Teman, och fabeldiktarna och kunskapssökarna - vishetens väg lärde de icke känna, och hennes stigar hade de icke i minne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'O Israel, huru stor är icke Guds boning, och huru vidsträckt det hus som han besitter!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Stort är det och utan ände, högt är det och utan mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Där blevo jättarna till, de allt ifrån urtiden namnkunniga; väldiga voro de till gestalt, förfarna i att strida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Men icke var det dessa som Gud utvalde, och icke var det för dem som han öppnade väg till visheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Nej, de förgingos, eftersom de icke hade förstånd, de förgingos för sin oförnuftighets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Vem har farit upp till himmelen och hämtat visheten och fört henne ned från molnen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Vem har farit tvärs över havet och funnit henne, och vem kan förvärva henne för utvalt guld?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Ingen finnes, som känner hennes väg, och ingen som aktar på hennes stig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 32, 'Men han som vet allting, han känner henne; han har funnit henne genom sin insikt, han som har danat jorden för evig tid och uppfyllt den med fyrfotadjur;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 33, 'han som sänder ljungelden åstad, och den går, som kallar på den, och den lyder honom med bävan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 34, 'Och stjärnorna lysa på sina poster och glädja sig; 35');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 35, 'han kallar på dem, och de svara: »Här äro vi.» De lysa med glädje inför honom som har skapat dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 36, 'Sådan är vår Gud; ingen annan gäller något i jämförelse med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 37, 'Han utrönte all vishetens väg och gav henne åt Jakob, sin tjänare, och åt Israel, sin älskade. Därefter blev hon skådad på jorden och hade sin umgängelse bland människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Hon är boken med Guds stadgar och lagen som består evinnerligen. Alla de som hålla fast vid henne, de skola vinna liv, men de som Övergiva henne skola dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Vänd om, du Jakob, och sök att vinna henne; vandra framåt efter hennes sken, i det ljus hon sprider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Giv icke din ära åt en annan eller dina förmåner åt ett främmande folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'O Israel, saliga äro vi, ty det som täckes Gud har blivit oss kunnigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Var vid gott mod, mitt folk, du som bär namnet Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'I haven blivit sålda åt hednafolken, dock icke till undergång; därför att I haven förtörnat Gud, haven I blivit givna till pris åt edra motståndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'I haven ju retat honom som har skapat eder, genom att offra åt onda andar i stället för åt Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'I haven förgätit honom som har fostrat eder, den evige Guden, I haven ock bedrövat henne som har uppfött eder, Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ty hon såg den vredesdom som nu har kommit över eder från Gud. Hon sade: »Lyssnen härtill, I som bon omkring Sion, ty Gud har låtit en svår bedrövelse drabba mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Jag har sett mina söner och döttrar föras bort i den fångenskap som den Evige har låtit drabba dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Ty med glädje har jag uppfött dem, men med gråt och bedrövelse har jag måst släppa dem ifrån mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Må ingen glädja sig över mig, i en värnlös änka, som har övergivits av så många. Det är för mina barns synders skull som jag har lämnats ensam, därför att de veko av ifrån Guds lag');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'och icke ville veta av hans stadgar; de vandrade ju icke på Guds buds vägar och trädde ej in på de stigar där han ville fostra dem i rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Kommen hit, I som bon omkring Sion, och betänken huru mina söner och döttrar hava blivit bortförda i den fångenskap som den Evige har låtit drabba dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Ty han har skickat över dem ett folk fjärran ifrån, ett fräckt folk, med främmande tungomål, som icke hade försyn för de gamla och ej någon misskund med de unga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'utan ryckte bort ifrån änkan hennes älskade söner och berövade den ensamma hennes döttrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Men jag - huru skulle väl jag förmå att hjälpa eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Nej han som nar låtit olyckan drabba eder, han skall ock befria eder ur edra fienders hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Dragen bort, mina barn, dragen bort; jag måste ju vara övergiven och ensam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Jag har tagit av mig lyckans skrud och iklätt mig min böndräkt av säcktyg; jag vill ropa till den Evige, så länge jag är till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Varen vid gott mod, mina barn, och ropen till Gud, så skall han befria eder från övermakten, ifrån fiendernas hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Ty på den Evige har jag grundat mitt hopp om eder frälsning, och glädje har kommit mig till del från den Helige, för den barmhärtighets skull som inom kort skall vederfaras eder från den Evige, eder frälsare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Väl måste jag släppa eder ifrån mig med bedrövelse och gråt, men Gud skall giva eder tillbaka åt mig, med fröjd och glädje till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Ty likasom de som bo omkring Sion nu hava sett eder föras bort såsom fångar, så skola de inom kort få skåda den frälsning ifrån eder Gud, som skall komma eder till del, med stor härlighet och glans från den Evige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Mina barn, fördragen med tålamod den vredesdom som har kommit över eder från Gud. Ty väl har din fiende hårt ansatt dig, men du skall inom kort få skåda hans undergång, och du skall få sätta din fot på hans hals.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 26, 'Mina förklemade barn fingo vandra oländiga vägar, de blevo bortförda såsom en hjord som har rövats av fiender.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 27, 'Men våren vid gott mod, mina barn, och ropen till Gud. Ty han som har låtit detta ske, han skall åter tänka på eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 28, 'Ja, såsom eder håg förut stod till att gå bort ifrån Gud, så vänden nu om och söken honom med tiofaldig iver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 29, 'Ty han som har låtit denna olycka vederfaras eder, han skall ock låta den eviga glädjen vederfaras eder, då när han förlänar eder frälsning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 30, 'Var vid gott mod, Jerusalem! Han som har givit dig ditt namn, han skall trösta dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 31, 'Olyckliga de som misshandlade dig, och som gladde sig över ditt fall!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 32, 'Olyckliga de städer som dina barn måste tjäna! Olycklig hon som tog emot dina söner!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 33, 'Ty såsom hon gladde sig över ditt fall och fröjdade sig över din undergång, så skall hon få sörja över att själv vara övergiven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 34, 'Och jag skall taga bort ifrån henne den larmande mängdens jubel, och hennes stolta skryt skall vändas i bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 35, 'Ty eld skall från den Evige komma över henne intill en avlägsen framtid, och av onda andar skall hon bliva bebodd i lång tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 36, 'Lyft upp dina ögon mot öster, Jerusalem, och skåda den glädje som kommer till dig från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 37, 'Se, där komma dina söner, de som du måste släppa ifrån dig; de komma, församlade från både öster och väster, på den Heliges bud, uppfyllda av glädje över Guds härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Tag av dig, Jerusalem, den bedrövelsens och lidandets dräkt du bär, och ikläd dig för evigt Guds härlighets sköna skrud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Hölj dig i Guds rättfärdighets mantel, sätt på ditt huvud den Eviges härlighets diadem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Ty Gud skall visa din glans för all världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Ja, det namn du skall få ifrån Gud för evig tid skall vara »Rättfärdighetens frid» och »Gudsfruktans härlighet».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Stå upp, Jerusalem, och ställ dig på höjden; lyft upp dina ögon mot öster och se dina barn komma, församlade från både väster och öster, på den Heliges bud, uppfyllda av glädje över att Gud har kommit ihåg dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ty väl drogo de bort ifrån dig till fots, drivna åstad av fienderna, men Gud för dem nu åter till dig, högt burna i härlighet såsom på en konungatron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Ja, Gud har bjudit att alla höga berg skola sänkas, så ock de eviga kullarna, och att dalarna skola fyllas, så att det bliver slät mark, på det att Israel må vandra framåt i trygghet, under hägnet av Guds härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Och skogarna och alla doftande träd skänka skugga åt Israel på Guds befallning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Ja, Gud skall leda Israel under glädje, i ljuset av sin härlighet, med den barmhärtighet och rättfärdighet som kommer från honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Detta är en avskrift av ett brev som Jeremias sände till dem som av babyloniernas konung skulle föras bort såsom fångar till Babylonien, och vari han kungjorde för dem vad som hade blivit honom befallt av Gud. För de synders skull som I haven begått mot Gud skolen I av Nebukadnessar, babyloniernas konung, föras bort såsom fångar till Babylonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'När I nu haven kommit till Babylonien, skolen I stanna där i många år, ja, under en lång tid, intill dess sju mansåldrar hava gått till ända. Men sedan skall jag föra eder ut därifrån i frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Nu skolen I där i Babylonien få se avgudar av silver och guld och trä, som man bär på sina axlar, men som likväl väcka fruktan hos hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Tagen eder då till vara, så att icke också I bliven lika främlingarna och låten eder intagas av fruktan för avgudarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'när I fån se huru människoskarorna framför dem och bakom dem falla ned och tillbedja dem. Tanken i stället i edert sinne: »Dig, Herre, skall man tillbedja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Ty min ängel är med eder, och han skall skydda edra liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Avgudabildernas tungor äro snidade av hantverkare, och själva äro de överdragna med guld och silver; lögn äro de, och de kunna icke tala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Och såsom gällde det en jungfru som gärna smyckar sig, så taga de guld');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'och förfärdiga därav kransar till att sätta på sina avgudars huvuden. Det händer till och med att prästerna från sina avgudar taga undan guld och silver och använda det för sitt eget behov;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'ja, att de jämväl åt skökorna i skökohuset giva av sina avgudars egendom. Vidare pryda de dem, dessa avgudar av silver och avgudar av guld och trä, med kläder såsom människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Men de kunna icke skydda sig för rost och maskar, fastän de äro höljda i purpmr-dräkter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Man måste avtorka deras ansikten för det damms skull som röres upp i tempelbyggnaden, och som i ymnighet lägger sig på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'En spira har avguden också, likasom en styresman över ett land, han som dock icke kan förgöra den som förbryter sig mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Och en yxa håller han i handen, så ock ett annat stridsredskap, men han kan icke rädda sig själv från krig och rövare. Härav kan nian förstå att de inga gudar äro. Frukten alltså icke för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Såsom ett kärl som en människa brukar bliver odugligt, när det går sönder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'så är det ju ock med deras avgudar. Där de stå uppställda i templen, äro deras ögon fulla av dammet som röres upp av de inträdandes steg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Och såsom man spärrar igen alla utgångar för någon som har förbrutit sig mot en konung, då ju en sådan har förverkat sitt liv, så stänga prästerna till avgudarnas hus med dörrar, riglar och bommar, för att de icke skola stjälas bort av rövare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'De tända lampor åt dem, till och med flera än åt sig själva; och dock kunna avgudarna icke se en enda av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Det är med dem såsom med bjälkarna som sitta i tempelbyggnaden. Det säges att de uppfrätas i sitt inre; och maskarna ur jorden äta upp både dem och deras kläder, utan att de förnimma det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'De äro svärtade i sina ansikten av röken i tempelbyggnaden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Flädermöss, svalor och andra fåglar komma flygande och slå ned på deras kroppar och huvuden; ja, till och med kattor komma och sätta sig där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Härav kunnen I förstå att de inga gudar äro. Frukten alltså icke för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'De äro visserligen överdragna med guld för att se sköna ut; men om man icke gnider av rostfläckarna, så blänka de alls icke. De hade ju ej heller, medan de blevo gjutna, någon förnimmelse därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 24, 'De hava blivit köpta till vad pris som helst, dessa som dock icke hava någon livsande i sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 25, 'Eftersom de icke hava några fötter, måste man bära dem på axlarna; och så lägga de sin ömklighet i dagen för människorna. Och jämväl de som göra tjänst inför dem måste skämmas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 26, 'Ty avgudarna kunna icke resa upp sig av sig själva, om de skulle falla till marken, och de kunna icke röra sig av sig själva, om man en gång har ställt dem upprätt, ej heller kunna de räta upp sig, om de komma i lutande ställning; nej, såsom för de döda får man sätta fram sina offergåvor för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 27, 'Och det som offras åt dem avyttra deras präster och använda till sin egen nytta. Likaledes taga ock deras hustrur av offerköttet och salta in, men de dela icke med sig åt den fattige eller behövande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 28, 'Kvinnor som hava sin månadsrening och barnaföderskor få vidröra deras offer. Då I alltså härav kunnen förstå att de inga gudar äro, så mån I icke frukta för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 29, 'Ja, varför skulle de kallas gudar? Kvinnor sätta ju fram mat åt dessa avgudar av silver och guld och trä.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 30, 'Och i deras tempel sitta prästerna med sönderrivna kläder och med avrakat hår och skägg och blottade huvuden');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 31, 'och tjuta och ropa inför sina avgudar, såsom somliga göra vid dödsmåltider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 32, 'Prästerna taga sig stycken av avgudarnas kläder och bekläda sina hustrur och barn därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 33, 'Vare sig man låter dem få röna något ont eller något gott, äro de ur stånd att vedergälla det. De kunna varken tillsätta eller avsätta en konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 34, 'Lika litet kunna de förläna gods eller penningar. Om någon gör ett löfte åt dem och icke infriar det, så kunna de aldrig utkräva det som har blivit dem lovat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 35, 'De förmå icke att rädda en människa från döden, ej heller att befria en svagare från hans överman.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 36, 'Åt en blind kunna de icke giva tillbaka hans syn; en människa som befinner sig i nöd kunna de icke hjälpa därur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 37, 'En änka kunna de icke bevisa barmhärtighet, ej heller kunna de öva välgörenhet mot en som är faderlös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 38, 'Lika stenar som hava huggits ur klippan äro dessa träbeläten och dessa med guld eller silver överdragna bilder; de som göra tjänst inför dem komma ock på skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 39, 'Huru skulle alltså dessa kunna anses för gudar eller kallas så?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 40, 'Ja, än mer; kaldéerna själva draga vanära över dem, i det att de, när de se någon som är stum och icke kan tala, föra fram en bild av Bel och bedja den att den stumme skall kunna tala, som om den kunde förstå något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 41, 'Och dessa kunna icke inse detta och så vända dem ryggen; ty de hava intet förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 42, 'Och kvinnorna sitta där vid vägarna, med bindor på sig, och bränna sitt rökverk av kli.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 43, 'Men när en av dem har blivit förd avsides och lägrad av någon som går därförbi, då smädar hon den kvinna som sitter näst intill henne, därför att icke denna har rönt samma heder som hon själv och icke har fått sin binda avsliten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 44, 'Allt vad som sker med avgudarna är bedrägeri. Huru skulle alltså dessa kunna anses för gudar eller kallas så?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 45, 'Av hantverkare och guldsmeder äro de förfärdigade, och de kunna aldrig bliva något annat än vad konstnärerna vilja att de skola bliva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 46, 'Då nu de som förfärdiga dem icke själva hava någon lång tillvaro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 47, 'huru kan man väl då vänta att de som hava blivit förfärdigade av dem kunna få det? Nej, lögn och smälek är vad de lämna efter sig åt de efterlevande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 48, 'Ty när dessa avgudar hemsökas av krig och annan olycka, rådslå prästerna med varandra om var de skola kunna gömma sig tillsammans med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 49, 'Huru kan man alltså undgå att märka att de inga gudar äro, dessa som icke kunna rädda sig själva vare sig undan krig eller annan olycka?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 50, 'Eftersom de ju äro allenast träbeläten och bilder överdragna med guld eller silver, skall det en gång bliva kunnigt att de äro lögn. För alla folk och konungar skall det bliva uppenbart att de inga gudar äro, utan verk av människohänder, och att ingen gudomlig kraft finnes i dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 51, 'Vem skulle alltså kunna undgå att inse att de inga gudar äro?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 52, 'De kunna ju icke tillsätta en konung i ett land; ej heller kunna de giva regn åt människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 53, 'I sin vanmakt kunna de varken skaffa sig själva rätt eller avvärja en oförrätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 54, 'Ja, de äro lika kråkorna, som flyga mellan himmel och jord. Och om eld kommer lös i avgudarnas hus, dessa avgudars vilka äro av trä eller äro överdragna med guld eller silver, så fly deras präster och rädda sig undan, men de själva förbrinna ända igenom såsom träbjälkar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 55, 'Mot en konung eller mot fiender kunna de icke göra något motstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 56, 'Huru skulle man då kunna gå in på eller anse att de äro gudar? Varken undan tjuvar eller undan rövare kunna de rädda sig, dessa avgudar som äro av trä eller äro överdragna med silver eller guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 57, 'De som få dem i sitt våld taga bort guldet, och silvret på dem och gå sin väg med de kläder som de äro iförda, utan att de kunna hjälpa sig själva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 58, 'Således är det bättre att vara en konung, som lägger sin tapperhet i dagen, eller ett husgeråd, som är nyttigt för det ändamål vartill dess ägare vill begagna det, än att vara en sådan falsk gud. Ja, till och med en dörr i ett hus, vilken skyddar det som finnes därinne, är förmer än dessa falska gudar; och en träpelare i ett palats är förmer än dessa falska gudar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 59, 'Solen och månen och stjärnorna, som lysa och utsändas för sina ändamål, lyda villigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 60, 'Likaså är ljungelden, när den visar sig, skön att skåda. Så är det ock med vinden, som blåser i alla länder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 61, 'Och när molnen få befallning av Gud att fara ut över hela jordkretsen, då fullborda de det som har blivit dem befallt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 62, 'Och när elden sändes ut från ovan till att förtära berg och skogar, då gör den det som har blivit den bjudet. Men dessa avgudar, de hava varken till skapnad eller verkningskraft någon likhet med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 63, 'Fördenskull böra de varken anses för gudar eller kallas så; de äro ju ej heller i stånd till att vare sig fälla dom eller göra väl mot människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 64, 'Då I alltså kunnen förstå att de inga gudar äro, så mån I icke frukta för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 65, 'Konungar kunna de ju varken förbanna eller välsigna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 66, 'De kunna icke låta några tecken visa sig på himmelen för folken; ej heller kunna de lysa såsom solen eller skina såsom månen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 67, 'Djuren på marken äro bättre än de; ty dessa kunna fly in i sina gömslen och så hjälpa sig själva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 68, 'På intet sätt visar det sig alltså för oss att de äro gudar. Frukten fördenskull icke för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 69, 'Ja, såsom en fågelskrämma på ett gurkfält, vilken icke giver något skydd, äro deras avgudar, dessa som äro av trä eller äro överdragna med guld eller silver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 70, 'Vid en törnhäck omkring en trädgård, som alla slags fåglar slå ned på, eller vid en död kropp som ligger utkastad i mörkret kunna de sammalunda förliknas, dessa deras avgudar, som äro av trä eller äro överdragna med guld eller silver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 71, 'Redan deras multnande kläder av purpur och linne lära oss förstå att de inga gudar äro. Till sist bliva de också själva sönderfrätta och bliva till smälek i landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 72, 'Bättre är alltså den som är rättfärdig och icke har några avgudabilder. Ty han går fri ifrån försmädelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 73, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Tillägg till Daniel 3,23: Asarias bekänner sitt folks och sina egna synder och beder om hjälp. Herrens ängel räddar honom och hans vänner från att förtäras av elden. Men de tre männen gingo omkring mitt ibland lågorna och lovsjöngo Gud och prisade Herren. ej gjort vad du har bjudit oss, för att det skulle gå oss väl. den med bergolja och tjära och blår och torrt ris.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Och Asarias ställde sig där, jämte de andra, och bad denna bön; han upplät sin mun mitt i elden och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Lovad vare du, Herre, våra fäders Gud, och prisat och förhärligat vare ditt namn evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Ty du är rättfärdig i allt vad du har gjort mot oss, och alla dina gärningar äro rättvisa, och dina vägar äro rätta, och alla dina domar äro sannfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Ja, sannfärdiga domar har du utfört vid allt vad du har låtit komma över oss och över Jerusalem, våra fäders heliga stad. Med sanning och rätt har du låtit allt detta komma över oss för våra synders skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Ty vi hava syndat och handlat ogudaktigt genom att avfalla från dig, ja, vi hava svårt försyndat oss i alla stycken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Vi hava icke hörsammat dina bud eller tagit dem i akt');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Ja, allt som du har låtit komma över oss och allt som du har gjort mot oss, det har du gjort med rättvis dom:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'du har överlämnat oss i fienders händer, i ogudaktiga, hätska avfällingars händer, och åt en orättfärdig konung, den ondskefullaste på hela jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Och nu kunna vi icke upplåta vår mun; skam och smälek hava drabbat dina tjänare och dem som frukta dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Övergiv oss dock ej helt och hållet, för ditt namns skull, och bryt icke ditt förbund,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'och låt icke din barmhärtighet vika ifrån oss, för Abrahams, din väns, skull och för Isaks, din tjänares, skull och för Israels, din heliges, skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Du lovade ju dem att du ville göra deras säd talrik såsom stjärnorna på himmelen och såsom sanden på havets strand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Men nu hava vi, o Herre, blivit ringare än något annat folk och leva denna dag i betryck överallt på jorden, för våra synders skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Och i denna stund hava vi icke någon furste eller någon profet eller ledare, ej heller kunna vi längre frambära något brännoffer eller slaktoffer eller något spisoffer eller någon rökelse, ej heller hava vi någon plats där vi kunna offra inför ditt ansikte och så finna barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Men låt oss bliva nådigt mottagna, med förkrossat hjärta och ödmjuk ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'likasom frambure vi brännoffer av vädurar och tjurar eller feta lamm i tiotusental. Låt vårt offer så gälla inför ditt ansikte i dag, och giv att vi i allt må efterfölja dig. Ty de som förtrösta på dig komma icke på skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Och nu följa vi dig av allt hjärta och frukta dig och söka ditt ansikte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Låt oss icke komma på skam, utan handla rned oss efter din mildhet och efter din stora barmhärtighet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'förlossa oss i enlighet med dina underbara gärningar, och förhärliga ditt namn, o Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Och låt alla dem som göra dina tjänare något ont få blygas, låt dem komma på skam med all sin makt och allt sitt herravälde, och låt deras styrka bliva krossad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'så att de få förnimma att du är Herren, allena Gud, och att du är ärad över hela världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Men konungens tjänare, vilka det ålåg att kasta dem i ugnen, upphörde icke att elda');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Och lågan steg upp ända till fyrtionio alnar över ugnen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'och den slog ut åt sidorna och förtärde dem av kaldéerna omkring ugnen, vilka nåddes av den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Men Herrens ängel hade stigit ned i ugnen tillsammans med Asarias och hans vänner, och han drev ut eldslågan ur ugnen och gjorde så,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'att ugnens inre var såsom genomsusat av en daggfrisk vind. Och elden kom icke alls vid dem och gjorde dem icke någon skada eller något men.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Då sjöngo de tre såsom med en mun en lovsång och förhärligade och prisade Gud i ugnen. De sjöngo:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Lovad vare du, o Herre, våra fäders Gud, och prisad och upphöjd i evighet; lovat vare ditt heliga och härliga namn och högt prisat och upphöjt i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Lovad vare du i din heliga härlighets tempel och högt lovsjungen och ärad i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Lovad vare du, där du tronar på keruberna och skådar ned i djupen, och prisad och upphöjd i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 32, 'Lovad vare du på ditt rikes tron och högt lovsjungen och upphöjd i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 33, 'Lovad vare du på himmelens fäste och lovsjungen och förhärligad i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 34, 'Loven Herren, I alla Herrens verk, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 35, 'Loven Herren, I Herrens änglar, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 36, 'Loven Herren, I himlar, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 37, 'Loven Herren, alla vatten ovan himmelen, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 38, 'Loven Herren, I alla Herrens härskaror, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 39, 'Loven Herren, sol och måne, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 40, 'Loven Herren, himmelens stjärnor, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 41, 'Loven Herren, allt regn och all dagg, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 42, 'Loven Herren, alla vindar, lovsjungen och upphöjen honom i evighet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 43, 'Loven Herren, eld och hetta, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 44, 'Loven Herren, frost och köld, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 45, 'Loven Herren, rimfrost och snö, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 46, 'Loven Herren, nätter och dagar, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 47, 'Loven Herren, ljus och mörker, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 48, 'Loven Herren, ljungeldar och moln, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 49, 'Love jorden Herren, lovsjunge och upphöje den honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 50, 'Loven Herren, berg och höjder, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 51, 'Loven Herren, alla växter på jorden, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 52, 'Loven Herren, I källor, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 53, 'Loven Herren, hav och floder, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 54, 'Loven Herren, I havsvidunder och alla djur som röra sig i vattnet, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 55, 'Loven Herren, alla himmelens fåglar, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 56, 'Loven Herren, alla vilda djur och boskapsdjur, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 57, 'Loven Herren, I människors barn, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 58, 'Lova Herren, o Israel, lovsjung och upphöj honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 59, 'Loven Herren, I Herrens präster, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 60, 'Loven Herren, I Herrens tjänare, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 61, 'Loven Herren, I de rättfärdigas andar och själar, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 62, 'Loven Herren, I fromme och i hjärtat ödmjuke, lovsjungen och upphöjen honom i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 63, 'Loven Herren, Ananias, Asarias och Misael, lovsjungen och upphöjen honom i evighet. Ty han har förlossat oss ur dödsriket och räddat oss ur dödens våld; han har frälst oss mitt ur den brinnande lågan, ja, han har frälst oss ur elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 64, 'Tacken Herren, ty han är god, ty hans nåd varar evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 65, 'Loven gudarnas Gud, I alla som frukten Herren; lovsjungen och tacken honom, ty hans nåd varar evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 66, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 67, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 68, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'I Babylon bodde en man som hette Joakim. att de voro falska vittnen, och gjorde mot dem detsamma som de själva hade haft det onda uppsåtet att göra mot sin nästa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Och han tog sig en hustru, som hette Susanna, Kelkias’ dotter. Hon var en mycket fager kvinna och fruktade Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Ty hennes föräldrar voro rättfärdiga och hade uppfostrat sin dotter efter Moses’ lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Och Joakim var mycket rik och ägde en stor trädgård, som låg invid hans hus. Och hos honom plägade judarna församla sig, eftersom han var den anseddaste bland dem alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Nu hade i det året två äldste bland folket blivit utsedda till domare, sådana om vilka Herren hade sagt: »Lagöverträdelse utgick från Babylon, från de äldste som voro domare, vilka räknades såsom styresmän för folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Dessa uppehöllo sig ständigt i Joakims hus. Och alla som hade någon rättssak kommo till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'När sedan folket vid middagstiden hade begivit sig hem, plägade Susanna gå in i sin mans trädgård för att lustvandra där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Och de båda äldste, som dag efter dag sågo henne gå ditin och lustvandra, grepos av begärelse till henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Och de läto sitt sinne bliva förvänt och slogo ned sina ögon, så att de icke blickade upp mot himmelen eller tänkte på att de kunde bliva drabbade av ett rättvist straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Och båda voro de svårt plågade för hennes skull, men de omtalade icke sitt kval för varandra;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'ty de blygdes för att omtala sin begärelse, att de nämligen ville pläga umgänge med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Men de vaktade dag efter dag med iver på att få se henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'En dag sade de till varandra: »Låt oss nu gå hem, ty måltidstimmen är inne.» Och de gingo därifrån och skildes från varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Men sedan vände de tillbaka och möttes på samma ställe som förut, och när de då utfrågade varandra om orsaken, tillstodo de sin begärelse. Och nu kommo de överens med varandra om en lämplig tid då de skulle kunna finna henne ensam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Då hände sig en gång, medan de vaktade på en läglig dag, att hon kom in i trädgården, likasom dagligen förut, åtföljd av allenast två tjänarinnor. Och hon fick lust till att bada där, eftersom det var mycket varmt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Och ingen fanns därinne utom de båda äldste, som hade gömt sig och vaktade på henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Och hon sade till tjänarinnorna: »Hämten hit olja och salvor, och stängen trädgårdsporten, så att jag kan få bada.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Och de gjorde såsom hon hade sagt. De stängde igen trädgårdsporten och gingo ut genom sidoporten för att hämta det som de hade fått tillsägelse om; men de sågo icke de äldste, ty dessa höllo sig gömda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Men så snart tjänarinnorna hade gått sin väg, kommo de båda äldste fram och skyndade emot Susanna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'och sade: »Se,trädgårdsporten är stängd, och ingen ser oss, och vi äro upptända av begärelse till dig. Gör oss därför till viljes och hav umgänge med oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Varom icke, så skola vi vittna emot dig att du hade en ung man hos dig, och att det var därför som du sände tjänarinnorna bort ifrån dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Då suckade Susanna och sade: »Jag är i trångmål på alla sidor; ty om jag gör detta, så bliver döden min lott, och om jag icke gör det, kan jag icke undkomma edra händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Men det är mig bättre att icke göra detta och så falla i edra händer än att synda inför Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nu begynte Susanna att ropa med högröst, men de båda äldste ropade också, där de stodo framför henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 25, 'Och den ene skyndade bort och öppnade trädgårdsporten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 26, 'Men när husfolket fingo höra ropet i trädgården, ilade de in genom sidoporten för att se vad som hade vederfarits henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 27, 'Då nu de äldste avlade sin berättelse, betogos tjänarna av stor blygsel, ty något sådant hade aldrig förut blivit sagt om Susanna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 28, 'När folket dagen därefter kom tillsammans hos Joakim, hennes man, kommo ock de båda äldste dit, fyllda av sitt syndiga uppsåt mot Susanna, för att få henne dömd till döden. Och de sade inför folket: 29 »Sänden efter Susanna, Kelkias\' dotter, Joakims hustru.» Och man sände efter henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 30, 'Så kom hon då dit, åtföljd av sina föräldrar och sina barn och alla sina fränder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 31, 'Och eftersom Susanna hade en mycket yppig växt och var fager att skåda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 32, 'befallde de ogudaktiga männen att man skulle taga av henne slöjan — hon var nämligen beslöjad — för att de så skulle få mätta sina ögon med hennes fägring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 33, 'Och de som åtföljde henne gräto, såväl som alla andra som sågo henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 34, 'De båda äldste stodo nu upp mitt ibland folket och lade sina händer på hennes huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 35, 'Men hon blickade gråtande upp mot himmelen, ty hennes hjärta förtröstade på Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 36, 'Och de äldste sade: »Medan vi ensamma vandrade omkring i trädgården, kom denna kvinna ditin med två tjänarinnor, och hon lät stänga igen trädgårdsporten och skickade bort tjänarinnorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 37, 'Då kom en ung man, som hade hållit sig gömd, fram till henne och lade sig hos henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 38, 'Men när vi, som befunno oss i ett hörn av trädgården, sågo den syndiga gärningen, skyndade vi fram till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 39, 'Och vi sågo dem pläga umgänge med varandra; men honom kunde vi icke taga fast, ty han var starkare än vi och öppnade porten och ilade sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 40, 'Henne däremot grepo vi, och vi frågade henne vem den unge mannen var,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 41, 'men hon ville icke omtala det för oss. Detta vittna vi.» Och församlingen trodde dem, eftersom de voro folkets äldste och domare, och de dömde henne till döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 42, 'Men Susanna ropade med hög röst och sade: »Evige Gud, du som känner det fördolda, du som vet allt, innan det ännu har skett,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 43, 'du vet att de hava burit falskt vittnesbörd mot mig. Och nu måste jag dö, fastän jag icke har gjort något av det som dessa illvilligt hava påbördat mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 44, 'Och Herren hörde hennes röst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 45, 'Ty när hon fördes bort för att undergå dödsstraffet, uppväckte Gud den helige anden hos en ännu helt ung man, som hette Daniel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 46, 'Och han ropade med hög röst: »Jag är oskyldig till denna kvinnas blod.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 47, 'Och allt folket vände sig till honom och sade: »Vad är meningen med det du här säger?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 48, 'Då trädde han fram mitt ibland dem och sade: »Ären I så dåraktiga, I Israels barn! Utan att hava hållit förhör och utan att hava utforskat huru saken verkligen förhåller sig haven I dömt en Israels dotter skyldig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 49, 'Vänden om igen till domstolen, ty dessa hava burit falskt vittnesbörd mot henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 50, 'Då vände allt folket med hast tillbaka. Och de äldste sade till honom: »Kom och sätt dig här mitt ibland oss, och säg oss din mening, ty åt dig har Gud givit en domares uppdrag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 51, 'Och Daniel sade till folket: »Skiljen dem långt ifrån varandra, så vill jag förhöra dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 52, 'Och när de så hade blivit skilda ifrån varandra, lät han kalla fram den ene av dem och sade till honom: »Du som har åldrats under ett liv i ondska, nu komma de synder över dig, som du tillförne bedrev,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 53, 'i det att du avkunnade orättfärdiga domar och fällde de oskyldiga och friade de skyldiga, fastän Herren säger: \'Du skall icke dräpa den som är oskyldig och har rätt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 54, 'Nåväl! Ifall du verkligen såg denna kvinna, säg då: under vad för ett träd såg du dem hava umgänge med varandra?» Och han svarade: »Under en blodbok.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 55, 'Då sade Daniel: »Träffande ljög du nu dig själv till fördärv; ty nu strax skall en Guds ängel, på befallning från Gud, utgjuta ditt blod.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 56, 'Sedan han hade låtit denne gå undan, befallde han att man skulle föra fram den andre. Och han sade till honom: »Du som är av Kanaans och icke av Judas\' säd, fägringen dårade dig, och begärelsen förvände ditt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 57, 'På detta sätt haven I handlat mot Israels döttrar, och dessa hava av fruktan haft umgänge med eder. Men en dotter av Judas underkastade sig icke edert syndiga förslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 58, 'Säg mig nu alltså: under vad för ett träd överraskade du dem i umgänge med varandra?» Och han svarade: »Under en järnek.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 59, 'Då sade Daniel till honom: »Träffande har också du nu ljugit dig själv till fördärv; ty Guds ängel står redo med svärdets järn i sin hand för att hugga dig itu och så förgöra eder båda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 60, 'Då begynte hela församlingen att ropa med hög röst och att lova Gud, honom som frälsar dem som hoppas på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 61, 'Och de stodo upp emot de båda äldste, eftersom Daniel genom deras egen muns vittnesbörd hade');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 62, 'såsom det är föreskrivet i Moses\' lag, och dräpte dem. Så blev oskyldigt blod frälst på den dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 63, 'Och Kelkias och hans hustru prisade Gud för Susannas, deras dotters, skull tillika med Joakim, hennes man, och alla fränderna, därför att något otillbörligt icke hade blivit funnet hos henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 64, 'Och Daniel blev stor inför folket, ifrån den dagen och allt framgent.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Där fanns också en stor drake, som babylonierna dyrkade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Och konungen sade till Daniel: »Du vill väl icke påstå att också den är av koppar? Han lever ju, och han äter och dricker. Du kan icke bestrida att han är en levande gud. Du må därför tillbedja honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 25, 'Men Daniel sade: »Herren, min Gud, vill jag tillbedja, ty han är en levande Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 26, 'Men om du, o konung, tillstädjer mig det, skall jag döda draken utan svärd eller käpp.» Och konungen sade: »Ja, jag tillstädjer dig det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 27, 'Då tog Daniel tjära och talg och hår och kokade det tillhopa och gjorde kakor därav och kastade dem i gapet på draken. Och sedan draken hade ätit upp dem, sprack han mitt itu. Då sade Daniel: »Där sen I hurudana edra gudomligheter äro!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 28, 'Men när babylonierna fingo höra detta, förtröt det dem högeligen, och de rotade sig samman mot konungen och sade: »Konungen har blivit jude; Bel har han störtat omkull, och draken har han dödat, och prästerna har han dräpt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 29, 'Och de begåvo sig till konungen och sade: »Utlämna Daniel åt oss. Varom icke, så skola vi döda dig och hela ditt hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 30, 'Då nu konungen såg att de så hårt ansatte honom, utlämnade han, nödd och tvungen, Daniel åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 31, 'Och de kastade denne i lejongropen, och han förblev där i sex dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 32, 'I gropen funnos sju lejon, och dem plägade man giva två människor och två får om dagen. Men den gången gav man dem icke något, på det att de skulle äta upp Daniel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 33, 'I Judeen levde på den tiden profeten Habackuk. Han hade kokat något till soppa och betat bröd i en skål och var just på väg till fältet för att bära ut det till skördemännen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 34, 'Då sade en Herrens ängel till Habackuk: »Bär den mat som du har där till Babylon, till Daniel, där han ligger i lejonssgropen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 35, 'Men Habackuk sade: »Herre, jag har aldrig varit i Babylon och känner icke till den gropen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 36, 'Då grep Herrens ängel honom vid hjässan och lyfte honom i håret och förde honom genom sin andedräkts vinande stormvind till Babylon, mitt över gropen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 37, 'Och Habackuk ropade och sade: »Daniel, Daniel, tag här den mat som Gud har sänt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 38, 'Då sade Daniel: »Så har du då tänkt på mig, o Gud; du har icke övergivit dem som älska dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 39, 'Och Daniel stod upp och åt. Men Guds ängel förde strax Habackuk tillbaka till det ställe där han förut var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 40, 'Men på sjunde dagen begav sig konungen åstad för att begråta Daniel. Och när han kom till gropen och såg ned, fick han se Daniel sitta där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 41, 'Då ropade han med hög röst och sade: »Stor är du, Herre, Daniels Gud, och ingen annan Gud finnes förutom dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 42, 'Och han lät draga upp Daniel. Men dem som hade sökt bereda hans fördärv lät han kasta ned i gropen. Och de blevo med hast uppslukade inför hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Sedan Alexander av Macedonien, Filippus’ son, som drog ut från kittéernas land, hade slagit Darius, persernas och medernas konung, blev han konung efter denne. (Redan förut var han konung över Grekland.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Han förde många krig, och han intog fästningar och dräpte konungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Och han trängde fram intill jordens ändar och tog byte från en mängd folk. Då nu jorden låg där kuvad inför honom, blev han högmodig, och hans hjärta förhävde sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Och han samlade en mycket stark här och gjorde sig till herre över länder och folk och riken, och de blevo skattskyldiga under honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Men därefter blev han sängliggande sjuk. Då han nu kände sitt slut nalkas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'kallade han till sig sina anseddaste tjänare, dem som från hans ungdom hade blivit uppfostrade tillsammans med honom, och fördelade sitt rike mellan dem, medan han ännu levde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Alexander hade vid sin död regerat i tolv år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Hans tjänare togo så väldet efter honom, var och en i sitt område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Och de antogo alla efter hans död konungavärdighet, så ock deras söner efter dem, i många år. Och de förövade mycket ont på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Från dem utgick en syndfull telning, Antiokus Epifanes, konung Antiokus’ son, som tidigare hade varit sänd såsom gisslan till Rom Han blev konung i det grekiska konungadömets ett hundra trettio sjunde år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'På den tiden uppstodo i Israel ogudaktiga män; och de vunno många på sin sida, då de sade: »Låt oss gå åstad och sluta förbund med hedningarna som bo runt omkring oss; ty alltsedan vi hava avskilt oss från dem, hava vi drabbats av många olyckor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Man fann behåg i det talet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Och några av folket förklarade sig villiga att begiva sig åstad till konungen; och han gav dem myndighet till att införa hedniska bruk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'De uppförde nu i Jerusalem en byggnad för kroppsövningar, enligt hednisk sed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Och de skaffade sig åter förhud och avföllo från det heliga förbundet; de gingo i ok tillsammans med hedningarna och sålde sig till att göra vad ont var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Då nu Antiokus såg sitt välde befäst, fick han i sinnet att bliva konung också i Egypten, för att så bliva konung över båda rikena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Han föll alltså in i Egypten med en stor härsmakt, med vagnar och elefanter och ryttare, och med en stor flotta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'och inlät sig i strid med Ptolemeus, konungen i Egypten. Och Ptolemeus kunde icke hålla stånd mot honom, utan flydde, och många föllo slagna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Antiokus’ folk intog nu de fasta städerna i Egypten; och han lät plundra Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Sedan Antiokus så hade slagit Egypten, vände han, år 143, tillbaka och drog då med en stor härsmakt upp till Israel och Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Och i sitt övermod trädde han in i helgedomen; och han tog bort det gyllene altaret och ljusstaken, med alla dess tillbehör,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'och skådebrödsbordet och kannorna och skålarna och de gyllene fyrfaten och förlåten och kransarna och de gyllene prydnaderna på framsidan av templet och all pålagd metall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Och han tog silvret och guldet och de dyrbara kärlen; han tog ock de undangömda skatter som han träffade på');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 24, 'och drog med alltsammans hem till sitt land, sedan han förut hade anställt ett blodbad och fört ett högeligen övermodigt tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 25, 'Då kom en stor sorg över Israel i alla dess landsändar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 26, 'och furstarna och de äldste suckade; jungfrur och ynglingar blevo maktlösa, och kvinnornas fägring försvann.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 27, 'Var brudgum stämde upp klagosång, och bruden i brudgemaket blev försänkt i sorg;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 28, 'landet bävade för sina inbyggares skull, och Jakobs hela hus blev höljt med skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 29, 'Två år därefter sände konungen en högste skattindrivare till Juda städer; och han kom till Jerusalem med en stor härsmakt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 30, 'Han gav dem svikligen fredliga försäkringar, och de satte tro till honom. Men sedan överföll han plötsligt staden och anställde en stor manspillan där och förgjorde mycket folk i Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 31, 'Och han plundrade staden och brände upp den i eld och bröt ned dess hus och dess murar runt omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 32, 'Och de förde kvinnorna och barnen bort såsom fångar och bemäktigade sig boskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 33, 'Sedan befäste de Davids stad med en hög och stark mur och fasta torn; så fingo de där en borg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 34, 'Och de lade i den in en besättning av syndigt folk, ogudaktiga män, vilka förskansade sig där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 35, 'De lade där ock upp förråd av vapen och livsmedel; och bytet från Jerusalem samlade de tillhopa och lade i förvar där. Den borgen blev en farlig snara;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 36, 'den blev ett bakhåll för helgedomen och en svår motståndare för Israel, hela tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 37, 'Och de utgöto oskyldigt blod runt omkring helgedomen; ja, helgedomen oskärade de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 38, 'Jerusalems inbyggare flydde för deras skull, och staden blev ett hemvist för främlingar; den blev främmande för sin egen avkomma, och dess barn övergåvo den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 39, 'Dess helgedom blev öde såsom en ödemark, dess högtider förvandlades till sorgedagar, dess sabbater till smälek, dess heder till förakt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 40, 'Så stor som dess härlighet hade varit, blev nu dess vanheder, och dess höghet förvandlades till sorg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 41, 'Och konungen utfärdade ett påbud för hela sitt rike att alla skulle vara ett enda folk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 42, 'och att var och en skulle övergiva sina egna seder och bruk. Och alla hednafolk fogade sig efter konungens befallning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 43, 'Jämväl många israeliter funno behag i hans gudsdyrkan och offrade åt avgudarna och ohelgade sabbaten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 44, 'Därjämte sände konungen ut budbärare med skrivelser till Jerusalem och Juda städer, med befallning att de skulle vandra efter sedvänjor som voro främmande för landet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 45, 'och upphöra med brännoffer och slaktoffer och drickoffer i helgedomen, och ohelga sabbater och högtider,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 46, 'och besmitta helgedomen och de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 47, 'Vidare skulle de bygga altaren och helgedomar och avgudahus, och offra kött av svin och andra orena djur,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 48, 'och lämna sina gossebarn oomskurna; ja, de skulle besudla sina själar med allt vad orent och befläckat var,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 49, 'och så förgäta lagen och upphäva alla dess rätter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 50, 'Och var och en som icke gjorde efter konungens befallning, han skulle straffas till livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 51, 'Sådant var innehållet av de skrivelser som han lät utfärda i sitt rike. Han insatte ock tillsyningsmän över hela folket och bjöd Juda städer att offra, var stad för sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 52, 'Och många av folket, alla de som ville övergiva lagen, slöto sig till dem. Och de foro illa fram i landet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 53, 'och tvingade israeliterna att gömma sig, varhelst de kunde finna en tillflyktsort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 54, 'På femtonde dagen i månaden Kisleu år 145 satte de upp »förödelsens styggelse» på brännoffersaltaret; och runt omkring i Juda städer byggde de avgudaaltaren');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 55, 'och tände offereld framför husens dörrar och på gatorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 56, 'Och de lagböcker som de träffade på revo de sönder och brände upp i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 57, 'Och envar hos vilken förbundets bok påträffades och envar som höll sig till lagen var enligt konungens förordning hemfallen åt döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 58, 'I sin våldsamma framfart förforo de så i städerna, månad efter månad, mot Israel, mot dem som ertappades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 59, 'Och på tjugufemte dagen i var månad offrade de på det avgudaaltare som var uppfört på brännoffersaltaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 60, 'Och de kvinnor som hade låtit omskära sina barn dödade de, såsom det var befallt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 61, 'och därvid hängde de de späda barnen vid mödrarnas halsar. Också dem som hörde till deras hus och de män som hade omskurit barnen dödade de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 62, 'Men många israeliter togo mod till sig och föresatte sig att icke äta något orent;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 63, 'de underkastade sig hellre döden, än de ville besmitta sig genom maten och ohelga det heliga förbundet. Och de måste så lida döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 64, 'Ja, en övermåttan svår vredesdom drabbade Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Vid den tiden uppträdde Mattatias, som var son av Johannes, Simeons son, en präst av Joaribs söner, från Jerusalem. Han bodde i Modein.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Och han hade fem söner: Johannes, med tillnamnet Gaddis,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Simon, som kallades Tassis,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Judas, som kallades Mackabeus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Eleasar, som kallades Avaran, och Jonatan, som kallades Apfus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Då han nu fick höra vilka hädiska gärningar som förövades i Judeen och i Jerusalem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'sade han: »Ve mig! Varför har jag blivit född till att se mitt folks undergång och den heliga stadens undergång och till att sitta här stilla, medan den är given i fienders hand och helgedomen i främlingars hand?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Dess tempel har blivit såsom en Vanärad man,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'dess präktiga kärl hava förts bort såsom rov; dess späda barn hava dödats på dess gator, och dess unga män genom fiendens svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Finnes något folk som icke har tagit dess borg i besittning och icke har bemäktigat sig dess egendom såsom byte?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'All dess prydnad är borttagen, i stället för fri har den nu blivit en träl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Ja, allt vad vi ägde heligt och skönt och härligt är förött, hedningarna hava oskärat det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Varförr skulle vi längre leva?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Och Mattatias och hans söner revo sönder sina kläder och höljde sig i sorgdräkt och sörjde djupt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Men konungens utsända, som skulle tvinga folket till avfall, kommo till staden Modein, för att invånarna där skulle offra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Och många israeliter trädde fram till dem. Också Mattatias och hans söner kommo allasammans ditfram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Då togo konungens utsända till orda och talade så till Mattatias och sade: »Du är en styresman här i staden, en ansedd och betydande man, och du har ett starkt stöd i söner och fränder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Så träd nu du först fram och gör efter vad konungen har påbjudit, såsom alla folk och övriga judar och de som äro kvar i Jerusalem redan hava gjort. Då skall du och ditt hus få räknas bland konungens vänner, och du och dina söner skolen bliva ärade med silver och guld och många skänker.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Men Mattatias svarade och sade med hög röst: »Om än alla folk inom konungens rike äro honom hörsamma, så att envar avfaller från sina fäders gudsdyrkan och villigt fogar sig i hans bud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'så vilja dock jag och mina söner och mina fränder vandra efter förbundet med våra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Bort det, att vi skulle övergiva lagen och våra rätter!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Konungens förordning ämna vi icke hörsamma; vi vilja icke vika av ifrån vår gudsdyrkan, vare sig till höger eller till vänster.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 23, 'Just då han hade sagt detta, trädde en judisk man i allas åsyn fram för att offra på altaret i Modein, såsom konungen hade påbjudit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 24, 'När Mattatias såg detta, blev han uppfylld av nitälskan, och hans innersta kom i uppror, och han gav fritt lopp åt sin vrede, såsom rätt och tillbörligt var, och skyndade fram och dräpte mannen där på altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 25, 'Också konungens sändebud, som sökte tvinga folket att offra, dödade han samtidigt; och altaret rev han ned.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 26, 'Så nitälskade han för lagen, i det att han gjorde såsom Finees en gång hade gjort med Sambri, Saloms son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 27, 'Och Mattatias ropade i staden med hög röst och sade: »Var och en som nitälskar för lagen och vill upprätthålla förbundet, han må följa mig och draga bort härifrån.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 28, 'Så flydde han med sina söner till bergen; och allt vad de ägde i staden lämnade de i sticket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 29, 'Då drogo många, som foro efter rättfärdighet och rätt, ut i öknen för att uppehålla sig där;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 30, 'och de togo med sig sina barn och sina hustrur och sin boskap. Ty förföljelserna mot dem blevo mycket svåra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 31, 'När det blev berättat för konungens män och det krigsfolk som fanns i Davids stad i Jerusalem, att en skara män, sådana som hade föraktat konungens bud, hade dragit ut till grottorna i öknen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 32, 'begåvo de sig med hast i stort antal efter dem. När de då träffade på dem, lägrade de sig gent emot dem och beredde sig till att anfalla dem på sabbatsdagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 33, 'Och de sade till dem: »Må det nu vara nog. Kommen ut, och gören såsom konungen har befallt, så skolen I få leva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 34, 'Men de svarade: »Vi vilja icke komma ut, och vi vilja icke göra såsom konungen har befallt och därmed ohelga sabbatsdagen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 35, 'Då begynte de andra strax att strida mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 36, 'Men de försvarade sig icke och kastade icke en sten mot dem och spärrade icke igen ingångarna till grottorna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 37, 'utan sade: »Vi vilja allasammans dö i vår oskuld. Himmel och jord äro vittnen till att I förgören oss utan all rätt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 38, 'Men de andra gingo till angrepp mot dem under sabbatsdagen; och så dödades de, tillika med sina hustrur och sina barn och sin boskap, till ett antal av vid pass ett tusen personer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 39, 'När Mattatias och hans vänner fingo veta detta, sörjde de dem djupt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 40, 'Och de sade till varandra: »Om vi alla göra såsom våra bröder hava gjort och underlåta att strida mot hedningarna, till försvar för våra liv och våra rätter, så skola de snart hava utrotat oss från jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 41, 'Därför fattade de den dagen följande beslut: »Om någon drager ut till strid mot oss på sabbatsdagen, så vilja vi försvara oss mot honom; vi vilja icke allasammans omkomma, såsom våra bröder omkommo i grottorna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 42, 'Vid den tiden församlade sig hos dem en skara asidéer, tappra stridsmän i Israel, alla de som voro villiga att försvara lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 43, 'Och alla som flydde undan förföljelserna slöto sig till dem och ökade ytterligare deras styrka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 44, 'Så fingo de en här till stånd. Och de dräpte syndarna i sin vrede och avfällingarna i sin förtörnelse. Och de som blevo kvar efter dem flydde till hedningarna för att rädda sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 45, 'Och Mattatias och hans vänner drogo omkring och revo ned deras altaren');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 46, 'och läto med våld omskära alla oomskurna gossebarn som de träffade på inom Israels område;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 47, 'och de övermodiga förföljde de. Så hade företaget god framgång under deras ledning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 48, 'Och de togo lagen i skydd mot hedningarnas angrepp och mot konungarnas angrepp, och de tillstadde icke syndarna att upphöja sitt horn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 49, 'Men då tiden närmade sig att Mattatias skulle dö, sade han till sina söner: »Nu härska övermod och hemsökelse och en tid av omstörtning och en svår vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 50, 'Så nitälsken då, mina barn, för lagen, och given edra liv till försvar för förbundet med edra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 51, 'Tänken på vad fäderna hava utfört i sin tid, så skolen I ock vinna stor ära och ett evärdligt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 52, 'Abraham blev ju befunnen trogen, när han sattes på prov, och det räknades honom till rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 53, 'Josef höll budet, när han var i trångmål, och han blev herre över Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 54, 'Med Finees, vår fader, gjordes för hans nitälskans skull ett förbund, med löfte om ett evärdligt prästadöme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 55, 'Josua blev, därför att han hade efterkommit befallningen, domare i Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 56, 'Kaleb fick ett stycke land såsom arvedel för det vittnesbörds skull som han hade avlagt inför menigheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 57, 'David fick för sin fromhets skull en konungatron till arvedel, för evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 58, 'Elias blev upptagen till himmelen, därför att han hade nitälskat för lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 59, 'Ananias, Asarias och Misael blevo för sin tros skull frälsta ur lågorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 60, 'Daniel blev på grund av sin oskuld räddad ur lejonens gap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 61, 'Betänken på detta sätt huru det alltid går, släkte efter släkte: ingen som hoppas på Honom dukar under.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 62, 'Frukten därför icke för en syndig mans befallning, ty hans härlighet skall släpas i smutsen och bliva maskars föda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 63, 'I dag förhäver han sig, och i morgon skall man icke mer finna honom, ty han har vänt åter till det stoft varav han är kommen, och hans anslag har blivit om intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 64, 'Men I, mina barn, våren frimodiga och oförfärade i att värna lagen, ty I skolen genom den vinna ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 65, 'Här står eder broder Simeon. Jag vet att han är en rådvis man. Lyssnen alltid till honom; han skall vara för eder såsom en fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 66, 'Och Judas Mackabeus, han som har varit en tapper stridsman allt ifrån sin ungdom, han skall bliva eder härförare och kämpa vårt folks strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 67, 'Och samlen omkring eder alla dem som hålla lagen, och utkräven hämnd för edert folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 68, 'Vedergällen hedningarna vad de hava gjort, och akten på lagens stadgar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 69, 'Därefter välsignade han dem. Och så blev han samlad till sina fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 70, 'Han dog år 146; Och hans söner begrovo honom i hans fäders grav i Modein, och hela Israel höll stor dödsklagan efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Hans son Judas, som kallades Mackabeus, trädde nu i hans ställe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Och alla hans bröder och alla de som hade slutit sig till hans fader bistodo honom; och de förde Israels strid med glatt mod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Han vann ära åt sitt folk vida omkring; han tog på sig sitt pansar såsom en hjälte och omgjordade sig med sin krigsrustning; han utkämpade strider och skyddade sin här med svärdet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Han var lik ett lejon i sina bedrifter, lik ett ungt lejon, som rytande störtar sig över sitt rov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Han spårade upp de laglösa och förföljde dem, och han lät eld komma över dem som oroade hans folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'De laglösa sjönko ihop av fruktan för honom, och alla som övade laglöshet blevo slagna med skräck; ja, räddningens verk hade god framgång under hans ledning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Han uppväckte bitter vrede hos många konungar, men beredde Jakob glädje genom sina bedrifter; till evärdlig tid skall hans minne välsignas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Han drog fram genom Juda städer och utrotade de ogudaktiga ur landet och avvände vreden från Israel;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'hans rykte nådde till jordens ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Men Apollonius samlade hedniskt krigsfolk och en stor här från Samarien, för att strida mot Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'När Judas fick veta detta, drog han ut för att möta honom. Och han besegrade honom och dödade honom; många föllo slagna, och de övriga flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Och de togo deras egendom såsom byte; Judas själv tog Apollonius’ svärd och begagnade det sedan alltid i striden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'När Seron, hövitsmannen över den syriska hären, fick höra att Judas hade församlat hos sig en skara, en hop av trogna, av män som voro redo att draga ut till strid,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'då sade han: »Jag vill göra mig ett namn och vinna ära i riket; jag vill strida mot Judas och hans folk, dessa som förakta konungens befallning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Så drog också han ditupp, följd av en stark här av ogudaktiga, som skulle hjälpa honom i att utkräva hämnd på Israels barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Och han hade nästan hunnit fram till vägen som leder upp till Betoron, då Judas med en ringa hop drog ut emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'När nu Judas’ män sågo hären komma emot sig, sade de till honom: »Huru skola vi, som äro så få, kunna strida mot en så stor mängd? Därtill äro vi ock utmattade, eftersom vi icke hava ätit något i dag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Men Judas svarade: »Det kan lätt hända att en stor hop bliver prisgiven åt några få, och det gör icke någon skillnad för himmelen att skaffa räddning genom många eller genom få.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Ty det är icke på härens storlek som segern i striden beror; nej, från himmelen kommer kraften.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'De draga emot oss, fulla av övermod och laglöshet, för att tillintetgöra oss och våra kvinnor och barn, och för att utplundra oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Men vi strida för våra liv och för våra stadgar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 22, 'och Han själv skall krossa dem inför våra ögon. Frukten alltså icke för dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 23, 'Och när han hade slutat att tala, gjorde han ett plötsligt anlopp mot dem. Och Seron och hans här blev i grund slagen av honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 24, 'och de förföljde dem utför den sluttning som går ned från Betoron, ända fram till slätten. Vid pass åtta hundra man föllo på deras sida; de övriga flydde till filistéernas land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 25, 'Från den stunden begynte man att frukta för Judas och hans bröder; och bävan föll över hedningarna där runt omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 26, 'Och ryktet om honom nådde ända fram till konungen, och alla folk talade om Judas’ strider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 27, 'Då nu konung Antiokus fick höra om dessa händelser, upptändes han av vrede. Och han sände ut och lät samla sitt rikes hela krigsmakt, en övermåttan stark här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 28, 'Och han öppnade sin skattkammare och gav sitt krigsfolk sold för ett år, och bjöd dem att hålla sig redo för att göra tjänst, närhelst så behövdes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 29, 'Men när han såg att penningarna begynte taga slut i hans skattkamrar, och när skatterna från hans rike inflöto allt sparsammare, till följd av den söndring och skada som han hade åstadkommit i landet, genom att söka avskaffa de sedvänjor som gällde sedan urminnes tid,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 30, 'då befarade han att han, såsom en och annan gång förut, icke skulle hava medel till sina utgifter och till de skänker som han tillförne med frikostig hand hade plägat utdela; han överbjöd nämligen häri de konungar som hade varit före honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 31, 'Och han visste icke alls vad han skulle göra. Då beslöt han att draga åstad till Persien och upptaga skatterna i dessa trakter och samla tillhopa penningar i mängd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 32, 'Han lämnade därvid kvar Lysias, en ansedd man av konungslig börd, för att förestå regeringen inom länderna ifrån floden Eufrat till Egyptens gränser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 33, 'och för att leda hans son Antiokus’ uppfostran, till dess han själv kom tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 34, 'Och han överlämnade åt honom hälften av hären, så ock elefanterna, och gav honom befallning om allt som han önskade, och särskilt angående invånarna i Judeen och Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 35, 'Lysias skulle mot dem sända ut en här, för att krossa och tillintetgöra Israels makt och vad som var kvar av Jerusalem och utplåna deras åminnelse från den platsen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 36, 'och han skulle låta främlingar bosätta sig i hela deras område och genom lottkastning fördela deras land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 37, 'Med den återstående hälften av hären bröt konungen därefter upp från sin huvudstad Antiokia, år 147; och han övergick floden Eufrat och genomtågade de övre landskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 38, 'Men Lysias utsåg Ptolomeus, Dorymenes’ son, och Nikanor och Gorgias, som voro mäktiga män bland konungens vänner,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 39, 'och sände med dem fyrtio tusen man fotfolk och sju tusen ryttare, för att de skulle draga in i Judeen och förhärja det, såsom konungen hade befallt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 40, 'De bröto nu upp med hela sin här, och då de hade kommit fram, lägrade de sig nära Ammaus på slätten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 41, 'När köpmännen där i landet fingo höra talas om dem, togo de med sig silver och guld i stor myckenhet, så ock fotbojor, och begåvo sig till lägret för att köpa israeliter såsom trälar. Och till hären slöt sig också krigsfolk från Syrien och filistéernas land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 42, 'När nu Judas och hans broder sågo att faran blev allt större, och att hären hade lägrat sig inom deras område, och när de fingo kunskap om vad konungen hade bjudit att man skulle göra med deras folk, till dess fördärv och undergång,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 43, 'då sade de till varandra: »Låt oss åter upprätta vårt folk ur dess fall och strida för vårt folk och för helgedomen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 44, 'Och menigheten församlade sig för att vara redo till strid och för att åkalla och bedja om nåd och förbarmande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 45, 'Men Jerusalem var obebott såsom en öken, ingen av dess barn gick där in eller ut. Helgedomen var förtrampad, och främlingar bodde på borgen; staden hade blivit ett tillhåll för hedningar. Glädjen hade försvunnit ifrån Jakob, och flöjt och harpa hade tystnat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 46, 'Så församlade de sig och begåvo sig till Massefa, mitt emot Jerusalem; ty Massefa var en plats där Israel fordom hade plägat tillbedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 47, 'Och de fastade den dagen och höljde sig i sorgdräkt och strödde aska på sina huvuden och revo sönder sina kläder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 48, 'Sedan bredde de ut lagboken, en av dessa böcker som hedningarna plägade söka efter, för att i dem teckna bilder av sina avgudar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 49, 'Och de buro fram prästkläderna och förstlingsfrukterna och tiondegärderna. De läto ock de nasirer träda fram, vilkas nasirtid hade gått till ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 50, 'Och de ropade med hög röst till himmelen och sade: »Vad skola vi göra med dessa? Och vart skola vi föra dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 51, 'Din helgedom är ju förtrampad och oskärad, och dina präster leva i sorg och förnedring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 52, 'Och nu hava hedningarna församlat sig mot oss för att tillintetgöra oss. Du vet själv vad de hava i sinnet mot oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 53, 'Huru skola vi kunna hålla stånd mot dem, om icke du hjälper oss?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 54, 'Och de blåste i trumpeterna och ropade med hög röst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 55, 'Därefter tillsatte Judas anförare för folket, hövitsmän över tusen och över hundra och över femtio och över tio.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 56, 'Och han befallde att de som hade byggt ett hus eller trolovat sig med en kvinna eller planterat en vingård eller voro försagda skulle vända om, var och en hem till sitt, såsom skrivet var i lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 57, 'Sedan bröt hären upp och lägrade sig söder om Ammaus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 58, 'Och Judas sade: »Omgjorden eder, och skicken eder såsom tappra män, och hållen eder redo till i morgon att strida med dessa hedningar, som hava församlat sig mot oss för att tillintetgöra oss och vår helgedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 59, 'Ty det är oss bättre att dö i striden än att nödgas se vårt folks och vår helgedoms ofärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 60, 'Men såsom han vill, som är i himmelen, så må det ske.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Men Gorgias tog med sig fem tusen man fotfolk och ett tusen utvalda ryttare, och bröt om natten upp med denna här');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'för att angripa judarnas här och tillfoga den ett plötsligt nederlag; och folk ifrån borgen visade honom vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Men när Judas fick höra detta, bröt han upp med sina kämpar, i avsikt att slå konungens här, den som stod vid Ammaus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'medan krigsfolket ännu var skingrat utanför lägret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Då nu Gorgias under natten kom fram till Judas’ läger och icke fann någon där, sökte han dem bland bergen; han tänkte nämligen att de hade flytt för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Men i dagbräckningen blev Judas synlig på slätten med tre tusen man, vilka dock icke voro så försedda med skyddsvapen och svärd som de skulle hava önskat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'När de nu sågo huru starkt och väl förskansat hedningarnas läger var, och huru det var omgivet av ryttare, idel stridskunnigt folk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'då sade Judas till de män som följde honom: »Frukten Icke för deras stora antal, och radens icke för deras anlopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Kommen ihåg huru våra fäder blevo frälsta i Röda havet, när Farao med sin här förföljde dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Så låtom oss nu ropa till himmelen, i hopp om att Han skall hava behag till oss och tänka på förbundet med fäderna och låta denna här bliva i grund slagen av oss i dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Då skola alla hedningar förnimma att det finnes en som förlossar och frälsar Israel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'När sedan utlänningarna lyfte upp sina ögon och sågo dem tåga emot sig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'drogo de ut ur lägret till strid. Och Judas’ män blåste i trumpeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'De drabbade nu samman, och hedningarna blevo i grund slagna och flydde utåt slätten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'och de som blevo efter föllo allasammans för svärd. Men de förföljde dem till Gasera och till slättmarkerna i Idumeen och till Asotus och Jamnia. Vid pass tre tusen man föllo på deras sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'När Judas med sin här kom tillbaka, efter att hava, förföljt dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'sade han till folket: »Låten icke locka eder av begär efter bytet, ty vi hava ännu en strid framför oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'då ju Gorgias med sin här befinner sig i berglandet helt nära oss; nej, hållen nu stånd mot våra fiender och striden med dem. Sedan kunnen I utan fruktan taga byte.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Innan Judas ännu hade talat till slut, syntes en avdelning fiender skymta fram mellan bergen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Dessa fingo nu se att de andra hade blivit slagna på flykten, och att man just höll på med att tända eld på lägret; ty röken, som de sågo stiga upp därifrån, röjde vad som hade hänt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'När de förstodo huru det var, blevo de storligen förskräckta, och när de tillika sågo Judas’ här stå stridsfärdig på slätten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'flydde de allasammans till filistéernas land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Då vände Judas om för att plundra lägret. Och de togo guld och silver i mängd och mörkblå och äkta röda purpurtyger och många andra dyrbarheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'När de sedan vände tillbaka, läto de psalmer och lovsånger ljuda mot himmelen, »ty hans nåd är god, ty den varar evinnerligen».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Ja, det var en stor seger som på den dagen beskärdes Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Men alla de hedningar som hade undkommit begåvo sig till Lysias och omtalade för honom allt vad som hade hänt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'När han fick höra detta, blev han bestört; och han var missmodig över att det icke hade gått med Israel såsom han hade önskat, och att saken icke hade avlupit i enlighet med vad konungen hade bjudit honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Följande år samlade han därför sextio tusen man utvalt fotfolk och fem tusen ryttare för att åter strida mot judarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'De tågade till Idumeen och lägrade sig vid Betsura, men Judas drog dem till mötes med tio tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Då han nu såg huru stark hären var, bad han och sade: »Lovad vare du, Israels frälsare, du som gjorde kämpens anlopp om intet genom din tjänare Davids hand och gav filistéernas här i Jonatans, Sauls sons, och hans vapendragares händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Giv nu denna här till pris åt ditt folk Israel, och låt dem komma på skam med sitt krigsfolk och sina ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Injaga räddhåga hos dem och förlama deras djärva mod, så att de vackla och i grund bliva slagna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 33, 'Slå ned dem genom deras svärd, som älska dig, så att alla de som känna ditt namn få prisa dig med lovsånger.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 34, 'Därefter drabbade de båda härarna tillhopa, och av Lysias’ här dödades vid pass fem tusen man, som föllo för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 35, 'När Lysias såg huru hans egen krigshär hade blivit slagen på flykten, men huru Judas’ män hade blivit uppfyllda med djärvhet, och huru dessa voro redo att med ädelt mod kämpa på liv och död, drog han därifrån till Antiokia; och han lejde främmande krigsfolk för att, sedan han åter hade fått hären fulltalig, ånyo tåga mot Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 36, 'Då sade Judas och hans bröder: »Nu hava våra fiender blivit i grund slagna; låt oss därför draga upp till Jerusalem för att rena helgedomen och på nytt inviga den.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 37, 'Och hela hären församlade sig, och de drogo upp till Sions berg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 38, 'När de nu sågo helgedomen vara ödelagd och altaret oskärat och portarna vara uppbrända och gräs och buskar uppvuxna på förgårdarna, likasom i en småskog eller på ett berg, och kamrarna vara förstörda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 39, 'då revo de sönder sina kläder och upphävde högljudd sorgelåt och strödde aska på sina huvuden');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 40, 'och föllo ned till jorden på sina ansikten. Och de blåste i larmtrumpeterna och ropade upp mot himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 41, 'Därefter befallde Judas en avdelning krigsmän att föra striden mot besättningen på borgen, till dess han hade renat helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 42, 'Han utvalde nu till präster sådana som voro ostraffliga och hade sin lust i lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 43, 'Och man renade helgedomen och förde besmittelsens stenar bort till en oren plats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 44, 'Sedan överlade de om vad de borde göra med det oskärade brännoffersaltaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 45, 'Och de funno på det goda rådet att riva ned det, för att det icke skulle bliva en orsak till tadel mot dem, eftersom hedningarna hade besmittat det. Alltså revo de ned altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 46, 'Men stenarna lade de i förvar på tempelberget, på en därtill lämplig plats, i avvaktan på att en profet skulle uppträda, som kunde giva anvisning om vad man borde göra med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 47, 'Sedan togo de ohuggna stenar, såsom skrivet var i lagen, och byggde ett nytt altare, sådant som det förra var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 48, 'De återställde likaledes helgedomen och det inre av huset och invigde förgårdarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 49, 'Och de läto förfärdiga nya heliga kärl och förde ljusstaken och rökelsealtaret och bordet in i templet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 50, 'Och de antände rökelse på altaret och tände lamporna på ljusstaken, så att de lyste i templet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 51, 'Och de lade fram bröd på bordet och spände ut förhängena. Och så fullbordade de allt vad de hade företagit sig att göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 52, 'Men på tjugufemte dagen i nionde månaden, det är månaden Kisleu, år 148, stodo de bittida upp');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 53, 'och framburo, såsom skrivet var i lagen, ett offer på det nya brännoffersaltare som de hade uppfört.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 54, 'I samma månad och på samma dag som hedningarna hade oskärat det, blev det nu på nytt invigt med sånger och med spelande på cittror, harpor och cymbaler.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 55, 'Och hela folket föll ned på sina ansikten, och de ropade mot himmelen och tillbådo och lovade honom som hade låtit det gå dem så väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 56, 'De firade så det nya altarets invigning i åtta dagar, och de framburo brännoffer under glädje och offrade tackoffer och lovoffer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 57, 'Och de prydde templets framsida med gyllene kransar och små sköldar och gjorde nya portar och kamrar och försågo dessa med dörrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 58, 'Och det blev en mycket stor glädje bland folket, därför att den smälek som hedningarna hade tillfogat dem nu hade blivit borttagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 59, 'Och Judas och hans bröder och Israels hela menighet fastställde att dagarna för altarets invigning årligen, på sin bestämda tid, skulle firas i åtta dagar, från tjugufemte dagen i månaden Kisleu räknat, med glädje och fröjd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 60, 'Vid samma tid befäste de ock Sions berg runt omkring med höga murar och starka torn, för att hedningarna icke skulle kunna komma och förtrampa det, såsom de förut hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 61, 'Och Judas lade där in en besättning till dess försvar. Och de befäste Betsura, för att folket så skulle hava en fästning mot Idumeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'När hedningarna runt omkring fingo höra att altaret åter hade blivit uppfört, och att helgedomen hade blivit återställd i sitt förra skick, vredgades de storligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Och de lade råd om att utrota dem av Jakobs släkt, som bodde inom deras gränser, och de begynte att sprida död och förödelse bland folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Och Judas stridde mot Esaus barn i Idumeen, dem som bodde i Akrabattene, därför att de lågo på lur vid Israels gränser. Och han tillfogade dem ett stort nederlag och kuvade dem och tog deras egendom såsom byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Han tänkte också på Beans barns ondska; de voro nämligen folket till en snara och ett giller genom att ligga i försåt för dem vid vägarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Dessa inneslöt han i deras torn; och han belägrade dem och gav dem till spillo och brände upp stadens torn i eld, tillika med alla dem som voro därinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Sedan gick han över floden till Ammons barn. Där träffade han på en stark stridsmakt och mycket krigsfolk, med Timoteus såsom anförare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Och han inlät sig i många strider med dem; och de blevo i grund slagna av honom, och han besegrade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Vidare intog han Jaser med underlydande orter och vände därefter tillbaka till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Nu församlade sig hedningarna i Galaad mot de israeliter som befunno sig på deras område, för att tillintetgöra dem. Men dessa flydde till fästningen Datema.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Och de sände ett brev till Judas och hans bröder, så lydande: »Hedningarna runt omkring oss hava församlat sig mot oss för att tillintetgöra oss;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'och nu stå de färdiga till att komma och intaga den fästning dit vi hava flytt, och Timoteus är anförare för deras här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Så kom nu och rädda oss ur deras våld. Ty många av de våra hava redan fallit,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'och alla våra bröder i Tubias’ område äro dödade. Och man har bortfört deras kvinnor och barn och deras tillhörigheter och där nedgjort vid pass ett tusen män.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Medan man ännu höll på med att läsa brevet, kommo andra budbärare, från Galileen, i sönderrivna kläder, och framförde det budskapet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'att folk ifrån Ptolemais, Tyrus och Sidon, så ock hela det av hedningar bebodda Galileen, hade församlat sig mot dem för att göra ände på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'När Judas och folket fingo höra härom, församlade sig menigheten i talrik mängd, för att lägga råd om vad de skulle göra för sina nödställda bröder, som angrepos av hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Och Judas sade till sin broder Simon: »Välj ut manskap åt dig, och drag åstad och rädda dina bröder i Galileen. Jag och min broder Jonatan vilja draga till Galaaditis.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Men han kvarlämnade Josef, Sakarias’ son, och Asarias såsom anförare för folket, med återstoden av hären, i Judeen till dess försvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Och han bjöd dem och sade: »Fören befälet över folket här, men undviken att inlåta eder i strid med hedningarna, till dess vi hava kommit tillbaka.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Och Simon fick tre tusen man på sin lott för att draga till Galileen, och Judas åtta tusen man för att draga till Galaaditis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Simon drog alltså åstad till Galileen och inlät sig i många strider med hedningarna; och de blevo i grund slagna av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Och han förföljde dem till Ptolemais’ stadsport. Av hedningarna föllo vid pass tre tusen man; och han bemäktigade sig deras egendom såsom byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Därefter tog han med sig de judar som bodde i Galileen och i Arbatta, tillika med deras kvinnor och barn och allt vad de ägde; och de förde dem till Judeen under stor glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Men Judas Mackabeus och hans broder Jonatan gingo över Jordan och tågade tre dagsresor genom öknen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Där stötte de på nabatéerna. Och dessa bemötte dem fredligt och omtalade för dem allt vad som hade vederfarits deras bröder i Galaaditis.’ De sade: 26 »Många av dem hållas inneslutna i Bossora och Bosor, i Alima, Kasfor, Maked och Karnain, idel fasta och stora städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Jämväl i de övriga städerna i Galaaditis hållas några inneslutna. Till i morgon bereda sig deras fiender att angripa fästningarna och så intaga dem och tillintetgöra alla dem som äro därinne på en och samma dag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Då slog Judas med sin här plötsligt in på vägen till Bossora, i öknen. Och han intog staden och dödade allt mankön med svärdsegg och tog all deras egendom såsom byte och brände upp staden i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Sedan bröt han upp därifrån om natten');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'och tågade till fästningen. Och när dagen grydde, lyfte de upp sina ögon och blevo då varse en oräknelig mängd människor, som förde fram stegar och stormverktyg, för att intaga fästningen, och höllo på att strida mot dem som voro därinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'När Judas såg att striden hade begynt och hörde huru larmet från staden steg upp mot himmelen, under trumpetstötar och höga rop,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'sade han till sina krigsmän: »Striden nu i dag till försvar för våra bröder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Därefter tågade han fram i tre hopar, i ryggen på fienderna; och hans män stötte i trumpeterna och upphävde bönerop.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 34, 'Men när Timoteus’ här förstod att det var Mackabeus, flydde de för honom. Och han tillfogade dem ett stort nederlag; vid pass åtta tusen man av deras folk föllo på den dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 35, 'Sedan vek han av till Masfa och angrep denna stad. Och han intog den och dödade allt mankön där och tog all egendom i den såsom byte och brände upp den i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 36, 'Därifrån drog han vidare och intog Kasfor, Maked, Bosor och de övriga städerna i Galaaditis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 37, 'Härefter samlade Timoteus en ny här och lägrade sig mitt emot Rafon, på andra sidan bäcken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 38, 'Judas sände då några män för att bespeja lägret, och de berättade för honom och sade: »Alla hedningar runt omkring oss hava församlat sig hos dem. en mycket stor härskara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 39, 'Också araber hava de lejt till att hjälpa sig. Och de hava sitt läger på andra sidan bäcken och äro redo att draga ut emot dig till strid.» Då tågade Judas dem till mötes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 40, 'Och när Judas och hans folk kommo nära vattenbäcken, sade Timoteus till hövitsmännen i sin här: »Om han går först över och anfaller oss, så skola vi icke kunna hålla stånd mot honom, ty han skall då bliva oss övermäktig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 41, 'Men om han gripes av räddhåga och lägrar sig på andra sidan floden, då skola vi gå över den och anfalla honom och så bliva honom övermäktiga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 42, 'När Judas nu hade kommit fram till vattenbäcken, ställde han folkets tillsyningsmän vid bäcken och bjöd dem så: »Låten icke någon enda lägra sig, utan må de allasammans draga ut i striden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 43, 'Därmed gick han först över och anföll fienden, och allt hans folk följde honom. Och alla hedningarna blevo i grund slagna av honom; och de kastade ifrån sig sina vapen och flydde till helgedomen i Karnain.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 44, 'Men israeliterna intogo staden och brände upp helgedomen i eld, tillika med alla dem som voro därinne. Och Karnain blev kuvat, och man kunde icke vidare stå emot Judas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 45, 'Nu församlade Judas alla israeliter i Galaaditis, både små och stora, och kvinnor och barn och ägodelar, en mycket stor hop, för att draga till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 46, 'Och de kommo till Efron. Detta var en stor och mycket fast stad, som låg vid ingången till passet, så att det icke var möjligt att komma fram vid sidan om den, vare sig till höger eller till vänster, utan man måste taga vägen mitt igenom den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 47, 'Men invånarna stängde staden för dem och spärrade för portarna med stenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 48, 'Då sände Judas bud till dem med fridsam hälsning och lät säga: »Låt oss tåga genom ditt område för att så komma fram till vårt land. Ingen skall göra eder någon skada; vi begära allenast att få tåga vägen fram härigenom.» Men de ville icke öppna för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 49, 'Då befallde Judas att man skulle ropa ut i hären att var och en skulle stanna på den plats där han befann sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 50, 'Och krigsmännen gjorde så. Och de stridde mot staden hela den dagen och hela den följande natten; och så blev staden given i hans händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 51, 'Och han förgjorde allt mankön med svärdsegg och förstörde staden i grund och tog all egendom i den såsom byte. Sedan tågade han igenom staden, fram över de slagnas kroppar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 52, 'Därefter gingo de över Jordan och kommo så till den stora slätten mitt emot Betsan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 53, 'Och Judas höll tillsammans dem som blevo efter och uppmuntrade folket, så länge de voro på väg, till dess han hade kommit fram till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 54, 'Och de drogo upp på Sions berg under glädje och fröjd och framburo brännoffer, därför att ingen enda av dem hade fallit, till dess de hade kommit välbehållna tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 55, 'Under den tid då Judas, jämte Jonatan, uppehöll sig i Galaads land, och hans broder Simon i Galileen framför Ptolemais,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 56, 'fingo Josef, Sakarias’ son, och Asarias, krigshövitsmännen i Judeen, höra talas om de krigiska bedrifter som de andra hade utfört.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 57, 'Då sade de: »Också vi vilja göra oss ett namn och draga ut för att strida mot hedningarna runt omkring oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 58, 'Och de bådade upp manskapet i den här som stod under deras befäl och drogo mot Jamnia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 59, 'Gorgias ryckte då ut ur staden med sitt folk för att möta dem i öppen strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 60, 'Och Josef och Asarias blevo slagna på flykten och förföljda ända till Judeens gränser; och på den dagen föllo av^ Israels folk vid pass två tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 61, 'Sålunda led folket ett stort nederlag, därför att de, i tro att de skulle kunna utföra bedrifter, icke hade hörsammat Judas och hans bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 62, 'Men dessa andra voro icke av de mäns släkt, genom vilkas hand räddning blev Israel beskärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 63, 'Hjälten Judas åter och hans bröder vunno stor ära hos hela Israel och hos alla hedningar, varhelst deras namn nämndes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 64, 'Och man församlade sig hos dem för att lyckönska dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 65, 'Judas och hans bröder drogo sedan ut och stridde mot Esaus barn i landet söderut; och han slog Hebron med underlydande orter och rev ned dess fästning och brände upp dess torn, runt omkring staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 66, 'Därefter bröt han upp för att tåga till filistéernas land och tog vägen genom Marisa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 67, 'Vid detta tillfälle föllo några präster i striden, när de ville utmärka sig och oförsiktigt gåvo sig ut i striden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 68, 'Judas vek nu av till Asotus, i filistéernas land. Och han rev ned deras altaren och brände upp deras avgudabilder och bemäktigade sig all egendom i städerna såsom byte. Därefter vände han tillbaka till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Under det att konung Antiokus tågade genom de övre landskapen, fick han höra att i Persien fanns en stad vid namn Elymais, som var beryktad för sin rikedom på silver och guld,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'och att dess helgedom var övermåttan rik, och att där funnos rustningar av guld, och pansar och andra vapen, som hade kvarlämnats där av den macedoniske konungen Alexander, Filippus’ son, som var den förste konungen över grekerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Han drog alltså dit och sökte intaga staden för att plundra den. Men han förmådde det icke, ty saken hade blivit bekant för stadens invånare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Och de reste sig till strid mot honom, och han måste fly och drog under stor grämelse därifrån, för att vända om till Babylon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Då kom en budbärare till honom i Persien, med underrättelse om att de härar som hade dragit till Judeen hade blivit slagna på flykten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'och att Lysias, som hade dragit dit i spetsen för en stark härsmakt, hade blivit slagen av judarna, och att dessa hade förstärkt sig genom vapen och manskap och rikt byte, som de hade tagit från de härar de hade nedgjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Vidare hade de rivit ned den styggelse som han hade låtit uppföra på altaret i Jerusalem och omgivit helgedomen med höga murar, så att den hade blivit sådan den förut var; på samma sätt hade de ock gjort med Betsura, som var en av hans egna städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'När konungen hörde allt detta, blev han häpen och mycket upprörd. Och han blev sängliggande och föll i en sjukdom, av grämelse över att det icke hade gått honom såsom han önskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Och han blev liggande där i lång tid, ty stor grämelse överföll honom alltjämt på nytt. Då han nu förstod att han skulle dö,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'kallade han till sig alla sina vänner och sade till dem: »Sömnen flyr mina ögon, och mitt sinne är nedtryckt av bekymmer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Och jag har sagt vid mig själv:’I vilket trångmål har jag icke råkat, och huru stor är icke den olycka som nu vill fördränka mig, jag som dock var så mild och så älskad, när jag utövade min konungamakt!’');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Men nu kommer jag ihåg det onda som jag har förövat i Jerusalem, huru jag har tagit alla kärl av guld och silver, som funnos i staden, och sänt ut folk för att utan orsak tillintetgöra inbyggarna i Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Jag förstår att det är därför som dessa olyckor hava drabbat mig. Och nu måste jag förgås av stor grämelse i ett främmande land.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Sedan kallade han till sig Filippus, en av sina vänner, och satte honom Över hela sitt rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Och han gav honom sin krona, sin mantel och sin ring, med uppdrag att leda hans son Antiokus och fostra honom för hans konungsliga kall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Och konung Antiokus gav där upp andan, år 149.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'När Lysias fick veta att konungen var död, insatte han till konung efter honom hans son Antiokus, som han hade fostrat under hans barndom, och gav honom namnet Eupator.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Men de som voro på borgen hindrade israeliterna från att fritt besöka helgedomen och sökte alltjämt bereda dem ofärd och utgjorde ett stöd för hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Judas begynte då tänka på att tillintetgöra dem; och han sammankallade hela folket för att belägra dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Och de församlade sig allasammans och begynte att belägra dem, år 150; Och han lät anordna ställningar för kastredskap och förfärdiga stormverktyg mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Men några av dem lyckades komma igenom avspärrningen, och till dem slöto sig en del ogudaktiga israeliter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Dessa begåvo sig till konungen och sade: »Huru länge skall du dröja med att hålla dom, och när skall du hämnas våra bröder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Vi voro villiga att tjäna din fader och vandra efter hans befallningar och följa hans bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Fördenskull blevo våra landsmän alltmer avogt sinnade mot oss; ja, så många av oss, som de träffade på, dödade de, och vår egendom plundrade de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 25, 'Och icke allenast mot oss hava de räckt ut sin hand, utan ock mot alla sina grannar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 26, 'Och se, nu hava de begynt att belägra borgen i Jerusalem för att intaga den; och de hava befäst helgedomen och Betsura.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 27, 'Om du nu icke skyndar att förekomma dem, skola de göra vad som är värre än detta; och du skall då icke längre kunna hejda dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 28, 'När konungen hörde detta, blev han vred. Och han församlade alla sina vänner, hövitsmännen över hans fotfolk och dem som förde befälet över ryttarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 29, 'Jämväl från andra riken och från öarna i havet kom lejt krigsfolk till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 30, 'Skaran av hans krigare uppgick till ett antal av ett hundra tusen man fotfolk och tjugu tusen ryttare; därtill kommo trettiotvå elefanter, som voro övade till strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 31, 'Och de drogo genom Idumeen och lägrade sig mitt emot Betsura; och de stridde i lång tid och förfärdigade stormverktyg. Men de belägrade gjorde ett utfall och brände upp dessa i eld och stridde med manligt mod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 32, 'Och Judas bröt upp från borgen och tågade till Betsakaria och lägrade sig där, mitt emot konungens läger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 33, 'Och bittida om morgonen lät konungen sin här, som var uppfylld av stridslust, bryta upp i riktning mot Betsakaria. Och krigsfolket ställde upp sig i stridsordning, och man blåste i trumpeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 34, 'För elefanterna ställde man fram röd saft av druvor och mullbär, för att uppegga dem till striden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 35, 'Sedan fördelade de djuren på de olika häravdelningarna och ställde bredvid var elefant ett tusen man till fots, som voro klädda i kedjepansar och hade kopparhjälmar på sina huvuden; därtill voro fem hundra utvalda ryttare avdelade för vart djur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 36, 'Dessa plägade redan på förhand ständigt uppehålla sig i elefantens närhet: de följde med vart den gick och veko icke ifrån den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 37, 'Och var elefant bar, förutom sin förare, ett starkt, skyddat trätorn, som var fastgjort på dess rygg med bukgjordar; och i vart torn funnos trettiotvå krigsmän, som förde striden från djurets rygg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 38, 'De återstående ryttarna ställde man upp å ömse sidor, på härens båda flyglar, för att därmed oroa fienderna och skaffa betäckning åt fotfolkets olika avdelningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 39, 'Och när solen lyste på sköldarna, som voro av guld eller koppar, lyste bergen av dem och flammade såsom brinnande facklor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 40, 'En del av konungens här bredde ut sig över bergshöjderna, en annan del åter på jämn mark; och de kommo framtagande med fasta steg och i god ordning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 41, 'Och alla bävade, när de hörde dånet av deras stora skaror och trampet av deras steg och slamret av deras vapen; hären var nämligen övermåttan stor och talrik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 42, 'Men Judas ryckte närmare med sin här för att inlåta sig i strid; och i den striden föllo sex hundra man av konungens här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 43, 'Därunder blev Eleasar Avaran bland elefanterna varse en som var betäckt med kungligt pansar, och som i storlek överträffade alla de andra djuren, så att det såg ut, som om den skulle bära konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 44, 'Då gav han sig själv till pris för att rädda sitt folk och förvärva sig ett evärdligt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 45, 'Han skyndade alltså djärvt fram mot den, mitt in i häravdelningen, och högg ned fiender till höger och vänster, så att de drevos undan från den åt ömse sidor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 46, 'Därefter böjde han sig ned under elefanten och gav den en stöt i buken och dödade den så. Och när den störtade till marken, föll den över honom. Så fann han där sin död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 47, 'Men när Judas’ män märkte huru stark konungens här var, och med vilken häftighet krigsfolket gjorde sina anfall, veko de undan för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 48, 'Konungens krigsmän drogo nu upp till Jerusalem för att möta judarna i strid; och konungen lägrade sig gent emot Judeen och Sions berg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 49, 'Med besättningen i Betsura slöt han fred. De måste lämna staden, ty de hade icke nog livsmedel där för att kunna uthärda en belägring i den; landet hade nämligen då sitt sabbatsår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 50, 'Konungen intog alltså Betsura och lade där in en besättning för att försvara staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 51, 'Därefter belägrade han helgedomen i lång tid och uppförde där ställningar för kastredskap och ställde upp stormverktyg och redskap för att kasta eld och stenar, så ock skorpioner för att skjuta pilar, och därtill slungor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 52, 'Men de belägrade förfärdigade, också de, krigsredskap till försvar mot fiendens och stridde i lång tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 53, 'Men de hade icke några livsmedel i sina förrådsrum, eftersom det nu var det sjunde året; och de som hade blivit räddade och förda upp till Judeen från hedningarnas land hade förtärt vad som fanns kvar av förråden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 54, 'Därför stannade allenast några få krigsmän kvar vid helgedomen, ty hungern blev dem övermäktig; och de skingrades, var och en till sin hemort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 55, 'Då fick Lysias höra att Filippus, vilken konung Antiokus före sin död hade satt till att leda sin sons uppfostran för hans konungsliga kall,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 56, 'hade kommit tillbaka från Persien och Me-dien, i spetsen för den här som hade följt konungen, och att han sökte efter att bemäktiga sig riksstyrelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 57, 'Han blev därför med ens benägen till avtag och sade till konungen och anförarna för hären, så ock till manskapet: »Vi bliva för var dag allt svagare och hava helt obetydligt med livsmedel, och platsen som vi belägra är fast, och därtill vilar omsorgen om hela riket på oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 58, 'Låt oss fördenskull ingå förlikning med dessa män och sluta fred med dem och med hela deras folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 59, 'Vi vilja tillstädja dem att såsom förut vandra efter sina egna stadgar; ty det är därför att vi hava upphävt dessa deras stadgar, som de hava blivit uppretade och gjort allt detta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 60, 'Det talet behagade konungen och hövitsmännen väl; och han sände bud till judarna och erbjöd dem fred, och dessa gingo in därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 61, 'Och sedan konungen och hövitsmännen hade givit dem edlig bekräftelse på villkoren, drogo de ut ur fästningen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 62, 'och konungen tågade in på Sions berg. Men när han såg huru väl befäst platsen var, svek han den ed som han hade svurit, och bjöd att man skulle riva ned murarna runt omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 63, 'Därefter bröt han skyndsamt upp och vände tillbaka till Antiokia; och när han fann Filippus vara herre i staden, inlät han sig i strid med honom och intog staden med våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 1, 'År 151 undkom Demetrius, Seleukus’ son, från Rom och landsteg med några få följeslagare i en stad vid kusten och uppträdde där såsom konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 2, 'Och när han därefter drog in i sina fäders konungapalats, grep krigsfolket Antiokus och Lysias för att föra dem till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 3, 'Men då han fick veta detta, sade han: »Låten dem icke komma inför mina ögon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 4, 'Så blevo de då dödade av krigsfolket, och Demetrius besteg sitt rikes tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 5, 'Då begåvo sig alla avfälliga och ogudaktiga israeliter till honom, och de anfördes av Alcimus, som ville bliva erkänd såsom överstepräst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 6, 'Dessa anklagade sitt folk inför konungen och sade: »Judas och hans bröder hava röjt alla dina vänner ur vägen, och oss har han fördrivit ifrån vårt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 7, 'Så sänd nu åstad någon som du litar på, och låt honom komma för att med egna ögon se allt det fördärv som Judas har dragit över oss och konungens land, och för att straffa dessa och alla som hava varit dem behjälpliga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 8, 'Konungen utsåg då härtill Backides, en av konungens vänner, som var ståthållare i landet på andra sidan floden och var en högt uppsatt man i riket och trogen konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 9, 'Denne sände han åstad jämte den ogudaktige Alcimus, vilken han tillförsäkrade den översteprästerliga värdigheten; och han bjöd honom att utkräva hämnd på Israels barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 10, 'De bröto alltså upp och kommo med en stor här till Judeen. Backides sände nu, i sviklig avsikt, budbärare till Judas och hans bröder med fridsam hälsning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 11, 'De aktade likväl icke på deras ord, eftersom de sågo att de hade kommit dit i spetsen för en stor här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 12, 'Men en skara skriftlärde församlade sig hos Alcimus och Backides för att söka vinna rättvisa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 13, 'Och asidéerna voro de första bland Israels barn, som sökte utverka fred av dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 14, 'ty de tänkte: »Det är en präst av Arons släkt, som har kommit med detta krigsfolk; han skall icke göra oss något ont.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 15, 'Och han gav dem fredliga försäkringar och lovade dem med ed att de icke skulle söka bereda dem och deras vänner ofärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 16, 'Och de satte tro till honom. Men han lät gripa sextio män av dem och dräpa dem på en och samma dag, såsom skriften säger: 17 »Dina frommas döda kroppar hava de kastat ut, och deras blod hava de utgjutit runt omkring Jerusalem, och ingen fanns, som begrov dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 17, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 18, 'Och fruktan och förskräckelse för dem föll över hela folket; de sade: »Ingen sanning och rätt finnes hos dem. De hava ju brutit överenskommelsen och den ed som de svuro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 19, 'Men Backides bröt upp från Jerusalem och lägrade sig i Betset. Därifrån sände han åstad och lät gripa ett stort antal av sina anhängare, som hade gått över till fienderna, och därtill några bland folket; och han lät avliva dem och kasta deras kroppar i den stora brunnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 20, 'Därefter överlät Backides landet åt Alcimus och lämnade kvar hos honom en häravdelning till hans hjälp och begav sig sedan tillbaka till konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 21, 'Alcimus kämpade nu ivrigt för sitt översteprästämbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 22, 'Och hos honom församlade sig alla de som sökte väcka förvirring bland sitt folk; och de bemäktigade sig Judeen och foro mycket våldsamt fram i Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 23, 'När Judas såg allt det onda som Alcimus och hans anhängare förövade bland Israels barn, i ännu högre mått än hedningarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 24, 'drog han omkring till alla trakter av Judeen och utkrävde hämnd på dem som hade gått över till fienderna; och de hindrades från att fritt röra sig i landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 25, 'Men då nu Alcimus såg att Judas och hans anhängare fingo överhanden, och märkte att han icke kunde hålla stånd mot dem, vände han tillbaka till konungen och framställde svåra anklagelser mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 26, 'Konungen sände då Nikanor, en av sina anseddaste hövitsmän, vilken var uppfylld av hat och fiendskap mot Israel, med uppdrag att tillintetgöra folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 27, 'Och sedan Nikanor med en stor här hade kommit fram till Jerusalem, sände han, i sviklig avsikt, bud till Judas och hans bröder med fridsam hälsning och lät säga: 28 »Icke må det vara någon strid mellan mig och eder. Jag vill komma till eder, i sällskap med några få män, för att i fred och vänskap sammanträffa med eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 28, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 29, 'Och han begav sig till Judas, och de hälsade varandra fredligt. Men fienderna stodo färdiga att föra bort Judas med våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 30, 'Saken blev dock bekant för Judas, nämligen att han i sviklig avsikt hade kommit till honom. Judas drog sig därför skyggt undan och vägrade att vidare sammanträffa med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 31, 'När Nikanor märkte att hans anslag hade blivit röjt, drog han ut till öppen strid mot Judas vid Kafarsalama.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 32, 'Därvid föllo av Nikanors folk vid pass fem hundra man; de Övriga flydde till Davids stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 33, 'Härefter steg Nikanor upp på Sions berg. Då trädde några av prästerna ut från helgedomen, så ock några av folkets äldste, för att fredligt hälsa honom och visa honom det brännoffer som just höll på att frambäras för konungens välgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 34, 'Men han drev gäck med dem och gjorde spe av dem och förorenade dem och talade övermodiga ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 35, 'Och han svor i vrede en ed och sade: »Såframt icke Judas och hans här nu strax överlämnas i min hand, skall jag, när jag välbehållen kommer tillbaka, bränna upp detta hus.» Och han gick sin väg därifrån i stor vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 36, 'Då gingo prästerna in igen och ställde sig framför altaret och templet och brusto ut i gråt och sade: 37 »Du har ju själv utvalt detta hus till att uppkallas efter ditt namn, för att tjäna ditt folk till ett hus för åkallan och bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 37, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 38, 'Så utkräv nu hämnd på denne man och på hans här, och låt dem falla för svärd. Kom ihåg deras hädelser, och låt dern icke bliva beståndande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 39, 'Och Nikanor drog bort ifrån Jerusalem och lägrade sig i Betoron; där förenade sig en här från Syrien med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 40, 'Judas åter lägrade sig i Adasa med tre tusen man. Och Judas bad och sade: 41 »När en gång den assyriske konungens sändebud hädade, gick din ängel ut och slog ett hundra åttiofem tusen man i hans här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 41, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 42, 'Låt likaså denna här i dag bliva i grund slagen av oss, för att de övriga må förstå att han har talat smädliga ord mot din helgedom; och döm honom efter hans ondska.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 43, 'Och på trettonde dagen i månaden Adar drabbade härarna samman till strid. Och Nikanors här blev slagen, och själv var han den förste som föll i striden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 44, 'Men när hären såg att Nikanor var fallen, kastade de ifrån sig sina vapen och flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 45, 'Och judarna förföljde dem en dagsresa, från Adasa fram till Gasera, och de blåste i larmtrumpeterna bakom dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 46, 'Då drog folket ut från alla byar i Judeen runt omkring och angrep dem från alla sidor, så att de vände sig mot varandra. Och de föllo allasammans för svärd; icke en enda av dem slapp undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 47, 'Och judarna togo byte och rov; och Nikanors huvud höggo de av, så ock hans högra hand, som han i övermod hade lyft mot höjden, och togo dem med sig till Jerusalem och fäste upp dem där, högt uppe i höjden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 48, 'Nu gladde sig folket högeligen, och de firade den dagen såsom en stor glädjedag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 49, 'Och de bestämde att denna dag årligen skulle firas på den trettonde dagen i månaden Adar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 50, 'Och Judeen hade nu rö en kort tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 1, 'Nu fick Judas höra sägas om romarna att de voro tappra stridsmän, och att de visade välvilja mot alla som slöto sig till dem, och ingingo vänskap med alla som vände sig till dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 2, 'och att de, såsom sagt är, voro tappra stridsmän. Man berättade för honom om deras krig och om de bedrifter som de hade utfört bland galaterna, och huru de hade övervunnit dessa och gjort dem skattskyldiga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 3, 'så ock om allt som de hade uträttat i Spanien, i det att de hade bemäktigat sig silver- och guldgruvorna där,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 4, 'och huru de genom sin klokhet och ihärdighet hade bemäktigat sig hela det landet, fastän det låg mycket långt avlägset från deras eget. De hade likaledes övervunnit de konungar som hade dragit emot dem från jordens ända, så att de i grund hade slagit dem och tillfogat dem svåra nederlag och tvingat de överblivna att betala dem en årlig skatt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 5, 'Och man berättade huru de hade i strid slagit och övervunnit Filippus, så ock Perseus, kittéernas konung, och de andra som hade upprest sig mot dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 6, 'likaså huru Antiokus den store, konungen i Asien, som drog ut till strid mot dem med ett hundra tjugu elefanter och med ryttare och vagnar och en mycket stor här till fots, i grund hade blivit slagen av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 7, 'Honom själv hade de fått levande i sitt våld, och de hade ålagt honom och hans efterträdare att betala dem en dryg skatt och lämna gisslan och avträdaland åt dem,’');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 8, 'nämligen Indien, Medien och Lydien, så ock andra av deras skönaste länder; och när de hade mottagit dessa av honom, hade de givit dem åt konung Eumenes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 9, 'Och vidare berättade man huru Greklands folk hade fattat det beslutet att komma och tillintetgöra dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 10, 'men huru de hade fått kunskap härom och sänt en härhövitsman mot dem och utkämpat en strid med dem. Därvid hade många av dessa fallit slagna; och deras kvinnor och barn hade de fört bort såsom fångar, och de hade utplundrat dem och bemäktigat sig deras land och förstört deras fästningar. De hade utplundrat dem och gjort dem sig underdåniga allt intill denna dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 11, 'Och alla övriga konungariken och alla de öar som hade satt sig upp mot dem hade de i grund kuvat och gjort sig underdåniga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 12, 'Med sina vänner och dem som satte sin lit till dem hade de däremot hållit vänskap, men övervunnit de konungar som bodde nära och fjärran, så att alla som hörde dem omtalas fruktade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 13, 'Ty alla som de ville hjälpa och göra till konungar, de fingo bliva konungar, men dem som de ville avsätta, dem avsatte de. Och på det sättet hade de kommit till mycket stor makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 14, 'Och trots allt detta hade ingen av dem satt på sig konungakronan eller iklätt sig purpurmanteln för att yvas i den,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 15, 'utan de hade inrättat åt sig en rådsförsamling, och där rådplägade dagligen tre hundra tjugu män, i det att de beständigt lade råd angående menigheten, för att ordna för den på bästa sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 16, 'Och de anförtrodde åt en enda man att för ett år vara deras högste styresman och att härska över hela deras område; och alla hörsammade denne ende, och ingen avund eller tävlan om makten fanns bland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 17, 'Judas utsåg nu Eupolemus, son till Johannes, Ackos’ son, och Jason, Eleasars son, och sände dem åstad till Rom, för att ingå vänskap och förbund med romarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 18, 'och för att dessa skulle avlyfta oket från dem, eftersom de ju kunde se huru det grekiska riket höll Israel i träldom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 19, 'De begåvo sig alltså åstad till Rom; och vägen dit var mycket lång. När de nu hade kommit inför rådsförsamlingen, togo de till orda och sade: 20 »Judas, som ock kallas Mackabeus, och hans bröder och det judiska folket hava sänt oss till eder, för att med eder ingå fred och förbund, och för att vi skola bliva upptagna bland edra bundsförvanter och vänner.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 20, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 21, 'Det talet behagade dem väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 22, 'Och så lyder avskriften av den skrivelse som de såsom svar läto inrista på koppartavlor och sände till Jerusalem, för att där hos dem förvaras till en påminnelse om den fred och det förbund som hade ingåtts:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 23, '»Må det gå romarna och det judiska folket väl till lands och vatten i evärdlig tid, och må svärd och fiende vara fjärran ifrån dem!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 24, 'Men om krig först hotar Rom eller någon av dess bundsförvanter inom hela dess välde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 25, 'så skall det judiska folket, alltefter som omständigheterna kräva av dem, av uppriktigt hjärta komma dem till hjälp i striden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 26, 'och åt krigsfolket skola romarna icke behöva vare sig giva eller tillhandahålla livsmedel, vapen, penningar eller skepp, annat än om de själva så finna för gott. Och det judiska folket skall uppfylla dessa sina förpliktelser, utan att taga någon ersättning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 27, 'Och på samma sätt: om det judiska folket först råkar ut för krig, så skola romarna med villigt sinne komma dem till hjälp i striden, alltefter som omständigheterna kräva av dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 28, 'och åt hjälphären skall man icke behöva giva livsmedel, vapen, penningar eller skepp, annat än om romarna så finna för gott. Och de skola uppfylla dessa förpliktelser, och det utan svek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 29, 'I enlighet med dessa bestämmelser hava romarna träffat avtal med det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 30, 'Men om härefter endera parten önskar lägga något till eller taga något ifrån dessa bestämmelser, så skola de få göra detta efter sitt eget behag; och vad de sålunda till-lägga eller borttaga, det skall hava gällande kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 31, 'Vad åter angår det onda som konung Demetrius tillfogar eder, så hava vi skrivit ett brev till honom, av följande innehåll:’Varför har du lagt ett så tungt ok på våra vänner och bundsförvanter judarna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 32, 'Om de nu ytterligare komma och anföra klagomål mot dig, så skola vi skaffa dem rätt och föra krig mot dig både till lands och vatten.’»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 1, 'När Demetrius fick höra att Nikanor och hans här hade fallit i striden, sände han ånyo, för andra gången, Backides och Alcimus till Judeen, med högra flygeln av sin här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 2, 'Och de slogo in på vägen till Galgala och lägrade sig gent emot Mesalot i Arbela och intogo staden och anställde en stor manspillan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 3, 'I första månaden av år 152 lägrade de sig framför Jerusalem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 4, 'sedan bröto de upp därifrån och tågade till Berea, med tjugu tusen man fotfolk och två tusen ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 5, 'Judas låg nu lägrad i Elasa med tre tusen man utvalt manskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 6, 'Men när dessa sågo att den fientliga hären var så stor, blevo de högeligen förskräckta; och många gåvo sig bort ifrån lägret, så att slutligen icke mer än åtta hundra man funnos kvar av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 7, 'Då nu Judas såg att hans här hade givit sig av, men på samma gång förstod att strid var oundviklig, blev han mycket illa till mods över att han icke hade tid nog till att samla sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 8, 'Och i sin förtvivlan sade han till dem som hade stannat kvar: »Låt oss bryta upp och draga fram mot våra motståndare; måhända kunna vi utkämpa en strid med dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 9, 'Men de sökte avråda honom och sade: »Det kunna vi förvisso icke. Låt oss hellre nu rädda våra liv, så vilja vi sedan återvända tillsammans med våra bröder och strida mot dem. Vi äro ju alltför få.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 10, 'Men Judas sade: »Bort det, att jag skulle så göra och fly för dem! Är vår stund kommen, låt oss då ock manligen dö för våra bröder; må vi icke lämna en fläck,på vår ära.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 11, 'Men den fientliga hären bröt upp från lägret, och de ställde upp sig mot dem. Ryttarna delades i två hopar, och framför fotfolket gingo slungarna och bågskyttarna, tillika med alla de tappraste, som skulle kämpa i främsta ledet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 12, 'Backides själv befann sig på högra flygeln. Så ryckte nu hären i full slagordning fram med båda flyglarna, och de blåste i trumpeterna. Också Judas’ män stötte i sina trumpeter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 13, 'och marken darrade av larmet från härarna; och striden begynte bittida om morgonen och varade ända till sena aftonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 14, 'När Judas såg att Backides med kärnan av hären befann sig på högra flygeln, vände han sig dit, och med honom alla de modigaste männen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 15, 'Och högra flygeln blev i grund slagen av dem, och de förföljde den till berget Asotus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 16, 'Men när de som stodo på vänstra flygeln sågo att den högra flygeln hade blivit slagen, vände de om och följde tätt bakefter Judas och hans folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 17, 'Nu uppstod en häftig strid, och många föllo slagna på vardera sidan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 18, 'Också Judas föll, och de övriga flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 19, 'Men Jonatan och Simon togo upp sin broder Judas\' kropp, och de begrovo honom i hans fäders grav i Modein.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 20, 'Och de begräto honom där, och hela Israel höll stor dödsklagan efter honom och sörjde honom i många dagar; de sjöngo:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 21, '»Huru har icke hjälten fallit, Israels frälsare!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 22, 'Vad nu mer är att säga om Judas och om de strider som han utkämpade och de bedrifter som han utförde och om hans storhet, det har icke blivit upptecknat, ty det skulle bliva alltför mycket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 23, 'Efter Judas’ död reste de avfälliga åter huvudet överallt inom Israels område, och alla de som gjorde vad orätt var frodades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 24, 'Vid den tiden uppstod en mycket svår hungersnöd, så att folket i landet gick över till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 25, 'Och Backides utvalde de ogudaktiga och satte dem till herrar över landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 26, 'Och dessa efterspanade och spårade upp Judas’ vänner och förde dem inför Backides; och han straffade dem och behandlade dem skymfligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 27, 'Och det blev ett stort betryck i Israel, så stort att dess like icke hade förekommit, allt ifrån den tid då en profet för sista gången lät sig ses bland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 28, 'Då församlade sig alla Judas’ vänner och sade till Jonatan: 29 »Alltsedan din broder Judas har gått bort, finnes icke någon hans like, någon som kan draga ut mot fienderna och Backides och mot dem som hata vårt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 30, 'Därför välja vi dig nu i dag till att i hans ställe vara vår hövding och anförare och föra vår strid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 31, 'Jonatan mottog alltså på den dagen högsta ledningen och trädde i sin broder Judas’ ställe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 32, 'När Backides fick veta detta, sökte han efter tillfälle att döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 33, 'Men då Jonatan, och hans broder Simon och alla hans anhängare fingo veta detta, flydde de till Tekoas öken och lägrade sig vid brunnen Asfars vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 34, 'Detta fick Backides veta på sabbatsdagen och drog då med hela sin krigshär över till andra sidan av Jordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 35, 'Jonatan hade nämligen sänt sin broder Johannes åstad såsom anförare för trossen, och bett sina vänner nabatéerna att de skulle få lämna sina många tillhörigheter i förvar hos dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 36, 'Då drogo Jambris barn ut från Medaba och fingo Johannes och allt vad han förde med sig i sitt våld och tågade bort därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 37, 'Men sedan hade det blivit berättat för Jonatan och hans broder Simon att Jambris barn. just höllo på att fira ett stort bröllop, och att de nu voro på väg för att hämta bruden, som var dotter till en av de förnämsta stormännen i Kanaan, från Nadabat med stort följe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 38, 'Då tänkte de på sin broder Johannes och tågade ditupp och gömde sig i en hålväg i berget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 39, 'När de nu lyfte upp sina ögon, fingo de se ett tåg komma, med stort larm och präktig utrustning. Det var brudgummen och hans vänner och fränder som drogo ut för att möta brudföljet, med pukor och andra musikinstrument och en mängd tillbehör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 40, 'Då bröto de fram mot dem från bakhållet och anställde ett blodbad på dem. Många föllo slagna, och de övriga flydde in bland bergen; och all deras utrustning togo de såsom byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 41, 'Och bröllopet blev förbytt i sorg och deras spel i klagosång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 42, 'Så hämnades de sin broders blod och vände därefter tillbaka till Jordans sumpmarker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 43, 'Detta fick Backides höra, och han kom på sabbatsdagen till Jordans stränder med en stor här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 44, 'Då sade Jonatan till sina landsmän: »Låt oss nu stå upp och strida för våra liv. Ty aldrig någonsin förr hava vi varit i så stor fara som i dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 45, 'Se, fienderna äro ju både framför oss och bakom oss, och på ömse sidor hava vi Jordans vatten, därtill ock sumpmark och skogsmark, och det finnes icke någon möjlighet till att undkomma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 46, 'Så ropen nu till himmelen att I mån bliva frälsta ur edra fienders hand.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 47, 'Och striden begynte, och Jonatan räckte ut sin hand för att stöta ned Backides, men denne drog sig tillbaka undan honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 48, 'Då kastade sig Jonatan och hans män i Jordan och simmade över till andra stranden. Men fienderna gingo icke över Jordan efter dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 49, 'Och på Backides’ sida föllo på den dagen vid pass tre tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 50, 'Denne vände sedan tillbaka till Jerusalem och förstärkte flera fasta städer i Judeen, fästningen vid Jeriko, så ock Ammaus, Betoron, Betel, Tamnata-Faraton och Tefon, med höga murar och portar och bommar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 51, 'Och man lade in besättningar i dem för att oroa Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 52, 'Han befäste också ytterligare staden Betsura och Gasara och borgen och lade i dem in krigsfolk och förråd av livsmedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 53, 'Och han tog sönerna till de anseddaste männen i landet såsom gisslan och satte dem i förvar på borgen i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 54, 'I andra månaden av år 153 gav Alcimus befallning om att riva ned muren till helgedomens inre förgård och ville så riva ned vad profeterna hade byggt upp. Men i samma stund som Alcimus begynte härmed,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 55, 'drabbades han av en hemsökelse, så att hans företag förhindrades; och hans mun blev tillstoppad, i det att han blev förlamad, så att han icke vidare kunde tala eller beställa om sitt hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 56, 'Så dog då Alcimus, vid den tiden, under svåra plågor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 57, 'När Backides fick underrättelse om att Alcimus var död, vände han tillbaka till konungen. Och Judeen hade nu ro i två år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 58, 'Men de avfälliga lade samfällt råd och sade: »Se, Jonatan och hans anhängare sitta i rö och säkerhet. Nu vilja vi därför hämta hit Backides; han skall gripa dem allasammans på en enda natt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 59, 'Så begåvo de sig då åstad till honom och lade råd med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 60, 'Han bröt nu upp och kom tågande med en stor här och sände i hemlighet brev till alla sina bundsförvanter i Judeen, med befallning att de skulle gripa Jonatan och dem som voro med honom. Men de förmådde det icke, ty de andra fingo vetskap om deras plan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 61, 'Och dessa grepo själva vid pass femtio av landets inbyggare, som voro anstiftare av det onda anslaget, och dräpte dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 62, 'Därefter drogo sig Jonatan och Simon och hans anhängare undan till Betbasi i öknen; och han byggde åter upp vad som var förstört av staden och befäste den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 63, 'När Backides fick veta detta, samlade han allt sitt krigsfolk och bådade upp dem som voro från Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 64, 'Och han kom och lägrade sig framför Betbasi och stridde mot den staden i lång tid och lät förfärdiga stormverktyg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 65, 'Då lämnade Jonatan sin broder Simon kvar där i staden och drog själv med några få män ut på landsbygden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 66, 'Och han slog Odomera och hans bröder, så ock Fasirons barn, i deras tältläger. När han sedan begynte att göra anfall mot fienden och rycka närmare med sin skara,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 67, 'gjorde Simon och hans folk ett utfall från staden och brände upp stormverktygen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 68, 'Och de stridde mot Backides, och han blev i grund slagen av dem; och de vållade honom stor grämelse, därför att hans plan och hans krigståg hade misslyckats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 69, 'Han upptändes nu av vrede mot de avfällingar som hade givit honom det rådet att draga dit till landet; och man lät avliva många av dem. Sedan beslöt Backides att draga därifrån till sitt land igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 70, 'När Jonatan fick veta detta, skickade han sändebud till honom för att ingå fred med honom och utverka att fångarna skulle utlämnas åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 71, 'Backides gick in härpå och gjorde såsom han begärde; ytterligare lovade han honom med ed att han icke mer, så länge han levde, skulle söka bereda honom ofärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 72, 'Och han utlämnade åt honom de fångar som han tidigare hade tagit i Judeen. Sedan vände han om och drog till sitt land igen och kom aldrig vidare inom Judeens gränser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 73, 'Så fick nu svärdet vila i Israel. Och Jonatan bosatte sig i Makmas. Sedan begynte Jonatan att uppträda såsom folkets styresman, och han utrotade de ogudaktiga ur Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 1, 'År 160 drog Alexander Epifanes, Antiokus’ son, ditupp och intog Ptolemais, och invånarna mottogo honom hos sig, och han uppträdde såsom konung där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 2, 'När konung Demetrius fick höra detta, samlade han en mycket stor här och drog ut för att möta honom i öppen strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 3, 'Och till Jonatan sände Demetrius ett brev med fridsam hälsning, i avsikt att bevisa honom stor heder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 4, 'Ty han tänkte: »Vi vilja skynda oss att i förväg ingå fredlig överenskommelse med dem, innan han ingår en sådan med Alexander mot oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 5, 'Ty han kommer icke att förgäta allt det onda som vi hava gjort honom och hans bröder och hans folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 6, 'Och han gav Jonatan myndighet till att samla krigsfolk och företaga rustningar och till att vara hans bundsförvant, och lovade att han skulle åt honom utlämna dem som befunno sig på borgen såsom gisslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 7, 'Jonatan begav sig då till Jerusalem och läste upp brevet inför hela folket och inför besättningen på borgen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 8, 'Dessa blevo storligen förfärade, när de fingo höra att konungen hade givit honom myndighet till att samla krigsfolk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 9, 'Och besättningen på borgen utlämnade till Jonatan dem som befunno sig där såsom gisslan, och han överlämnade dem åt deras föräldrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 10, 'Jonatan bosatte sig nu i Jerusalem och begynte att uppbygga och återställa staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 11, 'Och han befallde dem som utförde arbetena att bygga stadsmurarna och befästningarna vid Sions berg, runt omkring, av huggen sten och därmed förstärka platsen; och de gjorde så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 12, 'De utlänningar som bodde i de fästningar som Backides hade låtit förstärka togo nu till flykten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 13, 'var och en lämnade den plats där han befann sig och begav sig därifrån hem till sitt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 14, 'Allenast i Betsura stannåde några kvar av dem som hade övergivit lagen och stadgarna; denna plats tjänade dem nämligen såsom tillflyktsort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 15, 'När konung Alexander fick höra talas om alla de löften som Demetrius i sitt brev hade givit Jonatan, och när man för honom berättade om de strider som denne och hans bröder hade utkämpat, och om de bedrifter som de hade utfört, och om de vedermödor som de hade haft att utstå,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 16, 'då sade han: »Skulle vi väl kunna finna en sådan mans like? Vi vilja nu göra honom till vår vän och bundsförvant.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 17, 'Han skrev alltså ett brev, som han sände honom. Det lydde så:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 18, '»Konung Alexander hälsar sin broder Jonatan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 19, 'Vi hava hört sägas om dig att du är en tapper stridsman, och att du är väl ägnad till att vara vår vän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 20, 'Därför insätta vi dig nu i dag till överstepräst för ditt folk och förordna att du skall kallas konungens vän» - samtidigt sände han honom en purpurmantel och en gyllene krona - »och bedja dig att du ville stå på vår sida och hålla vänskap med oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 21, 'Jonatan iförde sig då den heliga skruden i sjunde månaden av år 160, vid lövhyddohögtiden. Och han samlade krigsfolk och företog stora rustningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 22, 'Då nu Demetrius fick höra talas härom, blev han illa till mods och sade: 23 »Varför hava vi låtit detta ske, att Alexander har förekommit oss med att träda i vänskapsförhållande till judarna och så stärkt sin makt?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 23, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 24, 'Också jag vill skriva till dem för att söka övertala dem med löften om upphöjelse och förmåner, på det att de må hålla med mig och hjälpa mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 25, 'Och han sände dem ett brev av följande lydelse: »Konung Demetrius hälsar det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 26, 'Vi hava med fägnad hört att I haven hållit de med oss ingångna fördragen och stått fast vid vänskapen med oss och icke övergått till våra fiender.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 27, 'Fortfaren nu ock allt framgent att iakttaga trohet mot oss, så skola vi bereda eder fördelar, till tack för vad');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 28, 'I gören till vårt gagn; vi skola bevilja eder många eftergifter och tilldela eder många förmåner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 29, 'Härmed löser jag eder och fritager alla judar från de personliga avgifterna och från saltskatten och kransskatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 30, 'Och den ersättning för tredjedelen av grödan och för hälften av trädfrukterna, som det tillkommer mig att uppbära, vill jag från denna dag och allt framgent avstå från att uppbära i Judeen och i de tre områden som härmed läggas till detta land från Samarien och Galileen, allt ifrån denna dag och för evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 31, 'Och Jerusalem med angränsande område må vara heligt och vara fritaget ifrån skatter; fritagna vare ock tiondegärderna och tempelinkomsterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 32, 'Jag avstår också från rätten till borgen i Jerusalem och överlåter den åt översteprästen, för att han där, till dess försvar, må lägga in en besättning av sådant manskap som han själv vill utvälja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 33, 'Och envar jude inom hela mitt rike, som har blivit bortförd i fångenskap ifrån Judeen, giver jag fri för intet. Och alla mina tjänstemän må efterlåta avgifterna jämväl för deras fäkreatur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 34, 'Och alla högtider och sabbater och nymånader och övriga fastställda festdagar, och tre dagar före och tre dagar efter högtiderna, alla dessa dagar skola för alla judar som bo i hela mitt rike vara fria ifrån indrivning av skatter och avgifter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 35, 'och ingen skall under dem hava rättighet att kräva någon av dem eller falla någon besvärlig för en rättssak, vilken det vara må.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 36, 'Vidare må vid pass trettio tusen judar uppföras bland konungens krigsmän; och underhåll skall givas åt dem, i likhet med vad som tillkommer konungens alla övriga krigsmän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 37, 'En del av dem skall inläggas i konungens största fästningar, och några av dem skola sättas på förtroendeposter i riket. Och deras befälhavare och hövitsmän skola uttagas bland dem själva. Och de skola få vandra efter sin egen lag, såsom konungen har förordnat angående dem som bo i Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 38, 'Och de tre områden som hava blivit lagda till Judeen från Samarien, de skola tilläggas Judeen på så sätt att de skola anses stå under en och samme styresman och icke lyda under någon annan myndighet än översteprästens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 39, 'Ptolemais med tillhörande område giver jag såsom gåva åt helgedomen i Jerusalem, för att de kostnader som äro förbundna med tjänsten i helgedomen skola betalas därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 40, 'Och för egen del giver jag årligen femton tusen siklar silver av konungens inkomster, vilka skola utgå från lämpliga orter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 41, 'Och allt som ännu återstår att betala, vad mina ämbetsmän ännu icke hava avlämnat, såsom skedde under tidigare år, allt detta skola de härefter lämna för tjänstgöringen i Guds hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 42, 'Och vidare: de fem tusen siklar silver som man har plägat upptaga av templets medel, av de årligen inflytande inkomsterna, också dessa penningar efterskänkas, eftersom de tillkomma prästerna, som göra tjänst där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 43, 'Och envar som flyr till helgedomen i Jerusalem med hela dess område, därför att han står i skuld till konungen, eller därför att han har ådragit sig skuld på något annat sätt, envar sådan skall, med allt vad han äger i mitt rike, vara befriad från straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 44, 'Och kostnaderna för att återställa och förnya helgedomens byggnader skola betalas av konungens inkomster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 45, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 46, 'Likaså skola kostnaderna för att återställa Jerusalems murar och befästa det runt omkring betalas av konungens inkomster; detsamma skall gälla i fråga om kostnaderna för att återställa fästningsmurarna på andra orter i Judeen.» När Jonatan och folket hörde dessa löften läsas upp, satte de ingen tro till dem och antogo dem icke; ty de tänkte på det myckna onda som konungen hade gjort i Israel och på det svåra betryck som han hade dragit över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 47, 'De föredrogo i stället Alexander, därför att denne var den förste som hade sänt dem fridsam hälsning, och de förblevo hela tiden hans bundsförvanter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 48, 'Men konung Alexander samlade en stor här och lägrade sig mitt emot Demetrius.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 49, 'Och de båda konungarna drabbade samman, och Demetrius’ här flydde. och Alexander förföljde honom och fick överhanden över dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 50, 'och han fortsatte striden mycket hårdnackat, ända till dess solen gick ned. Och Demetrius föll på den dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 51, 'Sedan skickade Alexander sändebud till Ptolemeus, konungen i Egypten, med en hälsning av följande innehåll:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 52, '»Jag har nu kommit igen till mitt rike och satt mig på mina fäders tron och fått makten i mina händer och i grund slagit Demetrius och blivit herre över vårt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 53, 'Jag har nämligen drabbat samman med honom, och han själv och hans här hava blivit slagna av oss, och så hava vi satt oss på hans konungatron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 54, 'Då nu så är, må vi ingå vänskap med varandra. Giv du mig din dotter till äkta; jag vill bliva din måg och vill giva dig och henne skänker som äro dig värdiga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 55, 'Konung Ptolemeus svarade sålunda: »Vilken lycklig dag detta är, då du har kommit tillbaka till dina fäders land och satt dig på deras konungatron!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 56, 'Vad angår det som du har begärt i ditt brev, så vill jag göra det. Men möt mig i Ptolemais, så att vi få träffa varandra; jag vill då taga dig till min måg, såsom du har föreslagit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 57, 'Så drog då Ptolemeus ut ur Egypten med sin dotter Kleopatra och kom till Ptolemais, år 162.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 58, 'Och konung Alexander mötte honom där; Ptolemeus gav honom då sin dotter Kleopatra till äkta och gjorde bröllop åt henne i Ptolemais med stor ståt, såsom konungar pläga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 59, 'Konung Alexander skrev nu till Jonatan att denne skulle komma dit för att möta honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 60, 'Och han drog med ståt till Ptolemais och träffade där samman med de båda konungarna. Och han gav dem och deras vänner silver och guld och många skänker, och han fann nåd för deras ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 61, 'Mot honom församlade sig nu några skändliga israelitiska män, avfällingar från lagen, för att anföra klagomål mot honom; men konungen aktade icke på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 62, 'Konungen befallde i stället sina tjänare att taga av Jonatan hans egna kläder och kläda honom i purpur; och de gjorde så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 63, 'Och konungen lät honom sitta vid sin sida, och han sade till sina hövitsmän: »Ledsagen honom in i staden, och låten utropa att ingen får anföra klagomål mot denne i någon sak, och att ingen må falla honom besvärlig i något, vad det vara må.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 64, 'När nu de som ville anföra klagomål mot honom sågo vilken ära som vederfors honom, enligt vad härolden utropade, och när de sågo huru han hade blivit klädd i purpur, då flydde de allasammans därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 65, 'Men konungen lät ytterligare ära honom genom att upptaga honom bland sina främsta vänner och utnämna honom till befälhavare och ståthållare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 66, 'Sedan vände Jonatan tillbaka till Jerusalem med frid och glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 67, 'År 165 kom Demetrius’ son Demetrius från Kreta till sina fäders land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 68, 'När konung Alexander fick höra detta, blev han mycket illa till mods och vände om till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 69, 'Och Demetrius lät Apollonius, ståthållaren i Celesyrien, behålla sitt ämbete, och denne samlade en stor här och lägrade sig i Jamnia. Därifrån sände han bud till översteprästen Jonatan och lät säga: 70 »Du är den ende som uppreser sig mot oss, och jag har blivit till åtlöje och smälek för din skull. Varför förhäver du dig mot oss däruppe bland bergen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 70, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 71, 'Om du litar på ditt krigsfolk, välan, kom då hitned till oss på slätten, och låt oss här mäta oss med varandra; du må veta att jag har städernas krigsmakt på min sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 72, 'Du kan ju fråga och göra dig underrättad om vem jag är, och vilka de andra äro, som bistå oss; man skall då svara att I icke skolen kunna behålla fältet mot oss, ty två gånger hava dina fäder blivit slagna på flykten i sitt eget land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 73, 'Mycket mindre skall du nu kunna hålla stånd mot ryttarna och mot så mycket fotfolk på slätten, där det icke finnes ett enda klippblock eller en enda sten eller alls någon möjlighet till att komma undan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 74, 'När Jonatan hörde denna Apollonius’ hälsning, blev han uppbragt i sitt sinne. Och han utvalde tio tusen man och drog ut ur Jerusalem; och hans broder Simon förenade sig med honom för att bistå honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 75, 'Och han lägrade sig framför Joppe; men invånarna i staden stängde portarna för honom, ty Apollonius hade en besättning där. Då angrep han staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 76, 'Och invånarna blevo förskräckta och öppnade portarna, och så fick Jonatan Joppe i sitt våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 77, 'Men när Apollonius fick höra detta, lät han tre tusen ryttare och en myckenhet fotfolk göra sig redo och drog så fram mot Asotus, som om han ville taga vägen därigenom. Samtidigt ryckte han ock fram på slätten; han hade nämligen ryttare i mängd, och dessa litade han på. Men Jonatan följde efter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 78, 'bakom honom, åt Asotus till, och härarna drabbade samman med varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 79, 'Och Apollonius hade i hemlighet lämnat ett tusen ryttare kvar i deras rygg;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 80, 'men Jonatan fick veta att man låg i bakhåll för honom. De omringade nu hans häravdelning och avsköto sina pilar mot folket, från bittida om morgonen ända till aftonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 81, 'Men folket behöll sin ställning, såsom Jonatan hade befallt, så att fiendernas hästar blevo uttröttade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 82, 'Då ryckte Simon fram med sin skara och inlät sig i strid med det i slagordning uppställda fotfolket (ryttarna voro ju nämligen utmattade), och de blevo i grund slagna av honom och flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 83, 'Också ryttarna sking- rade sig över slätten. Och de flydde till Asotus och begåvo sig in i Bet-Dagon, deras avgudahus, för att rädda sig där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 84, 'Men Jonatan brände upp Asotus och städerna där runt omkring och tog all egendom i dem såsom byte. Jämväl Dagons helgedom, tillika med dem som hade tagit sin tillflykt dit, brände han upp i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 85, 'Och de som föllo för svärd uppgingo, tillsammans med dem som innebrändes, till vid pass åtta tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 86, 'Sedan bröt Jonatan upp därifrån och lägrade sig framför Askalon; och stadens invånare gingo under stor ståt ut för att möta honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 87, 'Därefter vände Jonatan och hans folk tillbaka till Jerusalem med rikt byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 88, 'Då nu konung Alexander fick höra härom, bevisade han Jonatan ännu större ära:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 89, 'han sände honom ett spänne av guld, ett sådant som det är sed att förära konungarnas fränder; han gav honom ock Ackaron med hela dess område till besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 1, 'Men konungen i Egypten samlade en stor här, så talrik som sanden på havets strand, därtill ock skepp i myckenhet. Ty han sökte efter att med list bemäktiga sig Alexanders rike och lägga det till sitt eget rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 2, 'Han drog alltså under fredliga försäkringar in i Syrien, och städernas invånare öppnade portarna för honom och gingo honom till mötes. Det var nämligen konung Alexanders befallning att man så skulle möta honom, då han ju var hans svärfader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 3, 'Men alltefter; som Ptolemeus tågade in i städerna, lade han av sitt krigsfolk in besättningar i var stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 4, 'När han nu kom fram till Asotus, visade man honom huru Dagons helgedom hade blivit uppbränd, och huru Asotus och kringliggande städer hade blivit förstörda, och man visade honom de utkastade döda kropparna och resterna av dem som Jonatan hade bränt upp under striden; man hade nämligen staplat upp högar av dem utefter hans väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 5, 'Och man berättade för konungen vad Jonatan hade gjort, för att därigenom nedsvärta honom. Men konungen svarade intet därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 6, 'Och Jonatan kom konungen till mötes i Joppe med ståt; och de hälsade varandra och stannade där över natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 7, 'Jonatan följde sedan konungen ända till den flod som heter Eleuterus och vände så tillbaka till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 8, 'Men konung Ptolemeus gjorde sig till herre över kuststäderna ända till det Seleucia som ligger vid havet. Och eftersom han umgicks med onda planer mot Alexander,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 9, 'skickade han sändebud till konung Demetrius och lät säga: »Välan! Låt oss ingå förbund med varandra, så vill jag giva dig min dotter till äkta, henne som Alexander nu har till gemål, och du skall bliva konung över din faders rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 10, 'Jag ångrar nämligen att jag har givit honom min dotter, ty han har sökt efter tillfälle att döda mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 11, 'På det sättet nedsvärtade han honom, därför att han hade begär efter hans rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 12, 'Han tog alltså ifrån honom sin dotter och gav henne åt Demetrius och bröt med Alexander, så att fiendskapen mellan dem blev uppenbar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 13, 'Och när Ptolemeus hade dragit in i Antiokia, satte han Asiens krona på sitt huvud och bar således nu två kronor, Egyptens och Asiens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 14, 'Konung Alexander befann sig vid denna tid i Cilicien; det var nämligen så, att invånarna i dessa trakter höllo på att avfalla från honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 15, 'Då nu Alexander fick höra vad som hade hänt, drog han ut till strid mot Ptolemeus. Denne tågade också ut och mötte honom med en stark stridsmakt och slog honom på flykten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 16, 'Alexander flydde då till Arabien för att söka skydd där, och konung Ptolemeus kom så till makten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 17, 'Men araben Sabdiel högg huvudet av Alexander och sände det till Ptolemeus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 18, 'På tredje dagen dog också konung Ptolemeus, och de besättningar som han hade lagt in i sina fästningar nedgjor-des nu av fästningarnas egen befolkning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 19, 'Och så blev Demetrius konung, år 167.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 20, 'Vid den tiden församlade Jonatan sitt folk ifrån Judeen för att strida mot borgen i Jerusalem. Och de ställde upp mot den ett stort antal stormverktyg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 21, 'Då begåvo sig några avfällingar, några som hatade sitt eget folk, till konungen och omtalade för honom att Jonatan höll på att belägra borgen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 22, 'När han fick höra detta, blev han vred; och strax, så snart han hade hört det, bröt han upp och drog till Ptolemais. Därjämte skrev han till Jonatan att han skulle upphäva belägringen och så fort som möjligt möta honom i Ptolemais för att där sammanträffa med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 23, 'När Jonatan fick detta bud, gav han befallning om att fortsätta belägringen. Men han utvalde ock några bland de äldste i Israel och bland prästerna till att vara sändebud; han gav sig också själv in i det farliga företaget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 24, 'Han tog med sig silver och guld och kläder och en myckenhet andra skänker och begav sig så till konungen i Ptolemais. Och han fann nåd för hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 25, 'Nu kommo några avfällingar bland hans landsmän och anförde klagomål mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 26, 'Men då handlade konungen mot honom på samma sätt som hans företrädare hade gjort och upphöjde honom inför alla sina vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 27, 'Och han tillförsäkrade honom översteprästämbetet och alla andra värdigheter som han förut innehade och lät räkna honom bland sina främsta vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 28, 'Jonatan bad nu konungen att han ville medgiva skattefrihet för Judeen och de tre områdena i Samarien, och lovade honom i stället tre hundra talenter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 29, 'Konungen gick in härpå och utfärdade angående allt detta en skrivelse till Jonatan av följande lydelse:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 30, '»Konung Demetrius hälsar sin broder Jonatan och det judiska folket. En avskrift av det brevst som vi hava skrivit till vår frände Lastenes angående eder sända vi härmed till eder, för att I skolen få del därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 31, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 32, '’Konung Demetrius hälsar sin fader Lastenes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 33, 'Det judiska folket, våra vänner och trogna bundsförvanter, hava vi, på grund av deras tillgivenhet mot oss, beslutit tilldela följande förmanér.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 34, 'Vi tillförsäkra dem såväl Judeens landområde som de tre områdena Aferema, Lydda och Ramataim, vilka hava lagts till Judeen från Samarien, så ock alla dem underlydande orter. Åt alla dem som offra i Jerusalem efterskänka vi vad de skola lämna i ersättning för den konungen tillkommande andel, som konungen förut årligen har mottagit från dem av jordens gröda och trädens frukter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 35, 'likaså det övriga som från denna dag tillkommer oss av tiondegärderna och av andra avgifter som tillkomma oss, så ock avgifterna för saltdammarna, såväl som den oss tillkommande kransskatten; allt detta efterskänka vi dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 36, 'Och intet härav skall upphävas från denna dag till evärdlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 37, 'Ombesörjen nu alltså att en avskrift tages härav, och att denna överlämnas åt Jonatan till att uppsättas på det heliga berget, på en bemärkt plats som är lämplig härför\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 38, 'När konung Demetrius nu såg att lugn och ro rådde i hans land, och att han icke vidare mötte något motstånd, lät han allt sitt krigsfolk åtskiljas och begiva sig var och en till sin hemort, med undantag av det främmande krigsfolk som han hade lejt från hedningarnas öar. Då blev allt krigsfolket från hans fäders tid hätskt mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 39, 'Tryfon var en bland Alexanders forna anhängare. Då han nu såg att allt krigsfolket knorrade mot Demetrius, begav han sig till araben Imalkue, som var uppfostrare för Alexanders späde son Antiokus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 40, 'Och han låg över honom med böner att han skulle överlämna gossen åt honom, för att denne skulle bliva konung efter sin fader. Och han omtalade för honom allt vad Demetrius hade gjort, och huru hätskt hans krigsfolk var sinnat mot honom. Och han stannade där i lång tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 41, 'Och Jonatan sände bud till konung Demetrius och begärde att han skulle låta besättningarna på borgen i Jerusalem och i de övriga fästningarna avtåga; ty de lågo i strid med Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 42, 'Demetrius sände då bud till Jonatan med det svaret: »Icke allenast detta vill jag göra dig och ditt folk, utan jag vill också, när jag får lägligt tillfälle därtill, högt ära dig och ditt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 43, 'Och du gör nu rätt och väl, om du sänder manskap till min hjälp i striden, ty allt mitt krigsfolk har avfallit från mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 44, 'Så sände då Jonatan tre tusen tappra stridsmän till honom i Antiokia; och när dessa kommo till konungen, gladde han sig över deras ankomst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 45, 'Men stadens invånare församlade sig mitt i staden, till ett antal av vid pass ett hundra tjugu tusen människor, och ville bringa konungen om livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 46, 'Konungen flydde då in i sitt palats, men invånarna i staden besatte stadens gator och begynte att strida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 47, 'Då kallade konungen judarna till hjälp, och de församlade sig allasammans hos honom. Därvid skingrade folket sig i staden. Och judarna dräpte på den dagen vid pass ett hundra tusen människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 48, 'Och de satte eld på staden och togo den dagen rikt byte; och de räddade så konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 49, 'Men när invånarna i staden sågo att judarna hade bemäktigat sig staden, efter sin önskan, förlorade de modet och ropade bönfallande till konungen och sade: 50 »Ingå förlikning med oss, och bjud judarna upphöra med att strida mot oss och staden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 50, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 51, 'Och de kastade ifrån sig sina vapen och slöto fred. Och judarna kommo i högt anseende hos konungen och hos alla i hans rike, och de vände så tillbaka till Jerusalem med rikt byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 52, 'Men när konung Demetrius nu åter hade satt sig på sitt rikes tron och lugn och ro rådde i hans land,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 53, 'då svek han alla sina löften och bröt med Jonatan och vedergällde icke de tjänster som denne hade bevisat honom, utan ansatte honom hårt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 54, 'Härefter kom Tryfon tillbaka i sällskap med Antiokus, som ännu var en helt ung gosse. Denne uppträdde nu såsom konung och satte kronan på sitt huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 55, 'Och hos honom församlade sig allt det krigsfolk som Demetrius skymfligt hade sänt bort; och de begynte att strida mot denne, och han flydde och blev slagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 56, 'Och Tryfon satte sig i besittning av elefanterna och bemäktigade sig Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 57, 'Och den unge Antiokus skrev till Jonatan sålunda: »Härmed tillförsäkrar jag dig översteprästämbetet och sätter dig över de fyra områdena och förklarar dig för en av konungens vänner.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 58, 'Tillika sände han honom bordskärl av guld och gav honom rättighet att dricka ur guldkärl och vara klädd i purpur och bära ett spänne av guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 59, 'Och hans broder Simon satte han till befälhavare inom området från Tyriska trappan till Egyptens gräns.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 60, 'Jonatan drog nu ut och tågade genom landet och städerna på andra sidan floden; och allt krigsfolket i Syrien församlades hos honom till att hjälpa honom i striden. Sedan begav han sig till Askalon, och där gingo stadens invånare ut för att möta honom med all heder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 61, 'Därifrån drog han till Gasa, men invånarna i Gasa stängde portarna för honom. Då begynte han att belägra staden och brände upp de kringliggande städerna i eld och plundrade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 62, 'Invånarna i Gasa bådo nu Jonatan om fred, och han ingick förlikning med dem; och han tog sönerna till deras förnämsta män såsom gisslan och sände dem till Jerusalem. Sedan drog han vidare genom landet, ända till Damaskus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 63, 'Nu fick Jonatan höra att Demetrius’ hövitsmän med en stor här hade kommit till Kedes i Galileen, i avsikt att hindra honom från hans förehavande.’ Han drog då ut mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 64, 'Men sin broder Simon hade han lämnat kvar i hemlandet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 65, 'Och Simon lägrade sig vid Betsura och stridde mot det i lång tid och höll det inneslutet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 66, 'Besättningen begärde då att få ingå förlikning, och han beviljade deras bön och lät dem avtåga. Därefter tog han staden i besittning och lade in en besättning där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 67, 'Jonatan och hans här hade emellertid lägrat sig vid Gennesarets sjö, och de bröto nuu bittida om morgonen upp till Hasors slätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 68, 'Då kom en här, bestående av utländskt krigsfolk, emot honom där på slätten. Och de hade bland bergen ställt ut folk i bakhåll för honom, men själva tågade de rakt emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 69, 'När nu de som lågo i bakhåll bröto upp från sin plats och gåvo sig i strid, togo alla Jonatans män till flykten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 70, 'icke en enda av dem stannade kvar, förutom Mattatias, Absaloms son, och Judas, Kalfis son, som voro hövitsmän över krigshären.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 71, 'Då rev Jonatan sönder sina kläder och strödde stoft på sitt huvud och bad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 72, 'Därefter vände han sig mot fienderna och stridde med dem och slog dem på flykten; och de flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 73, 'Och när de av hans folk, som förut hade flytt, sågo detta, vände de om till honom och förföljde tillsammans med honom fienderna ända till Kedes, där de hade sitt läger; och de lägrade sig också själva där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 74, 'Av det utländska krigsfolket föllo på den dagen vid pass tre tusen man. Därefter vände Jonatan tillbaka till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 1, 'Eftersom Jonatan nu insåg att tillfället var honom lägligt, utvalde han några män och sände dem till Rom, för att bekräfta och förnya vänskapen med romarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 2, 'Också till Sparta och till andra ställen sände han brev med samma innehåll.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 3, 'De begåvo sig alltså åstad till Rom När de nu hade kommit inför rådsförsamlingen, sade de: »Översteprästen Jonatan och det judiska folket hava sänt oss hit, för att få vänskapen och förbundet med dem förnyade på samma villkor som förut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 4, 'Och romarna gåvo dem brev till de styrande på vart ställe, med befallning att dessa skulle sörja för att de välbehållna kunde fortsätta sin resa till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 5, 'Och så lyder avskriften av det brev som Jonatan skrev till spartanerna:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 6, '»Översteprästen Jonatan och folkets Stora råd och prästerna och det övriga judiska folket hälsa sina bröder spartanerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 7, 'Redan tidigare har ett brev, varav en avskrift här bifogas, blivit sänt till översteprästen Onias från eder konung Areus därom att I ären våra bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 8, 'Och Onias bemötte edert sändebud med all heder och tog emot brevet, vari uttryckligen talades om förbund och vänskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 9, 'Vi äro nu visserligen icke i behov härav, eftersom de heliga böcker som vi hava i våra händer utgöra vår tröst;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 10, 'men vi hava likväl tagit oss före att skicka sändebud till eder, för att få broderskapet och vänskapen med eder förnyade, på det att vi icke måtte bliva främlingar för eder. Ty lång tid är förfluten, sedan I skickaden sändebud till oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 11, 'Vad oss angår, så komma vi alltid och oavlåtligt ihåg eder vid högtiderna och på övriga tillbörliga dagar, vid de offer som vi frambära och i våra böner, såsom rätt och tillbörligt är att man minnes bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 12, 'Och vi glädja oss åt eder ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 13, 'Men vi för vår del hava varit omvärvda av mycket betryck och av många strider, och konungarna runt omkring oss hava stritt mot oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 14, 'Vi hava nu icke velat falla eder och våra övriga bundsförvanter och vänner besvärliga med dessa strider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 15, 'Ty vi hava vår hjälp från himmelen, som hjälper oss. Och så hava vi blivit frälsta ifrån våra fiender, medan våra fiender hava blivit förödmjukade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 16, 'Nu hava vi emellertid utvalt Numenius, Antiokus’ son, och Antipater, Jasons son, och sänt dem till romarna, för att låta förnya den vänskap och det förbund som vi tidigare hava ingått med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 17, 'Vi hava därvid bjudit dem att fara också till eder och hälsa eder och avlämna till eder vårt brev angående förnyelsen av broderskapet oss emellan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 18, 'Och nu skulle det vara oss till behag, om I villen giva oss svar härpå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 19, 'Och så lyder avskriften av det brev som spartanerna sände till Onias:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 20, '»Areus, spartanernas konung, hälsar översteprästen Onias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 21, 'I en skrift har angående spartanerna och judarna den uppgiften blivit påträffad, att de äro bröder och av Abrahams släkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 22, 'Och sedan vi nu hava fått veta detta, skulle det vara oss till behag, om I villen skriva till oss och säga oni det står väl till med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 23, 'Vi å vår sida skriva nu här till eder: Vår boskap och våra ägodelar tillhöra eder, likasom vad edert är tillhör oss. Vi bjuda alltså våra sändebud att lämna eder muntligt besked i överensstämmelse härmed.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 24, 'Och Jonatan fick höra att Demetrius\' hövitsmän hade kommit igen med en ännu större här än förra gången, för att strida mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 25, 'Då bröt han upp från Jerusalem och drog dem till mötes in på Hamats område. Ty han ville icke giva dem rådrum till att infalla i hans eget land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 26, 'Och han sände ut spejare till deras läger; och dessa kommo tillbaka och omtalade för honom att de beredde sig till att överfalla dem om natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 27, 'När sedan solen gick ned, befallde Jonatan sitt folk att vaka och stå under vapen för att vara redo till strid under hela natten; han ställde ock ut vaktposter runt omkring lägret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 28, 'Men när fienderna hörde att Jonatan och hans folk voro redo till strid, blevo de förskräckta och förlorade modet. Och sedan de hade tänt upp eldar i sitt läger, drogo de bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 29, 'Men Jonatan och hans folk märkte ingenting förrän på morgonen, eftersom de sågo eldarna brinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 30, 'Jonatan satte nu efter dem, men han kunde icke hinna upp dem; ty de hade redan övergått floden Eleuterus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 31, 'Då vände sig Jonatan mot de araber som kallas sabadéer och slog dem och tog deras egendom såsom byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 32, 'Därefter bröt han upp och drog till Damaskus och tågade igenom hela landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 33, 'Simon drog också ut och tågade igenom landet ända till Askalon och till fästningarna där i närheten. Sedan vände han sig mot Joppe och intog staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 34, 'Han hade nämligen hört att man ville överlämna fästningen till Demetrius’ folk. Därför lade han nu in en besättning där, till stadens försvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 35, 'Sedan Jonatan hade kommit tillbaka, sammankallade han folkets äldste och beslöt, i samråd med dem, att bygga fästningar i Judeen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 36, 'och att göra Jerusalems murar högre och att uppföra en hög mur mellan borgen och staden, för att avspärra borgen från staden, så att den komme att ligga avskild; på det sättet skulle dess besättning varken kunna köpa eller sälja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 37, 'De församlade sig alltså för att bygga. Ett stycke av muren österut vid bäcken hade störtat in; de satte ock det så kallade Kafenata i stånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 38, 'Och Simon befäste Adida i Låglandet och försåg det med fasta portar och bommar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 39, 'Men Tryfon stod efter att bliva konung i Asien och att sätta kronan på sitt huvud och att bära hand på konung Antiokus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 40, 'Han befarade dock att Jonatan icke skulle lämna honom fria händer, utan giva sig i strid med honom; och han sökte därför efter ett lägligt tillfälle att gripa honom för att döda honom. Han bröt alltså upp och begav sig till Betsan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 41, 'Och Jonatan drog ut för att möta honom med fyrtio tusen utvalda stridsmän och kom också till Betsan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 42, 'När Tryfon såg att han hade kommit dit med en så stor här, vågade han icke bära hand på honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 43, 'han tog i stället emot honom med all heder och anbefallde honom hos alla sina vänner och gav honom skänker och bjöd sina vänner och sitt krigsfolk att visa honom samma lydnad som honom själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 44, 'Därefter sade han till Jonatan: »Varför har du besvärat allt detta folk med att tåga hit, fastän icke något krig råder mellan oss?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 45, 'Låt dem nu draga till sina hemorter, men välj ut åt dig några få män till att ledsaga dig. Kom sedan med mig till Ptolemais, så vill jag överlämna staden åt dig, såsom ock de övriga fästningarna och det övriga krigsfolket och alla ämbetsmännen. Därefter vill jag vända om och draga bort. Ty fördenskull har jag kommit hit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 46, 'Och Jonatan satte tro till honom och gjorde såsom han hade föreslagit; han lät hären draga sin väg, och den avtågade till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 47, 'Hos sig behöll han kvar allenast tre tusen man; och av dem lämnade han två tusen i Galileen, medan ett tusen följde honom åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 48, 'Men när Jonatan hade kommit in i Ptolemais, stängde invånarna i Ptolemais portarna och togo honom till fånga; och alla som hade följt honom ditin dräpte de med svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 49, 'Därefter sände Tryfon fotfolk och ryttare till Galileen och till den stora slätten för att nedgöra allt Jonatans folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 50, 'Men när dessa fingo höra sägas att han skulle vara tillfångatagen och dödad tillika med sina män, uppmuntrade de varandra och tågade fram i tätt slutna led, redo till strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 51, 'Då nu förföljarna sågo att dessa ämnade kämpa på liv och död, vände de om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 52, 'Så kommo alla välbehållna till Judeen. Och de sörjde Jonatan och hans män och kände stor fruktan; ja, hela Israel sörjde dem djupt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 53, 'Men alla hedningar där runt omkring sökte efter att utrota dem. Ty de sade: »De hava icke mer någon som anför och hjälper dem. Låt oss därför nu strida med dem och utplåna deras åminnelse bland människor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 1, 'När Simon fick höra att Tryfon hade samlat en stor här för att tåga in i Judeen och ödelägga det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 2, 'och när han såg att folket var uppfyllt av bävan och förskräckelse, drog han upp till Jerusalem och församlade] folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 3, 'Och han talade uppmuntrande ord till dem och sade till dem: »I veten själva allt vad vi allasammans, jag och mina bröder och min faders hus, hava gjort för lagen och helgedomen, så ock vilka strider och trångmål vi hava utstått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 4, 'Därför hava ock alla mina bröder omkommit för Israels skull, så att jag är den ende som är kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 5, 'Men bort det, att jags någonsin i nödens stund skulle skona mitt liv! Jag är ju icke förmer än mina bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 6, 'Nej, jag vill tvärtom bliva en hämnare för mitt folk och för helgedomen och för våra kvinnor och barn, eftersom alla hedningar i sitt hat hava församlat sig för att utrota oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 7, 'Då flammade folkets mod åter upp, så snart de hörde dessa ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 8, 'och de svarade med hög röst och sade: »Du skall vara vår anförare i Judas’ och Jonatans, din broders, ställe;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 9, 'du skall föra vår strid, och allt vad du bjuder oss, det vilja vi göra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 10, 'Han samlade nu alla stridbara män och lät med all hast bygga Jerusalems murar färdiga och befäste staden runt omkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 11, 'Och han sände Jonatan, Absaloms son, med en ansenlig häravdelning till Joppe; denne tvingade invånarna att draga ut ur staden och stannade själv kvar där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 12, 'Men Tryfon bröt med en stor här upp från Ptolemais för att tåga in i Judeen, och han förde därvid Jonatan med sig såsom fånge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 13, 'Men Simon lägrade sig i Adida, mitt för slättlandet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 14, 'När Tryfon fick veta att Simon hade trätt i sin broder Jonatans ställe, och att han ämnade giva sig i strid med honom, skickade han sändebud till honom och lät säga: 15 »Det är för de penningars skull vilka din broder Jonatan är skyldig den kungliga skattkammaren för de ämbeten han har innehaft, som vi hålla honom fången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 15, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 16, 'Men sänd nu ett hundra talenter silver, och två av hans söner såsom gisslan, för att han icke, när han har blivit frigiven, må avfalla från oss; då vilja vi giva honom fri.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 17, 'Simon förstod visserligen att det låg svek i deras ord till honom; men han sände likväl efter penningarna och gossarna för att icke ådraga sig stor ovilja hos folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 18, 'De kunde ju eljest hava sagt att Jonatan hade mist livet, därför att brodern icke hade sänt penningarna och gossarna till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 19, 'Han sände alltså gossarna åstad, så ock de ett hundra talenterna. Men Tryfon svek sitt ord och gav icke Jonatan fri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 20, 'Sedan kom han tågande för att infalla i landet och ödelägga det. Och han tog en omväg över Adora. Men Simon och hans här tågade jämsides med honom till var plats, vart han än drog.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 21, 'Och besättningen på borgen sände gång på gång budbärare till Tryfon, vilka skulle bedja honom att skyndsamt komma till dem genom öknen och sända dem livsmedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 22, 'Då lät Tryfon alla sina ryttare göra sig redo för att avgå dit. Men i den natten föll det så mycket snö att han icke kunde komma fram för snöns skull. Då bröt han upp och drog till Galaaditis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 23, 'När han nu närmade sig Baskama, lät han avliva Jonatan; och denne blev begraven där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 24, 'Men Tryfon vände om och drog hem till sitt land igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 25, 'Då sände Simon åstad och lät hämta sin broder Jonatans ben; och han begrov honom i Modein, hans fäders stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 26, 'Och hela Israel höll stor dödsklagan efter honom och sörjde honom i många dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 27, 'Och Simon lät på sin faders och sina bröders grav uppföra en hög och vitt omkring synlig byggnad, med huggen sten på framsidan och baksidan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 28, 'På denna lät han uppställa sju pyramider, den ena mitt emot den andra, för sin fader och sin moder och sina fyra bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 29, 'Och för dessa pyramider lät han förfärdiga konstnärliga prydnader, och lät däromkring uppresa stora pelare och på pelarna framställa vapenrustningar till evärdlig åminnelse och bredvid rustningarna inhuggna skepp, så att det hela skulle vara synligt för alla som seglade på havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 30, 'Sådan var den gravvård som han lät uppföra i Modein, och den finnes kvar där ännu i dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 31, 'Men Tryfon handlade svekfullt mot den unge konung Antiokus och lät avliva honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 32, 'Och han uppträdde såsom konung i hans ställe och satte Asiens krona på sitt huvud och for mycket våldsamt fram i landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 33, 'Simon förstärkte nu fästningarna i Judeen och skyddade dem runt omkring med höga torn och starka murar och med portar och bommar; och han lade upp livsmedel i fästningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 34, 'Därefter utvalde Simon några män, som han sände till konung Demetrius för att utverka eftergifter åt landet, eftersom Tryfon icke gjorde annat än plundrade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 35, 'Och konung Demetrius svarade honom härpå i ett brev, som han sände honom. Det brev som han så skrev till honom lydde på följande sätt:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 36, '»Konung Demetrius hälsar översteprästen och konungarnas vän Simon, så ock de äldste och det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 37, 'Den krans av guld och den palmkvist som I haven sänt oss hava vi mottagit. Och vi äro redo att ingå en slutgiltig fred med eder och att skriva till ämbetsmännen att de skola bevilja eder eftergifter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 38, 'Allt vad vi hava fastställt med avseende på eder står fast, och de fästningar som I haven byggt må tillhöra eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 39, 'Vi tillgiva eder ock de förseelser och felsteg som I haven begått intill denna dag, och vi efterskänka jämväl den kransskatt som I hittills haven varit skyldiga att betala; ej heller må övriga avgifter som hava plägat utkrävas i Jerusalem vidare utkrävas där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 40, 'Och de av eder, som kunna vara lämpliga till att upptagas i vår livvakt, må upptagas däri. Och må nu fred råda mellan oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 41, 'År 170 blev så hedningarnas ok avlyft från Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 42, 'Och Israels folk begynte nu att i urkunder och rättshandlingar skriva: »I Simons, judarnas store översteprästs, befälhavares och furstes, första år.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 43, 'Vid den tiden lägrade sig Simon framför Gasara och inneslöt staden med krigsfolk. Och han lät förfärdiga en stormmaskin och förde fram den mot staden; han lyckades så att göra en öppning i ett torn och intog det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 44, 'Då nu de som voro inne i stormmaskinen rusade in i staden, uppstod en stor förvirring där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 45, 'Och stadens invånare stego i sönderrivna kläder upp på murarna, tillika med kvinnor och barn, och ropade med hög röst och bådo att Simon skulle ingå förlikning med dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 46, 'och sade: »Handla icke med oss efter våra onda gärningar, utan efter din barmhärtighet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 47, 'Simon gick då in på en förlikning med dem och upphörde att strida mot dem. Men han tvingade dem att draga ut ur staden och lät rena de hus i vilka avgudabilderna funnos, och så gjorde han sitt intåg i den under psalmer och lovsånger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 48, 'Han förde därefter allt orent bort ur staden och lät män som höllo lagen bosätta sig där; och han befäste den ytterligare och byggde där ett hus åt sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 49, 'Men eftersom besättningen på borgen i Jerusalem var avskuren från landsbygden, så att de varken kunde gå ut eller gå in, och varken kunde köpa eller sälja, uppstod en svår hungersnöd bland dem; och ganska många av dem omkommo av svält.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 50, 'Då ropade de till Simon att han skulle ingå förlikning med dem. Och han gick in härpå och lät dem draga ut från platsen och renade borgen från all besmittelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 51, 'Och han gjorde sitt intåg i borgen på tjugutredje dagen i andra månaden av år 171, under lovprisning och med palmkvistar och under ljudet av harpor, cymbaler och psaltare och av psalmer och sånger, därför att en så farlig fiende hade blivit fördriven ur Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 52, 'Och han bestämde att de årligen skulle fira denna dag under glädje. Därefter befäste han ytterligare tempelberget invid borgen; och där bodde han själv med de sina.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 53, 'Men när Simon såg att hans son Johannes var en dugande man, satte han honom till anförare för hela hären. Och Johannes bodde i Gasara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 1, 'År 172 samlade konung Demetrius sin här och tågade till Medien, i avsikt att där skaffa sig krigsfolk som skulle hjälpa honom i hans strid mot Tryfon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 2, 'Då nu Arsaces, konungen i Persien och Medien, fick höra att Demetrius hade trängt in på hans område, sände han ut en av sina hövitsmän för att söka få honom levande i sitt våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 3, 'Denne drog då åstad och slog Demetrius’ här och tog honom själv till fånga och förde honom till Arsaces. Och han satte honom i fängsligt förvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 4, 'Judeen hade nu ro, så länge Simon levde. Han sökte sitt folks bästa, och hans makt och hans ära behagade dem väl under hela hans livstid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 5, 'Till alla hans andra ärorika gärningar kom ock att han vann Joppe till hamnstad och därmed skaffade en infartsort för öarna i havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 6, 'Han utvidgade gränserna åt sitt folk och höll landet under sitt välde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 7, 'Han förde många tillbaka hem ur deras fångenskap och blev herre över Gasara och Betsura och borgen. Han skaffade bort allt orent ur denna; och ingen fanns, som kunde stå honom emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 8, 'Man odlade sin jord i trygghet, och jorden gav sin gröda, och träden på marken buro sin frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 9, 'Gamla män sutto på gatorna, alla samtalade de om allmänt väl, och de unga iförde sig krigarskrudens ståt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 10, 'Han försåg städerna med födoämnen och utrustade dem med försvarsmedel; ja, ryktet om hans ära nådde till jordens ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 11, 'Han skaffade fred åt landet, och Israel fröjdade sig storligen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 12, 'envar satt under sitt vinträd och sitt fikonträd, och ingen fanns, som förskräckte dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 13, 'Ingen stridde vidare mot dem i landet, och konungarna blevo i grund slagna på den tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 14, 'Han styrkte alla betryckta bland sitt folk, han var en ivrare för lagen och tillintetgjorde alla avfällingar och ogärningsmän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 15, 'Han smyckade helgedomen härligt och ökade antalet av helgedomens kärl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 16, 'När det blev känt i Rom att Jonatan var död, och likaså i Sparta, blevo de uppfyllda av stor bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 17, 'Men när de fingo höra att hans broder Simon hade blivit överstepräst efter honom och nu rådde över landet och dess städer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 18, 'skrevo de till honom på koppartavlor, för att med honom förnya den vänskap och det förbund som de hade ingått med hans bröder Judas och Jonatan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 19, 'Och denna skrivelse lästes upp inför menigheten i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 20, 'Så lyder avskriften av det brev som spartanerna sände: »Spartanernas styresmän och stad hälsa översteprästen Simon och de äldste och prästerna och det övriga judiska folket, sina bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 21, 'De sändebud som I haven skickat till vårt folk hava förtäljt för oss om eder ära och berömmelse, och vi hava glatt oss över deras ankomst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 22, 'Och vi hava, angående det som de anförde, bland folkbesluten upptecknat följande:’Numenius, Antiokus’ son, och Antipater, Jasons son, judarnas sändebud, hava kommit till oss för att förnya vänskapen med oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 23, 'Och folket har funnit för gott att taga emot dessa män med all heder och att införa en uppteckning av deras framställning bland de offentliga statshandlingarna, för att det spartanska folket skall bevara detta i minnet.\' Och en avskrift härav sända vi härmed till översteprästen Simon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 24, 'Därefter sände Simon åstad Numenius till Rom med en stor sköld av guld, som vägde ett tusen minor, för att bekräfta förbundet med romarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 25, 'När folket fick höra om allt detta, sade de: »Varmed skola vi bevisa Simon och hans söner vår tacksamhet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 26, 'Han har ju stått fast, såsom ock hans bröder och hela hans faders hus, och de hava stritt mot Israels fiender och fördrivit dem; och de hava befäst dess frihet.» Så läto de då inrista en inskrift på koppartavlor, som de satte upp på pelare på Sions berg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 27, 'Och detta är vad som stod i denna inskrift: »På adertonde dagen i månaden Elul av år 172, som är det tredje året under den store översteprästen Simon, Saramel,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 28, 'har vid en stor församling av prästerna och folket och folkets hövitsmän och landets äldste följande blivit kungjort för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 29, 'Eftersom landet så ofta har varit utsatt för krig, hava Simon, Mattatias\' son, en ättling av Joaribs söner, och hans bröder givit sig själva i faran och satt sig till motvärn mot sitt folks fiender, för att deras helgedom och lagen skulle äga bestånd, och de hava förvärvat stor ära åt sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 30, 'När nu Jonatan, sedan han hade slutit deras folk tillsammans och blivit deras överstepräst, hade samlats till sina fäder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 31, 'ville deras fiender infalla i deras land för att ödelägga det och för att räcka ut sina händer mot deras helgedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 32, 'Då stod Simon upp och stridde för sitt folk och gav ut mycket penningar av egna medel och försåg sitt folks stridsmän med vapen och gav dem sold.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 33, 'Och han befäste städerna i Judeen, så ock Betsura vid Judeens gräns, varest fienderna förut hade haft sina förråd av vapen, och lade där in judar såsom be- sättning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 34, 'Han befäste ock Joppe vid havet och Gasara vid Asotus\' gräns, varest fienderna förut hade bott, och lät judar bosätta sig där. Och allt som var behövligt för deras underhåll lade han in i dessa städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 35, 'När folket nu besinnade Simons trofasthet och tänkte på vilken ära han hade föresatt sig att förvärva åt sitt folk, satte de honom till sin furste och överstepräst, därför att han hade utfört allt detta, och därför att han ständigt hade bevisat en så stor rättrådighet och trofasthet mot sina landsmän, och eftersom han hade strävat efter att på allt sätt upphöja sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 36, 'Och i hans tid lyckades det att under hans ledning utdriva hedningarna ur landet, och särskilt dem som bodde i Davids stad, i Jerusalem, vilka där hade gjort sig en borg, varifrån de plägade göra strövtåg, så att de besmittade platsen omkring helgedomen och svårt kränkte dess helighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 37, 'Och han lät judar bosätta sig i den och befäste den ytterligare, för att så bereda landet och staden trygghet, och han gjorde Jerusalems murar högre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 38, 'På grund härav stadfäste konung Demetrius honom i hans översteprästämbete;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 39, 'och han upptog honom bland sina vänner och bevisade honom stor ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 40, 'Ty han hade hört sägas att romarna hade förklarat judarna för vänner, bundsförvanter och bröder, och att de hade bemött Simons sändebud med all heder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 41, 'Och nu hava judarna och deras präster funnit följande för gott. Simon skall vara deras furste och överstepräst för evärdlig tid, till dess en tillförlitlig profet uppstår,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 42, 'och han skall vara deras befälhavare och skall efter eget gottfinnande få insätta uppsyningsrnan över deras arbeten och över landet och över vapnen och över fästningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 43, 'Vidare skall han hava vård om helgedomen, och han skall bliva åtlydd av alla; och alla skriftliga urkunder i landet skola utfärdas i hans namn, och han skall få kläda sig i purpur och bära guldprydnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 44, 'Och det skall icke vara någon av folket eller prästerna tillstått att upphäva något härav eller göra invändningar mot hans påbud eller sammankalla en församling i landet, utan hans medgivande, eller kläda sig i purpur eller pryda sig med spänne av guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 45, 'Men om någon handlar i strid häremot eller upphäver något härav, så skall han vara hemfallen åt straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 46, 'Och folket har enhälligt funnit för gott att rörande Simon fastställa att man skall förfara efter dessa bestämmelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 47, 'Simon har ock antagit detta och funnit för gott att vara överstepräst och befälhavare och landsfurste för judarna och deras präster och att hava ledningen av allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 48, 'Och de hava bestämt att denna skrift skall inristas på koppartavlor, och att dessa skola sättas upp inom helgedomens inhägnade område på en bemärkt plats,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 49, 'så ock att en avskrift av dem skall läggas i förvar i skattkammaren för Simons och hans söners räkning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 1, 'Antiokus, konung Demetrius\' son, sände från öarna i havet ett brev till Simon, judarnas överstepräst och landsfurste, och till hela folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 2, 'Det var av följande lydelse: »Konung Antiokus hälsar översteprästen och landsfursten Simon, så ock det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 3, 'Alldenstund några skändliga män hava bemäktigat sig våra fäders rike, men jag har i sinnet att åter tillvinna mig riket för att återställa det i dess förra skick - jag har ock fördenskull lejt en myckenhet främmande krigsfolk och utrustat krigsskepp');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 4, 'och har i sinnet att landstiga och tåga igenom landet, för att straffa dem som hava förhärjat vårt land och ödelagt många städer i riket —');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 5, 'därför giver jag dig nu min stadfästelse på att du skall vara fri ifrån alla de pålagor som de som hava varit konungar före mig hava efterskänkt dig, och ifrån alla övriga avgifter som de hava efterskänkt dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 6, 'Och jag giver dig härmed tillstånd att slå eget mynt för ditt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 7, 'Jerusalem och helgedomen må vara fria; och alla de vapen som du har anskaffat och de fästningar som du har byggt och nu innehar må förbliva din tillhörighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 8, 'Och allt vad du nu är skyldig konungen och vad du framdeles kan komma att bliva honom skyldig, det må från denna dag och för all framtid bliva dig efterskänkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 9, 'Och när vi åter hava upprättat vårt rike, vilja vi bevisa dig och ditt folk och helgedomen stor ära, så att eder ära bliver kunnig på hela jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 10, 'År 174 landsteg Antiokus i sina fäders land, och allt krigsfolket gick då över till honom, så att allenast några få stannade kvar hos Tryfon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 11, 'Och konung Antiokus förföljde honom, och han flydde undan och kom till Dora vid havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 12, 'Ty han märkte att olyckorna hade hopat sig över honom, och att krigsfolket hade övergivit honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 13, 'Antiokus lägrade sig nu framför Dora med ett hundra tjugu tusen man fotfolk och åtta tusen ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 14, 'Och han inneslöt staden, och skeppen ingrepo från sjösidan, och han ansatte så staden både till lands och vatten och lät icke någon slippa ut eller in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 15, 'Under tiden kommo Numenius och hans följeslagare tillbaka från Rom och förde till konungarna och länderna med sig brev, i vilka följande stod skrivet:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 16, '»Lucius, konsul i Rom, hälsar konung Ptolemeus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 17, 'Judarnas sändebud hava såsom våra vänner och bundsförvanter kommit hit till oss, för att förnya den vänskap och det förbund som av gammalt har rått med oss, härtill utsända av översteprästen Simon och det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 18, 'Och de förde med sig en sköld av guld om ett tusen minor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 19, 'Så hava vi nu funnit för gott att skriva till konungarna och länderna att de icke skola söka bereda dem ofärd, eller anfalla dem och deras städer och deras land med krig, eller ingå förbund med deras fiender.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 20, 'Och vi hava beslutit att taga emot skölden av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 21, 'Om alltså några skändliga män hava flytt ifrån deras land till eder, så skolen I utlämna dem till översteprästen Simon, för att han må straffa dem efter deras lag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 22, 'Detsamma skrev han ock till konung Demetrius och till Attalus och Ariarates och Arsaces');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 23, 'och till alla länder, till Sampsame och Sparta och till Delos, Myndus, Sicyon, Karien, Samos, Pamfylien, Lycien, Halikarnas-sus, Rodus, Faselis, Kos, Side, Aradus, Gortyna, Knidus, Cypern och Cyrene.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 24, 'Och en avskrift härav sände han till översteprästen Simon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 25, 'Dagen efter sin ankomst begynte konung Antiokus belägringen av Dora och förde därvid oavlåtligt fram sina skaror mot staden och lät förfärdiga stormverktyg. Och han inneslöt Tryfon, så att ingen kunde slippa ut eller in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 26, 'Simon sände honom nu två tusen man utvalt folk till att hjälpa honom i striden, så ock silver och guld och förnödenheter i ganska riklig mängd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 27, 'Men konungen ville icke taga emot något därav, utan återkallade allt som han förut hade lovat honom och bröt med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 28, 'Och han sände till honom Atenobius, en av sina vänner, för att underhandla med honom, och lät säga: »I haven i edert våld Joppe, Gasara och borgen i Jerusalem, städer som tillhöra mitt rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 29, 'Deras områden haven I ödelagt och haven farit mycket våldsamt fram i landet; I haven ock gjort eder till herrar över många andra platser i mitt rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 30, 'Så lämnen nu tillbaka de städer som I haven intagit, och betalen skatterna från de platser som I haven gjort eder till herrar över utanför Judeens gränser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 31, 'Varom icke, så given mig i stället fem hundra talenter silver, och såsom ersättning för den skada som I haven anställt, så ock för skatterna från städerna, ytterligare fem hundra talenter. I annat fall skola vi komma och strida mot eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 32, 'Konungens vän Atenobius kom alltså till Jerusalem; och när han fick se Simons härlighet och bordet med guld- och silverkärl och hans talrika uppvaktning, blev han häpen. Han framförde nu till honom konungens budskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 33, 'Då svarade Simon honom och sade: »Vi hava varken tagit andras land eller tillägnat oss andras egendom, utan allenast våra fäders arvedel, som våra fiender vid lägligt tillfälle mot all rätt hava bemäktigat sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 34, 'Men eftersom tillfället nu är gynnsamt för oss, hålla vi fast vid våra fäders arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 35, 'Vad angår Joppe och Gasara, som du fordrar igen, så hava dessa tillfogat vårt folk och vårt land stor skada. För dem vilja vi likväl giva ett hundra talenter.» Men Atenobius svarade honom icke ett ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 36, 'utan vände i vrede tillbaka till konungen och förtäljde för honom om Simons svar och om hans härlighet och om allt vad han hade sett. Då upptändes konungen av mycket stor vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 37, 'Men Tryfon gick ombord på ett skepp och flydde till Ortosia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 38, 'Då satte konungen Cendebeus till befälhavare över havskusten och lämnade honom fotfolk och ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 39, 'Och han bjöd honom att lägra sig invid Judeen och bjöd honom likaledes att befästa Cedron och förstärka dess portar och att strida mot judarna. Men konungen själv förföljde Tryfon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 40, 'Så drog då Cendebeus till Jamnia och begynte att oroa judarna och göra infall i Judeen och taga fångar och anställa blodbad bland folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 41, 'Och han befäste Cedron och förlade där ryttare och fotfolk, sorn skulle draga ut på strövtåg på vägarna i Judeen, såsom konungen hade befallt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 1, 'Men Johannes begav sig upp från Gasara och berättade för sin fader Simon vad Cende-beus förövade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 2, 'Då kallade Simon sina båda äldsta söner, Judas och Johannes, till sig och sade till dem: »Jag och mina bröder och min faders hus hava fört Israels strider allt ifrån vår ungdom ända till denna dag, och det har lyckats att under vår ledning rädda Israel många gånger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 3, 'Men nu är jag gammal, och I ären genom himmelens nåd i eder bästa ålder. Så träden då i mitt och min broders ställe, och dragen ut och striden för vårt folk. Och må himmelens bistånd vara med eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 4, 'Han utvalde därefter från landet tjugu tusen stridbara män, så ock ryttare; och de drogo mot Gendebeus och stannade över natten i Modein.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 5, 'Men bittida om morgonen bröto de upp och tågade ut på slätten. Då kom en stor här emot dem, fotfolk och ryttare; och en bäck skilde härarna åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 6, 'Johannes och hans folk lägrade sig nu mitt emot fienderna. Men när han såg att folket skydde för att gå över bäcken, gick han själv först över; och då männen sågo honom göra så, gingo också de över, efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 7, 'Han delade nu sitt folk, så att ryttarna kommo mitt ibland fotfolket; motståndarnas ryttare voro nämligen mycket talrika.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 8, 'Och de blåste i trumpeterna, och Cendebeus med sin här drevs på flykten, och många av dem föllo slagna; de övriga flydde till fästningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 9, 'Vid detta tillfälle blev Johannes\' broder Judas sårad. Men Johannes förföljde dem ända fram till Cedron, som Gendebeus hade befäst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 10, 'Och då de nu flydde till vakttornen på Asotus\' mark, brände Johannes upp denna stad i eld. På fiendernas sida föllo vid pass två tusen man; men Johannes vände välbehållen hem igen till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 11, 'Ptolemeus, Abubus\' son, hade blivit satt till befälhavare över slätten vid Jeriko. Och han hade kommit i besittning av guld och silver i mängd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 12, 'han var nämligen översteprästens måg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 13, 'Därför blev hans hjärta högmodigt, och han fick i sinnet att bemäktiga sig landet och uppgjorde svekfulla planer mot Simon och hans söner, i avsikt att röja dem ur vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 14, 'Nu plägade Simon resa omkring till städerna i landet för att sörja för deras bästa. Härunder kom han ock ned till Jeriko med sina söner Mattatias och Judas i elfte månaden, det är månaden Sabat, av år 177.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 15, 'Och Abubus\' son tog i sviklig avsikt emot dem i den lilla fästning, vid namn Dok, som han hade byggt, och gjorde för dem ett stort gästabud, sedan han förut hade gömt manskap där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 16, 'Men när Simon och hans söner hade blivit druckna, stodo Ptolemeus och hans män upp och togo sina vapen och trängde in till Simon i gästabudssalen och dräpte honom och hans söner, så ock några av hans tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 17, 'Han begick sålunda en stor trolöshet och vedergällde gott med ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 18, 'Sedan skrev Ptolemeus ett brev härom till konungen och sände bud till honom, med begäran om att han skulle skicka krigsfolk till hans hjälp och åt honom överlämna landet och städerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 19, 'Andra bud sände han till Gasara för att röja Johannes ur vägen. Och till överstarna sände han brev med uppmaning att de skulle infinna sig hos honom, så ville han giva dem silver och guld och andra skänker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 20, 'Andra åter sände han åstad för att taga Jerusalem och tempelberget i besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 21, 'Men en man skyndade i förväg till Gasara och berättade för Johannes att hans fader och hans bröder hade blivit dödade, och att Ptolemeus hade sänt folk åstad för att dräpa också honom själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 22, 'När Johannes fick höra detta, blev han mycket bestört; och han lät gripa de män som hade kommit för att döda honom och lät avliva dem. Ty han hade fått besked om att de sökte efter tillfälle att döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 23, 'Vad nu mer är att säga om Johannes och om hans strider och om de bedrifter som han utförde och om huru han åter byggde upp murarna och om allt annat vad han gjorde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 24, 'det finnes upptecknat i krönikan om hans översteprästämbete, allt ifrån den tid då han blev överstepräst efter sin fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'De judiska bröderna i Jerusalem och det judiska landet hälsa de judiska bröderna i Egypten och önska dem god lycka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Må Gud förläna eder allt gott och tänka på sitt förbund med sina trogna tjänare Abraham, Isak och Jakob.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Och give han eder alla ett sådant sinne att I frukten honom och gören hans vilja med frimodigt hjärta och villig själ.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Och må han öppna edra hjärtan för sin lag och sina stadgar och giva eder lycka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Och må han höra edra böner och åter bliva eder nådig, och må han icke övergiva eder i den onda tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Sådan är nu den bön som vi här bedja för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Under Demetrius\' regering, år 169, skrevo vi judar ett brev till eder i det övermåttan svåra betryck som drabbade oss under dessa år, alltsedan Jason med sina anhängare hade avfallit från det heliga landet och från riket,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'då när man brände upp porten och utgöt oskyldigt blod. Men vi bådo till Herren, och vi blevo bönhörda. Och vi framburo slaktoffer och spisoffer och tände lamporna och lade fram skådebröden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Och nu uppmana vi eder att fira den lövhyddohögtid som hålles i månaden Kisleu.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Skrivet år 188.» »Folket i Jerusalem och Judeen och Stora rådet och Judas hälsa Aristobulus, konung Ptolemeus\' lärare, av de smorda prästernas släkt, så ock övriga judar som äro i Egypten, och önska dem all välgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Då vi nu av Gud hava blivit räddade ur stora faror, tacka vi honom av allt hjärta; därvid äro vi dock alltid redo att ånyo upptaga striden mot konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Gud själv jagade nämligen bort dem som hade begynt strid i den heliga staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'När fursten hade kommit till Persien med sin här, som ansågs vara oemotståndlig, blevo de nedgjorda i Naneas helgedom, varvid Naneas präster begagnade en list.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Antiokus hade nämligen tillsammans med sina vänner begivit sig till denna plats, under förevändning av att vilja förmäla sig med gudinnan, i avsikt att så tillägna sig de rika skatterna såsom hemgift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Då nu Naneas präster hade lagt fram dessa och Antiokus tillsammans med några få andra hade inträtt inom det inhägnade tempelområdet, stängde prästerna igen helgedomen, så snart han hade kommit ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Därefter öppnade de lönnluckan i taket och kastade ned stenar och krossade så fursten och hans följe. Sedan höggo de dem i stycken och avhöggo deras huvuden och kastade ut dessa till dem som stodo därutanför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Lovad vare vår Gud för allt detta, han som så gav de ogudaktiga till spillo!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Då vi nu ämna på tjugufemte dagen i månaden Kisleu fira helgedomens rening, hava vi ansett det tillbörligt att giva eder meddelande härom, för att också I skolen fira lövhyddohögtiden och åminnelsen av den eld som tändes, när Neemias frambar offer, han som en gång åter byggde upp helgedomen och altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'När våra fäder fördes till Persien, togo nämligen den tidens fromma präster i hemlighet eld från altaret och dolde den djupt nere i en brunn, en sådan som ständigt är tom på vatten; och där beredde de åt den ett säkert förvaringsrum, som ingen annan kände till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Men efter många års förlopp, när det så behagade Gud, lät konungen i Persien Neemias vända tillbaka. Denne sände då ättlingarna av de präster som hade gömt elden, för att hämta den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Men när dessa förklarade att de icke hade funnit någon eld, utan allenast en tjock vätska, befallde han dem att ösa upp därav och taga med sig. När sedan det som hörde till offret hade blivit upplagt på altaret, befallde Neemias prästerna att med vätskan begjuta både veden och det som låg därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Då nu detta hade skett och solen, som förut hade varit skymd av moln, efter en stund lyste fram, flammade en hög låga upp, så att alla förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Och prästerna förrättade bön, medan offret förtärdes; ja, såväl prästerna som alla de övriga bådo. Jonatan ledde bönen, och de övriga, och med dem Neemias, stämde in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Bönen hade följande lydelse: \'Herre, Herre Gud, alltings skapare, du fruktansvärde och starke och rättfärdige och barmhärtige, du som allena är konung och allena är god,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'du som allena förlänar oss allt, du som allena är rättfärdig, allsmäktig och evig, du som frälsar Israel ur all nöd, du som har gjort våra fäder till dina utvalda och helgat dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'tag emot detta offer för hela ditt folk Israel, och beskydda din arvedel, och helga den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Samla åter tillhopa dem av oss, som äro kringspridda, befria dem som leva i träldom bland hedningarna, se till dem som äro föraktade och avskydda, och låt hedningarna förnimma att du är vår Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Straffa dem som förtrycka och misshandla oss i övermod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Plantera ditt folk på din heliga plats, enligt vad Moses har talat.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Och prästerna sjöngo därtill lovsångerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 31, 'Då nu det som hörde till offret hade blivit förbränt, befallde Neemias att man skulle gjuta jämväl återstoden av vätskan på stora stenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 32, 'Och när så hade skett, flammade en låga upp, vilken dock förtärdes av det sken som utstrålade från altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 33, 'Men när händelsen hade blivit bekant och det hade blivit berättat för perserkonungen att en vätska hade blivit funnen på den plats där de präster som blevo bortförda hade dolt elden, och att Neemias och hans män därmed hade helgat det som hörde till offret,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 34, 'då lät konungen, sedan han hade prövat saken, inhägna platsen och utmärka den såsom helig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 35, 'Och konungen tog mycket penningar och delade ut åt dem som han ville bevisa välvilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 36, 'Och Neemias och hans män benämnde vätskan neftar (det betyder rening), men av de flesta kallas den neftai.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Man finner i urkunderna att profeten Jeremias befallde dem som fördes bort att de skulle taga undan eld, såsom förut är berättat,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'och att profeten överlämnade lagen åt dem som fördes bort och därvid bjöd dem att de icke skulle förgäta Herrens stadgar, och att de icke skulle låta sig vilseföras i sitt sinne, när de fingo se avgudabilderna av guld och silver och prydnaderna på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Och jämväl med andra sådana ord förmanade han dem att troget bevara lagen i sina hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Det stod också i samma skrift att profeten, på grund av en uppenbarelse från Gud, befallde att tabernaklet och arken skulle bäras efter honom, och att han så begav sig åstad till det berg från vars höjd Moses hade skådat Guds arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Då nu Jeremias hade kommit dit, fann han ett grottliknande rum; och han lät bära tabernaklet och arken och rökelsealtaret ditin, och spärrade sedan till ingången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Några av dem som hade följt med honom begåvo sig efteråt ditbort för att märka ut vägen, men de kunde icke finna den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'När Jeremias fick veta detta, bannade han dem och sade: \'Platsen skall vara okänd, till dess Gud åter församlar hela folket och barmhärtighet vederfares oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Då skall Herren låta dessa föremål komma i dagen, och man skall få se Herrens härlighet, molnskyn, såsom den uppenbarade sig på Moses\' tid och på den dag då Salomo bad att platsen skulle bliva helgad i underbar måtto.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Och där förtäljdes också huru denne, som ägde sådan vishet, frambar offer vid helgedomens invigning och fullbordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Likasom Moses bad till Herren, och eld föll ned från himmelen och förtärde det som hörde till offret, så bad ock Salomo till Herren, och elden föll ned och förbrände brännoffren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Och Moses sade: \'Därför att man icke har ätit syndoffret, har det blivit förbränt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Likaså firade ock Salomo de åtta dagarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Detsamma stod också omtalat i Neemias\' uppteckningar och hågkomster, så ock huru denne grundade ett bibliotek och där samlade böckerna om konungarna och profeterna, och Davids skrifter, jämte konungabrev om tempelskänker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Likaså samlade ock Judas åt oss alla de böcker som hade blivit skingrade till följd av det krig vi hava haft att utkämpa; och de finnas nu hos oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'I mån alltså, om I behoven dem, sända bud och hämta dem till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Då vi nu således ämna fira tempelreningen, skriva vi detta till eder. Och I gören väl, om I firen dessa dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Men Gud, som har frälst hela sitt folk och återgivit dem alla sin arvedel, så ock konungadömet och prästadömet och heligheten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'såsom han hade lovat i sin lag, på honom hoppas vi nu, och vänta att han snart skall förbarma sig över oss och församla oss till den heliga platsen från alla land under himmelen. Ty han har räddat oss ur stor nöd och renat platsen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Vad nu angår Judas Mackabeus och hans bröder och den stora helgedomens rening och altarets invigning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'vidare striderna mot Antiokus Epifanes och hans son Eupator');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'och de uppenbarelser som tedde sig på himmelen för dem som modigt och ärofullt kämpade för judendomen, så att de, trots sitt ringa antal, togo byte i hela landet och förjagade de vilda fiendeskarorna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'och återvunno den över hela världen namnkunniga helgedomen och befriade staden och åter upprättade lagarna, som voro nära att bliva avskaffade, i det att Herren i sin stora mildhet blev dem nådig -');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'vad nu angår allt detta, som av Jason från Cyrene har blivit berättat i fem böcker, så skola vi här försöka att sammanfatta det i en enda bok.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ty i det vi besinnade huru många taluppgifterna där äro, och vilket besvär som de behandlade ämnenas rikedom vållar dem som önska intränga i de historiska skildringarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'hava vi här vinnlagt oss om att bereda underhållning åt dem som vilja hava något att läsa, och lättnad för dem som bemöda sig om att i minnet bevara vad de hava läst, och gagn åt alla dem som få boken i sina händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'För oss åter, som hava påtagit oss besväret med sammandraget, är arbetet visserligen icke lätt, utan förenat med ansträngning och möda -');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'alldeles såsom den som anordnar ett festligt lag och strävar efter att se de andra till godo icke själv har det bekvämt; men likväl vilja vi, på grund av den tacksamhet som vi vänta från många, gärna underkasta oss detta besvär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Att noga utforska var särskild omständighet betrakta vi därvid såsom den verklige författareris sak, medan vi själva vilja bemöda oss om att tillämpa reglerna för ett sammandrag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Det är ju så, att medan den som uppför ett nytt hus måste tänka på bygget i dess helhet, behöver den som åtager sig att förse det med målningar i inbränt arbete allenast taga reda på det som är erforderligt för dess utsmyckning; på det sättet är det, efter min mening, också med oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Ty att fördjupa sig i saken och noga redogöra för allting och underkasta sig mycken möda med alla enskildheter, det tillkommer den ursprunglige historieskrivaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 31, 'Men den som vill utföra en bearbetning, han bör hava lov att sträva efter korthet i uttryckssättet, och samtidigt slippa att lämna en uttömmande skildring av händelserna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 32, 'Härmed må vi då begynna vår framställning, sedan vi till det först sagda hava tillfogat allenast detta. Det vore ju dåraktigt att komma med ett mångordigt företal till berättelsen, men meddela själva berättelsen i kort sammandrag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Vid den tid då full frid och ro rådde i den heliga staden, och medan lagens föreskrifter ännu på bästa sätt togos i akt, tack vare översteprästen Onias\' fromhet och hans avsky för vad orätt var,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'förekom det att till och med konungarna bevisade den heliga platsen heder och förhärligade helgedomen genom de präktigaste skänker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Ja, Seleukus, konungen i Asien, betalade av sina egna inkomster alla de kostnader som voro förbundna med offertjänsten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Nu hände sig att en viss Simon, av Benjamins stam, som hade blivit satt till uppsyningsman vid helgedomen, blev oense med översteprästen angående uppsikten över torghandeln i staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Då han nu icke kunde driva sin vilja igenom mot Onias, begav han sig till Apollonius från Tarsus, vilken på den tiden var ståthållare i Celesyrien och Fenicien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Och han omtalade för denne huru skattkammaren i Jerusalem var uppfylld av så övermåttan stora rikedomar, att penningarna för sin myckenhets skull icke kunde räknas; han framhöll ock att dessa vida överstego vad som behövdes för offren, och att konungen mycket väl skulle kunna få alltsammans i sitt våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'När Apollonius sedan träffade samman med konungen, gav han denne meddelande om de skatter som han hade fått vetskap om. Konungen utsåg då sin kansler Heliodorus och sände honom åstad, med uppdrag att bortföra de nyss omtalade penningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Heliodorus företog strax denna resa, under förevändning av att vilja besöka städerna i Celesyrien och Fenicien, men i verkligheten för att utföra konungens plan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'När han kom fram till Jerusalem, blev han där vänligt mottagen av översteprästen och folket i staden. Han underrättade nu denne om det meddelande som han hade fått, och förklarade varför han hade kommit dit; han frågade honom ock om saken verkligen förhöll sig på det uppgivna sättet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Översteprästen påvisade då att penningarna utgjordes av gods som hade lämnats i förvar av änkor och faderlösa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'en del därav också av Hyrkanus, Tobias\' son, en man i mycket hög ställning. Det var icke så, sade han, som den gudlöse Simon falskeligen hade uppgivit; alltsammans uppgick allenast till fyra hundra talenter silver och två hundra talenter guld,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'och en sådan orätt kunde man på inga villkor begå mot dem som hade förlitat sig på platsens helighet och den i hela världen ärade helgedomens höghet och okränkbarhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Men den andre vidhöll, med stöd av det uppdrag som han hade fått av konungen, att penningarna under alla förhållanden måste indragas till den kungliga skattkammaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Då han nu på utsatt dag skulle gå in i templet för att låta besiktiga skatten, rådde en mycket stor ångest i hela staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Prästerna kastade sig i sina ämbetsskrudar ned framför altaret och ropade mot himmelen och åkallade honom som hade stiftat lagen om gods som var lämnat i förvar, att han ville bevara allt detta oförkränkt åt dem som hade lämnat det i förvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Och den som såg översteprästens utseende, honom måste det skära i hjärtat; ty hans uppsyn och hans förändrade ansiktsfärg förrådde hans själs ångest.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Han var nämligen uppfylld av en sådan fruktan och darrade så i hela kroppen, att den smärta som bodde i hans bröst tydligt framträdde för dem som sågo honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Men de som voro i husen rusade hopvis ut därifrån för att gemensamt bedja, eftersom den heliga platsen var i fara att bliva vanärad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Och de gifta kvinnorna samlade sig i skaror på gatorna, omgjordade under bröstet med säcktyg, och jungfrurna, som eljest icke fingo visa sig ute, strömmade tillsammans, dels till portarna, dels på murarna, och några sågo ut genom fönstren;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'men allasammans räckte de händerna mot himmelen och framsade böner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Och det var ömkansvärt att skåda de många människorna, som hade kastat sig ned om varandra, och översteprästen, som stod där väntande, i högsta ångest.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 22, 'Under det att nu dessa anropade Herren, den Allsmäktige, att han ville i full trygghet bevara det anförtrodda godset oförkränkt åt dem som hade anförtrott det till förvaring,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 23, 'beredde sig Heliodorus till att sätta sitt beslut i verket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 24, 'Men när han, åtföljd av sina drabanter, redan var framme vid skattkammaren, lät han som råder över andarna och över all makt en stor uppenbarelse ske, så att alla de som hade dristat sig att följa med ditin blevo slagna med häpnad över Guds makt och förlamade av skräck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 25, 'Ty för dem visade sig en häst, som var prydd med en präktig mundering och bar en fruktansvärd ryttare. Den sprängde häftigt fram och lyfte sina f ramhovar mot Heliodorus. Och ryttaren tedde sig för dem i en vapenrustning av guld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 26, 'Utom denne såg man två unga män, med ansenlig styrka, strålande av skönhet och i praktfulla kläder, vilka trädde fram till Heliodorus och ställde sig bredvid honom, en på vardera sidan, och oavlåtligt gisslade honom, i det att de tilldelade honom slag på slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 27, 'Heliodorus föll då plötsligt till marken, och djupt mörker höljde hans syn. Han blev nu skyndsamt upplyft och lagd på en bår;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 28, 'och den som nyss med talrikt följe och hela drabanthopen hade trätt in i den förut omtalade skattkammaren, han måste nu bäras, helt och hållet ur stånd till att hjälpa sig själv, sedan han uppenbarligen hade fått förnimma Guds makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 29, 'Där låg då alltså denne, slagen till marken genom den gudomliga kraftens verkan, mållös och berövad allt hopp om räddning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 30, 'men de andra prisade Herren, som så underbart förhärligade sin boning. Och helgedomen, som kort förut hade varit uppfylld av skräck och förvirring, var nu, då Herren, den Allsmäktige, hade uppenbarat sig, fylld av fröjd och glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 31, 'Men några av Heliodorus\' förtrogna bådo med hast Onias att han skulle åkalla den Högste och så utverka livet åt honom som rentav var nära att utandas sin sista suck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 32, 'Och eftersom översteprästen befarade att konungen kunde få den uppfattningen att någon illgärning hade blivit begången mot Heliodorus av judarna, frambar han ett offer för dennes räddning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 33, 'Medan nu översteprästen förrättade försoningsoffret, visade sig åter för Heliodorus samma unga män, iförda samma klädnader som förut; de trädde fram till honom och sade: »Du må känna stor tacksamhet mot översteprästen Onias, ty för hans skull har Herren återskänkt dig livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 34, 'Men du själv, som har fått känna på gisselslag från himmelen, du må för alla förkunna Guds stora makt.» Sedan de hade sagt detta, försvunno de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 35, 'Och Heliodorus frambar ett offer åt Gud och gjorde stora löften åt den som hade låtit honom behålla livet. Sedan han därefter hade tagit avsked av Onias, drog han med sitt krigsfolk tillbaka till konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 36, 'Och han vittnade inför alla om de gärningar av den högste Guden, som han med egna ögon hade skådat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 37, 'När sedan konungen en dag frågade Heliodorus vem som kunde vara lämplig att ännu en gång sända till Jerusalem, svarade denne: 38 »Om du har någon som är din motståndare, eller någon som stämplar mot din styrelse, så sänd honom dit; du skall då få honom tillbaka gisslad, såframt han alls kommer undan med livet, eftersom förvisso någon gudomlig kraft omhägnar den platsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 38, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 39, 'Ty han som har sin boning i himmelen, han har själv vård om denna plats och skyddar den; och var och en som kommer dit i ont uppsåt slår och förgör han.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 40, 'På detta sätt ändade Heliodorus\' företag, och så gick det till, när tempelskatten blev bevarad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Men den förut omtalade Sisom hade gjort angivelsen om penningarna och förrått sitt fädernesland, utspridde det onda ryktet om Onias, att det var denne själv som hade skrämt Heliodorus och anstiftat hela olyckan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Ja, han fördristade sig att kalla honom som var stadens välgörare och sina landsmäns beskyddare och lagens nitiske vårdare för en ränksmidare mot styrelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Men när fiendskapen gick så långt att en av Simons betrodda män till och med gjorde sig skyldig till blodsdåd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'och Onias nu insåg huru farlig en sådan tvedräkt kunde bliva, och därtill märkte huru Apollonius, Menesteus\' son, ståthållaren i Celesyrien och Fenicien, ytterligare underblåste Simons ondska,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'då begav han sig åstad till konungen, icke för att uppträda såsom anklagare mot sina landsmän, men i avsikt att främja vad som lände hela folket till gagn, både i det allmänna och i det enskilda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Han förstod nämligen att det skulle vara omöjligt att få frid och ro i de allmänna förhållandena, om icke konungen tog saken i sin hand, och att Simon icke skulle upphöra med sin galenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Men när Seleukus hade avlidit och Antiokus, med tillnamnet Epifanes, hade övertagit konungamakten, lyckades Jason, Onias\' broder, på bakslugt sätt tillvälla sig översteprästämbetet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'i det att han ingav en skrivelse till konungen och lovade honom tre hundra sextio talenter silver, och därtill ur en annan inkomstkälla åttio talenter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Därjämte utfäste han sig att lämna skriftlig förbindelse på ytterligare ett hundra femtio talenter, om det tillstaddes honom att efter eget gottfinnande upprätta en anstalt för kroppsövningar och en övningsskola för ynglingar, och att få upptaga Jerusalems invånare såsom medborgare i Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Sedan konungen hade givit sitt bifall härtill och Jason så hade fått makten i sina händer, begynte denne genast att omdana sina landsmän efter grekiskt mönster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Han förkastade de förmåner som konungen hade beviljat judarna genom förmedling av Johannes, fader till den Eupolemus som var med bland dem som sändes till romarna, för att ingå vänskap och förbund; han avskaffade ock de lagliga ordningarna och införde nya lagstridiga seder och bruk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Så anlade han med vett och vilja just nedanför själva borgen en anstalt för kroppsövningar, och de förnämaste unga männen förmådde han att i grekisk huvudbonad deltaga i övningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Och en sådan blomstring nådde det grekiska väsendet, och en så stor omfattning tog övergången till hedniska skick och bruk, i följd av den ogudaktige och föga översteprästerligt sinnade Jasons övermåttan stora skändlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'att prästerna icke längre brydde sig om att sköta sin tjänst vid altaret, utan visade förakt för templet och försummade offren och skyndade åstad för att få vara med om det lagstridiga skådespelet på övningsbanan, så snart tecken hade givits till övning med kastskivan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Det som fäderna räknade såsom något hedrande, det aktade de sålunda för intet; de grekiska utmärkelserna däremot ansågo de vara mycket ärofulla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Fördenskull råkade de ock i svår nöd; de fingo till fiender och plågare just dem vilkas levnadsvanor de så ivrigt efterhärmade, och som de i allt ville likna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ty att vanvörda de gudomliga lagarna sker icke utan våda. Nej, att så är, det visar vad som efteråt händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Då nu de vart fjärde år återkommande tävlingsspelen firades i Tyrus, i konungens närvaro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'skickade den skändlige Jason såsom ombud från Jerusalem vid spelen några män som hade fått medborgarrätt i Antiokia, för att lämna fram tre hundra drakmer silver till offret åt Herkules. Men de som så skulle lämna fram penningarna bådo att man icke skulle använda dem till offer, utan bestämma dem för någon annan utgift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Dessa penningar skulle alltså enligt avsändarens vilja gå till offret åt Herkules, men tack vare dem som skulle lämna fram penningarna gingo dessa till treroddarfartygens utrustning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Med anledning av konung Filometors tronbestigning blev Apollonius, Menesteus\' son, sänd till Egypten. Genom honom fick Antiokus underrättelse om att Filometor hade blivit ovänligt stämd mot hans regering. Han begynte därför att vidtaga mått och steg för att trygga sitt rikes säkerhet. Då han nu för detta ändamål hade begivit sig till Joppe, avlade han också ett besök i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Här fick han ett ståtligt mottagande av Jason och folket i staden och ledsagades ditin under fackelsken och glädjerop. Därefter drog han med sin här till Fenicien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Men efter tre år sände Jason åstad Menelaus, en broder till den förut nämnde Simon, för att till konungen överlämna de penningar som han hade utlovat, och för att avsluta förhandlingarna angående några nödiga frågor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 24, 'Denne ställde sig in hos konungen och smickrade honom, under det att han själv uppträdde såsom vore han en mäktig man, och lyckades så få översteprästämbetet överflyttat på sig, i det han överbjöd Jason med tre hundra talenter silver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 25, 'Sedan han nu hade erhållit konungens fullmakt, vände han tillbaka hem, utan att äga något som gjorde honom värdig översteprästämbetet, men med alla en grym härskares lidelser och ett vilddjurs raseri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 26, 'Så blev då Jason, som bakslugt hade undanträngt sin egen broder, själv på ett bakslugt sätt undanträngd av en annan och jagad i landsflykt till ammoniternas land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 27, 'Menelaus var alltså visserligen i besittning av makten, men fullgjorde icke sina skyldigheter i fråga om de penningar som han hade lovat konungen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 28, 'och detta, fastän Sostratus, befälhavaren på borgen, framställde krav på dem; denne ålåg det nämligen att indriva penningavgifterna. På grund härav lät konungen kalla dem båda inför sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 29, 'Menelaus lämnade då kvar såsom ställföreträdare i översteprästämbetet sin broder Lysimakus, Sostratus åter såsom sin ställföreträdare Krates, befälhavaren på Cypern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 30, 'Så stodo nu sakerna, när ett upplopp inträffade i Tarsus och Mallus, med anledning av att dessa städer hade blivit bortgivna såsom gåva åt Antiokis, konungens bihustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 31, 'Konungen begav sig då med all hast dit, för att ordna förhållandena, och lämnade såsom sin ställföreträdare kvar Andronikus, en av dem som stodo högst i anseende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 32, 'Menelaus, som nu ansåg sig hava fått ett gynnsamt tillfälle, tillgrep några av helgedomens guldkärl och förärade dem åt Andronikus; andra sådana hade han just låtit sälja i Tyrus och kringliggande städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 33, 'När Onias hade fått säker kunskap härom, uttalade han sitt skarpa ogillande därav, sedan han förut hade dragit sig undan till en fridlyst plats i Dafne, det som ligger invid Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 34, 'Menelaus tog på grund härav Andronikus avsides och uppmanade honom att bära hand på Onias. Sedan Andronikus hade låtit övertala sig till att begå ett sådant svek och fått bekräfta detta med edlig försäkran, begav han sig åstad till Onias och lyckades också, fastän han var misstänkt, att, efter avgiven försäkran, övertala denne att lämna sin fristad. Han lät nu ofördröjligen röja honom ur vägen, utan att hava någon försyn för vad rätt var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 35, 'Därför kände också icke allenast judar, utan jämväl många från de andra folken ovilja och förtrytelse över det orättfärdiga mordet på denne man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 36, 'Och när konungen kom tillbaka från Ciliciens landsändar, anförde judarna i staden klagomål över att Onias så hade blivit dräpt utan sak; och jämväl grekerna visade sin avsky över ogärningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 37, 'Då blev Antiokus djupt bedrövad, och han rördes till medlidande och tårar på grund av den avlidnes hovsamhet och stora redbarhet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 38, 'han upptändes av vrede och lät genast taga ifrån Andronikus hans purpurmantel och slita sönder hans kläder, och han lät föra honom omkring genom hela staden, till just den plats där han hade förövat illgärningen mot Onias. Där lät han avrätta mördaren, som sålunda av Herren fick sitt välförtjänta straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 39, 'Men Lysimakus begick, med Menelaus\' goda minne, många helgerån i staden, och ryktet härom spridde sig utanför staden. Då samlade sig mängden tillhopa mot Lysimakus, sedan ett stort antal guldkärl redan hade blivit skingrade åt olika håll.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 40, 'Men när folkhoparna, fulla av förbittring, satte sig i rörelse, lät Lysimakus väpna vid pass tre tusen man och gjorde så själv begynnelsen med att bruka våld; därvid hade en viss Hauranus ledningen, en man som var långt framskriden i ålder och lika långt i dårskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 41, 'Så snart de nu märkte att Lysimakus rentav lät det gå till anfall, grepo somliga av dem stenar, andra grova trästycken, och några togo händerna fulla av askan som låg där, och slungade allt detta om vartannat in bland Lysimakus\' folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 42, 'På det sättet sårade de många av dem och nedgjorde också några och drevo hela skaran på flykten. Och helgerånaren själv dräpte de invid skattkammaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 43, 'Med anledning av vad som hade skett öppnades en rättegång mot Menelaus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 44, 'Och när konungen hade anlänt till Tyrus, förde de tre män som hade blivit ditsända av Stora rådet sin talan inför honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 45, 'Men då Menelaus\' sak redan syntes förlorad, lovade han Ptolemeus, Dorymenes\' son, en ansenlig summa penningar, för att denne skulle söka vinna konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 46, 'I detta syfte förde Ptolemeus konungen bort till en pelargång, under förevändning av att han skulle få svalka sig, och lyckades nu omstämma honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 47, 'Och så frikände konungen Menelaus från anklagelserna, denne som var upphovsman till hela skändligheten; men de ömkansvärda männen, som skulle hava blivit frikända såsom icke skyldiga, till och med om de hade haft att föra talan inför skyter, dem dömde han till döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 48, 'Dessa som hade talat till försvar för staden och folket och de heliga kärlen fingo således utan dröjsmål undergå ett oförtjänt straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 49, 'På grund av denna våldsgärning blevo jämväl några tyrier upprörda och betalade utgifterna för deras likbegängelse med stor frikostighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 50, 'Men Menelaus fick, till följd av de maktägandes snikenhet, behålla sin höga ställning; och han uppträdde såsom en stor ränksmidare mot sina egna landsmän, allt under det att han tillväxte i ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 1, 'Vid samma tid företog Antiokus sitt andra krigståg till Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 2, 'Då hände sig att man i hela staden under vid pass fyrtio dagar såg ryttare, iklädda guldstickade dräkter och väpnade med spjut, spränga fram genom luften i hopar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 3, 'och man såg svärd som drogos och avdelade ryttarskaror och anfall som gjordes och sammandrabbningar från ömse sidor; och man såg sköldar svingas och lansar slungas i mängd och pilar flyga och prydnader av guld blixtra, och man såg pansar av allahanda slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 4, 'Med anledning härav bådo alla att synen måtte hava en lyckosam betydelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 5, 'Men sedan ett falskt ryktes hade uppstått, att Antiokus hade avlidit, skaffade sig Jason minst ett tusen man, och med dessa företog han ett oförmodat anfall på staden. Då nu de som voro på muren hade drivits undan och staden slutligen just var nära att intagas, flydde Menelaus till borgen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 6, 'Nu anställde Jason ett skoningslöst blodbad i staden på sina egna bröder. Han betänkte därvid icke att hans framgång mot stamfränderna var den största motgång, utan tyckte sig hembära seger över fiender och icke över landsmän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 7, 'Men makten lyckades han icke att sätta sig i besittning av; slutet av hans anslag blev i stället att han med skam måste såsom flykting vända tillbaka till ammoniternas land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 8, 'Och detta blev änden på hans usla levnad: han blev först kastad i fängelse hos Aretas, arabernas furste, och sedan måste han, förföljd av alla, fly ifrån stad till stad; han blev hatad såsom en avfälling från lagen och avskydd såsom en bödel mot sitt eget land och folk; till sist blev han bortjagad till Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 9, 'Han som hade tvingat så många att fly ifrån sitt eget land till främmande land, han omkom nu själv i främmande land, sedan han hade farit över till lacedemonierna, i hopp om att hos dem erhålla skydd till följd av frändskapen med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 10, 'Och han som hade låtit kasta ut så många döda kroppar, utan att unna dem någon begravning, han blev själv obegråten, ja, han fick icke en gång någon som helst likbegängelse, ej heller en grav hos sina fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 11, 'När underrättelse nådde konungen om vad som hade hänt, fick han den föreställningen att Judeen var på väg att avfalla. Därför bröt han upp från Egypten, vild av vrede, och intog staden med vapenmakt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 12, 'Och han befallde sitt krigsfolk att utan försköning hugga ned dem som kommo i deras väg octi att dräpa dem som flydde upp i husen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 13, 'Så pågick där ett blodbad på unga och gamla; man avlivade minderåriga och kvinnor och barn, man slaktade jungfrur och spenabarn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 14, 'Åttio tusen människor gingo förlorade under sammanlagt allenast tre dagar: fyrtio tusen dräptes under handgemänget, och ett lika stort antal såldes såsom trälar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 15, 'Men konungen lät sig icke nöja härmed; han fördristade sig ock att träda in i den helgedom som var den heligaste på hela jorden, vägledd av Menelaus, denne som hade förrått både lagen och sitt fädernesland.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 16, 'Med sina orena händer tog han de heliga kärlen; och de skänker som många konungar hade låtit ställa upp där, för att förhöja den heliga platsens glans och ära, dem släpade han bort med sina besudlade händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 17, 'Och Antiokus förhävde sig däröver i sitt sinne och betänkte icke att Herren till en kort tid vredgades på stadens invånare för deras synders skull, och att det var därför som den heliga platsen nu blev prisgiven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 18, 'Men om det icke hade varit så, att de förut voro insnärjda i en mängd synder, så skulle konungen, när han trängde ditin, strax hava genom gisselslag blivit tvingad att uppgiva sitt fräcka dåd, alldeles såsom det gick med Heliodorus, när han av konung Seleukus hade blivit sänd åstad för att besiktiga skattkammaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 19, 'Men Herren hade icke utvalt folket för platsens skull, utan platsen för folkets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 20, 'Därför blev också platsen, sedan den hade fått vara med om de olyckor som drabbade folket, själv omsider delaktig av de välgärningar som detta fick röna; och sedan den hade råkat i fiendehand till följd av den Allsmäktiges vrede, blev den, när den store härskaren åter hade blivit folket nådig, med all heder upprättad igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 21, 'Antiokus förde alltså bort ett tusen åtta hundra talenter ur helgedomen och drog så med all hast därifrån till Antiokia. Och nu trodde han i sitt högmod att han kunde göra land till hav, och hav till land; så stor var hans hjärtas förhävelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 22, 'Han lämnade också kvar uppsyningsrnan för att plåga folket: i Jerusalem Filippus, till börden en frygier, vilken betedde sig ännu grymmare än den som hade tillsatt honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 23, 'och på Garisim Andronikus. Utom dessa lämnade han ock kvar Menelaus, som utövade ett ännu värre förtryck mot sina landsmän än de övriga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 24, 'Och i sitt hätska sinnelag mot judarna sände konungen åstad Apollonius, befälhavaren över mysierna, i spetsen för en krigshär på tjugutvå tusen man, med befallning att hugga ned alla vapenföra män och att sälja kvinnor och minderåriga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 25, 'Sedan denne hade kommit till Jerusalem, hycklade han fredliga avsikter och höll sig stilla, till dess den heliga sabbatsdagen var inne. Men när han nu såg huru judarna den dagen höllo sig overksamma, befallde han sitt folk att ställa upp sig i vapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 26, 'Alla dem som då gingo ut ur staden för att se vad som tilldrog sig lät han nu på en gång nedgöra. Därefter ryckte han under vapen skyndsamt in i staden och bragte en stor mängd människor om livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 27, 'Men Judas, som ock kallades Mackabeus, drog sig undan till öknen tillika med ett tiotal andra. Där levde han, jämte dem som voro med honom, bland bergen såsom de vilda djuren; och de livnärde sig hela tiden med vad som växte på marken. Detta gjorde de för att icke ådraga sig besmittelse såsom de övriga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 1, 'Icke lång tid därefter sände konungen åstad en gammal man, en atenare, för att tvinga judarna att övergiva sina fäders lag och att upphöra med att leva efter Guds lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 2, 'Han skulle därjämte oskära templet i Jerusalem och inviga det åt den olympiske Jupiter, så ock templet på Garisim åt den Jupiter som var gästvänskapens beskyddare, eftersom de som bodde på den platsen hade ett så gästvänligt sinnelag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 3, 'Ett sådant ondskans anlopp kändes jämväl för den stora mängden svårt och olidligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 4, 'Ty i liderliga, vilda sällskap uppfyllde hedningarna helgedomen; de levde i sus och dus tillsammans med skökor och hade i de heliga förgårdarna umgänge med kvinnor och förde därtill med sig ditin otillbörliga ting.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 5, 'Och altaret var uppfyllt med otillåtna offer, sådana som voro förbjudna i lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 6, 'Man fick icke längre hålla sabbat eller taga de fäderneärvda högtiderna i akt; ja, man fick icke alls bekänna sig vara jude.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 7, 'Och på konungens födelsedag, som firades i var månad, drevs folket med grymt tvång till att deltaga i offermåltiderna; och vid Backusfesten tvingades de att med murgrönskrans på huvudet gå med i festtåget till Backus\' ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 8, 'En förordning utgick också, på Ptolemeus\' inrådan, till de närmast belägna grekiska städerna, att man där skulle gå till väga mot judarna på samma sätt och tvinga dem att deltaga i offermåltiderna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 9, 'men att man skulle dräpa alla dem som icke ville besluta sig för att antaga grekiska seder och bruk. Ja, man kunde nu tydligt se vilket elände som rådde där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 10, 'Så blevo en gång två kvinnor som hade låtit omskära sina gossebarn hämtade fram; och man hängde de späda barnen vid deras bröst och förde sedan mödrarna i allas åsyn omkring i staden och störtade dem slutligen utför muren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 11, 'Och andra, som hade skyndat tillsammans till grottorna där i närheten för att obemärkt fira den sjunde dagen, men som hade blivit förrådda för Filippus, blevo allasammans innebrända, därför att de på grund av den höga dagens härlighet hyste betänkligheter mot att försvara sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 12, 'Nu vill jag uppmana alla dem som få denna bok i sina händer att icke bliva modfällda till följd av sådana olyckor, men att i stället besinna att hemsökelserna icke syfta till vårt folks fördärv, utan tvärtom tjäna till dess fostran.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 13, 'Också är det ett bevis på stor nåd att de gudlösa icke under lång tid få gå fria, utan med hast drabbas av sitt straff.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 14, 'När det gäller andra folk, väntar väl Herren i sin långmodighet med att tukta dem, till dess de hava hunnit fylla sina synders mått; men med oss har han däremot icke velat handla på samma sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 15, 'Han vill ju icke att vi i vår synd skola gå till den yttersta gränsen, för att han sedan skall nödgas straffa oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 16, 'Därför undandrager han oss aldrig sin barmhärtighet, och han övergiver icke sitt folk, om han än fostrar det genom olyckor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 17, 'Dock, detta vare oss sagt allenast såsom en erinran. Efter detta korta avb rrott vilja vi nu åtgå till berättelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 18, 'En viss Eleasar, som hörde till de förnämsta bland de skriftlärde, en redan till hög ålder kommen man med mycket vördnadsbjudande utseende, tvingades att öppna munnen för att äta svinkött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 19, 'Men eftersom han hellre ville dö med ära än leva i skam, spottade han först ut köttet och gick sedan frivilligt fram mot pinbänken');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 20, 'på det sätt som det hövdes alla dem att vandra en sådan väg, vilka hade mod till att visa ifrån sig det som icke är tillstått att smaka, vore det ock för att få behålla livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 21, 'Men då nu de som skulle hava tillsyn över den lagstridiga offermåltiden sedan länge voro bekanta med den gamle mannen, förde de honom avsides och uppmanade honom att låta skaffa dit kött som han hade lov till att förtära, och som han själv hade tillrett, men låtsa, som om han åte av det offerkött som konungen hade påbjudit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 22, 'Om han så gjorde, skulle han bliva befriad från dödsstraffet och tack vare den gamla vänskapen med dem få röna detta prov på välvilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 23, 'Men han fattade nu ett ädelt beslut, ett sådant som hövdes hans år, och den värdighet som var förenad med hans höga ålder, och de grå hår som han hade vunnit med ära, och hans rättsinniga vandel allt ifrån ungdomen, ja, än mer, ett sådant som överensstämde med den heliga, av Gud inrättade lagordningen. I det han begärde att utan dröjsmål bliva sänd till dödsriket, förklarade han öppet: 24 »Det vore ju icke värdigt en ålder, sådan som min, att hyckla och därigenom komma många av de unga att tro att den nittioårige Eleasar hade övergått till hedendomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 24, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 25, 'På det sättet skulle jag ju föra också dem på avvägar genom mitt hyckleri och draga skam och vanära över mina grå hår, allenast för att ännu få leva en helt kort och obetydlig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 26, 'Ty om jag än för tillfället undslipper det straff som människor utkräva, så skall jag dock varken såsom levande eller såsom död kunna fly undan den Allsmäktiges hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 27, 'Därför vill jag nu modigt skiljas ifrån livet och så visa mig värdig min höga ålder');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 28, 'och lämna de unga ett ädelt föredöme huru man bör villigt och med ädelt mod gå en skön död till mötes för den höga och heliga lagen.» Han fick icke säga mer, förrän han strax släpades till pinbänken,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 29, 'i det att de som förde honom bort nu förändrade sin kort förut visade välvilja till ovilja, eftersom de ansågo de ord som han nyss hade uttalat vittna om vanvett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 30, 'Då han nu var nära att uppgiva andan under slagen, drog han en djup suck och sade: »Herren, som äger den heliga kunskapen, han vet väl, att fastän jag kunde bliva befriad från dödsstraffet, jag genom gisselslagen utstår grymma kval i min kropp, men att jag i min själ med glädje lider detta, därför att jag fruktar honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 31, 'På detta sätt slutade alltså denne man sina dagar och efterlämnade så i sin död ett föredöme i ädelt mod och ett minnesvärt exempel på manlig dygd, icke allenast åt de unga, utan ock åt den stora hopen av sitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 1, 'Det hände sig ock att sju bröder, tillika med deras moder, blevo gripna, och att konungen genom misshandling med gissel och remmar sökte tvinga dem att smaka av det förbjudna svinköttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 2, 'Men en av dem tog i allas namn till orda och sade: »Vad vill du fråga oss om, och vad vill du få veta av oss? Vi äro ju redo att dö, hellre än att vi skulle överträda våra fäders lag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 3, 'Då blev konungen upptänd av vrede och gav befallning om att låta hetta upp pannor och kittlar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 4, 'Sedan man nu ofördröjligen hade gjort detta, befallde han att man skulle skära av tungan på den som hade fört ordet och draga av honom huvudsvålen och lemlästa honom, medan hans bröder och modern sågo på.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 5, 'Och när han var helt och hållet stympad, blev han, medan han ännu var vid liv, på konungens befallning buren till elden och stekt i en panna. Då nu oset från pannan spridde sig vida omkring, manade de övriga, tillika med modern, varandra att med ädelt mod lida döden; de sade: 6 »Herren Gud ser till detta, och han skall förvisso förbarma sig över oss, såsom Moses gav till känna i den sång i vilken han öppet vittnade mot folket, när han sade: \'Och över sina tjänare skall han förbarma sig\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 6, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 7, 'Då nu den förste på detta sätt hade gått hädan, förde de fram den andre för att likaledes skymfligt pinas. Och sedan de hade flått av honom huvudsvålen med håret, frågade de honom: »Vill du äta, förrän din kropp styckas sönder, lem för lem?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 8, 'Men han svarade på sina fäders tungomål och sade: »Nej, det vill jag icke.» Fördenskull fick också denne undergå den återstående misshandlingen, han likasom den förste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 9, 'Men då han var nära att uppgiva andan, sade han: »Du niding, du tager oss väl bort ifrån detta livet, men hela världens konung skall låta oss, som hava dött till försvar för hans lag, uppstå till ett nytt, ett evigt liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 10, 'Efter honom blev den tredje skymfligt pinad, och när han så blev befalld, räckte han strax ut sin tunga och sträckte likaledes oförfärat fram händerna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 11, 'och sade med ädelt mod: »Från himmelen har jag fått dessa lemmar, och för Hans lags skull räknar jag dem för ringa, och av Honom hoppas jag att en gång få dem tillbaka igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 12, 'Nu måste konungen själv och hans män häpna över ynglingens mod och förundra sig över huru han aktade kvalen för intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 13, 'Sedan också denne hade skilts hädan, misshandlade och pinade de den fjärde på samma sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 14, 'Och då han var nära att dö, sade han så: »Det är en stor tröst, när man måste dö för människohand, att då få hysa det av Gud ingivna hoppet att genom honom få uppstå igen. Men för dig skall det icke finnas någon uppståndelse till liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 15, 'Omedelbart därefter förde de fram den femte och misshandlade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 16, 'Men han såg på konungen och sade: »Eftersom du har makt bland människor, gör du, fastän du är dödlig, vad du vill. Mena dock icke att vårt folk är övergivet av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 17, 'Fortsätt du blott, så skall du få skåda hans stora makt, huru han skall plåga dig och dina efterkommande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 18, 'Efter honom förde de fram den sjätte, och när han höll på att dö, sade han: »Bedrag icke fåfängt dig själv. Ty det är genom vårt eget förvållande som vi måste lida detta, eftersom vi hava syndat mot vår Gud. Det är därför som dessa förundransvärda hemsökelser hava drabbat oss;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 19, 'men tro icke att du själv skall undgå ditt straff, du som har företagit dig att strida mot Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 20, 'Men i all synnerhet visade sig modern beundransvärd och förtjänt av ett gott eftermäle. Ty fastän hon under en enda dag fick se sju söner berövas livet, uthärdade hon det dock med modigt sinne, därför att hon hade sitt hopp till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 21, 'Var och en av dem uppmuntrade hon på fädernas tungomål, i det hon själv var uppfylld av ett ädelt tänkesätt och styrkte sitt kvinnliga hjärta genom manligt mod. Hon sade till dem: 22 »Jag vet icke på vad sätt I haven blivit till i mitt sköte; det är ju icke jag som har skänkt eder ande och liv eller i sin rätta ordning sammanfogat grundämnena i vars och ens kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 22, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 23, 'Så skall då ock förvisso världens skapare, han som har danat människan och frambragt alla varelser, så att de hava blivit till, i sin barmhärtighet en gång giva eder anden och livet tillbaka, så visst som I nu räknen eder själva ringa för hans lags skull.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 24, 'Antiokus trodde visserligen att hon föraktade honom, och misstänkte att hon förde smädligt tal. Men eftersom den yngste ännu återstod, sökte han icke endast övertala honom med vänliga ord, utan gav honom också på samma gång edlig försäkran om att han skulle göra honom rik och lycklig, så ock upptaga honom bland sina vänner och anförtro honom ämbeten, om han allenast ville övergiva sina fäders lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 25, 'Men då ynglingen icke alls aktade härpå, lät konungen kalla till sig modern och uppmanade henne att giva sin unge son ett råd som ledde till dennes räddning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 26, 'På hans enträgna uppmaningar åtog hon sig slutligen att söka övertala sin son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 27, 'Hon lutade sig nu fram mot honom, och i det hon drev gäck med den grymme tyrannen, talade hon på fädernas tungomål sålunda: »Min son, hav förbarmande med mig, som i nio månader har burit dig under mitt hjärta och i tre år har givit dig di, och som under trogen omvårdnad har fostrat dig och lett dig ända till den ålder du nu har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 28, 'Jag beder dig, mitt barn, lyft upp dina ögon och se på himmelen och jorden, och betrakta allt som finnes där, och betänk att Gud icke har gjort detta av något som fanns förut, och att människan bliver till på samma sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 29, 'Så frukta nu icke för denne bödel, utan visa dig värdig dina bröder, och lid villigt döden, på det att jag genom Guds barmhärtighet må få dig igen tillsammans med dina bröder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 30, 'Innan hon ännu hade slutat att tala, sade ynglingen: »Vad vanten I på? Jag vill icke hörsamma konungens bud, utan jag lyssnar till budet i den lag som genom Moses blev given åt våra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 31, 'Men du som har gjort hebreerna allt upptänkligt ont, du skall icke kunna undkomma Guds hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 32, 'Vi lida ju för våra synders skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 33, 'Men om än den levande Guden, vår Herre, till vår tuktan och fostran har vredgats på oss för en kort tid, så skall han dock åter bliva sina tjänare nådig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 34, 'Men du, ogudaktige, du som i skändlighet överträffar alla andra, förhävdig icke fåfängt, uppblåst av ovissa förhoppningar, då du nu har lyft din hand mot himmelens barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 35, 'Ännu har du dock icke undflytt den allsmäktige och allseende Gudens dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 36, 'Ty nu hava våra bröder, sedan de hava utstått ett kort lidande, efter Guds löfte fått dricka av evigt flödande liv; men du skall genom Guds dom få skörda det rättvisa straffet för ditt övermod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 37, 'Jag offrar nu, likasom mina bröder, liv och blod för våra fäders lag, i det jag anropar Gud att han inom kort ville bliva vårt folk nådig, men nödga dig att under plågor och kval öppet bekänna att han allena är Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 38, 'och beder att den Allsmäktiges vrede, som med rätta har kommit över hela vårt folk, må stanna vid mig och mina bröder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 39, 'Nu blev konungen upptänd av vrede, och i sin förbittring över hans gäckande tal förfor han ännu grymmare med honom än med de övriga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 40, 'Så skildes också han hädan i renhet och under full förtröstan på Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 41, 'Sist, efter sina söner, fick ock modern ända sitt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 42, 'Härmed må det vara nog berättat om de hedniska offermåltiderna och de övermåttan svåra våldsgärningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 1, 'Men Judas, som ock kallades Mackabeus, och hans anhängare smögo sig obemärkt in i byarna och uppmanade sina stamfränder att sluta sig till dem; och de upptogo bland sig dem som höllo fast vid judendomen och lyckades så att samla vid pass sex tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 2, 'Och de anropade Herren att han ville se till det av alla förtrampade folket och jämväl förbarma sig över templet, som hade blivit oskärat av ogudaktiga människor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 3, 'och att han likaledes ville hava misskund med den av förödelse hemsökta staden, som nu var nära att bliva jämnad med marken, och höra det rop som från allt det utgjutna blodet uppsteg till honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 4, 'så ock att han ville komma ihåg huru de oskyldiga små barnen orättfärdigt hade blivit dräpta, och huru man hade hädat hans namn, och låta sin avsky för dessa ogärningar bliva uppenbar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 5, 'Sedan Mackabeus så hade fått en här samlad, kunde hedningarna icke längre hålla stånd mot honom, eftersom Herrens vrede nu hade förbytts i misskund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 6, 'Han kom oförmodat tågande och brände städer och byar, och han satte sig i besittning av lämpliga platser och slog mycket stora fiendeskaror på flykten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 7, 'och för dylika anfall tog han vanligen nätterna till hjälp. Och ryktet om hans stora tapperhet spridde sig överallt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 8, 'När Filippus märkte att Judas på kort tid hade haft sådan framgång, och att han vann allt flera fördelar, skrev han till Ptolemeus, ståthållaren i Celesyrien och Fenicien, att denne skulle komma kunungens sak till hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 9, 'Ptolemeus utsåg då strax Nikanor, Patroklus\' son, en av konungens främsta vänner, och sände honom åstad, i spetsen för en här på icke mindre än tjugu tusen man, vilken var sammansatt av allahanda folkslag, på det att han skulle tillintetgöra hela det judiska folket. Och vid hans sida ställdes Gorgias, en härhövitsman, som var väl förfaren i krigiska värv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 10, 'Nikanor beslöt sig nu för att genom försäljning av de fångar som han hoppades att taga bland judarna skaffa konungen medel till hela den gärd på två tusen talenter, som denne hade att erlägga till romarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 11, 'Han sände därför strax bud till städerna vid havskusten och inbjöd invånarna att köpa upp judiska trälar, under löfte om att lämna nittio stycken för en talent, allt detta utan att ana det straff som i en snar framtid väntade honom från den Allsmäktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 12, 'När underrättelsen om att Nikanor var i antågande nådde Judas, meddelade han sitt folk att den fientliga hären befann sig i närheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 13, 'Då smögo sig de som voro modstulna, eller som icke satte sin lit till Guds rättfärdighet så småningom bort och begåvo sig därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 14, 'Men de övriga sålde allt vad de ännu hade kvar, och bådo tillika till Herren att han ville frälsa dem som den gudlöse Nikanor hade sålt, redan innan de hade drabbat samman,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 15, 'och att han ville göra detta, om icke för deras skull, så dock för de förbunds skull som han hade ingått med deras fäder, och därför att de hade fått bliva uppkallade efter hans höga och härliga namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 16, 'Mackabeus samlade nu sitt folk, som uppgick till sex tusen man, och förmanade dem att icke låta skrämma sig av fienderna eller frukta för den stora mängden av hedningar som tvärt emot all rätt kommo tågande mot dem, utan att i stället med ädelt mod gå till kampen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 17, 'Han förmanade dem att därvid ställa för sina ögon det våld som dessa brottsligt hade övat mot den heliga platsen, så ock den skymfliga och grymma behandling som de hade låtit staden undergå, och därtill huru deras fäderneärvda ordning hade blivit avskaffad. 18 »Ty», sade han, »de förlita sig på vapen och djärva dåd, men vi förlita oss på den allsmäktige Guden, som med en enda vink förmår slå ned icke allenast dem som rycka fram mot oss, utan ock hela världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 18, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 19, 'Och han förtäljde ytterligare för dem om de tillfällen då Gud hade kommit med sin hjälp i fädernas dagar, både på Sennakerims tid, då när de ett hundra åttiofem tusen omkommo,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 20, 'och under den strid som i Babylonien utkämpades mot galaterna. Då hade de, fastän de tillhopa utgjorde allenast åtta tusen man, jämte fyra tusen macedonier dragit ut i striden; och de åtta tusen hade då, medan macedonierna intet kunde uträtta, nedgjort de ett hundra tjugu tusen, tack vare det bistånd som beskärdes dem från himmelen, och vunnit stort byte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 21, 'Sedan han genom dessa ord hade ingjutit tillförsikt hos dem och gjort dem villiga att dö till försvar för lagen och fäderneslandet, indelade han sin här i fyra avdelningar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 22, 'och satte sina bröder Simon, Josef och Jonatan i spetsen för var sin skara, så att var och en fick befälet över ett tusen fem hundra man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 23, 'Tillika bjöd han Eleasar att bland dem föreläsa den heliga boken och gav sedan denna lösen: »Med Guds hjälp.» Därefter satte han sig själv i spetsen för den första avdelningen och gick till anfall mot Nikanor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 24, 'Och den Allsmäktige kom dem till hjälp i striden, så att de dräpte över nio tusen fiender och svårt sårade och lemlästade största delen av Nikanors här och tvingade alla de övriga att gripa till flykten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 25, 'Och de togo penningarna ifrån dem som hade kommit tillstädes för att köpa dem själva; och de förföljde fienderna ett långt stycke, till dess den knappa tiden nödgade dem att vända om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 26, 'Ty det var dagen före sabbaten, och därför ville de icke längre fortfara med att sätta efter dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 27, 'Men de samlade tillhopa fiendernas vapen och klädde av de fallna fienderna deras rustningar. Sedan firade de sabbaten och lovade och tackade storligen Herren, som hade bevarat dem intill den dagen och nu hade begynt att visa dem barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 28, 'Men efter sabbaten utskiftade de av bytet åt dem som hade lidit någon skada och åt änkorna och de faderlösa; återstoden fördelade de mellan sig själva och sina barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 29, 'Och när de hade fullgjort detta, höllo de gemensamt bön och bådo Herren, den barmhärtige, att han åter ville av allt hjärta bliva sina tjänare nådig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 30, 'När de senare stötte samman med Timoteus\' och Backides\' folk, nedgjorde de över tjugu tusen man av dem. Och de satte sig i besittning av flera mycket högt belägna fästningar; och de utskiftade rikligt byte. Därvid gåvo de åt dem som hade lidit någon skada och åt de faderlösa och änkorna, och därtill åt åldringarna, lika mycket som de själva behöllo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 31, 'Och sedan de hade samlat tillhopa fiendernas vapen, lade de alltsammans omsorgsfullt i förvar på därför lämpliga platser; men återstoden av bytet förde de till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 32, 'Och de avlivade Fylarkes, som hörde till Timoteus\' närmaste män, en övermåttan ogudaktig människa, som hade tillfogat judarna mycket lidande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 33, 'Och när de höllo segerfest hemma i Jerusalem, läto de dem som hade bränt upp de heliga portarna brinna inne, och bland dem Kallistenes, som hade tagit sin tillflykt till ett litet hus. Så fingo dessa den välförtjänta lönen för sin gudlöshet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 34, 'Men den store uslingen Nikanor, som hade lockat de tusen uppköparna att komma tillstädes för att köpa judar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 35, 'han blev, tack vare Herrens hjälp, förödmjukad av dem som i hans ögon voro ringare än alla andra; han måste nu lägga av sin lysande skrud och utan något följe, lik en rymmare, taga vägen tvärs igenom landet till Antiokia, övermåttan olycklig över sin krigshärs undergång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 36, 'Och han som hade åtagit sig att skaffa tillhopa allt som behövdes för att betala gärden till romarna, genom att försälja de fångar som togos i Jerusalem, han måste nu förtälja att judarna hade Gud till sin förkämpe, och att de av detta skäl voro oåtkomliga, därför att de nämligen följde den lag som han hade stadgat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 1, 'Vid samma tid hade Antiokus med nesa måst bryta upp från Persiens landsändar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 2, 'Han hade nämligen dragit in i en stad som hette Persepolis, i akt och mening att plundra templet där och sedan behålla staden i sitt våld. Till följd härav satte sig nu folkmassorna i rörelse och sökte sin hjälp i vapnen. Och Antiokus blev av invånarna jagad på flykten och måste anträda ett skymfligt återtåg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 3, 'Då han nu befann sig i närheten av Ekbatana, nådde honom underrättelsen om vad som hade hänt Nikanor, såsom ock Timoteus och dennes folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 4, 'Då blev han upptänd av förbittring och tänkte att låta judarna få umgälla jämväl det onda han hade rönt av dem som hade drivit honom på flykten. Han bjöd därför sin körsven att köra på, utan uppehåll, ända till dess de hade kommit fram; och dock svävade redan domen från himmelen över hans huvud. Ty i sitt övermod sade han så: »När jag kommer till Jerusalem, skall jag göra det till en begravningsplats för judarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 5, 'Men Herren, som ser till allt, Israels Gud, slog honom med en obotlig, osynlig sjukdom. Just då han hade talat till slut, överfölls han av olidliga kval i inälvorna och svåra plågor i sitt inre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 6, 'Och det var alldeles rättvist, eftersom han hade plågat andra med mångahanda gruvliga lidanden i deras innersta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 7, 'Men han lät ingalunda sitt trots fara, utan blev tvärtom ännu mer uppfylld av sitt övermod; ja, han andades eld och lågor i sin förbittring mot judarna. Och han befallde att man ytterligare skulle påskynda färden. Men då hände sig att han störtade ned från vagnen, där den rusade fram med ilande fart; och han skadade sig i fallet så svårt att alla lemmarna i hans kropp blevo sönderbråkade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 8, 'Och han som nyss i mer än mänskligt högmod tyckte sig kunna befalla över havets vågor, och som tilltrodde sig att kunna väga de höga bergen på vågskål, han fick nu, sedan han så hade blivit slagen till marken låta bära sig på en bår och lämnade härmed ett för alla tydligt bevis på Guds makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 9, 'Ja, det gick så långt att maskar krälade fram ur den gudlöses kropp, och att köttet under plågor och kval föll sönder, medan han ännu levde; och hela lägret besvärades svårt av stanken från hans ruttnande kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 10, 'Och den man som kort förut hade inbillat sig att nå upp till himmel ens stjärnor, honom förmådde nu ingen bära för den olidligt svåra stankens skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 11, 'Då han nu låg där alldeles nedbruten, begynte han verkligen att låta det mesta av sitt övermod fara och att komma till besinning genom Guds straff, när han för vart ögonblick allt värre ansattes av kvalen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 12, 'Och då han icke ens kunde uthärda stanken från sin egen kropp, sade han: »Det är rätt och tillbörligt att ödmjuka sig under Gud och att icke göra sig lik Gud i sina tankar, då man är dödlig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 13, 'Och han, den skändlige, gjorde löften åt Herren, som icke ni er skulle förbarma sig över honom. Han lovade');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 14, 'att förklara den heliga staden för fri, den stad dit han nu med all hast styrde sin färd, i avsikt att jämna den med marken och göra den till en begravningsplats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 15, 'Och judarna, som han hade beslutit att icke en gång bevärdiga med en grav, utan tillika med deras späda barn låta kasta ut såsom föda åt rovfåglar och vilddjur, dem ville han allasammans göra likställda med atenarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 16, 'Det heliga templet, som han förut hade plundrat, det ville han nu pryda med de skönaste helgedomsskänker, och alla de heliga kärlen ville han mångdubbelt ersätta, och de utgifter som voro förbundna med offren ville han betala av sina egna inkomster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 17, 'Därtill ville han också själv bliva jude och begiva sig åstad till alla av människor bebodda trakter för att förkunna Guds makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 18, 'Men när trots allt plågorna icke ville upphöra, då nu Guds dom rättvist hade drabbat honom, uppgav han allt hopp för egen del, men lät till judarna skriva nedanstående brev, avfattat såsom en böneskrift och av följande lydelse:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 19, '»Sina trogna judiska undersåtar sänder Antiokus, konung och krigsherre, de bästa hälsningar och tillönskar dem all välgång och lycka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 20, 'Om I och edra barn befinnen eder väl och det går eder efter önskan i edra angelägenheter, så tackar jag Gud av allt mitt hjärta, i det jag sätter mitt hopp till himmelen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 21, 'för egen del är jag däremot icke vid god hälsa. Den heder och tillgivenhet som I haven bevisat mig minnes jag med all välvilja. Då jag nu på återvägen från Persiens landsändar har råkat i en farlig sjukdom, har jag ansett det vara nödigt att sörja för allas eder gemensamma trygghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 22, 'Väl har jag icke förlorat allt hopp för egen del; tvärtom har jag gott hopp om att lyckligt kunna genomgå sjukdomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 23, 'Men då jag besinnar att också min fader, när han med sin här drog till de övre landsändarna, utnämnde sin efterträdare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 24, 'för att, om något oförutsett inträffade eller någon allvarsam underrättelse inginge, de hemmavarande skulle veta vem styrelsen hade blivit lämnad åt och så slippa att gripas av oro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 25, 'och då jag därtill betänker huru de kringboende furstarna och rikets grannar alltid akta på lägligt tillfälle och vänta på huru det skall gå, har jag till konung utnämnt min son Antiokus. Honom har jag ock ofta förut, vid mina färder till de övre provinserna, anförtrott och anbefallt åt de flesta av eder. Och till honom själv har jag skrivit ett brev, som här bifogas i avskrift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 26, 'Jag uppmanar och beder eder alltså att I allasammans, i hågkomst av de välgärningar som I, både i det allmänna och i det enskilda, haven fått röna, också för min son bibehållen den tillgivenhet som I haven för mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 27, 'Jag är nämligen viss om att han på ett milt och människovänligt sätt skall efterfölja mina grundsatser och så komma väl överens med eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 28, 'Så fick nu denne mördare och hädare själv utstå de svåraste lidanden, alldeles såsom han hade behandlat andra, och måste sluta sitt liv genom den ömkligaste död bland bergen i ett främmande land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 29, 'Hans döda kropp blev sedan hemförd av Filippus, hans fosterbroder. Men av fruktan för Antiokus\' son begav sig denne sedan åstad till Ptolemeus Filometor i Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 1, 'Men Mackabeus och hans folk togo, under Herrens ledning, helgedomen och staden åter i besittning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 2, 'De altaren som hedningarna hade byggt upp på torget revo de ned, likaledes ock deras helgedomar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 3, 'Och de renade templet och uppförde ett nytt altare. Därefter skaffade de sig eld genom att slå gnistor ur stenar och fram-buro så, efter två års avbrott, slaktoffer; och de redde till rökelse och ställde i ordning lamporna och lade fram skådebröden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 4, 'Sedan de hade gjort så, kastade de sig ned på marken och bådo till Herren att de icke vidare måtte råka i sådan olycka, utan att om de ock framdeles syndade, han då ville tukta dem med mildhet och icke mer giva dem till pris åt hädiska och grymma hedningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 5, 'Och det hände sig så, att tempelreningen ägde rum just på samma dag som templet hade blivit oskärat av hedningarna, nämligen på den tjugufemte dagen i samma månad, månaden Kisleu.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 6, 'Och under glädje höllo de i åtta dagar en högtid lik lövhyddofesten, i det att de tänkte på huru de kort förut under lövhyddohögtiden hade uppehållit sig bland bergen och i klipphålorna likasom de vilda djuren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 7, 'Därför togo de nu lövprydda stavar och gröna grenar i sina händer, tillika med palmkvistar, och stämde upp lovsånger till honom som hade givit dem den framgången att de nu fingo rena hans heliga plats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 8, 'Och de stadgade genom allmänt påbud och beslut, såsom en lag för hela det judiska folket, att man årligen skulle fira dessa dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 9, 'Ett sådant slut fick Antiokus med tillnamnet Epifanes. 10} Nu skola vi berätta vad som tilldrog sig under Antiokus Eupator, den ogudaktige Antiokus\' son, och vilja därvid giva en kort sammanfattning av de ihållande svåra krigshändelserna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 10, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 11, 'Sedan denne hade övertagit konungamakten, utnämnde han till riksföreståndare en viss Lysias, som tillika skulle vara högste befälhavare i Celesyrien och Fenicien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 12, 'Ty Ptolemeus, som kallades Makron, vilken på ett föredömligt sätt hade låtit en rättvis behandling vederfaras judarna, eftersom de förut hade fått lida sådan orätt, och som hade försökt att komma till fredlig uppgörelse med dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 13, 'hade på grund härav blivit anklagad hos Eupator av dennes vänner. Han hade ock överallt fått heta förrädare, därför att han, sedan han av Filometor hade blivit betrodd med styrelsen över Cypern, hade lämnat dennes tjänst och gått över till Antiokus Epifanes. Och då han nu ingalunda hade vunnit någon ära genom förvaltningen av sitt ämbete, hade han tagit in gift och så själv gjort ände på sitt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 14, 'Men Gorgias, som nu fick det närmaste befälet i dessa trakter, hade främmande krigsfolk i sin tjänst och höll hela tiden kriget mot judarna vid makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 15, 'På samma gång blevo judarna också svårt ansatta av iduméerna, vilka voro i besittning av lämpligt belägna fästningar. Genom att bland sig upptaga dem som hade måst fly ifrån Jerusalem sökte dessa nu att hålla kriget vid makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 16, 'Men Mackabeus och hans folk förrättade bön och bådo Gud att komma dem till hjälp i striden. Därefter bröto de fram mot iduméernas fästningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 17, 'De angrepo dessa med all kraft och satte sig så i besittning av platserna; de drevo undan alla som stridde på muren och dräpte alla som kommo i deras väg. Så nedgjorde de ända till tjugu tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 18, 'Men icke mindre än nio tusen togo sin tillflykt till två torn, som voro mycket starka och voro försedda med allt vad som behövdes för att uthärda en belägring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 19, 'Mackabeus lämnade då kvar Simon och Josef, tillika med Sackeus och hans folk, som voro tillräckligt många för att kunna belägra tornen, och begav sig själv därifrån till platser där hans egen närvaro var av nöden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 20, 'Men Simons närmaste män läto av vinningslystnad muta sig av några bland dem som befunno sig i tornen; och sedan de hade fått sjuttio tusen drakmer, läto de några slippa ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 21, 'Men när det blev berättat för Mackabeus om vad som hade hänt, församlade han folkets anförare och anklagade de andra för att hava sålt sina bröder för penningar, genom att släppa lös fienderna mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 22, 'Då dessa således hade befunnits vara förrädare, lät han avrätta dem; därefter intog han strax de båda tornen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 23, 'Och eftersom han hade framgång i allt vad han företog sig med väpnad hand, förgjorde han i de båda fästningarna mer än tjugu tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 24, 'Men Timoteus, samme man som tidigare hade blivit slagen av judarna, församlade en ansenlig mängd främmande krigsfolk och samlade tillhopa asiatiska ryttare i stort antal. Han kom sedan tågande för att med vapenmakt intaga Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 25, 'Då han nu närmade sig, strödde Mackabeus och hans folk stoft på sina huvuden och svepte säcktyg om sina länder för att anropa Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 26, 'Och de föllo ned framför altaret, på fotsteget, och bådo honom att han ville vara dem nådig och »bliva en fiende till deras fiender och en motståndare till deras motståndare», såsom ju ock lagen giver till känna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 27, 'Och när de hade slutat sin bön, grepo de till vapen och ryckte ett långt stycke framåt ifrån staden. Och sedan de hade kommit nära fienderna, stannade de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 28, 'Men strax därefter, när solen gick upp, drabbade man samman från ömse sidor. På den ena sidan hade man därvid såsom underpant på framgång och seger, förutom sin tapperhet, också sin tillförsikt till Herren, medan man på den andra tog den vilda stridsivern till ledare i kampen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 29, 'Och när striden var som häftigast, uppenbarade sig från himmelen för fienderna fem strålande män på guldbetslade hästar. Och de satte sig i spetsen för judarna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 30, 'och togo Mackabeus mellan sig och skyddade honom med sina vapen och bevarade honom osårad; mot fienderna åter avsköto de pilar och slungade de ljungeldar. Därigenom blevo dessa bländade och förvirrade, och de blevo då nedhuggna, slagna av skräck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 31, 'Tjugu tusen fem hundra man av fotfolket blevo dödade, så ock sex hundra ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 32, 'Och Timoteus själv flydde till en fästning som hette Gasara, en mycket starkt befäst plats, där Kereas förde befälet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 33, 'Men Mackabeus och hans folk belägrade med friskt mod fästningen i tjugufyra dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 34, 'De inneslutna förlitade sig dock på platsens fasthet och uttalade övermåttan svåra hädelser och foro ut i otillbörliga ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 35, 'Men när den tjugufemte dagen bröt in, gjorde några unga män bland Mackabeus\' folk, upptända av vrede över hädelserna, ett anfall mot muren och höggo med manligt mod och i vilt raseri ned envar som kom i deras väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 36, 'Andra ryckte likaledes, med en kringgående rörelse, fram mot de inneslutna och satte eld på tornen; de tände ock på bål och brände dessa gudsförsmädare levande. Andra åter sprängde portarna och släppte in den övriga hären och intogo så staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 37, 'Och Timoteus, som hade gömt sig i en brunn, dräpte de, så ock Kereas, hans broder, och Apollofanes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 38, 'Sedan de hade utfört allt detta, prisade de Herren med lovsånger och tacksägelser, honom som bevisade Israel så stora välgärningar och gav dem seger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 1, 'Men Lysias, som var konungens förmyndare och frände och tillika riksföreståndare, kände stor förtrytelse över vad som hade hänt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 2, 'Han samlade fördenskull, en helt kort tid därefter, omkring åttio tusen man fotfolk och alla sina ryttare och tågade mot judarna. Han tänkte därvid att göra Jerusalem till en boningsplats för greker');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 3, 'och att pålägga helgedomen skatt, likasom han annorstädes hade gjort med de hedniska helgedomarna, och att utbjuda översteprästämbetet till salu för vart år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 4, 'Men han betänkte därvid icke huru stor Guds makt var, utan var uppblåst över sina tiotusental av fotfolk och sina tusental av ryttare och sina åttio elefanter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 5, 'Han bröt alltså in i Judeen och ryckte fram mot Betsura, en befäst plats på omkring fem mils avstånd från Jerusalem. Och han höll sedan denna plats hårt innesluten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 6, 'Men när Mackabeus och hans folk fingo underrättelse om att han höll på att belägra fästningarna, bönföllo de Herren under veklagan och tårar, tillika med hela menigheten, att han ville sända en god ängel till Israels räddning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 7, 'Mackabeus själv grep sedan, först av alla, sina vapen, och han uppmuntrade de andra att tillsammans med honom trotsa faran och undsätta sina bröder. Och så bröto de frimodigt upp i samlad skara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 8, 'Och medan de ännu voro kvar där, nära Jerusalem, visade sig i spetsen för dem en ryttare i vita kläder, som svingade gyllene vapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 9, 'Då prisade de, alla tillhopa, den barmhärtige Guden och blevo så styrkta i sina hjärtan, att de nu voro redo att angripa icke allenast människor, utan också de grymmaste vilddjur och murar av järn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 10, 'Så tågade de då framåt, ordnåde till strid, ledda av honom som Herren i sin barmhärtighet hade sänt dem från himmelen till att vara deras hjälpare i striden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 11, 'Och såsom lejon störtade de sig över fienderna och nedgjorde elva tusen man av fotfolket och ett tusen sex hundra ryttare; alla de övriga tvingade de att fly.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 12, 'De flesta av dessa lyckades endast svårt sårade och utan vapen rädda sig undan. Jämväl Lysias själv fann sin räddning i en neslig flykt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 13, 'Men Lysias var en mycket klok man. Då han nu vid sig själv tänkte på det nederlag som han hade lidit och förstod att hebreerna voro oövervinnliga, eftersom de hade den mäktige Guden till hjälpare i striden, sände han budbärare till dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 14, 'för att söka övertala dem till att ingå förlikning med honom på i allo billiga villkor, och lovade att han också skulle söka övertala konungen och nödga honom att bliva vän med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 15, 'Och Mackabeus gick in på allt som Lysias föreslog, av omtanke för det allmänna bästa; alla de skriftliga framställningar som Mackabeus hade gjort till Lysias angående judarna blevo nämligen beviljade av konungen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 16, 'Det brev som Lysias hade skrivit till judarna var av följande lydelse: »Lysias hälsar det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 17, 'Edra sändebud, Johannes och Absalom, hava lämnat fram edert här i avskrift bifogade svar och begärt besked angående de däri framställda önskningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 18, 'Jag har därför meddelat konungen allt som behövde underställas honom själv, och det som var möjligt att antaga har han beviljat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 19, 'Om I alltså stån fast vid eder välvilliga hållning mot styrelsen, så skall jag söka att också för framtiden främja edert bästa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 20, 'Angående de särskilda punkterna har jag uppdragit åt dessa män, jämte mina egna sändebud, att vidare förhandla med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 21, 'Faren väl. År 148, den tjugufjärde dagen i månaden Dioskurus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 22, 'Konungens brev åter lydde så: »Konung Antiokus hälsar sin broder Lysias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 23, 'Sedan nu vår fader har blivit försatt bland gudarna, är det vår vilja att våra undersåtar må få ostört ägna sig åt vården av sina angelägenheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 24, 'Men vi hava fått höra att judarna icke vilja samtycka till att övergå till grekiska seder, såsom vår fader påbjöd, utan att de föredraga att inrätta sig efter sina egna vanor och på grund härav begära tillstånd att få följa sina stadgar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 25, 'Alldenstund vi alltså önska att jämväl detta folk må få vara i ostörd ro, så förordna vi härmed att deras helgedom skall återställas till dem, och att de skola få leva efter sina fäderneärvda sedvänjor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 26, 'Du gör således väl i att sända bud till dem och giva dem bindande försäkringar härom, för att de så, när de få lära känna våra grundsatser, må vara vid gott mod och med glatt sinne gripa sig an skötseln av sina angelägenheter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 27, 'Och konungens brev till det judiska folket hade följande lydelse: »Konung Antiokus hälsar judarnas Stora råd, så ock övriga judar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 28, 'Det fägnar oss, om I befinnen eder väl; vi själva äro ock vid god hälsa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 29, 'Menelaus har givit till känna för oss att I viljen vända tillbaka hem och ägna eder åt edra värv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 30, 'Alla dem som begiva sig hem till sitt, före den trettionde dagen i månaden Xantikus, tillförsäkras härmed full trygghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 31, 'Därjämte beviljas judarna oinskränkt frihet till att följa sina egna spisordningar och sina egna lagar, likasom tillförne; och ingen av dem skall på något sätt bliva antastad för några av dem begångna förseelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 32, 'Jag sänder nu ock här Menelaus för att giva eder lugnande försäkringar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 33, 'Faren väl. År 148, den femtonde dagen i månaden Xantikus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 34, 'Jämväl romarna sände ett brev till dem, av följande innehåll: »Kvintus Memmius och Titus Manius, sändebud från romarna, hälsa det judiska folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 35, 'I det som Lysias, konungens frände, har beviljat eder äro också vi ense med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 36, 'Men vad angår de frågor som han har ansett böra hänskjutas till konungen, så överläggen härom, och sänden sedan strax ett bud till oss, för att vi må kunna uttala vår mening, såsom det tillkommer oss. Vi äro nu nämligen på väg till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 37, 'Skynden eder alltså att sända till oss några män, för att också vi å vår sida må få veta av vilken mening I ären.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 38, 'Leven väl. År 148, den femtonde dagen i månaden Xantikus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 1, 'Sedan nu detta fördrag hade blivit ingånget, vände Lysias tillbaka till konungen. Och judarna ägnade sig åt sitt åkerbruk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 2, 'Men några av befälhavarna i dessa trakter, nämligen Timoteus och Apollonius, Genneus\' son, vidare Hieronymus och Demofon och därtill Nikanor, befälhavaren på Cypern, lämnade dem icke i fred och tillstadde dem icke att leva i lugn och ro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 3, 'Och invånarna i Joppe begingo följande illdåd. De inbjödo de judar som bodde bland dem att tillika med kvinnor och barn stiga ned i båtar, som de höllo i beredskap, likasom om de icke hade något ont i sinnet mot dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 4, 'och som om de handlade efter allmänt beslut av staden. Men när dessa antogo inbjudningen, i tanke att de andra ville visa sitt vänliga sinnelag, och att de icke förenade något misstänkt, förde man dem ut till havs och dränkte dem, till ett antal av icke mindre än två hundra personer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 5, 'När Judas fick underrättelse om den grymhet som hade förövats mot hans landsmän, bådade han upp sitt manskap');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 6, 'och åkallade Gud, den rättfärdige domaren, och drog därefter ut mot sina bröders mördare. Han satte om natten eld på hamnen och brände upp båtarna och nedgjorde dem som hade tagit sin tillflykt dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 7, 'Men eftersom själva staden var stängd, bröt han upp därifrån, i avsikt att senare komma tillbaka och i grund förstöra hela staden Joppe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 8, 'Men när han fick underrättelse om att man också i Jamnia ämnade gå till väga på samma sätt mot de judar som voro bosatta där,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 9, 'angrep han jämväl denna stad om natten och antände hamnen tillika med flottan, så att eldskenet syntes ända till Jerusalem, fastän avståndet dit var två hundra fyrtio stadier.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 10, 'Därifrån drogo de åstad mot Timoteus. När de nu hade hunnit nio stadier, blevo de angripna av araber till ett antal av icke mindre än fem tusen man till fots och fem hundra till häst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 11, 'Då uppstod en häftig strid. Judas och hans folk hade genom Guds hjälp framgång i striden, men herdefolkets skaror lågo under. Dessa bådo då Judas att ingå förlikning med dem och lovade därvid att både lämna boskap och i övrigt bistå honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 12, 'Och eftersom Judas höll före att de verkligen kunde vara honom till gagn i många stycken, gick han in på att hålla fred med dem; och sedan de hade mottagit försäkran härom, drogo de åter bort till sina tält.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 13, 'Han angrep också en stad vid namn Kaspin, vilken var väl skyddad av jordvallar och omgiven av murar. Och den var bebodd av allahanda hedningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 14, 'Men de som befunno sig därinne litade på murarnas fasthet och sina förråd av livsmedel och uppträdde med stor fräckhet mot Judas och hans folk. De smädade dem och foro därtill ut i hädelser och uttalade otillbörliga ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 15, 'Men Judas och hans folk åkallade den mäktige härskaren över hela världen, honom som på Josuas tid utan murbräckor och andra konstmässiga stormverktyg hade störtat omkull Jerikos murar; sedan stormade de i raseri fram mot muren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 16, 'Så intogo de nu staden genom Guds vilja; och de anställde ett obeskrivligt blodbad, så att sjön som låg därinvid och var två stadier bred syntes fylld av det blod som hade utgjutits däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 17, 'Sedan lämnade de denna plats och tågade sju hundra femtio stadiers väg och kommo så fram till Karax, där de judar som kallas tubianer äro bosatta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 18, 'Timoteus själv träffade de icke på i dessa trakter, ty han hade brutit upp därifrån med oförrättat ärende; men han hade på en viss plats lämnat kvar en besättning, som var mycket stark.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 19, 'Dositeus och Sosipater, två bland anförarna i Mackabeus\' här, ryckte då ut och nedgjorde dem som Timoteus hade lämnat kvar i fästningen, över tio tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 20, 'Men Mackabeus ordnade sin här i olika avdelningar och tillsatte anförare för dessa avdelningar. Sedan bröt han upp mot Timoteus, som under sitt befäl hade en här på ett hundra tjugu tusen man fotfolk och två tusen fem hundra ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 21, 'När Timoteus fick underrättelse om att Judas var i antågande, sände han i förväg bort kvinnor och barn och den övriga trossen till en plats som hette Karnion; den var nämligen svår att innesluta och svårtillgänglig, eftersom endast trånga pass ledde ditupp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 22, 'Men så snart Judas\' första avdelning blev synlig, grepos fienderna av förskräckelse; och de uppfylldes av fruktan, därför att den Allseende uppenbarade sin makt mot dem. De togo till flykten och lupo den ene hit och den andre dit; så blevo många bland dem sårade av sina egna och genomborrade av deras svärdsspetsar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 23, 'Men Judas satte efter dem med all iver, och han högg ned de uslingarna och förgjorde vid pass trettio tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 24, 'Och Timoteus själv föll i händerna på Dositeus\' och Sosipaters folk. Under många förespeglingar bad han nu att de skulle släppa honom med livet, därför att han hade fäder till många och bröder till andra i sitt våld, och dessa eljest icke skulle komma att skonas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 25, 'När han då med många ord högtidligen hade förbundit sig till att återställa dessa oskadda, gåvo de honom lös, för att så rädda sina bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 26, 'Därefter drog Judas ut mot Karnion och Atergatis\' tempel och dräpte tjugufem tusen människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 27, 'Sedan dessa hade blivit slagna och nedgjorda, drog han med sin här åstad jämväl mot Efron, en fast stad, där Lysias bodde, så ock en stor mängd människor av allahanda folk. Och kraftigt ungt manskap, som stod uppställt framtill på murarna, gjorde tappert motstånd; där funnos ock stora förråd av krigsverktyg och skjutredskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 28, 'Men de åkallade den Allsmäktige, honom som med kraft krossar fiendernas härsmakt, och bemäktigade sig så staden och nedgjorde vid pass tjugufem tusen av dem som befunno sig därinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 29, 'Sedan bröto de upp därifrån och ryckte mot Skytopolis, som ligger sex hundra stadier från Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 30, 'Men då de judar som voro bosatta där avlade vittnesbörd om den välvilja och det vänliga bemötande i olyckans tider, som invånarna i Skytopolis hade visat dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 31, 'betygade de dem sin tacksamhet och uppmanade dem därjämte att också för framtiden vara välvilliga mot deras folk; och sedan vände de tillbaka till Jerusalem, eftersom veckohögtiden var nära för handen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 32, 'Efter denna högtid, som ock kallas pingst, ryckte de mot Gorgias, ståthållaren i Idumeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 33, 'Och han drog ut med tre tusen man fotfolk och fyra hundra ryttare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 34, 'Då de nu drabbade samman, hände sig att några få bland judarna stupade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 35, 'Men en viss Dositeus, en av Bacenors folk, som var en skicklig ryttare och en stark man, hade fattat tag i Gorgias och drog honom nu våldsamt med sig, under det att han höll fast i hans mantel. Han ville nämligen få den nidingen levande i sitt våld. Då sprängde en tracisk ryttare fram mot honom och högg av honom armen. Och så kom Gorgias undan till Marisa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 36, 'Men när Esdris\' folk var utmattat, eftersom de hade kämpat mycket länge, anropade Judas Herren att han ville uppenbara sig såsom deras hjälpare och ledare i striden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 37, 'och upphävde stridsropet på sina fäders tungomål och stämde tillika upp lovsånger; så stormade han oförmodat fram mot Gorgias och hans folk och drev dem på flykten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 38, 'Judas drog sig sedan med sin här tillbaka till staden Odollam. Och då nu den sjunde dagen inträffade, helgade de sig enligt övlig sed och stannade där över sabbaten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 39, 'Men följande dag begåvo sig Judas\' män åstad, eftersom saken nu icke längre kunde uppskjutas, för att hämta upp de fallnas döda kroppar och åter förena dem med deras stamförvanter i fädernas gravar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 40, 'Då träffade de på hos envar av de döda, under livklädnaden, amuletter som avbildade Jamnias avgudar, sådana som lagen förbjuder judarna att hava; och då blev det tydligt för alla att det var därför som dessa hade fallit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 41, 'Alla prisade nu vad Herren, den rättfärdige domaren, här hade gjort, han som låter det fördolda bliva uppenbart.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 42, 'Därefter vände de sig till åkallan och bådo att den begångna synden helt måtte bliva utplånad. Och den ädle Judas förmanade manskapet att själva taga sig till vara för att synda, då de nu med egna ögon sågo vad som hade blivit följden av de fallnas synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 43, 'Och han gjorde en insamling bland sina män och skaffade så tillhopa vid pass två tusen drakmer silver. Dessa sände han till Jerusalem, för att man skulle frambära ett syndoffer. Häri handlade han mycket rätt och ädelt. Han tänkte nämligen på uppståndelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 44, 'Ty om han icke hade väntat att de fallna skulle uppstå, så hade det varit överflödigt och dåraktigt att bedja för sådana som voro döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 45, 'Vidare besinnade han vilken härlig nådelön som är förvarad åt dem som hava avsomnat i fromhet; och detta var en helig och from tanke. På grund härav lät han anställa det nämnda försoningsoffret för dem som voro döda, för att de så skulle bliva fria ifrån sin synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 1, 'År 149 nådde den underrättelsen Judas och hans anhängare, att Antiokus Eupator med stor härsmakt kom tågande mot Judeen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 2, 'åtföljd av sin förmyndare Lysias, som ock var riksföreståndare; vardera stod i spetsen för en grekisk här på ett hundra tio tusen man fotfolk, fem tusen tre hundra ryttare, tjugutvå elefanter och tre hundra lievagnar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 3, 'Till dem slöt sig ock Menelaus; och han uppmuntrade med mycken förställning Antiokus till kriget, dock ingalunda för att främja sitt fäderneslands väl, utan i tanke att han nu åter skulle kunna få makten sig anförtrodd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 4, 'Men han som är konungarnas konung uppväckte Antiokus\' vrede mot den uslingen; och när Lysias visade att denne bar skulden till alla olyckorna, gav konungen befallning om att föra honom till Berea och avliva honom på det sätt som är brukligt på denna plats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 5, 'Där finnes nämligen ett femtio alnar högt torn, som är uppfyllt med glödande aska; detta har en vridbar inrättning, som på alla sidor stupar rätt ned i askan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 6, 'Där bliver var och en som har gjort sig skyldig till tempelrån eller också begått något annat övermåttan svårt brott nedstörtad och så bragt om livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 7, 'En sådan död måste nu den ogudaktige Menelaus lida, utan att ens få komma i jorden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 8, 'och detta var alldeles rättvist. Ty eftersom han hade begått så många synder mot altaret, vars eld var helig, och med den dess aska, därför fick han sin död i aska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 9, 'Men konungen kom nu tågande, förgrymmad i sitt sinne, i avsikt att låta judarna få känna på det värsta av vad som hade vederfarits dem under hans faders tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 10, 'När Judas fick underrättelse härom, uppmanade han folket att dag och natt anropa Herren att han nu, om någonsin, ville komma dem till hjälp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 11, 'nu då de voro i fara att bliva berövade sin lag, sitt fädernesland och sitt heliga tempel, och icke tillstädja att folket, som nyss hade fått något litet andrum, blev givet i de hädiska hedningarnas våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 12, 'Sedan alla endräktigt hade gjort så och i tre dagar utan avbrott hade åkallat Herren, den barmhärtige, under gråt och fasta och knäfall, talade Judas uppmuntrande ord till dem och befallde dem att hålla sig redo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 13, 'När han sedan hade haft en enskild sammankomst med de äldste, beslöt han att de skulle draga ut och med Guds hjälp låta det komma till ett avgörande, förrän konungens krigshär hade infallit i Judeen och satt sig i besittning av staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 14, 'Och i det han så överlämnade utgången åt honom som är världens skapare, uppmuntrade han sitt folk att med ädelt mod kämpa intill döden för lagen och helgedomen, för staden och fäderneslandet och samhällsordningen. Därefter slog han upp sitt läger i närheten av Modein.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 15, 'Och sedan han hade givit sitt folk denna lösen: »Gud giver segern», gjorde han med en utvald skara tappra unga män om natten ett anfall på konungens högkvarter; därvid nedgjorde han vid pass två tusen man i lägret och fällde den förnämsta av elefanterna, tillika med alla dem som befunno sig i tornet på dess rygg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 16, 'Och till slut uppfyllde de lägret med skräck och förvirring och drogo sin väg såsom segrare, först när dagen begynte att gry.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 17, 'Och allt detta hade skett tack vare Herrens beskärm, genom vilket han blev hulpen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 18, 'Sedan konungen nu hade fått pröva på judarnas djärva mod, försökte han att med listiga medel bemäktiga sig de fasta platserna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 19, 'och ryckte så mot Betsura, en stark judisk fästning. Han drevs tillbaka; han gjorde då ett nytt anfall, men blev besegrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 20, 'Men Judas tillförde de inneslutna vad de behövde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 21, 'Och Rodokus, en man ur den judiska hären, yppade för fienderna vad som borde hållas hemligt. Han efterspanades och blev gripen och inspärrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 22, 'Konungen förhandlade ånyo med besättningen i Betsura; han gav och mottog fredsförsäkringar. Sedan tågade han bort');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 23, 'och angrep Judas och hans folk, men led nederlag. Så fick han underrättelse om att Filippus, som hade lämnats kvar såsom riksföreståndare, hade gjort uppror i Antiokia. I bestörtningen häröver inledde han underhandlingar med judarna. Han gav efter och besvor en överenskommelse på i allo billiga villkor; han ingick förlikning med dem och frambar offer och hedrade templet och den heliga platsen och uppträdde välvilligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 24, 'Sedan tog han avsked av Mackabeus. Därefter, sedan han hade lämnat kvar Hegemonides såsom befälhavare över området från Ptolemais till Gerar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 25, 'drog han åstad till Ptolemais. Men invånarna där i Ptolemais voro misslynta över fördraget - de hade nämligen stor ovilja mot judarna - och ville hava bestämmelserna upphävda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 26, 'Lysias trädde då fram på talarstolen och försvarade, så gott han kunde, vad som hade hänt; han lyckades ock att övertyga och lugna dem och göra dem välvilligt stämda. Därefter tågade han tillbaka till Antiokia. På detta sätt ändade konungens anryckande och återtåg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 1, 'Tre år därefter nåddes Judas och hans anhängare av den underrättelsen att Demetrius, Seleukus\' son, med en stark här och flotta hade seglat in i Tripolis\' hamn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 2, 'och att han hade röjt Antiokus och dennes förmyndare Lysias ur vägen och så satt sig i besittning av landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 3, 'En viss Alcimus, som tidigare hade varit överstepräst, hade, under tiden före sammanblandningen, med vett och vilja befläckat sig med hedniskt väsende, men insåg nu att han icke på något sätt kunde rädda sin ställning eller vidare få tillträde till det heliga altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 4, 'Han begav sig därför, år 151, till konung Demetrius och förärade honom en krans av guld och en palmkvist, och jämte dessa sedvanliga skänker några av helgedomens olivkvistar. Den första dagen höll han sig stilla. Men sedan fick han ett tillfälles som gynnade hans galenskap. Demetrius lät nämligen kalla honom till ett rådssammanträde och frågade honom därvid om huru judarna voro sinnade, och vad de hade för planer. Härpå svarade han då: 6 »De bland judarna, som kallas asidéer, och som hava Judas Mackabeus till ledare, hålla alltjämt kriget vid makt och anstifta oroligheter och hindra att lugn och ro får råda i riket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 5, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 6, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 7, 'Med anledning härav, och sedan jag själv har blivit berövad min fäderneärvda värdighet, jag menar översteprästämbetet, har jag nu begivit mig hit,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 8, 'först och främst av uppriktig omtanke om det som tillkommer konungen, men för det andra också av hänsyn till mina egna landsmäns bästa. Ty genom de förut nämnda människornas oförnuft lider hela vårt folk den största skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 9, 'Så värdes då, o konung, noga taga kännedom om detta i alla dess enskildheter, och låt dig vårda om vårt land, såväl som om vårt folk, som är så svårt ansatt, i enlighet med den nådefulla välvilja som du har mot alla människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 10, 'Ty så länge Judas är i livet, är det omöjligt att få frid och ro i landet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 11, 'Sedan denne hade talat så, begynte strax konungens övriga vänner, vilka voro hätska mot Judas, att ytterligare uppegga Demetrius.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 12, 'Han lät då genast kalla till sig Nikanor, som förut hade varit överste för elefantavdelningen, och utnämnde honom till befälhavare i Judeen och sände honom åstad dit,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 13, 'med skriftlig befallning att röja Judas själv ur vägen och skingra hans folk, så ock att insätta Alcimus såsom överstepräst vid den höga helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 14, 'Och de hedningar i Judeen, som hade flytt för Judas, slöto sig i hopar till Nikanor,! hopp om att själva vinna fördelar genom judarnas motgångar och olyckor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 15, 'Men när judarna fingo höra talas om att Nikanor var i antågande, och att hedningarna gingo till anfall, strödde de stoft på sina huvuden och åkallade honom som för evärdlig tid hade utvalt sitt folk, och som alltid tager sig an sin arvedel genom att uppenbara sin makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 16, 'På sin anförares befallning bröto de sedan strax upp från staden, och de stötte på fienden vid byn Dessau.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 17, 'Men Simon, Judas\' broder, hade råkat i strid med Nikanor och lidit en tillfällig motgång, på grund av den plötsliga bestörtning som motståndarna hade framkallat hos dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 18, 'Det oaktat drog Nikanor i betänkande att låta saken avgöras genom blodig strid, när han hörde talas om den tapperhet och det mod som Judas och hans folk visade i kampen för sitt fädernesland.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 19, 'Han sände därför Posidonius, Teodotus och Mattatias för att söka uppnå en ömsesidig överenskommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 20, 'Sedan man länge hade överlagt härom, lade anföraren fram saken för manskapet, och då det härvid visade sig att alla voro av en och samma mening, gåvo de sitt bifall till fördraget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 21, 'Och man bestämde en viss dag då de båda anförarna enskilt skulle komma tillsammans. Och Judas trädde fram. Och där stodo två stolar mitt emot varandra; man hade nämligen satt fram stolar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 22, 'Men Judas hade på lämpliga platser ställt beväpnat folk i beredskap, för den händelse att ifrån fiendernas sida något plötsligt övervåld skulle ske. De överlade nu med varandra efter vad omständigheterna krävde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 23, 'Nikanor vistades därefter någon tid i Jerusalem utan att företaga något otillbörligt; och det folk som i stora skaror hade samlats hos honom lät han åtskiljas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 24, 'Och han hade under hela tiden Judas i sitt sällskap; han hade nämligen fattat varm tillgivenhet för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 25, 'Han uppmanade honom att gifta sig och skaffa sig barn. Judas gifte sig också och levde i god ro och njöt av livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 26, 'Men när Alcimus märkte att dessa hade blivit så goda vänner, tog han med sig en avskrift av det ingångna fördraget och begav sig till Demetrius och anklagade Nikanor för att hysa tänkesätt som voro stridande mot rikets bästa; denne hade nämligen till hans efterträdare utnämnt riksförrädaren Judas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 27, 'Upptänd av vrede och uppeggad genom den skurkens förtal, skrev konungen då ett brev till Nikanor och sade sig känna stor förtrytelse över fördraget och befallde honom att utan dröjsmål sända Mackabeus fängslad till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 28, 'När denna befallning nådde Nikanor, blev han bestört och kände sig illa till mods över att nödgas upphäva överenskommelserna, fastän mannen intet hade förbrutit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 29, 'Men då det icke var möjligt att sätta sig emot konungen, ville han invänta ett lägligt tillfälle för att med list utföra saken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 30, 'Mackabeus märkte nu att Nikanor antog en strävare hållning mot honom, och att hans bemötande icke var så hövligt som vanligt. Och eftersom han förstod att denna strävhet ingalunda hade den bästa betydelse, samlade han ganska många av sina anhängare omkring sig och höll sig undan för Nikanor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 31, 'Men då nu denne insåg att han hade blivit grundligt överlistad av Judas, begav han sig till det höga och heliga templet, medan prästerna höllo på att frambära de tillbörliga offren, och befallde dem att utlämna honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 32, 'När dessa då med ed bedyrade att de icke kände till, var den som han sökte befann sig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 33, 'räckte han ut sin hand mot templet och svor denna ed: »Om I icke utlämnen Judas fängslad till mig, så skall jag låta jämna denna Guds boning med marken och riva ned altaret och på denna plats upprätta en präktig helgedom åt Backus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 34, 'Sedan han hade sagt detta, gick han sin väg. Men prästerna räckte sina händer upp mot himmelen och åkallade honom som alltid kämpar för vårt folk; de sade så: 35 »O Herre, fastän du icke är i behov av något av allt det som är till, har det dock behagat dig att ett tempel, där du kunde hava din boning, skulle finnas bland oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 35, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 36, 'Så bevara nu ock, du all helighets helige Herre, detta hus obesmittat till evärdlig tid, detta hus som så nyss har blivit renat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 37, 'En viss Rasis, en av de äldste i Jerusalem, blev nu angiven för Nikanor. Han var en man som älskade sina landsmän, och som åtnjöt mycket högt anseende och för sin välviljas skull hade fått tillnamnet »judarnas fader».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 38, 'Han hade nämligen tidigare, under tiden före sammanblandningen, framställt lagtolkningar angående rätt judendom och med all ståndaktighet vågat liv och blod för judendomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 39, 'Då Nikanor nu ville öppet visa huru häftigt han hatade judarna, sände han över fem hundra krigsmän åstad för att gripa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 40, 'Genom att låta gripa denne trodde han sig nämligen tillfoga dem en svår olycka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 41, 'Men då skaran var nära att intaga tornet och de redan stormade gårdsporten och ropade att man skulle skaffa eld, så att de kunde antända dörrarna, tog Rasis, när han såg sig omringad på alla sidor, sitt svärd och riktade det mot sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 42, 'Ty han ville hellre dö en ädel död än falla i uslingarnas händer och bliva misshandlad på ett sätt som var hans ädla sinnelag ovärdigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 43, 'Men när han i sin heta iver icke träffade rätt med stöten och hopen redan trängde in genom dörrarna, sprang han oförskräckt upp på muren och kastade sig med manligt mod utför, mitt in bland hopen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 44, 'Då nu denna hastigt vek undan, så att ett mellanrum uppstod, störtade han ned mitt på den tomma platsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 45, 'Men ännu vid liv och gripen av vild upphetsning, reste han sig upp, och fastän blodet flöt i strömmar och han var så svårt sårad, ilade han mitt igenom hopen och ställde sig uppe på en brant klippa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 46, 'Och när han redan var helt och hållet förblödd, slet han ut sina inälvor och fattade dem med båda händerna och slungade dem mot hopen. Och sedan han hade anropat honom som råder över liv och ande att han en gång ville giva honom dem tillbaka, slutade han på detta sätt sina dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 1, 'Men när Nikanor fick underrättelse om att Judas och hans män befunno sig i Samariens landsändar, beslöt han att angripa dem på vilodagen, då det kunde ske utan fara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 2, 'Då sade de judar som av nödtvång följde honom: »Förgör dem icke så grymt och omänskligt, utan visa den dag ära, som av den Allseende har blivit hedrad med större helighet än andra dagar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 3, 'Han, den store uslingen, frågade då: »Finnes det i himmelen en härskare som har bjudit att hålla sabbatsdagen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 4, 'Och när de förklarade: »Ja, det är den levande Herren själv, härskaren i himmelen, som har befallt att man skall fira den sjunde dagen»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 5, 'sade den andre: »Men jag är en härskare på jorden, och jag bjuder eder att gripa till vapen och utföra konungens uppdrag.» Dock förmådde han icke utföra sitt skändliga beslut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 6, 'Och Nikanor förhävde sig i stort högmod och hade föresatt sig att uppresa en minnesstod åt sig såsom segrare över Judas och hans här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 7, 'Men Mackabeus upphörde icke att med all tillförsikt förlita sig på att han skulle få hjälp från Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 8, 'Och han uppmanade sitt folk att icke rädas för hedningarnas anfall, utan tänka på det bistånd som de så ofta förut hade fått röna från himmelen, och jämväl denna gång vänta på den seger som den Allsmäktige skulle beskära dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 9, 'Och han tröstade dem med ord ur lagen och profeterna, och påminde dem tillika om de strider som de hade utkämpat, och gjorde dem därigenom ännu mer villiga till strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 10, 'Och sedan han på detta sätt hade uppeldat deras mod, utdelade han sina befallningar; och han framhöll därvid ytterligare för dem hedningarnas trolöshet och edsbrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 11, 'När han sålunda hade väpnat envar av dem, icke så mycket med den trygghet sköld och spjut giver, som med den uppmuntran manliga ord kunna skänka, väckte han också hos alla en övermåttan stor glädje genom att ytterligare förtälja en trovärdig dröm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 12, 'Och detta var vad han hade sett i sin dröm: Han hade sett huru den förre översteprästen Onias, som var en god och ädel man, försynt i umgänget, mild i sitt väsen och värdig i sitt tal, och som allt ifrån ungdomen flitigt hade vinnlagt sig om allt som hör dygden till, huru denne stod och bad med uträckta händer för judarnas hela menighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 13, 'Därefter visade sig en annan man för honom, en som utmärkte sig för sitt grå hår och sitt vördnadsbjudande utseende; och en underbar och överväldigande värdighet vilade över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 14, 'Och Onias tog till orda och sade: «Denne är Jeremias, Guds profet, som älskar sina bröder och beder mycket för folket och den heliga staden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 15, 'Och Jeremias sträckte fram sin högra hand och räckte Judas ett gyllene svärd, och han sade därvid till honom: 16 »Tag emot detta heliga svärd såsom en gåva från Gud; därmed skall du slå ned dina motståndare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 16, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 17, 'Sedan de nu hade blivit uppmuntrade genom Judas\' ord, som voro så förträffliga och så väl ägnade att egga till tapperhet och ingjuta mandom i unga sinnen, beslöto de att icke uppslå något läger, utan med ädelt mod gå till anfall och med all manhaftighet inlåta sig i strid och så låta det komma till ett avgörande, eftersom både staden och det heliga och helgedomen voro i fara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 18, 'Deras oro för hustrur och barn, såväl som för bröder och fränder, betydde nämligen mindre för dem; deras oro gällde först och främst det helgade templet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 19, 'Också hos dem som funnos kvar i staden var ångesten mycket svår, i det att de bävade för huru striden på öppna fältet skulle sluta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 20, 'Redan väntade alla på det förestående avgörandet, och redan hade fienderna samlat sina skaror; deras här hade ordnat sig till strid, och elefanterna hade förts fram till en lämplig plats, och ryttarna stodo uppställda på flyglarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 21, 'Då Mackabeus nu såg att skarorna voro helt nära, och såg deras brokiga vapenutrustning och elefanternas vildhet, räckte han händerna upp mot himmelen och åkallade Herren, som gör under; ty han visste att avgörandet icke sker genom vapenmakt, utan efter som det bliver bestämt av honom som förlänar segern åt dem som äro värdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 22, 'Han åkallade Herren och sade därvid så: »Du sände din ängel, O Herre, på Esekias\', Juda konungs, tid, och han förgjorde av Sennakerims här vid pass ett hundra åttiofem tusen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 23, 'Så sänd också nu, du härskare i himmelen, en god ängel framför oss till att sprida fruktan och bävan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 24, 'Och må de som under hädelser hava dragit upp mot ditt heliga tempel bliva slagna med skräck genom kraften av din arm.» Därmed slutade han sin bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 25, 'Nikanor och hans folk ryckte nu fram under trumpetklang och stridssånger,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 26, 'men Judas och hans folk drabbade under åkallan och böner samman med fienden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 27, 'Och under det att de förde svärdet med sina händer, men med sina hjärtan bådo till Gud, nedgjorde de icke mindre än trettiofem tusen man, ty de blevo högeligen styrkta därigenom att Gud uppenbarade sin makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 28, 'Och när striden var slut och de under glädje vände tillbaka, funno de Nikanor, där han låg fallen i sin vapenrustning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 29, 'Då begynte de att ropa och larma; och de prisade den Allsmäktige på sina fäders tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 30, 'Och han som alltid hade såsom den främste kämpat med liv och blod för sina landsmän och bevarat sin ungdoms tillgivenhet för sina stamförvanter, han befallde att man skulle hugga av Nikanors huvud, så ock hans hand tillika med armen, och föra dem med sig till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 31, 'Och när han hade kommit dit, kallade han tillhopa sina stamförvanter och lät prästerna taga plats framför altaret och sände sedan efter dem som befunno sig på borgen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 32, 'Och han visade dem den skändlige Nikanors huvud och den smädarens hand, vilken denne under förmätet tal hade räckt ut mot den Allsmäktiges heliga hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 33, 'Han lät ock skära av den gudlöse Nikanors tunga och bjöd att den skulle styckas och givas åt fåglarna; det övriga skulle hängas upp framför templet, till lön för hans galenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 34, 'Och de ropade allasammans mot himmelen och lovade Herren, som hade uppenbarat sin makt, och sade: »Lovad vare han som har bevarat sin heliga plats obesmittadl»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 35, 'Och Judas lät fästa upp Nikanors huvud på borgen, så att det var synligt för alla, såsom ett tydligt vittnesbörd om Herrens hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 36, 'Och de stadgade alla genom ett gemensamt beslut att man icke skulle låta denna dag gå obemärkt förbi, utan att man skulle fira den såsom en bemärkelsedag, just den trettonde dagen i tolfte månaden - samma månad som på syriska kallas Adar - dagen före Mardokeus\' dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 37, 'På detta sätt ändade alltså Nikanors företag. Och alldenstund hebreerna allt ifrån den tiden hava varit i besittning av sin stad, vill också jag här sluta min berättelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 38, 'Om den nu befinnes vara väl och skickligt avfattad, så överensstämmer detta med min egen önskan; om den däremot är svagt och medelmåttigt avfattad, så har jag dock gjort så gott som jag förmådde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 39, 'Det är ju så, att det bjuder emot att dricka enbart vin eller enbart vatten, medan vin, blandat med vatten, är välsmakande och skänker en behaglig njutning. På samma sätt förnöjer en väl utförd skildring deras öron, som få skriften i sina händer. Och härmed vill jag nu sluta.');
