INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, '2 Krön 33,12; Syndabekännelse och bön om förlåtelse. Herre, du Allsmäktige, i himmelen, du våra fäders Gud, Abrahams, Isaks och Jakobs och deras rättfärdiga säds Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'du som har gjort himmel och jord med all deras härlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'du som har fjättrat havet genom ditt buds ord, du som har tillslutit djupet och förseglat det med ditt fruktansvärda och härliga namn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'du för vilkens makt allt skälver och bävar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'då ju ingen kan uthärda din härlighets majestät och ingen kan stå din vrede emot, när du hotar syndarna!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Ingen kan mäta eller utrannsaka ditt löftes nåd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'ty du är Herren, den Allrahögste, barmhärtig, långmodig och stor i nåd, och du ångrar det onda som du låter drabba människor. Du har ju, o Herre, efter din stora godhet utlovat bättring och förlåtelse för dem som hava syndat mot dig, och du har efter din stora barmhärtighet bestämt att syndare få göra bättring, så att de kunna bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Därför, o Herre, du de rättfärdigas Gud, pålade du icke de rättfärdiga bättring, Abraham, Isak och Jakob, som icke hade syndat mot dig, men mig, som är en syndare, pålade du bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ty de synder jag har begått äro talrikare än havets sand, mina överträdelser äro ju mångfaldiga, ja, Herre, mångfaldiga, och jag är icke värd att blicka uppåt och skåda himmelens höjd, för mina många missgärningars skull;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'jag är ju nedtyngd av många järnbojor, så att jag icke kan upplyfta mitt huvud. Och jag får icke någon ro; ty jag har uppväckt din förtörnelse och gjort vad ont är i dina ögon, i det jag lät uppställa styggelser och förövade skändligheter i mängd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Så böjer jag nu mitt hjärtas knä och anropar den godhet som bor hos dig:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'Jag har syndat, o Herre, jag har syndat, och jag känner själv mina överträdelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'Jag beder och anropar dig: Förlåt mig, Herre, ja, förlåt mig, och låt mig icke förgås i mina överträdelser; vredgas ej för beständigt, så att du låter mitt elände bestå, och fördöm mig icke här där jag ligger i underjorden. Du är ju, o Herre, de botfärdigas Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Ja, också på mig skall du bevisa all din godhet; fastän jag är ovärdig, skall du frälsa mig efter din stora barmhärtighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, 'och jag skall beständigt prisa dig i alla mina livsdagar. Ty dig lovsjunger himmelens hela härskara, och din är äran i evighet. Amen.');
