INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Detta är Jesu Kristi, Davids sons, Abrahams sons, släkttavla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Abraham födde Isak, Isak födde Jakob, Jakob födde Judas och hans bröder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Judas födde Fares och Sara med Tamar, Fares födde Esrom, Esrom födde Aram;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Aram födde Aminadab, Aminadab födde Naasson, Naasson födde Salmon;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Salmon födde Boes med Rakab, Boes födde Jobed med Rut, Jobed födde Jessai;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Jessai födde David, konungen, David födde Salomo med Urias\' hustru;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Salomo födde Roboam, Roboam födde Abia. Abia födde Asaf;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Asaf födde Josafat, Josafat födde Joram, Joram födde Osias;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Osias födde Joatam, Joatam födde Akas, Akas födde Esekias;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Esekias födde Manasses, Manasses födde Amos, Amos födde Josias;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Josias födde Jekonias och hans bröder, vid den tid då folket blev bortfört i fångenskap till Babylonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Sedan folket hade blivit bortfört i fångenskap till Babylonien, födde Jekonias Salatiel, Salatiel födde Sorobabel;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Sorobabel födde Abiud, Abiud födde Eljakim, Eljakim födde Asor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Asor födde Sadok, Sadok födde Akim, Akim födde Eliud;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Eliud födde Eleasar, Eleasar födde Mattan, Mattan födde Jakob;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Jakob födde Josef, Marias man, och av henne föddes Jesus, som kallas Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Så utgöra släktlederna från Abraham intill David tillsammans fjorton leder, och från David intill dess att folket blev bortfört i fångenskap till Babylonien fjorton leder, och från det att folket blev bortfört i fångenskap till Babylonien intill Kristus fjorton leder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Med Jesu Kristi födelse gick det så till. Sedan Maria, hans moder, hade blivit trolovad med Josef, befanns hon, förrän de kommo tillsammans, vara havande av helig ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Nu var Josef, hennes man, en rättsinnig man och ville icke utsätta henne for vanära; därför beslöt han att hemligen skilja sig från henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Men när han hade fått detta i sinnet, se, då visade sig i drömmen en Herrens ängel för honom och sade: »Josef, Davids son, frukta icke att taga till dig Maria, din hustru; ty det som är avlat i henne är av helig ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Och hon skall föda en son, och honom skall du giva namnet Jesus[1], ty han skall frälsa sitt folk ifrån deras synder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Allt detta har skett, för att det skulle fullbordas, som var sagt av Herren genom profeten som sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, '»Se, jungfrun skall bliva havande och föda en son, och man skall giva honom namnet Emmanuel» (det betyder Gud med oss).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'När Josef hade vaknat upp ur sömnen, gjorde han som Herrens ängel hade befallt honom och tog sin hustru till sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Och han kände henne icke, förrän hon hade fött en son; och honom gav han namnet Jesus. [1] Jämför hebr. jeschuá, som betyder frälsning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'När nu Jesus var född i Betlehem i Judeen, på konung Herodes\' tid, då kommo vise män från österns länder till Jerusalem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'och sade: »Var är den nyfödde judakonungen? Vi hava nämligen sett hans stjärna i östern och hava kommit för att giva honom vår hyllning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'När konung Herodes hörde detta, blev han förskräckt, och hela Jerusalem med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'Och han församlade alla överstepräster och skriftlärde bland folket och frågade dem var Messias skulle födas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'De svarade honom: »I Betlehem i Judeen; ty så är skrivet genom profeten:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, '\'Och du Betlehem, du judiska bygd, ingalunda är du minst bland Juda furstar, ty av dig skall utgå en furste som skall vara en herde för mitt folk Israel.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'Då kallade Herodes hemligen till sig de vise männen och utfrågade dem noga om tiden då stjärnan hade visat sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'Sedan lät han dem fara till Betlehem och sade: »Faren åstad och forsken noga efter barnet; och när I haven funnit det, så låten mig veta detta, för att också jag må komma och giva det min hyllning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'När de hade hört konungens ord, foro de åstad; och se, stjärnan som de hade sett i östern gick framför dem, till dess att den kom över det ställe där barnet var. Där stannade den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'Och när de sågo stjärnan, uppfylldes de av mycket stor glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'Och de gingo in i huset och fingo se barnet med Maria, dess moder. Då föllo de ned och gåvo det sin hyllning; och de togo fram sina skatter och framburo åt det skänker: guld, rökelse och myrra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Sedan fingo de, genom en uppenbarelse i drömmen, befallning att icke återvända till Herodes; och de drogo så en annan väg tillbaka till sitt land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'Men när de hade dragit åstad, se, då visade sig i drömmen en Herrens ängel för Josef och sade: »Stå upp och tag barnet och dess moder med dig, och fly till Egypten, och bliv kvar där, till dess jag säger dig till; ty Herodes tänker söka efter barnet för att förgöra det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Då stod han upp och tog barnet och dess moder med sig om natten, och drog bort till Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'Där blev han kvar intill Herodes\' död, för att det skulle fullbordas, som var sagt av Herren genom profeten som sade: »Ut ur Egypten kallade jag min son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'När Herodes nu såg att han hade blivit gäckad av de vise männen, blev han mycket vred. Och han sände åstad och lät döda alla de gossebarn i Betlehem och hela området däromkring, som voro två år gamla och därunder, detta enligt den uppgift om tiden, som han hade fått genom att utfråga de vise männen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Då fullbordades det som var sagt genom profeten Jeremias, när han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, '»Ett rop hördes i Rama, gråt och mycken jämmer; det var Rakel som begrät sina barn, och hon ville icke låta trösta sig, eftersom de icke mer voro till.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Men när Herodes var död, se, då visade sig i drömmen en Herrens ängel for Josef, i Egypten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'och sade: »Stå upp och tag barnet och dess moder med dig, och begiv dig till Israels land; ty de som traktade efter barnets liv äro nu döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'Då stod han upp och tog barnet och dess moder med sig, och kom så till Israels land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'Men när han hörde att Arkelaus regerade över Judeen; efter sin fader Herodes, fruktade han att begiva sig dit; och på grund av en uppenbarelse i drömmen drog han bort till Galileens bygder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'Och när han hade kommit dit, bosatte han sig i en stad som hette Nasaret, för att det skulle fullbordas, som var sagt genom profeterna, att han skulle kallas nasaré.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Vid den tiden uppträdde Johannes döparen och predikade i Judeens öken');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'och sade: »Gören bättring, ty himmelriket är nära.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Det var om denne som profeten Esaias talade, när han sade: »Hör rösten av en som ropar i öknen: \'Bereden vägen för Herren, gören stigarna jämna för honom.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'Och Johannes hade kläder av kamelhår och bar en lädergördel om sina länder, och hans mat var gräshoppor och vildhonung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'Och från Jerusalem och hela Judeen och hela trakten omkring Jordan gick då folket ut till honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'och lät döpa sig av honom i floden Jordan, och bekände därvid sina synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Men när han såg många fariséer och sadducéer komma för att låta döpa sig, sade han till dem: »I huggormars avföda, vem har ingivit eder att söka komma undan den tillstundande vredesdomen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Bären då ock sådan frukt som tillhör bättringen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'Och menen icke att I kunnen säga vid eder själva: \'Vi hava ju Abraham till fader\'; ty jag säger eder att Gud av dessa stenar kan uppväcka barn åt Abraham.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'Och redan är yxan satt till roten på träden; så bliver då vart träd som icke bär god frukt avhugget och kastat i elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'Jag döper eder i vatten till bättring, men den som kommer efter mig, han är starkare än jag, och jag är icke ens värdig att bära hans skor; han skall döpa eder i helig ande och eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Han har sin kastskovel i handen, och han skall noga rensa sin loge och samla in sitt vete i ladan; men agnarna skall han bränna upp i en eld som icke utsläckes.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'Därefter kom Jesus från Galileen till Johannes, vid Jordan, för att låta döpa sig av honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'men denne ville hindra honom och sade: »Jag behövde döpas av dig, och du kommer till mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Då svarade Jesus och sade till honom: »Låt det nu så ske; ty det höves oss att så uppfylla all rättfärdighet. Då tillstadde han honom det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Och när Jesus var döpt, steg han strax upp ur vattnet; och se, då öppnades himmelen, och han såg Guds Ande sänka sig ned såsom en duva och komma över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Och från himmelen kom en röst, som sade: »Denne är min älskade Son, i vilken jag har funnit behag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Därefter blev Jesus av Anden förd upp i öknen, för att han skulle frestas av djävulen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'Och när han hade fastat i fyrtio dagar och fyrtio nätter, blev han omsider hungrig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Då trädde frestaren fram och sade till honom: »Är du Guds Son, så bjud att dessa stenar bliva bröd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'Men han svarade och sade: »Det är skrivet: \'Människan skall leva icke allenast av bröd, utan av allt det som utgår av Guds mun.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Därefter tog djävulen honom med sig till den heliga staden och ställde honom uppe på helgedomens mur');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'och sade till honom: »Är du Guds Son, så kasta dig ned; det är ju skrivet: \'Han skall giva sina änglar befallning om dig, och de skola bära dig på händerna, så att du icke stöter din fot mot någon sten.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Jesus sade till honom: »Det är ock skrivet: \'Du skall icke fresta Herren, din Gud.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Åter tog djävulen honom med sig, upp på ett mycket högt berg, och visade honom alla riken i världen och deras härlighet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'och sade till honom: »Allt detta vill jag giva dig, om du faller ned och tillbeder mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Då sade Jesus till honom: »Gå bort, Satan; ty det är skrivet: \'Herren, din Gud, skall du tillbedja, och honom allena skall du tjäna.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Då lämnade djävulen honom; och se, änglar trädde fram och betjänade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Men när han hörde att Johannes hade blivit satt i fängelse, drog han sig tillbaka till Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Och han lämnade Nasaret och begav sig till Kapernaum, som ligger vid sjön, på Sabulons och Neftalims område, och bosatte sig där,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'för att det skulle fullbordas, som var sagt genom profeten Esaias, när han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, '»Sabulons land och Neftalims land, trakten åt havet till, landet på andra sidan Jordan, hedningarnas Galileen --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'det folk som där satt i mörker fick se ett stort ljus; ja, de som sutto i dödens ängd och skugga, för dem gick upp ett ljus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Från den tiden begynte Jesus predika och säga: »Gören bättring, ty himmelriket är nära.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Då han nu vandrade utmed Galileiska sjön, fick han se två bröder, Simon, som kallas Petrus, och Andreas, hans broder, kasta ut nät i sjön, ty de voro fiskare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'Och han sade till dem: »Följen mig så skall jag göra eder till människofiskare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Strax lämnade de näten och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'När han hade gått därifrån ett stycke längre fram, fick han se två andra bröder, Jakob, Sebedeus\' son, och Johannes, hans broder, där de jämte sin fader Sebedeus sutto i båten och ordnade sina nät; och han kallade dem till sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Och strax lämnade de båten och sin fader och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Och han gick omkring i hela Galileen och undervisade i deras synagogor och predikade evangelium om riket och botade alla slags sjukdomar och allt slags skröplighet bland folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 24, 'Och ryktet om honom gick ut över hela Syrien, och man förde till honom alla sjuka som voro hemsökta av olika slags lidanden och plågor, alla som voro besatta eller månadsrasande eller lama; och han botade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 25, 'Och honom följde mycket folk ifrån Galileen och Dekapolis och Jerusalem och Judeen och från landet på andra sidan Jordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 1, 'När han nu såg folket, gick han upp på berget; och sedan han hade satt sig ned, trädde hans lärjungar fram till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 2, 'Då öppnade han sin mun och undervisade dem och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 3, '»Saliga äro de som äro fattiga i anden, ty dem hör himmelriket till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 4, 'Saliga äro de som sörja, ty de skola bliva tröstade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 5, 'Saliga äro de saktmodiga, ty de skola besitta jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 6, 'Saliga äro de som hungra och törsta efter rättfärdighet, ty de skola bliva mättade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 7, 'Saliga äro de barmhärtiga, ty dem skall vederfaras barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 8, 'Saliga äro de renhjärtade, ty de skola se Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 9, 'Saliga äro de fridsamma, ty de skola kallas Guds barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 10, 'Saliga äro de som lida förföljelse för rättfärdighets skull, ty dem hör himmelriket till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 11, 'Ja, saliga ären I, när människorna för min skull smäda och förfölja eder och sanningslöst säga allt ont mot eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 12, 'Glädjens och fröjden eder, ty eder lön är stor i himmelen. Så förföljde man ju ock profeterna, som voro före eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 13, 'I ären jordens salt; men om saltet mister sin sälta, varmed skall man då giva det sälta igen? Till intet annat duger det än till att kastas ut och trampas ned av människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 14, 'I ären världens ljus. Icke kan en stad döljas, som ligger uppe på ett berg?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 15, 'Ej heller tänder man ett ljus och sätter det under skäppan, utan man sätter det på ljusstaken, så att det lyser för alla dem som äro i huset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 16, 'På samma sätt må ock edert ljus lysa inför människorna, så att de se edra goda gärningar och prisa eder Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 17, 'I skolen icke mena att jag har kommit för att upphäva lagen eller profeterna. Jag har icke kommit för att upphäva, utan för att fullborda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 18, 'Ty sannerligen säger jag eder: Intill dess himmel och jord förgås, skall icke den minsta bokstav, icke en enda prick av lagen förgås, förrän det allt har fullbordats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 19, 'Därför, den som upphäver ett av de minsta bland dessa bud och lär människorna så, han skall räknas för en av de minsta i himmelriket; men den som håller dem och lär människorna så, han skall räknas för stor i himmelriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 20, 'Ty jag säger eder, att om eder rättfärdighet icke övergår de skriftlärdes och fariséernas, så skolen I icke komma in i himmelriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 21, 'I haven hört att det är sagt till de gamle: \'Du skall icke dräpa; och den som dräper, han är hemfallen åt Domstolens[1] dom.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 22, 'Men jag säger eder: Var och en som vredgas på sin broder, han är hemfallen åt Domstolens dom; men den som säger till sin broder: \'Du odåga\', han är hemfallen åt Stora rådets dom; och den som säger: \'Du dåre\', han är hemfallen åt det brinnande Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 23, 'Därför, om du kommer med din gåva till altaret, och där drager dig till minnes att din broder har något emot dig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 24, 'så lägg ned din gåva där framför altaret, och gå först bort och förlik dig med din broder, och kom sedan och bär fram din gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 25, 'Var villig till snar förlikning med din motpart, medan du ännu är med honom på vägen, så att din motpart icke drager dig inför domaren, och domaren överlämnar dig åt rättstjänaren, och du bliver kastad i fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 26, 'Sannerligen säger jag dig: Du skall icke slippa ut därifrån, förrän du har betalt den yttersta skärven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 27, 'I haven hört att det är sagt: \'Du skall icke begå äktenskapsbrott.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 28, 'Men jag säger eder: Var och en som med begärelse ser på en annans hustru, han har redan begått äktenskapsbrott med henne i sitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 29, 'Om nu ditt högra öga är dig till förförelse, så riv ut det och kasta det ifrån dig; ty det är bättre för dig att en av dina lemmar fördärvas, än att hela din kropp kastas i Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 30, 'Och om din högra hand är dig till förförelse, så hugg av den och kasta den ifrån dig; ty det är bättre för dig att en av dina lemmar fördärvas, än att hela din kropp kommer till Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 31, 'Det är ock sagt: \'Den som vill skilja sig från sin hustru han skall giva henne skiljebrev.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 32, 'Men jag säger eder: Var och en som skiljer sig från sin hustru för någon annan saks skull än för otukt, han bliver orsak till att äktenskapsbrott begås med henne. Och den som tager en frånskild kvinna till hustru, han begår äktenskapsbrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 33, 'Ytterligare haven I hört att det är sagt till de gamle: \'Du skall icke svärja falskt\' och \'Du skall hålla din ed inför Herren.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 34, 'Men jag säger eder att I alls icke skolen svärja, varken vid himmelen, ty den är \'Guds tron\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 35, 'ej heller vid jorden, ty den är \'hans fotapall\', ej heller vid Jerusalem, ty det är \'den store Konungens stad\';');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 36, 'ej heller må du svärja vid ditt huvud, ty du kan icke göra ett enda hår vare sig vitt eller svart;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 37, 'utan sådant skall edert tal vara, att ja är ja, och nej är nej. Vad därutöver är, det är av ondo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 38, 'I haven hört att det är sagt: \'Öga för öga och tand för tand.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 39, 'Men jag säger eder att I icke skolen stå emot en oförrätt; utan om någon slår dig på den högra kinden, så vänd ock den andra till åt honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 40, 'och om någon vill gå till rätta med dig för att beröva dig din livklädnad, så låt honom få manteln med;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 41, 'och om någon tvingar dig att till hans tjänst gå med en mil, så gå två med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 42, 'Giv åt den som beder dig, och vänd dig icke bort ifrån den som vill låna av dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 43, 'I haven hört att det är sagt: \'Du skall älska din nästa och hata din ovän.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 44, 'Men jag säger eder: Älsken edra ovänner, och bedjen för dem som förfölja eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 45, 'och varen så eder himmelske Faders barn; han låter ju sin sol gå upp över både onda och goda och låter det regna över både rättfärdiga och orättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 46, 'Ty om I älsken dem som älska eder, vad lön kunnen I få därför? Göra icke publikanerna detsamma?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 47, 'Och om I visen vänlighet mot edra bröder allenast, vad synnerligt gören I därmed? Göra icke hedningarna detsamma?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 48, 'Varen alltså I fullkomliga, såsom eder himmelske Fader är fullkomlig.» [1] Se Domstol i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 1, '»Tagen eder till vara för att öva eder rättfärdighet inför människorna, för att bliva sedda av dem; annars haven I ingen lön hos eder Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 2, 'Därför, när du giver en allmosa, så låt icke stöta i basun för dig, såsom skrymtarna göra i synagogorna och på gatorna, för att de skola bliva prisade av människorna. Sannerligen säger jag eder: De hava fått ut sin lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 3, 'Nej, när du giver en allmosa, låt då din vänstra hand icke få veta vad den högra gör,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 4, 'så att din allmosa gives i det fördolda. Då skall din Fader, som ser i det fördolda, vedergälla dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 5, 'Och när I bedjen, skolen I icke vara såsom skrymtarna, vilka gärna stå i synagogorna och i gathörnen och bedja, för att bliva sedda av människorna. Sannerligen säger jag eder: De hava fått ut sin lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 6, 'Nej, när du vill bedja, gå då in i din kammare, och stäng igen din dörr, och bed till din Fader i det fördolda. Då skall din Fader, som ser i det fördolda, vedergälla dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 7, 'Men i edra böner skolen I icke hopa tomma ord såsom hedningarna, vilka mena att de skola bliva bönhörda för sina många ords skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 8, 'Så varen då icke lika dem; eder Fader vet ju vad I behöven, förrän I bedjen honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 9, 'I skolen alltså bedja sålunda: \'Fader vår, som är i himmelen! Helgat varde ditt namn[1];');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 10, 'tillkomme ditt rike; ske din vilja, såsom i himmelen, så ock på jorden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 11, 'vårt dagliga bröd giv oss i dag;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 12, 'och förlåt oss våra skulder, såsom ock vi förlåta dem oss skyldiga äro;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 13, 'och inled oss icke i frestelse, utan fräls oss ifrån ondo.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 14, 'Ty om I förlåten människorna deras försyndelser, så skall ock eder himmelske Fader förlåta eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 15, 'men om I icke förlåten människorna, så skall ej heller eder Fader förlåta edra försyndelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 16, 'Och när I fasten, skolen I icke visa en bedrövad uppsyn såsom skrymtarna, vilka vanställa sina ansikten för att bliva sedda av människorna med sin fasta. Sannerligen säger jag eder: De hava fått ut sin lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 17, 'Nej, när du fastar, smörj då ditt huvud och två ditt ansikte,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 18, 'för att du icke må bliva sedd av människorna med din fasta, utan allenast av din Fader, som är i det fördolda. Då skall din Fader, som ser i det fördolda, vedergälla dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 19, 'Samlen eder icke skatter på jorden, där mott och mal förstöra, och där tjuvar bryta sig in och stjäla,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 20, 'utan samlen eder skatter i himmelen, där mott och mal icke förstöra, och där inga tjuvar bryta sig in och stjäla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 21, 'Ty där din skatt är, där kommer ock ditt hjärta att vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 22, 'Ögat är kroppens lykta. Om nu ditt öga är friskt, så får hela din kropp ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 23, 'Men om ditt öga är fördärvat, då bliver hela din kropp höljd i mörker. Är det nu så, att ljuset, som du har i dig, är mörker, huru djupt bliver då icke mörkret!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 24, 'Ingen kan tjäna två herrar; ty antingen kommer han då att hata den ene och älska den andre, eller kommer han att hålla sig till den förre och förakta den senare. I kunnen icke tjäna både Gud och Mamon[2].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 25, 'Därför säger jag eder: Gören eder icke bekymmer för edert liv, vad I skolen äta eller dricka, ej heller för eder kropp, vad I skolen kläda eder med. Är icke livet mer än maten, och kroppen mer än kläderna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 26, 'Sen på fåglarna under himmelen: de så icke, ej heller skörda de, ej heller samla de in i lador; och likväl föder eder himmelske Fader dem. Ären I icke mycket mer än de?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 27, 'Vilken av eder kan, med allt sitt bekymmer, lägga en enda aln till sin livslängd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 28, 'Och varför bekymren I eder för kläder? Beskåden liljorna på marken, huru de växa: de arbeta icke, ej heller spinna de;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 29, 'och likväl säger jag eder att icke ens Salomo i all sin härlighet var så klädd som en av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 30, 'Kläder nu Gud så gräset på marken, vilket i dag står och i morgon kastas i ugnen, skulle han då icke mycket mer kläda eder, I klentrogne?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 31, 'Så gören eder nu icke bekymmer, och sägen icke: \'Vad skola vi äta?\' eller: \'Vad skola vi dricka?\' eller: \'Vad skola vi kläda oss med?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 32, 'Efter allt detta söka ju hedningarna, och eder himmelske Fader vet att I behöven allt detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 33, 'Nej, söken först efter hans rike och hans rättfärdighet, så skall också allt detta andra tillfalla eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 34, 'Gören eder alltså icke bekymmer för morgondagen, ty morgondagen skall själv bära sitt bekymmer. Var dag har nog av sin egen plåga.» [1] Se Fader vår i Ordförklaringarna. [2] Se Mamon i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 1, '»Dömen icke, på det att I icke mån bliva dömda;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 2, 'ty med den dom varmed I dömen skolen I bliva dömda, och med det mått som I mäten med skall ock mätas åt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 3, 'Huru kommer det till, att du ser grandet i din broders öga, men icke bliver varse bjälken i ditt eget öga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 4, 'Eller huru kan du säga till din broder: \'Låt mig taga ut grandet ur ditt öga\', du som har en bjälke i ditt eget öga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 5, 'Du skrymtare, tag först ut bjälken ur ditt eget öga; därefter må du se till, att du kan taga ut grandet ur din broders öga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 6, 'Given icke åt hundarna vad heligt är, och kasten icke edra pärlor för svinen, på det att dessa icke må trampa dem under fötterna och sedan vända sig om och sarga eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 7, 'Bedjen, och eder skall varda givet; söken, och I skolen finna; klappen, och för eder skall varda upplåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 8, 'Ty var och en som beder, han får; och den som söker, han finner; och för den som klappar skall varda upplåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 9, 'Eller vilken är den man bland eder, som räcker sin son en sten, när han beder honom om bröd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 10, 'eller som räcker honom en orm, när han beder om fisk?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 11, 'Om nu I, som ären onda, förstån att giva edra barn goda gåvor, huru mycket mer skall icke då eder Fader, som är i himmelen, giva vad gott är åt dem som bedja honom!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 12, 'Därför, allt vad I viljen att människorna skola göra eder, det skolen I ock göra dem; ty detta är lagen och profeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 13, 'Gån in genom den trånga porten. Ty vid och bred är den väg som leder till fördärvet, och många äro de som gå fram på den;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 14, 'och den port är trång och den väg är smal, som leder till livet, och få äro de som finna den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 15, 'Tagen eder till vara för falska profeter, som komma till eder i fårakläder, men invärtes äro glupande ulvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 16, 'Av deras frukt skolen I känna dem. Icke hämtar man väl vindruvor från törnen, eller fikon från tistlar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 17, 'Så bär vart och ett gott träd god frukt, men ett dåligt träd bär ond frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 18, 'Ett gott träd kan icke bära ond frukt, ej heller kan ett dåligt träd bära god frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 19, 'Vart träd som icke bär god frukt bliver avhugget och kastat i elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 20, 'Alltså skolen I känna dem av deras frukt. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 21, 'Icke kommer var och en in i himmelriket, som säger till mig: \'Herre, Herre\', utan den som gör min himmelske Faders vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 22, 'Många skola på \'den dagen\'[1] säga till mig: \'Herre, Herre, hava vi icke profeterat i ditt namn och genom ditt namn drivit ut onda andar och genom ditt namn gjort många kraftgärningar?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 23, 'Men då skall jag betyga för dem: \'Jag har aldrig känt eder; gån bort ifrån mig, I ogärningsmän.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 24, 'Därför, var och en som hör dessa mina ord och gör efter dem, han må liknas vid en förståndig man som byggde sitt hus på hälleberget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 25, 'Och slagregn föll, och vattenströmmarna kommo, och vindarna blåste och kastade sig mot det huset; och likväl föll det icke omkull, eftersom det var grundat på hälleberget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 26, 'Men var och en som hör dessa mina ord och icke gör efter dem, han må liknas vid en oförståndig man som byggde sitt hus på sanden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 27, 'Och slagregn föll, och vattenströmmarna kommo, och vindarna blåste och slogo mot det huset; och det föll omkull, och dess fall var stort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 28, 'När Jesus hade slutat detta tal, häpnade folket över hans förkunnelse;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 29, 'ty han förkunnade sin lära för dem med makt och myndighet, och icke såsom deras skriftlärde. [1] Se Dagen i Ordförklaringarna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 1, 'Sedan han hade kommit ned från berget, följde honom mycket folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 2, 'Då trädde en spetälsk man fram och föll ned för honom och sade: »Herre, vill du, så kan du göra mig ren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 3, 'Då räckte han ut handen och rörde vid honom och sade: »Jag vill; bliv ren.» Och strax blev han ren från sin spetälska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 4, 'Och Jesus sade till honom: »Se till, att du icke säger detta för någon; men gå bort och visa dig för prästen, och frambär den offergåva som Moses har påbjudit, till ett vittnesbörd för dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 5, 'När han därefter kom in i Kapernaum, trädde en hövitsman fram till honom och bad honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 6, 'och sade: »Herre, min tjänare ligger därhemma lam och lider svårt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 7, 'Han sade till honom: »Skall då jag komma och bota honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 8, 'Hövitsmannen svarade och sade: »Herre, jag är icke värdig att du går in under mitt tak. Men säg allenast ett ord, så bliver min tjänare frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 9, 'Jag är ju själv en man som står under andras befäl: jag har ock krigsmän under mig, och om jag säger till en av dem: \'Gå\', så går han, eller till en annan: \'Kom\', så kommer han; och om jag säger till min tjänare: \'Gör det\', då gör han så.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 10, 'När Jesus hörde detta, förundrade han sig och sade till dem som följde honom: »Sannerligen säger jag eder: I Israel har jag icke hos någon funnit så stor tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 11, 'Och jag säger eder: Många skola komma från öster och väster och få vara med Abraham, Isak och Jakob till bords i himmelriket,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 12, 'men rikets barn skola bliva utkastade i mörkret därutanför; där skall vara gråt och tandagnisslan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 13, 'Och Jesus sade till hövitsmannen: »Gå; såsom du tror, så må det ske dig.» Och i samma stund blev tjänaren frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 14, 'När Jesus sedan kom in i Petrus\' hus, fick han se hans svärmoder ligga sjuk i feber.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 15, 'Då rörde han vid hennes hand, och febern lämnade henne; och hon stod upp och betjänade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 16, 'Men när det hade blivit afton, förde man till honom många som voro besatta; och han drev ut andarna med sitt blotta ord, och alla som voro sjuka botade han,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 17, 'för att det skulle fullbordas, som var sagt genom profeten Esaias, när han sade: »Han tog på sig våra krankheter, och våra sjukdomar bar han.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 18, 'Då nu Jesus såg mycket folk omkring sig, bjöd han att man skulle fara över till andra stranden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 19, 'Och en skriftlärd kom fram och sade till honom: »Mästare, jag vill följa dig varthelst du går.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 20, 'Då svarade Jesus honom: »Rävarna hava kulor, och himmelens fåglar hava nästen; men Människosonen har ingen plats där han kan vila sitt huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 21, 'Och en annan av hans lärjungar sade till honom: »Herre, tillstäd mig att först gå bort och begrava min fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 22, 'Då svarade Jesus honom: »Följ du mig, och låt de döda begrava sina döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 23, 'Och han steg i båten, och hans lärjungar följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 24, 'Och se, då uppstod en häftig storm på sjön, så att vågorna slogo över båten; men han låg och sov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 25, 'Då gingo de fram och väckte honom och sade: »Herre, hjälp oss; vi förgås.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 26, 'Han sade till dem: »I klentrogne, varför rädens I?» Därefter stod han upp och näpste vindarna och sjön, och det blev alldeles lugnt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 27, 'Och människorna förundrade sig och sade: »Vad är denne för en, eftersom både vindarna och sjön äro honom lydiga?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 28, 'När han så hade kommit över till gadarenernas land på andra stranden, kommo två besatta emot honom, ut från gravarna där. Och de voro mycket våldsamma, så att ingen kunde färdas den vägen fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 29, 'Dessa ropade då och sade: »Vad har du med oss att göra, du Guds Son? Har du kommit hit för att plåga oss, förrän tid är?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 30, 'Nu gick där långt ifrån dem en stor svinhjord i bet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 31, 'Och de onda andarna bådo honom och sade: »Om du vill driva ut oss så låt oss fara in i svinhjorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 32, 'Då sade han till dem: »Faren åstad.» Och de gåvo sig åstad och foro in i svinen. Och se, då störtade sig hela hjorden utför branten ned i sjön och omkom i vattnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 33, 'Men herdarna flydde; och när de hade kommit in i staden, omtalade de alltsammans, och särskilt vad som hade skett med de besatta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 34, 'Då gick hela staden ut för att möta Jesus; och när de fingo se honom, bådo de att han skulle begiva sig bort ifrån deras område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 1, 'Och han steg i en båt och for över och kom till sin egen stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 2, 'Då förde de till honom en lam man, som låg på en säng. När Jesus såg deras tro sade han till den lame: »Var vid gott mod, min son; dina synder förlåtas dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 3, 'Då sade några av de skriftlärde vid sig själva: »Denne hädar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 4, 'Men Jesus förstod deras tankar och sade: »Varför tänken I i edra hjärtan vad ont är?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 5, 'Vilket är lättare, att säga: \'Dina synder förlåtas dig\' eller att säga: \'Stå upp och gå\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 6, 'Men för att I skolen veta att Människosonen har makt här på jorden att förlåta synder, så stå upp» -- sade han nu till den lame -- »och tag din säng och gå hem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 7, 'Då stod han upp och gick hem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 8, 'När folket såg detta, blevo de häpna och prisade Gud, som hade givit sådan makt åt människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 9, 'När Jesus därifrån gick vidare fram, fick han se en man, som hette Matteus, sitta vid tullhuset. Och han sade till denne: »Följ mig.» Då stod han upp och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 10, 'När han därefter låg till bords i hans hus, kommo många publikaner och syndare dit och voro bordsgäster där, jämte Jesus och hans lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 11, 'Men då fariséerna sågo detta, sade de till hans lärjungar: »Huru kan eder mästare äta med publikaner och syndare?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 12, 'När han hörde detta, sade han: »Det är icke de friska som behöva läkare, utan de sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 13, 'Men gån I åstad och lären eder vad de orden betyda: \'Jag har behag till barmhärtighet, och icke till offer.\' Ty jag har icke kommit för att kalla rättfärdiga, utan för att kalla syndare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 14, 'Därefter kommo Johannes\' lärjungar till honom och sade: »Varför fasta icke dina lärjungar då vi och fariséerna ofta fasta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 15, 'Jesus svarade dem: »Icke kunna väl bröllopsgästerna sörja, så länge brudgummen är hos dem? Men den tid skall komma, då brudgummen tages ifrån dem, och då skola de fasta. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 16, 'Ingen sätter en lapp av okrympt tyg på en gammal mantel, ty det isatta stycket skulle riva bort ännu mer av manteln, och hålet skulle bliva värre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 17, 'Ej heller slår man nytt vin I gamla skinnläglar; om någon så gjorde, skulle läglarna sprängas sönder och vinet spillas ut, jämte det att läglarna fördärvades. Nej, man slår nytt vin i nya läglar, så bliva båda delarna bevarade.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 18, 'Medan han talade detta till dem, trädde en synagogföreståndare fram och föll ned för honom och sade: »Min dotter har just nu dött, men kom och lägg din hand på henne, så bliver hon åter levande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 19, 'Då stod Jesus upp och följde honom med sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 20, 'Men en kvinna, som i tolv år hade lidit av blodgång, närmade sig honom bakifrån och rörde vid hörntofsen på hans mantel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 21, 'Ty hon sade vid sig själv: »Om jag allenast får röra vid hans mantel, så bliver jag hulpen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 22, 'Då vände Jesus sig om, och när han fick se henne, sade han: »Var vid gott mod, min dotter; din tro har hjälpt dig.» Och kvinnan var hulpen från den stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 23, 'När Jesus sedan kom in i föreståndarens hus och fick se flöjtblåsarna och folket som höjde klagolåt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 24, 'sade han: »Gån bort härifrån; ty flickan är icke död, hon sover.» Då hånlogo de åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 25, 'Men sedan folket hade blivit utvisat, gick han in och tog flickan vid handen. Då stod hon upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 26, 'Och ryktet härom gick ut över hela det landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 27, 'När Jesus gick därifrån, följde honom två blinda som ropade och sade: »Davids son, förbarma dig över oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 28, 'Och då han kom hem, trädde de blinda fram till honom; och Jesus frågade dem: »Tron I att jag kan göra detta?» De svarade honom: »Ja, Herre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 29, 'Då rörde han vid deras ögon och sade: »Ske eder efter eder tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 30, 'Och deras ögon öppnades. Och Jesus tillsade dem strängeligen att se till, att ingen finge veta detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 31, 'Men de gingo åstad och utspridde ryktet om honom över hela det landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 32, 'När dessa voro på väg ut, förde man till honom en dövstum som var besatt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 33, 'Och när den onde anden hade blivit utdriven, talade den dövstumme. Och folket förundrade sig och sade: »Sådant har aldrig förut varit sett i Israel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 34, 'Men fariséerna sade: »Det är med de onda andarnas furste som han driver ut de onda andarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 35, 'Och Jesus gick omkring i alla städer och byar och undervisade i deras synagogor och predikade evangelium om riket och botade alla slags sjukdomar och allt slags skröplighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 36, 'Och när han såg folkskarorna, ömkade han sig över dem, eftersom de voro så illa medfarna och uppgivna, »lika får som icke hava någon herde.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 37, 'Därför sade han till sina lärjungar: »Skörden är mycken, men arbetarna äro få.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 38, 'Bedjen fördenskull skördens Herre att han sänder ut arbetare till sin skörd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 1, 'Och han kallade till sig sina tolv lärjungar och gav dem makt över orena andar, till att driva ut dem, så ock makt att bota alla slags sjukdomar och allt slags skröplighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 2, 'Och dessa äro de tolv apostlarnas namn: först Simon, som kallas Petrus, och Andreas, hans broder; vidare Jakob, Sebedeus\' son, och Johannes, hans broder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 3, 'Filippus och Bartolomeus; Tomas och Matteus, publikanen; Jakob, Alfeus\' son, och Lebbeus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 4, 'Simon ivraren och Judas Iskariot, densamme som förrådde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 5, 'Dessa tolv sände Jesus ut; och han bjöd dem och sade: »Ställen icke eder färd till hedningarna, och gån icke in i någon samaritisk stad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 6, 'utan gån hellre till de förlorade fåren av Israels hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 7, 'Och där I gån fram skolen I predika och säga: \'Himmelriket är nära.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 8, 'Boten sjuka, uppväcken döda, gören spetälska rena, driven ut onda andar. I haven fått för intet; så given ock för intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 9, 'Skaffen eder icke guld eller silver eller koppar i edra bälten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 10, 'icke någon ränsel för eder färd, ej heller dubbla livklädnader, ej heller skor eller stav; ty arbetaren är värd sin mat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 11, 'Men när I haven kommit in i någon stad eller by, så utforsken vilken därinne som är värdig, och stannen hos honom, till dess I lämnen den orten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 12, 'Och när I kommen in i ett hus, så hälsen det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 13, 'Om då det huset är värdigt, så må den frid I tillönsken det komma däröver; men om det icke är värdigt, då må den frid I tillönsken det vända tillbaka till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 14, 'Och om man på något ställe icke tager emot eder och icke hör på edra ord, så gån ut ur det huset eller den staden, och skudden stoftet av edra fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 15, 'Sannerligen säger jag eder: För Sodoms och Gomorras land skall det på domens dag bliva drägligare än för den staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 16, 'Se, jag sänder eder åstad såsom får mitt in ibland ulvar. Varen fördenskull kloka såsom ormar och menlösa såsom duvor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 17, 'Tagen eder till vara för människorna; ty de skola draga eder inför domstolar, och i sina synagogor skola de gissla eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 18, 'och I skolen föras fram också inför landshövdingar och konungar, för min skull, till ett vittnesbörd för dem och för hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 19, 'Men när man drager eder inför rätta, gören eder då icke bekymmer för huru eller vad I skolen tala; ty vad I skolen tala skall bliva eder givet i den stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 20, 'Det är icke I som skolen tala, utan det är eder Faders Ande som skall tala i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 21, 'Och den ene brodern skall då överlämna den andre till att dödas, ja ock fadern sitt barn; och barn skola sätta sig upp mot sina föräldrar och skola döda dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 22, 'Och I skolen bliva hatade av alla, för mitt namns skull. Men den som är ståndaktig intill änden, han skall bliva frälst. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 23, 'När de nu förfölja eder i en stad, så flyn till en annan; och om de också där förfölja eder, så flyn till ännu en annan. Ty sannerligen säger jag eder: I skolen icke hava hunnit igenom alla Israels städer, förrän Människosonen kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 24, 'Lärjungen är icke förmer än sin mästare, ej heller är tjänaren förmer än sin herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 25, 'Det må vara lärjungen nog, om det går honom såsom hans mästare, och tjänaren, om det går honom såsom hans herre. Om de hava kallat husbonden för Beelsebul, huru mycket mer skola de icke så kalla hans husfolk!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 26, 'Frukten alltså icke för dem; ty intet är förborgat, som icke skall bliva uppenbarat, och intet är fördolt, som icke skall bliva känt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 27, 'Vad jag säger eder i mörkret, det skolen säga i ljuset, och vad I hören viskas i edert öra, det skolen I predika på taken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 28, 'Och frukten icke för dem som väl kunna dräpa kroppen, men icke hava makt att dräpa själen, utan frukten fastmer honom som har makt att förgöra både själ och kropp i Gehenna. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 29, 'Säljas icke två sparvar för en skärv[1]? Och icke en av dem faller till jorden utan eder Faders vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 30, 'Men på eder äro till och med huvudhåren allasammans räknade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 31, 'Frukten alltså icke; I ären mer värda än många sparvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 32, 'Därför, var och en som bekänner mig inför människorna, honom skall ock jag kännas vid inför min Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 33, 'Men den som förnekar mig inför människorna, honom skall ock jag förneka inför min Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 34, 'I skolen icke mena att jag har kommit för att sända frid på jorden. Jag har icke kommit för att sända frid, utan svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 35, 'Ja, jag har kommit för att uppväcka söndring, så att \'sonen sätter sig upp mot sin fader och dottern mot sin moder och sonhustrun mot sin svärmoder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 36, 'och envar får sitt eget husfolk till fiender\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 37, 'Den som älskar fader eller moder mer än mig, han är mig icke värdig, och den som älskar son eller dotter mer än mig, han är mig icke värdig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 38, 'och den som icke tager sitt kors på sig och efterföljer mig, han är mig icke värdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 39, 'Den som finner sitt liv, han skall mista det, och den som mister sitt liv, för min skull, han skall finna det. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 40, 'Den som tager emot eder, han tager emot mig, och den som tager emot mig, han tager emot honom som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 41, 'Den som tager emot en profet, därför att det är en profet, han skall få en profets lön; och den som tager emot en rättfärdig man, därför att det är en rättfärdig man, han skall få en rättfärdig mans lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 42, 'Och den som giver en av dessa små allenast en bägare friskt vatten att dricka, därför att det är en lärjunge -- sannerligen säger jag eder: Han skall ingalunda gå miste om sin lön.» [1] Se Skärv i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 1, 'När Jesus hade givit sina tolv lärjungar alla dessa bud, gick han därifrån vidare, för att undervisa och predika i deras städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 2, 'Men när Johannes i sitt fängelse fick höra om Kristi gärningar, sände han bud med sina lärjungar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 3, 'och lät fråga honom: »Är du den som skulle komma, eller skola vi förbida någon annan?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 4, 'Då svarade Jesus och sade till dem: »Gån tillbaka och omtalen för Johannes vad I hören och sen:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 5, 'blinda få sin syn, halta gå, spetälska bliva rena, döva höra, döda uppstå, och \'för fattiga förkunnas glädjens budskap\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 6, 'Och salig är den för vilken jag icke bliver en stötesten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 7, 'När dessa sedan gingo bort, begynte Jesus tala till folket om Johannes: »Varför var det I gingen ut i öknen? Var det för att se ett rör som drives hit och dit av vinden?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 8, 'Eller varför gingen I ut? Var det för att se en människa klädd i fina kläder? De som bära fina kläder, dem finnen I ju i konungapalatsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 9, 'Varför gingen I då ut? Var det för att se en profet? Ja, jag säger eder: Ännu mer än en profet är han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 10, 'Han är den om vilken det är skrivet: \'Se, jag sänder ut min ängel framför dig, och han skall bereda vägen för dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 11, 'Sannerligen säger jag eder: Bland dem som äro födda av kvinnor har ingen uppstått, som har varit större än Johannes döparen; men den som är minst i himmelriket är likväl större än han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 12, 'Och från Johannes döparens dagar intill denna stund tränger himmelriket fram med storm, och människor storma fram och rycka det till sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 13, 'Ty alla profeterna och lagen hava profeterat intill Johannes;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 14, 'och om I viljen tro det: han är Elias, den som skulle komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 15, 'Den som har öron, han höre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 16, 'Men vad skall jag likna detta släkte vid? Det är likt barn som sitta på torgen och ropa till andra barn');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 17, 'och säga: \'Vi hava spelat för eder, och I haven icke dansat; vi hava sjungit sorgesång, och I haven icke jämrat eder.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 18, 'Ty Johannes kom, och han varken äter eller dricker, och så säger man: \'Han är besatt av en ond ande.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 19, 'Människosonen kom, och han både äter och dricker, och nu säger man: \'Se vilken frossare och vindrinkare han är, en publikaners och syndares vän!\' Men Visheten har fått rätt av sina barn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 20, 'Därefter begynte han tala bestraffande ord till de städer i vilka han hade utfört så många av sina kraftgärningar, och förehålla dem att de icke hade gjort bättring:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 21, '»Ve dig, Korasin! Ve dig, Betsaida! Ty om de kraftgärningar som äro gjorda i eder hade blivit gjorda i Tyrus och Sidon, så skulle de för länge sedan hava gjort bättring i säck och aska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 22, 'Men jag säger eder: För Tyrus och Sidon skall det på domens dag bliva drägligare än för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 23, 'Och du, Kapernaum, skall väl du bliva upphöjt till himmelen? Nej, ned till dödsriket måste du fara. Ty om de kraftgärningar som äro gjorda i dig hade blivit gjorda i Sodom, så skulle det hava stått ännu i dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 24, 'Men jag säger eder att det för Sodoms land skall på domens dag bliva drägligare än för dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 25, 'Vid den tiden talade Jesus och sade: »Jag prisar dig, Fader, du himmelens och jordens Herre, för att du väl har dolt detta för de visa och kloka, men uppenbarat det för de enfaldiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 26, 'Ja, Fader; så har ju varit ditt behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 27, 'Allt har av min Fader blivit förtrott åt mig. Och ingen känner Sonen utom Fadern, ej heller känner någon Fadern utom Sonen och den för vilken Sonen vill göra honom känd. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 28, 'Kommen till mig, I alla som arbeten och ären betungade, så skall jag giva eder ro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 29, 'Tagen på eder mitt ok och lären av mig, ty jag är saktmodig och ödmjuk i hjärtat; \'så skolen I finna ro för edra själar\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 30, 'Ty mitt ok är milt, och min börda är lätt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 1, 'Vid den tiden tog Jesus på sabbaten vägen genom ett sädesfält; och hans lärjungar blevo hungriga och begynte rycka av ax och äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 2, 'När fariséerna sågo detta, sade de till honom: »Se, dina lärjungar göra vad som icke är lovligt att göra på en sabbat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 3, 'Han svarade dem: »Haven I icke läst vad David gjorde, när han och de som följde honom blevo hungriga:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 4, 'huru han då gick in i Guds hus, och huru de åto skådebröden, fastän det ju varken för honom eller för dem som följde honom var lovligt att äta sådant bröd, utan allenast för prästerna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 5, 'Eller haven I icke läst i lagen att prästerna på sabbaten bryta sabbaten i helgedomen, och likväl äro utan skuld?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 6, 'Men jag säger eder: Här är vad som är förmer än helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 7, 'Och haden I förstått vad det är: \'Jag har behag till barmhärtighet, och icke till offer\', så skullen I icke hava dömt dem skyldiga, som äro utan skuld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 8, 'Ty Människosonen är herre över sabbaten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 9, 'Och han gick därifrån vidare och kom in i deras synagoga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 10, 'Och se, där var en man som hade en förvissnad hand. Då frågade de honom och sade: »Är det lovligt att bota sjuka på sabbaten?» De ville nämligen få något att anklaga honom för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 11, 'Men han sade till dem: »Om någon bland eder har ett får, och detta på sabbaten faller i en grop, fattar han icke då i det och drager upp det?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 12, 'Huru mycket mer värd är nu icke en människa än ett får! Alltså är det lovligt att på sabbaten göra vad gott är.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 13, 'Därefter sade han till mannen: »Räck ut din hand.» Och han räckte ut den, och den blev frisk igen och färdig såsom den andra. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 14, 'Då gingo fariséerna bort och fattade det beslutet om honom, att de skulle förgöra honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 15, 'Men när Jesus fick veta detta, gick han bort därifrån; och många följde honom, och han botade dem alla,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 16, 'men förbjöd dem strängeligen att utbreda ryktet om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 17, 'Ty det skulle fullbordas, som var sagt genom profeten Esaias, när han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 18, '»Se, över min tjänare, som jag har utvalt, min älskade, i vilken min själ har funnit behag, över honom skall jag låta min Ande komma, och han skall förkunna rätten bland folken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 19, 'Han skall icke kiva eller skria, och hans röst skall man icke höra på gatorna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 20, 'Ett brutet rör skall han icke sönderkrossa, och en rykande veke skall han icke utsläcka, intill dess att han har fört rätten fram till seger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 21, 'Och till hans namn skola folken sätta sitt hopp.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 22, 'Då förde man till honom en besatt, som var blind och dövstum. Och han botade honom, så att den dövstumme talade och såg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 23, 'Och allt folket uppfylldes av häpnad och sade: »Månne icke denne är Davids son?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 24, 'Men när fariséerna hörde detta, sade de: »Det är allenast med Beelsebul, de onda andarnas furste, som denne driver ut de onda andarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 25, 'Men han förstod deras tankar och sade till dem: »Vart rike som har kommit i strid med sig självt bliver förött, och intet samhälle eller hus som har kommit i strid med sig självt kan hava bestånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 26, 'Om nu Satan driver ut Satan, så har han kommit i strid med sig själv. Huru kan då hans rike hava bestånd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 27, 'Och om det är med Beelsebul som jag driver ut de onda andarna, med vem driva då edra egna anhängare ut dem? De skola alltså vara edra domare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 28, 'Om det åter är med Guds Ande som jag driver ut de onda andarna, så har ju Guds rike kommit till eder. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 29, 'Eller huru kan någon gå in i en stark mans hus och beröva honom hans bohag, såframt han icke förut har bundit den starke? Först därefter kan han plundra hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 30, 'Den som icke är med mig, han är emot mig, och den som icke församlar med mig, han förskingrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 31, 'Därför säger jag eder: All annan synd och hädelse skall bliva människorna förlåten, men hädelse mot Anden skall icke bliva förlåten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 32, 'Ja, om någon säger något mot Människosonen, så skall det bliva honom förlåtet; men om någon säger något mot den helige Ande, så skall det icke bliva honom förlåtet, varken i denna tidsåldern eller i den tillkommande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 33, 'I måsten döma så: antingen är trädet gott, och då måste dess frukt vara god; eller är trädet dåligt, och då måste dess frukt vara dålig. Ty av frukten känner man trädet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 34, 'I huggormars avföda, huru skullen I kunna tala något gott, då I själva ären onda? Vad hjärtat är fullt av, det talar ju munnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 35, 'En god människa bär ur sitt goda förråd fram vad gott är, och en ond människa bär ur sitt onda förråd fram vad ont är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 36, 'Men jag säger eder, att för vart fåfängligt ord som människorna tala skola de göra räkenskap på domens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 37, 'Ty efter dina ord skall du dömas rättfärdig, och efter dina ord skall du dömas skyldig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 38, 'Då togo några av de skriftlärde och fariséerna till orda och sade till honom: »Mästare, vi skulle vilja se något tecken av dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 39, 'Men han svarade och sade till dem: »Ett ont och trolöst släkte är detta! Det åstundar ett tecken, men intet annat tecken skall givas det än profeten Jonas\' tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 40, 'Ty likasom Jonas tre dagar och tre nätter var i den stora fiskens buk, så skall ock Människosonen tre dagar och tre nätter vara i jordens sköte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 41, 'Ninevitiska män skola vid domen träda fram tillsammans med detta släkte och bliva det till dom. Ty de gjorde bättring vid Jonas\' predikan; och se, här är vad som är mer än Jonas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 42, 'Drottningen av Söderlandet skall vid domen träda fram tillsammans med detta släkte och bliva det till dom. Ty hon kom från jordens ända för att höra Salomos visdom; och se, här är vad som är mer än Salomo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 43, 'När en oren ande har farit ut ur en människa, vandrar han omkring i ökentrakter och söker efter ro, men finner ingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 44, 'Då säger han: \'Jag vill vända tillbaka till mitt hus, som jag gick ut ifrån.\' Och när han kommer dit och finner det stå ledigt och vara fejat och prytt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 45, 'då går han åstad och tager med sig sju andra andar, som äro värre än han själv, och de gå ditin och bo där; och så bliver för den människan det sista värre än det första. Så skall det ock gå med detta onda släkte.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 46, 'Medan han ännu talade till folket, kommo hans moder och hans bröder och stannade därutanför och ville tala med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 47, 'Då sade någon till honom: »Se, din moder och dina bröder stå härutanför och vilja tala med dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 48, 'Men han svarade och sade till den som omtalade detta för honom: »Vilken är min moder, och vilka äro mina bröder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 49, 'Och han räckte ut handen mot sina lärjungar och sade: »Se här är min moder, och här äro mina bröder!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 50, 'Ty var och en som gör min himmelske Faders vilja, den är min broder och min syster och min moder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 1, 'Samma dag gick Jesus ut från huset där han bodde och satte sig vid sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 2, 'Då församlade sig mycket folk omkring honom. Därför steg han i en båt; och han satt i den, medan allt folket stod på stranden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 3, 'Och han talade till dem mycket i liknelser; han sade: »En såningsman gick ut för att så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 4, 'Och när han sådde, föll somt vid vägen, och fåglarna kommo och åto upp det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 5, 'Och somt föll på stengrund, där det icke hade mycket jord, och det kom strax upp, eftersom det icke hade djup jord;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 6, 'men när solen hade gått upp, förbrändes det, och eftersom det icke hade någon rot, torkade det bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 7, 'Och somt föll bland törnen, och törnena sköto upp och förkvävde det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 8, 'Men somt föll i god jord, och det gav frukt, dels hundrafalt, dels sextiofalt, dels trettiofalt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 9, 'Den som har öron, han höre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 10, 'Då trädde lärjungarna fram och sade till honom: »Varför talar du till dem i liknelser?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 11, 'Han svarade och sade: »Eder är givet att lära känna himmelrikets hemligheter, men dem är det icke givet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 12, 'Ty den som har, åt honom skall varda givet, så att han får över nog; men den som icke har, från honom skall tagas också det han har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 13, 'Därför talar jag till dem i liknelser, eftersom de med seende ögon intet se, och med hörande öron intet höra, och intet heller förstå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 14, 'Så fullbordas på dem Esaias\' profetia, den som säger: \'Med hörande öron skolen I höra, och dock alls intet förstå, och med seende ögon skolen I se, och dock alls intet förnimma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 15, 'Ty detta folks hjärta har blivit förstockat, och med öronen höra de illa, och sina ögon hava de tillslutit, så att de icke se med sina ögon, eller höra med sina öron, eller förstå med sina hjärtan, och omvända sig och bliva helade av mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 16, 'Men saliga äro edra ögon, som se, och edra öron, som höra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 17, 'Ty sannerligen säger jag eder: Många profeter och rättfärdiga män åstundade att se det som I sen, men fingo dock icke se det, och att höra det som I hören, men fingo dock icke höra det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 18, 'Hören alltså I vad som menas med liknelsen om såningsmannen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 19, 'När någon hör ordet om riket, men icke förstår det, då kommer den onde och river bort det som såddes i hans hjärta. Om en sådan människa kan det sägas att säden såddes vid vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 20, 'Och att den såddes på stengrunden, det är sagt om den som väl hör ordet och strax tager emot det med glädje,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 21, 'men som icke har någon rot i sig, utan bliver beståndande allenast till en tid, och när bedrövelse eller förföljelse påkommer för ordets skull, då kommer han strax på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 22, 'Och att den såddes bland törnena, det är sagt om den som väl hör ordet, men låter tidens omsorger och rikedomens bedrägliga lockelse förkväva det, så att han bliver utan frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 23, 'Men att den såddes i den goda jorden, det är sagt om den som både hör ordet och förstår det, och som jämväl bär frukt och giver dels hundrafalt, dels sextiofalt, dels trettiofalt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 24, 'En annan liknelse framställde han för dem; han sade: »Med himmelriket är det, såsom när en man sådde god säd i sin åker;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 25, 'men när folket sov, kom hans ovän och sådde ogräs mitt ibland vetet och gick sedan sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 26, 'När nu säden sköt upp och satte frukt, så visade sig ock ogräset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 27, 'Då trädde husbondens tjänare fram och sade till honom: \'Herre, du sådde ju god säd i din åker; varifrån har den då fått ogräs?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 28, 'Han svarade dem: \'En ovän har gjort detta.\' Tjänarna sade till honom: \'Vill du alltså att vi skola gå åstad och samla det tillhopa?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 29, 'Men han svarade: \'Nej; ty då kunden I rycka upp vetet jämte ogräset, när I samlen detta tillhopa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 30, 'Låten båda slagen växa tillsammans intill skördetiden; och när skördetiden är inne, vill jag säga till skördemännen: \'Samlen först tillhopa ogräset, och binden det i knippor till att brännas upp, och samlen sedan in vetet i min lada.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 31, 'En annan liknelse framställde han för dem; han sade: »Himmelriket är likt ett senapskorn som en man tager och lägger ned i sin åker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 32, 'Det är minst av alla frön, men när det har växt upp, är det störst bland kryddväxter; ja, det bliver ett träd, så att himmelens fåglar komma och bygga sina nästen på dess grenar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 33, 'En annan liknelse framställde han för dem: »Himmelriket är likt en surdeg som en kvinna tager och blandar in i tre skäppor[1] mjöl, till dess alltsammans bliver syrat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 34, 'Allt detta talade Jesus i liknelser till folket, och utan liknelser talade han intet till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 35, 'Ty det skulle fullbordas, som var sagt genom profeten som sade: »Jag vill öppna min mun till liknelser, uppenbara vad förborgat har varit från världens begynnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 36, 'Därefter lät han folket gå och gick själv hem. Och hans lärjungar trädde fram till honom och sade: »Uttyd för oss liknelsen om ogräset i åkern.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 37, 'Han svarade och sade: »Den som sår den goda säden är Människosonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 38, 'Åkern är världen. Den goda säden, det är rikets barn, men ogräset är ondskans barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 39, 'Ovännen, som sådde det, är djävulen. Skördetiden är tidens ände. Skördemännen är änglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 40, 'Såsom nu ogräset samlas tillhopa och brännes upp i eld, så skall det ock ske vid tidens ände.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 41, 'Människosonen skall då sända ut sina änglar, och de skola samla tillhopa och föra bort ur hans rike alla dem som äro andra till fall, och dem som göra vad orätt är,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 42, 'och skola kasta dem i den brinnande ugnen; där skall vara gråt och tandagnisslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 43, 'Då skola de rättfärdiga lysa såsom solen, i sin Faders rike. Den som har öron, han höre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 44, 'Himmelriket är likt en skatt som har blivit gömd i en åker. Och en man finner den, men håller det hemligt; och i sin glädje går han bort och säljer allt vad han äger och köper den åkern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 45, 'Ytterligare är det med himmelriket, såsom när en köpman söker efter goda pärlor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 46, 'och då han har funnit en dyrbar pärla, går han bort och säljer vad han äger och köper den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 47, 'Ytterligare är det med himmelriket, såsom när en not kastas i havet och samlar tillhopa fiskar av alla slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 48, 'När den så bliver full, drager man upp den på stranden och sätter sig ned och samlar de goda i kärl, men de dåliga kastar man bort. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 49, 'Så skall det ock ske vid tidens ände: änglarna skola gå ut och skilja de onda från de rättfärdiga');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 50, 'och kasta dem i den brinnande ugnen; där skall vara gråt och tandagnisslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 51, 'Haven I förstått allt detta?» De svarade honom: »Ja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 52, 'Då sade han till dem: »Så är nu var skriftlärd, som har blivit en lärjunge för himmelriket, lik en husbonde som ur sitt förråd bär fram nytt och gammalt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 53, 'När Jesus hade framställt alla dessa liknelser, drog han bort därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 54, 'Och han kom till sin fädernestad, och där undervisade han folket i deras synagoga, så att de häpnade och sade: »Varifrån har han fått denna vishet? Och hans kraftgärningar, varifrån komma de?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 55, 'Är då denne icke timmermannens son? Heter icke hans moder Maria, och heta icke hans bröder Jakob och Josef och Simon och Judas?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 56, 'Och hans systrar, bo de icke alla hos oss? Varifrån har han då fått allt detta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 57, 'Så blev han för dem en stötesten. Men Jesus sade till dem: »En profet är icke föraktad utom i sin fädernestad och i sitt eget hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 58, 'Och för deras otros skull gjorde han där icke många kraftgärningar. [1] Se Skäppa i Ordförklaringarna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 1, 'Vid den tiden fick Herodes, landsfursten, höra ryktet om Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 2, 'Då sade han till sina tjänare: »Det är Johannes döparen. Han har uppstått från de döda, och därför verka dessa krafter i honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 3, 'Herodes hade nämligen låtit gripa Johannes och binda honom och sätta honom i fängelse, för Herodias\', sin broder Filippus\' hustrus, skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 4, 'Ty Johannes hade sagt till honom: »Det är icke lovligt för dig att hava henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 5, 'Och han hade velat döda honom, men han fruktade för folket, eftersom de höllo honom för en profet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 6, 'Men så kom Herodes\' födelsedag. Då dansade Herodias\' dotter inför dem; och hon behagade Herodes så mycket,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 7, 'att han med en ed lovade att giva henne vad helst hon begärde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 8, 'Hon sade då, såsom hennes moder ingav henne: »Giv mig här på ett fat Johannes döparens huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 9, 'Då blev konungen bekymrad, men för edens och för bordsgästernas skull bjöd han att man skulle giva henne det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 10, 'och sände åstad och lät halshugga Johannes i fängelset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 11, 'Och hans huvud blev framburet på ett fat och givet åt flickan; och hon bar det till sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 12, 'Men hans lärjungar kommo och togo hans döda kropp och begrovo honom. Sedan gingo de och omtalade det för Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 13, 'Då Jesus hörde detta, for han i en båt därifrån bort till en öde trakt, där de kunde vara allena. Men när folket fick höra härom, kommo de landvägen efter honom från städerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 14, 'Och då han steg i land, fick han se att där var mycket folk; och han ömkade sig över dem och botade deras sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 15, 'Men när det led mot aftonen, trädde hans lärjungar fram till honom och sade: »Trakten är öde, och tiden är redan framskriden. Låt folket skiljas åt, så att de kunna gå bort i byarna och köpa sig mat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 16, 'Men Jesus sade till dem: »De behöva icke gå bort; given I dem att äta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 17, 'De svarade honom: »Vi hava här icke mer än fem bröd och två fiskar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 18, 'Då sade han: »Bären dem hit till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 19, 'Därefter tillsade han folket att lägga sig ned i gräset. Och han tog de fem bröden och de två fiskarna och såg upp till himmelen och välsignade dem. Och han bröt bröden och gav dem åt lärjungarna, och lärjungarna gåvo åt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 20, 'Och de åto alla och blevo mätta Sedan samlade man upp de överblivna styckena, tolv korgar fulla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 21, 'Men de som hade ätit voro vid pass fem tusen män, förutom kvinnor och barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 22, 'Strax därefter nödgade han sina lärjungar att stiga i båten och före honom fara över till andra stranden, medan han tillsåg att folket skildes åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 23, 'Och sedan detta hade skett, gick han upp på berget för att vara allena och bedja. När det så hade blivit afton, var han där ensam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 24, 'Båten var då redan många stadier[1] från land och hårt ansatt av vågorna, ty vinden låg emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 25, 'Men under fjärde nattväkten kom Jesus till dem, gående fram över sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 26, 'När då lärjungarna fingo se honom gå på sjön, blevo de förfärade och sade: »Det är en vålnad», och ropade av förskräckelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 27, 'Men Jesus begynte strax tala till dem och sade: »Varen vid gott mod; det är jag, varen icke förskräckta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 28, 'Då svarade Petrus honom och sade: »Herre, är det du, så bjud mig att komma till dig på vattnet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 29, 'Han sade: »Kom.» Då steg Petrus ut ur båten och begynte gå på vattnet och kom till Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 30, 'Men när han såg huru stark vinden var, blev han förskräckt; och då han nu begynte sjunka, ropade han och sade: »Herre, hjälp mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 31, 'Och strax räckte Jesus ut handen och fattade i honom och sade till honom: »Du klentrogne, varför tvivlade du?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 32, 'När de sedan hade kommit upp i båten, lade sig vinden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 33, 'Men de som voro i båten föllo ned för honom och sade: »Förvisso är du Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 34, 'När de hade farit över, kommo de till Gennesarets land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 35, 'Då nu folket där på orten kände igen honom, sände de ut bud i hela trakten däromkring, och man förde till honom alla som voro sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 36, 'Och de bådo honom att allenast få röra vid hörntofsen på hans mantel; och alla som rörde vid den blevo hulpna. [1] Se Stadie i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 1, 'Härefter kommo fariséer och skriftlärde från Jerusalem till Jesus och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 2, '»Varför överträda dina lärjungar de äldstes stadgar? De två ju icke sina händer, när de skola äta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 3, 'Men han svarade och sade till dem: »Varför överträden I själva Guds bud, för edra stadgars skull?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 4, 'Gud har ju sagt: \'Hedra din fader och din moder\' och: \'Den som smädar sin fader eller sin moder, han skall döden dö.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 5, 'Men I sägen, att om någon säger till sin fader eller sin moder: \'Vad du av mig kunde hava fått till hjälp, det giver jag i stället såsom offergåva\', då behöver han alls icke hedra sin fader eller sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 6, 'I haven så gjort Guds budord om intet, för edra stadgars skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 7, 'I skrymtare, rätt profeterade Esaias om eder, när han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 8, '\'Detta folk ärar mig med sina läppar, men deras hjärtan äro långt ifrån mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 9, 'och fåfängt dyrka de mig, eftersom de läror de förkunna äro människobud.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 10, 'Och han kallade folket till sig och sade till dem: »Hören och förstån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 11, 'Icke vad som går in i munnen orenar människan, men vad som går ut ifrån munnen, det orenar människan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 12, 'Då trädde hans lärjungar fram och sade till honom: »Vet du, att när fariséerna hörde det du nu sade, var det för dem en stötesten?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 13, 'Men han svarade och sade: »Var planta som min himmelske Fader icke har planterat skall ryckas upp med rötterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 14, 'Frågen icke efter dem. De äro blinda ledare; och om en blind leder en blind, så falla de båda i gropen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 15, 'Då tog Petrus till orda och sade till honom: »Uttyd för oss detta bildliga tal.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 16, 'Han sade: »Ären då också I ännu utan förstånd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 17, 'Insen I icke att allt som går in i munnen, det går ned i buken och har sin naturliga utgång?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 18, 'Men vad som går ut ifrån munnen, det kommer från hjärtat, och det är detta som orenar människan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 19, 'Ty från hjärtat komma onda tankar, mord, äktenskapsbrott, otukt, tjuveri, falskt vittnesbörd, hädelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 20, 'Det är detta som orenar människan; men att äta med otvagna händer, det orenar icke människan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 21, 'Och Jesus begav sig bort därifrån och drog sig undan till trakten av Tyrus och Sidon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 22, 'Då kom en kananeisk kvinna från det området och ropade och sade: »Herre, Davids son, förbarma dig över mig. Min dotter plågas svårt av en ond ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 23, 'Men han svarade henne icke ett ord. Då trädde hans lärjungar fram och bådo honom och sade: »Giv henne besked; hon förföljer oss ju med sitt ropande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 24, 'Han svarade och sade: »Jag är icke utsänd till andra än till de förlorade fåren av Israels hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 25, 'Men hon kom fram och föll ned för honom och sade: »Herre, hjälp mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 26, 'Då svarade han och sade: »Det är otillbörligt att taga brödet från barnen och kasta det åt hundarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 27, 'Hon sade: »Ja, Herre. Också äta ju hundarna allenast av de smulor som falla ifrån deras herrars bord.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 28, 'Då svarade Jesus och sade till henne: »O kvinna, din tro är stor. Ske dig såsom du vill.» Och hennes dotter var frisk ifrån den stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 29, 'Men Jesus gick därifrån vidare och kom till Galileiska sjön. Och han gick upp på berget och satte sig där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 30, 'Då kom mycket folk till honom, och de hade med sig halta, blinda, dövstumma, lytta och många andra; dem lade de ned för hans fötter, och han botade dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 31, 'så att folket förundrade sig, när de funno dövstumma tala, lytta vara friska och färdiga, halta gå och blinda se. Och man prisade Israels Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 32, 'Och Jesus kallade sina lärjungar till sig och sade: »Jag ömkar mig över folket, ty det är redan tre dagar som de hava dröjt kvar hos mig, och de hava intet att äta; och jag vill icke låta dem gå ifrån mig fastande, för att de icke skola uppgivas på vägen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 33, 'Då sade lärjungarna till honom: »Varifrån skola vi här, i en öken, få så mycket bröd, att vi kunna mätta så mycket folk?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 34, 'Jesus frågade dem: »Huru många bröd haven I?» De svarade: »Sju, och därtill några få småfiskar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 35, 'Då tillsade han folket att lägra sig på marken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 36, 'Och han tog de sju bröden, så ock fiskarna, och tackade Gud och bröt bröden och gav åt lärjungarna, och lärjungarna gåvo åt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 37, 'Så åto de alla och blevo mätta. Och de överblivna styckena samlade man sedan upp, sju korgar fulla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 38, 'Men de som hade ätit voro fyra tusen män, förutom kvinnor och barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 39, 'Sedan lät han folket skiljas åt och steg i båten och for till Magadans område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 1, 'Och fariséerna och sadducéerna kommo dit och ville sätta honom på prov; de begärde att han skulle låta dem se något tecken från himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 2, 'Men han svarade och sade till dem: »Om aftonen sägen I: \'Det bliver klart väder, ty himmelen är röd\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 3, 'och om morgonen: \'Det bliver oväder i dag, ty himmelen är mulen och röd.\' Ja, om himmelens utseende förstån I att döma, men om tidernas tecken kunnen I icke döma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 4, 'Ett ont och trolöst släkte är detta! Det åstundar ett tecken, men intet annat tecken skall givas det än Jonas\' tecken.» Och så lämnade han dem och gick sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 5, 'När sedan lärjungarna foro åstad, över till andra stranden, hade de förgätit att taga med sig bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 6, 'Och Jesus sade till dem: »Sen till, att I tagen eder till vara för fariséernas och sadducéernas surdeg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 7, 'Då talade de med varandra och sade: »Det är därför att vi icke hava tagit med oss bröd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 8, 'Men när Jesus märkte detta, sade han: »I klentrogne, varför talen I eder emellan om att I icke haven bröd med eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 9, 'Förstån I ännu ingenting? Och kommen I icke ihåg de fem bröden åt de fem tusen, och huru många korgar I då togen upp?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 10, 'Ej heller de sju bröden åt de fyra tusen, och huru många korgar I då togen upp?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 11, 'Huru kommer det då till, att I icke förstån att det ej var om bröd som jag talade till eder? Tagen eder till vara för fariséernas och sadducéernas surdeg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 12, 'Då förstodo de att det icke var för surdeg i bröd som han hade bjudit dem att taga sig till vara, utan för fariséernas och sadducéernas lära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 13, 'Men när Jesus kom till trakten av Cesarea Filippi, frågade han sina lärjungar och sade: »Vem säger folket Människosonen vara?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 14, 'De svarade: »Somliga säga Johannes döparen, andra Elias, andra åter Jeremias eller en annan av profeterna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 15, 'Då frågade han dem: »Vem sägen då I mig vara?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 16, 'Simon Petrus svarade och sade: »Du är Messias, den levande Gudens Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 17, 'Då svarade Jesus och sade till honom: »Salig är du, Simon, Jonas\' son; ty kött och blod har icke uppenbarat detta för dig, utan min Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 18, 'Så säger ock jag dig att du är Petrus; och på denna klippa[1] skall jag bygga min församling, och dödsrikets portar skola icke bliva henne övermäktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 19, 'Jag skall giva dig himmelrikets nycklar: allt vad du binder på jorden, det skall vara bundet i himmelen; och allt vad du löser på jorden, det skall vara löst i himmelen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 20, 'Därefter förbjöd han lärjungarna att för någon säga att han var Messias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 21, 'Från den tiden begynte Jesus förklara för sina lärjungar, att han måste gå till Jerusalem och lida mycket av de äldste och översteprästerna och de skriftlärde, och att han skulle bliva dödad, men att han på tredje dagen skulle uppstå igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 22, 'Då tog Petrus honom avsides och begynte ivrigt motsäga honom och sade: »Bevare dig Gud, Herre! Ingalunda får detta vederfaras dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 23, 'Men han vände sig om och sade till Petrus: »Gå bort, Satan, och stå mig icke i vägen; du är för mig en stötesten, ty dina tankar äro icke Guds tankar, utan människotankar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 24, 'Därefter sade Jesus till sina lärjungar: »Om någon vill efterfölja mig, så försake han sig själv och tage sitt kors på sig: så följe han mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 25, 'Ty den som vill bevara sitt liv, han skall mista det; men den som mister sitt liv, för min skull, han skall finna det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 26, 'Och vad hjälper det en människa, om hon vinner hela världen, men förlorar sin själ? Eller vad kan en människa giva till lösen för sin själ?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 27, 'Människosonen skall komma i sin Faders härlighet med sina änglar, och då skall han vedergälla var och en efter hans gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 28, 'Sannerligen säger jag eder: Bland dem som här stå finnas några som icke skola smaka döden, förrän de få se Människosonen komma i sitt rike.» [1] Klippa heter på grekiska petra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 1, 'Sex dagar därefter tog Jesus med sig Petrus och Jakob och Johannes, Jakobs broder, och förde dem upp på ett högt berg, där de voro allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 2, 'Och hans utseende förvandlades inför dem: hans ansikte sken såsom solen, och hans kläder blevo vita såsom ljuset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 3, 'Och se, för dem visade sig Moses och Elias, i samtal med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 4, 'Då tog Petrus till orda och sade till Jesus: »Herre, här är oss gott att vara[1]; vill du, så skall jag här göra tre hyddor, åt dig en och åt Moses en och åt Elias en.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 5, 'Och se, medan han ännu talade, överskyggade dem en ljus sky, och ur skyn kom en röst som sade: »Denne är min älskade Son, i vilken jag har funnit behag; hören honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 6, 'När lärjungarna hörde detta, föllo de ned på sina ansikten i stor förskräckelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 7, 'Men Jesus gick fram och rörde vid dem och sade: »Stån upp, och varen icke förskräckta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 8, 'När de då lyfte upp sina ögon, sågo de ingen utom Jesus allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 9, 'Då de sedan gingo ned från berget, bjöd Jesus dem och sade: »Omtalen icke för någon denna syn, förrän Människosonen har uppstått från de döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 10, 'Men lärjungarna frågade honom och sade: »Huru kunna då de skriftlärde säga att Elias först måste komma?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 11, 'Han svarade och sade: »Elias måste visserligen komma och upprätta allt igen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 12, 'men jag säger eder att Elias redan har kommit. Men de ville icke veta av honom, utan förforo mot honom alldeles såsom de ville. Sammalunda skall ock Människosonen få lida genom dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 13, 'Då förstodo lärjungarna att det var om Johannes döparen som han talade till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 14, 'När de därefter kommo till folket, trädde en man fram till honom och föll på knä för honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 15, 'och sade: »Herre, förbarma dig över min son ty han är månadsrasande och plågas svårt; ofta faller han i elden och ofta i vattnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 16, 'Och jag förde honom till dina lärjungar, men de kunde icke bota honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 17, 'Då svarade Jesus och sade: »O du otrogna och vrånga släkte, huru länge måste jag vara bland eder? Huru länge måste jag härda ut med eder? Fören honom hit till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 18, 'Och Jesus tilltalade honom strängt, och den onde anden for ut ur honom; och gossen var botad från den stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 19, 'Sedan, när de voro allena, trädde lärjungarna fram till Jesus och frågade: »Varför kunde icke vi driva ut honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 20, 'Han svarade dem: »För eder otros skull. Ty sannerligen säger jag eder: Om I haven tro, vore den ock blott såsom ett senapskorn, så skolen I kunna säga till detta berg: \'Flytta dig härifrån dit bort\', och det skall flytta sig; ja, intet skall då vara omöjligt för eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 21, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 22, 'Medan de nu tillsammans vandrade omkring i Galileen, sade Jesus till dem: »Människosonen skall bliva överlämnad i människors händer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 23, 'och man skall döda honom, men på tredje dagen skall han uppstå igen.» Då blevo de mycket bedrövade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 24, 'Och när de hade kommit till Kapernaum, trädde de som uppburo tempelskatten fram till Petrus och sade: »Plägar icke eder mästare betala tempelskatt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 25, 'Han svarade: »Jo.» När han sedan hade kommit hem, förekom honom Jesus med frågan: »Vad synes dig, Simon? Av vilka taga jordens konungar tull eller skatt, av sina söner eller av andra människor?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 26, 'Han svarade: »Av andra människor.» Då sade Jesus till honom: »Alltså äro då sönerna fria.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 27, 'Men för att vi icke skola bliva dem till en stötesten, så gå ned till sjön och kasta ut en krok. Tag så den första fisk som du drager upp, och när du öppnar munnen på den skall du där finna en silverpenning[3]. Tag den, och giv den åt dem for mig och dig.» [1] Eller: Då tog Petrus till orda och sade till Jesus: »Herre, det är gott att vi äro här tillstädes» osv. [2] Se Nya testamentets text i Ordförklaringarna. [3] Se Silverpenning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 1, 'I samma stund trädde lärjungarna fram till Jesus och frågade: »Vilken är den störste i himmelriket?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 2, 'Då kallade han fram ett barn och ställde det mitt ibland dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 3, 'och sade: »Sannerligen säger jag eder: Om I icke omvänden eder och bliven såsom barn, skolen I icke komma in i himmelriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 4, 'Den som nu så ödmjukar sig, att han bliver såsom detta barn, han är den störste i himmelriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 5, 'Och den som tager emot ett sådant barn I mitt namn, han tager emot mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 6, 'Men den som förför en av dessa små som tro på mig, för honom vore det bättre att en kvarnsten hängdes om hans hals och han sänktes ned i havets djup.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 7, 'Ve världen för förförelsers skull! Förförelser måste ju komma; men ve den människa genom vilken förförelsen kommer!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 8, 'Om nu din hand eller din fot är dig till förförelse, så hugg av den och kasta den ifrån dig. Det är bättre för dig att ingå i livet lytt eller halt, än att hava båda händerna eller båda fötterna i behåll och kastas i den eviga elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 9, 'Och om ditt öga är dig till förförelse, så riv ut det och kasta det ifrån dig. Det är bättre för dig att ingå i livet enögd, än att hava båda ögonen i behåll och kastas i det brinnande Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 10, 'Sen till, att I icke förakten någon av dessa små; ty jag säger eder att deras änglar i himmelen alltid se min himmelske Faders ansikte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 11, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 12, 'Vad synes eder? Om en man har hundra får, och ett av dem har kommit vilse, lämnar han icke då de nittionio på bergen och går åstad och söker efter det som har kommit vilse?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 13, 'Och händer det då att han finner det -- sannerligen säger jag eder: då gläder han sig mer över det fåret än över de nittionio som icke hade kommit vilse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 14, 'Så är det ej heller eder himmelske Faders vilja att någon av dessa små skall gå förlorad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 15, 'Men om din broder försyndar sig, så gå åstad och förehåll honom det enskilt. Om han då lyssnar till dig, så har du vunnit din broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 16, 'Men om han icke lyssnar till dig, så tag med dig ännu en eller två, för att \'var sak må avgöras efter två eller tre vittnens utsago\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 17, 'Lyssnar han icke till dem, så säg det till församlingen. Lyssnar han ej heller till församlingen, så vare han för dig såsom en hedning och en publikan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 18, 'Sannerligen säger jag eder: Allt vad I binden på jorden, det skall vara bundet i himmelen; och allt vad I lösen på jorden, det skall vara löst i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 19, 'Ytterligare säger jag eder, att om två av eder här på jorden komma överens att bedja om något, vad det vara må, så skall det beskäras dem av min Fader, som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 20, 'Ty var två eller tre är församlade i mitt namn, där är jag mitt ibland dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 21, 'Då trädde Petrus fram och sade till honom: »Herre, huru många gånger skall jag förlåta min broder, om han försyndar sig mot mig? Är sju gånger nog?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 22, 'Jesus svarade honom: »Jag säger dig: Icke sju gånger, utan sjuttio gånger sju gånger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 23, 'Alltså är det med himmelriket, såsom när en konung ville hålla räkenskap med sina tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 24, 'Och när han begynte hålla räkenskap, förde man fram till honom en som var skyldig honom tio tusen pund[2].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 25, 'Men då denna icke kunde betala, bjöd hans herre att han skulle säljas, så ock hans hustru och barn och allt vad han ägde, för att skulden måtte bliva betald.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 26, 'Då föll tjänaren ned för hans fötter och sade: \'Hav tålamod med mig, så skall jag betala dig alltsammans.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 27, 'Och tjänarens herre ömkade sig över honom och gav honom fri och efterskänkte honom hans skuld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 28, 'Men när samme tjänare kom ut, träffade han på en av sina medtjänare, som var skyldig honom hundra silverpenningar[3]; och han tog fast denne och grep honom vid strupen och sade: \'Betala vad du är skyldig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 29, 'Då föll hans medtjänare ned och bad honom och sade: \'Hav tålamod med mig, så skall jag betala dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 30, 'Men han ville icke, utan gick åstad och lät sätta honom i fängelse, till dess han hade betalt vad han var skyldig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 31, 'Då nu hans medtjänare sågo det som skedde, togo de mycket illa vid sig och gingo och berättade för sin herre allt som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 32, 'Då kallade hans herre honom till sig och sade till honom: \'Du onde tjänare, allt vad du var skyldig efterskänkte jag dig, eftersom du bad mig därom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 33, 'Borde då icke också du hava förbarmat dig över din medtjänare, såsom jag förbarmade mig över dig?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 34, 'Och i sin vrede överlämnade hans herre honom i fångknektarnas våld, intill dess han hade betalt allt vad han var skyldig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 35, 'Så skall ock min himmelske Fader göra med eder, om I icke av hjärtat förlåten var och en sin broder.» [1] Se Nya testamentets text i Ordförklaringarna. [2] Se Pund i Ordförklaringarna. [3] Se Silverpenningar i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 1, 'När Jesus hade slutat detta tal, drog han bort ifrån Galileen och begav sig, genom landet på andra sidan Jordan, till Judeens område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 2, 'Och mycket folk följde honom, och han botade där de sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 3, 'Då ville några fariséer snärja honom och trädde fram till honom och sade: »Är det lovligt att skilja sig från sin hustru av vilken orsak som helst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 4, 'Men han svarade och sade: »Haven I icke läst att Skaparen redan i begynnelsen \'gjorde dem till man och kvinna\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 5, 'och sade: \'Fördenskull skall en man övergiva sin fader och sin moder och hålla sig till sin hustru, och de tu skola varda ett kött\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 6, 'Så äro de icke mer två, utan ett kött. Vad nu Gud har sammanfogat, det må människan icke åtskilja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 7, 'Då sade de till honom: »Huru kunde då Moses bjuda att man skulle giva hustrun skiljebrev och så skilja sig från henne?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 8, 'Han svarade dem: »För edra hjärtans hårdhets skull tillstadde Moses eder att skiljas från edra hustrur, men från begynnelsen har det icke varit så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 9, 'Och jag säger eder: Den som för någon annan orsaks skull än för otukt skiljer sig från sin hustru och tager sig en annan hustru, han begår äktenskapsbrott.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 10, 'Då sade lärjungarna till honom: »Är det så med mannens ställning till hustrun, då är det icke rådligt att gifta sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 11, 'Men han svarade dem: »Icke alla kunna taga emot det ordet, utan allenast de åt vilka sådant är givet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 12, 'Ty visserligen finnas somliga som genom födelsen, allt ifrån moderlivet, äro oskickliga till äktenskap, andra åter som av människor hava gjorts oskickliga därtill, men somliga finnas ock, som för himmelrikets skull självmant hava gjort sig oskickliga därtill. Den som kan taga emot detta, han tage emot det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 13, 'Därefter buros barn fram till honom, för att han skulle lägga händerna på dem och bedja; men lärjungarna visade bort dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 14, 'Då sade Jesus: »Låten barnen vara, och förmenen dem icke att komma till mig; ty himmelriket hör sådana till.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 15, 'Och han lade händerna på dem och gick sedan därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 16, 'Då trädde en man fram till honom och sade: »Mästare, vad gott skall jag göra för att få evigt liv?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 17, 'Han sade till honom: »Varför frågar du mig om vad som är gott? En finnes som är god. Men vill du ingå i livet, så håll buden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 18, 'Han frågade: »Vilka?» Jesus svarade: »\'Du skall icke dräpa\', \'Du skall icke begå äktenskapsbrott\', \'Du skall icke stjäla\', \'Du skall icke bära falskt vittnesbörd\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 19, '\'Hedra din fader och din moder\' och \'Du skall älska din nästa såsom dig själv.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 20, 'Då sade den unge mannen till honom: »Allt detta har jag hållit. Vad fattas mig ännu?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 21, 'Jesus svarade honom: »Vill du vara fullkomlig, så gå bort och sälj vad du äger och giv åt de fattiga; då skall du få en skatt i himmelen. Och kom sedan och följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 22, 'Men när den unge mannen hörde detta, gick han bedrövad bort, ty han hade många ägodelar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 23, 'Då sade Jesus till sina lärjungar: »Sannerligen säger jag eder: För den som är rik är det svårt att komma in i himmelriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 24, 'Ja, jag säger eder: Det är lättare för en kamel att komma in genom ett nålsöga, än för den som är rik att komma in i Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 25, 'När lärjungarna hörde detta, blevo de mycket häpna och sade: »Vem kan då bliva frälst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 26, 'Men Jesus såg på dem och sade till dem: »För människor är detta omöjligt, men för Gud är allting möjligt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 27, 'Då tog Petrus till orda och sade till honom: »Se, vi hava övergivit allt och följt dig; vad skola vi få därför?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 28, 'Jesus svarade dem: »Sannerligen säger jag eder: När världen födes på nytt, då när Människosonen sätter sig på sin härlighets tron, då skolen också I, som haven efterföljt mig, få sitta på tolv troner såsom domare över Israels tolv stammar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 29, 'Och var och en som har övergivit hus, eller bröder eller systrar, eller fader eller moder, eller barn, eller jordagods, för mitt namns skull, han skall få mångfaldigt igen, och skall få evigt liv till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 30, 'Men många som äro de första skola bliva de sista, och många som äro de sista skola bliva de första.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 1, '»Ty med himmelriket är det, såsom när en husbonde bittida om morgonen gick ut för att leja åt sig arbetare till sin vingård.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 2, 'Och när han hade kommit överens med arbetarna om en viss dagspenning[1], sände han dem till sin vingård.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 3, 'När han sedan gick ut vid tredje timmen, fick han se några andra stå sysslolösa på torget;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 4, 'och han sade till dem: \'Gån ock I till min vingård, så skall jag giva eder vad skäligt är.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 5, 'Och de gingo. Åter gick han ut vid sjätte timmen och vid nionde och gjorde sammalunda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 6, 'Också vid elfte timmen gick han ut och fann då några andra stå där; och han sade till dem: \'Varför stån I här hela dagen sysslolösa?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 7, 'De svarade honom: \'Därför att ingen har lejt oss.\' Då sade han till dem: \'Gån ock I till min vingård.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 8, 'När det så hade blivit afton, sade vingårdens herre till sin förvaltare: \'Kalla fram arbetarna och giv dem deras lön, men begynn med de sista och gå så tillbaka ända till de första.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 9, 'Då nu de kommo fram, som voro lejda vid elfte timmen, fick var och en av dem full dagspenning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 10, 'När sedan de första kommo, trodde de att de skulle få mer, men också var och en av dem fick samma dagspenning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 11, 'När de så fingo, knorrade de mot husbonden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 12, 'och sade: \'Dessa sista hava arbetat allenast en timme, och du har ändå ställt dem lika med oss, som hava burit dagens tunga och solens hetta?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 13, 'Då svarade han en av dem och sade: \'Min vän, jag gör dig ingen orätt. Kom du icke överens med mig om den dagspenningen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 14, 'Tag vad dig tillkommer och gå. Men åt denne siste vill jag giva lika mycket som åt dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 15, 'Har jag icke lov att göra såsom jag vill med det som är mitt? Eller skall du med onda ögon se på att jag är så god?\' --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 16, 'Så skola de sista bliva de första, och de första bliva de sista.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 17, 'Då nu Jesus ville gå upp till Jerusalem, tog han till sig de tolv, så att de voro allena; och under vägen sade han till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 18, '»Se, vi gå nu upp till Jerusalem, och Människosonen skall bliva överlämnad åt översteprästerna och de skriftlärde, och de skola döma honom till döden');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 19, 'och överlämna honom åt hedningarna till att begabbas och gisslas och korsfästas; men på tredje dagen skall han uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 20, 'Då trädde Sebedeus\' söners moder fram till honom med sina söner och föll ned för honom och ville begära något av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 21, 'Han frågade henne: »Vad vill du?» Hon svarade honom: »Säg att i ditt rike den ene av dessa mina två söner skall få sitta på din högra sida, och den andre på din vänstra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 22, 'Men Jesus svarade och sade: »I veten icke vad I begären. Kunnen I dricka den kalk som jag skall dricka?» De svarade honom: »Det kunna vi.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 23, 'Då sade han till dem: »Ja, väl skolen I få dricka min kalk, men platsen på min högra sida och platsen på min vänstra tillkommer det icke mig att bortgiva, utan de skola tillfalla dem för vilka så är bestämt av min Fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 24, 'När de tio andra hörde detta, blevo de misslynta på de två bröderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 25, 'Då kallade Jesus dem till sig och sade: »I veten att furstarna uppträda mot sina folk såsom herrar, och att de mäktige låta folken känna sin myndighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 26, 'Så är det icke bland eder; utan den som vill bliva störst bland eder, han vare de andras tjänare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 27, 'och den som vill vara främst bland eder, han vare de andras dräng,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 28, 'likasom Människosonen har kommit, icke för att låta tjäna sig, utan för att tjäna och giva sitt liv till lösen för många.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 29, 'När de sedan gingo ut ifrån Jeriko, följde honom mycket folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 30, 'Och se, två blinda sutto där vid vägen. När dessa hörde att det var Jesus som gick där fram, ropade de och sade: »Herre, förbarma dig över oss, du Davids son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 31, 'Och folket tillsade dem strängeligen att de skulle tiga; men de ropade dess mer och sade: »Herre, förbarma dig över oss, du Davids son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 32, 'Då stannade Jesus och kallade dem till sig och sade: »Vad viljen I att jag skall göra eder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 33, 'De svarade honom: »Herre, låt våra ögon bliva öppnade.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 34, 'Då förbarmade sig Jesus över dem och rörde vid deras ögon, och strax fingo de sin syn och följde honom. [1] Se Dagspenning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 1, 'När de nu nalkades Jerusalem och kommo till Betfage vid Oljeberget, då sände Jesus åstad två lärjungar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 2, 'och sade till dem: »Gån in i byn som ligger mitt framför eder, så skolen I strax finna en åsninna stå där bunden och en fåle bredvid henne; lösen dem och fören dem till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 3, 'Och om någon säger något till eder, så skolen I svara: \'Herren behöver dem\'; då skall han strax släppa dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 4, 'Detta har skett, för att det skulle fullbordas, som var sagt genom profeten som sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 5, '»Sägen till dottern Sion: \'Se, din konung kommer till dig, saktmodig, ridande på en åsna, på en arbetsåsninnas fåle.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 6, 'Och lärjungarna gingo åstad och gjorde såsom Jesus hade befallt dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 7, 'och ledde till honom åsninnan och fålen; och de lade sina mantlar på denne, och han satte sig därovanpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 8, 'Och folkskaran, som var mycket stor, bredde ut sina mantlar på vägen; men somliga skuro kvistar av träden och strödde på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 9, 'Och folket, både de som gingo före honom och de som följde efter, ropade och sade: »Hosianna Davids son! Välsignad vare han som kommer[1], i Herrens namn. Hosianna i höjden!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 10, 'När han så drog in i Jerusalem, kom hela staden i rörelse, och man frågade: »Vem är denne?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 11, 'Och folket sade: »Det är Jesus, profeten, från Nasaret i Galileen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 12, 'Och Jesus gick in i helgedomen. Och han drev ut alla dem som sålde och köpte i helgedomen, och han stötte omkull växlarnas bord och duvomånglarnas säten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 13, 'Och han sade till dem: »Det är skrivet: \'Mitt hus skall kallas ett bönehus.\' Men I gören det till en rövarkula.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 14, 'Och blinda och halta kommo fram till honom i helgedomen, och han botade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 15, 'Men när översteprästerna och de skriftlärde sågo de under som han gjorde, och sågo barnen som ropade i helgedomen och sade: »Hosianna Davids son!», då förtröt detta dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 16, 'och de sade till honom: »Hör du vad dessa säga?» Då svarade Jesus dem: »Ja; haven I aldrig läst: \'Av barns och spenabarns mun har du berett dig lov\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 17, 'Därefter lämnade han dem och gick ut ur staden till Betania och stannade där över natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 18, 'När han sedan på morgonen gick in till staden igen, blev han hungrig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 19, 'Och då han fick se ett fikonträd vid vägen, gick han fram till det, men fann intet därpå, utom allenast löv. Då sade han till det: »Aldrig någonsin mer skall frukt växa på dig.» Och strax förtorkades fikonträdet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 20, 'När lärjungarna sågo detta, förundrade de sig och sade: »Huru kunde fikonträdet så i hast förtorkas?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 21, 'Då svarade Jesus och sade till dem: »Sannerligen säger jag eder: Om I haven tro och icke tvivlen, så skolen I icke allenast kunna göra sådant som skedde med fikonträdet, utan I skolen till och med kunna säga till detta berg: \'Häv dig upp och kasta dig i havet\', och det skall ske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 22, 'Och allt vad I med tro bedjen om i eder bön, det skolen I få.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 23, 'När han därefter hade kommit in i helgedomen, trädde översteprästerna och folkets äldste fram till honom, där han undervisade; och de sade: »Med vad myndighet gör du detta? Och vem har givit dig sådan myndighet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 24, 'Jesus svarade och sade till dem: »Också jag vill ställa en fråga till eder; om I svaren mig på den, så skall ock jag säga eder med vad myndighet jag gör detta».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 25, 'Johannes\' döpelse, varifrån var den: från himmelen eller från människor?» Då överlade de med varandra och sade: »Om vi svara: \'Från himmelen\', så frågar han oss: \'Varför trodden I honom då icke?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 26, 'Men om vi svara: \'Från människor\', då måste vi frukta för folket, ty alla hålla de Johannes för en profet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 27, 'De svarade alltså Jesus och sade: »Vi veta det icke.» Då sade ock han till dem: »Så säger icke heller jag eder med vad myndighet jag gör detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 28, 'Men vad synes eder? En man hade två söner. Och han kom till den förste och sade: \'Min son, gå i dag och arbeta i vingården.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 29, 'Han svarade och sade: \'Jag vill icke\'; men efteråt ångrade han sig och gick.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 30, 'Och han kom till den andre och sade sammalunda. Då svarade denne och sade: \'Ja, herre\'; men han gick icke,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 31, 'Vilken av de två gjorde vad fadern ville?» De svarade: »Den förste.» Jesus sade till dem: »Ja, sannerligen säger jag eder: Publikaner och skökor skola förr gå in i Guds rike än I.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 32, 'Ty Johannes kom och lärde eder rättfärdighetens väg, och I trodden honom icke, men publikaner och skökor trodde honom. Och fastän I sågen detta, ångraden I eder icke heller efteråt, så att I trodden honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 33, 'Hören nu en annan liknelse: En husbonde planterade en vingård, och han satte stängsel omkring den och högg ut ett presskar därinne och byggde ett vakttorn; därefter lejde han ut den åt vingårdsmän och for utrikes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 34, 'När sedan frukttiden nalkades, sände han sina tjänare till vingårdsmännen för att uppbära frukten åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 35, 'Men vingårdsmännen togo fatt på hans tjänare, och en misshandlade de, en annan dräpte de, en tredje stenade de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 36, 'Åter sände han åstad andra tjänare, flera än de förra, men de gjorde med dem sammalunda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 37, 'Slutligen sände han till dem sin son, ty han tänkte: \'De skola väl hava försyn för min son.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 38, 'Men när vingårdsmännen fingo se hans son, sade de till varandra: \'Denne är arvingen; kom, låt oss dräpa honom, så få vi hans arv.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 39, 'Och de togo fatt på honom och förde honom ut ur vingården och dräpte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 40, 'När nu vingårdens herre kommer, vad skall han då göra med de vingårdsmännen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 41, 'De svarade honom: »Eftersom de hava illa gjort, skall han illa förgöra dem, och vingården skall han lämna åt andra vingårdsmän, som giva honom frukten, när tiden därtill är inne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 42, 'Jesus sade till dem: »Ja, haven I aldrig läst i skrifterna: \'Den sten som byggningsmännen förkastade. den har blivit en hörnsten; av Herren har den blivit detta, och underbar är den i våra ögon\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 43, 'Därför säger jag eder att Guds rike skall tagas ifrån eder, och givas åt ett folk som bär dess frukt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 44, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 45, 'Då nu översteprästerna och fariséerna hörde hans liknelser, förstodo de att det var om dem som han talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 46, 'Och de hade gärna velat gripa honom, men de fruktade för folket, eftersom man höll honom för en profet. [1] Se Messias i Ordförklaringarna. [2] Se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 1, 'Och Jesus begynte åter tala till dem i liknelser och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 2, '»Med himmelriket är det, såsom när en konung gjorde bröllop åt sin son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 3, 'Han sände ut sina tjänare för att kalla till bröllopet dem som voro bjudna; men de ville icke komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 4, 'Åter sände han ut andra tjänare och befallde dem att säga till dem som voro bjudna: \'Jag har nu tillrett min måltid, mina oxar och min gödboskap äro slaktade, och allt är redo; kommen till bröllopet.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 5, 'Men de aktade icke därpå, utan gingo bort, den ene till sitt jordagods, den andre till sin köpenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 6, 'Och de övriga grepo hans tjänare och misshandlade och dräpte dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 7, 'Då blev konungen vred och sände ut sitt krigsfolk och förgjorde dråparna och brände upp deras stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 8, 'Därefter sade han till sina tjänare: \'Bröllopet är tillrett, men de som voro bjudna voro icke värdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 9, 'Gån därför ut till vägskälen och bjuden till bröllopet alla som I träffen på.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 10, 'Och tjänarna gingo ut på vägarna och samlade tillhopa alla som de träffade på, både onda och goda, och bröllopssalen blev full av bordsgäster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 11, 'Men när konungen nu kom in för att se på gästerna, fick han där se en man som icke var klädd i bröllopskläder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 12, 'Då sade han till honom: \'Min vän, huru har du kommit hitin, då du icke bär bröllopskläder?\' Och han kunde intet svara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 13, 'Då sade konungen till tjänarna: \'Gripen honom vid händer och fötter, och kasten honom ut i mörkret härutanför.\' Där skall vara gråt och tandagnisslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 14, 'Ty många äro kallade, men få utvalda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 15, 'Därefter gingo fariséerna bort och fattade det beslutet att de skulle söka snärja honom genom något hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 16, 'Och de sände till honom sina lärjungar, tillika med herodianerna, och läto dem säga: »Mästare, vi veta att du är sannfärdig och lär om Guds väg vad sant är, utan att fråga efter någon; ty du ser icke till personen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 17, 'Så säg oss då: Vad synes dig? Är det lovligt att giva kejsaren skatt, eller är det icke lovligt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 18, 'Men Jesus märkte deras ondska och sade: »Varför söken I att snärja mig, I skrymtare?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 19, 'Låten mig se skattepenningen.» Då lämnade de fram till honom en penning[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 20, 'Därefter frågade han dem: »Vems bild och överskrift är detta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 21, 'De svarade: »Kejsarens.» Då sade han till dem: »Så given då kejsaren vad kejsaren tillhör, och Gud vad Gud tillhör.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 22, 'När de hörde detta, förundrade de sig. Och de lämnade honom och gingo sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 23, 'Samma dag trädde några sadducéer fram till honom och ville påstå att det icke gives någon uppståndelse; de frågade honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 24, 'och sade: »Mästare, Moses har sagt: \'Om någon dör barnlös, så skall hans broder i hans ställe äkta hans hustru och skaffa avkomma åt sin broder.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 25, 'Nu voro hos oss sju bröder. Den förste tog sig hustru och dog, och eftersom han icke hade någon avkomma, lämnade han sin hustru efter sig åt sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 26, 'Sammalunda ock den andre och den tredje, allt intill den sjunde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 27, 'Sist av alla dog hustrun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 28, 'Vilken av de sju skall då vid uppståndelsen få henne till hustru? De hade ju alla äktat henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 29, 'Jesus svarade och sade till dem: »I faren vilse, ty I förstån icke skrifterna, ej heller Guds kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 30, 'Vid uppståndelsen taga män sig icke hustrur, ej heller givas hustrur åt män, utan de äro då såsom änglarna i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 31, 'Men vad nu angår de dödas uppståndelse, haven I icke läst vad eder är sagt av Gud:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 32, '\'Jag är Abrahams Gud och Isaks Gud och Jakobs Gud\'? Han är en Gud icke för döda, utan för levande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 33, 'När folket hörde detta, häpnade de över hans undervisning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 34, 'Men när fariséerna fingo höra att han hade stoppat munnen till på sadducéerna, samlade de sig tillhopa;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 35, 'och en av dem, som var lagklok, ville snärja honom och frågade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 36, '»Mästare, vilket är det yppersta budet i lagen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 37, 'Då svarade han honom: »\'Du skall älska HERREN, din Gud, av allt ditt hjärta och av all din själ och av allt ditt förstånd.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 38, 'Detta är det yppersta och förnämsta budet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 39, 'Därnäst kommer ett som är detta likt: \'Du skall älska din nästa såsom dig själv.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 40, 'På dessa två bud hänger hela lagen och profeterna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 41, 'Men då nu fariséerna voro församlade, frågade Jesus dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 42, 'och sade: »Vad synes eder om Messias, vems son är han?» De svarade honom: »Davids.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 43, 'Då sade han till dem: »Huru kan då David, genom andeingivelse, kalla honom \'herre\'? Han säger ju:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 44, '\'Herren sade till min herre: Sätt dig på min högra sida, till dess jag har lagt dina fiender under dina fötter.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 45, 'Om nu David kallar honom \'herre\', huru kan han då vara hans son?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 46, 'Och ingen förmådde svara honom ett ord. Ej heller dristade sig någon från den dagen att vidare ställa någon fråga till honom. [1] Se Penning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 1, 'Därefter talade Jesus till folket och till sina lärjungar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 2, 'och sade: »På Moses\' stol hava de skriftlärde och fariséerna satt sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 3, 'Därför, allt vad de säga eder, det skolen I göra och hålla, men efter deras gärningar skolen I icke göra; ty de säga, men göra icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 4, 'De binda ihop tunga bördor och lägga dem på människornas skuldror, men själva vilja de icke röra ett finger för att flytta dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 5, 'Och alla sina gärningar göra de för att bliva sedda av människorna. De göra sina böneremsor breda och hörntofsarna på sina mantlar stora.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 6, 'De vilja gärna hava de främsta platserna vid gästabuden och sitta främst i synagogorna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 7, 'och vilja gärna bliva hälsade på torgen och av människorna kallas \'rabbi\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 8, 'Men I skolen icke låta kalla eder \'rabbi\', ty en är eder Mästare, och I ären alla bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 9, 'Ej heller skolen I kalla någon på jorden eder \'fader\'[1], ty en är eder Fader, han som är i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 10, 'Ej heller skolen I låta kalla eder \'läromästare\', ty en är eder läromästare, Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 11, 'Den som är störst bland eder, han vare de andras tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 12, 'Men den som upphöjer sig, han skall bliva förödmjukad, och den som ödmjukar sig, han skall bliva upphöjd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 13, 'Ve eder, I skriftlärde och fariséer, I skrymtare, som tillsluten himmelriket för människorna! Själva kommen I icke ditin, och dem som vilja komma dit tillstädjen I icke att komma in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 14, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 15, 'Ve eder, I skriftlärde och fariséer, I skrymtare, som faren omkring över vatten och land för att göra en proselyt, och när någon har blivit det, gören I honom till ett Gehennas barn, dubbelt värre än I själva ären!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 16, 'Ve eder, I blinde ledare, som sägen: \'Om någon svär vid templet, så betyder det intet; men om någon svär vid guldet i templet, då är han bunden av sin ed\'!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 17, 'I dåraktige och blinde, vilket är då förmer, guldet eller templet, som har helgat guldet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 18, 'Så ock: \'Om någon svär vid altaret, så betyder det intet; men om någon svär vid offergåvan som ligger därpå, då är han bunden av sin ed.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 19, 'I blinde, vilket är då förmer, offergåvan eller altaret, som helgar offergåvan?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 20, 'Den som svär vid altaret, han svär alltså både vid detta och vid allt som ligger därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 21, 'Och den som svär vid templet, han svär både vid detta och vid honom som bor däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 22, 'Och den som svär vid himmelen, han svär både vid Guds tron och vid honom som sitter därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 23, 'Ve eder, I skriftlärde och fariséer. I skrymtare, som given tionde av mynta och dill och kummin, men underlåten det som är viktigast i lagen, nämligen rätten och barmhärtigheten och troheten! Det ena borden I göra, men icke underlåta det andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 24, 'I blinde ledare, som silen bort myggan och sväljen kamelen!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 25, 'Ve eder, I skriftlärde och fariséer, I skrymtare, som gören det yttre av bägaren och fatet rent, medan de inuti äro fulla av vad I haven förvärvat genom rofferi och omättlig ondska!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 26, 'Du blinde farisé, gör först insidan av bägaren ren, för att sedan också dess utsida må bliva ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 27, 'Ve eder, I skriftlärde och fariséer, I skrymtare, som ären lika vitmenade gravar, vilka väl utanpå synas prydliga, men inuti äro fulla av de dödas ben och allt slags orenlighet!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 28, 'Så synens ock I utvärtes för människorna rättfärdiga, men invärtes ären I fulla av skrymteri och orättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 29, 'Ve eder, I skriftlärde och fariséer, I skrymtare, som byggen upp profeternas gravar och pryden de rättfärdigas grifter');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 30, 'och sägen: \'Om vi hade levat på våra fäders tid, så skulle vi icke hava varit delaktiga med dem i profeternas blod\'!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 31, 'Så vittnen I då om eder själva, att I ären barn av dem som dräpte profeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 32, 'Nåväl, uppfyllen då I edra fäders mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 33, 'I ormar, I huggormars avföda, huru skullen I kunna söka undgå att dömas till Gehenna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 34, 'Se, därför sänder jag till eder profeter och vise och skriftlärde. Somliga av dem skolen I dräpa och korsfästa, och somliga av dem skolen I gissla i edra synagogor och förfölja ifrån den ena staden till den andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 35, 'Och så skall över eder komma allt rättfärdigt blod som är utgjutet på jorden, ända ifrån den rättfärdige Abels blod intill Sakarias\', Barakias\' sons blod, hans som I dräpten mellan templet och altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 36, 'Sannerligen säger jag eder: Allt detta skall komma över detta släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 37, 'Jerusalem, Jerusalem, du som dräper profeterna och stenar dem som äro sända till dig! Huru ofta har jag icke velat församla dina barn, likasom hönan församlar sina kycklingar under sina vingar! Men I haven icke velat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 38, 'Se, edert hus skall komma att stå övergivet och öde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 39, 'Ty jag säger eder: Härefter skolen I icke få se mig, intill den tid då I sägen: \'Välsignad vare han som kommer[3], i Herrens namn.\'» [1] Se Fader i Ordförklaringarna. [2] Se Nya testamentets text i Ordförklaringarna. [3] Se Messias i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 1, 'Och Jesus gick därifrån, ut ur helgedomen. Hans lärjungar trädde då fram och bådo honom giva akt på helgedomens byggnader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 2, 'Då svarade han och sade till dem: »Ja, I sen nu allt detta; men sannerligen säger jag eder: Här skall icke lämnas sten på sten; allt skall bliva nedbrutet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 3, 'När han sedan satt på Oljeberget, trädde hans lärjungar fram till honom, medan de voro allena, och sade: »Säg oss när detta skall ske, och vad som bliver tecknet till din tillkommelse och tidens ände.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 4, 'Då svarade Jesus och sade till dem: »Sen till, att ingen förvillar eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 5, 'Ty många skola komma under mitt namn och säga: \'Jag är Messias\' och skola förvilla många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 6, 'Och I skolen få höra krigslarm och rykten om krig; sen då till, att I icke förloren besinningen, ty sådant måste komma, men därmed är ännu icke änden inne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 7, 'Ja, folk skall resa sig upp mot folk och rike mot rike, och det skall bliva hungersnöd och jordbävningar på den ena orten efter den andra;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 8, 'men allt detta är allenast begynnelsen till \'födslovåndorna\'[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 9, 'Då skall man prisgiva eder till misshandling, och man skall dräpa eder, och I skolen bliva hatade av alla folk, för mitt namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 10, 'Och då skola många komma på fall, och den ene skall förråda den andre, och den ene skall hata den andre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 11, 'Och många falska profeter skola uppstå och skola förvilla många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 12, 'Och därigenom att laglösheten förökas, skall kärleken hos de flesta kallna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 13, 'Men den som är ståndaktig intill änden, han skall bliva frälst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 14, 'Och detta evangelium om riket skall bliva predikat i hela världen, till ett vittnesbörd för alla folk. Och sedan skall änden komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 15, 'När I nu fån se \'förödelsens styggelse\'[2], om vilken är talat genom profeten Daniel, stå på helig plats -- den som läser detta, han give akt därpå --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 16, 'då må de som äro i Judeen fly bort till bergen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 17, 'och den som är på taket må icke stiga ned för att hämta vad som finnes i hans hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 18, 'och den som är ute på marken må icke vända tillbaka för att hämta sin mantel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 19, 'Och ve dem som äro havande, eller som giva di på den tiden!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 20, 'Men bedjen att eder flykt icke må ske om vintern eller på sabbaten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 21, 'Ty då skall det bliva \'en stor vedermöda, vars like icke har förekommit allt ifrån världens begynnelse intill nu\', ej heller någonsin skall förekomma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 22, 'Och om den tiden icke bleve förkortad, så skulle intet kött bliva frälst; men för de utvaldas skull skall den tiden bliva förkortad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 23, 'Om någon då säger till eder: \'Se här är Messias\', eller: \'Där är han\', så tron det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 24, 'Ty människor som falskeligen säga sig vara Messias skola uppstå, så ock falska profeter, och de skola göra stora tecken och under, för att, om möjligt förvilla jämväl de utvalda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 25, 'Jag har nu sagt eder det förut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 26, 'Därför, om man säger till eder: \'Se, han är i öknen\', så gån icke ditut, eller: \'Se, han är inne i huset\', så tron det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 27, 'Ty såsom ljungelden, när den går ut från öster, synes ända till väster, så skall Människosonens tillkommelse vara. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 28, 'Där åteln är, dit skola rovfåglarna församla sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 29, 'Men strax efter den tidens vedermöda skall solen förmörkas och månen upphöra att giva sitt sken, och stjärnorna skola falla ifrån himmelen, och himmelens makter[3] skola bäva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 30, 'Och då skall Människosonens tecken visa sig på himmelen, och alla släkter på jorden skola då jämra sig. Och man skall få se \'Människosonen komma på himmelens skyar\' med stor makt och härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 31, 'Och han skall sända ut sina änglar med starkt basunljud, och de skola församla hans utvalda från de fyra väderstrecken, från himmelens ena ända till den andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 32, 'Ifrån fikonträdet mån I här hämta en liknelse. När dess kvistar begynna att få save och löven spricka ut, då veten I att sommaren är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 33, 'Likaså, när I sen allt detta, då kunnen I ock veta att han är nära och står för dörren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 34, 'Sannerligen säger jag eder: Detta släkte skall icke förgås, förrän allt detta sker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 35, 'Himmel och jord skola förgås, men mina ord skola aldrig förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 36, 'Men om den dagen och den stunden vet ingen något, icke ens änglarna i himmelen, ingen utom Fadern allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 37, 'Ty såsom det skedde på Noas tid, så skall det ske vid Människosonens tillkommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 38, 'Såsom människorna levde på den tiden, före floden: de åto och drucko, män togo sig hustrur, och hustrur gåvos åt män, ända till den dag då Noa gick in i arken;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 39, 'och de visste av intet, förrän floden kom och tog dem allasammans bort -- så skall det ske vid Människosonens tillkommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 40, 'Då skola två män vara tillsammans ute på marken; en skall bliva upptagen, och en skall lämnas kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 41, 'Två kvinnor skola mala på samma kvarn; en skall bliva upptagen, och en skall lämnas kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 42, 'Vaken fördenskull; ty I veten icke vilken dag vår Herre kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 43, 'Men det förstån I väl, att om husbonden visste under vilken nattväkt tjuven skulle komma, så vakade han och tillstadde icke att någon bröt sig in i hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 44, 'Varen därför ock I redo; ty i en stund då I icke vänten det skall Människosonen komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 45, 'Finnes nu någon trogen och förståndig tjänare, som av sin herre har blivit satt över hans husfolk för att giva dem mat i rätt tid --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 46, 'salig är då den tjänaren, om hans herre, när han kommer, finner honom göra så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 47, 'Sannerligen säger jag eder: Han skall sätta honom över allt vad han äger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 48, 'Men om så är, att tjänaren är en ond man, som säger i sitt hjärta: \'Min herre kommer icke så snart\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 49, 'och han begynner slå sina medtjänare och äter och dricker med dem som äro druckna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 50, 'då skall den tjänarens herre komma på en dag då han icke väntar det, och i en stund då han icke tänker sig det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 51, 'och han skall låta hugga honom i stycken och låta honom få sin del med skrymtare. Där skall vara gråt och tandagnisslan.» [1] Se Födslovåndor i Ordförklaringarna. [2] Se Förödelsens styggelse i Ordförklaringarna. [3] Se Makter i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 1, '»Då skall det vara med himmelriket, såsom när tio jungfrur togo sina lampor och gingo ut för att möta brudgummen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 2, 'Men fem av dem voro oförståndiga, och fem voro förståndiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 3, 'De oförståndiga togo väl sina lampor, men togo ingen olja med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 4, 'De förståndiga åter togo olja i sina kärl, tillika med lamporna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 5, 'Då nu brudgummen dröjde, blevo de alla sömniga och somnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 6, 'Men vid midnattstiden ljöd ett anskri: \'Se brudgummen kommer! Gån ut och möten honom.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 7, 'Då stodo alla jungfrurna upp och redde till sina lampor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 8, 'Och de oförståndiga sade till de förståndiga: \'Given oss av eder olja, ty våra lampor slockna.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 9, 'Men de förståndiga svarade och sade: \'Nej, den skulle ingalunda räcka till för både oss och eder. Gån hellre bort till dem som sälja, och köpen åt eder.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 10, 'Men när de gingo bort för att köpa, kom brudgummen, och de som voro redo gingo in med honom till bröllopet, och dörren stängdes igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 11, 'Omsider kommo ock de andra jungfrurna och sade: \'Herre, herre, låt upp för oss.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 12, 'Men han svarade och sade: \'Sannerligen säger jag eder: Jag känner eder icke.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 13, 'Vaken fördenskull; ty I veten icke dagen, ej heller stunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 14, 'Ty det skall ske, likasom när en man som ville fara utrikes kallade till sig sina tjänare och överlämnade åt dem sina ägodelar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 15, 'åt en gav han fem pund[1], åt en annan två och åt en tredje ett pund, åt var och en efter hans förmåga, och for utrikes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 16, 'Strax gick då den som hade fått de fem punden bort och förvaltade dem så, att han med dem vann andra fem pund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 17, 'Den som hade fått de två punden vann på samma sätt andra två.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 18, 'Men den som hade fått ett pund gick bort och grävde en grop i jorden och gömde där sin herres penningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 19, 'En lång tid därefter kom tjänarnas herre hem och höll räkenskap med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 20, 'Då trädde den fram, som hade fått de fem punden, och bar fram andra fem pund och sade: \'Herre, du överlämnade åt mig fem pund; se, andra fem pund har jag vunnit.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 21, 'Hans herre svarade honom: \'Rätt så, du gode och trogne tjänare! När du var satt över det som ringa är, var du trogen; jag skall sätta dig över mycket. Gå in i din herres glädje.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 22, 'Så trädde ock den fram, som hade fått de två punden, och sade: \'Herre, du överlämnade åt mig två pund; se, andra två pund har jag vunnit.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 23, 'Hans herre svarade honom: \'Rätt så, du gode och trogne tjänare! När du var satt över det som ringa är, var du trogen; jag skall sätta dig över mycket. Gå in i din herres glädje.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 24, 'Sedan trädde ock den fram, som hade fått ett pund, och sade: \'Herre, jag hade lärt känna dig såsom en sträng man, som vill skörda, där du icke har sått, och inbärga, där du icke har utstrött;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 25, 'och av fruktan för dig gick jag bort och gömde ditt pund i jorden. Se här har du vad dig tillhör.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 26, 'Då svarade hans herre och sade till honom: \'Du onde och late tjänare, du visste att jag vill skörda, där jag icke har sått, och inbärga, där jag icke har utstrött?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 27, 'Då borde du också hava satt in mina penningar i en bank, så att jag hade fått igen mitt med ränta, när jag kom hem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 28, 'Tagen därför ifrån honom hans pund, och given det åt den som har de tio punden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 29, 'Ty var och en som har, åt honom skall varda givet, så att han får över nog; men den som icke har, från honom skall tagas också det han har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 30, 'Och kasten den oduglige tjänaren ut i mörkret härutanför.\' Där skall vara gråt och tandagnisslan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 31, 'Men när Människosonen kommer i sin härlighet, och alla änglar med honom, då skall han sätta sig på sin härlighets tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 32, 'Och inför honom skola församlas alla folk och han skall skilja dem från varandra, såsom en herde skiljer fåren ifrån getterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 33, 'Och fåren skall han ställa på sin högra sida, och getterna på den vänstra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 34, 'Därefter skall Konungen säga till dem som stå på hans högra sida: \'Kommen, I min Faders välsignade, och tagen i besittning det rike som är tillrett åt eder från världens begynnelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 35, 'Ty jag var hungrig, och I gåven mig att äta; jag var törstig, och I gåven mig att dricka; jag var husvill, och I gåven mig härbärge,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 36, 'naken, och I klädden mig; jag var sjuk, och I besökten mig; jag var i fängelse, och I kommen till mig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 37, 'Då skola de rättfärdiga svara honom och säga: \'Herre, när sågo vi dig hungrig och gåvo dig mat, eller törstig och gåvo dig att dricka?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 38, 'Och när sågo vi dig husvill och gåvo dig härbärge, eller naken och klädde dig?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 39, 'Och när sågo vi dig sjuk eller i fängelse och kommo till dig?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 40, 'Då skall Konungen svara och säga till dem: \'Sannerligen säger jag eder: Vadhelst I haven gjort mot en av dessa mina minsta bröder, det haven I gjort mot mig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 41, 'Därefter skall han ock säga till dem som stå på hans vänstra sida: \'Gån bort ifrån mig, I förbannade[2], till den eviga elden, som är tillredd åt djävulen och hans änglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 42, 'Ty jag var hungrig, och I gåven mig icke att äta; jag var törstig, och I gåven mig icke att dricka;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 43, 'jag var husvill, och I gåven mig icke härbärge, naken, och I klädden mig icke, sjuk och i fängelse, och I besökten mig icke.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 44, 'Då skola också de svara och säga: \'Herre, när sågo vi dig hungrig eller törstig eller husvill eller naken eller sjuk eller i fängelse och tjänade dig icke?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 45, 'Då skall han svara dem och säga: \'Sannerligen säger jag eder: Vadhelst I icke haven gjort mot en av dessa minsta, det haven I ej heller gjort mot mig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 46, 'Och dessa skola då då bort till evigt straff, men de rättfärdiga till evigt liv.» [1] Se Pund i Ordförklaringarna. [2] Eller: Därefter skall han ock säga till dem som stå på hans vänstra sida: \'Gån bort ifrån mig i förbannelse\' osv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 1, 'När nu Jesus hade talat allt detta till slut, sade han till sina lärjungar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 2, '»I veten att det två dagar härefter är påsk; då skall Människosonen bliva förrådd och utlämnad till att korsfästas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 3, 'Därefter församlade sig översteprästerna och folkets äldste hos översteprästen, som hette Kaifas, i hans hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 4, 'och rådslogo om att låta gripa Jesus med list och döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 5, 'Men de sade: »Icke under högtiden, för att ej oroligheter skola uppstå bland folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 6, 'Men när Jesus var i Betania, i Simon den spetälskes hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 7, 'framträdde till honom en kvinna som hade med sig en alabasterflaska med dyrbar smörjelse; denna göt hon ut över hans huvud, där han låg till bords.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 8, 'Då lärjungarna sågo detta, blevo de misslynta och sade: »Varför skulle detta förspillas?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 9, 'Man hade ju kunnat sälja det för mycket penningar och giva dessa åt de fattiga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 10, 'När Jesus märkte detta, sade han till dem: »Varför oroen I kvinnan? Det är en god gärning som hon har gjort mot mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 11, 'De fattiga haven I ju alltid ibland eder, men mig haven I icke alltid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 12, 'När hon göt ut denna smörjelse på min kropp, gjorde hon det såsom en tillredelse till min begravning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 13, 'Sannerligen säger jag eder: Varhelst i hela världen detta evangelium bliver predikat, där skall ock det som hon nu har gjort bliva omtalat, henne till åminnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 14, 'Därefter gick en av de tolv, den som hette Judas Iskariot, bort till översteprästerna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 15, 'och sade: »Vad viljen I giva mig för att jag skall överlämna honom åt eder?» Då vägde de upp åt honom trettio silverpenningar[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 16, 'Och från den stunden sökte han efter lägligt tillfälle att förråda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 17, 'Men på första dagen i det osyrade brödets högtid trädde lärjungarna fram till Jesus och frågade: »Var vill du att vi skola reda till åt dig att äta påskalammet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 18, 'Han svarade: »Gån in i staden till den och den och sägen till honom: \'Mästaren låter säga: Min tid är nära; hos dig vill jag hålla påskhögtid med mina lärjungar.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 19, 'Och lärjungarna gjorde såsom Jesus hade befallt dem och redde till påskalammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 20, 'När det nu hade blivit afton, lade han sig till bords med de tolv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 21, 'Och medan de åto, sade han: »Sannerligen säger jag eder: En av eder skall förråda mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 22, 'Då blevo de mycket bedrövade och begynte fråga honom, var efter annan: »Icke är det väl jag, Herre?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 23, 'Då svarade han och sade: »Den som jämte mig nu doppade handen i fatet, han skall förråda mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 24, 'Människosonen skall gå bort, såsom det är skrivet om honom; men ve den människa genom vilken Människosonen bliver förrådd! Det hade varit bättre för den människan, om hon icke hade blivit född.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 25, 'Judas, han som förrådde honom, tog då till orda och frågade: »Rabbi, icke är det väl jag?» Han svarade honom: »Du har själv sagt det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 26, 'Medan de nu åto, tog Jesus ett bröd och välsignade det och bröt det och gav åt lärjungarna och sade: »Tagen och äten; detta är min lekamen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 27, 'Och han tog en kalk och tackade Gud och gav åt dem och sade: »Dricken härav alla;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 28, 'ty detta är mitt blod, förbundsblodet, som varder utgjutet för många till syndernas förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 29, 'Och jag säger eder: Härefter skall jag icke mer dricka av det som kommer från vinträd, förrän på den dag då jag dricker det nytt med eder i min Faders rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 30, 'När de sedan hade sjungit lovsången, gingo de ut till Oljeberget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 31, 'Då sade Jesus till dem: »I denna natt skolen I alla komma på fall för min skull, ty det är skrivet: \'Jag skall slå herden, och fåren i hjorden skola förskingras.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 32, 'Men efter min uppståndelse skall jag före eder gå till Galileen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 33, 'Då svarade Petrus och sade till honom: »Om än alla andra komma på fall för din skull, så skall dock jag aldrig komma på fall.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 34, 'Jesus sade till honom: »Sannerligen säger jag dig: I denna natt, förrän hanen har galit, skall du tre gånger förneka mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 35, 'Petrus svarade honom: »Om jag än måste dö med dig, så skall jag dock förvisso icke förneka dig.» Sammalunda sade ock alla de andra lärjungarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 36, 'Därefter kom Jesus med dem till ett ställe som hette Getsemane. Och han sade till lärjungarna: »Bliven kvar här, medan jag går dit bort och beder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 37, 'Och han tog med sig Petrus och Sebedeus\' två söner; och han begynte bedrövas och ängslas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 38, 'Då sade han till dem: »Min själ är djupt bedrövad, ända till döds; stannen kvar här och vaken med mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 39, 'Därefter gick han litet längre bort och föll ned på sitt ansikte och bad och sade: »Min Fader, om det är möjligt, så gånge denna kalk ifrån mig. Dock icke såsom jag vill, utan såsom du vill!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 40, 'Sedan kom han tillbaka till lärjungarna och fann dem sovande. Då sade han till Petrus: »Så litet förmådden I då vaka en kort stund med mig!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 41, 'Vaken, och bedjen att I icke mån komma i frestelse. Anden är villig, men köttet är svagt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 42, 'Åter gick han bort, för andra gången, och bad och sade: »Min Fader, om detta icke kan gå ifrån mig, utan jag måste dricka denna kalk, så ske din vilja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 43, 'När han sedan kom tillbaka, fann han dem åter sovande, ty deras ögon voro förtyngda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 44, 'Då lät han dem vara och gick åter bort och bad, för tredje gången, och sade återigen samma ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 45, 'Därefter kom han tillbaka till lärjungarna och sade till dem: »Ja, I soven ännu alltjämt och vilen eder! Se, stunden är nära då Människosonen skall bliva överlämnad i syndares händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 46, 'Stån upp, låt oss gå; se, den är nära, som förråder mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 47, 'Och se, medan han ännu talade, kom Judas, en av de tolv, och jämte honom en stor folkskara, med svärd och stavar, utsänd från översteprästerna och folkets äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 48, 'Men förrädaren hade givit dem ett tecken; han hade sagt: »Den som jag kysser, den är det; honom skolen I gripa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 49, 'Och han trädde nu strax fram till Jesus och sade: »Hell dig, rabbi!» och kysste honom häftigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 50, 'Jesus sade till honom: »Min vän, gör vad du är här för att göra.» Då stego de fram och grepo Jesus och togo honom fången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 51, 'Men en av dem som voro med Jesus förde handen till sitt svärd och drog ut det och högg till översteprästens tjänare och högg så av honom örat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 52, 'Då sade Jesus till honom: »Stick ditt svärd tillbaka i skidan: ty alla som taga till svärd skola förgöras genom svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 53, 'Eller menar du att jag icke kunde utbedja mig av min Fader, att han nu sände till min tjänst mer än tolv legioner änglar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 54, 'Men huru bleve då skrifterna fullbordade, som säga att så måste ske?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 55, 'I samma stund sade Jesus till folkskaran: »Såsom mot en rövare haven I gått ut med svärd och stavar för att fasttaga mig. Var dag har jag suttit i helgedomen och undervisat, utan att I haven gripit mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 56, 'Men allt detta har skett, för att profeternas skrifter skola fullbordas.» Då övergåvo alla lärjungarna honom och flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 57, 'Men de som hade gripit Jesus förde honom bort till översteprästen Kaifas, hos vilken de skriftlärde och de äldste hade församlat sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 58, 'Och Petrus följde honom på avstånd ända till översteprästens gård; där gick han in och satte sig bland rättstjänarna för att se vad slutet skulle bliva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 59, 'Och översteprästerna och hela Stora rådet sökte efter något falskt vittnesbörd mot Jesus, för att kunna döda honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 60, 'men fastän många falska vittnen trädde fram, funno de likväl intet. Slutligen trädde dock två män fram');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 61, 'och sade: »Denne har sagt: \'Jag kan bryta ned Guds tempel och på tre dagar bygga upp det igen.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 62, 'Då stod översteprästen upp och sade till honom: »Svarar du intet? Huru är det med det som dessa vittna mot dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 63, 'Men Jesus teg. Då sade översteprästen till honom: »Jag besvär dig vid den levande Guden, att du säger oss om du är Messias, Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 64, 'Jesus svarade honom: »Du har själv sagt det. Men jag säger eder: Härefter skolen I få se Människosonen sitta på Maktens högra sida och komma på himmelens skyar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 65, 'Då rev översteprästen sönder sina kläder och sade: »Han har hädat. Vad behöva vi mer några vittnen? I haven nu hört hädelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 66, 'Vad synes eder?» De svarade och sade: »Han är skyldig till döden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 67, 'Därefter spottade man honom i ansiktet och slog honom på kinderna, den ene med knytnäven, den andre med flata handen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 68, 'och sade: »Profetera för oss, Messias: vem var det som slog dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 69, 'Men Petrus satt utanför på gården. Då kom en tjänstekvinna fram till honom och sade: »Också du var med Jesus från Galileen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 70, 'Men han nekade inför alla och sade: »Jag förstår icke vad du menar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 71, 'När han sedan hade kommit ut i porten, fick en annan kvinna se honom och sade till dem som voro där: »Denne var med Jesus från Nasaret.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 72, 'Åter nekade han med en ed och sade: »Jag känner icke den mannen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 73, 'Litet därefter kommo de kringstående fram och sade till Petrus: »Förvisso är också du en av dem; redan ditt uttal röjer dig ju.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 74, 'Då begynte han förbanna sig och svärja: »Jag känner icke den mannen.» Och i detsamma gol hanen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 75, 'Då kom Petrus ihåg Jesu ord, huru han hade sagt: »Förrän hanen gal, skall du tre gånger förneka mig.» Och han gick ut och grät bitterligen. [1] Se Silverpenning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 1, 'Men när det hade blivit morgon, fattade alla översteprästerna och folkets äldste det beslutet angående Jesus, att de skulle döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 2, 'Och de läto binda honom och förde honom bort och överlämnade honom åt Pilatus, landshövdingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 3, 'När då Judas, som hade förrått honom, såg att han var dömd, ångrade han sig och bar de trettio silverpenningarna[1] tillbaka till översteprästerna och de äldste');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 4, 'och sade: »Jag har syndat därigenom att jag har förrått oskyldigt blod.» Men de svarade: »Vad kommer det oss vid? Du får själv svara därför.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 5, 'Då kastade han silverpenningarna i templet och gick sin väg. Sedan gick han bort och hängde sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 6, 'Men översteprästerna togo silverpenningarna och sade: »Det är icke lovligt att lägga dem i offerkistan, eftersom det är blodspenningar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 7, 'Och sedan de hade fattat sitt beslut, köpte de för dem Krukmakaråkern till begravningsplats för främlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 8, 'Därför kallas den åkern ännu i dag Blodsåkern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 9, 'Så fullbordades det som var sagt genom profeten Jeremias, när han sade: »Och jag tog de trettio silverpenningarna -- priset för den man vilkens värde hade blivit bestämt, den som israelitiska män hade värderat --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 10, 'och jag gav dem till betalning för Krukmakaråkern, i enlighet med Herrens befallning till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 11, 'Men Jesus ställdes fram inför landshövdingen. Och landshövdingen frågade honom och sade: »Är du judarnas konung?» Jesus svarade honom: »Du säger det själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 12, 'Men när översteprästerna och de äldste framställde sina anklagelser mot honom, svarade han intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 13, 'Då sade Pilatus till honom: »Hör du icke huru mycket de hava att vittna mot dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 14, 'Men han svarade honom icke på en enda fråga, så att landshövdingen mycket förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 15, 'Nu var det sed att landshövdingen vid högtiden gav folket en fånge lös, vilken de ville.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 16, 'Och man hade då en beryktad fånge, som hette Barabbas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 17, 'När de nu voro församlade, frågade Pilatus dem: »Vilken viljen I att jag skall giva eder lös, Barabbas eller Jesus, som kallas Messias?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 18, 'Han visste nämligen att det var av avund som man hade dragit Jesus inför rätta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 19, 'Och medan han satt på domarsätet, hade hans hustru sänt bud till honom och låtit säga: »Befatta dig icke med denne rättfärdige man; ty jag har i natt lidit mycket i drömmen för hans skull.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 20, 'Men översteprästerna och de äldste hade övertalat folket att begära Barabbas och låta förgöra Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 21, 'När alltså landshövdingen nu frågade dem och sade: »Vilken av de två viljen I att jag skall giva eder lös?», så svarade de: »Barabbas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 22, 'Då frågade Pilatus dem: »Vad skall jag då göra med Jesus, som kallas Messias?» De svarade alla: »Låt korsfästa honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 23, 'Men han frågade: »Vad ont har han då gjort?» Då skriade de ännu ivrigare: »Låt korsfästa honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 24, 'När nu Pilatus såg att han intet kunde uträtta, utan att larmet blev allt starkare, lät han hämta vatten och tvådde sina händer i folkets åsyn och sade: »Jag är oskyldig till denne mans blod. I fån själva svara därför.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 25, 'Och allt folket svarade och sade: »Hans blod komme över oss och över våra barn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 26, 'Då gav han dem Barabbas lös; men Jesus lät han gissla och utlämnade honom sedan till att korsfästas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 27, 'Då togo landshövdingens krigsmän Jesus med sig in i pretoriet och församlade hela den romerska vakten omkring honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 28, 'Och de togo av honom hans kläder och satte på honom en röd mantel');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 29, 'och vredo samman en krona av törnen och satte den på hans huvud, och i hans högra hand satte de ett rör. Sedan böjde de knä inför honom och begabbade honom och sade: »Hell dig, judarnas konung!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 30, 'Och de spottade på honom och togo röret och slogo honom därmed i huvudet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 31, 'Och när de så hade begabbat honom, klädde de av honom manteln och satte på honom hans egna kläder och förde honom bort till att korsfästas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 32, 'Då de nu voro på väg ditut, träffade de på en man från Cyrene, som hette Simon. Honom tvingade de att gå med och bära hans kors.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 33, 'Och när de hade kommit till en plats som kallades Golgata (det betyder huvudskalleplats),');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 34, 'räckte de honom vin att dricka, blandat med galla; men då han hade smakat därpå, ville han icke dricka det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 35, 'Och när de hade korsfäst honom, delade de hans kläder mellan sig genom att kasta lott om dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 36, 'Sedan sutto de där och höllo vakt om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 37, 'Och över hans huvud hade man satt upp en överskrift, som angav vad han var anklagad för, och den lydde så: »Denne är Jesus, judarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 38, 'Med honom korsfästes då ock två rövare, den ene på högra sidan och den andre på vänstra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 39, 'Och de som gingo där förbi bespottade honom och skakade huvudet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 40, 'och sade: »Du som bryter ned templet och inom tre dagar bygger upp det igen, hjälp dig nu själv, om du är Guds Son, och stig ned från korset.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 41, 'Sammalunda talade ock översteprästerna, jämte de skriftlärde och de äldste, begabbande ord och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 42, '»Andra har han hjälpt; sig själv kan han icke hjälpa. Han är ju Israels konung; han stige nu ned från korset, så vilja vi tro på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 43, 'Han har satt sin förtröstan på Gud, må nu han frälsa honom, om han har behag till honom, han har ju sagt: \'Jag är Guds Son.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 44, 'På samma sätt smädade honom också rövarna som voro korsfästa med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 45, 'Men vid sjätte timmen kom över hela landet ett mörker, som varade ända till nionde timmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 46, 'Och vid nionde timmen ropade Jesus med hög röst och sade: »Eli, Eli, lema sabaktani[2]?»; det betyder: »Min Gud, min Gud, varför har du övergivit mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 47, 'Men när några av dem som stodo där borde detta, sade de: »Han kallar på Elias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 48, 'Och strax skyndade en av dem fram och tog en svamp och fyllde den med ättikvin och satte den på ett rör och gav honom att dricka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 49, 'Men de andra sade: »Låt oss se om Elias kommer och hjälper honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 50, 'Åter ropade Jesus med hög röst och gav upp andan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 51, 'Och se, då rämnade förlåten i templet i två stycken, uppifrån och ända ned, och jorden skalv, och klipporna rämnade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 52, 'och gravarna öppnades, och många avsomnade heligas kroppar stodo upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 53, 'De gingo ut ur sina gravar och kommo efter hans uppståndelse in i den heliga staden och uppenbarade sig för många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 54, 'Men när hövitsmannen och de som med honom höllo vakt om Jesus sågo jordbävningen och det övriga som skedde, blevo de mycket förskräckta och sade: »Förvisso var denne Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 55, 'Och många kvinnor som hade följt Jesus från Galileen och tjänat honom, stodo där på avstånd och sågo vad som skedde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 56, 'Bland dessa voro Maria från Magdala och den Maria som var Jakobs och Joses\' moder, så ock Sebedeus\' söners moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 57, 'Men när det hade blivit afton, kom en rik man från Arimatea, vid namn Josef, som ock hade blivit en Jesu lärjunge;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 58, 'denne gick till Pilatus och utbad sig att få Jesu kropp. Då bjöd Pilatus att man skulle lämna ut den åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 59, 'Och Josef tog hans kropp och svepte den i en ren linneduk');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 60, 'och lade den i den nya grav som han hade låtit hugga ut åt sig i klippan; och sedan han hade vältrat en stor sten för ingången till graven, gick han därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 61, 'Men Maria från Magdala och den andra Maria voro där, och de sutto gent emot graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 62, 'Följande dag, som var dagen efter tillredelsedagen, församlade sig översteprästerna och fariséerna och gingo till Pilatus');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 63, 'och sade: »Herre, vi hava dragit oss till minnes att den villoläraren sade, medan han ännu levde: \'Efter tre dagar skall jag uppstå.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 64, 'Bjud fördenskull att man skyddar graven intill tredje dagen, så att hans lärjungar icke komma och stjäla bort honom, och sedan säga till folket att han har uppstått från de döda. Då bliver den sista villan värre än den första.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 65, 'Pilatus svarade dem: »Där haven I vakt; gån åstad och skydden graven så gott I kunnen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 66, 'Och de gingo åstad och skyddade graven, i det att de icke allenast satte ut vakten, utan ock förseglade stenen. [1] Se Silverpenning i Ordförklaringarna. [2] Se Betoning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 1, 'När sabbaten hade gått till ända, i gryningen till första veckodagen, kommo Maria från Magdala och den andra Maria för att se graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 2, 'Då blev det en stor jordbävning; ty en Herrens ängel steg ned från himmelen och gick fram och vältrade bort stenen och satte sig på den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 3, 'Och han var att skåda såsom en ljungeld, och hans kläder voro vita såsom snö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 4, 'Och väktarna skälvde av förskräckelse för honom och blevo såsom döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 5, 'Men ängeln talade och sade till kvinnorna: »Varen I icke förskräckta; jag vet att I söken Jesus, den korsfäste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 6, 'Han är icke här, ty han är uppstånden, såsom han hade förutsagt. Kommen hit, och sen platsen där han har legat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 7, 'Och gån så åstad med hast, och sägen till hans lärjungar att han är uppstånden från de döda. Och han skall före eder gå till Galileen; där skolen I få se honom. Jag har nu sagt eder det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 8, 'Och de gingo med hast bort ifrån graven, under fruktan och med stor glädje, och skyndade åstad för att omtala det för hans lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 9, 'Men se, då kom Jesus emot dem och sade: »Hell eder!» Och de gingo fram och fattade om hans fötter och tillbådo honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 10, 'Då sade Jesus till dem: »Frukten icke; gån åstad och omtalen detta för mina bröder, på det att de må gå till Galileen; där skola de få se mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 11, 'Men under det att de voro på vägen, kommo några av väktarna till staden och underrättade översteprästerna om allt det som hade hänt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 12, 'Då församlade sig dessa jämte de äldste; och sedan de hade fattat sitt beslut, gåvo de en ganska stor summa penningar åt krigsmännen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 13, 'och sade: »Så skolen I säga: \'Hans lärjungar kommo om natten och stulo bort honom, medan vi sovo.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 14, 'Och om saken kommer för landshövdingens öron, så skola vi ställa honom till freds och sörja för, att I kunnen vara utan bekymmer.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 15, 'Och de togo emot penningarna och gjorde såsom man hade lärt dem. Och det talet utspriddes bland judarna och är gängse bland dem ännu i denna dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 16, 'Men de elva lärjungarna begåvo sig till det berg i Galileen, dit Jesus hade bjudit dem att gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 17, 'Och när de fingo se honom, tillbådo de honom. Dock funnos några som tvivlade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 18, 'Då trädde Jesus fram och talade till dem och sade: »Mig är given all makt i himmelen och på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 19, 'Gån fördenskull ut och gören alla folk till lärjungar, döpande dem i Faderns och Sonens och den helige Andes namn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 20, 'lärande dem att hålla allt vad jag har befallt eder. Och se, jag är med eder alla dagar intill tidens ände.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Jesus Detta är begynnelsen av evangelium om Jesus Kristus, Guds Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Så är skrivet hos profeten Esaias: »Se, jag sänder ut min ängel framför dig, och han skall bereda vägen för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Hör rösten av en som ropar i öknen: \'Bereden vägen för Herren, gören stigarna jämna för honom.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'I enlighet härmed uppträdde Johannes döparen i öknen och predikade bättringens döpelse till syndernas förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Och hela judiska landet och alla Jerusalems invånare gingo ut till honom och läto döpa sig av honom i floden Jordan, och bekände därvid sina synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Och Johannes hade kläder av kamelhår och bar en lädergördel om sina länder och levde av gräshoppor och vildhonung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Och han predikade och sade: »Efter mig kommer den som är starkare än jag; jag är icke ens värdig att böja mig ned för att upplösa hans skorem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Jag döper eder med vatten, men han skall döpa eder med helig ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Och det hände sig vid den tiden att Jesus kom från Nasaret i Galileen. Och han lät döpa sig i Jordan av Johannes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Och strax då han steg upp ur vattnet, såg han himmelen dela sig och Anden såsom en duva sänka sig ned över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Och en röst kom från himmelen: »Du är min älskade Son; i dig har jag funnit behag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Strax därefter förde Anden honom ut i öknen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Och han var i öknen i fyrtio dagar och frestades av Satan och levde bland vilddjuren; och änglarna betjänade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Men sedan Johannes hade blivit satt i fängelse, kom Jesus till Galileen och predikade Guds evangelium');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'och sade: »Tiden är fullbordad, och Guds rike är nära; gören bättring, och tron evangelium.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'När han nu gick fram utmed Galileiska sjön, fick han se Simon och Simons broder Andreas kasta ut nät i sjön, ty de voro fiskare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'Och Jesus sade till dem: »Följen mig, så skall jag göra eder till människofiskare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'Strax lämnade de näten och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'När han hade gått litet längre fram, fick han se Jakob, Sebedeus\' son, och Johannes, hans broder, där de sutto i båten, också de, och ordnade sina nät.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Och strax kallade han dem till sig; och de lämnade sin fader Sebedeus med legodrängarna kvar i båten och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Sedan begåvo de sig in i Kapernaum; och strax, på sabbaten, gick han in i synagogan och undervisade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'Och folket häpnade över hans förkunnelse; ty han förkunnade sin lära för dem med makt och myndighet, och icke såsom de skriftlärde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'Strax härefter befann sig i deras synagoga en man som var besatt av en oren ande. Denne ropade');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'och sade: »Vad har du med oss att göra, Jesus från Nasaret? Har du kommit för att förgöra oss? Jag vet vem du är, du Guds Helige.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'Men Jesus tilltalade honom strängt och sade: »Tig, och far ut ur honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'Då slet och ryckte den orene anden honom och ropade med hög röst och for ut ur honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 27, 'Och alla häpnade, så att de begynte fråga varandra och säga: »Vad är detta? Det är ju en ny lära, med makt och myndighet. Till och med de orena andarna befaller han, och de lyda honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 28, 'Och ryktet om honom gick strax ut överallt i hela den kringliggande trakten av Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 29, 'Och strax då de hade kommit ut ur synagogan, begåvo de sig med Jakob och Johannes till Simons och Andreas\' hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 30, 'Men Simons svärmoder låg sjuk i feber, och de talade strax med honom om henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 31, 'Då gick han fram och tog henne vid handen och reste upp henne; och febern lämnade henne, och hon betjänade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 32, 'Men när solen hade gått ned och det hade blivit afton, förde man till honom alla som voro sjuka eller besatta;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 33, 'och hela staden var församlad utanför dörren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 34, 'Och han botade många som ledo av olika slags sjukdomar; och han drev ut många onda andar, men tillstadde icke de onda andarna att tala, eftersom de kände honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 35, 'Och bittida om morgonen, medan det ännu var mörkt, stod han upp och gick åstad bort till en öde trakt, och bad där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 36, 'Men Simon och de som voro med honom skyndade efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 37, 'Och när de funno honom, sade de till honom: »Alla fråga efter dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 38, 'Då sade han till dem: »Låt oss draga bort åt annat håll, till de närmaste småstäderna, för att jag också där må predika; ty därför har jag begivit mig ut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 39, 'Och han gick åstad och predikade i hela Galileen, i deras synagogor, och drev ut de onda andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 40, 'Och en spetälsk man kom fram till honom och föll på knä och bad honom och sade till honom: »Vill du, så kan du göra mig ren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 41, 'Då förbarmade han sig och räckte ut handen och rörde vid honom och sade till honom: »Jag vill; bliv ren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 42, 'Och strax vek spetälskan ifrån honom, och han blev ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 43, 'Sedan vände Jesus strax bort honom med stränga ord');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 44, 'och sade till honom: »Se till, att du icke säger något härom för någon; men gå bort och visa dig för prästen, och frambär för din rening det offer som Moses har påbjudit, till ett vittnesbörd för dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 45, 'Men när han kom ut, begynte han ivrigt förkunna och utsprida vad som hade skett, så att Jesus icke mer kunde öppet gå in i någon stad, utan måste hålla sig ute i öde trakter; och dit kom man till honom från alla håll.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Några dagar därefter kom han åter till Kapernaum; och när det spordes att han var hemma,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'församlade sig så mycket folk, att icke ens platsen utanför dörren mer kunde rymma dem; och han förkunnade ordet för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Då kommo de till honom med en lam man, som bars dit av fyra män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Och då de för folkets skull icke kunde komma fram till honom med mannen, togo de bort taket över platsen där han var; och sedan de så hade gjort en öppning, släppte de ned sängen, som den lame låg på.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'När Jesus såg deras tro, sade han till den lame: »Min son, dina synder förlåtas dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Nu sutto där några skriftlärde, och dessa tänkte i sina hjärtan:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '»Huru kan denne tala så? Han hädar ju. Vem kan förlåta synder, utom Gud allena?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Strax förnam då Jesus i sin ande att de tänkte så vid sig själva; och han sade till dem: »Huru kunnen I tänka sådant i edra hjärtan?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Vilket är lättare, att säga till den lame: \'Dina synder förlåtas dig\' eller att säga: \'Stå upp, tag din säng och gå\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Men för att I skolen veta att Människosonen har makt här på jorden att förlåta synder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'så säger jag dig» (och härmed vände han sig till den lame): »Stå upp, tag din säng och gå hem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Då stod han upp och tog strax sin säng och gick ut i allas åsyn, så att de alla uppfylldes av häpnad och prisade Gud och sade: »Sådant hava vi aldrig sett.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Åter begav han sig ut och gick längs med sjön. Och allt folket kom till honom, och han undervisade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'När han nu gick där fram, fick han se Levi, Alfeus\' son, sitta vid tullhuset. Och han sade till denne: »Följ mig.» Då steg han upp och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'När Jesus därefter låg till bords i hans hus, voro där såsom bordsgäster, jämte Jesus och hans lärjungar, också många publikaner och syndare; ty många sådana funnos bland dem som följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Men när de skriftlärde bland fariséerna sågo att han åt med publikaner och syndare, sade de till hans lärjungar: »Huru kan han äta med publikaner och syndare?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'När Jesus hörde detta, sade han till dem: »Det är icke de friska som behöva läkare, utan de sjuka. Jag har icke kommit för att kalla rättfärdiga, utan för att kalla syndare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Och Johannes\' lärjungar och fariséerna höllo fasta. Och man kom och sade till honom: »Varför fasta icke dina lärjungar, då Johannes\' lärjungar och fariséernas lärjungar fasta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'Jesus svarade dem: »Kunna väl bröllopsgästerna fasta, medan brudgummen ännu är hos dem? Nej, så länge de hava brudgummen hos sig, kunna de icke fasta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Men den tid skall komma, då brudgummen tages ifrån dem, och då, på den tiden, skola de fasta. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ingen syr en lapp av okrympt tyg på en gammal mantel; om någon så gjorde, skulle det isatta nya stycket riva bort ännu mer av den gamla manteln, och hålet skulle bliva värre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Ej heller slår någon nytt vin i gamla skinnläglar; om någon så gjorde, skulle vinet spränga sönder läglarna, så att både vinet och läglarna fördärvades. Nej, nytt vin slår man i nya läglar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'Och det hände sig på sabbaten att han tog vägen genom ett sädesfält; och hans lärjungar begynte rycka av axen, medan de gingo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 24, 'Då sade fariséerna till honom: »Se! Huru kunna de på sabbaten göra vad som icke är lovligt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 25, 'Han svarade dem: »Haven I aldrig läst vad David gjorde, när han själv och de som följde honom kommo i nöd och blevo hungriga:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 26, 'huru han då, på den tid Abjatar var överstepräst, gick in i Guds hus och åt skådebröden -- fastän det ju icke är lovligt för andra än för prästerna att äta sådant bröd -- och huru han jämväl gav åt dem som följde honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 27, 'Därefter sade han till dem: »Sabbaten blev gjord för människans skull, och icke människan för sabbatens skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 28, 'Så år då Människosonen herre också över sabbaten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Och han gick åter in i en synagoga. Där var då en man som hade en förvissnad hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Och de vaktade på honom, för att se om han skulle bota denne på sabbaten; de ville nämligen få något att anklaga honom för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Då sade han till mannen som hade den förvissnade handen: »Stå upp, och kom fram.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Sedan sade han till dem: »Vilketdera är lovligt på sabbaten: att göra vad gott är, eller att göra vad ont är, att rädda någons liv, eller att döda?» Men de tego.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Då såg han sig omkring på dem med vrede, bedrövad över deras hjärtans förstockelse, och sade till mannen: »Räck ut din hand.» Och han räckte ut den; och hans hand blev frisk igen. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Då gingo fariséerna bort och fattade strax, tillsammans med herodianerna, det beslutet att de skulle förgöra honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Och Jesus drog sig med sina lärjungar undan till sjön, och en stor hop folk följde honom från Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Och från Judeen och Jerusalem och Idumeen och från landet på andra sidan Jordan och från trakterna omkring Tyrus och Sidon kom en stor hop folk till honom, när de fingo höra huru stora ting han gjorde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Och han tillsade sina lärjungar att en båt skulle hållas tillreds åt honom, för folkets skull, för att de icke skulle tränga sig inpå honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Ty han botade många och blev därför överlupen av alla som hade någon plåga och fördenskull ville röra vid honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Och när de orena andarna sågo honom, föllo de ned för honom och och ropade och sade: »Du är Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Men han förbjöd dem strängeligen, åter och åter, att röja honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Och han gick upp på berget och kallade till sig några som han själv utsåg; och de kommo till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Så förordnade han tolv som skulle följa honom, och som han ville sända ut till att predika,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'och de skulle hava makt att bota sjuka och driva ut onda andar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Han förordnade alltså dessa tolv: Simon, åt vilken han gav tillnamnet Petrus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'vidare Jakob, Sebedeus\' son, och Johannes, Jakobs broder, åt vilka han gav tillnamnet Boanerges (det betyder tordönsmän);');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'vidare Andreas och Filippus och Bartolomeus och Matteus och Tomas och Jakob, Alfeus\' son, och Taddeus och Simon ivraren');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'och Judas Iskariot, densamme som förrådde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Och när han kom hem, församlade sig folket åter, så att de icke ens fingo tillfälle att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Då nu hans närmaste fingo höra härom, gingo de åstad för att taga vara på honom; ty de menade att han var från sina sinnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Och de skriftlärde som hade kommit ned från Jerusalem sade att han var besatt av Beelsebul, och att det var med de onda andarnas furste som han drev ut de onda andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Då kallade han dem till sig och sade till dem i liknelser: »Huru skulle Satan kunna driva ut Satan?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'Om ett rike har kommit i strid med sig självt, så kan det riket ju icke hava bestånd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'och om ett hus har kommit i strid med sig självt, så skall icke heller det huset kunna äga bestånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 26, 'Om alltså Satan har satt sig upp mot sig själv och kommit i strid med sig själv, så kan han icke äga bestånd, utan det är då ute med honom. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 27, 'Nej, ingen kan gå in i en stark mans hus och plundra honom på hans bohag, såframt han icke förut har bundit den starke. Först därefter kan han plundra hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 28, 'Sannerligen säger jag eder: Alla andra synder skola bliva människors barn förlåtna, ja ock alla andra hädelser, huru hädiskt de än må tala;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 29, 'men den som hädar den helige Ande, han får icke någonsin förlåtelse, utan är skyldig till evig synd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 30, 'De hade ju nämligen sagt att han var besatt av en oren ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 31, 'Så kommo nu hans moder och hans bröder; och de stannade därutanför och sände bud in till honom för att kalla honom ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 32, 'Och mycket folk satt där omkring honom; och man sade till honom: »Se, din moder och dina bröder stå härutanför och fråga efter dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 33, 'Då svarade han dem och sade: Vilken är min moder, och vilka äro mina bröder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 34, 'Och han såg sig omkring på dem som sutto där runt omkring honom, och han sade: »Se här är min moder, och här äro mina bröder!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 35, 'Den som gör Guds vilja, den är min broder och min syster och min moder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Och han begynte åter undervisa vid sjön. Och där församlade sig en stor hop folk omkring honom. Därför steg han i en båt; och han satt i den ute på sjön, under det att allt folket stod på land utmed sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Och han undervisade dem mycket i liknelser och sade till dem i sin undervisning:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, '»Hören! En såningsman gick ut för att så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Då hände sig, när han sådde, att somt föll vid vägen, och fåglarna kommo och åto upp det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Och somt föll på stengrund, där det icke hade mycket jord, och det kom strax upp, eftersom det icke hade djup jord;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'men när solen hade gått upp, förbrändes det, och eftersom det icke hade någon rot, torkade det bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Och somt föll bland törnen, och törnena sköto upp och förkvävde det, så att det icke gav någon frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Men somt föll i god jord, och det sköt upp och växte och gav frukt och bar trettiofalt och sextiofalt och hundrafalt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Och han tillade: »Den som har öron till att höra, han höre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'När han sedan hade dragit sig undan ifrån folket, frågade honom de tolv, och med dem de andra som följde honom, om liknelserna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Då sade han till dem: »Åt eder är Guds rikes hemlighet given, men åt dem som stå utanför meddelas alltsammans i liknelser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'för att de \'med seende ögon skola se, och dock intet förnimma, och med hörande öron höra, och dock intet förstå, så att de icke omvända sig och undfå förlåtelse\'.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Sedan sade han till dem: »Förstån I icke denna liknelse, huru skolen I då kunna fatta alla de andra liknelserna? --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Vad såningsmannen sår är ordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Och att säden såddes vid vägen, det är sagt om dem i vilka ordet väl bliver sått, men när de hava hört det, kommer strax Satan ock tager bort ordet som såddes i dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Sammalunda förhåller det sig med det som sås på stengrunden: det är sagt om dem, som när de få höra ordet, väl strax taga emot det med glädje,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'men icke hava någon rot i sig, utan bliva beståndande allenast till en tid; när sedan bedrövelse eller förföljelse påkommer för ordets skull, då komma de strax på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Annorlunda förhåller det sig med det som sås bland törnena: det är sagt om dem som väl höra ordet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'men låta tidens omsorger och rikedomens bedrägliga lockelse, och begärelser efter andra ting, komma därin och förkväva ordet, så att det bliver utan frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'Men att det såddes i den goda jorden, det är sagt om dem som både höra ordet och taga emot det, och som bära frukt, trettiofalt och sextiofalt och hundrafalt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'Och han sade till dem: »Icke tager man väl fram ett ljus, för att det skall sättas under skäppan eller under bänken; man gör det ju, för att det skall sättas på ljusstaken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Ty intet är fördolt, utom för att det skall bliva uppenbarat; ej heller har något blivit undangömt, utom för att det skall komma i dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, 'Om någon har öron till att höra, så höre han.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Och han sade till dem: »Akten på vad I hören. Med det mått som I mäten med skall ock mätas åt eder, och ännu mer skall bliva eder tilldelat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'Ty den som har, åt honom skall varda givet; men den som icke har, från honom skall tagas också det han har.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 26, 'Och han sade: »Så är det med Guds rike, som när en man sår säd i jorden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 27, 'och han sover, och han vaknar, och nätter och dagar gå, och säden skjuter upp och växer i höjden, han vet själv icke huru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 28, 'Av sig själv bär jorden frukt, först strå och sedan ax, och omsider finnes fullbildat vete i axet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 29, 'När så frukten är mogen, låter han strax lien gå, ty skördetiden är då inne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 30, 'Och han sade: »Vad skola vi likna Guds rike vid, eller med vilken liknelse skola vi framställa det?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 31, 'Det är såsom ett senapskorn, som när det lägges ned i jorden, är minst av alla frön på jorden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 32, 'men sedan det är nedlagt, skjuter det upp och bliver störst bland alla kryddväxter och får så stora grenar, att himmelens fåglar kunna bygga sina nästen i dess skugga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 33, 'I många sådana liknelser förkunnade han ordet för dem, efter deras förmåga att fatta det;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 34, 'och utan liknelse talade han icke till dem. Men för sina lärjungar uttydde han allt, när de voro allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 35, 'Samma dag, om aftonen, sade han till dem: »Låt oss fara över till andra stranden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 36, 'Så läto de folket gå och togo honom med i båten, där han redan förut var; och jämväl andra båtar följde med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 37, 'Då kom en häftig stormvind, och vågorna slogo in i båten, så att båten redan begynte fyllas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 38, 'Men han själv låg i bakstammen och sov, lutad mot huvudgärden. Då väckte de honom och sade till honom: »Mästare, frågar du icke efter att vi förgås?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 39, 'När han så hade vaknat, näpste han vinden och sade till sjön: »Tig, var stilla.» Och vinden lade sig, och det blev alldeles lugnt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 40, 'Därefter sade han till dem: »Varför rädens I? Haven I ännu ingen tro?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 41, 'Och de hade blivit mycket häpna och sade till varandra: »Vem är då denne, eftersom både vinden och sjön äro honom lydiga?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Så kommo de över till gerasenernas land, på andra sidan sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Och strax då han hade stigit ur båten, kom en man, som var besatt av en oren ande, emot honom från gravarna där;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'han hade nämligen sitt tillhåll bland gravarna. Och icke ens med kedjor kunde man numera fängsla honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'ty väl hade han många gånger blivit fängslad med fotbojor och kedjor, men han hade slitit itu kedjorna och brutit sönder fotbojorna, och ingen kunde få makt med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Och han vistades alltid, dag och natt, bland gravarna och på bergen och skriade och sargade sig själv med stenar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'När denne nu fick se Jesus på avstånd, skyndade han fram och föll ned för honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'och ropade med hög röst och sade: »Vad har du med mig att göra, Jesus, du Guds, den Högstes, Son? Jag besvär dig vid Gud, plåga mig icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Jesus skulle nämligen just säga till honom: »Far ut ur mannen, du orena ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Då frågade han honom: »Vad är ditt namn?» Han svarade honom: »Legion är mitt namn, ty vi äro många.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Och han bad honom enträget att icke driva dem bort ifrån den trakten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Nu gick där vid berget en stor svinhjord i bet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Och de bådo honom och sade: »Sänd oss åstad in i svinen; låt oss få fara in i dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Och han tillstadde dem det. Då gåvo sig de orena andarna åstad och foro in i svinen. Och hjorden, vid pass två tusen svin, störtade sig utför branten ned i sjön och drunknade i sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Men de som vaktade dem flydde och berättade härom i staden och på landsbygden; och folket gick åstad för att se vad det var som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'När de då kommo till Jesus, fingo de se den som hade varit besatt, mannen som hade haft legionen i sig, sitta där klädd och vid sina sinnen; och de betogos av häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'Och de som hade åsett händelsen förtäljde för dem vad som hade vederfarits den besatte, och vad som hade skett med svinen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, 'Då begynte folket bedja honom att han skulle gå bort ifrån deras område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'När han sedan steg i båten, bad honom mannen som hade varit besatt, att han skulle få följa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Men han tillstadde honom det icke, utan sade till honom: »Gå hem till de dina, och berätta för dem huru stora ting Herren har gjort med dig, och huru han har förbarmat sig över dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, 'Då gick han åstad och begynte förkunna i Dekapolis huru stora ting Jesus hade gjort med honom; och alla förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, 'Och när Jesus hade farit över i båten, tillbaka till andra stranden, församlade sig mycket folk omkring honom, där han stod vid sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'Då kom en synagogföreståndare, vid namn Jairus, dit; och när denne fick se honom, föll han ned för hans fötter');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'och bad honom enträget och sade: »Min dotter ligger på sitt yttersta. Kom och lägg händerna på henne, så att hon bliver hulpen och får leva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'Då gick han med mannen; och honom följde mycket folk, som trängde sig inpå honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Nu var där en kvinna som hade haft blodgång i tolv år,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'och som hade lidit mycket hos många läkare och kostat på sig allt vad hon ägde, utan att det hade varit henne till något gagn; snarare hade det blivit värre med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 27, 'Hon hade fått höra om Jesus och kom nu i folkhopen, bakom honom, och rörde vid hans mantel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 28, 'Ty hon tänkte: »Om jag åtminstone får röra vid hans kläder, så bliver jag hulpen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 29, 'Och strax uttorkade hennes blods källa, och hon kände i sin kropp att hon var botad från sin plåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 30, 'Men strax då Jesus inom sig förnam vilken kraft som hade gått ut ifrån honom, vände han sig om i folkhopen och frågade: »Vem rörde vid mina kläder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 31, 'Hans lärjungar sade till honom: »Du ser huru folket tränger på, och ändå frågar du: \'Vem rörde vid mig?\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 32, 'Då såg han sig omkring för att få se den som hade gjort detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 33, 'Men kvinnan fruktade och bävade, ty hon visste vad som hade skett med henne; och hon kom fram och föll ned för honom och sade honom hela sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 34, 'Då sade han till henne: »Min dotter, din tro har hjälpt dig. Gå i frid, och var botad från din plåga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 35, 'Medan han ännu talade, kommo några från synagogföreståndarens hus och sade: »Din dotter är död; du må icke vidare göra mästaren omak.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 36, 'Men när Jesus märkte vad som talades, sade han till synagogföreståndaren: »Frukta icke, tro allenast.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 37, 'Och han tillstadde ingen att följa med, utom Petrus och Jakob och Johannes, Jakobs broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 38, 'Så kommo de till synagogföreståndarens hus, och han fick där se en hop människor som höjde klagolåt och gräto och jämrade sig högt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 39, 'Och han gick in och sade till dem: »Varför klagen I och gråten? Flickan är icke död, hon sover.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 40, 'Då hånlogo de åt honom. Men han visade ut dem allasammans; och han tog med sig allenast flickans fader och moder och dem som hade fått följa med honom, och gick in dit där flickan låg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 41, 'Och han tog flickan vid handen och sade till henne: »Talita, kum» (det betyder: »Flicka, jag säger dig, stå upp»).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 42, 'Och strax stod flickan upp och begynte gå omkring (hon var nämligen tolv år gammal); och de blevo strax uppfyllda av stor häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 43, 'Men han förbjöd dem strängeligen att låta någon få veta vad som hade skett. Därefter tillsade han att man skulle giva henne något att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Och han gick bort därifrån och begav sig till sin fädernestad; och hans lärjungar följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Och när det blev sabbat, begynte han undervisa i synagogan. Och folket häpnade, när de hörde honom; de sade: »Varifrån har han fått detta? Och vad är det för vishet som har blivit honom given? Och dessa stora kraftgärningar som göras genom honom, varifrån komma de?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Är då denne icke timmermannen, han som är Marias son och broder till Jakob och Joses och Judas och Simon? Och bo icke hans systrar här hos oss?» Så blev han för dem en stötesten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Då sade Jesus till dem: »En profet är icke föraktad utom i sin fädernestad och bland sina fränder och i sitt eget hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Och han kunde icke där göra någon kraftgärning, utom att han botade några få sjuka, genom att lägga händerna på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Och han förundrade sig över deras otro. Sedan gick han omkring i byarna, från den ena byn till den andra, och undervisade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Och han kallade till sig de tolv och sände så ut dem, två och två, och gav dem makt över de orena andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Och han bjöd dem att icke taga något med sig på vägen, utom allenast en stav: icke bröd, icke ränsel, icke penningar i bältet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Sandaler finge de dock hava på fötterna, men de skulle icke bära dubbla livklädnader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Och han sade till dem: »När I haven kommit in i något hus, så stannen där, till dess I lämnen den orten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Och om man på något ställe icke tager emot eder och icke hör på eder, så gån bort därifrån, och skudden av stoftet som är under edra fötter, till ett vittnesbörd mot dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Och de gingo ut och predikade att man skulle göra bättring;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'och de drevo ut många onda andar och smorde många sjuka med olja och botade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Och konung Herodes fick höra om honom, ty hans namn hade blivit känt. Man sade: »Det är Johannes döparen, som har uppstått från de döda, och därför verka dessa krafter i honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Men andra sade: »Det är Elias.» Andra åter sade: »Det är en profet, lik de andra profeterna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Men när Herodes hörde detta, sade han: »Det är Johannes, den som jag lät halshugga. Han bar uppstått från de döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Herodes hade nämligen sänt åstad och låtit gripa Johannes och binda honom och sätta honom i fängelse, för Herodias\', sin broder Filippus\' hustrus, skull. Ty henne hade Herodes tagit till äkta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'och Johannes hade då sagt till honom: »Det är icke lovligt för dig att hava din broders hustru.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Därför hyste nu Herodes agg till honom och ville döda honom, men han hade icke makt därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Ty Herodes förstod att Johannes var en rättfärdig och helig man, och han fruktade för honom och gav honom sitt beskydd. Och när han hade hört honom, blev han betänksam i många stycken; och han hörde honom gärna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 21, 'Men så kom en läglig dag, i det att Herodes på sin födelsedag gjorde ett gästabud för sina stormän och för krigsöverstarna och de förnämsta männen i Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 22, 'Då gick Herodias\' dotter ditin och dansade; och hon behagade Herodes och hans bordsgäster. Och konungen sade till flickan: »Begär av mig vadhelst du vill, så skall jag giva dig det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 23, 'Ja, han lovade henne detta med ed och sade: »Vadhelst du begär av mig, det skall jag giva dig, ända till hälften av mitt rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 24, 'Då gick hon ut och frågade sin moder: »Vad skall jag begära?» Hon svarade: »Johannes döparens huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 25, 'Och strax skyndade hon in till konungen och framställde sin begäran och sade: »Jag vill att du nu genast giver mig på ett fat Johannes döparens huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 26, 'Då blev konungen mycket bekymrad, men för edens och för bordsgästernas skull ville han icke avvisa henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 27, 'Alltså sände konungen strax en drabant med befallning att hämta hans huvud. Och denne gick åstad och halshögg honom i fängelset');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 28, 'och bar sedan fram hans huvud på ett fat och gav det åt flickan, och flickan gav det åt sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 29, 'Men när hans lärjungar fingo höra härom, kommo de och togo hans döda kropp och lade den i en grav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 30, 'Och apostlarna församlade sig hos Jesus och omtalade för honom allt vad de hade gjort, och allt vad de hade lärt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 31, 'Då sade han till dem: »Kommen nu I med mig bort till en öde trakt, där vi få vara allena, och vilen eder något litet.» Ty de fingo icke ens tid att äta; så många voro de som kommo och gingo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 32, 'De foro alltså i båten bort till en öde trakt, där de kunde vara allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 33, 'Men man såg dem fara sin väg, och många fingo veta det; och från alla städer strömmade då människor tillsammans dit landvägen och kommo fram före dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 34, 'När han så steg i land, fick han se att där var mycket folk. Då ömkade han sig över dem, eftersom de voro »lika får som icke hade någon herde»; och han begynte undervisa dem i mångahanda stycken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 35, 'Men när det redan var långt lidet på dagen, trädde hans lärjungar fram till honom och sade: »Trakten är öde, och det är redan långt lidet på dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 36, 'Låt dem skiljas åt, så att de kunna gå bort i gårdarna och byarna häromkring och köpa sig något att äta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 37, 'Men han svarade och sade till dem: »Given I dem att äta.» De svarade honom: »Skola vi då gå bort och köpa bröd för två hundra silverpenningar[1] och giva dem att äta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 38, 'Men han sade till dem: »Huru många bröd haven I? Gån och sen efter.» Sedan de hade gjort så, svarade de: »Fem, och därtill två fiskar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 39, 'Då befallde han dem att låta alla i skilda matlag lägga sig ned i gröna gräset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 40, 'Och de lägrade sig där i skilda hopar, hundra eller femtio i var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 41, 'Därefter tog han de fem bröden och de två fiskarna och såg upp till himmelen och välsignade dem. Och han bröt bröden och gav dem åt lärjungarna, för att de skulle lägga fram åt folket; också de två fiskarna delade han mellan dem alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 42, 'Och de åto alla och blevo mätta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 43, 'Sedan samlade man upp överblivna brödstycken, tolv korgar fulla, därtill ock kvarlevor av fiskarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 44, 'Och det var fem tusen män som hade ätit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 45, 'Strax därefter nödgade han sina lärjungar att stiga i båten och i förväg fara över till Betsaida på andra stranden, medan han själv tillsåg att folket skildes åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 46, 'Och när han hade tagit avsked av folket, gick han därifrån upp på berget för att bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 47, 'När det så hade blivit afton, var båten mitt på sjön, och han var ensam kvar på land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 48, 'Och han såg dem vara hårt ansatta, där de rodde fram, ty vinden låg emot dem. Vid fjärde nattväkten kom han då till dem, gående på sjön, och skulle just gå förbi dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 49, 'Men när de fingo se honom gå på sjön, trodde de att det var en vålnad och ropade högt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 50, 'ty de sågo honom alla och blevo förfärade. Men han begynte strax tala med dem och sade till dem: »Varen vid gott mod; det är jag, varen icke förskräckta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 51, 'Därefter steg han upp till dem i båten, och vinden lade sig. Och de blevo uppfyllda av stor häpnad;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 52, 'ty de hade icke kommit till förstånd genom det som hade skett med bröden, utan deras hjärtan voro förstockade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 53, 'När de hade farit över till andra stranden, kommo de till Gennesarets land och lade till där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 54, 'Och när de stego ur båten, kände man strax igen honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 55, 'och man skyndade omkring med bud i hela den trakten, och folket begynte då överallt bära de sjuka på sängar dit där man hörde att han var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 56, 'Och varhelst han gick in i någon by eller någon stad eller någon gård, där lade man de sjuka på de öppna platserna. Och de bådo honom att åtminstone få röra vid hörntofsen på hans mantel; och alla som rörde vid den blevo hulpna. [1] Se Silverpenning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Och fariséerna, så ock några skriftlärde som hade kommit från Jerusalem, församlade sig omkring honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'och de fingo då se några av hans lärjungar äta med »orena», det är otvagna, händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Nu är det så med fariséerna och alla andra judar, att de icke äta något utan att förut, till åtlydnad av de äldstes stadgar, noga hava tvagit sina händer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'likasom de icke heller, när de komma från torget, äta något utan att förut hava tvagit sig; många andra stadgar finnas ock, som de av ålder pläga hålla, såsom att skölja bägare och träkannor och kopparskålar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Därför frågade honom nu fariséerna och de skriftlärde: »Varför vandra icke dina lärjungar efter de äldstes stadgar, utan äta med orena händer?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Men han svarade dem: »Rätt profeterade Esaias om eder, I skrymtare, såsom det är skrivet: \'Detta folk ärar mig med sina läppar, men deras hjärtan äro långt ifrån mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'och fåfängt dyrka de mig, eftersom de läror de förkunna äro människobud.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'I sätten Guds bud å sido och hållen människors stadgar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Ytterligare sade han till dem: »Rätt så; I upphäven Guds bud för att hålla edra egna stadgar!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Moses har ju sagt: \'Hedra din fader och din moder\' och \'Den som smädar sin fader eller sin moder, han skall döden dö.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Men I sägen: om en son säger till sin fader eller sin moder: \'Vad du av mig kunde hava fått till hjälp, det giver jag i stället såsom korban\' (det betyder offergåva),');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'då kunnen I icke tillstädja honom att vidare göra något för sin fader eller sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'På detta sätt gören I Guds budord om intet genom edra fäderneärvda stadgar. Och mycket annat sådant gören I.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Därefter kallade han åter folket till sig och sade till dem: »Hören mig alla och förstån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Intet som utifrån går in i människan kan orena henne, men vad som går ut ifrån människan, detta är det som orenar henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'När han sedan hade lämnat folket och kommit inomhus, frågade hans lärjungar honom om detta bildliga tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Han svarade dem: »Ären då också I så utan förstånd? Insen I icke att intet som utifrån går in i människan kan orena henne,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'eftersom det icke går in i hennes hjärta, utan ned i buken, och har sin naturliga utgång?» Härmed förklarade han all mat för ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Och han tillade: »Vad som går ut ifrån människan, detta är det som orenar människan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Ty inifrån, från människornas hjärtan, utgå deras onda tankar, otukt, tjuveri, mord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'äktenskapsbrott, girighet, ondska, svek, lösaktighet, avund, hädelse, övermod, oförsynt väsende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Allt detta onda går inifrån ut, och det orenar människan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Och han stod upp och begav sig bort därifrån till Tyrus\' område. Där gick han in i ett hus och ville icke att någon skulle få veta det. Dock kunde han icke förbliva obemärkt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'utan en kvinna, vilkens dotter var besatt av en oren ande, kom, strax då hon hade fått höra om honom, och föll ned för hans fötter;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'det var en grekisk kvinna av syrofenicisk härkomst. Och hon bad honom att han skulle driva ut den onde anden ur hennes dotter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Men han sade till henne: »Låt barnen först bliva mättade; det är ju otillbörligt att taga brödet från barnen och kasta det åt hundarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Hon svarade och sade till honom: »Ja, Herre; också äta hundarna under bordet allenast av barnens smulor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 29, 'Då sade han till henne: »För det ordets skull säger jag dig: Gå; den onde anden har farit ut ur din dotter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 30, 'Och när hon kom hem, fann hon flickan ligga på sängen och såg att den onde anden hade farit ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 31, 'Sedan begav han sig åter bort ifrån Tyrus\' område och tog vägen över Sidon och kom, genom Dekapolis\' område, till Galileiska sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 32, 'Och man förde till honom en som var döv och nästan stum och bad honom att lägga handen på denne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 33, 'Då tog han honom avsides ifrån folket och satte sina fingrar i hans öron och spottade och rörde vid hans tunga');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 34, 'och såg upp till himmelen, suckade och sade till honom: »Effata» (det betyder: »Upplåt dig»).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 35, 'Då öppnades hans öron, och hans tungas band löstes, och han talade redigt och klart.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 36, 'Och Jesus förbjöd dem att omtala detta för någon; men ju mer han förbjöd dem, dess mer förkunnade de det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 37, 'Och folket häpnade övermåttan och sade: »Allt har han väl beställt: de döva låter han höra och de stumma tala.» [1] Se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Då vid samma tid åter mycket folk hade kommit tillstädes, och de icke hade något att äta, kallade han sina lärjungar till sig och sade till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, '»Jag ömkar mig över folket, ty det är redan tre dagar som de hava dröjt kvar hos mig, och de hava intet att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Om jag nu låter dem fastande gå ifrån mig hem, så uppgivas de på vägen; somliga av dem hava ju kommit långväga ifrån.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Då svarade hans lärjungar honom: »Varifrån skall man här i en öken kunna få bröd till att mätta dessa med?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Han frågade dem: »Huru många bröd haven I?» De svarade: »Sju.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Då tillsade han folket att lägra sig på marken. Ock han tog de sju bröden, tackade Gud och bröt dem och gav åt sina lärjungar, för att de skulle lägga fram dem; och de lade fram åt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'De hade ock några få småfiskar; och när han hade välsignat dessa, bjöd han att man likaledes skulle lägga fram dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Så åto de och blevo mätta. Och man samlade sedan upp sju korgar med överblivna stycken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Men antalet av dem som voro tillstädes var vid pass fyra tusen. Sedan lät han dem skiljas åt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Och strax därefter steg han i båten med sina lärjungar och for till trakten av Dalmanuta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Och fariséerna kommo ditut och begynte disputera med honom; de ville sätta honom på prov och begärde av honom något tecken från himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Då suckade han ur sin andes djup och sade: »Varför begär detta släkte ett tecken? Sannerligen säger jag eder: Åt detta släkte skall intet tecken givas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Så lämnade han dem och steg åter i båten och for över till andra stranden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 14, 'Och de hade förgätit att taga med sig bröd; icke mer än ett enda bröd hade de med sig i båten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 15, 'Och han bjöd dem och sade: »Sen till, att I tagen eder till vara för fariséernas surdeg och för Herodes\' surdeg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 16, 'Då talade de med varandra om att de icke hade bröd med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 17, 'Men när han märkte detta, sade han till dem: »Varför talen I om att I icke haven bröd med eder? Fatten och förstån I då ännu ingenting? Äro edra hjärtan så förstockade?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 18, 'I haven ju ögon; sen I då icke? I haven ju öron; hören I då icke?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 19, 'Och kommen I icke ihåg huru många korgar fulla av stycken I samladen upp, när jag bröt de fem bröden åt de fem tusen?» De svarade honom: »Tolv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 20, '»Och när jag bröt de sju bröden åt de fyra tusen, huru många korgar fulla av stycken samladen I då upp?» De svarade: »Sju.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 21, 'Då sade han till dem: »Förstån I då ännu ingenting?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 22, 'Därefter kommo de till Betsaida. Och man förde till honom en som var blind och bad honom att han skulle röra vid denne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 23, 'Då tog han den blinde vid handen och ledde honom utanför byn; sedan spottade han på hans ögon och lade händerna på honom och frågade honom: »Ser du något?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 24, 'Han såg då upp och svarade: »Jag kan urskilja människorna; jag ser dem gå omkring, men de likna träd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 25, 'Därefter lade han åter händerna på hans ögon, och nu såg han tydligt och var botad och kunde jämväl på långt håll se allting klart.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 26, 'Och Jesus bjöd honom gå hem och sade: »Gå icke ens in i byn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 27, 'Och Jesus gick med sina lärjungar bort till byarna vid Cesarea Filippi. På vägen dit frågade han sina lärjungar och sade till dem: »Vem säger folket mig vara?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 28, 'De svarade och sade: »Johannes döparen; andra säga dock Elias, andra åter säga: \'Det är en av profeterna.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 29, 'Då frågade han dem: »Vem sägen då I mig vara?» Petrus svarade och sade till honom: »Du är Messias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 30, 'Då förbjöd han dem strängeligen att för någon säga detta om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 31, 'Sedan begynte han undervisa dem om att Människosonen måste lida mycket, och att han skulle bliva förkastad av de äldste och översteprästerna och de skriftlärde, och att han skulle bliva dödad, men att han tre dagar därefter skulle uppstå igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 32, 'Och han talade detta i oförtäckta ordalag. Då tog Petrus honom avsides och begynte ivrigt motsäga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 33, 'Men han vände sig om, och när han då såg sina lärjungar, talade han strängt till Petrus och sade: »Gå bort, Satan, och stå mig icke i vägen; ty dina tankar äro icke Guds tankar, utan människotankar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 34, 'Och han kallade till sig folket jämte sina lärjungar och sade till dem: »Om någon vill efterfölja mig, så försake han sig själv och tage sitt kors på sig; så följe han mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 35, 'Ty den som vill bevara sitt liv, han skall mista det; men den som mister sitt liv, för min och för evangelii skull, han skall bevara det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 36, 'Och vad hjälper det en människa, om hon vinner hela världen, men förlorar sin själ?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 37, 'Och vad kan en människa giva till lösen för sin själ?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 38, 'Den som blyges för mig och för mina ord, i detta trolösa och syndiga släkte, för honom skall ock Människosonen blygas, när han kommer i sin Faders härlighet med de heliga änglarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Ytterligare sade han till dem: »Sannerligen säger jag eder: Bland dem som här stå finnas några som icke skola smaka döden, förrän de få se Guds rike vara kommet i sin kraft.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Sex dagar därefter tog Jesus med sig Petrus och Jakob och Johannes och förde dem ensamma upp på ett högt berg, där de voro allena. Och hans utseende förvandlades inför dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'och hans kläder blevo glänsande och mycket vita, så att ingen valkare på jorden kan göra kläder så vita.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Och för dem visade sig Elias jämte Moses, och dessa samtalade med Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Då tog Petrus till orda och sade till Jesus: »Rabbi, här är oss gott att vara[1]; låt oss göra tre hyddor, åt dig en och åt Moses en och åt Elias en.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Han visste nämligen icke vad han skulle säga; så stor var deras förskräckelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Då kom en sky som överskyggde dem, och ur skyn kom en röst: »Denne är min älskade Son; hören honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Och plötsligt märkte de, när de sågo sig omkring, att där icke mer fanns någon hos dem utom Jesus allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Då de sedan gingo ned från berget, bjöd han dem att de icke, förrän Människosonen hade uppstått från de döda, skulle för någon omtala vad de hade sett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Och de lade märke till det ordet och begynte tala med varandra om vad som kunde menas med att han skulle uppstå från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Och de frågade honom och sade: »De skriftlärde säga ju att Elias först måste komma?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Han svarade dem: »Elias måste visserligen först komma och upprätta allt igen. Men huru kan det då vara skrivet om Människosonen att han skall lida mycket och bliva föraktad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Dock, jag säger eder att Elias redan har kommit; och de förforo mot honom alldeles såsom de ville, och såsom det var skrivet att det skulle gå honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'När de därefter kommo till lärjungarna, sågo de att mycket folk var samlat omkring dem, och att några skriftlärde disputerade med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Och strax då allt folket fick se honom, blevo de mycket häpna och skyndade fram och hälsade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Då frågade han dem: »Varom disputeren I med dem?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Och en man i folkhopen svarade honom: »Mästare, jag har fört till dig min son, som är besatt av en stum ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Och varhelst denne får fatt i honom kastar han omkull honom, och fradgan står gossen om munnen, och han gnisslar med tänderna och bliver såsom livlös. Nu bad jag dina lärjungar att de skulle driva ut honom, men de förmådde det icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Då svarade han dem och sade: »O du otrogna släkte, huru länge måste jag vara hos eder? Huru länge måste jag härda ut med eder? Fören honom till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Och de förde honom till Jesus. Och strax då han fick se Jesus, slet och ryckte anden honom, och han föll ned på jorden och vältrade sig, under det att fradgan stod honom om munnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Jesus frågade då hans fader: »Huru länge har det varit så med honom?» Han svarade: »Alltsedan han var ett litet barn;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'och det har ofta hänt att han har kastat honom än i elden, än i vattnet, för att förgöra honom. Men om du förmår något, så förbarma dig över oss och hjälp oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Då sade Jesus till honom: »Om jag förmår, säger du. Allt förmår den som tror.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Strax ropade gossens fader och sade: »Jag tror! Hjälp min otro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Men när Jesus såg att folk strömmade tillsammans dit, tilltalade han den orene anden strängt och sade till honom: »Du stumme och döve ande, jag befaller dig: Far ut ur honom, och kom icke mer in i honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Då skriade han och slet och ryckte gossen svårt och for ut; och gossen blev såsom död, så att folket menade att han verkligen var död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Men Jesus tog honom vid handen och reste upp honom; och han stod då upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'När Jesus därefter hade kommit inomhus, frågade hans lärjungar honom, då de nu voro allena: »Varför kunde icke vi driva ut honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 29, 'Han svarade dem: »Detta slag kan icke drivas ut genom något annat än bön och fasta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 30, 'Och de gingo därifrån och vandrade genom Galileen; men han ville icke att någon skulle få veta det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 31, 'Han undervisade nämligen sina lärjungar och sade till dem: »Människosonen skall bliva överlämnad i människors händer, och man skall döda honom; men tre dagar efter det att han har blivit dödad skall han uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 32, 'Och de förstodo icke vad han sade, men de fruktade att fråga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 33, 'Och de kommo till Kapernaum. Och när han hade kommit dit där han bodde, frågade han dem: »Vad var det I samtaladen om på vägen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 34, 'Men de tego, ty de hade på vägen talat med varandra om vilken som vore störst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 35, 'Då satte han sig ned och kallade till sig de tolv och sade till dem: »Om någon vill vara den förste, så vare han den siste av alla och allas tjänare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 36, 'Och han tog ett barn och ställde det mitt ibland dem; sedan tog han det upp i famnen och sade till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 37, '»Den som tager emot ett sådant barn i mitt namn, han tager emot mig, och den som tager emot mig, han tager icke emot mig, utan honom som har sänt mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 38, 'Johannes sade till honom: »Mästare, vi sågo huru en man som icke följer oss drev ut onda andar genom ditt namn; och vi ville hindra honom, eftersom han icke följde oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 39, 'Men Jesus sade: »Hindren honom icke; ty ingen som genom mitt namn har gjort en kraftgärning kan strax därefter tala illa om mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 40, 'Ty den som icke är emot oss, han är för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 41, 'Ja, den som giver eder en bägare vatten att dricka, därför att I hören Kristus till -- sannerligen säger jag eder: Han skall ingalunda gå miste om sin lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 42, 'Och den som förför en av dessa små som tro, för honom vore det bättre, om en kvarnsten hängdes om hans hals och han kastades i havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 43, 'Om nu din hand är dig till förförelse, så hugg av den. Det är bättre för dig att ingå i livet lytt, än att hava båda händerna i behåll och komma till Gehenna, till den eld som icke utsläckes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 44, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 45, 'Och om din fot är dig till förförelse, så hugg av den. Det är bättre för dig att ingå i livet halt, än att hava båda fötterna i behåll och kastas i Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 46, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 47, 'Och om ditt öga är dig till förförelse, så riv ut det. Det är bättre för dig att ingå i Guds rike enögd, än att hava båda ögonen i behåll och kastas i Gehenna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 48, 'där \'deras mask icke dör och elden icke utsläckes\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 49, 'Ty var människa måste saltas med eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 50, 'Saltet är en god sak; men om saltet mister sin sälta, varmed skolen I då återställa dess kraft? -- Haven salt i eder och hållen frid inbördes.» [1] Eller: Då tog Petrus till orda och sade till Jesus: »Rabbi, det är gott att vi äro här tillstädes» osv. [2] Se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Och han stod upp och begav sig därifrån, genom landet på andra sidan Jordan, till Judeens område. Och mycket folk församlades åter omkring honom, och åter undervisade han dem, såsom hans sed var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Då ville några fariséer snärja honom, och de trädde fram och frågade honom om det vore lovligt för en man att skilja sig från sin hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Men han svarade och sade till dem: »Vad har Moses bjudit eder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'De sade: »Moses tillstadde att en man fick skriva skiljebrev åt sin hustru och så skilja sig från henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Då sade Jesus till dem: »För edra hjärtans hårdhets skull skrev han åt eder detta bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Men redan vid världens begynnelse \'gjorde Gud dem till man och kvinna\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, '\'Fördenskull skall en man övergiva sin fader och sin moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Och de tu skola varda ett kött.\' Så äro de icke mer två, utan ett kött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Vad nu Gud har sammanfogat, det må människan icke åtskilja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'När de sedan hade kommit hem, frågade hans lärjungar honom åter om detsamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Och han svarade dem: »Den som skiljer sig från sin hustru och tager sig en annan hustru, han begår äktenskapsbrott mot henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Och om en hustru skiljer sig från sin man och tager sig en annan man, då begår hon äktenskapsbrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Och man bar fram barn till honom, för att han skulle röra vid dem; men lärjungarna visade bort dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'När Jesus såg detta, blev han misslynt och sade till dem: »Låten barnen komma till mig, och förmenen dem det icke; ty Guds rike hör sådana till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Sannerligen säger jag eder: Den som icke tager emot Guds rike såsom ett barn, han kommer aldrig ditin.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Och han tog dem upp i famnen och lade händerna på dem och välsignade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'När han sedan begav sig åstad för att fortsätta sin väg, skyndade en man fram och föll på knä för honom och frågade honom: »Gode Mästare, vad skall jag göra för att få evigt liv till arvedel?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Jesus sade till honom: »Varför kallar du mig god? Ingen är god utom Gud allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Buden känner du: \'Du skall icke dräpa\', \'Du skall icke begå äktenskapsbrott\', \'Du skall icke stjäla\', \'Du skall icke bära falskt vittnesbörd\', \'Du skall icke undanhålla någon vad honom tillkommer\', Hedra din fader och din moder.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Då svarade han honom: »Mästare, allt detta har jag hållit från min ungdom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Då såg Jesus på honom och fick kärlek till honom och sade till honom: »Ett fattas dig: gå bort och sälj allt vad du äger och giv åt de fattiga; då skall du få en skatt i himmelen. Och kom sedan och följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Men han blev illa till mods vid det talet och gick bedrövad bort, ty han hade många ägodelar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Då såg Jesus sig omkring och sade till sina lärjungar: »Huru svårt är det icke för dem som hava penningar att komma in i Guds rike!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Men lärjungarna häpnade vid hans ord. Då tog Jesus åter till orda och sade till dem: »Ja, mina barn, huru svårt är det icke att komma in i Guds rike!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Det är lättare för en kamel att komma igenom ett nålsöga, än för den som är rik att komma in i Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Då blevo de ännu mer häpna och sade till varandra: »Vem kan då bliva frälst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Jesus såg på dem och sade: »För människor är det omöjligt, men icke för Gud, ty för Gud är allting möjligt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Då tog Petrus till orda och sade till honom: »Se, vi hava övergivit allt och följt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Jesus svarade: »Sannerligen säger jag eder: Ingen som för min och evangelii skull har övergivit hus, eller bröder eller systrar, eller moder eller fader, eller barn, eller jordagods,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'ingen sådan finnes, som icke skall få hundrafalt igen: redan här i tiden hus, och bröder och systrar, och mödrar och barn, och jordagods, mitt under förföljelser, och i den tillkommande tidsåldern evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Men många som äro de första skola bliva de sista, medan de sista bliva de första.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Och de voro på vägen upp till Jerusalem. Och Jesus gick före dem, och de gingo där bävande; och de som följde med dem voro uppfyllda av fruktan. Då tog han åter till sig de tolv och begynte tala till dem om vad som skulle övergå honom:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, '»Se, vi gå nu upp till Jerusalem, och Människosonen skall bliva överlämnad åt översteprästerna och de skriftlärde, och de skola döma honom till döden och överlämna honom åt hedningarna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'och dessa skola begabba honom och bespotta honom och gissla honom och döda honom; men tre dagar därefter skall han uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Då trädde Jakob och Johannes, Sebedeus\' söner, fram till honom och sade till honom: »Mästare, vi skulle vilja att du läte oss få vad vi nu tänka begära av dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Han frågade dem: »Vad viljen I då att jag skall låta eder få?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'De svarade honom: »Låt den ene av oss i din härlighet få sitta på din högra sida, och den andre på din vänstra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Men Jesus sade till dem: »I veten icke vad I begären. Kunnen I dricka den kalk som jag dricker, eller genomgå det dop som jag genomgår?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'De svarade honom: »Det kunna vi.» Då sade Jesus till dem: »Ja, den kalk jag dricker skolen I få dricka, och det dop jag genomgår skolen I genomgå,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 40, 'men platsen på min högra sida och platsen på min vänstra tillkommer det icke mig att bortgiva, utan de skola tillfalla dem för vilka så är bestämt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 41, 'När de tio andra hörde detta, blevo de misslynta på Jakob och Johannes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 42, 'Då kallade Jesus dem till sig och sade till dem: »I veten att de som räknas för folkens furstar uppträda mot dem såsom herrar, och att deras mäktige låta dem känna sin myndighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 43, 'Men så är det icke bland eder; utan den som vill bliva störst bland eder, han vare de andras tjänare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 44, 'och den som vill vara främst bland eder, han vare allas dräng.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 45, 'Också Människosonen har ju kommit, icke för att låta tjäna sig, utan för att tjäna och giva sitt liv till lösen för många.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 46, 'Och de kommo till Jeriko. Men när han åter gick ut ifrån Jeriko, följd av sina lärjungar och en ganska stor hop folk, satt där vid vägen en blind tiggare, Bartimeus, Timeus\' son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 47, 'När denne hörde att det var Jesus från Nasaret, begynte han ropa och säga: »Jesus, Davids son, förbarma dig över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 48, 'Och många tillsade honom strängeligen att han skulle tiga; men han ropade ännu mycket mer: »Davids son, förbarma dig över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 49, 'Då stannade Jesus och sade: »Kallen honom hit.» Och de kallade på den blinde och sade till honom: »Var vid gott mod, stå upp; han kallar dig till sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 50, 'Då kastade han av sig sin mantel och stod upp med hast och kom fram till Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 51, 'Och Jesus talade till honom och sade: »Vad vill du att jag skall göra dig?» Den blinde svarade honom: »Rabbuni, låt mig få min syn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 52, 'Jesus sade till honom: »Gå; din tro har hjälpt dig.» Och strax fick han sin syn och följde honom på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'När de nu nalkades Jerusalem och voro nära Betfage och Betania vid Oljeberget, sände han åstad två av sina lärjungar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'och sade till dem: »Gån in i byn som ligger mitt framför eder, så skolen I, strax då I kommen ditin, finna en åsnefåle stå där bunden, som ännu ingen människa har suttit på; lösen den och fören den hit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Och om någon frågar eder varför I gören detta, så skolen I svara: \'Herren behöver den, men han skall strax sända den tillbaka hit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Då gingo de åstad och funno en åsnefåle stå där bunden utanför en port vid vägen, och de löste den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Och några som stodo där bredvid sade till dem: »Vad gören I? Varför lösen I fålen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Men de svarade dem såsom Jesus hade bjudit. Då lät man dem vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Och de förde fålen till Jesus och lade sina mantlar på den, och han satte sig upp på den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Och många bredde ut sina mantlar på vägen, andra åter skuro av kvistar och löv på fälten och strödde på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Och de som gingo före och de som följde efter ropade: »Hosianna! Välsignad vare han som kommer[1], i Herrens namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Välsignat vare vår fader Davids rike, som nu kommer. Hosianna i höjden!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Så drog han in i Jerusalem och kom in i helgedomen; och när han hade sett sig omkring överallt och det redan var sent på dagen, gick han med de tolv ut till Betania.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'När de dagen därefter voro på väg tillbaka från Betania, blev han hungrig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Och då han på avstånd fick se ett fikonträd som hade löv, gick han dit för att se om han till äventyrs skulle finna något därpå; men när han kom fram till det, fann han intet annat än löv, det var icke då fikonens tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Då talade han och sade till trädet: »Aldrig någonsin mer äte någon frukt av dig.» Och hans lärjungar hörde detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'När de sedan kommo fram till Jerusalem, gick han in i helgedomen och begynte driva ut dem som sålde och köpte i helgedomen. Och han stötte omkull växlarnas bord och duvomånglarnas säten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'han tillstadde icke heller att man bar någonting genom helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Och han undervisade dem och sade: »Det är ju skrivet: \'Mitt hus skall kallas ett bönehus för alla folk.\' Men I haven gjort det till en rövarkula.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Då översteprästerna och de skriftlärde fingo höra härom, sökte de efter tillfälle att förgöra honom; ty de fruktade för honom, eftersom allt folket häpnade över hans undervisning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'När det blev afton, begåvo de sig ut ur staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Men då de nu på morgonen åter gingo där fram, fingo de se fikonträdet vara förtorkat ända från roten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Då kom Petrus ihåg vad som hade skett och sade till honom: »Rabbi, se, fikonträdet som du förbannade är förtorkat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Jesus svarade och sade till dem: »Haven tro på Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Sannerligen säger jag eder: Om någon säger till detta berg: \'Häv dig upp, och kasta dig i havet\' och därvid icke tvivlar i sitt hjärta, utan tror att det han säger skall ske, då skall det ske honom så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Därför säger jag eder: Allt vad I bedjen om och begären, tron att det är eder givet; och det skall ske eder så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Och när I stån och bedjen, så förlåten, om I haven något emot någon, för att också eder Fader, som är i himmelen, må förlåta eder edra försyndelser.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, '[2]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Så kommo de åter till Jerusalem. Och medan han gick omkring i helgedomen, kommo översteprästerna och de skriftlärde och de äldste fram till honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'och de sade till honom: »Med vad myndighet gör du detta? Och vem har givit dig myndighet att göra detta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Jesus svarade dem: »Jag vill ställa en fråga till eder; svaren mig på den, så skall ock jag säga eder med vad myndighet jag gör detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Johannes\' döpelse, var den från himmelen eller från människor? Svaren mig härpå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Då överlade de med varandra och sade: »Om vi svara: \'Från himmelen\', så frågar han: \'Varför trodden I honom då icke?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Eller skola vi svara: \'Från människor\'?» -- det vågade de icke av fruktan för folket, ty alla höllo före att Johannes verkligen var en profet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'De svarade alltså Jesus och sade: »Vi veta det icke.» Då sade Jesus till dem: »Så säger icke heller jag eder med vad myndighet jag gör detta.» [1] Se Messias i Ordförklaringarna. [2] Se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Och han begynte tala till dem i liknelser: »En man planterade en vingård och satte stängsel däromkring och högg ut ett presskar och byggde ett vakttorn; därefter lejde han ut den åt vingårdsmän och for utrikes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'När sedan rätta tiden var inne, sände han en tjänare till vingårdsmännen, för att denne av vingårdsmännen skulle uppbära någon del av vingårdens frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Men de togo fatt på honom och misshandlade honom och läto honom gå tomhänt tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Åter sände han till dem en annan tjänare. Honom slogo de i huvudet och skymfade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Sedan sände han åstad ännu en annan, men denne dräpte de. Likaså gjorde de med många andra: somliga misshandlade de, och andra dräpte de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Nu hade han ock en enda son, vilken han älskade. Honom sände han slutligen åstad till dem, ty han tänkte: \'De skola väl hava försyn för min son.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Men vingårdsmännen sade till varandra: \'Denne är arvingen; kom, låt oss dräpa honom, så bliver arvet vårt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Och de togo fatt på honom och dräpte honom och kastade honom ut ur vingården. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Vad skall nu vingårdens herre göra? Jo, han skall komma och förgöra vingårdsmännen och lämna vingården åt andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Haven I icke läst detta skriftens ord: \'Den sten som byggningsmännen förkastade, den har blivit en hörnsten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'av Herren har den blivit detta, och underbar är den i våra ögon\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'De hade nu gärna velat gripa honom, men de fruktade för folket; ty de förstodo att det var om dem som han hade talat i denna liknelse. Så läto de honom vara och gingo sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Därefter sände de till honom några fariséer och herodianer, för att dessa skulle fånga honom genom något hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Dessa kommo nu och sade till honom: »Mästare, vi veta att du är sannfärdig och icke frågar efter någon, ty du ser icke till personen, utan lär om Guds väg vad sant är. Är det lovligt att giva kejsaren skatt, eller är det icke lovligt? Skola vi giva skatt, eller icke giva?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Men han förstod deras skrymteri och sade till dem: »Varför söken I att snärja mig? Tagen hit en penning[1], så att jag får se den.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Då lämnade de fram en sådan. Därefter frågade han dem: »Vems bild och överskrift är detta?» De svarade honom: »Kejsarens.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Då sade Jesus till dem: »Så given kejsaren vad kejsaren tillhör, och Gud vad Gud tillhör.» Och de förundrade sig högeligen över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Sedan kommo till honom några av sadducéerna, vilka mena att det icke gives någon uppståndelse. Dessa frågade honom och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, '»Mästare, Moses har givit oss den föreskriften, att om någon har en broder som dör, och som efterlämnar hustru, men icke lämnar barn efter sig, så skall han taga sin broders hustru till äkta och skaffa avkomma åt sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Nu voro här sju bröder. Den förste tog sig en hustru, men dog utan att lämna någon avkomma efter sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Då tog den andre i ordningen henne, men också han dog utan att lämna någon avkomma efter sig; sammalunda den tredje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Så skedde med alla sju: ingen av dem lämnade någon avkomma efter sig. Sist av alla dog ock hustrun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Vilken av dem skall nu vid uppståndelsen, när de uppstå, få henne till hustru? De hade ju alla sju tagit henne till hustru.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Jesus svarade dem: »Visar icke eder fråga att I faren vilse och varken förstån skrifterna, ej heller Guds kraft?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Efter uppståndelsen från de döda taga män sig icke hustrur, ej heller givas hustrur åt män, utan de äro då såsom änglarna i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Men vad nu det angår, att de döda uppstå, haven I icke läst i Moses\' bok, på det ställe där det talas om törnbusken, huru Gud sade till honom så: \'Jag är Abrahams Gud och Isaks Gud och Jakobs Gud\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Han är en Gud icke för döda, utan för levande. I faren mycket vilse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Då trädde en av de skriftlärde fram, en som hade hört deras ordskifte och förstått att han hade svarat dem väl. Denne frågade honom: »Vilket är det förnämsta av alla buden?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Jesus svarade: »Det förnämsta är detta: \'Hör, Israel! Herren, vår Gud, Herren är en.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 30, 'Och du skall älska Herren, din Gud, av allt ditt hjärta och av all din själ och av allt ditt förstånd och av all din kraft.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 31, 'Därnäst kommer detta: \'Du skall älska din nästa såsom dig själv.\' Intet annat bud är större än dessa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 32, 'Då svarade den skriftlärde honom: »Mästare, du har i sanning rätt i vad du säger, att han är en, och att ingen annan är än han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 33, 'Och att älska honom av allt sitt hjärta och av allt sitt förstånd och av all sin kraft och att älska sin nästa såsom sig själv, det är \'förmer än alla brännoffer och slaktoffer\'.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 34, 'Då nu Jesus märkte att han hade svarat förståndigt, sade han till honom: »Du är icke långt ifrån Guds rike.» Sedan dristade sig ingen att vidare ställa någon fråga på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 35, 'Medan Jesus undervisade i helgedomen, framställde han denna fråga: »Huru kunna de skriftlärde säga att Messias är Davids son?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 36, 'David själv har ju sagt genom den helige Andes ingivelse: \'Herren sade till min herre: Sätt dig på min högra sida, till dess jag har lagt dina fiender dig till en fotapall.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 37, 'Så kallar nu David själv honom \'herre\'; huru kan han då vara hans son?» Och folkskarorna hörde honom gärna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 38, 'Och han undervisade dem och sade till dem: »Tagen eder till vara för de skriftlärde, som gärna gå omkring i fotsida kläder och gärna vilja bliva hälsade på torgen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 39, 'och gärna sitta främst i synagogorna och på de främsta platserna vid gästabuden --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 40, 'detta under det att de utsuga änkors hus, medan de för syns skull hålla långa böner. De skola få en dess hårdare dom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 41, 'Och han satte sig mitt emot offerkistorna och såg huru folket lade ned penningar i offerkistorna. Och många rika lade dit mycket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 42, 'Men en fattig änka kom och lade ned två skärvar[2], det är ett öre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 43, 'Då kallade han sina lärjungar till sig och sade till dem: »Sannerligen säger jag eder: Denna fattiga änka lade dit mer än alla de andra som lade något i offerkistorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 44, 'Ty dessa lade alla dit av sitt överflöd, men hon lade dit av sitt armod allt vad hon hade, så mycket som fanns i hennes ägo.» [1] Se Penning i Ordförklaringarna. [2] Se Skärv i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Då han nu gick ut ur helgedomen, sade en av hans lärjungar till honom: »Mästare, se hurudana stenar och hurudana byggnader!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Jesus svarade honom: »Ja, du ser nu dessa stora byggnader; men här skall förvisso icke lämnas sten på sten; allt skall bliva nedbrutet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'När han sedan satt på Oljeberget, mitt emot helgedomen, frågade honom Petrus och Jakob och Johannes och Andreas, då de voro allena:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, '»Säg oss när detta skall ske, och vad som bliver tecknet till att tiden är inne, då allt detta skall gå i fullbordan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Då begynte Jesus tala till dem och sade: »Sen till, att ingen förvillar eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Många skola komma under mitt namn och säga: \'Det är jag\' och skola förvilla många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Men när I fån höra krigslarm och rykten om krig, så förloren icke besinningen; sådant måste komma, men därmed är ännu icke änden inne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Ja, folk skall resa sig upp mot folk och rike mot rike, och det skall bliva jordbävningar på den ena orten efter den andra, och hungersnöd skall uppstå; detta är begynnelsen till \'födslovåndorna\'[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Men tagen I eder till vara. Man skall då draga eder inför domstolar, och I skolen bliva gisslade i synagogor och ställas fram inför landshövdingar och konungar, för min skull, till ett vittnesbörd för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Men evangelium måste först bliva predikat för alla folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'När man nu för eder åstad och drager eder inför rätta, så gören eder icke förut bekymmer om vad I skolen tala; utan vad som bliver eder givet i den stunden, det mån I tala. Ty det är icke I som skolen tala, utan den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Och den ene brodern skall då överlämna den andre till att dödas, ja ock fadern sitt barn; och barn skola sätta sig upp mot sina föräldrar och skola döda dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Och I skolen bliva hatade av alla, för mitt namns skull. Men den som är ståndaktig intill änden, han skall bliva frälst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Men när I fån se \'förödelsens styggelse\'[2] stå där han icke borde stå -- den som läser detta, han give akt därpå -- då må de som äro i Judeen fly bort till bergen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'och den som är på taket må icke stiga ned och gå in för att hämta något ur sitt hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'och den som är ute på marken må icke vända tillbaka för att hämta sin mantel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Och ve de som äro havande, eller som giva di på den tiden!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Men bedjen att det icke må ske om vintern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Ty den tiden skall bliva \'en tid av vedermöda, så svår att dess like icke har förekommit allt ifrån världens begynnelse, från den tid då Gud skapade världen, intill nu\', ej heller någonsin skall förekomma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Och om Herren icke förkortade den tiden, så skulle intet kött bliva frälst; men för de utvaldas skull, för de människors skull, som han har utvalt, har han förkortat den tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Och om någon då säger till eder: \'Se här är Messias\', eller: \'Se där är han\', så tron det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ty människor som falskeligen säga sig vara Messias skola uppstå, så ock falska profeter, och de skola göra tecken och under, för att, om möjligt, förvilla de utvalda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Men tagen I eder till vara. Jag har nu sagt eder allt förut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Men på den tiden, efter den vedermödan, skall solen förmörkas och månen upphöra att giva sitt sken,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'och stjärnorna skola falla ifrån himmelen, och makterna[3] i himmelen skola bäva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 26, 'Och då skall man få se \'Människosonen komma i skyarna\' med stor makt och härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 27, 'Och han skall då sända ut sina änglar och församla sina utvalda från de fyra väderstrecken, från jordens ända till himmelens ända.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 28, 'Ifrån fikonträdet mån I här hämta en liknelse. När dess kvistar begynna att få save och löven spricka ut, då veten I att sommaren är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 29, 'Likaså, när I sen detta ske, då kunnen I ock veta att han är nära och står för dörren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 30, 'Sannerligen säger jag eder: Detta släkte skall icke förgås, förrän allt detta sker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 31, 'Himmel och jord skola förgås, men mina ord skola icke förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 32, 'Men om den dagen och den stunden vet ingen något, icke änglarna i himmelen, icke ens Sonen -- ingen utom Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 33, 'Tagen eder till vara, vaken; ty I veten icke när tiden är inne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 34, 'Såsom när en man reser utrikes och lämnar sitt hus och giver sina tjänare makt och myndighet däröver, åt var och en hans särskilda syssla, och därvid ock bjuder portvaktaren att vaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 35, 'likaså bjuder jag eder: Vaken; ty I veten icke när husets herre kommer, om han kommer på aftonen eller vid midnattstiden eller i hanegället eller på morgonen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 36, 'vaken, så att han icke finner eder sovande, när han oförtänkt kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 37, 'Men vad jag säger till eder, det säger jag till alla: Vaken!» [1] Se Födslovåndor i Ordförklaringarna. [2] Se Förödelsens styggelse i Ordförklaringarna. [3] Se Makter i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 1, 'Två dagar därefter var det påsk och det osyrade brödets högtid. Och översteprästerna och de skriftlärde sökte efter tillfälle att gripa honom med list och döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 2, 'De sade nämligen: »Icke under högtiden, för att ej oroligheter skola uppstå bland folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 3, 'Men när han var i Betania, i Simon den spetälskes hus, och där låg till bords, kom en kvinna som hade med sig en alabasterflaska med smörjelse av dyrbar äkta nardus. Och hon bröt sönder flaskan och göt ut smörjelsen över hans huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 4, 'Några som voro där blevo då misslynta och sade till varandra: »Varför skulle denna smörjelse förspillas?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 5, 'Man hade ju kunnat sälja den för mer än tre hundra silverpenningar[1] och giva dessa åt de fattiga.» Och de talade hårda ord till henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 6, 'Men Jesus sade: »Låten henne vara. Varför oroen I henne? Det är en god gärning som hon har gjort mot mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 7, 'De fattiga haven I ju alltid ibland eder, och närhelst I viljen kunnen I göra dem gott, men mig haven I icke alltid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 8, 'Vad hon kunde, det gjorde hon. Hon har i förväg smort min kropp såsom en tillredelse till min begravning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 9, 'Och sannerligen säger jag eder: Varhelst i hela världen evangelium bliver predikat, där skall ock det som hon nu har gjort bliva omtalat, henne till åminnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 10, 'Och Judas Iskariot, han som var en av de tolv, gick bort till översteprästerna och ville förråda honom åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 11, 'När de hörde detta, blevo de glada och lovade att giva honom en summa penningar. Sedan sökte han efter tillfälle att förråda honom, då lägligt var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 12, 'På första dagen i det osyrade brödets högtid, när man slaktade påskalammet, sade hans lärjungar till honom: »Vart vill du att vi skola gå och reda till, så att du kan äta påskalammet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 13, 'Då sände han åstad två av sina lärjungar och sade till dem: »Gån in i staden; där skolen I möta en man som bär en kruka vatten. Följen honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 14, 'Och sägen till husbonden i det hus där han går in: \'Mästaren frågar: Var finnes härbärget där jag skall äta påskalammet med mina lärjungar?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 15, 'Då skall han visa eder en stor sal i övre våningen, tillredd och ordnad för måltid; reden till åt oss där.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 16, 'Och lärjungarna begåvo sig i väg och kommo in i staden och funno det så som han hade sagt dem; och de redde till påskalammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 17, 'När det sedan hade blivit afton, kom han dit med de tolv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 18, 'Och medan de lågo till bords och åto, sade Jesus: »Sannerligen säger jag eder: En av eder skall förråda mig, \'den som äter med mig\'.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 19, 'Då begynte de bedrövas och fråga honom, den ene efter den andre: »Icke är det väl jag?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 20, 'Och han sade till dem: »Det är en av de tolv, den som jämte mig doppar i fatet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 21, 'Ja, Människosonen skall gå bort, såsom det är skrivet om honom; men ve den människa genom vilken Människosonen bliver förrådd! Det hade varit bättre för den människan, om hon icke hade blivit född.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 22, 'Medan de nu åto, tog han ett bröd och välsignade det och bröt det och gav åt dem och sade: »Tagen detta; detta är min lekamen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 23, 'Och han tog en kalk och tackade Gud ock gav åt dem; och de drucko alla därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 24, 'Och han sade till dem: »Detta är mitt blod, förbundsblodet, som varder utgjutet för många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 25, 'Sannerligen säger jag eder: Jag skall icke mer dricka av det som kommer från vinträd, förrän på den dag då jag dricker det nytt i Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 26, 'När de sedan hade sjungit lovsången, gingo de ut till Oljeberget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 27, 'Då sade Jesus till dem: »I skolen alla komma på fall; ty det är skrivet: \'Jag skall slå herden, och fåren skola förskingras.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 28, 'Men efter min uppståndelse skall jag före eder gå till Galileen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 29, 'Då svarade Petrus honom: »Om än alla andra komma på fall, så skall dock jag det icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 30, 'Jesus sade till honom: »Sannerligen säger jag dig: Redan i denna natt, förrän hanen har galit två gånger, skall du tre gånger förneka mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 31, 'Då försäkrade han ännu ivrigare: »Om jag än måste dö med dig, så skall jag dock icke förneka dig.» Sammalunda sade ock alla de andra. Och de kommo till ett ställe som kallades Getsemane.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 32, 'Då sade han till sina lärjungar: »Bliven kvar här, medan jag beder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 33, 'Och han tog med sig Petrus och Jakob och Johannes; och han begynte bäva och ängslas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 34, 'Och han sade till dem: »Min själ är djupt bedrövad, ända till döds; stannen kvar här och vaken.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 35, 'Därefter gick han litet längre bort och föll ned på jorden och bad, att om möjligt vore, den stunden skulle bliva honom besparad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 36, 'Och han sade: »Abba, Fader, allt är möjligt för dig. Tag denna kalk ifrån mig. Dock icke vad jag vill, utan vad du vill!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 37, 'Sedan kom han tillbaka och fann dem sovande. Då sade han till Petrus: »Simon, sover du? Förmådde du då icke vaka en kort stund?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 38, 'Vaken, och bedjen att I icke mån komma i frestelse. Anden är villig, men köttet är svagt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 39, 'Och han gick åter bort och bad och sade samma ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 40, 'När han sedan kom tillbaka, fann han dem åter sovande, ty deras ögon voro förtyngda. Och de visste icke vad de skulle svara honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 41, 'För tredje gången kom han tillbaka och sade då till dem: »Ja, I soven ännu alltjämt och vilen eder! Det är nog. Stunden är kommen. Människosonen skall nu bliva överlämnad i syndarnas händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 42, 'Stån upp, låt oss gå; se, den som förråder mig är nära.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 43, 'Och i detsamma, medan han ännu talade, kom Judas, en av de tolv, och jämte honom en folkskara med svärd och stavar, utsänd från översteprästerna och de skriftlärde och de äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 44, 'Men förrädaren hade kommit överens med dem om ett tecken och sagt: »Den som jag kysser, den är det; honom skolen I gripa och föra bort under säker bevakning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 45, 'Och när han nu kom dit, trädde han strax fram till honom och sade: »Rabbi!» och kysste honom häftigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 46, 'Då grepo de Jesus och togo honom fången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 47, 'Men en av dem som stodo där bredvid drog sitt svärd och högg till översteprästens tjänare och högg så av honom örat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 48, 'Och Jesus talade till dem och sade: »Såsom mot en rövare haven I gått ut med svärd och stavar för att fasttaga mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 49, 'Var dag har jag varit ibland eder i helgedomen och undervisat, utan att I haven gripit mig. Men skrifterna skulle ju fullbordas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 50, 'Då övergåvo de honom alla och flydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 51, 'Och bland dem som hade följt med honom var en ung man, höljd i ett linnekläde, som var kastat över blotta kroppen; honom grepo de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 52, 'Men han lämnade linneklädet kvar och flydde undan naken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 53, 'Så förde de nu Jesus bort till översteprästen, och där församlade sig alla översteprästerna och de äldste och de skriftlärde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 54, 'Och Petrus följde honom på avstånd ända in på översteprästens gård; där satt han sedan tillsammans med tjänarna och värmde sig vid elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 55, 'Och översteprästerna och hela Stora rådet sökte efter något vittnesbörd mot Jesus, för att kunna döda honom; men de funno intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 56, 'Ty väl vittnade många falskt mot honom, men vittnesbörden stämde icke överens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 57, 'Och några stodo upp och vittnade falskt mot honom och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 58, '»Vi hava själva hört honom säga: \'Jag skall bryta ned detta tempel, som är gjort med händer, och skall sedan på tre dagar bygga upp ett annat, som icke är gjort med händer.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 59, 'Men icke ens i det stycket stämde deras vittnesbörd överens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 60, 'Då stod översteprästen upp ibland dem och frågade Jesus och sade: »Svarar du intet? Huru är det med det som dessa vittna mot dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 61, 'Men han teg och svarade intet. Åter frågade översteprästen honom och sade till honom: »Är du Messias, den Högtlovades Son?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 62, 'Jesus svarade: »Jag är det. Och I skolen få se Människosonen sitta på Maktens högra sida och komma med himmelens skyar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 63, 'Då rev översteprästen sönder sina kläder och sade: »Vad behöva vi mer några vittnen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 64, 'I hörden hädelsen. Vad synes eder?» Då dömde de alla honom skyldig till döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 65, 'Och några begynte spotta på honom; och sedan de hade höljt över hans ansikte, slogo de honom på kinderna med knytnävarna och sade till honom: »Profetera.» Också rättstjänarna slogo honom på kinderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 66, 'Medan nu Petrus befann sig därnere på gården, kom en av översteprästens tjänstekvinnor dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 67, 'Och när hon fick se Petrus, där han satt och värmde sig, såg hon på honom och sade: »Också du var med nasaréen, denne Jesus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 68, 'Men han nekade och sade: »Jag varken vet eller förstår vad du menar.» Sedan gick han ut på den yttre gården.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 69, 'När tjänstekvinnan då fick se honom där, begynte hon åter säga till dem som stodo bredvid: »Denne är en av dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 70, 'Då nekade han åter. Litet därefter sade återigen de som stodo där bredvid till Petrus: »Förvisso är du en av dem; du är ju också en galilé.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 71, 'Då begynte han förbanna sig och svärja: »Jag känner icke den man som I talen om.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 72, 'Och i detsamma gol hanen för andra gången. Då kom Petrus ihåg Jesu ord, huru han hade sagt till honom: »Förrän hanen har galit två gånger, skall du tre gånger förneka mig.» Och han brast ut i gråt. [1] Se Silverpenning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 1, 'Sedan nu översteprästerna, tillsammans med de äldste och de skriftlärde, hela Stora rådet, på morgonen hade fattat sitt beslut, läto de strax binda Jesus och förde honom bort och överlämnade honom åt Pilatus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 2, 'Då frågade Pilatus honom: »Är du judarnas konung?» Han svarade honom och sade: »Du säger det själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 3, 'Och översteprästerna framställde många anklagelser mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 4, 'Pilatus frågade honom då åter och sade: »Svarar du intet? Du hör ju huru mycket det är som de anklaga dig för.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 5, 'Men Jesus svarade intet mer, så att Pilatus förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 6, 'Nu plägade han vid högtiden giva dem en fånge lös, den som de begärde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 7, 'Och där fanns då en man, han som kallades Barabbas, vilken satt fängslad jämte de andra som hade gjort upplopp och under upploppet begått dråp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 8, 'Folket kom ditupp och begynte begära att han skulle göra åt dem såsom han plägade göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 9, 'Pilatus svarade dem och sade: »Viljen I att jag skall giva eder \'judarnas konung\' lös?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 10, 'Han förstod nämligen att det var av avund som översteprästerna hade dragit Jesus inför rätta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 11, 'Men översteprästerna uppeggade folket till att begära att han hellre skulle giva dem Barabbas lös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 12, 'När alltså Pilatus åter tog till orda och frågade dem: »Vad skall jag då göra med den som I kallen \'judarnas konung\'?»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 13, 'så skriade de åter: »Korsfäst honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 14, 'Men Pilatus frågade dem: »Vad ont har han då gjort?» Då skriade de ännu ivrigare: »Korsfäst honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 15, 'Och eftersom Pilatus ville göra folket till viljes, gav han dem Barabbas lös; men Jesus lät han gissla och utlämnade honom sedan till att korsfästas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 16, 'Och krigsmännen förde honom in i palatset, eller pretoriet, och kallade tillhopa hela den romerska vakten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 17, 'Och de klädde på honom en purpurfärgad mantel och vredo samman en krona av törnen och satte den på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 18, 'Sedan begynte de hälsa honom: »Hell dig, judarnas konung!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 19, 'Och de slogo honom i huvudet med ett rör och spottade på honom; därvid böjde de knä och gåvo honom sin hyllning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 20, 'Och när de hade begabbat honom, klädde de av honom den purpurfärgade manteln och satte på honom hans egna kläder och förde honom ut för att korsfästa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 21, 'Och en man som kom utifrån marken gick där fram, Simon från Cyrene, Alexanders och Rufus\' fader; honom tvingade de att gå med och bära hans kors.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 22, 'Och de förde honom till Golgataplatsen (det betyder huvudskalleplatsen).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 23, 'Och de räckte honom vin, blandat med myrra, men han tog icke emot det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 24, 'Och de korsfäste honom och delade sedan hans kläder mellan sig, genom att kasta lott om vad var och en skulle få.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 25, 'Och det var vid tredje timmen som de korsfäste honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 26, 'Och den överskrift som man hade satt upp över honom, för att angiva vad han var anklagad för, hade denna lydelse: »Judarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 27, 'Och de korsfäste med honom två rövare, den ene på hans högra sida och den andre på hans vänstra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 28, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 29, 'Och de som gingo där förbi bespottade honom och skakade huvudet och sade: »Tvi dig, du som \'bryter ned templet och bygger upp det igen inom tre dagar\'!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 30, 'Hjälp dig nu själv, och stig ned från korset.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 31, 'Sammalunda talade ock översteprästerna, jämte de skriftlärde, begabbande ord med varandra och sade: »Andra har han hjälpt; sig själv kan han icke hjälpa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 32, 'Han som är Messias, Israels konung, han stige nu ned från korset, så att vi få se det och tro.» Också de män som voro korsfästa med honom smädade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 33, 'Men vid sjätte timmen kom över hela landet ett mörker, som varade ända till nionde timmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 34, 'Och vid nionde timmen ropade Jesus med hög röst: »Eloi, Eloi, lema sabaktani[2]?»; det betyder: »Min Gud, min Gud, varför har du övergivit mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 35, 'Då några av dem som stodo där bredvid hörde detta, sade de: »Hör, han kallar på Elias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 36, 'Men en av dem skyndade fram och fyllde en svamp med ättikvin och satte den på ett rör och gav honom att dricka, i det han sade: »Låt oss se om Elias kommer och tager honom ned.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 37, 'Men Jesus ropade med hög röst och gav upp andan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 38, 'Då rämnade förlåten i templet i två stycken, uppifrån och ända ned.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 39, 'Men när hövitsmannen, som stod där mitt emot honom, såg att han på sådant sätt gav upp andan, sade han: »Förvisso var denne man Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 40, 'Också några kvinnor stodo där på avstånd och sågo vad som skedde. Bland dessa voro jämväl Maria från Magdala och den Maria som var Jakob den yngres och Joses\' moder, så ock Salome');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 41, '-- vilka hade följt honom och tjänat honom, medan han var i Galileen -- därtill många andra kvinnor, de som med honom hade vandrat upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 42, 'Det var nu tillredelsedag (det är dagen före sabbaten), och det hade blivit afton.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 43, 'Josef från Arimatea, en ansedd rådsherre och en av dem som väntade på Guds rike, tog därför nu mod till sig och gick in till Pilatus och utbad sig att få Jesu kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 44, 'Då förundrade sig Pilatus över att Jesus redan skulle vara död, och han kallade till sig hövitsmannen och frågade honom om det var länge sedan han hade dött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 45, 'Och när han av hövitsmannen hade fått veta huru det var, skänkte han åt Josef hans döda kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 46, 'Denne köpte då en linneduk och tog honom ned och svepte honom i linneduken och lade honom i en grav som var uthuggen i en klippa; sedan vältrade han en sten för ingången till graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 47, 'Men Maria från Magdala och den Maria som var Joses\' moder sågo var han lades. [1] Se Nya testamentets text i Ordförklaringarna. [2] Se Betoning i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 1, 'Och när sabbaten var förliden, köpte Maria från Magdala och den Maria som var Jakobs moder och Salome välluktande kryddor, för att sedan gå åstad och smörja honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 2, 'Och bittida om morgonen på första veckodagen kommo de till graven, redan vid soluppgången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 3, 'Och de sade till varandra: »Vem skall åt oss vältra bort stenen från ingången till graven?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 4, 'Men när de sågo upp, fingo de se att stenen redan var bortvältrad. Den var nämligen mycket stor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 5, 'Och när de hade kommit in i graven, fingo de se en ung man sitta där på högra sidan, klädd i en vit fotsid klädnad; och de blevo förskräckta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 6, 'Men han sade till dem: »Varen icke förskräckta. I söken Jesus från Nasaret, den korsfäste. Han är uppstånden, han är icke här. Se där är platsen där de lade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 7, 'Men gån bort och sägen till hans lärjungar, och särskilt till Petrus: \'Han skall före eder gå till Galileen; där skolen I få se honom, såsom han bar sagt eder.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 8, 'Då gingo de ut och flydde bort ifrån graven, ty bävan och bestörtning hade kommit över dem. Och i sin fruktan sade de intet till någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 9, '[Men efter sin uppståndelse visade han sig på första veckodagens morgon först för Maria från Magdala, ur vilken han hade drivit ut sju onda andar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 10, 'Hon gick då och omtalade det för dem som hade följt med honom, och som nu sörjde och gräto.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 11, 'Men när dessa hörde sägas att han levde och hade blivit sedd av henne, trodde de det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 12, 'Därefter uppenbarade han sig i en annan skepnad för två av dem, medan de voro stadda på vandring utåt landsbygden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 13, 'Också dessa gingo bort och omtalade det för de andra; men icke heller dem trodde man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 14, 'Sedan uppenbarade han sig också för de elva, när de lågo till bords; och han förebrådde dem då deras otro och deras hjärtans hårdhet, i det att de icke hade trott dem som hade sett honom vara uppstånden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 15, 'Och han sade till dem: »Gån ut i hela världen och prediken evangelium för allt skapat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 16, 'Den som tror och bliver döpt, han skall bliva frälst; men den som icke tror, han skall bliva fördömd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 17, 'Och dessa tecken skola åtfölja dem som tro: genom mitt namn skola de driva ut onda andar, de skola tala nya tungomål,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 18, 'ormar skola de taga i händerna, och om de dricka något dödande gift, så skall det alls icke skada dem; på sjuka skola de lägga händerna, och de skola då bliva friska.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 19, 'Därefter, sedan Herren Jesus hade talat med dem, blev han upptagen i himmelen och satte sig på Guds högra sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 20, 'Men de gingo ut och predikade allestädes. Och Herren verkade med dem och stadfäste ordet genom de tecken som åtföljde det.][1] [1] V. 9--20 se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Alldenstund många andra hava företagit sig att om de händelser, som bland oss hava timat, avfatta berättelser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'i enlighet med vad som har blivit oss meddelat av dem som själva voro åsyna vittnen och ordets tjänare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'så har ock jag, sedan jag grundligt har efterforskat allt ända ifrån begynnelsen, beslutit mig för att i följd och ordning skriva därom till dig, ädle Teofilus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'så att du kan inse huru tillförlitliga de stycken äro, i vilka du har blivit undervisad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'På den tid då Herodes var konung över Judeen levde en präst vid namn Sakarias, av Abias\' »dagsavdelning». Denne hade till hustru en av Arons döttrar som hette Elisabet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'De voro båda rättfärdiga inför Gud och vandrade ostraffligt efter alla Herrens bud och stadgar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Men de hade inga barn, ty Elisabet var ofruktsam; och båda voro de komna till hög ålder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Medan han nu en gång, när ordningen kom till hans avdelning, gjorde prästerlig tjänst inför Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'hände det sig, vid den övliga lottningen om de prästerliga sysslorna, att det tillföll honom att gå in i Herrens tempel och tända rökelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Och hela menigheten stod utanför och bad, medan rökoffret förrättades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Då visade sig för honom en Herrens ängel, stående på högra sidan om rökelsealtaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Och när Sakarias såg honom, blev han förskräckt, och fruktan föll över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Men ängeln sade till honom: »Frukta icke, Sakarias; ty din bön är hörd, och din hustru Elisabet skall föda dig en son, och honom skall du giva namnet Johannes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Och han skall bliva dig till glädje och fröjd, och många skola glädja sig över hans födelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Ty han skall bliva stor inför Herren. Vin och starka drycker skall han icke dricka, och redan i sin moders liv skall han bliva uppfylld av helig ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Och många av Israels barn skall han omvända till Herren, deras Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Han skall gå framför honom i Elias\' ande och kraft, för att \'vända fädernas hjärtan till barnen\' och omvända de ohörsamma till de rättfärdigas sinnelag, så att han skaffar åt Herren ett välberett folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Då sade Sakarias till ängeln: »Varav skall jag veta detta? Jag är ju själv gammal, och min hustru är kommen till hög ålder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Ängeln svarade och sade till honom: »Jag är Gabriel, som står inför Gud, och jag är utsänd för att tala till dig och förkunna dig detta glada budskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Och se, ända till den dag då detta sker skall du vara mållös och icke kunna tala, därför att du icke trodde mina ord, vilka dock i sin tid skola fullbordas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Och folket stod och väntade på Sakarias och förundrade sig över att han så länge dröjde i templet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'och när han kom ut, kunde han icke tala till dem. Då förstodo de att han hade sett någon syn i templet. Och han tecknade åt dem och förblev stum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Och när tiden för hans tjänstgöring hade gått till ända, begav han sig hem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Men efter den tiden blev hans hustru Elisabet havande och höll sig dold i fem månader;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'och hon sade: »Så har Herren gjort med mig nu, då han har sett till min smälek bland människorna, för att borttaga den.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'I sjätte månaden blev ängeln Gabriel sänd av Gud till en stad i Galileen som hette Nasaret,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'till en jungfru som var trolovad med en man vid namn Josef, av Davids hus; och jungfruns namn var Maria.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 28, 'Och ängeln kom in till henne och sade: »Hell dig, du högtbenådade! Herren är med dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 29, 'Men hon blev mycket förskräckt vid hans ord och tänkte på vad denna hälsning månde innebära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 30, 'Då sade ängeln till henne: »Frukta icke, Maria; ty du har funnit nåd för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 31, 'Se, du skall bliva havande och föda en son, och honom skall du giva namnet Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 32, 'Han skall bliva stor och kallas den Högstes Son, och Herren Gud skall giva honom hans fader Davids tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 33, 'Och han skall vara konung över Jakobs hus till evig tid, och på hans rike skall ingen ände vara.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 34, 'Då sade Maria till ängeln: »Huru skall detta ske? Jag vet ju icke av någon man.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 35, 'Ängeln svarade och sade till henne: »Helig ande skall komma över dig, och kraft från den Högste skall överskygga dig; därför skall ock det heliga som varder fött kallas Guds Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 36, 'Och se, jämväl din fränka Elisabet har blivit havande och skall föda en son, nu på sin ålderdom; och detta är sjätte månaden för henne, som säges vara ofruktsam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 37, 'Ty för Gud kan intet vara omöjligt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 38, 'Då sade Maria: »Se, jag är Herrens tjänarinna; ske mig såsom du har sagt.» Och ängeln lämnade henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 39, 'En av de närmaste dagarna stod Maria upp och begav sig skyndsamt till en stad i Judeen, uppe i bergsbygden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 40, 'Och hon trädde in i Sakarias\' hus och hälsade Elisabet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 41, 'När då Elisabet hörde Marias hälsning, spratt barnet till i hennes liv; och Elisabet blev fylld av helig ande');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 42, 'och brast ut och ropade högt och sade: »Välsignad vare du bland kvinnor, och välsignad din livsfrukt!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 43, 'Men varför sker mig detta, att min Herres moder kommer till mig?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 44, 'Se, när ljudet av din hälsning nådde mina öron, spratt barnet till av fröjd i mitt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 45, 'Och salig är du, som trodde att det skulle fullbordas, som blev dig sagt från Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 46, 'Då sade Maria: »Min själ prisar storligen Herren,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 47, 'och min ande fröjdar sig i Gud, min Frälsare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 48, 'Ty han har sett till sin tjänarinnas ringhet; och se, härefter skola alla släkten prisa mig salig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 49, 'Ty den Mäktige har gjort stora ting med mig, och heligt är hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 50, 'Hans barmhärtighet varar från släkte till släkte över dem som frukta honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 51, 'Han har utfört väldiga gärningar med sin arm, han har förskingrat dem som tänkte övermodiga tankar i sina hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 52, 'Härskare har han störtat från deras troner, och ringa män har han upphöjt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 53, 'hungriga har han mättat med sitt goda, och rika har han skickat bort med tomma händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 54, 'Han har tagit sig an sin tjänare Israel och tänkt på att bevisa barmhärtighet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 55, 'mot Abraham och mot hans säd till evig tid, efter sitt löfte till våra fäder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 56, 'Och Maria stannade hos henne vid pass tre månader och vände därefter hem igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 57, 'Så var nu för Elisabet tiden inne, då hon skulle föda; och hon födde en son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 58, 'Och när hennes grannar och fränder fingo höra att Herren hade bevisat henne så stor barmhärtighet, gladde de sig med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 59, 'Och på åttonde dagen kommo de för att omskära barnet; och de ville kalla honom Sakarias, efter hans fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 60, 'Men hans moder tog till orda och sade: »Ingalunda; han skall heta Johannes.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 61, 'Då sade de till henne: »I din släkt finnes ju ingen som har det namnet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 62, 'Och de frågade hans fader genom tecken vad han ville att barnet skulle heta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 63, 'Då begärde han en tavla och skrev dessa ord: »Johannes är hans namn.» Och alla förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 64, 'Men i detsamma öppnades hans mun, och hans tunga löstes, och han talade och lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 65, 'Och deras grannar betogos alla av häpnad, och ryktet om allt detta gick ut över Judeens hela bergsbygd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 66, 'Och alla som hörde det lade märke därtill och sade: »Vad månde väl varda av detta barn?» Också var ju Herrens hand med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 67, 'Och hans fader Sakarias blev uppfylld av helig ande och profeterade och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 68, '»Lovad vare Herren, Israels Gud, som har sett till sitt folk och berett det förlossning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 69, 'och som har upprättat åt oss ett frälsningens horn i sin tjänare Davids hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 70, 'såsom han hade lovat genom sin forntida heliga profeters mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 71, 'Ty han ville frälsa oss från våra ovänner och ur alla våra motståndares hand,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 72, 'och så göra barmhärtighet med våra fäder och tänka på sitt heliga förbund,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 73, 'vad han med ed hade lovat för vår fader Abraham,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 74, 'Han ville beskära oss att få tjäna honom utan fruktan, frälsta ur våra ovänners hand,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 75, 'ja, att göra tjänst inför honom i helighet och rättfärdighet i alla våra dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 76, 'Och du, barn, skall bliva kallad den Högstes profet, ty du skall gå framför Herren och bereda vägar för honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 77, 'till att giva hans folk kunskap om frälsning, i det att deras synder bliva dem förlåtna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 78, 'Så skall ske för vår Guds förbarmande kärleks skull, som skall låta ett ljus gå upp och skåda ned till oss från höjden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 79, 'för att \'skina över dem som sitta i mörker och dödsskugga\' och så styra våra fötter in på fridens väg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 80, 'Och barnet växte upp och blev allt starkare i anden. Och han vistades i öknen, intill den dag då han skulle träda fram för Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Och det hände sig vid den tiden att från kejsar Augustus utgick ett påbud att hela världen skulle skattskrivas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Detta var den första skattskrivningen, och den hölls, när Kvirinius var landshövding över Syrien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Då färdades alla var och en till sin stad, för att låta skattskriva sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Så gjorde ock Josef; och eftersom han var av Davids hus och släkt, for han från staden Nasaret i Galileen upp till Davids stad, som heter Betlehem, i Judeen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'för att låta skattskriva sig jämte Maria, sin trolovade, som var havande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Medan de voro där, hände sig att tiden var inne, då hon skulle föda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Och hon födde sin förstfödde son och lindade honom och lade honom i en krubba, ty det fanns icke rum för dem i härbärget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'I samma nejd voro då några herdar ute på marken och höllo vakt om natten över sin hjord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Då stod en Herrens ängel framför dem, och Herrens härlighet kringstrålade dem; och de blevo mycket förskräckta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Men ängeln sade till dem: »Varen icke förskräckta. Se, jag bådar eder en stor glädje, som skall vederfaras allt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Ty i dag har en Frälsare blivit född åt eder i Davids stad, och han är Messias, Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Och detta skall för eder vara tecknet: I skolen finna ett nyfött barn, som ligger lindat i en krubba.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'I detsamma sågs där jämte ängeln en stor hop av den himmelska härskaran, och de lovade Gud och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, '»Ära vare Gud i höjden, och frid på jorden, bland människor till vilka han har behag!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'När så änglarna hade farit ifrån herdarna upp i himmelen, sade dessa till varandra: »Låt oss nu gå till Betlehem och se det som där har skett, och som Herren har kungjort för oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Och de skyndade åstad dit och funno Maria och Josef, och barnet som låg i krubban.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Och när de hade sett det, omtalade de vad som hade blivit sagt till dem om detta barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Och alla som hörde det förundrade sig över vad herdarna berättade för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Men Maria gömde och begrundade allt detta i sitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Och herdarna vände tillbaka och prisade och lovade Gud för allt vad de hade fått höra och se, alldeles såsom det blivit dem sagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'När sedan åtta dagar hade gått till ända och han skulle omskäras, gavs honom namnet Jesus, det namn som hade blivit nämnt av ängeln, förrän han blev avlad i sin moders liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Och när deras reningsdagar hade gått till ända, de som voro föreskrivna i Moses\' lag, förde de honom upp till Jerusalem för att bära honom fram inför Herren,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'enligt den föreskriften i Herrens lag, att »allt mankön som öppnar moderlivet skall räknas såsom helgat åt Herren»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'så ock för att offra »ett par duvor eller två unga turturduvor», såsom stadgat var i Herrens lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'I Jerusalem levde då en man, vid namn Simeon, en rättfärdig och from man, som väntade på Israels tröst; och helig ande var över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Och av den helige Ande hade han fått den uppenbarelsen att han icke skulle se döden, förrän han hade fått se Herrens Smorde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 27, 'Han kom nu genom Andens tillskyndelse till helgedomen. Och när föräldrarna buro in barnet Jesus, för att så göra med honom som sed var efter lagen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 28, 'då tog också han honom i sin famn och lovade Gud och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 29, '»Herre, nu låter du din tjänare fara hädan i frid, efter ditt ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 30, 'ty mina ögon hava sett din frälsning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 31, 'vilken du har berett till att skådas av alla folk:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 32, 'ett ljus som skall uppenbaras för hedningarna, och en härlighet som skall givas åt ditt folk Israel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 33, 'Och hans fader och moder förundrade sig över det som sades om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 34, 'Och Simeon välsignade dem och sade till Maria, hans moder: »Se, denne är satt till fall eller upprättelse för många i Israel, och till ett tecken som skall bliva motsagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 35, 'Ja, också genom din själ skall ett svärd gå. Så skola många hjärtans tankar bliva uppenbara.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 36, 'Där fanns ock en profetissa, Hanna, Fanuels dotter, av Asers stam. Hon var kommen till hög ålder; i sju år hade hon levat med sin man, från den tid då hon var jungfru,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 37, 'och hon var nu änka, åttiofyra år gammal. Och hon lämnade aldrig helgedomen, utan tjänade där Gud med fastor och böner, natt och dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 38, 'Hon kom också i samma stund tillstädes och prisade Gud och talade om honom till alla dem som väntade på förlossning för Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 39, 'Och när de hade fullgjort allt som var stadgat i Herrens lag, vände de tillbaka till sin stad, Nasaret i Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 40, 'Men barnet växte upp och blev allt starkare och uppfylldes av vishet; och Guds nåd var över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 41, 'Nu plägade hans föräldrar årligen vid påskhögtiden begiva sig till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 42, 'När han var tolv år gammal, gingo de också dit upp, såsom sed var vid högtiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 43, 'Men när de hade varit med om alla högtidsdagarna och vände hem igen, stannade gossen Jesus kvar i Jerusalem, utan att hans föräldrar lade märke därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 44, 'De menade att han var med i ressällskapet och vandrade så en dagsled och sökte efter honom bland fränder och vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 45, 'När de då icke funno honom, vände de tillbaka till Jerusalem och sökte efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 46, 'Och efter tre dagar funno de honom i helgedomen, där han satt mitt ibland lärarna och hörde på dem och frågade dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 47, 'och alla som hörde honom blevo uppfyllda av häpnad över hans förstånd och hans svar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 48, 'När de nu fingo se honom där, förundrade de sig högeligen; och hans moder sade till honom: »Min son, varför gjorde du oss detta? Se, din fader och jag hava sökt efter dig med stor oro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 49, 'Då sade han till dem: »Varför behövden I söka efter mig? Vissten I då icke att jag bör vara där min Fader bor?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 50, 'Men de förstodo icke det som han talade till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 51, 'Så följde han med dem och kom ned till Nasaret; och han var dem underdånig. Och hans moder gömde allt detta i sitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 52, 'Och Jesus växte till i ålder och vishet och nåd inför Gud och människor[1]. [1] Eller: Och Jesus växte upp och växte till i vishet och nåd osv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'I femtonde året av kejsar Tiberius\' regering, när Pontius Pilatus var landshövding i Judeen, och Herodes var landsfurste i Galileen, och hans broder Filippus landsfurste i Itureen och Trakonitis-landet, och Lysanias landsfurste i Abilene,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'på den tid då Hannas var överstepräst jämte Kaifas -- då kom Guds befallning till Johannes, Sakarias\' son, i öknen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'och han gick åstad och predikade i hela trakten omkring Jordan bättringens döpelse till syndernas förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Så uppfylldes vad som var skrivet i profeten Esaias\' utsagors bok: »Hör rösten av en som ropar i öknen: Bereden vägen för Herren, gören stigarna jämna för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Alla dalar skola fyllas och alla berg och höjder sänkas; vad krokigt är skall bliva rak väg, och vad oländigt är skall bliva släta stigar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'och allt kött skall se Guds frälsning.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Han sade nu till folket som kom ut för att låta döpa sig av honom: »I huggormars avföda, vem har ingivit eder att söka komma undan den tillstundande vredesdomen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Bären då ock sådan frukt som tillhör bättringen. Och sägen icke vid eder själva: \'Vi hava ju Abraham till fader\'; Ty jag säger eder att Gud av dessa stenar kan uppväcka barn åt Abraham.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Redan är också yxan satt till roten på träden; så bliver då vart träd som icke bär god frukt avhugget och kastat på elden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Och folket frågade honom och sade: »Vad skola vi då göra?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Han svarade och sade till dem: »Den som har två livklädnader, han dele med sig åt den som icke har någon; och en som har matförråd, han göre sammalunda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Så kommo ock publikaner för att låta döpa sig, och de sade till honom: »Mästare, vad skola vi göra?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Han svarade dem: »Kräven icke ut mer än vad som är eder föreskrivet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Också krigsmän frågade honom och sade: »Vad skola då vi göra? Han svarade dem: »Tilltvingen eder icke penningar av någon, genom hot eller på annat otillbörligt sätt, utan låten eder nöja med eder sold.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Och folket gick där i förbidan, och alla undrade i sina hjärtan om Johannes icke till äventyrs vore Messias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Men Johannes tog till orda och sade: till dem alla: »Jag döper eder med vatten, men den som kommer, som är starkare än jag, den vilkens skorem jag icke är värdig att upplösa; han skall döpa eder i helig ande och eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Han har sin kastskovel i handen, ty han vill noga rensa sin loge och samla in vetet i sin lada; men agnarna skall han bränna upp i en eld som icke utsläckes.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Så förmanade han folket också i många andra stycken och förkunnade evangelium för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'Men när han hade förehållit Herodes, landsfursten, hans synd i fråga om hans broders hustru Herodias och förehållit honom allt det onda som han eljest hade gjort,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, 'lade Herodes till allt annat också det att han inspärrade Johannes i fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'När nu allt folket lät döpa sig och jämväl Jesus blev döpt, så skedde därvid, medan han bad, att himmelen öppnades,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 22, 'och den helige Ande sänkte sig ned över honom I lekamlig skepnad såsom en duva; och från himmelen kom en röst: »Du är min älskade Son; i dig har jag funnit behag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 23, 'Och Jesus var vid pass trettio år gammal, när han begynte sitt verk. Och man menade att han var son av Josef, som var son av Eli,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 24, 'som var son av Mattat, som var son av Levi, som var son av Melki, som var son av Jannai, som var son av Josef,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 25, 'som var son av Mattatias, som var son av Amos, som var son av Naum, som var son av Esli, som var son av Naggai,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 26, 'som var son av Maat, som var son av Mattatias, som var son av Semein, som var son av Josek, som var son av Joda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 27, 'som var son av Joanan, som var son av Resa, som var son av Sorobabel, som var son av Salatiel, som var son av Neri,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 28, 'som var son av Melki, som var son av Addi, som var son av Kosam, som var son av Elmadam, som var son av Er,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 29, 'som var son av Jesus, som var son av Elieser, som var son av Jorim, som var son av Mattat, som var son av Levi,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 30, 'som var son av Simeon, som var son av Judas, som var son av Josef, som var son av Jonam, som var son av Eljakim,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 31, 'som var son av Melea, som var son av Menna, som var son av Mattata, som var son av Natam, som var son av David,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 32, 'som var son av Jessai, som var son av Jobed, som var son av Boos, som var son av Sala, som var son av Naasson,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 33, 'som var son av Aminadab, som var son av Admin, som var son av Arni, som var son av Esrom, som var son av Fares, som var son av Judas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 34, 'som var son av Jakob, som var son av Isak, som var son av Abraham, som var son av Tara, som var son av Nakor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 35, 'som var son av Seruk, som var son av Ragau, som var son av Falek, som var son av Eber, som var son av Sala,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 36, 'som var son av Kainam, som var son av Arfaksad, som var son av Sem, som var son av Noa, som var son av Lamek,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 37, 'som var son av Matusala, som var son av Enok, som var son av Jaret som var son av Maleleel, som var son av Kainan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 38, 'som var son av Enos, som var son av Set, som var son av Adam, som var son av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Sedan vände Jesus tillbaka från Jordan, full av helig ande, och fördes genom Anden omkring i öknen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'och frestades av djävulen under fyrtio dagar. Och under de dagarna åt han intet; men när de hade gått till ända, blev han hungrig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Då sade djävulen till honom: »Är du Guds Son, så bjud denna sten att bliva bröd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Jesus svarade honom: »Det är skrivet: \'Människan skall leva icke allenast av bröd.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Och djävulen förde honom upp på en höjd och visade honom i ett ögonblick alla riken i världen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'och sade till honom: »Åt dig vill jag giva makten över allt detta med dess härlighet; ty åt mig har den blivit överlämnad, och åt vem jag vill kan jag giva den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Om du alltså tillbeder inför mig, så skall den hel och hållen höra dig till.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Jesus svarade och sade till honom: »Det är skrivet: \'Herren, din Gud, skall du tillbedja, och honom allena skall du tjäna.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Och han förde honom till Jerusalem och ställde honom uppe på helgedomens mur och sade till honom: »Är du Guds Son, så kasta dig ned härifrån;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'det är ju skrivet: \'Han skall giva sina änglar befallning om dig, att de skola väl bevara dig\';');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'så ock: \'De skola bära dig på händerna, så att du icke stöter din fot mot någon sten.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Då svarade Jesus och sade till honom: »Det är sagt: \'Du skall icke fresta Herren, din Gud.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'När djävulen så hade slutat med alla sina frestelser, vek han ifrån honom, intill läglig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Och Jesus vände i Andens kraft tillbaka till Galileen; och ryktet om honom gick ut i hela den kringliggande trakten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Och han undervisade i deras synagogor och blev prisad av alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Så kom han till Nasaret, där han var uppfödd. Och på sabbatsdagen gick han, såsom hans sed var, in i synagogan: och där stod han upp till att föreläsa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Då räckte man åt honom profeten Esaias\' bok; och när han öppnade boken, fick han se det ställe där det stod skrivet:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, '»Herrens Ande är över mig, ty han har smort mig. Han har satt mig till att förkunna glädjens budskap för de fattiga, till att predika frihet för de fångna och syn för de blinda, ja, till att giva de förtryckta frihet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'och till att predika ett nådens år från Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'Sedan lade han ihop boken och gav den tillbaka åt tjänaren och satte sig ned. Och alla som voro i synagogan hade sina ögon fästa på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, 'Då begynte han tala och sade till dem: »I dag är detta skriftens ord fullbordat inför edra öron.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'Och de gåvo honom alla sitt vittnesbörd och förundrade sig över de nådens ord som utgingo från hans mun, och sade: »Är då denne icke Josefs son?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'Då sade han till dem: »Helt visst skolen I nu vända mot mig det ordet: \'Läkare, bota dig själv\' och säga: \'Sådana stora ting som vi hava hört vara gjorda i Kapernaum, sådana må du göra också här i din fädernestad.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'Och han tillade: »Sannerligen säger jag eder: Ingen profet bliver i sitt fädernesland väl mottagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'Men jag säger eder, såsom sant är: I Israel funnos många änkor på Elias\' tid då himmelen var tillsluten i tre år och sex månader, och stor hungersnöd kom över hela landet --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 26, 'och likväl blev Elias icke sänd till någon av dessa, utan allenast till en änka i Sarepta i Sidons land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 27, 'Och många spetälska funnos i Israel på profeten Elisas tid; och likväl blev ingen av dessa gjord ren, utan allenast Naiman från Syrien.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 28, 'När de som voro i synagogan hörde detta, uppfylldes de alla av vrede');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 29, 'och stodo upp och drevo honom ut ur staden och förde honom ända fram till branten av det berg som deras stad var byggd på, och ville störta honom därutför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 30, 'Men han gick sin väg mitt igenom hopen och vandrade vidare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 31, 'Och han kom ned till Kapernaum, en stad i Galileen, och undervisade folket på sabbaten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 32, 'Och de häpnade över hans undervisning, ty han talade med makt och myndighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 33, 'Och i synagogan var en man som var besatt av en oren ond ande. Denne ropade med hög röst:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 34, '»Bort härifrån! Vad har du med oss att göra, Jesus från Nasaret? Har du kommit för att förgöra oss? Jag vet vem du är, du Guds Helige.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 35, 'Men Jesus tilltalade honom strängt och sade: »Tig och far ut ur honom.» Då kastade den onde anden omkull mannen mitt ibland dem och for ut ur honom, utan att hava gjort honom någon skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 36, 'Och häpnad kom över dem alla, och de talade med varandra och sade: »Vad är det med dennes ord? Med myndighet och makt befaller han ju de orena andarna, och de fara ut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 37, 'Och ryktet om honom spriddes åt alla håll i den kringliggande trakten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 38, 'Men han stod upp och gick ut ur synagogan och kom in i Simons hus. Och Simons svärmoder var ansatt av en svår feber, och de bådo honom för henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 39, 'Då trädde han fram och lutade sig över henne och näpste febern, och den lämnade henne; och strax stod hon upp och betjänade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 40, 'Men när solen gick ned, förde alla till honom sina sjuka, sådana som ledo av olika slags sjukdomar. Och han lade händerna på var och en av dem och botade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 41, 'Onda andar blevo ock utdrivna ur många, och de ropade därvid och sade: »Du är Guds Son.» Men han tilltalade dem strängt och tillsade dem att icke säga något, eftersom de visste att han var Messias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 42, 'Och när det åter hade blivit dag, gick han åstad bort till en öde trakt. Men folket sökte efter honom; och när de kommo fram till honom, ville de hålla honom kvar och hindra honom att gå sin väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 43, 'Men han sade till dem: »Också för de andra städerna måste jag förkunna evangelium om Guds rike, ty därtill har jag blivit utsänd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 44, 'Och han predikade i synagogorna i Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Då nu en gång folket, för att höra Guds ord, trängde sig inpå honom där han stod vid Gennesarets sjö,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'fick han se två båtar ligga vid sjöstranden; men de som fiskade hade gått i land och höllo på att skölja sina nät.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Då steg han i en av båtarna, den som tillhörde Simon, och bad honom lägga ut något litet från land. Sedan satte han sig ned och undervisade folket från båten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Och när han hade slutat att tala, sade han till Simon: »Lägg ut på djupet; och kasten där ut edra nät till fångst.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Då svarade Simon och sade: »Mästare, vi hava arbetat hela natten och fått intet; men på ditt ord vill jag kasta ut näten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Och när de hade gjort så, fingo de en stor hop fiskar i sina nät; och näten gingo sönder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Då vinkade de åt sina kamrater i den andra båten, att dessa skulle komma och hjälpa dem. Och de kommo och fyllde upp båda båtarna, så att de begynte sjunka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'När Simon Petrus såg detta, föll han ned för Jesu knän och sade: »Gå bort ifrån mig, Herre; jag är en syndig människa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ty för detta fiskafänges skull hade han och alla som voro med honom betagits av häpnad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'jämväl Jakob och Johannes, Sebedeus\' söner, som deltogo med Simon i fisket. Men Jesus sade till Simon: »Frukta icke; härefter skall du fånga människor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Och de förde båtarna i land och lämnade alltsammans och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Och medan han var i en av städerna, hände sig, att där kom en man som var full av spetälska. När denne fick se Jesus, föll han ned på sitt ansikte och bad honom och sade: »Herre, vill du, så kan du göra mig ren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Då räckte han ut handen och rörde vid honom och sade: »Jag vill; bliv ren.» Och strax vek spetälskan ifrån honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Och han förbjöd honom att omtala detta för någon, men tillade: »Gå åstad och visa dig för prästen och frambär för din rening ett offer, såsom Moses har påbjudit, till ett vittnesbörd för dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Men ryktet om honom spridde sig dess mer; och mycket folk samlade sig för att höra honom och för att bliva botade från sina sjukdomar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Men han drog sig undan till öde trakter och bad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Nu hände sig en dag, då han undervisade folket, att där sutto några fariséer och laglärare -- sådana hade nämligen kommit dit från alla byar i Galileen och Judeen och från Jerusalem -- och Herrens kraft verkade, så att sjuka blevo botade av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Då kommo några män dit med en lam man, som de buro på en säng; och de försökte komma in med honom för att lägga honom ned framför Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Men då de för folkets skull icke kunde finna något annat sätt att komma in med honom stego de upp på taket och släppte honom tillika med sängen ned genom tegelbeläggningen, mitt ibland dem, framför Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'När han såg deras tro, sade han: »Min vän, dina synder äro dig förlåtna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Då begynte de skriftlärde och fariséerna tänka så: »Vad är denne för en, som talar så hädiska ord? Vem kan förlåta synder utom Gud allena?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Men Jesus förnam deras tankar och svarade och sade till dem: »Vad är det I tänken i edra hjärtan?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'Vilket är lättare att säga: \'Dina synder äro dig förlåtna\' eller att säga: \'Stå upp och gå\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Men för att I skolen veta, att Människosonen har makt här på jorden att förlåta synder, så säger jag dig» (och härmed vände han sig till den lame): »Stå upp, tag din säng och gå hem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Då stod han strax upp i deras åsyn och tog sängen, som han hade legat på, och gick hem, prisande Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'Och de grepos alla av bestörtning och prisade Gud; och de sade, fulla av häpnad: »Vi hava i dag sett förunderliga ting.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'Sedan begav han sig därifrån. Och han fick se en publikan, vid namn Levi, sitta vid tullhuset. Och han sade till denne: »Följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Då lämnade han allt och stod upp och följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 29, 'Och Levi gjorde i sitt hus ett stort gästabud för honom; och en stor hop publikaner och andra voro bordsgäster där jämte dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 30, 'Men fariséerna -- särskilt de skriftlärde bland dem -- knorrade mot hans lärjungar och sade: »Huru kunnen I äta och dricka med publikaner och syndare?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 31, 'Då svarade Jesus och sade till dem: »De är icke de friska som behöva läkare, utan de sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 32, 'Jag har icke kommit för att kalla rättfärdiga, utan syndare, till bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 33, 'Och de sade till honom: »Johannes\' lärjungar fasta ofta och hålla böner, sammalunda ock fariséernas; men dina lärjungar äta och dricka.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 34, 'Jesus svarade dem: »Icke kunnen I väl ålägga bröllopsgästerna att fasta, medan brudgummen ännu är hos dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 35, 'Men en annan tid skall komma, och då, när brudgummen tages ifrån dem, då, på den tiden, skola de fasta.» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 36, 'Han framställde ock för dem denna liknelse: »Ingen river av en lapp från en ny mantel och sätter den på en gammal mantel; om någon så gjorde, skulle han icke allenast riva sönder den nya manteln, utan därtill komme, att lappen från den nya manteln icke skulle passa den gamla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 37, 'Ej heller slår någon nytt vin i gamla skinnläglar; om någon så gjorde, skulle det nya vinet spränga sönder läglarna, och vinet skulle spillas ut, jämte det att läglarna fördärvades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 38, 'Nej, nytt vin bör man slå i nya läglar. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 39, 'Och ingen som har druckit gammalt vin vill sedan gärna hava nytt; ty han tycker, att det gamla är bättre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, 'Och det hände sig på en sabbat att han tog vägen genom ett sädesfält; och hans lärjungar ryckte av axen och gnuggade sönder dem med händerna och åto.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, 'Då sade några av fariséerna; »Huru kunnen I göra vad som icke är lovligt att göra på sabbaten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, 'Jesus svarade och sade till dem: »Haven I icke läst om det som David gjorde, när han själv och de som följde honom blevo hungriga:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'huru han då gick in i Guds hus och tog skådebröden och åt, och jämväl gav åt dem som följde honom, fastän det ju icke är lovligt för andra än allenast för prästerna att äta sådant bröd?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Därefter sade han till dem: »Människosonen är herre över sabbaten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'På en annan sabbat hände sig att han gick in i synagogan och undervisade. Där var då en man vilkens högra hand var förvissnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'Och de skriftlärde och fariséerna vaktade på honom, för att se om han botade någon på sabbaten; de ville nämligen finna något att anklaga honom för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'Men han förstod deras tankar och sade till mannen som hade den förvissnade handen: »Stå upp, och träd fram.» Då stod han upp och trädde fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'Sedan sade Jesus till dem: »Jag vill göra eder en fråga. Vilketdera är lovligt på sabbaten: att göra vad gott är, eller att göra vad ont är, att rädda någons liv, eller att förgöra det?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Och han såg sig omkring på dem alla och sade till mannen: »Räck ut din hand.» Och han gjorde så; och hans hand blev frisk igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Men de blevo såsom ursinniga och talade med varandra om vad de skulle kunna företaga sig mot Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Så hände sig på den tiden att han gick åstad upp på berget för att bedja; och han blev kvar där över natten i bön till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'Men när det blev dag, kallade han till sig sina lärjungar och utvalde bland dem tolv, som han ock benämnde apostlar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, 'Simon, vilken han ock gav namnet Petrus, och Andreas, hans broder; vidare Jakob och Johannes och Filippus och Bartolomeus');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'och Matteus och Tomas och Jakob, Alfeus\' son, och Simon, som kallades ivraren;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'vidare Judas, Jakobs son, och Judas Iskariot, den som blev en förrädare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, 'Dessa tog han nu med sig och steg åter ned och stannade på en jämn plats; och en stor skara av hans lärjungar var där församlad, så ock en stor hop folk ifrån hela Judeen och Jerusalem, och från kuststräckan vid Tyrus och Sidon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'Dessa hade kommit för att höra honom och för att bliva botade från sina sjukdomar. Och jämväl de som voro kvalda av orena andar blevo botade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'Och allt folket sökte att få röra vid honom, ty kraft gick ut ifrån honom och botade alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'Och han lyfte upp sina ögon och säg på sina lärjungar och sade: »Saliga ären I, som ären fattiga, ty eder hör Guds rike till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Saliga ären I, som nu hungren, ty I skolen bliva mättade. Saliga ären I, som nu gråten, ty I skolen le.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'Saliga ären I, när människorna för Människosonens skull hata eder och förskjuta och smäda eder och kasta bort edert namn såsom något ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Glädjens på den dagen, ja, springen upp av fröjd, ty se, eder lön är stor i himmelen. På samma satt gjorde ju deras fäder med profeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 24, 'Men ve eder, I som ären rika, ty I haven fått ut eder hugnad!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 25, 'Ve eder, som nu ären mätta, ty I skolen hungra! Ve eder, som nu len, ty I skolen sörja och gråta!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 26, 'Ve eder, när alla människor tala väl om eder! På samma sätt gjorde ju deras fader i fråga om de falska profeterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 27, 'Men till eder, som hören mig, säger jag: Älsken edra ovänner, gören gott mot dem som hata eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 28, 'välsignen dem som förbanna eder, bedjen för dem som förorätta eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 29, 'Om någon slår dig på den ena kinden, så håll ock fram den andra åt honom; och om någon tager manteln ifrån dig, så förvägra honom icke heller livklädnaden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 30, 'Giv åt var och en som beder dig; och om någon tager ifrån dig vad som är ditt, så kräv det icke igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 31, 'Såsom I viljen att människorna skola göra mot eder, så skolen I ock göra mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 32, 'Om I älsken dem som älska eder, vad tack kunnen I få därför? Också syndare älska ju dem av vilka de bliva älskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 33, 'Och om I gören gott mot dem som göra eder gott, vad tack kunnen I få därför? Också syndare göra ju detsamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 34, 'Och om I lånen åt dem av vilka I kunnen hoppas att själva få något, vad tack kunnen I få därför? Också syndare låna ju åt syndare för att få lika igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 35, 'Nej, älsken edra ovänner, och gören gott och given lån utan att hoppas på någon gengäld. Då skall eder lön bliva stor, och då skolen I vara den Högstes barn; ty han är mild mot de otacksamma och onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 36, 'Varen barmhärtiga, såsom eder Fader är barmhärtig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 37, 'Dömen icke, så skolen I icke bliva dömda; fördömen icke, så skolen I icke bliva fördömda. Förlåten, och eder skall bliva förlåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 38, 'Given, och eder skall bliva givet. Ett gott mått, väl packat, skakat och överflödande, skall man giva eder i skötet; ty med det mått som I mäten med skall ock mätas åt eder igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 39, 'Han framställde ock för dem denna liknelse: »Kan väl en blind leda en blind? Falla de icke då båda i gropen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 40, 'Lärjungen är icke förmer än sin mästare; när någon bliver fullärd, så bliver han allenast sin mästare lik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 41, 'Huru kommer det till, att du ser grandet i din broders öga, men icke bliver varse bjälken i ditt eget öga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 42, 'Huru kan du säga till din broder: \'Broder, låt mig taga ut grandet i ditt öga\', du som icke ser bjälken i ditt eget öga? Du skrymtare, tag först ut bjälken ur ditt eget öga; därefter må du se till, att du kan tala ut grandet i din broders öga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 43, 'Ty intet gott träd finnes, som bär dålig frukt, och lika litet finnes något dåligt träd som bär god frukt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 44, 'vart och ett träd kännes ju igen på sin frukt. Icke hämtar man väl fikon ifrån törnen, ej heller skördar man vindruvor av törnbuskar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 45, 'En god människa bär ur sitt hjärtas goda förråd fram vad gott är, och en ond människa bär ur sitt onda förråd fram vad ont är; ty vad hennes hjärta är fullt av, det talar hennes mun. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 46, 'Men varför ropen I till mig: \'Herre, Herre\', och gören dock icke vad jag säger?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 47, 'Var och en som kommer till mig och hör mina ord och gör efter dem, vem han är lik, det skall jag visa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 48, 'Han är lik en man som ville bygga ett hus och som då grävde djupt och lade dess grund på hälleberget. När sedan översvämning kom, störtade sig vattenströmmen mot det huset, men den förmådde dock icke skaka det, eftersom det var så byggt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 49, 'Men den som hör och icke gör, han är lik en man som byggde ett hus på blotta jorden, utan att lägga någon grund. Och vattenströmmen störtade sig emot det, och strax föll det samman, och det husets fall blev stort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 1, 'När han nu hade talat allt detta till slut inför folket, gick han in i Kapernaum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 2, 'Men där var en hövitsman som hade en tjänare, vilken låg sjuk och var nära döden; och denne var högt skattad av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 3, 'Då han nu fick höra om Jesus, sände han till honom några av judarnas äldste och bad honom komma och bota hans tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 4, 'När dessa kommo till Jesus, bådo de honom enträget och sade: »Han är värd att du gör honom detta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 5, 'ty han har vårt folk kärt, och det är han som har byggt synagogan åt oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 6, 'Då gick Jesus med dem. Men när han icke var långt ifrån hövitsmannens hus, sände denne några av sina vänner och lät säga till honom: »Herre, gör dig icke omak; ty jag är icke värdig att du går in under mitt tak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 7, 'Därför har jag ej heller aktat mig själv värdig att komma till dig Men säg ett ord, så bliver min tjänare frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 8, 'Jag är ju själv en man som står under andras befäl; jag har ock krigsmän under mig, och om jag säger till en av dem: \'Gå\', så går han, eller till en annan: \'Kom\', så kommer han, och om jag säger till min tjänare: \'Gör det\', då gör han så.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 9, 'När Jesus hörde detta, förundrade han sig över honom och vände sig om och sade till folket som följde honom: »Jag säger eder: Icke ens i Israel har jag funnit så stor tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 10, 'Och de som hade blivit utsända gingo hem igen och funno tjänaren vara frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 11, 'Därefter begav han sig till en stad som hette Nain; och med honom gingo hans lärjungar och mycket folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 12, 'Och se, då han kom nära stadsporten, bars där ut en död, och han var sin moders ende son, och hon var änka; och en ganska stor hop folk ifrån staden gick med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 13, 'När Herren fick se henne, ömkade han sig över henne och sade till henne: »Gråt icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 14, 'Och han gick fram och rörde vid båren, och de som buro stannade. Och han sade: »Unge man, jag säger dig: Stå upp.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 15, 'Då satte sig den döde upp och begynte tala. Och han gav honom åt hans moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 16, 'Och alla betogos av häpnad och prisade Gud och sade: Den stor profet har uppstått ibland oss» och: »Gud har sett till sitt folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 17, 'Och detta tal om honom gick ut i hela Judeen och i hela landet däromkring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 18, 'Och allt detta fick Johannes höra berättas av sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 19, 'Då kallade Johannes till sig två av sina lärjungar och sände dem till Herren med denna fråga: »Är du den som skulle komma, eller skola vi förbida någon annan?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 20, 'När mannen kommo fram till honom, sade de: »Johannes döparen har sänt oss till dig och låter fråga: \'Är du den som skulle komma, eller skola vi förbida någon annan?\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 21, 'Just då höll Jesus på med att bota många som ledo av sjukdomar och plågor, eller som voro besatta av onda andar, och åt många blinda gav han deras syn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 22, 'Och han svarade och sade till männen: »Gån tillbaka och omtalen för Johannes vad I haven sett och hört: blinda få sin syn, halta gå, spetälska bliva rena, döva höra, döda uppstå, \'för fattiga förkunnas glädjens budskap\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 23, 'Och salig är den för vilken jag icke bliver en stötesten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 24, 'När sedan Johannes\' sändebud hade gått sin väg, begynte han tala till folket om Johannes: »Varför var det I gingen ut i öknen? Var det för att se ett rör som drives hit och dit av vinden?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 25, 'Eller varför gingen I ut? Var det för att se en människa klädd i fina kläder? De som bära präktiga kläder och leva i kräslighet, dem finnen I ju i konungapalatsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 26, 'Varför gingen I då ut? Var det för att se en profet? Ja, jag säger eder: Ännu mer än en profet är han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 27, 'Han är den om vilken det är skrivet: \'Se, jag sänder ut min ängel framför dig, och han skall bereda vägen för dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 28, 'Jag säger eder: Bland dem som äro födda av kvinnor har ingen varit större än Johannes; men den som är minst i Guds rike är likväl större än han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 29, 'Så gav ock allt folket som hörde honom Gud rätt, jämväl publikanerna, och läto döpa sig med Johannes\' dop.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 30, 'Men fariséerna och de lagkloke föraktade Guds rådslut i fråga om dem själva och läto icke döpa sig av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 31, 'Vad skall jag då likna detta släktes människor vid? Ja, vad äro de lika?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 32, 'De äro lika barn som sitta på torget och ropa till varandra och säga: \'Vi hava spelat för eder, och I haven icke dansat; vi hava sjungit sorgesång, och I haven icke gråtit.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 33, 'Ty Johannes döparen har kommit, och han äter icke bröd och dricker ej heller vin, och så sägen I: \'Han är besatt av en ond ande.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 34, 'Människosonen har kommit, och han både äter och dricker, och nu sägen I: \'Se, vilken frossare och vindrinkare han är, en publikaners och syndares vän!\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 35, 'Men Visheten har fått rätt av alla sina barn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 36, 'Och en farisé inbjöd honom till en måltid hos sig; och han gick in i fariséens hus och lade sig till bords.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 37, 'Nu fanns där i staden en synderska; och när denna fick veta att han låg till bords i fariséens hus, gick hon dit med en alabasterflaska med smörjelse');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 38, 'och stannade bakom honom vid hans fötter, gråtande, och begynte väta hans fötter med sina tårar och torkade dem med sitt huvudhår och kysste ivrigt hans fötter och smorde dem med smörjelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 39, 'Men när fariséen som hade inbjudit honom såg detta, sade han vid sig själv: »Vore denne en profet, så skulle han känna till, vilken och hurudan denna kvinna är, som rör vid honom; han skulle då veta att hon är en synderska.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 40, 'Då tog Jesus till orda och sade till honom: »Simon, jag har något att säga dig.» Han svarade: »Mästare, säg det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 41, '»En man som lånade ut penningar hade två gäldenärer. Den ene var skyldig honom fem hundra silverpenningar, den andre femtio.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 42, 'Men då de icke kunde betala, efterskänkte han skulden för dem båda. Vilken av dem kommer nu att älska honom mest?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 43, 'Simon svarade och sade: »Jag menar den åt vilken han efterskänkte mest.» Då sade han till honom: »Rätt dömde du»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 44, 'Och så vände han sig åt kvinnan och sade till Simon: »Ser du denna kvinna? När jag kom in i ditt hus, gav du mig intet vatten till mina fötter, men hon har vätt mina fötter med sina tårar och torkat dem med sitt hår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 45, 'Du gav mig ingen hälsningskyss, men ända ifrån den stund då jag kom hitin, har hon icke upphört att ivrigt kyssa mina fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 46, 'Du smorde icke mitt huvud med olja, men hon har smort mina fötter med smörjelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 47, 'Fördenskull säger jag dig: Hennes många synder äro henne förlåtna; hon har ju ock visat mycken kärlek. Men den som får litet förlåtet, han älskar ock litet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 48, 'Sedan sade han till henne: »Dina synder äro dig förlåtna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 49, 'Då begynte de som voro bordsgäster jämte honom att säga vid sig själva: »Vem är denne, som till och med förlåter synder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 50, 'Men han sade till kvinnan: »Din tro har frälst dig. Gå i frid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 1, 'Därefter vandrade han igenom landet, från stad till stad och från by till by, och predikade och förkunnade evangelium om Guds rike. Och med honom följde de tolv,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 2, 'så ock några kvinnor som hade blivit befriade från onda andar och botade från sjukdomar: Maria, som kallades Magdalena, ur vilken sju onda andar hade blivit utdrivna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 3, 'och Johanna, hustru till Herodes\' fogde Kusas, och Susanna och många andra som tjänade dem med sina ägodelar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 4, 'Då nu mycket folk kom tillhopa, i det att inbyggarna i de särskilda städerna begåvo sig ut till honom, sade han i en liknelse:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 5, '»En såningsman gick ut för att så sin säd. Och när han sådde, föll somt vid vägen och blev nedtrampat, och himmelens fåglar åto upp det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 6, 'Och somt föll på stengrund, och när det hade vuxit upp, torkade det bort, eftersom det icke där hade någon fuktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 7, 'Och somt föll bland törnen, och törnena växte upp tillsammans därmed och förkvävde det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 8, 'Men somt föll i god jord, och när det hade vuxit upp, bar det hundrafaldig frukt.» Sedan han hade talat detta, sade han med hög röst: »Den som har öron till att höra, han höre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 9, 'Då frågade hans lärjungar honom vad denna liknelse betydde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 10, 'Han sade: »Eder är givet att lära känna Guds rikes hemligheter, men åt de andra meddelas de i liknelser, för att de med seende ögon intet skola se och med hörande öron intet förstå\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 11, 'Så är nu detta liknelsens mening: Säden är Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 12, 'Och att den såddes vid vägen, det är sagt om dem som hava hört ordet, men sedan kommer djävulen och tager bort det ur deras hjärtan, för att de icke skola komma till tro och bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 13, 'Och att den såddes på stengrunden det är sagt om dem, som när de få höra ordet, taga emot det med glädje, men icke hava någon rot; de tro allenast till en tid, och i frestelsens stund avfalla de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 14, 'Och att den föll bland törnena, det är sagt om dem, som när de hava hört ordet, gå bort och låta sig förkvävas av rikedomens omsorger och njutandet av livets goda och så icke föra något fram till mognad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 15, 'Men att den föll i den goda jorden, det är sagt om dem, som när de hava hört ordet, behålla det i rättsinniga och goda hjärtan och bära frukt i ståndaktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 16, 'Ingen tänder ett ljus och gömmer det sedan under ett kärl eller sätter det under en bänk, utan man sätter det på en ljusstake, för att de som komma in skola se skenet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 17, 'Ty intet är fördolt, som icke skall bliva uppenbart, ej heller är något undangömt, som icke skall bliva känt och komma i dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 18, 'Akten fördenskull på huru I hören. Ty den som har, åt honom skall varda givet; men den som icke har, från honom skall tagas också det han menar sig hava.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 19, 'Och hans moder och hans bröder kommo och sökte honom, men för folkets skull kunde de icke komma in till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 20, 'Då sade man till honom: »Din moder och dina broder stå härutanför och vilja träffa dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 21, 'Men han svarade och sade till dem: »Min moder och mina bröder äro dessa, som höra Guds ord och göra det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 22, 'En dag steg han med sina lärjungar i en båt och sade till dem: »Låt oss fara över sjön till andra sidan.» Och de lade ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 23, 'Och medan de seglade fram, somnade han. Men en stormvind for ned över sjön, och deras båt begynte fyllas med vatten, så att de voro i fara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 24, 'Då gingo de fram och väckte upp honom och sade: »Mästare, Mästare, vi förgås.» När han så hade vaknat, näpste han vinden och vattnets vågor, och de stillades, och det blev lugnt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 25, 'Därefter sade han till dem: »Var är eder tro?» Men de hade blivit häpna och förundrade sig och sade till varandra: »Vem är då denne? Han befaller ju både vindarna och vattnet, och de lyda honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 26, 'Så foro de över till gerasenernas land, som ligger mitt emot Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 27, 'Och när han hade stigit i land, kom en man från staden emot honom, en som var besatt av onda andar, och som under ganska lång tid icke hade haft kläder på sig och icke bodde i hus, utan bland gravarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 28, 'Då nu denne fick se Jesus, skriade han och föll ned för honom och sade med hög röst: »Vad har du med mig att göra, Jesus, du Guds, den Högstes, son? Jag beder dig, plåga mig icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 29, 'Jesus skulle nämligen just bjuda den orene anden att fara ut ur mannen. Ty i lång tid hade han farit svårt fram med mannen; och väl hade denne varit fängslad med kedjor och fotbojor och hållits i förvar, men han hade slitit sönder bojorna och hade av den onde anden blivit driven ut i öknarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 30, 'Jesus frågade honom: »Vad är ditt namn?» Han svarade: »Legion.» Ty det var många onda andar som hade farit in i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 31, 'Och dessa bådo Jesus att han icke skulle befalla dem att fara ned i avgrunden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 32, 'Nu gick där en ganska stor svinhjord i bet på berget. Och de bådo honom att han ville tillstädja dem att fara in i svinen. Och han tillstadde dem det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 33, 'Då gåvo sig de onda andarna åstad ut ur mannen och foro in i svinen. Och hjorden störtade sig utför branten ned i sjön och drunknade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 34, 'Men när herdarna sågo vad som hade skett, flydde de och berättade härom i staden och på landsbygden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 35, 'Och folket gick ut för att se vad som hade skett. När de då kommo till Jesus, funno de mannen, ur vilken de onda andarna hade blivit utdrivna, sitta invid Jesu fötter, klädd och vid sina sinnen; och de betogos av häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 36, 'Och de som hade sett händelsen omtalade för dem huru den besatte hade blivit botad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 37, 'Allt folket ifrån den kringliggande trakten av gerasenernas land bad då Jesus att han skulle gå bort ifrån dem, ty de voro gripna av stor förskräckelse. Så steg han då i en båt för att vända tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 38, 'Och mannen, ur vilken de onda andarna hade blivit utdrivna, bad honom att få följa honom. Men Jesus tillsade honom att gå, med de orden:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 39, '»Vänd tillbaka hem, och förtälj huru stora ting Gud har gjort med dig.» Då gick han bort och förkunnade i hela staden huru stora ting Jesus hade gjort med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 40, 'När Jesus kom tillbaka, mottogs han av folket; ty alla väntade de på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 41, 'Då kom där en man, vid namn Jairus, som var föreståndare för synagogan. Denne föll ned för Jesu fötter och bad honom att han skulle komma till hans hus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 42, 'ty han hade ett enda barn, en dotter, vid pass tolv år gammal, som låg för döden. Men under det att han var på väg dit, trängde folket hårt på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 43, 'Nu var där en kvinna som hade haft blodgång i tolv år och icke hade kunnat botas av någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 44, 'Hon närmade sig honom bakifrån och rörde vid hörntofsen på hans mantel, och strax stannade hennes blodgång');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 45, 'Men Jesus frågade: »Vem var det som rörde vid mig?» Då alla nekade till att hava gjort det, sade Petrus: »Mästare, hela folkhopen trycker och tränger dig ju.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 46, 'Men Jesus sade: »Det var någon som rörde vid mig; ty jag kände att kraft gick ut ifrån mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 47, 'Då nu kvinnan såg att hon icke hade blivit obemärkt, kom hon fram bävande och föll ned för honom och omtalade inför allt folket varför hon hade rört vid honom, och huru hon strax hade blivit frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 48, 'Då sade han till henne: »Min dotter, din tro har hjälpt dig. Gå i frid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 49, 'Medan han ännu talade, kom någon från synagogföreståndarens hus och sade: »Din dotter är död; du må icke vidare göra mästaren omak.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 50, 'Men när Jesus hörde detta, sade han till honom: »Frukta icke; tro allenast, så får hon liv igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 51, 'Och när han hade kommit fram till hans hus, tillstadde han ingen att gå med ditin, utom Petrus och Johannes och Jakob och därtill flickans fader och moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 52, 'Och alla gräto och jämrade sig över henne. Men han sade: »Gråten icke; hon är icke död, hon sover.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 53, 'Då hånlogo de åt honom, ty de visste ju att hon var död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 54, 'Men han tog henne vid handen och sade med hög röst: »Flicka, stå upp.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 55, 'Då kom hennes ande igen, och hon stod strax upp. Och han tillsade att man skulle giva henne något att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 56, 'Och hennes föräldrar blevo uppfyllda av häpnad; men han förbjöd dem att för någon omtala vad som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 1, 'Och han kallade tillhopa de tolv och gav dem makt och myndighet över alla onda andar, så ock makt att bota sjukdomar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 2, 'Och han sände ut dem till att predika Guds rike och till att bota sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 3, 'Och han sade till dem: »Tagen intet med eder på vägen, varken stav eller ränsel eller bröd eller penningar, och haven icke heller dubbla livklädnader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 4, 'Och när I haven kommit in något hus, så stannen där, till dess I lämnen den orten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 5, 'Och om man någonstädes icke tager emot eder, så gån bort ifrån den staden, och skudden stoftet av edra fötter, till ett vittnesbörd mot dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 6, 'Och de gingo ut och vandrade igenom landet, från by till by, och förkunnade evangelium och botade sjuka allestädes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 7, 'Men när Herodes, landsfursten, fick höra om allt detta som skedde visste han icke vad han skulle tro. Ty somliga sade: »Det är Johannes, som har uppstått från de döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 8, 'Men andra sade: »Det är Elias, som har visat sig.» Andra åter sade: »Det är någon av de gamla profeterna, som har uppstått.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 9, 'Men Herodes själv sade: »Johannes har jag låtit halshugga. Vem är då denne, som jag hör sådant om?» Och han sökte efter tillfälle att få se honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 10, 'Och apostlarna kommo tillbaka och förtäljde för Jesus huru stora ting de hade gjort. De tog han dem med sig och drog sig undan till en stad som hette Betsaida, där de kunde vara allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 11, 'Men när folket fick veta detta, gingo de efter honom. Och han lät dem komma till sig och talade till dem om Guds rike; och dem som behövde botas gjorde han friska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 12, 'Men dagen begynte nalkas sitt slut. Då trädde de tolv fram och sade till honom: »Låt folket skiljas åt, så att de kunna gå bort i byarna och gårdarna häromkring och skaffa sig härbärge och få mat; vi äro ju här i en öde trakt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 13, 'Men han sade till dem: »Given I dem att äta.» De svarade: »Vi hava icke mer än fem bröd och två fiskar, såframt vi icke skola gå bort och köpa mat åt allt detta folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 14, 'Där voro nämligen vid pass fem tusen män. Då sade han till sina lärjungar: »Låten dem lägga sig ned i matlag, femtio eller så omkring i vart.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 15, 'Och de gjorde så och läto dem alla lägga sig ned.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 16, 'Därefter tog han de fem bröden och de två fiskarna och säg upp till himmelen och välsignade dem. Och han bröt bröden och gav åt lärjungarna, för att de skulle lägga fram åt folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 17, 'Och de åto alla och blevo mätta. sedan samlade man upp de stycken som hade blivit över efter dem, tolv korgar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 18, 'När han en gång hade dragit sig undan och var stadd i byn, voro hans lärjungar hos honom. Och han frågade dem och sade: »Vem säger folket mig vara?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 19, 'De svarade och sade: »Johannes döparen; dock säga andra Elias; andra åter säga: \'Det är någon av de gamla profeterna, som har uppstått.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 20, 'Då frågade han dem: »Vem sägen då I mig vara?» Petrus svarade och sade: »Guds Smorde.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 21, 'Då förbjöd han dem strängeligen att säga detta till någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 22, 'Och han sade: »Människosonen måste lida mycket, och han skall bliva förkastad av de äldste och översteprästerna och de skriftlärda och skall bliva dödad, men på tredje dagen skall han uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 23, 'Och han sade till alla: »Om någon vill efterfölja mig, så försake han sig själv och tage sitt kors på sig var dag; så följe han mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 24, 'Ty den som vill bevara sitt liv han skall mista det; men den som mister sitt liv, för min skull, han skall bevara det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 25, 'Och vad hjälper det en människa om hon vinner hela världen, men mister sig själv eller själv går förlorad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 26, 'Den som blyges för mig och för mina ord, för honom skall Människosonen blygas, när han kom mer i sin och min Faders och de heliga änglarnas härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 27, 'Men sannerligen säger jag eder: Bland dem som här stå finnas några som icke skola smaka döden, förrän de få se Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 28, 'Vid pass åtta dagar efter det att han hade talat detta tog han Petrus och Johannes och Jakob med sig och gick upp på berget för att bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 29, 'Och under det att han bad, blev hans ansikte förvandlat, och hans kläder blevo skinande vita.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 30, 'Och de, två män stodo där och samtalade med honom, och dessa voro Moses och Elias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 31, 'De visade sig i härlighet och talade om hans bortgång, vilken han skulle fullborda i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 32, 'Men Petrus och de som voro med honom voro förtyngda av sömn; då de sedan vaknade, sågo de hans härlighet och de båda männen, som stodo hos honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 33, 'När så dessa skulle skiljas ifrån honom, sade Petrus till Jesus: »Mästare, har är oss gott att vara; låt oss göra tre hyddor, en åt dig och en åt Moses och en åt Elias.» Han visste nämligen icke vad han sade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 34, 'Medan han så talade, kom en sky och överskyggde dem; och de blevo förskräckta, när de trädde in i skyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 35, 'Och ur skyn kom en röst som sade: »Denne är min Son, den utvalde; hören honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 36, 'Och i detsamma som rösten kom, funno de Jesus vara där allena. -- Och de förtego detta och omtalade icke för någon på den tiden något av vad de hade sett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 37, 'När de dagen därefter gingo ned från berget, hände sig att mycket folk kom honom till mötes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 38, 'Då ropade en man ur folkhopen och sade: »Mästare, jag beder dig, se till min son, ty han är mitt enda barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 39, 'Det är så, att en ande plägar gripa fatt i honom, och strax skriar han då, och anden sliter och rycker honom, och fradgan står honom om munnen. Och det är med knapp nöd han släpper honom, sedan han har sönderbråkat honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 40, 'Nu bad jag dina lärjungar att de skulle driva ut honom, men de kunde det icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 41, 'Då svarade Jesus och sade: »O du otrogna och vrånga släkte, huru länge måste jag vara hos eder och härda ut med eder? För hit din son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 42, 'Men ännu medan denne var på väg fram, kastade den onde anden omkull honom och slet och ryckte honom. Då tilltalade Jesus den orene anden strängt och gjorde gossen frisk och gav honom tillbaka åt hans fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 43, 'Och alla häpnade över Guds stora makt. Då nu alla förundrade sig över alla de gärningar som han gjorde, sade han till sina lärjungar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 44, '»Tagen emot dessa ord med öppna öron: Människosonen skall bliva överlämnad i människors händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 45, 'Men de förstodo icke detta som han sade, och det var förborgat för dem, så att de icke kunde fatta det; dock fruktade de att fråga honom om det som han hade sagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 46, 'Och bland dem uppstod tanken på vilken av dem som vore störst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 47, 'Men Jesus förstod deras hjärtans tankar och tog ett barn och ställde det bredvid sig');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 48, 'och sade till dem: »Den som tager emot detta barn i mitt namn, han tager emot mig, och den som tager emot mig, han tager emot honom som har sänt mig. Ty den som är minst bland eder alla, han är störst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 49, 'Och Johannes tog till orda och sade: »Mästare, sågo huru en man drev ut onda andar genom ditt namn; och du ville hindra honom, eftersom han icke följde med oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 50, 'Men Jesus sade till honom: »Hindren honom icke; ty den som icke är emot eder, han är för eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 51, 'Då nu tiden var inne att han skulle bliva upptagen, beslöt han att ställa sin färd till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 52, 'Och han sände budbärare framför sig; och de gingo åstad och kommo in i en samaritisk by för att reda till åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 53, 'Men folket där tog icke emot honom, eftersom han var stadd på färd till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 54, 'När de båda lärjungarna Jakob i och Johannes förnummo detta, sade de: »Herre, vill du att vi skola bedja att eld kommer ned från himmelen och förtär dem?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 55, 'Då vände han sig om och tillrättavisade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 56, 'Och de gingo till en annan by.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 57, 'Medan de nu färdades fram på vägen, sade någon till honom: »Jag vill följa dig, varthelst du går.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 58, 'Då svarade Jesus honom: »Rävarna hava kulor, och himmelens fåglar hava nästen; men Människosonen har ingen plats där han kan vila sitt huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 59, 'Och till en annan sade han: »Föl; mig.» Men denne svarade: »Tillstäd mig att först gå bort och begrava min fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 60, 'Då sade han till honom: »Låt de döda begrava sina döda; men gå du åstad och förkunna Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 61, 'Åter en annan sade: »Jag vill följa dig, Herre, men tillstäd mig att först taga avsked av dem som höra till mitt hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 62, 'Då svarade Jesus honom: »Ingen som ser sig tillbaka, sedan han har satt sin hand till plogen, är skickad för Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 1, 'Därefter utsåg Herren sjuttiotvå andra och sände ut dem framför sig, två och två, till var stad och ort dit han själv tänkte komma');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 2, '»Skörden är mycken, men arbetarna äro få. Bedjen fördenskull skördens Herre att han sänder ut arbetare till sin skörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 3, 'Gån åstad. Se, jag sänder eder såsom lamm mitt in ibland ulvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 4, 'Bären ingen penningpung, ingen ränsel, inga skor, och hälsen icke på någon under vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 5, 'Men när I kommen in i något hus, så sägen först: \'Frid vare över detta hus.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 6, 'Om då någon finnes därinne, som är frid värd, så skall den frid I tillönsken vila över honom; varom icke, så skall den vända tillbaka över eder själva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 7, 'Och stannen kvar i det huset, och äten och dricken vad de hava att giva, ty arbetaren är värd sin lön. Gån icke ur hus i hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 8, 'Och när I kommen in i någon stad där man tager emot eder, så äten vad som sättes fram åt eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 9, 'och boten de sjuka som finnas där, och sägen till dem: \'Guds rike är eder nära.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 10, 'Men när I kommen in i någon stad där man icke tager emot eder, så gån ut på dess gator och sägen:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 11, '\'Till och med det stoft som låder vid våra fötter ifrån eder stad skaka vi av oss åt eder. Men det mån I veta, att Guds rike är nära.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 12, 'Jag säger eder att det för Sodom skall på \'den dagen\' bliva drägligare än för den staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 13, 'Ve dig, Korasin! Ve dig, Betsaida! Ty om de kraftgärningar som äro gjorda i eder hade blivit gjorda i Tyrus och Sidon, så skulle de för länge sedan hava suttit i säck och aska och gjort bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 14, 'Men också skall det vid domen bliva drägligare för Tyrus och Sidon än för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 15, 'Och du. Kapernaum, skall väl du bliva upphöjt till himmelen? Nej, ned till dödsriket måste du fara. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 16, 'Den som hör eder, han hör mig, och den som förkastar eder, han förkastar mig; men den som förkastar mig, han förkastar honom som har sänt mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 17, 'Och de sjuttiotvå kommo tillbaka, uppfyllda av glädje, och sade: »Herre, också de onda andarna äro oss underdåniga genom ditt namn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 18, 'Då sade han till dem: »Jag såg Satan falla ned från himmelen såsom en ljungeld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 19, 'Se, jag har givit eder makt att trampa på ormar och skorpioner och att förtrampa all ovännens härsmakt, och han skall icke kunna göra eder någon skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 20, 'Dock, glädjens icke över att änglarna äro eder underdåniga, utan glädjens över att edra namn äro skrivna i himmelen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 21, 'I samma stund uppfylldes han av fröjd genom den helige Ande och sade: »Jag prisar dig, Fader, du himmelens och jordens Herre, för att du väl har dolt detta för de visa och kloka, men uppenbarat det för de enfaldiga. Ja, Fader; så har ju varit ditt behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 22, 'Allt har av min Fader blivit för trott åt mig. Och ingen känner vem Sonen är utom Fadern, ej heller vem Fadern är, utom Sonen och den för vilken Sonen vill göra honom känd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 23, 'Sedan vände han sig till lärjungarna, när han var allena med dem och sade: »Saliga äro de ögon som se det I sen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 24, 'Ty jag säger eder: Många profeter och konungar ville se det som I sen men fingo dock icke se det, och höra det som I hören, men fingo dock icke höra det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 25, 'Men en lagklok stod upp och ville snärja honom och sade: »Mästare, vad skall jag göra för att få evigt liv till arvedel?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 26, 'Då sade han till honom: »Vad är skrivet i lagen? Huru läser du?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 27, 'Han svarade och sade: »\'Du skall älska Herren, din Gud, av allt ditt hjärta och av all din själ och av all din kraft och av allt ditt förstånd och din nästa såsom dig själv.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 28, 'Han sade till honom: »Rätt svarade du. Gör det, så får du leva,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 29, 'Då ville han rättfärdiga sig och sade till Jesus: »Vilken är då min nästa?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 30, 'Jesus svarade och sade: »En man begav sig från Jerusalem ned till Jeriko, men råkade ut för rövare, som togo ifrån honom hans kläder och därtill slogo honom; därefter gingo de sin väg och läto honom ligga där halvdöd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 31, 'Så hände sig att en präst färdades samma väg; och när han fick se honom, gick han förbi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 32, 'Likaledes ock en levit: när denne kom till det stället och fick se honom, gick han förbi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 33, 'Men en samarit, som färdades samma väg, kom också dit där han låg; och när denne fick se honom, ömkade han sig över honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 34, 'och gick fram till honom och göt olja och vin i hans sår och förband dem. Sedan lyfte han upp honom på sin åsna och förde honom till ett härbärge och skötte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 35, 'Morgonen därefter tog han fram två silverpenningar och gav dem åt värden och sade: \'Sköt honom och vad du mer kostar på honom skall jag betala dig, när jag kommer tillbaka.\' --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 36, 'Vilken av dessa tre synes dig nu hava visat sig vara den mannens nästa, som hade fallit i rövarhänder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 37, 'Han svarade: »Den som bevisade honom barmhärtighet.» Då sade Jesus till honom: »Gå du och gör sammalunda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 38, 'När de nu voro på vandring, gick han in i en by, och en kvinna, vid namn Marta, tog emot honom i sitt hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 39, 'Och hon hade en syster, som hette Maria; denna satte sig ned vid Herrens fötter och hörde på hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 40, 'Men Marta var upptagen av mångahanda bestyr för att tjäna honom. Och hon gick fram och sade: »Herre, frågar du icke efter att min syster har lämnat alla bestyr åt mig allena? Säg nu till henne att hon hjälper mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 41, 'Då svarade Herren och sade till henne: »Marta, Marta, du gör dig bekymmer och oro för mångahanda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 42, 'men allenast ett är nödvändigt. Maria har utvalt den goda delen, och den skall icke tagas ifrån henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 1, 'När han en gång uppehöll sig på ett ställe för att bedja och hade slutat sin bön, sade en av hans lärjungar till honom: »Herre, lär oss att bedja, såsom ock Johannes lärde sina lärjungar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 2, 'Då sade han till dem: »När I bedjen, skolen I säga så: \'Fader, helgat varde ditt namn; tillkomme ditt rike;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 3, 'vårt dagliga bröd giv oss var dag;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 4, 'och förlåt oss våra synder, ty också vi förlåta var och en som är oss något skyldig; och inled oss icke i frestelse.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 5, 'Ytterligare sade han till dem: »Om någon av eder har en vän och mitt i natten kommer till denne och säger till honom: \'Käre vän, låna mig tre bröd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 6, 'ty en av mina vänner har kommit resande till mig, och jag har intet att sätta fram åt honom\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 7, 'så svarar kanske den andre inifrån huset och säger: \'Gör mig icke omak; dörren är redan stängd, och både jag och mina barn hava gått till sängs; jag kan icke stå upp och göra dig något.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 8, 'Men jag säger eder: Om han än icke, av det skälet att han är hans vän, vill stå upp och giva honom något, så kommer han likväl, därför att den andre är så påträngande, att stå upp och giva honom så mycket han behöver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 9, 'Likaså säger jag till eder: Bedjen, och eder skall varda givet; söken, och I skolen finna; klappen, och för eder skall varda upplåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 10, 'Ty var och en som beder, han får; och den som söker, han finner; och för den som klappar skall varda upplåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 11, 'Finnes bland eder någon fader, som när hans son beder honom om en fisk, i stallet för en fisk räcker honom en orm,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 12, 'eller som räcker honom en skorpion, när han beder om ett ägg?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 13, 'Om nu I, som ären onda, förstån att giva edra barn goda gåvor, huru mycket mer skall icke då den himmelske Fadern giva helig ande åt dem som bedja honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 14, 'Och han drev ut en ond ande som var dövstum. Och när den onde anden hade blivit utdriven, talade den dövstumme; och folket förundrade sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 15, 'Men några av dem sade: »Det är med Beelsebul, de onda andarnas furste, som han driver ut de onda andarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 16, 'Och några andra ville sätta honom på prov och begärde av honom ett tecken från himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 17, 'Men han förstod deras tankar och sade till dem: »Vart rike som har kommit i strid med sig självt bliver förött, så att hus faller på hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 18, 'Om nu Satan har kommit i strid med sig själv, huru kan då hans rike hava bestånd? I sägen ju att det är med Beelsebul som jag driver ut de onda andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 19, 'Men om det är med Beelsebul som jag driver ut de onda andarna, med vem driva då edra egna anhängare ut dem? De skola alltså vara edra domare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 20, 'Om det åter är med Guds finger som jag driver ut de onda andarna, så har ju Guds rike kommit till eder. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 21, 'När en stark man, fullt väpnad, bevakar sin gård, då äro hans ägodelar fredade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 22, 'Men om någon som är starkare än han angriper honom och övervinner honom, så tager denne ifrån honom alla vapnen, som han förtröstade på, och skiftar ut bytet efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 23, 'Den som icke är med mig, han är emot mig, och den som icke församlar med mig, han förskingrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 24, 'När en oren ande har farit ut ur en människa, vandrar han omkring i ökentrakter och söker efter ro. Men då han icke finner någon, säger han: \'Jag vill vända tillbaka till mitt hus, som jag gick ut ifrån.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 25, 'Och när han kommer dit och finner det fejat och prytt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 26, 'då går han åstad och tager med sig sju andra andar, som äro värre än han själv, och de gå ditin och bo där; och så bliver för den människan det sista värre än det första.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 27, 'När han sade detta, hov en kvinna in folkhopen upp sin röst och ropade till honom: »Saligt är det moderssköte som har burit dig, och de bröst som du har diat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 28, 'Men han svarade: »Ja, saliga är de som höra Guds ord och gömma det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 29, 'Men när folket strömmade till tog han till orda och sade: »Detta släkte är ett ont släkte Det begär ett tecken, men intet annat tecken skall givas det än Jonas\' tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 30, 'Ty såsom Jonas blev ett tecken för nineviterna, så skall ock Människosonen vara ett tecken för detta släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 31, 'Drottningen av Söderlandet skall vid domen träda fram tillsammans med detta släktes män och bliva dem till dom. Ty hon kom från jordens ända för att höra Salomos visdom; och se, har är vad som är mer än Salomo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 32, 'Ninevitiska män skola vid domen träda fram tillsammans med detta släkte och bliva det till dom. Ty de gjorde bättring vid Jonas\' predikan; och se, här är vad som är mer än Jonas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 33, 'Ingen tänder ett ljus och sätter det på en undangömd plats eller under skäppan, utan man sätter det på ljusstaken, för att de som komma in skola se skenet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 34, 'Ditt öga är kroppens lykta. När ditt öga är friskt, då har ock hela din kropp ljus; men när det är fördärvat, då är ock din kropp höljd i mörker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 35, 'Se därför till, att ljuset som du har i dig icke är mörker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 36, 'Om så hela din kropp får ljus och icke har någon del höljd i mörker, då har den ljus i sin helhet, såsom när en lykta lyser dig med sitt klara sken.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 37, 'Under det att han så talade, inbjöd en farisé honom till måltid hos sig; och han gick ditin och tog plats vid bordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 38, 'Men när fariséen såg att han icke tvådde sig före måltiden, förundrade han sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 39, 'Då sade Herren till honom: »I fariséer, I gören nu det yttre av bägaren och fatet rent, medan edert inre är fullt av rofferi och ondska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 40, 'I dårar, har icke han som har gjort det yttre också gjort det inre?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 41, 'Given fastmer såsom allmosa vad inuti kärlet är; först då bliver allt hos eder rent.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 42, 'Men ve eder, I fariséer, som given tionde av mynta och ruta och alla slags kryddväxter, men icke akten på rätten och på kärleken till Gud! Det ena borden I göra, men icke underlåta det andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 43, 'Ve eder, I fariséer, som gärna viljen sitta främst i synagogorna och gärna viljen bliva hälsade på torgen!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 44, 'Ve eder, I som ären lika gravar som ingen kan märka, och över vilka människorna gå fram utan att veta det!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 45, 'Då tog en av de lagkloke till orda och sade till honom: »Mästare, när du så talar, skymfar du också oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 46, 'Han svarade: »Ja, ve ock eder, I lagkloke, som på människorna läggen bördor, svåra att bära, men själva icke viljen med ett enda finger röra vid de bördorna!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 47, 'Ve eder, I som byggen upp profeternas gravar, deras som edra fäder dräpte!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 48, 'Så bären I då vittnesbörd om edra fäders gärningar och gillen dem; ty om de dräpte profeterna, så byggen I upp deras gravar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 49, 'Därför har ock Guds vishet sagt: \'Jag skall sända till dem profeter och apostlar, och somliga av dem skola de dräpa, och andra skola de förfölja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 50, 'Och så skall av detta släkte utkrävas alla profeters blod, allt det som är utgjutet från världens begynnelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 51, 'ända ifrån Abels blod intill Sakarias\' blod, hans som förgjordes mellan altaret och templet.\' Ja, jag säger eder: Det skall utkrävas av detta släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 52, 'Ve eder, I lagkloke, som haven tagit bort nyckeln till kunskapen! Själva haven I icke kommit ditin och för dem som ville komma dit haven I lagt hinder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 53, 'När han inför allt folket sade detta till dem, blevo fariséerna och de lagkloke mycket förbittrade och gåvo sig i strid med honom om många stycken;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 54, 'de sökte nämligen efter tillfälle att kunna anklaga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 1, 'Då nu otaligt mycket folk var församlat omkring honom, så att de trampade på varandra, tog han till orda och sade, närmast till sina lärjungar: »Tagen eder till vara för fariséernas surdeg, det är för skrymteri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 2, 'Intet är förborgat, som icke skall bliva uppenbarat, och intet är fördolt, som icke skall bliva känt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 3, 'Därför skall allt vad I haven sagt i mörkret bliva hört i ljuset, och vad I haven viskat i någons öra i kammaren, det skall bliva utropat på taken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 4, 'Men jag säger eder, mina vänner: Frukten icke för dem som väl kunna dräpa kroppen, men sedan icke hava makt att göra något mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 5, 'Jag vill lära eder vem I skolen frukta: frukten honom som har makt att, sedan han har dräpt, också kasta i Gehenna. Ja, jag säger eder: Honom skolen I frukta. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 6, 'Säljas icke fem sparvar för två skärvar? Och icke en av dem är förgäten hos Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 7, 'Men på eder äro till och med huvudhåren allasammans räknade. Frukten icke; I ären mer värda än många sparvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 8, 'Och jag säger eder: Var och en som bekänner mig inför människorna, honom skall ock Människosonen kännas vid inför Guds änglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 9, 'Men den som förnekar mig inför människorna, han skall ock bliva förnekad inför Guds änglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 10, 'Och om någon säger något mot Människosonen, så skall det bliva honom förlåtet; men den som hädar den helige Ande, honom skall det icke bliva förlåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 11, 'Men när man drager eder fram inför synagogor och överheter och myndigheter, så gören eder icke bekymmer för huru eller varmed I skolen försvara eder, eller vad I skolen säga;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 12, 'ty den helige Ande skall i samma stund lära eder vad I skolen säga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 13, 'Och en man i folkhopen sade till honom: »Mästare, säg till min broder att han skiftar arvet med mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 14, 'Men han svarade honom: »Min vän, vem har satt mig till domare eller skiftesman över eder?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 15, 'Därefter sade han till dem: »Sen till, att I tagen eder till vara för allt slags girighet; ty en människas liv beror icke därpå att hon har överflöd på ägodelar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 16, 'Och han framställde för dem en liknelse; han sade: »Det var en rik man vilkens åkrar buro ymniga skördar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 17, 'Och han tänkte vid sig själv och sade: \'Vad skall jag göra? Jag har ju icke rum nog för att inbärga min skörd.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 18, 'Därefter sade han: \'Så vill jag göra: jag vill riva ned mina lador och bygga upp större, och i dem skall jag samla in all min gröda och allt mitt goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 19, 'Sedan vill jag säga till min själ: Kära själ, du har mycket gott förvarat för många år; giv dig nu ro, ät, drick och var glad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 20, 'Men Gud sade till honom: \'Du dåre, i denna natt skall din själ utkrävas av dig; vem skall då få vad du har samlat i förråd?\' --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 21, 'Så går det den som samlar skatter åt sig själv, men icke är rik inför Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 22, 'Och han sade till sina lärjungar: »Därför säger jag eder: Gören eder icke bekymmer för edert liv, vad I skolen äta, ej heller för eder kropp, vad I skolen kläda eder med.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 23, 'Livet är ju mer än maten, och kroppen mer än kläderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 24, 'Given akt på korparna: de så icke, ej heller skörda de, och de hava varken visthus eller lada; och likväl föder Gud dem. Huru mycket mer ären icke I än fåglarna!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 25, 'Vilken av eder kan med allt sitt bekymmer lägga en aln till sin livslängd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 26, 'Förmån I nu icke ens det som minst är, varför gören I eder då bekymmer för det övriga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 27, 'Given akt på liljorna, huru de varken spinna eller väva; och likväl säger jag eder att icke ens Salomo i all sin härlighet var så klädd som en av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 28, 'Kläder nu Gud så gräset på marken, vilket i dag står och i morgon kastas i ugnen, huru mycket mer skall han då icke kläda eder, I klentrogne!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 29, 'Söken därför icke heller I efter vad I skolen äta, eller vad I skolen dricka, och begären icke vad som är för högt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 30, 'Efter allt detta söka ju hedningarna i världen, och eder Fader vet att I behöven detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 31, 'Nej, söken efter hans rike, så skall också detta andra tillfalla eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 32, 'Frukta icke, du lilla hjord; ty det har behagat eder Fader att giva eder riket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 33, 'Säljen vad I ägen och given allmosor; skaffen eder penningpungar som icke nötas ut, en outtömlig skatt i himmelen, dit ingen tjuv når, och där man icke fördärvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 34, 'Ty där eder skatt är, där komma ock edra hjärtan att vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 35, 'Haven edra länder omgjordade och edra lampor brinnande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 36, 'Och varen I lika tjänare som vänta på att deras herre skall bryta upp från bröllopet, för att strax kunna öppna för honom, när han kommer och klappar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 37, 'Saliga äro de tjänare som deras herre finner vakande, när han kommer. Sannerligen säger jag eder: Han skall fästa upp sin klädnad och låta dem taga plats vid bordet och själv gå fram och betjäna dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 38, 'Och vare sig han kommer under den andra nattväkten eller under den tredje och finner dem så göra -- saliga äro de då.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 39, 'Men det förstån I väl, att om husbonden visste vilken stund tjuven skulle komma, så tillstadde han icke att någon bröt sig in i hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 40, 'Så varen ock I redo ty i en stund då I icke vänten det skall Människosonen komma.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 41, 'Då sade Petrus: »Herre, är det om oss som du talar i denna liknelse, eller är det om alla?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 42, 'Herren svarade: »Finnes någon trogen och förståndig förvaltare, som av sin herre kan sättas över hans husfolk, för att i rätt tid giva dem deras bestämda kost --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 43, 'salig är då den tjänaren, om hans herre, när han kommer, finner honom göra så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 44, 'Sannerligen säger jag eder: Han skall sätta honom över allt vad han äger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 45, 'Men om så är, att tjänaren säger i sitt hjärta: \'Min herre kommer icke så snart\', och han begynner att slå de andra tjänarna och tjänarinnorna och att äta och dricka så att han bliver drucken,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 46, 'då skall den tjänarens herre komma på en dag då han icke väntar det, och i en stund då han icke tänker sig det, och han skall låta hugga honom i stycken och låta honom få sin del med de otrogna. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 47, 'Och den tjänare som hade fått veta sin herres vilja, men icke redde till eller gjorde efter hans vilja, han skall bliva straffad med många slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 48, 'Men den som, utan att hava fått veta hans vilja, gjorde vad som val slag värt, han skall bliva straffad med allenast få slag. Var och en åt vilken mycket är givet, av honom skall mycket varda utkrävt och den som har blivit betrodd med mycket, av honom skall man fordra dess mera.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 49, 'Jag har kommit för att tända en eld på jorden; och huru gärna ville jag icke att den redan brunne!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 50, 'Men jag måste genomgå ett dop; och huru ängslas jag icke, till dess att det är fullbordat!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 51, 'Menen I att jag har kommit för att skaffa frid på jorden? Nej, säger jag eder, fastmer söndring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 52, 'Ty om fem finnas i samma hus, skola de härefter vara söndrade från varandra, så att tre stå mot två Och två mot tre:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 53, 'fadern mot sin son och sonen mot sin fader, modern mot sin dotter och dottern mot sin moder, svärmodern mot sin sonhustru och sonhustrun mot sin svärmoder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 54, 'Han hade också till folket: »När I sen ett moln stiga upp i väster, sägen I strax: \'Nu kommer regn\'; och det sker så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 55, 'Och när I sen sunnanvind blåsa, sägen I: \'Nu kommer stark hetta\'; och detta sker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 56, 'I skrymtare, jordens och himmelens utseende förstån I att tyda; huru kommer det då till, att I icke kunnen tyda denna tiden?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 57, 'Varför låten I icke edert eget inre döma om vad rätt är?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 58, 'När du går till en överhetsperson med din motpart, så gör dig under vägen all möda att bliva förlikt med denne, så att han icke drager dig fram inför domaren; då händer att domaren överlämnar dig åt rättstjänaren, och att rättstjänaren kastar dig i fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 59, 'Jag säger dig: Du skall icke slippa ut därifrån, förrän du har betalt ända till den yttersta skärven.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 1, 'Vid samma tid kommo några och berättade för honom om de galiléer vilkas blod Pilatus hade blandat med deras offer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 2, 'Då svarade han och sade till dem: »Menen I att dessa galiléer voro större syndare än alla andra galiléer, eftersom de fingo lida sådant?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 3, 'Nej, säger jag eder; men om I icke gören bättring, skolen I alla sammalunda förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 4, 'Eller de aderton som dödades, när tornet i Siloam föll på dem, menen I att de voro mer brottsliga än alla andra människor som bo i Jerusalem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 5, 'Nej, säger jag eder; men om I icke gören bättring, skolen I alla sammalunda förgås.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 6, 'Och han framställde denna liknelse: »En man hade ett fikonträd planterat i sin vingård; och han kom och sökte frukt därpå, men fann ingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 7, 'Då sade han till vingårdsmannen: \'Se, nu i tre år har jag kommit och sökt frukt på detta fikonträd, utan att finna någon. Hugg bort det. Varför skall det därjämte få utsuga jorden?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 8, 'Men vingårdsmannen svarade och sade till honom: \'Herre, låt det stå kvar också detta år, för att jag under tiden må gräva omkring det och göda det;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 9, 'kanhända skall det så till nästa å bära frukt. Varom icke, så må du då hugga bort det.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 10, 'När han en gång på sabbaten undervisade i en synagoga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 11, 'var där en kvinna som i aderton år hade varit besatt av en sjukdomsande, och hon var så hopkrumpen, att hon alls icke kunde räta upp sin kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 12, 'Då nu Jesus fick se henne, kallade han henne till sig och sade till henne »Kvinna, du är fri ifrån din sjuk dom»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 13, 'och han lade därvid händerna på henne. Och strax rätade hon upp sig och prisade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 14, 'Men det förtröt synagogföreståndaren att Jesus på sabbaten botade sjuka; och han tog till orda och sade till folket: »Sex dagar finnas, på vilka man bör arbeta. På dem mån I alltså komma och låta bota eder, men icke på sabbatsdagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 15, 'Då svarade Herren honom och sade: »I skrymtare, löser icke var och en av eder på sabbaten sin oxe eller åsna från krubban och leder den bort för att vattna den?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 16, 'Och denna kvinna, en Abrahams dotter, som Satan har hållit bunden nu i aderton år, skulle då icke hon på sabbatsdagen få lösas från sin boja?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 17, 'När han sade detta, blygdes alla hans motståndare; och allt folket gladde sig över alla de härliga gärningar som gjordes av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 18, 'Så sade han då: »Vad är Guds rike likt, ja, vad skall jag likna det vid?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 19, 'Det är likt ett senapskorn som en man tager och lägger ned i sin trädgård, och det växer och bliver ett träd, och himmelens fåglar bygga sina nästen på dess grenar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 20, 'Ytterligare sade han: »Vad skall jag likna Guds rike vid?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 21, 'Det är likt en surdeg som en kvinna tager och blandar in i tre skäppor mjöl, till dess alltsammans bliver syrat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 22, 'Och han vandrade från stad till stad och från by till by och undervisade folket, under det att han fortsatte sin färd till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 23, 'Och någon frågade honom: »Herre, är det allenast få som bliva frälsta?» Då svarade han dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 24, '»Kämpen för att komma in genom den trånga dörren; ty många, säger jag eder, skola försöka att komma in och skola dock icke förmå det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 25, 'Om husbonden har stått upp och tillslutit dörren, och I sedan kommen och ställen eder därutanför och klappen på dörren och sägen: \'Herre, låt upp för oss\', så skall han svara och säga till eder: \'Jag vet icke varifrån I ären.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 26, 'Och I skolen då säga: \'Vi hava ju ätit och druckit med dig, och du har undervisat på våra gator.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 27, 'Men han skall svara: \'Jag säger eder: Jag vet icke varifrån I ären; gån bort ifrån mig, alla I ogärningsmän.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 28, 'Där skall då bliva gråt och tandagnisslan, när I fån se Abraham, Isak och Jakob och alla profeterna vara i Guds rike, men finnen eder själva utkastade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 29, 'Ja, människor skola komma från öster och väster, från norr och söder och bliva bordsgäster i Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 30, 'Och se, då skola somliga som äro de sista bliva de första, och somliga som äro de första bliva de sista.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 31, 'I samma stund kommo några fariséer fram och sade till honom: »Begiv dig åstad bort härifrån; ty Herodes vill dräpa dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 32, 'Då svarade han dem: »Gån och sägen den räven, att jag i dag och i morgon driver ut onda andar och botar sjuka, och att jag först på tredje dagen är färdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 33, 'Men jag måste vandra i dag och i morgon och i övermorgon, ty det är icke i sin ordning att en profet förgöres annorstädes än i Jerusalem. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 34, 'Jerusalem, Jerusalem, du som dräper profeterna och stenar dem som äro sända till dig! Huru ofta har jag icke velat församla dina barn, likasom hönan församlar sina kycklingar under sina vingar! Men haven icke velat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 35, 'Se, edert hus skall komma att stå övergivet. Men jag säger eder: I skolen icke se mig, förrän den tid kommen, då I sägen: \'Välsignad vare han som kommer, i Herrens namn.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 1, 'När han på en sabbat hade kommit in till en av de förnämligaste fariséerna för att intaga en måltid, hände sig, medan man där vaktade på honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 2, 'att en vattusiktig man kom dit och stod framför honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 3, 'Då tog Jesus till orda och sade till de lagkloke och fariséerna: »Är det lovligt att bota sjuka på sabbaten, eller är det icke lovligt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 4, 'Men de tego. Då tog han mannen vid handen och gjorde honom frisk och lät honom gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 5, 'Sedan sade han till dem: »Om någon av eder har en åsna eller en oxe som faller i en brunn, går han icke då strax och drager upp den, jämväl på sabbatsdagen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 6, 'Och de förmådde icke svara något härpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 7, 'Då han nu märkte huru gästerna utvalde åt sig de främsta platserna, framställde han för dem en liknelse; han sade till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 8, '»När du av någon har blivit bjuden till bröllop, så tag icke den främsta platsen vid bordet. Ty kanhända finnes bland gästerna någon som är mer ansedd än du,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 9, 'och då kommer till äventyrs den som har bjudit både dig och honom och säger till dig: \'Giv plats åt denne\'; och så måste du med skam intaga den nedersta platsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 10, 'Nej, när du har blivit bjuden, så gå och tag den nedersta platsen vid bordet. Ty det kan då hända att den som har bjudit dig säger till dig, när han kommer: \'Min vän, stig högre upp.\' Då vederfares dig heder inför alla de andra bordsgästerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 11, 'Ty var och en som upphöjer sig, han skall bliva förödmjukad, och den som ödmjukar sig, han skall bliva upphöjd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 12, 'Han sade ock till den som hade bjudit honom: »När du gör ett gästabud, på middagen eller på aftonen, så inbjud icke dina vänner eller dina bröder eller dina fränder, ej heller rika grannar, så att de bjuda dig igen och du därigenom får vedergällning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 13, 'Nej, när du gör gästabud, så bjud fattiga, krymplingar, halta, blinda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 14, 'Salig är du då; ty eftersom de icke förmå vedergälla dig, skall du få din vedergällning vid de rättfärdigas uppståndelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 15, 'Då nu en av de andra vid bordet hörde detta, sade denne till honom: »Salig är den som får bliva bordsgäst i Guds rike!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 16, 'Då sade han till honom: »En man tillredde ett stort gästabud och bjöd många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 17, 'Och när gästabudet skulle hållas, sände han ut sin tjänare och lät säga till dem som voro bjudna: \'Kommen, ty nu är allt redo.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 18, 'Men de begynte alla strax ursäkta sig. Den förste sade till honom: \'Jag har köpt ett jordagods, och jag måste gå ut och bese det. Jag beder dig, tag emot min ursäkt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 19, 'En annan sade: \'Jag har köpt fem par oxar, och jag skall nu gå åstad och försöka dem. Jag beder dig, tag emot min ursäkt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 20, 'Åter en annan sade: \'Jag har tagit mig hustru, och därför kan jag icke komma.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 21, 'Och tjänaren kom igen och omtalade detta för sin herre. Då blev husbonden vred och sade till sin tjänare: \'Gå strax ut på gator och gränder i staden, och för hitin fattiga och krymplingar och blinda och halta.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 22, 'Sedan sade tjänaren: \'Herre, vad du befallde har blivit gjort, men har är ännu rum.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 23, 'Då sade herren till tjänaren: \'Gå ut på vägar och stigar, och nödga människorna att komma hitin, så att mitt hus bliver fullt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 24, 'Ty jag säger eder att ingen av de män som voro bjudna skall smaka sin måltid.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 25, 'Och mycket folk gick med honom; och han vände sig om och sade till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 26, '»Om någon kommer till mig, och han därvid ej hatar sin fader och sin moder, och sin hustru och sina barn, och sina bröder och systrar, därtill ock sitt eget liv, så kan han icke vara min lärjunge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 27, 'Den som icke bär sitt kors och efterföljer mig, han kan icke vara min lärjunge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 28, 'Ty om någon bland eder vill bygga ett torn, sätter han sig icke då först ned och beräknar kostnaden och mer till, om han äger vad som behöves för att bygga det färdigt?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 29, 'Eljest, om han lade grunden, men icke förmådde fullborda verket skulle ju alla som finge se det begynna att begabba honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 30, 'och säga: \'Den mannen begynte bygga, men förmådde icke fullborda sitt verk.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 31, 'Eller om en konung vill draga ut i krig för att drabba samman med en annan konung, sätter han sig icke då först ned och tänker efter, om han förmår att med tio tusen möta den som kommer emot honom med tjugu tusen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 32, 'Om så icke är, måste han ju, medan den andre ännu är långt borta, skicka sändebud och underhandla om fred.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 33, 'Likaså kan ingen av eder vara min lärjunge, om han icke försakar allt vad han äger. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 34, 'Så är väl saltet en god sak, men om till och med saltet mister sin sälta, varmed skall man då återställa dess kraft?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 35, 'Varken för jorden eller för gödselhögen är det tjänligt; man kastar ut det. Den som har öron till att höra, han höre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 1, 'Och till honom kom allt vad publikaner och syndare hette för att höra honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 2, 'Men fariséerna och de skriftlärde knorrade och sade: »Denne tager emot syndare och äter med dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 3, 'Då framställde han för dem denna liknelse; han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 4, '»Om ibland eder finnes en man som har hundra får, och han förlorar ett av dem, lämnar han icke då de nittionio i öknen och går och söker efter det förlorade, till dess han finner det?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 5, 'Och när han har funnit det, lägger han det på sina axlar med glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 6, 'Och när han kommer hem, kallar han tillhopa sina vänner och grannar och säger till dem: \'Glädjens med mig, ty jag har funnit mitt får, som var förlorat.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 7, 'Jag säger eder att likaså bliver mer glädje i himmelen över en enda syndare som gör bättring, än över nittionio rättfärdiga som ingen bättring behöva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 8, 'Eller om en kvinna har tio silverpenningar, och hon tappar bort en av dem, tänder hon icke då upp ljus och sopar huset och söker noga, till dess hon finner den?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 9, 'Och när hon har funnit den, kallar hon tillhopa sina väninnor och grannkvinnor och säger: \'Glädjens med mig, ty jag har funnit den penning som jag hade tappat bort.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 10, 'Likaså, säger jag eder, bliver glädje hos Guds änglar över en enda syndare som gör bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 11, 'Ytterligare sade han: »En man hade två söner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 12, 'Och den yngre av dem sade till fadern: \'Fader, giv mig den del av förmögenheten, som faller på min lott.\' Då skiftade han sina ägodelar mellan dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 13, 'Och icke lång tid därefter lade den yngre sonen allt sitt tillhopa och for långt bort till ett främmande land. Där levde han i utsvävningar och förfor så sin förmögenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 14, 'Men sedan han hade slösat bort allt, kom en svär hungersnöd över det landet, och han begynte lida nöd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 15, 'Då gick han bort och gav sig under en man där i landet, och denne sände honom ut på sina marker för att vakta svin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 16, 'Och han åstundade att få fylla sin buk med de fröskidor som svinen åto; men ingen gav honom något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 17, 'Då kom han till besinning och sade: \'Huru många legodrängar hos min fader hava icke bröd i överflöd, medan jag har förgås av hunger!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 18, 'Jag vill stå upp och gå till min fader och säga till honom: Fader, jag har syndat mot himmelen och inför dig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 19, 'jag är icke mer värd att kallas din son. Låt mig bliva såsom en av dina legodrängar.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 20, 'Så stod han upp och gick till sin fader. Och medan han ännu var långt borta, fick hans fader se honom och ömkade sig över honom och skyndade emot honom och föll honom om halsen och kysste honom innerligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 21, 'Men sonen sade till honom: \'Fader, jag har syndat mot himmelen och inför dig; jag är icke mer värd att kallas din son.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 22, 'Då sade fadern till sina tjänare \'Skynden eder att taga fram den yppersta klädnaden och kläden honom i den, och sätten en ring på hans hand och skor på hans fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 23, 'Och hämten den gödda kalven och slakten den, så vilja vi äta och gör oss glada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 24, 'Ty denne min son var död, men har fått liv igen; han var förlorad men är återfunnen.\' Och de begynte göra sig glada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 25, 'Men hans äldre son var ute på marken. När denne nu vände tillbaka och hade kommit nära huset fick han höra spel och dans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 26, 'Då kallade han till sig en av tjänarna och frågade vad detta kunde betyda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 27, 'Denne svarade honom: \'Din broder har kommit hem; och då nu din fader har fått honom välbehållen tillbaka, har han låtit slakta den gödda kalven.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 28, 'Då blev han vred och ville icke gå in. Hans fader gick då ut och talade vanligt med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 29, 'Men han svarade och sade till sin fader: \'Se, i så många år har jag nu tjänat dig, och aldrig har jag överträtt något ditt bud; och lik väl har du åt mig aldrig givit ens en killing, för att jag skulle kunna göra mig glad med mina vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 30, 'Men när denne din son, som har förtärt dina ägodelar tillsammans med skökor, nu har kommit tillbaka, så har du för honom låtit slakta den gödda kalven.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 31, 'Då sade han till honom: \'Min son, du är alltid hos mig, och all mitt är ditt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 32, 'Men nu måste vi fröjda oss och vara glada; ty denne din broder var död, men har fått liv igen, han var förlorad, men är återfunnen.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 1, 'Han sade också till sina lärjungar: »En rik man hade en förvaltare som hos honom blev angiven för förskingring av hans ägodelar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 2, 'Då kallade han honom till sig och sade till honom: \'Vad är det jag hör om dig? Gör räkenskap för din förvaltning; ty du kan icke längre få vara förvaltare.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 3, 'Men förvaltaren sade vid sig själv: \'Vad skall jag göra, då min herre nu tager ifrån mig förvaltningen? Gräva orkar jag icke; att tigga blyges jag för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 4, 'Dock, nu vet jag vad jag skall göra, för att man må upptaga mig i sina hus, när jag bliver avsatt ifrån förvaltningen.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 5, 'Och han kallade till sig sin herres gäldenärer, var och en särskilt. Och han frågade den förste: \'Huru mycket är du skyldig min herre?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 6, 'Han svarade: \'Hundra fat[1] olja.\' Då sade han till honom: \'Tag här ditt skuldebrev, och sätt dig nu strax ned och skriv femtio.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 7, 'Sedan frågade han en annan: \'och du, huru mycket är du skyldig?\' Denne svarade: \'hundra tunnor[2] vete.\' Då sade han till honom: \'Tag här ditt skuldebrev och skriv åttio.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 8, 'Och husbonden prisade den orättrådige förvaltaren för det att han hade handlat klokt. Ty denna tidsålders barn skicka sig klokare mot sitt släkte än ljusets barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 9, 'Och jag säger eder: Skaffen eder vänner medelst den orättrådige Mamons goda, för att de, när detta har tagit slut, må taga emot eder i de eviga hyddorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 10, 'Den som är trogen i det minsta, han är ock trogen i vad mer är, och den som är orättrådig i det minsta, han är ock orättrådig i vad mer är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 11, 'Haven I nu icke varit trogna, när det gällde den orättrådige Mamons goda, vem vill då betro eder det sannskyldiga goda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 12, 'Och haven I icke varit trogna, när det gällde vad som tillhörde en annan, vem vill då giva eder det som hör eder till?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 13, 'Ingen som tjänar kan tjäna två herrar; ty antingen kommer han då att hata den ene och älska den andre, eller kommer han att hålla sig till den förre och förakta den senare. I kunnen icke tjäna både Gud och Mamon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 14, 'Allt detta hörde nu fariséerna, som voro penningkära, och de drevo då gäck med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 15, 'Men han sade till dem: »I hören till dem som göra sig rättfärdiga inför människorna. Men Gud känner edra hjärtan; ty det som bland människor är högt är en styggelse inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 16, 'Lagen och profeterna hava haft sin tid intill Johannes. Sedan dess förkunnas evangelium om Guds rike, och var man vill storma ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 17, 'Men snarare kunna himmel och jord förgås, än en enda prick av lagen kan falla bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 18, 'Var och en som skiljer sig från sin hustru och tager sig en annan hustru, han begår äktenskapsbrott. Och den som tager till hustru en kvinna som är skild från sin man, han begår äktenskapsbrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 19, 'Det var en rik man som klädde sig i purpur och fint linne och levde var dag i glädje och prakt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 20, 'Men en fattig man, vid namn Lasarus, låg vid hans port, full av sår,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 21, 'och åstundade att få stilla sin hunger med vad som kunde falla ifrån den rike mannens bord. Ja, det gick så långt att hundarna kommo och slickade hans sår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 22, 'Så hände sig att den fattige dog och blev förd av änglarna till Abrahams sköte. Också den rike dog och blev begraven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 23, 'När han nu låg i dödsriket och plågades, lyfte han upp sina ögon och fick se Abraham långt borta och Lasarus i hans sköte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 24, 'Då ropade han och sade: \'Fader Abraham, förbarma dig över mig, och sänd Lasarus att doppa det yttersta av sitt finger i vatten och svalka min tunga, ty jag pinas svårt i dessa lågor.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 25, 'Men Abraham svarade: \'Min son kom ihåg att du, medan du levde, fick ut ditt goda och Lasarus däremot vad ont var; nu åter får han här hugnad, under det att du pinas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 26, 'Och till allt detta kommer, att ett stort svalg är satt mellan oss och eder, för att de som vilja begiva sig över härifrån till eder icke skola kunna det, och för att ej heller någon därifrån skall kunna komma över till oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 27, 'Då sade han: \'Så beder jag dig då, fader, att du sänder honom till min faders hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 28, 'där jag har fem bröder, och låter honom varna dem, så att icke också de komma till detta pinorum.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 29, 'Men Abraham sade: \'De hava Moses och profeterna; dem må de lyssna till.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 30, 'Han svarade: \'Nej, fader Abraham; men om någon kommer till dem från de döda, så skola de göra bättring.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 31, 'Då sade han till honom: \'Lyssna de icke till Moses och profeterna, så skola de icke heller låta övertyga sig, om någon uppstår från de döda.\'» [1] Se Fat i Ordförkl. [2] Se Tunna i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 1, 'Och han sade till sina lärjungar: »Det är icke annat möjligt än att förförelser måste komma, men ve den genom vilken de komma!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 2, 'För honom vore det bättre att en kvarnsten hängdes om hans hals och han kastades i havet, än att han skulle förföra en av dessa små.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 3, 'Tagen eder till vara! Om din broder försyndat sig, så tillrättavisa honom; och om han då ångrar sig, så förlåt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 4, 'Ja, om han sju gånger om dagen försyndar sig mot dig och sju gånger kommer tillbaka till dig och säger: \'Jag ångrar mig\' så skall du förlåta honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 5, 'Och apostlarna sade till Herren: »Föröka vår tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 6, 'Då sade Herren: »Om I haden tro, vore den ock blott såsom ett senapskorn, så skullen I kunna säga till detta mullbärsfikonträd: \'Ryck dig upp med rötterna, och plantera dig i havet\', och det skulle lyda eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 7, 'Om någon bland eder har en tjänare som kör plogen eller vaktar boskap, icke säger han väl till tjänaren, när denne kommer hem från marken: \'Gå du nu strax till bords\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 8, 'Säger han icke fastmer till honom: \'Red till min måltid, och fäst så upp din klädnad och betjäna mig, medan jag äter och dricker; sedan må du själv äta och dricka\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 9, 'Icke tackar han väl tjänaren för att denne gjorde det som blev honom befallt?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 10, 'Sammalunda, när I haven gjort allt som har blivit eder befallt, då skolen I säga: \'Vi äro blott ringa tjänare: vi hava endast gjort vad vi voro pliktiga att göra.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 11, 'Då han nu var stadd på sin färd till Jerusalem, tog han vägen mellan Samarien och Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 12, 'Och när han kom in i en by, möttes han av tio spetälska män. Dessa stannade på avstånd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 13, 'och ropade och sade: »Jesus, Mästare, förbarma dig över oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 14, 'När han fick se dem, sade han till dem: »Gån och visen eder för prästerna.» Och medan de voro på väg dit, blevo de rena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 15, 'Och en av dem vände tillbaka, när han såg att han hade blivit botad, och prisade Gud med hög röst');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 16, 'och föll ned på mitt ansikte för Jesu fötter och tackade honom. Och denne var en samarit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 17, 'Då svarade Jesus och sade: »Blevo icke alla tio gjorda rena? Var äro de nio?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 18, 'Fanns då ibland dem ingen som vände tillbaka för att prisa Gud, utom denne främling?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 19, 'Och han sade till honom: »Stå upp och gå dina färde. Din tro har frälst dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 20, 'Och då han blev tillfrågad av fariséerna när Guds rike skulle komma, svarade han dem och sade: »Guds rike kommer icke på sådant sätt att det kan förnimmas med ögonen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 21, 'ej heller skall man kunna säga: \'Se här är det\', eller: \'Där är det.\' Ty se, Guds rike är invärtes i eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 22, 'Och han sade till lärjungarna: »Den tid skall komma, då I gärna skullen vilja se en av Människosonens dagar, men I skolen icke få det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 23, 'Väl skall man då säga till eder: \'Se där är han\', eller: \'Se här är han\'; men gån icke dit, och löpen icke därefter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 24, 'Ty såsom ljungelden, när den ljungar fram, lyser från himmelens ena ända till den andra, så skall det vara med Människosonen på hand dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 25, 'Men först måste han lida mycket och bliva förkastad av detta släkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 26, 'Och såsom det skedde på Noas tid, så skall det ock ske i Människosonens dagar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 27, 'människorna åto och drucko, män togo sig hustrur, och hustrur gåvos åt män, ända till den dag då Noa gick in i arken; då kom floden och förgjorde dem allasammans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 28, 'Likaledes, såsom det skedde på Lots tid: människorna åto och drucko, köpte och sålde, planterade och byggde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 29, 'men på den dag då Lot gick ut från Sodom regnade eld och svavel ned från himmelen och förgjorde dem allasammans,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 30, 'alldeles på samma sätt skall det ske den dag då Människosonen uppenbaras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 31, 'Den som den dagen är på taket och har sitt bohag inne i huset, han må icke stiga ned för att hämta det; ej heller må den som är ute på marken vända tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 32, 'Kommen ihåg Lots hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 33, 'Den som står efter att vinna sitt liv, han skall mista det; men den som mister det, han skall rädda det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 34, 'Jag säger eder: Den natten skola två ligga i samma säng; den ene skall bliva upptagen, den andre skall lämnas kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 35, 'Två kvinnor skola mala tillhopa; den ena skall bliva upptagen, den andra skall lämnas kvar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 36, 'Då frågade de honom: »Var då, Herre?» Han svarade dem: »Där den döda kroppen är, dit skola ock rovfåglarna församla sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 37, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 1, 'Och han framställde för dem en liknelse, för att lära dem att de alltid borde bedja, utan att förtröttas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 2, 'Han sade: »I en stad fanns en domare som icke fruktade Gud och ej heller hade försyn för någon människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 3, 'I samma stad fanns ock en änka som åter och åter kom till honom och sade: \'Skaffa mig rätt av min motpart.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 4, 'Till en tid ville han icke. Men omsider sade han vid sig själv: \'Det må nu vara, att jag icke fruktar Gud och ej heller har försyn för någon människa;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 5, 'likväl, eftersom denna änka är mig så besvärlig, vill jag ändå skaffa henne rätt, för att hon icke med sina ideliga besök skall alldeles pina ut mig.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 6, 'Och Herren tillade: »Hören vad den orättfärdige domaren här säger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 7, 'Skulle då Gud icke skaffa rätt åt sina utvalda, som ropa till honom dag och natt, och skulle han icke hava tålamod med dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 8, 'Jag säger eder: Han skall snart skaffa dem rätt. Men skall väl Människosonen, när han kommer, finna tro här på jorden?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 9, 'Ytterligare framställde han denna liknelse för somliga som förtröstade på sig själva och menade sig vara rättfärdiga, under det att de föraktade andra:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 10, '»Två män gingo upp i helgedomen för att bedja; den ene var en farisé och den andre en publikan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 11, 'Fariséen trädde fram och bad så för sig själv: \'Jag tackar dig, Gud, för att jag icke är såsom andra människor, rövare, orättrådiga, äktenskapsbrytare, ej heller såsom denne publikan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 12, 'Jag fastar två gånger i veckan; jag giver tionde av allt vad jag förvärvar.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 13, 'Men publikanen stod långt borta och ville icke ens lyfta sina ögon upp mot himmelen, utan slog sig för sitt bröst och sade: \'Gud, misskunda dig över mig syndare.\' --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 14, 'Jag säger eder: Denne gick hem igen rättfärdig mer an den andre. Ty var och en som upphöjer sig, han skall bliva förödmjukad, men den som ödmjukar sig, han skall bliva upphöjd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 15, 'Man bar fram till honom också späda barn, för att han skulle röra vid dem; men när hans lärjungar sågo detta, visade de bort dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 16, 'Då kallade Jesus barnen till sig, i det han sade: »Låten barnen komma till mig, och förmenen dem det icke; ty Guds rike hör sådana till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 17, 'Sannerligen säger jag eder: Den som icke tager emot Guds rike såsom ett barn, han kommer aldrig ditin.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 18, 'Och en överhetsperson frågade honom och sade: »Gode Mästare, vad skall jag göra för att få evigt liv till arvedel?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 19, 'Jesus sade till honom: »Varför kallar du mig god? Ingen är god utom Gud allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 20, 'Buden känner du: \'Du skall icke begå äktenskapsbrott\', \'Du skall icke dräpa\', \'Du skall icke stjäla\', \'Du skall icke bära falskt vittnesbörd\', \'Hedra din fader och din moder.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 21, 'Då svarade han: »Allt detta har jag hållit från min ungdom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 22, 'När Jesus hörde detta, sade han till honom: »Ett återstår dig ännu: sälj allt vad du äger och dela ut åt de fattiga; då skall du få en skatt i himmelen. Och kom sedan och följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 23, 'Men när han hörde detta, blev han djupt bedrövad, ty han var mycket rik.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 24, 'Då nu Jesus såg huru det var med honom, sade han: »Huru svårt är det icke för dem som hava penningar att komma in i Guds rike!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 25, 'Ja, det är lättare för en kamel att komma in genom ett nålsöga, än för den som är rik att komma in i Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 26, 'Då sade de som hörde detta: »Vem kan då bliva frälst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 27, 'Men han svarade: »Vad som är omöjligt för människor, det är möjligt för Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 28, 'Då sade Petrus: »Se, vi hava övergivit allt som var vårt och hava följt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 29, 'Han svarade dem: »Sannerligen säger jag eder: Ingen som för Guds rikes skull har övergivit hus, eller hustru, eller bröder, eller föräldrar eller barn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 30, 'ingen sådan finnes, som icke skall mångfaldigt igen redan här i tiden, och i den tillkommande tidsåldern evigt liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 31, 'Och han tog till sig de tolv och sade till dem: »Se, vi gå nu upp till Jerusalem, och allt skall fullbordas, som genom profeterna är skrivet om Människosonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 32, 'Ty han skall bliva överlämnad åt hedningarna och bliva begabbad och skymfad och bespottad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 33, 'och de skola gissla honom och döda honom; men på tredje dagen skall han uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 34, 'Och de förstodo intet härav; ja, detta som han talade var dem så fördolt, att de icke fattade vad som sades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 35, 'Då han nu nalkades Jeriko, hände sig att en blind man satt vid vägen och tiggde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 36, 'När denne hörde en hop människor gå där fram, frågade han vad det var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 37, 'Och man omtalade för honom att det var Jesus från Nasaret som kom på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 38, 'Då ropade han och sade: »Jesus, Davids son, förbarma dig över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 39, 'Och de som gingo framför tillsade honom strängeligen att han skulle tiga; men han ropade ännu mycket mer: »Davids son, förbarma dig över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 40, 'Då stannade Jesus och bjöd att mannen skulle ledas fram till honom. Och när han hade kommit fram, frågade han honom:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 41, '»Vad vill du att jag skall göra dig?» Han svarade: »Herre, låt mig få min syn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 42, 'Jesus sade till honom: »Hav din syn; din tro har hjälpt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 43, 'Och strax fick han sin syn och följde honom och prisade Gud. Och allt folket som såg detta lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 1, 'Och han kom in i Jeriko och gick fram genom staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 2, 'Där fanns en man, vid namn Sackeus, som var förman för publikanerna och en rik man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 3, 'Denne ville gärna veta vem som var Jesus och ville se honom, men han kunde det icke för folkets skull, ty han var liten till växten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 4, 'Då skyndade han i förväg och steg upp i ett mullbärsfikonträd för att få se honom, ty han skulle komma den vägen fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 5, 'När Jesus nu kom till det stället, såg han upp och sade till honom: »Sackeus, skynda dig ned, ty i dag måste jag gästa i ditt hus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 6, 'Och han skyndade sig ned och tog emot honom med glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 7, 'Men alla som sågo det knorrade och sade: »Han har gått in för att gästa hos en syndare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 8, 'Men Sackeus trädde fram och sade till Herren: »Herre, hälften av mina ägodelar giver jag nu åt de fattiga; och om jag har utkrävt för mycket av någon, så giver jag fyradubbelt igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 9, 'Och Jesus sade om honom: »I dag har frälsning vederfarits detta hus, eftersom också han är en Abrahams son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 10, 'Ty Människosonen har kommit för att uppsöka och frälsa det som var förlorat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 11, 'Medan de hörde härpå, framställde han ytterligare en liknelse, eftersom han var nära Jerusalem och de nu menade att Guds rike strax skulle uppenbaras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 12, 'Han sade alltså: »En man av förnämlig släkt tänkte fara bort till ett avlägset land för att utverka åt sig konungslig värdighet; sedan skulle han komma tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 13, 'Och han kallade till sig tio sin tjänare och gav dem tio pund och sade till dem: \'Förvalten dessa, till dess jag kommer tillbaka.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 14, 'Men hans landsmän hatade honom och sände, efter hans avfärd, åstad en beskickning och läto säga: \'Vi vilja icke att denne skall bliva konung över oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 15, 'När han sedan kom tillbaka, efter att hava utverkat åt sig den konungsliga värdigheten, lät han kalla till sig de tjänare åt vilka han hade givit penningarna, ty han ville veta vad var och en genom sin förvaltning hade förvärvat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 16, 'Då kom den förste fram och sade: \'Herre, ditt pund har givit i vinst tio pund.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 17, 'Han svarade honom: \'Rätt så, du gode tjänare! Eftersom du har varit trogen i en mycket ringa sak, skall du få makt och myndighet över tio städer.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 18, 'Därefter kom den andre i ordningen och sade: \'Herre, ditt pund har avkastat fem pund.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 19, 'Då sade han jämväl till denne: \'Så vare ock du satt över fem städer.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 20, 'Och den siste kom fram och sade: \'Herre, se här är ditt pund; jag har haft det förvarat i en duk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 21, 'Ty jag fruktade för dig, eftersom du är en sträng man; du vill taga upp vad du icke har lagt ned, och skörda vad du icke har sått.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 22, 'Han sade till honom: \'Efter dina egna ord vill jag döma dig, du onde tjänare. Du visste alltså att jag är en sträng man, som vill taga upp vad jag icke har lagt ned, och skörda vad jag icke har sått?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 23, 'Varför satte du då icke in mina penningar i en bank? Då hade jag, när jag kom hem, fått uppbära dem med ränta.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 24, 'Och han sade till dem som stodo vid hans sida: \'Tagen ifrån honom hans pund, och given det åt den som har de tio punden.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 25, 'De sade till honom: \'Herre, han har ju redan tio pund.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 26, 'Han svarade: \'Jag säger eder: Var och en som har, åt honom skall varda givet; men den som icke har, från honom skall tagas också det han har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 27, 'Men dessa mina ovänner, som icke ville hava mig till konung över sig, fören dem hit huggen ned dem här inför mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 28, 'Sedan Jesus hade sagt detta, gick han framför de andra upp mot Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 29, 'När han då nalkades Betfage och Betania, vid det berg som kallas Oljeberget, sände han åstad två av lärjungarna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 30, 'och sade: »Gån in i byn som ligger här mitt framför. Och när I kommen ditin, skolen I finna en åsnefåle stå där bunden, som ingen människa någonsin har suttit på, lösen den och fören den hit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 31, 'Och om någon frågar eder varför I lösen den skolen I svara så: \'Herren behöver den.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 32, 'Och de som hade blivit utsända gingo åstad och funno det så som han hade sagt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 33, 'Och när de löste fålen, frågade ägaren dem: »Varför lösen I fålen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 34, 'De svarade: »Herren behöver den.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 35, 'Och de förde fålen till Jesus och lade sina mantlar på den och läto Jesus sätta sig därovanpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 36, 'Och där han färdades fram bredde de ut sina mantlar under honom på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 37, 'Och då han var nära foten av Oljeberget, begynte hela lärjungaskaran i sin glädje att med hög röst lova Gud för alla de kraftgärningar som de hade sett;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 38, 'och de sade: »Välsignad vare han som kommer, konungen, i Herrens namn. Frid vare i himmelen och ära i höjden!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 39, 'Och några fariséer som voro med i folkhopen sade till honom: »Mästare, förbjud dina lärjungar att ropa så.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 40, 'Men han svarade och sade: »Jag säger eder: Om dessa tiga, skola stenarna ropa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 41, 'Då han nu kom närmare och fick se staden, begynte han gråta över den');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 42, 'och sade: »O att du i dag hade insett, också du, vad din frid tillhör! Men nu är det fördolt för dina ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 43, 'Ty den tid skall komma över dig, då dina fiender skola omgiva dig med belägringsvall och innesluta dig och tränga dig på alla sidor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 44, 'Och de skola slå ned dig till jorden, tillika med dina barn, som äro i dig, och skola icke lämna kvar i dig sten på sten, därför att du icke aktade på den tid då du var sökt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 45, 'Och han gick in i helgedomen och begynte driva ut dem som sålde därinne;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 46, 'och han sade till dem: »Det är skrivet: \'Och mitt hus skall vara ett bönehus.\' Men I haven gjort det till en rövarkula.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 47, 'Och han undervisade var dag i helgedomen. Och översteprästerna och de skriftlärde och folkets förnämste män sökte efter tillfälle att förgöra honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 48, 'men de kunde icke finna någon utväg därtill, ty allt folket höll sig till honom och hörde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 1, 'Och en dag, då han undervisade folket i helgedomen och förkunnade evangelium, trädde översteprästerna och de skriftlärde, tillika med de äldste, fram');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 2, 'och talade till honom och sade: »Säg oss, med vad myndighet gör du detta? Och vem är det som har rivit dig sådan myndighet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 3, 'Han svarade och sade till dem: »Också jag vill ställa en fråga till eder; svaren mig på den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 4, 'Johannes\' döpelse, var den från himmelen eller från människor?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 5, 'Då överlade de med varandra och sade: »Om vi svara: \'Från himmelen\' så frågar han: \'Varför trodden I honom då icke?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 6, 'Men om vi svara: \'Från människor\', då kommer allt folket att stena oss, ty de äro förvissade om att Johannes var en profet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 7, 'De svarade alltså att de icke visste varifrån den var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 8, 'Då sade Jesus till dem: »Så säger icke heller jag eder med vad myndighet jag gör detta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 9, 'Och han framställde för folket denna liknelse: »En man planterade en vingård och lejde ut den åt vingårdsmän och för utrikes för lång tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 10, 'När sedan rätta tiden var inne, sände han en tjänare till vingårdsmännen, för att de åt denne skulle lämna någon del av vingårdens frukt. Men vingårdsmännen misshandlade honom och läto honom gå tomhänt bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 11, 'Ytterligare sände han en annan tjänare. Också honom misshandlade och skymfade de och läto honom gå tomhänt bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 12, 'Ytterligare sände han en tredje. Men också denne slogo de blodig och drevo bort honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 13, 'Då sade vingårdens herre: \'Vad skall jag göra? Jo, jag vill sända min älskade son; för honom skola de väl ändå hava försyn.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 14, 'Men när vingårdsmannen fingo se honom, överlade de med varandra och sade: \'Denne är arvingen; låt oss dräpa honom, för att arvet må bliva vårt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 15, 'Och de förde honom ut ur vingården och dräpte honom. »Vad skall nu vingårdens herre göra med dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 16, 'Jo, han skall komma och förgöra de vingårdsmännen och lämna vingården åt andra.» När de hörde detta, sade de: »Bort det!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 17, 'Då såg han på dem och sade: »Vad betyder då detta skriftens ord: \'Den sten som byggningsmännen förkastade, den har blivit en hörnsten\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 18, 'Var och en som faller på den stenen, han skall bliva krossad; men den som stenen faller på, honom skall den söndersmula.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 19, 'Och de skriftlärde och översteprästerna hade gärna velat i samma stund gripa honom, men de fruktade för folket. Ty de förstodo att det var om dem som han hade talat i denna liknelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 20, 'Och de vaktade på honom och sände ut några som försåtligen skulle låtsa sig vara rättsinniga män, för att dessa skulle fånga honom genom något hans ord, så att de skulle kunna överlämna honom åt överheten, i landshövdingens våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 21, 'Dessa frågade honom och sade: »Mästare, vi veta att du talar och undervisar rätt och icke har anseende till personen, utan lär om Guds väg vad sant är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 22, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 23, 'Är det lovligt för oss att giva kejsaren skatt, eller är det icke lovligt?» Men han märkte deras illfundighet och sade till dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 24, '»Låten mig se en penning. Vems bild och överskrift bär den?» De svarade: »Kejsarens.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 25, 'Då sade han till dem: »Given alltså kejsaren vad kejsaren tillhör, och Gud vad Gud tillhör.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 26, 'Och de förmådde icke fånga honom genom något hans ord inför folket, utan förundrade sig över hans svar och tego.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 27, 'Därefter trädde några sadducéer fram och ville påstå att det icke gives någon uppståndelse. Dessa frågade honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 28, 'och sade: »Mästare, Moses har givit oss den föreskriften, att om någon har en broder som är gift, men dör barnlös, så skall han taga sin broders hustru till akta och skaffa avkomma åt sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 29, 'Nu voro här sju bröder. Den förste tog sig en hustru, men dog barnlös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 30, 'Då tog den andre i ordningen henne');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 31, 'och därefter den tredje; sammalunda alla sju. Men de dogo alla, utan att någon av dem lämnade barn efter sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 32, 'Slutligen dog ock hustrun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 33, 'Vilken av dem skall då vid uppståndelsen få kvinnan till hustru? De hade ju alla sju tagit henne till hustru.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 34, 'Jesus svarade dem: »Med den nuvarande tidsålderns barn är det så, att män taga sig hustrur, och hustrur givas åt män;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 35, 'men de som bliva aktade värdiga att få del i den nya tidsåldern och i uppståndelsen från de döda, med dem är det så, att varken män tag sig hustrur, eller hustrur givas män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 36, 'De kunna ju ej heller mer dö ty de äro lika änglarna och äro, Guds söner, eftersom de hava blivit delaktiga av uppståndelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 37, 'Men att de döda uppstå, det har ock Moses, på det ställe där det talas om törnbusken, givit till känna, när han kallar Herren \'Abrahams Gud och Isaks Gud och Jakobs Gud\';');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 38, 'Och han är en Gud icke för döda, utan för levande, ty för honom leva alla.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 39, 'Då svarade några av de skriftlärde och sade: »Mästare, du har talat rätt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 40, 'De dristade sig nämligen icke att vidare ställa någon fråga på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 41, 'Men han sade till dem: »Huru kan man säga att Messias är Davids son?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 42, 'David själv säger ju i Psalmernas bok: Herren sade till min herre: Sätt dig på min högra sida,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 43, 'till dess jag har lagt dina fiender dig till en fotapall.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 44, 'David kallar honom alltså \'herre\'; huru kan han då vara hans son?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 45, 'Och han sade till sina lärjungar, så att allt folket hörde det:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 46, '»Tagen eder till vara för de skriftlärde, som gärna gå omkring i fotsida kläder och gärna vilja bliva hälsade på torgen och gärna sitta främst i synagogorna och på de främsta platserna vid gästabuden --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 47, 'detta under det att de utsuga änkors hus, medan de för syns skull hålla långa baner. Del skola få en dess hårdare dom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 1, 'Och när han såg upp, fick han se huru de rika lade ned sina gåvor i offerkistorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 2, 'Därvid fick han ock se huru en fattig änka lade ned två skärvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 3, 'Då sade han: »Sannerligen säger jag eder: Denna fattiga änka lade dit mer än alla de andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 4, 'Ty det var av sitt överflöd som alla dessa lade ned något bland gåvorna, men hon lade dit av sitt armod allt vad hon hade i sin ägo.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 5, 'Och då några talade om helgedomen, huru den var uppförd av härliga stenar och prydd med helgedomsskänker, sade han:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 6, '»Dagar skola komma, då av allt detta som I nu sen icke skall lämnas sten på sten, utan allt skall bliva nedbrutet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 7, 'Då frågade de honom och sade: »Mästare, när skall detta ske? Och vad bliver tecknet till att tiden är inne, då detta kommer att ske?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 8, 'Han svarade: »Sen till, att I icke bliven förvillade. Ty många skola komma under mitt namn och säga: \'Det är jag\' och: \'Tiden är nära\'. Men följen dem icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 9, 'Och när I fån höra krigslarm och upprorslarm, så bliven icke förfärade; ty sådant måste först komma, men därmed är icke strax änden inne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 10, 'Därefter sade han till dem: »Folk skall resa sig upp mot folk och rike mot rike;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 11, 'och det skall bliva stora jordbävningar, så ock hungersnöd och farsoter på den ena orten efter den andra, och skräcksyner skola visa sig och stora tecken på himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 12, 'Men före allt detta skall man gripa eder, man skall förfölja eder och draga eder inför synagogorna och sätta eder i fängelse och föra eder fram inför konungar och landshövdingar, för mitt namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 13, 'Så skolen I få tillfälle att frambära vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 14, 'Märken därför noga att I icke förut mån göra eder bekymmer för huru I skolen försvara eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 15, 'Ty jag skall giva eder sådana ord och sådan vishet, att ingen av edra vedersakare skall kunna stå emot eller säga något emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 16, 'I skolen bliva förrådda till och med av föräldrar och bröder och fränder och vänner; och somliga av eder skall man döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 17, 'Och I skolen bliva hatade av alla för mitt namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 18, 'Men icke ett hår på edra huvuden skall gå förlorat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 19, 'Genom att vara ståndaktiga skolen I vinna edra själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 20, 'Men när I fån se Jerusalem omringas av krigshärar, då skolen I veta att dess ödeläggelse är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 21, 'Då må de som äro i Judeen fly bort till bergen, och de som äro inne i staden må draga ut därifrån och de som äro ute på landsbygden må icke gå ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 22, 'Ty detta är en hämndens tid, då allt som är skrivet skall uppfyllas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 23, 'Ve dem som äro havande, eller som giva di på den tiden! Ty stor nöd skall då komma i landet, och en vredesdom över detta folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 24, 'Och de skola falla för svärdsegg och bliva bortförda i fångenskap till allahanda hednafolk; och Jerusalem skall bliva förtrampat av hedningarna, till dess att hedningarnas tider äro fullbordade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 25, 'Och tecken skola ske i solen och månen och i stjärnorna, och på jorden skall ångest komma över folken, och de skola stå rådlösa vid havets och vågornas dån,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 26, 'då nu människor uppgiva andan av förskräckelse och ängslan för det som skall övergå världen; ty himmelens makter skola bäva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 27, 'Och då skall man få se \'Människosonen komma i en sky\', med stor makt och härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 28, 'Men när detta begynner ske, då mån I resa eder upp och upplyfta edra huvuden, ty då nalkas eder förlossning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 29, 'Och han framställde för dem en liknelse: »Sen på fikonträdet och på alla andra träd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 30, 'När I fån se att de skjuta knopp, då veten I av eder själva att sommaren redan är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 31, 'Likaså, när I sen detta ske, då kunnen I ock veta att Guds rike är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 32, 'Sannerligen säger jag eder: Detta släkte skall icke förgås, förrän allt detta sker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 33, 'Himmel och jord skola förgås, men mina ord skola aldrig förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 34, 'Men tagen eder till vara för att låta edra hjärtan förtyngas av omåttlighet och dryckenskap och timliga omsorger, så att den dagen kommer på eder oförtänkt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 35, 'ty såsom en snara skall den komma över hela jordens alla inbyggare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 36, 'Men vaken alltjämt, och bedjen att I mån kunna undfly allt detta som skall komma, och kunna bestå inför Människosonen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 37, 'Och han undervisade om dagarna i helgedomen, men om aftnarna gick han ut till det berg som kallas Oljeberget och stannade där över natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 38, 'Och allt folket kom bittida om morgonen till honom i helgedomen för att höra honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 1, 'Det osyrade brödets högtid, som ock kallas påsk, var nu nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 2, 'Och översteprästerna och de skriftlärde sökte efter tillfälle att röja honom ur vägen. De fruktade nämligen för folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 3, 'Men Satan for in i Judas, som kallades Iskariot, och som var en av de tolv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 4, 'Denne gick bort och talade med översteprästerna och befälhavarna för tempelvakten om huru han skulle överlämna honom åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 5, 'Då blevo de glada och förklarade sig villiga att giva honom en summa penningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 6, 'Och han gick in på deras anbud och sökte sedan efter lägligt tillfälle att förråda honom åt dem, utan att någon folkskockning uppstod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 7, 'Så kom nu den dag i det osyrad brödets högtid, då man skulle slakta påskalammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 8, 'Då sände han åstad Petrus och Johannes och sade: »Gån åstad och reden till åt oss, så att vi kunna äta påskalammet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 9, 'De frågade honom: Var vill du att vi skola reda till det?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 10, 'Han svarade dem: När I kommen in i staden, skolen I möta en man som bär en kruka vatten. Följen honom till det hus där han går in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 11, 'Och sägen till husbonden i det huset: \'Mästaren frågar dig: Var finnes härbärget där jag skall äta påskalammet med mina lärjungar?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 12, 'Då skall han visa eder en stor sal i övre våningen, ordnad för måltid; reden till där.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 13, 'Och de gingo åstad och funno det så som han hade sagt dem; och de redde till påskalammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 14, 'Och när stunden var inne, lade han sig till bords, och apostlarna med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 15, 'Och han sade till dem: »Jag har högeligen åstundat att äta detta påskalamm med eder, förrän mitt lidande begynner;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 16, 'ty jag säger eder att jag icke mer skall fira denna högtid, förrän den kommer till fullbordan i Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 17, 'Och han lät giva sig en kalk och tackade Gud och sade: »Tagen detta och delen eder emellan;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 18, 'ty jag säger eder att jag härefter icke, förrän Guds rike kommer, skall dricka av det som kommer från vinträd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 19, 'Sedan tog han ett bröd och tackade Gud och bröt det och gav åt dem och sade: »Detta är min lekamen, som varder utgiven för eder. Gören detta till min åminnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 20, 'Sammalunda tog han ock kalken, efter måltiden, och sade: »Denna kalk är det nya förbundet, i mitt blod, som varder utgjutet för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 21, 'Men se, den som förråder mig, hans hand är med mig på bordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 22, 'Ty Människosonen skall gå bort, såsom förut är bestämt; men ve den människa genom vilken han bliver förrådd!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 23, 'Och de begynte tala med varandra om vilken av dem det väl kunde vara som skulle göra detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 24, 'En tvist uppstod ock mellan dem om vilken av dem som skulle räknas för den störste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 25, 'Då sade han till dem: »Konungarna uppträda mot sina folk såsom härskare, och de som hava myndighet över folken låta kalla sig \'nådige herrar\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 26, 'Men så är det icke med eder; utan den som är störst bland eder, han vare såsom den yngste, och den som är den förnämste, han vare såsom en tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 27, 'Ty vilken är större: den som ligger till bords eller den som tjänar? Är det icke den som ligger till bords? Och likväl är jag här ibland eder såsom en tjänare. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 28, 'Men I ären de som hava förblivit hos mig i mina prövningar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 29, 'och såsom min Fader har överlåtit konungslig makt åt mig, så överlåter jag likadan makt åt eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 30, 'så att I skolen få äta och dricka vid mitt bord i mitt rike och sitta på troner såsom domare över Israels tolv släkter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 31, 'Simon, Simon! Se, Satan har begärt att få eder i sitt våld, för att kunna sålla eder såsom vete;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 32, 'men jag har bett för dig, att din tro icke må bliva om intet. Och när du en gång har omvänt dig, så styrk dina bröder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 33, 'Då sade han till honom: »Herre, jag är redo att med dig både gå i fängelse och gå i döden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 34, 'Men han svarade: »Jag säger dig, Petrus: I dag skall icke hanen gala, förrän du tre gånger har förnekat mig och sagt att du icke känner mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 35, 'Ytterligare sade han till dem: »När jag sände eder åstad utan penningpung, utan ränsel, utan skor, icke fattades eder då något?» De svarade: »Intet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 36, 'Då sade han till dem: »Nu åter må den som har en penningpung taga den med sig, och den som har en ränsel, han göre sammalunda; och den som icke har något svärd, han sälje sin mantel och köpe sig ett sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 37, 'Ty jag säger eder att på mig måste fullbordas detta skriftens ord: \'Han blev räknad bland ogärningsmän\'. Ja, det som är förutsagt om mig, det går nu i fullbordan»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 38, 'Då sade de: »Herre, se här äro två svärd.» Han svarade dem: »Det är nog.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 39, 'Och han gick ut och begav sig till Oljeberget, såsom hans sed var; och hans lärjungar följde honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 40, 'Men när han hade kommit till platsen, sade han till dem: »Bedjen att I icke mån komma i frestelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 41, 'Sedan gick han bort ifrån dem, vid pass ett stenkast, och föll ned på sina knän och bad');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 42, 'och sade: »Fader, om det är din vilja, så tag denna kalk ifrån mig. Dock, ske icke min vilja, utan din.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 43, 'Då visade sig för honom en ängel från himmelen, som styrkte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 44, 'Men han hade kommit i svår ångest och bad allt ivrigare, och hans svett blev såsom blodsdroppar, som föllo ned på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 45, 'När han sedan stod upp från bönen och kom tillbaka till lärjungarna, fann han dem insomnade av bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 46, 'Då sade han till dem: »Varför soven I? Stån upp, och bedjen att I icke mån komma i frestelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 47, 'Och se, medan han ännu talade, kom en folkskara; och en av de tolv, den som hette Judas, gick framför dem. Och han trädde fram till Jesus för att kyssa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 48, 'Men Jesus sade till honom: »Judas, förråder du Människosonen med en kyss?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 49, 'Då nu de som voro med Jesus sågo vad som var på färde, frågade de: »Herre, skola vi hugga till med svärd?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 50, 'Och en av dem högg till översteprästens tjänare och högg så av honom högra örat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 51, 'Då svarade Jesus och sade: »Låten det gå så långt.» Och han rörde vid hans öra och helade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 52, 'Sedan sade Jesus till dem som hade kommit emot honom, till översteprästerna och befälhavarna för tempelvakten och de äldste: »Såsom mot en rövare haven I gått ut med svärd och stavar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 53, 'Fastän jag var dag har varit med eder i helgedomen, haven I icke sträckt ut edra händer emot mig men detta är eder stund, och nu råder mörkrets makt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 54, 'Så grepo de honom och förde honom åstad in i översteprästens hus. Och Petrus följde efter på avstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 55, 'Och de tände upp en eld mitt på gården och satte sig där tillsammans, och Petrus satte sig ibland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 56, 'Men en tjänstekvinna, som fick se honom, där han satt vid elden fäste ögonen på honom och sade: »Också denne var med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 57, 'Men han nekade och sade: »Kvinna, jag känner honom icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 58, 'Kort därefter fick en annan, en av mannen, se honom och sade: »Också du är en av dem.» Men Petrus svarade: »Nej, det är jag icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 59, 'Vid pass en timme därefter kom en annan som bedyrade och sade: »Förvisso var också denne med honom; han är ju ock en galilé.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 60, 'Då svarade Petrus: »Jag förstår icke vad du menar.» Och i detsamma, medan han ännu talade, gol hanen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 61, 'Då vände Herren sig om och såg på Petrus; och Petrus kom då ihåg Herrens ord, huru han hade sagt till honom: »Förrän hanen i dag har galit, skall du tre gånger förneka mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 62, 'Och han gick ut och grät bitterligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 63, 'Och de män som höllo Jesus fången begabbade honom och misshandlade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 64, 'De höljde över honom och frågade honom och sade: »Profetera: vem var det som slog dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 65, 'Många andra smädliga ord talade de ock mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 66, 'Men när det blev dag, församlade sig folkets äldste, överstepräster och skriftlärde, och läto föra honom inför sitt Stora råd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 67, 'och sade: »Är du Messias, så säg oss det.» Men han svarade dem: »Om jag säger eder det, så tron I det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 68, 'Och om jag frågar, så svaren I icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 69, 'Men härefter skall Människosonen sitta på den gudomliga Maktens högra sida.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 70, 'Då sade de alla: »Så är du då Guds Son?» Han svarade dem: »I sägen det själva, att jag är det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 71, 'Då sade de: »Vad behöva vi mer något vittnesbörd? Vi hava ju själva nu hört det av hans egen mun.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 1, 'Och de stodo upp, hela hopen, och förde honom till Pilatus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 2, 'Där begynte de anklaga honom och sade: »Vi hava funnit att denne man förleder vårt folk och vill förhindra att man giver kejsaren skatt, och att han säger sig vara Messias, en konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 3, 'Då frågade Pilatus honom och sade: Är du judarnas konung?» Han svarade honom och sade: »Du säger det själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 4, 'Men Pilatus sade till översteprästerna och till folket: »Jag finner intet brottsligt hos denne man.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 5, 'Då blevo de ännu ivrigare och sade: »Han uppviglar med sin lära folket i hela Judeen, allt ifrån Galileen och ända hit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 6, 'När Pilatus hörde detta, frågade han om mannen var från Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 7, 'Och då han fick veta att han var från det land som lydde under Herodes\' välde, sände han honom bort till Herodes, som under dessa dalar också var i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 8, 'När Herodes fick se Jesus, blev han mycket glad, ty han hade sedan lång tid velat se honom; han hade nämligen hört talas om honom, och han hoppades nu att få se honom göra något tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 9, 'Men fastän han ställde ganska många frågor på Jesus, svarade denne honom intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 10, 'Och översteprästerna och de skriftlärde stodo där och anklagade honom häftigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 11, 'Men Herodes och hans krigsfolk bemötte honom med förakt och begabbade honom; och sedan de hade satt på honom en lysande klädnad, sände de honom tillbaka till Pilatus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 12, 'Och Herodes och Pilatus blevo den dagen vänner med varandra; Förut hade nämligen dem emellan rått ovänskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 13, 'Sedan kallade Pilatus tillhopa översteprästerna och rådsherrarna och folket');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 14, 'och sade till dem: »I haven fört till mig denne man och sagt att han förleder folket; och jag har nu i eder närvaro anställt rannsakning med honom, men icke funnit honom skyldig till något av det som I anklagen honom för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 15, 'Och ej heller Herodes har funnit honom skyldig; han har ju sänt honom tillbaka till oss. I sen alltså att denne icke har gjort något som förtjänar döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 16, 'Därför vill jag giva honom lös, medan jag har tuktat honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 17, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 18, 'Då skriade hela hopen och sade: »Hav bort denne, och giv oss Barabbas lös.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 19, '(Denne man hade blivit kastad i fängelse på grund av ett upplopp, som hade ägt rum i staden, och för ett dråps skull.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 20, 'Åter talade Pilatus till dem, ty han önskade att kunna giva Jesus lös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 21, 'Men de ropade emot honom: »Korsfäst, korsfäst honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 22, 'Då talade han till dem för tredje gången och frågade: »Vad ont har denne då gjort? Jag har icke funnit honom skyldig till något som förtjänar döden Därför vill jag giva honom lös, sedan jag har tuktat honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 23, 'Men de lågo över honom med höga rop och begärde att han skulle låta korsfästa honom; och deras rop blevo honom övermäktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 24, 'Då dömde Pilatus att så skulle ske, som de begärde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 25, 'Och han lösgav den man de begärde, den som hade blivit kastad i fängelse för upplopp och dråp; men Jesus utlämnade han, för att med honom skulle ske efter deras vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 26, 'När de sedan förde bort honom, fingo de fatt en man, Simon från Cyrene, som kom utifrån marken; på honom lade de korset, för att han skulle bära det efter Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 27, 'Men en stor hop folk följde med honom, bland dem också kvinnor som jämrade sig och gräto över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 28, 'Då vände Jesus sig om till dem och sade: »I Jerusalems döttrar, gråten icke över mig, utan gråten över eder själva och över edra barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 29, 'Ty se, den tid skall komma, då man skall säga: \'Saliga äro de ofruktsamma, de moderliv som icke hava fött barn, och de bröst som icke hava givit di.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 30, 'Då skall man begynna säga till: bergen: \'Fallen över oss\', och till höjderna: \'Skylen oss.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 31, 'Ty om han gör så med det friska trädet, vad skall icke då ske med det torra!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 32, 'Jämväl två andra, två ogärningsmän, fördes ut för att avlivas tillika med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 33, 'Och när de hade kommit till den plats som kallades »Huvudskallen» korsfäste de honom där, så ock ogärningsmännen, den ene på högra sidan och den andre på vänstra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 34, 'Men Jesus sade. »Fader, förlåt dem; ty de veta icke vad de göra. Och de delade hans kläder mellan sig och kastade lott om dem. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 35, 'Men folket stod och såg därpå. Och jämväl rådsherrarna drevo gäck med honom och sade: »Andra har han hjälpt; nu må han hjälpa sig själv, om han är Guds Smorde, den utvalde.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 36, 'Också krigsmännen gingo fram och begabbade honom och räckte honom ättikvin');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 37, 'och sade: »Är du judarnas konung, så hjälp dig själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 38, 'Men över honom hade man ock satt upp en överskrift: »Denne är judarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 39, 'Och en av de ogärningsmän som voro där upphängda smädade honom och sade: »Du är ju Messias; hjälp då dig själv och oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 40, 'Då tillrättavisade honom den andre och svarade och sade: »Fruktar icke heller du Gud, du som är under samma dom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 41, 'Oss vederfares detta med all rätt, ty vi lida vad våra gärningar äro värda, men denne man har intet ont gjort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 42, 'Sedan sade han: »Jesus, tänk på mig, när du kommer i ditt rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 43, 'Han svarade honom: »Sannerligen säger jag dig: I dag skall du vara med mig i paradiset.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 44, 'Det var nu omkring sjätte timmen; då kom över hela landet ett mörker, som varade ända till nionde timmen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 45, 'i det att solen miste sitt sken. Och förlåten i templet rämnade mitt itu.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 46, 'Och Jesus ropade med hög röst och sade: »Fader, i dina händer befaller jag min ande.» Och när han hade sagt detta, gav han upp andan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 47, 'Men när hövitsmannen såg vad som skedde, prisade han Gud och sade: »Så var då denne verkligen en rättfärdig man!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 48, 'Och när allt folket, de som hade kommit tillsammans för att se härpå, sågo vad som skedde, slogo de sig för bröstet och vände hem igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 49, 'Men alla hans vänner stodo på avstånd och sågo detta, bland dem också några kvinnor, de som hade följt med honom från Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 50, 'Nu var där en rådsherre, vi namn Josef, en god och rättfärdig man,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 51, 'som icke hade samtyckt till deras rådslag och gärning. Han var från Arimatea, en stad i Judeen; och han väntade på Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 52, 'Denne gick till Pilatus och utbad sig att få Jesu kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 53, 'Och han tog ned den och svepte den i en linneduk. Sedan lade han den i en grav som var uthuggen i klippan, och där ännu ingen hade varit lagd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 54, 'Det var då tillredelsedag, och sabbatsdagen begynte ingå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 55, 'Och de kvinnor, som med honom hade kommit från Galileen, följde efter och sågo graven och sågo huru hans kropp lades ned däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 56, 'Sedan vände de hem igen och redde till välluktande kryddor och smörjelse; men på sabbaten voro de stilla, efter lagens bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 1, 'Men på första veckodagen kommo de, tidigt i själva dagbräckningen, till graven med de välluktande kryddor som de hade tillrett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 2, 'Och de funno stenen vara bortvältrad från graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 3, 'Då gingo de ditin, men funno icke Herren Jesu kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 4, 'När de nu icke visste vad de skulle tänka härom, se, då stodo två man framför dem i skinande kläder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 5, 'Och de blevo förskräckta och böjde sina ansikten ned mot jorden. Då sade mannen till dem »Varför söken I den levande bland de döda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 6, 'Han är icke har, han är uppstånden. Kommen ihåg vad han talade till eder, medan han ännu var i Galileen, huru han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 7, '\'Människosonen måste bliva överlämnad i syndiga människors händer och bliva korsfäst; men på tredje dagen skall han uppstå igen.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 8, 'Då kommo de ihåg hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 9, 'Och de vände tillbaka från graven och omtalade allt detta för de elva och för alla de andra. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 10, 'Kvinnorna voro Maria från Magdala och Johanna och den Maria som var Jakobs moder. Och jämväl de andra kvinnorna instämde med dem och sade detsamma till apostlarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 11, 'Deras ord syntes dock för dessa vara löst tal, och de trodde dem icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 12, 'Men Petrus stod upp och skyndade till graven; och när han lutade sig ditin såg han där allenast linnebindlarna. Sedan gick han hem till sitt, uppfylld av förundran över det som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 13, 'Men två av dem voro samma dag stadda på vandring till en by som hette Emmaus, och som låg sextio stadiers väg från Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 14, 'Och de samtalade med varandra om allt detta som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 15, 'Medan de nu samtalade och överlade med varandra, nalkades Jesus själv och gick med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 16, 'Men deras ögon voro tillslutna, så att de icke kände igen honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 17, 'Och han sade till dem: »Vad är det I talen om med varandra, medan I gån här?» Då stannade de och sågo bedrövade ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 18, 'Och den ene, som hette Kleopas, svarade och sade till honom: »Du är väl en främling i Jerusalem, den ende som icke har hört vad där har skett i dessa dagar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 19, 'Han frågade dem: »Vad då?» De svarade honom: »Det som har skett med Jesus från Nasaret, vilken var en profet, mäktig i gärningar och ord inför Gud och allt folket:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 20, 'huru nämligen våra överstepräster och rådsherrar hava utlämnat honom till att dömas till döden och hava korsfäst honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 21, 'Men vi hoppades att han var den som skulle förlossa Israel. Och likväl, till allt detta kommer att det redan är tredje dagen sedan detta skedde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 22, 'Men nu hava därjämte några av våra kvinnor gjort oss häpna; ty sedan de bittida på morgonen hade varit vid graven');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 23, 'och icke funnit hans kropp, kommo de igen och sade att de till och med hade sett en änglasyn, och änglarna hade sagt att han levde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 24, 'Och när några av dem som voro med oss gingo bort till graven, funno de det vara så som kvinnorna hade sagt, men honom själv sågo de icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 25, 'Då sade han till dem: »O, huru oförståndiga ären I icke och tröghjärtade till att tro på allt vad profeterna hava talat!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 26, 'Måste icke Messias lida detta, för I att så ingå i sin härlighet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 27, 'Och han begynte att genomgå Moses och alla profeterna och uttydde för dem vad som i alla skrifterna var sagt om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 28, 'När de nu nalkades byn dit de voro på väg, ställde han sig som om han ville gå vidare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 29, 'Men de nödgade honom och sade: »Bliv kvar hos oss, ty det lider mot aftonen, och dagen nalkas redan sitt slut.» Då gick han ditin och stannade kvar hos dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 30, 'Och när han nu låg till bords med dem, tog han brödet och välsignade och bröt det och räckte åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 31, 'Därvid öppnades deras ögon, så att de kände igen honom. Men då försvann han ur deras åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 32, 'Och de sade till varandra: »Voro icke våra hjärtan brinnande i oss, när han talade med oss på vägen och uttydde skrifterna för oss?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 33, 'Och i samma stund stodo de upp och vände tillbaka till Jerusalem; och de funno där de elva församlade, så ock de andra som hade slutit sig till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 34, 'Och dessa sade: »Herren är verkligen uppstånden, och han har visat sig för Simon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 35, 'Då förtäljde de själva vad som hade skett på vägen, och huru han hade blivit igenkänd av dem, när han bröt brödet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 36, 'Medan de nu talade härom, stod han själv mitt ibland dem och sade till dem: »Frid vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 37, 'Då blevo de förfärade och uppfylldes av fruktan och trodde att det var en ande de sågo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 38, 'Men han sade till dem: »Varför ären I så förskräckta, och varför uppstiga tvivel i edra hjärtan?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 39, 'Sen här mina händer och mina fötter, och sen att det är jag själv; ja, tagen på mig och sen. En ande har ju icke kött och ben, såsom I sen mig hava.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 40, 'Och när han hade sagt detta, visade han dem sina händer och sina fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 41, 'Men då de ännu icke trodde, för glädjes skull, utan allenast förundrade sig, sade han till dem: »Haven I här något att äta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 42, 'Då räckte de honom ett stycke stekt fisk och något av en honungskaka;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 43, 'och han tog det och åt därav i deras åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 44, 'Och han sade till dem: »Det är såsom jag sade till eder, medan jag ännu var bland eder, att allt måste fullbordas, som är skrivet om mig i Moses\' lag och hos profeterna och i psalmerna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 45, 'Därefter öppnade han deras sinnen, så att de förstodo skrifterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 46, 'Och han sade till dem: »Det är så skrivet, att Messias skulle lida och på tredje dagen uppstå från de döda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 47, 'och att bättring till syndernas förlåtelse i hans namn skulle predikas bland alla folk, och först i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 48, 'I kunnen vittna härom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 49, 'Och se, jag vill sända till eder vad min Fader har utlovat. Men I skolen stanna kvar här i staden, till dess I från höjden bliven beklädda med kraft.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 50, 'Sedan förde han dem ut till Betania; och där lyfte han upp sina händer och välsignade dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 51, 'Och medan han välsignade dem, försvann han ifrån dem och blev upptagen till himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 52, 'Då tillbådo de honom och vände sedan tillbaka till Jerusalem, uppfyllda av stor glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 53, 'Och de voro sedan alltid i helgedomen och lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'I begynnelsen var Ordet, och Ordet var hos Gud, och Ordet var Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Detta var i begynnelsen hos Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Genom det har allt blivit till, och utan det har intet blivit till, som är till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'I det var liv, och livet var människornas ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Och ljuset lyser i mörkret, och mörkret har icke fått makt därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'En man uppträdde, sänd av Gud; hans namn var Johannes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Han kom såsom ett vittne, för att vittna om ljuset, på det att alla skulle komma till tro genom honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Icke var han ljuset, men han skulle vittna om ljuset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Det sanna ljuset, det som lyser över alla människor, skulle nu komma i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'I världen var han, och genom honom hade världen blivit till, men världen ville icke veta av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Han kom till sitt eget, och hans egna togo icke emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Men åt alla dem som togo emot honom gav han makt att bliva Guds barn, åt dem som tro på hans namn;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'och de hava blivit födda, icke av blod, ej heller av köttslig vilja, ej heller av någon mans vilja, utan av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Och Ordet vart kött och tog sin boning ibland oss, och vi sågo hans härlighet, vi sågo likasom en enfödd Sons härlighet från sin Fader, och han var full av nåd och sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Johannes vittnar om honom, han ropar och säger: »Det var om denne jag sade: \'Den som kommer efter mig, han är före mig; ty han var förr än jag.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Av hans fullhet hava vi ju alla fått, ja, nåd utöver nåd;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'ty genom Moses blev lagen given, men nåden och sanningen hava kommit genom Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Ingen har någonsin sett Gud; den enfödde Sonen, som är i Faderns sköte[1], han har kungjort vad Gud är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Och detta är vad Johannes vittnade, när judarna hade sänt till honom präster och leviter från Jerusalem för att fråga honom vem han var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Han svarade öppet och förnekade icke; han sade öppet: »Jag är icke Messias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Åter frågade de honom: »Vad är du då? Är du Elias?» Han svarade: »Det är jag icke.» -- »Är du Profeten?» Han svarade: »Nej.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Då sade de till honom: »Vem är du då? Säg oss det, så att vi kunna giva dem svar, som hava sänt oss. Vad säger du om dig själv?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Han svarade: »Jag är rösten av en som ropar i öknen: \'Jämnen vägen för Herren\', såsom profeten Esaias sade.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Och männen voro utsända ifrån fariséerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Och de frågade honom och sade till honom: »Varför döper du då, om du icke är Messias, ej heller Elias, ej heller Profeten?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, 'Johannes svarade dem och sade: »Jag döper i vatten; men mitt ibland eder står en som I icke kännen:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'han som kommer efter mig[2], vilkens skorem jag icke är värdig att upplösa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'Detta skedde i Betania, på andra sidan Jordan, där Johannes döpte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'Dagen därefter såg han Jesus nalkas; då sade han: »Se, Guds Lamm, som borttager världens synd!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'Om denne var det som jag sade: \'Efter mig kommer en man som är före mig; ty han var förr än jag.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 31, 'Och jag kände honom icke; men för att han skall bliva uppenbar för Israel, därför är jag kommen och döper i vatten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 32, 'Och Johannes vittnade och sade: »Jag såg Anden såsom en duva sänka sig ned från himmelen; och han förblev över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 33, 'Och jag kände honom icke; men den som sände mig till att döpa i vatten, han sade till mig: \'Den över vilken du får se Anden sänka sig ned och förbliva, han är den som döper i helig ande.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 34, 'Och jag har sett det, och jag har vittnat att denne är Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 35, 'Dagen därefter stod Johannes åter där med två av sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 36, 'När då Jesus kom gående, såg Johannes på honom och sade: »Se, Guds Lamm!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 37, 'Och de två lärjungarna hörde hans ord och följde Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 38, 'Då vände sig Jesus om, och när han såg att de följde honom, frågade han dem: »Vad viljen I?» De svarade honom: »Rabbi» (det betyder mästare) »var bor du?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 39, 'Han sade till dem: »Kommen och sen.» Då gingo de med honom och sågo var han bodde; och de stannade den dagen hos honom. -- Detta skedde vid den tionde timmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 40, 'En av de två som hade hört var Johannes sade, och som hade följt Jesus, var Andreas, Simon Petrus\' broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 41, 'Denne träffade först sin broder Simon och sade till honom: »Vi hava funnit Messias» (det betyder detsamma som Kristus).[3]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 42, 'Och han förde honom till Jesus. Då såg Jesus på honom och sade: »Du är Simon, Johannes\' son; du skall heta Cefas» (det betyder detsamma som Petrus).[4]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 43, 'Dagen därefter ville Jesus gå därifrån till Galileen, och han träffade då Filippus. Och Jesus sade till honom: »Följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 44, 'Och Filippus var från Betsaida, Andreas\' och Petrus\' stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 45, 'Filippus träffade Natanael och sade till honom: »Den som Moses har skrivit om i lagen och som profeterna hava skrivit om, honom hava vi funnit, Jesus, Josefs son, från Nasaret.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 46, 'Natanael sade till honom: »Kan något gott komma från Nasaret?» Filippus svarade honom: »Kom och se.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 47, 'När nu Jesus såg Natanael nalkas, sade han om honom: »Se, denne är en rätt israelit, i vilken icke finnes något svek.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 48, 'Natanael frågade honom: »Huru kan du känna mig?» Jesus svarade och sade till honom: »Förrän Filippus kallade dig, såg jag dig, där du var under fikonträdet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 49, 'Natanael svarade honom: »Rabbi, du är Guds Son, du är Israels konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 50, 'Jesus svarade och sade till honom: »Eftersom jag sade dig att jag såg dig under fikonträdet, tror du? Större ting än vad detta är skall du få se.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 51, 'Därefter sade han till honom: »Sannerligen, sannerligen säger jag eder: I skolen få se himmelen öppen och Guds änglar fara upp och fara ned över Människosonen.» [1] Eller: Ingen har någonsin sett Gud; en enfödd Gud, han som är i Faderns sköte, osv. [2] vilken har varit före mig. [3] Båda orden betyda den smorde; det förra är arameiska, det senare grekiska. [4] Det arameiska ordet kefa betyder klippa -- Jfr Matt 16,18.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'På tredje dagen var ett bröllop i Kana i Galileen, och Jesu moder var där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Också Jesus och hans lärjungar blevo bjudna till bröllopet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Och vinet begynte taga slut. Då sade Jesu moder till honom: »De hava intet vin.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Jesus svarade henne: »Låt mig vara, moder; min stund är ännu icke kommen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Hans moder sade då till tjänarna: »Vadhelst han säger till eder, det skolen I göra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Nu stodo där sex stenkrukor, sådana som judarna hade för sina reningar; de rymde två eller tre bat-mått var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Jesus sade till dem: »Fyllen krukorna med vatten.» Och de fyllde dem ända till brädden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Sedan sade han till dem: »Ösen nu upp och bären till övertjänaren.» Och de gjorde så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Och övertjänaren smakade på vattnet, som nu hade blivit vin; och han visste icke varifrån det hade kommit, vilket däremot tjänarna visste, de som hade öst upp vattnet. Då kallade övertjänaren på brudgummen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'och sade till honom: »Man brukar eljest alltid sätta fram det goda vinet, och sedan, när gästerna hava fått för mycket, det som är sämre. Du har gömt det goda vinet ända tills nu.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Detta var det första tecknet som Jesus gjorde. Han gjorde det i Kana i Galileen och uppenbarade så sin härlighet; och hans lärjungar trodde på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Därefter begav han sig ned till Kapernaum med sin moder och sina bröder och sina lärjungar; och där stannade de några få dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Judarnas påsk var nu nära, och Jesus begav sig då upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Och när han fick i helgedomen se huru där sutto män som sålde fäkreatur och får och duvor, och huru växlare sutto där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Då gjorde han sig ett gissel av tåg och drev dem alla ut ur helgedomen, med får och fäkreatur, och slog ut växlarnas penningar och stötte omkull deras bord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Och till duvomånglarna sade han: »Tagen bort detta härifrån; gören icke min Faders hus till ett marknadshus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Hans lärjungar kommo då ihåg att det var skrivet: »Nitälskan för ditt hus skall förtära mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Då togo judarna till orda och sade till honom: »Vad för tecken låter du oss se, eftersom du gör på detta sätt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Jesus svarade och sade till dem: »Bryten ned detta tempel, så skall jag inom tre dagar låta det uppstå igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Då sade judarna: »I fyrtiosex år har man byggt på detta tempel, och du skulle låta det uppstå igen inom tre dagar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Men det var om sin kropps tempel han talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Sedan, när han hade uppstått från de döda, kommo hans lärjungar ihåg att han hade sagt detta; och de trodde då skriften och det ord som Jesus hade sagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Medan han nu var i Jerusalem, under påsken, vid högtiden, kommo många till tro på hans namn, när de sågo de tecken som han gjorde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Men själv betrodde sig Jesus icke åt dem, eftersom han kände alla');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'och icke behövde någon annans vittnesbörd om människorna; ty av sig själv visste han vad i människan var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Men bland fariséerna var en man som hette Nikodemus, en av judarnas rådsherrar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Denne kom till Jesus om natten och sade till honom: »Rabbi, vi veta att det är från Gud du har kommit såsom lärare; ty ingen kan göra sådana tecken som du gör, om icke Gud är med honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Jesus svarade och sade till honom: »Sannerligen, sannerligen säger jag dig: Om en människa icke bliver född på nytt[1], så kan hon icke få se Guds rike.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Nikodemus sade till honom: »Huru kan en människa födas, när hon är gammal? Icke kan hon väl åter gå in i sin moders liv och födas?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Jesus svarade: »Sannerligen, sannerligen säger jag dig: Om en människa icke bliver född av vatten och ande, så kan hon icke komma in i Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Det som är fött av kött, det är kött; och det som är fött av Anden, det är ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Förundra dig icke över att jag sade dig att I måsten födas på nytt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Vinden blåser vart den vill, och du hör dess sus, men du vet icke varifrån den kommer, eller vart den far; så är det med var och en som är född av Anden[2].»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Nikodemus svarade och sade till honom: »Huru kan detta ske?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Jesus svarade och sade till honom: »Är du Israels lärare och förstår icke detta?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Sannerligen, sannerligen säger jag dig: Vad vi veta, det tala vi, och vad vi hava sett, det vittna vi om, men vårt vittnesbörd tagen I icke emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Tron i icke, när jag talar till eder om jordiska ting, huru skolen I då kunna tro, när jag talar till eder om himmelska ting?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Och likväl har ingen stigit upp till himmelen, utom den som steg ned från himmelen, Människosonen, som var i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Och såsom Moses upphöjde ormen i öknen, så måste Människosonen bliva upphöjd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'så att var och en som tror skall i honom hava evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Ty så älskade Gud världen, att han utgav sin enfödde Son, på det att var och en som tror på honom skall icke förgås, utan hava evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Ty icke sände Gud sin Son i världen för att döma världen, utan för att världen skulle bliva frälst genom honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Den som tror på honom, han bliver icke dömd, men den som icke tror, han är redan dömd, eftersom han icke tror på Guds enfödde Sons namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Och detta är domen, att när ljuset hade kommit i världen, människorna dock älskade mörkret mer än ljuset, eftersom deras gärningar voro onda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Ty var och en som gör vad ont är, han hatar ljuset och kommer icke till ljuset, på det att hans gärningar icke skola bliva blottade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Men den som gör sanningen, han kommer till ljuset, för att det skall bliva uppenbart att hans gärningar äro gjorda i Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Därefter begav sig Jesus med sina lärjungar till den judiska landsbygden, och där vistades han med dem och döpte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 23, 'Men också Johannes döpte, i Enon, nära Salim, ty där fanns mycket vatten; och folket kom dit och lät döpa sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 24, 'Johannes hade nämligen ännu icke blivit kastad i fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 25, 'Då uppstod mellan Johannes\' lärjungar och en jude en tvist om reningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 26, 'Och de kommo till Johannes och sade till honom: »Rabbi, se, den som var hos dig på andra sidan Jordan, den som du har vittnat om, han döper, och alla komma till honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 27, 'Johannes svarade och sade: »En människa kan intet taga, om det icke bliver henne givet från himmelen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 28, 'I kunnen själva giva mig det vittnesbördet att jag sade: \'Icke är jag Messias; jag är allenast sänd framför honom.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 29, 'Brudgum är den som har bruden; men brudgummens vän, som står där och hör honom, han gläder sig storligen åt brudgummens röst. Den glädjen är mig nu given i fullt mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 30, 'Det är såsom sig bör att han växer till, och att jag förminskas. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 31, 'Den som kommer ovanifrån, han är över alla; den som är från jorden, han är av jorden, och av jorden talar han. Ja, den som kommer från himmelen, han är över alla,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 32, 'och vad han har sett och hört, det vittnar han om; och likväl tager ingen emot hans vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 33, 'Men om någon tager emot hans vittnesbörd, så bekräftar han därmed att Gud är sannfärdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 34, 'Ty den som Gud har sänt, han talar Guds ord; Gud giver nämligen icke Anden efter mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 35, 'Fadern älskar Sonen, och allt har han givit i hans hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 36, 'Den som tror på Sonen, han har evigt liv; men den som icke hörsammar Sonen, han skall icke få se livet, utan Guds vrede förbliver över honom.» [1] Grundtextens uttryck har den dubbla betydelsen på nytt och ovanifrån; jfr v. 31. [2] Grundtexten har här samma uttryck för vind som för ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Men Herren fick nu veta att fariséerna hade hört hurusom Jesus vann flera lärjungar och döpte flera än Johannes;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'dock var det icke Jesus själv som döpte, utan hans lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Då lämnade han Judeen och begav sig åter till Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Därvid måste han taga vägen genom Samarien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Så kom han till en stad i Samarien som hette Sykar, nära det jordstycke som Jakob gav åt sin son Josef.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Och där var Jakobs brunn. Eftersom nu Jesus var trött av vandringen, satte han sig strax ned vid brunnen. Det var vid den sjätte timmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Då kom en samaritisk kvinna för att hämta vatten. Jesus sade till henne: »Giv mig att dricka.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Hans lärjungar hade nämligen gått in i staden för att köpa mat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Då sade den samaritiska kvinnan till honom: »Huru kan du, som är jude, bedja mig, som är en samaritisk kvinna, om något att dricka?» Judarna hava nämligen ingen umgängelse med samariterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Jesus svarade och sade till henne: »Förstode du Guds gåva, och vem den är som säger till dig: \'Giv mig att dricka\', så skulle i stället du hava bett honom, och han skulle då hava givit dig levande vatten[1].»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Kvinnan sade till honom: »Herre, du har ju intet att hämta upp vatten med, och brunnen är djup. Varifrån får du då det friska vattnet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Icke är du väl förmer än vår fader Jakob, som gav oss brunnen och själv med sina barn och sin boskap drack ur den?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Jesus svarade och sade till henne: »Var och en som dricker av detta vatten, han bliver törstig igen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'men den som dricker av det vatten som jag giver honom, han skall aldrig någonsin törsta, utan det vatten jag giver honom skall bliva i honom en källa vars vatten springer upp med evigt liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Kvinnan sade till honom: »Herre, giv mig det vattnet, så att jag icke mer behöver törsta och komma hit för att hämta vatten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Han sade till henne: »Gå och hämta din man, och kom sedan tillbaka.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Kvinnan svarade och sade: »Jag har ingen man.» Jesus sade till henne: »Du har rätt i vad du säger, att du icke har någon man.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Ty fem män har du haft, och den du nu har är icke din man; däri sade du sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Då sade kvinnan till honom: »Herre, jag ser att du är en profet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Våra fäder hava tillbett på detta berg, men I sägen att i Jerusalem den plats finnes, där man bör tillbedja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Jesus sade till henne: »Tro mig, kvinna: den tid kommer, då det varken är på detta berg eller i Jerusalem som I skolen tillbedja Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 22, 'I tillbedjen vad I icke kännen, vi tillbedja vad vi känna -- ty frälsningen kommer från judarna --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 23, 'men den tid skall komma, ja, den är redan inne, då sanna tillbedjare skola tillbedja Fadern i ande och sanning; ty sådana tillbedjare vill Fadern hava.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 24, 'Gud är ande, och de som tillbedja måste tillbedja i ande och sanning.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 25, 'Kvinnan sade till honom: »Jag vet att Messias skall komma, han som ock kallas Kristus; när han kommer, skall han förkunna oss allt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 26, 'Jesus svarade henne: »Jag, som talar med dig, är den du nu nämnde.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 27, 'I detsamma kommo hans lärjungar; och de förundrade sig över att han talade med en kvinna. Dock frågade ingen vad han ville henne, eller varför han talade med henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 28, 'Men kvinnan lät sin kruka stå och gick in i staden och sade till folket:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 29, '»Kommen och sen en man som har sagt mig allt vad jag har gjort. Månne icke han är Messias?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 30, 'Då gingo de ut ur staden och kommo till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 31, 'Under tiden bådo lärjungarna honom och sade: »Rabbi, tag och ät.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 32, 'Men han svarade dem: »Jag har mat att äta som I icke veten om.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 33, 'Då sade lärjungarna till varandra: »Kan väl någon hava burit mat till honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 34, 'Jesus sade till dem: »Min mat är att göra dens vilja, som har sänt mig, och att fullborda hans verk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 35, 'I sägen ju att det ännu är fyra månader innan skördetiden kommer. Men se, jag säger eder: Lyften upp edra ögon, och sen på fälten, huru de hava vitnat till skörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 36, 'Redan nu får den som skördar uppbära sin lön och samla in frukt till evigt liv; så kunna den som sår och den som skördar tillsammans glädja sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 37, 'Ty här sannas det ordet, att en är den som sår och en annan den som skördar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 38, 'Jag har sänt eder att skörda, där I icke haven arbetat. Andra hava arbetat, och I haven fått gå in i deras arbete[2].»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 39, 'Och många samariter från den staden kommo till tro på honom för kvinnans ords skull, då hon vittnade att han hade sagt henne allt vad hon hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 40, 'När sedan samariterna kommo till honom, både de honom att stanna kvar hos dem. Så stannade han där i två dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 41, 'Och långt flera kommo då till tro för hans egna ords skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 42, 'Och de sade till kvinnan: »Nu är det icke mer för dina ords skull som vi tro, ty vi hava nu själva hört honom, och vi veta nu att han i sanning är världens Frälsare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 43, 'Men efter de två dagarna gick han därifrån till Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 44, 'Ty Jesus vittnade själv att en profet icke är aktad i sitt eget fädernesland.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 45, 'När han nu kom till Galileen, togo galiléerna vänligt emot honom, eftersom de hade sett allt vad han hade gjort i Jerusalem vid högtiden. Också de hade nämligen varit där vid högtiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 46, 'Så kom han åter till Kana i Galileen, där han hade gjort vattnet till vin. I Kapernaum fanns då en man i konungens tjänst, vilkens son låg sjuk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 47, 'När han nu hörde att Jesus hade kommit från Judeen till Galileen, begav han sig åstad till honom och bad att han skulle komma ned och bota hans son; ty denne låg för döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 48, 'Då sade Jesus till honom: »Om I icke sen tecken och under, så tron I icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 49, 'Mannen sade till honom: »Herre, kom ned, förrän mitt barn dör.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 50, 'Jesus svarade honom: »Gå, din son får leva.» Då trodde mannen det ord som Jesus sade till honom, och gick.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 51, 'Och medan han ännu var på vägen hem, mötte honom hans tjänare och sade: »Din son kommer att leva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 52, 'Då frågade han dem vid vilken timme det hade blivit bättre med honom. De svarade honom: »I går vid den sjunde timmen lämnade febern honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 53, 'Då märkte fadern att det hade skett just den timme då Jesus sade till honom: »Din son får leva.» Och han kom till tro, så ock hela hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 54, 'Detta var nu åter ett tecken, det andra i ordningen som Jesus gjorde, sedan han hade kommit från Judeen till Galileen. [1] Grundtextens uttryck, som bokstavligen betyder levande vatten, har vanligen betydelsen friskt, rinnande vatten; kvinnan fattar uttrycket i den senare betydelsen. [2] Eller: Jag har sänt eder att skörda, där I icke haven arbetat. Andra hava arbetat, och deras arbete har kommit eder till godo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Därefter inföll en av judarnas högtider, och Jesus for upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Vid Fårporten i Jerusalem ligger en damm, på hebreiska kallad Betesda, och invid den finnas fem pelargångar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'I dessa lågo många sjuka, blinda, halta, förtvinade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Där fanns nu en man som hade varit sjuk i trettioåtta år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Då Jesus fick se denne, där han låg, och fick veta att han redan lång tid hade varit sjuk, sade han till honom: »Vill du bliva frisk?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Den sjuke svarade honom: »Herre, jag har ingen som hjälper mig ned i dammen, när vattnet har kommit i rörelse; och så stiger en annan ditned före mig, medan jag ännu är på väg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Jesus sade till honom: »Stå upp, tag din säng och gå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Och strax blev mannen frisk och tog sin säng och gick. Men det var sabbat den dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Därför sade judarna till mannen som hade blivit botad: »Det är sabbat; det är icke lovligt för dig att bära sängen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Men han svarade dem: »Den som gjorde mig frisk, han sade till mig: \'Tag din säng och gå.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Då frågade de honom: »Vem var den mannen som sade till dig att du skulle taga sin säng och gå?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Men mannen som hade blivit botad visste icke vem det var; ty Jesus hade dragit sig undan, eftersom mycket folk var där på platsen. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Sedan träffade Jesus honom i helgedomen och sade till honom: »Se, du har blivit frisk; synda icke härefter, på det att icke något värre må vederfaras dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 15, 'Mannen gick då bort och omtalade för judarna, att det var Jesus som hade gjort honom frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 16, 'Därför förföljde nu judarna Jesus[2], eftersom han gjorde sådant på sabbaten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 17, 'Men han svarade dem: »Min Fader verkar ännu alltjämt; så verkar ock jag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 18, 'Och därför stodo judarna ännu mer efter att döda honom, eftersom han icke allenast ville göra sabbaten om intet, utan ock kallade Gud sin Fader och gjorde sig själv lik Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 19, 'Då talade Jesus åter och sade till dem: »Sannerligen, sannerligen säger jag eder: Sonen kan icke göra något av sig själv, utan han gör allenast vad han ser Fadern göra; ty vad han gör, det gör likaledes ock Sonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 20, 'Ty Fadern älskar Sonen och låter honom se allt vad han själv gör; och större gärningar, än dessa äro, skall han låta honom se, så att I skolen förundra eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 21, 'Ty såsom Fadern uppväcker döda och gör dem levande, så gör ock Sonen levande vilka han vill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 22, 'Icke heller dömer Fadern någon, utan all dom har han överlåtit åt Sonen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 23, 'för att alla skola ära Sonen såsom de ära Faderns. Den som icke ärar Sonen, han ärar icke heller Fadern, som har sänt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 24, 'Sannerligen, sannerligen säger jag eder: Den som hör mina ord och tror honom som har sänt mig, han har evigt liv och kommer icke under någon dom, utan har övergått från döden till livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 25, 'Sannerligen säger jag eder: Den stund kommer, ja, den är redan inne, så de döda skola höra Guds Sons röst, och de som höra den skola bliva levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 26, 'Ty såsom Fadern har liv i sig själv, så har han ock givit åt Sonen att hava liv i sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 27, 'Och han har givit honom makt att hålla dom, eftersom han är Människoson.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 28, 'Förundren eder icke över detta. Ty den stund kommer, då alla som äro i gravarna skola höra hans röst');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 29, 'och gå ut ur dem: de som hava gjort vad gott är skola uppstå till liv, och de som hava gjort vad ont är skola uppstå till dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 30, 'Jag kan icke göra något av mig själv. Såsom jag hör, så dömer jag; och min dom är rättvis, ty jag söker icke min vilja, utan dens vilja, som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 31, 'Om jag själv vittnar om mig, så gäller icke mitt vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 32, 'Men det är en annan som vittnar om mig, och jag vet att hans vittnesbörd om mig är sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 33, 'I haven sänt bud till Johannes, och han har vittnat för sanningen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 34, 'Dock, det är icke av någon människa som jag tager emot vittnesbörd om mig; men jag säger detta, för att I skolen bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 35, 'Han var den brinnande, skinande lampan, och för en liten stund villen I fröjdas i dess ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 36, 'Men jag har ett vittnesbörd om mig, som är förmer än Johannes\' vittnesbörd: de gärningar som Fadern har givit mig att fullborda, just de gärningar som jag gör, de vittna om mig, att Fadern har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 37, 'Ja, Fadern, som har sänt mig, han har själv vittnat om mig. Hans röst haven I aldrig någonsin hört, ej heller haven I sett hans gestalt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 38, 'och hans ord haven I icke låtit förbliva i eder. Ty den han har sänt, honom tron I icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 39, 'I rannsaken skrifterna, därför att I menen eder i dem hava evigt liv; och det är dessa som vittna om mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 40, 'Men I viljen icke komma till mig för att få liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 41, 'Jag tager icke emot pris av människor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 42, 'men jag känner eder och vet att I icke haven Guds kärlek i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 43, 'Jag har kommit i min Faders namn, och I tagen icke emot mig; kommer en annan i sitt eget namn, honom skolen I nog mottaga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 44, 'Huru skullen I kunna tro, I som tagen emot pris av varandra och icke söken det pris som kommer från honom som allena är Gud?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 45, 'Menen icke att det är jag som skall anklaga eder hos Fadern. Den som anklagar eder är Moses, han till vilken I sätten edert hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 46, 'Trodden I Moses, så skullen I ju tro mig, ty om mig har han skrivit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 47, 'Men tron I icke hans skrifter, huru skolen I då kunna tro mina ord?» [2] och sökte att döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 1, 'Därefter for Jesus över Galileiska sjön, »Tiberias\' sjö».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 2, 'Och mycket folk följde efter honom, därför att de sågo de tecken som han gjorde med de sjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 3, 'Men Jesus gick upp på berget och satte sig där med sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 4, 'Och påsken, judarnas högtid, var nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 5, 'Då nu Jesus lyfte upp sina ögon och såg att mycket folk kom till honom, sade han till Filippus: »Varifrån skola vi köpa bröd, så att dessa få äta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 6, 'Men detta sade han för att sätta honom på prov, ty själv visste han vad han skulle göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 7, 'Filippus svarade honom: »Bröd för två hundra silverpenningar[1] vore icke nog för att var och en skulle få ett litet stycke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 8, 'Då sade till honom en annan av hans lärjungar, Andreas, Simon Petrus\' broder:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 9, '»Här är en gosse som har fem kornbröd och två fiskar; men vad förslår det för så många?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 10, 'Jesus sade: »Låten folket lägga sig här.» Och på det stället var mycket gräs. Då lägrade sig männen där, och deras antal var vid pass fem tusen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 11, 'Därefter tog Jesus bröden och tackade Gud och delade ut åt dem som hade lagt sig ned där, likaledes ock av fiskarna, så mycket de ville hava.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 12, 'Och när de voro mätta, sade han till sina lärjungar: »Samlen tillhopa de överblivna styckena, så att intet förfares.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 13, 'Då samlade de dem tillhopa och fyllde tolv korgar med stycken, som av de fem kornbröden hade blivit över efter dem som hade ätit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 14, 'Då nu människorna hade det tecken som han hade gjort, sade de: »Denne är förvisso Profeten som skulle komma i världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 15, 'När då Jesus märkte att de tänkte komma och med våld föra honom med sig och göra honom till konung, drog han sig åter undan till berget, helt allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 16, 'Men när det blev afton, gingo hans lärjungar ned till sjön');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 17, 'och stego i en båt för att fara över sjön till Kapernaum. Det hade då redan blivit mörkt, och Jesus hade ännu icke kommit till dem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 18, 'och sjön gick hög, ty det blåste hårt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 19, 'När de så hade rott vid pass tjugufem eller trettio stadier, fingo de se Jesus komma gående på sjön och nalkas båten. Då blevo de förskräckta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 20, 'Men han sade till dem: »Det är jag; varen icke förskräckta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 21, 'De ville då taga honom upp i båten; och strax var båten framme vid landet dit de foro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 22, 'Dagen därefter hände sig detta. Folket som stod kvar på andra sidan sjön hade lagt märke till att där icke fanns mer än en enda båt, och att Jesus icke hade stigit i den båten med sina lärjungar, utan att lärjungarna hade farit bort allena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 23, 'Andra båtar hade likväl kommit från Tiberias och lagt till nära det ställe där folket bespisades efter det att Herren hade uttalat tacksägelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 24, 'När alltså folket nu såg att Jesus icke var där, ej heller hans lärjungar, stego de själva i båtarna och foro till Kapernaum för att söka efter Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 25, 'Och då de funno honom där på andra sidan sjön, frågade de honom: »Rabbi, när kom du hit?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 26, 'Jesus svarade dem och sade: »Sannerligen, sannerligen säger jag eder: I söken mig icke därför att I haven sett tecken, utan därför att I fingen äta av bröden och bleven mätta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 27, 'Verken icke för att få den mat som förgås, utan för att få den mat som förbliver och har med sig evigt liv, den som Människosonen skall giva eder; ty honom har Fadern, Gud själv, låtit undfå sitt insegel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 28, 'Då sade de till honom: »Vad skola vi göra för att utföra Guds gärningar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 29, 'Jesus svarade och sade till dem: »Detta är Guds gärning, att I tron på den han har sänt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 30, 'De sade till honom: »Vad för tecken gör du då? Låt oss se något tecken, så att vi kunna tro dig. Vilken gärning utför du?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 31, 'Våra fäder fingo äta manna i öknen, såsom det är skrivet: \'Han gav dem bröd från himmelen att äta.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 32, 'Då svarade Jesus dem: »Sannerligen, sannerligen säger jag eder: Det är icke Moses som har givit eder brödet från himmelen, men det är min Fader som giver eder det rätta brödet från himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 33, 'Ty Guds bröd är det bröd som kommer ned från himmelen och giver världen liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 34, 'Då sade de till honom: »Herre, giv oss alltid det brödet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 35, 'Jesus svarade: »Jag är livets bröd. Den som kommer till mig, han skall aldrig hungra, och den som tror på mig, han skall aldrig törsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 36, 'Men det är såsom jag har sagt eder: fastän I haven sett mig, tron I dock icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 37, 'Allt vad min Fader giver mig, det kommer till mig; och den som kommer till mig, honom skall jag sannerligen icke kasta ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 38, 'Ty jag har kommit ned från himmelen, icke för att göra min vilja, utan för att göra dens vilja, som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 39, 'Och detta är dens vilja, som har sänt mig, att jag icke skall låta någon enda gå förlorad av dem som han har givit mig, utan att jag skall låta dem uppstå på den yttersta dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 40, 'Ja, detta är min Faders vilja, att var och en som ser Sonen och tror på honom, han skall hava evigt liv, och att jag skall låta honom uppstå på den yttersta dagen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 41, 'Då knorrade judarna över honom, därför att han hade sagt: »Jag är det bröd som har kommit ned från himmelen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 42, 'Och de sade: »Är denne icke Jesus, Josefs son, vilkens fader och moder vi känna? Huru kan han då säga: \'Jag har kommit ned från himmelen\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 43, 'Jesus svarade och sade till dem: »Knorren icke eder emellan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 44, 'Ingen kan komma till mig, om icke Fadern, som har sänt mig, drager honom; och jag skall låta honom uppstå på den yttersta dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 45, 'Det är skrivet hos profeterna: \'De skola alla hava fått lärdom av Gud.\' Var och en som har lyssnat till Fadern och lärt av honom, han kommer till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 46, 'Icke som om någon skulle hava sett Fadern, utom den som är från Gud; han har sett Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 47, 'Sannerligen, sannerligen säger jag eder: Den som tror, han har evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 48, 'Jag är livets bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 49, 'Edra fäder åto manna i öknen, och de dogo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 50, 'Men med det bröd som kommer ned från himmelen är det så, att om någon äter därav, så skall han icke dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 51, 'Jag är det levande brödet som har kommit ned från himmelen. Om någon äter av det brödet, så skall han leva till evig tid. Och det bröd som jag skall giva är mitt kött; och jag giver det, för att världen skall leva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 52, 'Då tvistade judarna med varandra och sade: »Huru skulle denne kunna giva oss sitt kött att äta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 53, 'Jesus sade då till dem: »Sannerligen, sannerligen säger jag eder: Om I icke äten Människosonens kött och dricken hans blod, så haven I icke liv i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 54, 'Den som äter mitt kött och dricker mitt blod, han har evigt liv, och jag skall låta honom uppstå på den yttersta dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 55, 'Ty mitt kött är sannskyldig mat, och mitt blod är sannskyldig dryck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 56, 'Den som äter mitt kött och dricker mitt blod, han förbliver i mig, och jag förbliver i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 57, 'Såsom Fadern, han som är den levande, har sänt mig, och såsom jag lever genom Fadern, så skall ock den som äter mig leva genom mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 58, 'Så är det med det bröd som har kommit ned från himmelen. Det är icke såsom det fäderna fingo äta, vilka sedan dogo; den som äter detta bröd, han skall leva till evig tid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 59, 'Detta sade han, när han undervisade i synagogan i Kapernaum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 60, 'Många av hans lärjungar, som hörde detta, sade då: »Detta är ett hårt tal; vem står ut med att höra på honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 61, 'Men Jesus visste inom sig att hans lärjungar knorrade över detta; och han sade till dem: »Är detta för eder en stötesten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 62, 'Vad skolen I då säga, om I fån se Människosonen uppstiga dit där han förut var? --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 63, 'Det är anden som gör levande; köttet är till intet gagneligt. De ord som jag har talat till eder äro ande och äro liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 64, 'Men bland eder finnas några som icke tro.» Jesus visste nämligen från begynnelsen vilka de voro som icke trodde, så ock vilken den var som skulle förråda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 65, 'Och han tillade: »Fördenskull har jag sagt eder att ingen kan komma till mig, om det icke bliver honom givet av Fadern.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 66, 'För detta tals skull drogo sig många av hans lärjungar tillbaka, så att de icke längre vandrade med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 67, 'Då sade Jesus till de tolv: »Icke viljen väl också I gå bort?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 68, 'Simon Petrus svarade honom: »Herre, till vem skulle vi gå? Du har det eviga livets ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 69, 'och vi tro och förstå att du är Guds helige.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 70, 'Jesus svarade dem: »Har icke jag själv utvalt eder, I tolv? Och likväl är en av eder en djävul.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 71, 'Detta sade han om Judas, Simon Iskariots son; ty det var denne som skulle förråda honom, och han var en av de tolv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 1, 'Därefter vandrade Jesus omkring i Galileen, ty i Judeen ville han icke vandra omkring, då nu judarna stodo efter att döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 2, 'Men judarnas lövhyddohögtid var nu nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 3, 'Då sade hans bröder till honom: »Begiv dig härifrån och gå till Judeen, så att också dina lärjungar få se de gärningar som du gör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 4, 'Ty ingen som vill vara känd bland människor utför sitt verk i hemlighet. Då du nu gör sådana gärningar, så träd öppet fram för världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 5, 'Det var nämligen så, att icke ens hans bröder trodde på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 6, 'Då sade Jesus till dem: »Min tid är ännu icke kommen, men för eder är tiden alltid läglig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 7, 'Världen kan icke hata eder, men mig hatar hon, eftersom jag vittnar om henne, att hennes gärningar äro onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 8, 'Gån I upp till högtiden; jag är icke stadd på väg upp till denna högtid, ty min tid är ännu icke fullbordad.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 9, 'Detta sade han till dem och stannade så kvar i Galileen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 10, 'Men när hans bröder hade gått upp till högtiden, då gick också han ditupp, dock icke öppet, utan likasom i hemlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 11, 'Och judarna sökte efter honom under högtiden och sade: »Var är han?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 12, 'Och bland folket talades i tysthet mycket om honom. Somliga sade: »Han är en rättsinnig man», men andra sade: »Nej, han förvillar folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 13, 'Dock talade ingen öppet om honom, av fruktan för judarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 14, 'Men när redan halva högtiden var förliden, gick Jesus upp i helgedomen och undervisade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 15, 'Då förundrade sig judarna och sade: »Varifrån har denne sin lärdom, han som icke har fått undervisning?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 16, 'Jesus svarade dem och sade: »Min lära är icke min, utan hans som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 17, 'Om någon vill göra hans vilja, så skall han förstå om denna lära är från Gud, eller om jag talar av mig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 18, 'Den som talar av sig själv, han söker sin egen ära; men den som söker dens ära, som har sänt honom, han är sannfärdig, och orättfärdighet finnes icke i honom. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 19, 'Har icke Moses givit eder lagen? Och likväl fullgör ingen av eder lagen. Varför stån I efter att döda mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 20, 'Folket svarade: »Du är besatt av en ond ande. Vem står efter att döda dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 21, 'Jesus svarade och sade till dem: »En gärning allenast gjorde jag, och alla förundren I eder över den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 22, 'Moses har givit eder omskärelsen -- icke som om den vore ifrån Moses, ty den är ifrån fäderna -- och så omskären I människor också på en sabbat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 23, 'Om nu en människa undfår omskärelsen på en sabbat, för att Moses\' lag icke skall göras om intet, huru kunnen I då vredgas på mig, därför att jag på en sabbat gjorde en människa hel och frisk?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 24, 'Dömen icke efter skenet, utan dömen en rätt dom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 25, 'Då sade några av folket i Jerusalem: »Är det icke denne som de stå efter att döda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 26, 'Och ändå får han tala fritt, utan att de säga något till honom. Hava då rådsherrarna verkligen blivit förvissade om att denne är Messias?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 27, 'Dock, denne känna vi, och vi veta varifrån han är; men när Messias kommer, känner ingen varifrån han är.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 28, 'Då sade Jesus med hög röst, där han undervisade i helgedomen: »Javäl, I kännen mig, och I veten varifrån jag är. Likväl har jag icke kommit av mig själv, men han som har sänt mig är en som verkligen har myndighet att sända, han som I icke kännen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 29, 'Men jag känner honom, ty från honom är jag kommen, och han har sänt mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 30, 'Då ville de gripa honom; dock kom ingen med sin hand vid honom, ty hans stund var ännu icke kommen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 31, 'Men många av folket trodde på honom, och de sade: »Icke skall väl Messias, när han kommer, göra flera tecken än denne har gjort?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 32, 'Sådant fingo fariséerna höra folket i tysthet tala om honom. Då sände översteprästerna och fariséerna ut rättstjänare för att gripa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 33, 'Men Jesus sade: »Ännu en liten tid är jag hos eder; sedan går jag bort till honom som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 34, 'I skolen då söka efter mig, men I skolen icke finna mig, och där jag är, dit kunnen I icke komma.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 35, 'Då sade judarna till varandra: »Vart tänker denne gå, eftersom vi icke skola kunna finna honom? Månne han tänker gå till dem som bo kringspridda bland grekerna? Tänker han då undervisa grekerna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 36, 'Vad betyder det ord som han sade: \'I skolen söka efter mig, men I skolen icke finna mig, och där jag är, dit kunnen I icke komma\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 37, 'På den sista dagen i högtiden, som ock var den förnämsta, stod Jesus där och ropade och sade: »Om någon törstar, så komme han till mig och dricke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 38, 'Den som tror på mig, av hans innersta skola strömmar av levande vatten[1] flyta fram, såsom skriften säger.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 39, 'Detta sade han om Anden, vilken de som trodde på honom skulle undfå; ty ande var då ännu icke given, eftersom Jesus ännu icke hade blivit förhärligad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 40, 'Några av folket, som hörde dessa ord, sade då: »Denne är förvisso Profeten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 41, 'Andra sade: »Han är Messias.» Andra åter sade: »Icke kommer väl Messias från Galileen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 42, 'Säger icke skriften att Messias skall komma av Davids säd och från den lilla staden Betlehem, där David bodde?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 43, 'Så uppstodo för hans skull stridiga meningar bland folket,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 44, 'och somliga av dem ville gripa honom; dock kom ingen med sin hand vid honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 45, 'När sedan rättstjänarna kommo tillbaka till översteprästerna och fariséerna, frågade dessa dem: »Varför haven I icke fört honom hit?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 46, 'Tjänarna svarade: »Aldrig har någon människa talat, som den mannen talar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 47, 'Då svarade fariséerna dem: »Haven nu också I blivit förvillade?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 48, 'Har då någon av rådsherrarna trott på honom? Eller någon av fariséerna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 49, 'Nej; men detta folk, som icke känner lagen, det är förbannat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 50, 'Då sade Nikodemus till dem, han som förut hade besökt honom[2], och som själv var en av dem:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 51, '»Icke dömer väl vår lag någon, utan att man först har förhört honom och utrönt vad han förehar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 52, 'De svarade och sade till honom: »Kanske också du är från Galileen? Rannsaka, så skall du finna att ingen profet kommer från Galileen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 53, '[Och de gingo hem, var och en till sitt. [1] Jämför noten till Joh 4,10. [2] om natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 1, 'Och Jesus gick ut till Oljeberget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 2, 'Men i dagbräckningen kom han åter till helgedomen[2].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 3, 'Då förde översteprästerna och fariséerna dit en kvinna som hade blivit beträdd med äktenskapsbrott; och när de hade lett henne fram,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 4, 'sade de till honom: »Mästare, denna kvinna har på bar gärning blivit beträdd med äktenskapsbrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 5, 'Nu bjuder Moses i lagen att sådana skola stenas. Vad säger då du?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 6, 'Detta sade de för att snärja honom, på det att de skulle få något att anklaga honom för. Då böjde Jesus sig ned och skrev med fingret på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 7, 'Men när de stodo fast vid sin fråga, reste han sig upp och sade till dem: »Den av eder som är utan synd, han kaste första stenen på henne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 8, 'Sedan böjde han sig åter ned och skrev på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 9, 'När de hörde detta[3], gingo de ut, den ene efter den andre, först de äldsta, och Jesus blev lämnad allena med kvinnan, som stod där kvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 10, 'Då såg Jesus upp och sade till kvinnan: »Var äro de andra? Har ingen dömt dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 11, 'Hon svarade: »Herre, ingen.» Då sade han till henne: »Icke heller jag dömer dig. Gå, och synda icke härefter.»][1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 12, 'Åter talade Jesus till dem och sade: »Jag är världens ljus; den som följer mig, han skall förvisso icke vandra i mörkret, utan skall hava livets ljus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 13, 'Då sade fariséerna till honom: »Du vittnar om dig själv; ditt vittnesbörd gäller icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 14, 'Jesus svarade och sade till dem: »Om jag än vittnar om mig själv, så gäller dock mitt vittnesbörd, ty jag vet varifrån jag har kommit, och vart jag går; men I veten icke varifrån jag kommer, eller vart jag går.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 15, 'I dömen efter köttet; jag dömer ingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 16, 'Och om jag än dömer, så är min dom en rätt dom, ty jag är därvid icke ensam, utan med mig är han som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 17, 'I eder lag är ju ock skrivet att vad två människor vittna, det gäller såsom sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 18, 'Här är nu jag som vittnar om mig; om mig vittnar också Fadern, som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 19, 'Då sade de till honom: »Var är då din Fader?» Jesus svarade: »I kännen varken mig eller min Fader. Om I känden mig, så känden I ock min Fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 20, 'Det var på det ställe där offerkistorna stodo som han talade dessa ord, medan han undervisade i helgedomen; men ingen bar hand på honom, ty hans stund var ännu icke kommen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 21, 'Åter sade han till dem: »Jag går bort, och I skolen då söka efter mig; men I skolen dö i eder synd. Dig jag går, dit kunnen I icke komma.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 22, 'Då sade judarna: »Icke vill han väl dräpa sig själv, eftersom han säger: \'Dit jag går, dit kunnen I icke komma\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 23, 'Men han svarade dem: »I ären härnedifrån, jag är ovanifrån; I ären av denna världen, jag är icke av denna världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 24, 'Därför sade jag till eder att I skullen dö i edra synder; ty om I icke tron att jag är den jag är, så skolen I dö i edra synder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 25, 'Då frågade de honom: »Vem är du då?» Jesus svarade dem: »Det som jag redan från begynnelsen har uttalat för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 26, 'Mycket har jag ännu att tala och att döma i fråga om eder. Men han som har sänt mig är sannfärdig, och vad jag har hört av honom, det talar jag ut inför världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 27, 'Men de förstodo icke att det var om Fadern som han talade till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 28, 'Då sade Jesus: »När I haven upphöjt Människosonen, då skolen I första att jag är den jag är, och att jag icke gör något av mig själv, utan talar detta såsom Fadern har lärt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 29, 'Och han som har sänt mig är med mig; han har icke lämnat mig allena, eftersom jag alltid gör vad honom behagar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 30, 'När han talade detta, kommo många till tro på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 31, 'Då sade Jesus till de judar som hade satt tro till honom: »Om I förbliven i mitt ord, så ären I i sanning mina lärjungar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 32, 'Och I skolen då förstå sanningen, och sanningen skall göra eder fria.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 33, 'De svarade honom: »Vi äro Abrahams säd och hava aldrig varit trälar under någon. Huru kan du då säga: \'I skolen bliva fria\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 34, 'Jesus svarade dem: »Sannerligen, sannerligen säger jag eder: Var och en som gör synd, han är syndens träl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 35, 'Men trälen får icke förbliva i huset för alltid; sonen får förbliva där för alltid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 36, 'Om nu Sonen gör eder fria, så bliven i verkligen fria.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 37, 'Jag vet att I ären Abrahams säd; men I stån efter att döda mig, eftersom mitt ord icke får någon ingång i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 38, 'Jag talar vad jag har sett hos min Fader; så gören ock I vad I haven hört av eder fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 39, 'De svarade och sade till honom: »Vår fader är ju Abraham.» Jesus svarade till dem: »Ären I Abrahams barn, så gören ock Abrahams gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 40, 'Men nu stån I efter att döda mig, en man som har sagt eder sanningen, såsom jag har hört den av Gud. Så handlade icke Abraham.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 41, 'Nej, I gören eder faders gärningar.» De sade till honom: »Vi äro icke födda i äktenskapsbrott. Vi hava Gud till fader och ingen annan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 42, 'Jesus svarade dem: »Vore Gud eder fader, så älskaden I ju mig, ty från Gud har jag utgått, och från honom är jag kommen. Ja, jag har icke kommit av mig själv, utan det är han som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 43, 'Varför fatten I då icke vad jag talar? Jo, därför att I icke \'stån ut med\' att höra på mitt ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 44, 'I haven djävulen till eder fader, och vad eder fader har begär till, det viljen i göra. Han har varit en mandråpare från begynnelsen, och i sanningen står han icke, ty sanning finnes icke i honom. När han talar lögn, då talar han av sitt eget, ty han är en lögnare, ja, lögnens fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 45, 'Men mig tron I icke, just därför att jag talar sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 46, 'Vilken av eder kan överbevisa mig om någon synd? Om jag alltså talar sanning, varför tron I mig då icke?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 47, 'Den som är av Gud, han lyssnar till Guds ord; och det är därför att I icke ären av Gud som I icke lyssnen därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 48, 'Judarna svarade och sade till honom: »Hava vi icke rätt, då vi säga att du är en samarit och är besatt av en ond ande?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 49, 'Jesus svarade: »Jag är icke besatt av någon ond ande; fastmer hedrar jag min Fader. I åter skymfen mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 50, 'Men jag söker icke min egen ära; en finnes dock som söker den och som dömer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 51, 'Sannerligen, sannerligen säger jag eder: Den som håller mitt ord, han skall aldrig någonsin se döden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 52, 'Judarna sade till honom: »Nu förstå vi att du är besatt av en ond ande. Abraham har dött, så ock profeterna, och likväl säger du: \'Den som håller mitt ord, han skall aldrig någonsin smaka döden.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 53, 'Icke är väl du förmer än vår Fader Abraham? Och han har ju dött. Profeterna hava också dött. Till vem gör du då dig själv?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 54, 'Jesus svarade: »Om jag själv ville skaffa mig ära, så vore min ära intet; men det är min Fader som förlänar mig ära, han som I säger vara eder Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 55, 'Dock, I haven icke lärt känna honom, men jag känner honom; och om jag sade att jag icke kände honom, så bleve jag en lögnare likasom I; men jag känner honom och håller hans ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 56, 'Abraham, eder fader, fröjdade sig över att han skulle få se min dag. Han fick se den och blev glad.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 57, 'Då sade judarna till honom: »Femtio år gammal är du icke ännu, och Abraham har du sett!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 58, 'Jesus sade till dem: »Sannerligen, sannerligen säger jag eder: Förrän Abraham blev till, är jag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 59, 'Då togo de upp stenar för att kasta på honom. Men Jesus gömde sig undan och gick sedan ut ur helgedomen. [1] 7,53--8,11; Se Nya testamentets text i Ordförkl. [2] och allt folket kom till honom, och han satte sig och lärde dem. [3] och kände sig överbevisade av samvetet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 1, 'När han nu gick vägen fram, fick han se en man som var född blind.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 2, 'Då frågade hans lärjungar honom och sade: »Rabbi, vilken har syndat, denne eller hans föräldrar, så att han har blivit född blind?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 3, 'Jesus svarade: »Det är varken denne som har syndat eller hans föräldrar, utan så har skett, för att Guds gärningar skulle uppenbaras på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 4, 'Medan dagen varar, måste vi göra dens gärningar, som har sänt mig; natten kommer, då ingen kan verka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 5, 'Så länge jag är i världen, är jag världens ljus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 6, 'När han hade sagt detta, spottade han på jorden och gjorde en deg av spotten och lade degen på mannens ögon');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 7, 'och sade till honom: »Gå bort och två dig i dammen Siloam» (det betyder utsänd). Mannen gick då dit och tvådde sig; och när han kom igen, kunde han se.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 8, 'Då sade grannarna och andra som förut hade sett honom såsom tiggare: »Är detta icke den man som att och tiggde?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 9, 'Somliga svarade: »Det är han.» Andra sade: »Nej, men han är lik honom.» Själv sade han: »Jag är den mannen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 10, 'Och de frågade honom: »Huru blevo då dina ögon öppnade?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 11, 'Han svarade: »Den man som heter Jesus gjorde en deg och smorde därmed mina ögon och sade till mig: \'Gå bort till Siloam och två dig.\' Jag gick då dit och tvådde mig, och så fick jag min syn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 12, 'De frågade honom: »Var är den mannen?» Han svarade: »Det vet jag icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 13, 'Då förde de honom, mannen som förut hade varit blind, bort till fariséerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 14, 'Och det var sabbat den dag då Jesus gjorde degen och öppnade hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 15, 'När nu jämväl fariséerna i sin ordning frågade honom huru han hade fått sin syn, svarade han dem: »Han lade en deg på mina ögon, och jag fick två mig, och nu kan jag se.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 16, 'Då sade några av fariséerna: »Den mannen är icke från Gud, eftersom han icke håller sabbaten.» Andra sade: »Huru skulle någon som är en syndare kunna göra sådana tecken?» Så funnos bland dem stridiga meningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 17, 'Då frågade de åter den blinde: »Vad säger du själv om honom, då det ju var dina ögon han öppnade?» Han svarade: »En profet är han.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 18, 'Men judarna trodde icke att han hade varit blind och fått sin syn, förrän de hade kallat till sig mannen föräldrar, hans som hade fått sin syn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 19, 'Dem frågade de och sade: »Är detta eder son, den som I sägen vara född blind? Huru kommer det då till, att han nu kan se?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 20, 'Då svarade han föräldrar och sade: »Att denne är vår son, och att han föddes blind, det veta vi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 21, 'Men huru han nu kan se, det veta vi icke, ej heller veta vi vem som har öppnat hans ögon. Frågen honom själv; han är gammal nog, han må själv tala för sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 22, 'Detta sade hans föräldrar, därför att de fruktade judarna; ty judarna hade redan kommit överens om att den som bekände Jesus vara Messias, han skulle utstötas ur synagogan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 23, 'Därför var det som hans föräldrar sade: »Han är gammal nog; frågen honom själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 24, 'Då kallade de för andra gången till sig mannen som hade varit blind och sade till honom: »Säg nu sanningen, Gud till pris. Vi veta att denne man är en syndare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 25, 'Han svarade: »Om han är en syndare vet jag icke; ett vet jag: att jag, som var blind, nu kan se.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 26, 'Då frågade de honom: »Vad gjorde han med dig? På vad sätt öppnade han dina ögon?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 27, 'Han svarade dem: »Jag har ju redan sagt eder det, men I hörden icke på mig. Varför viljen I då åter höra det? Kanske viljen också I bliva hans lärjungar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 28, 'Då bannade de honom och sade: »Du är själv hans lärjunge; vi äro Moses\' lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 29, 'Till Moses har Gud talat, det veta vi; men varifrån denne är, det veta vi icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 30, 'Mannen svarade och sade till dem: »Ja, däri ligger det förunderliga, att I icke veten varifrån han är, och ändå har han öppnat mina ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 31, 'Vi veta ju att Gud icke hör syndare, men också att om någon är gudfruktig och gör hans vilja, då hör han honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 32, 'Aldrig förut har man hört att någon har öppnat ögonen på en som föddes blind.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 33, 'Vore denne icke från Gud, så kunde han intet göra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 34, 'De svarade och sade till honom: »Du är hel och hållen född i synd, och du vill undervisa oss!» Och så drevo de ut honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 35, 'Jesus fick sedan höra att de hade drivit ut honom, och när han så träffade honom, sade han: »Tror du på Människosonen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 36, 'Han svarade och sade: »Herre, vem är han då? Säg mig det, så att jag kan tro på honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 37, 'Jesus sade till honom: »Du har sett honom; det är han som talar med dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 38, 'Då sade han: »Herre, jag tror.» Och han föll ned för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 39, 'Och Jesus sade: »Till en dom har jag kommit hit i världen, för att de som icke se skola varda seende, och för att de som se skola varda blinda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 40, 'När några fariséer som voro i hans närhet hörde detta, sade de till honom: »Äro då kanske också vi blinda?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 41, 'Jesus svarade dem: »Voren I blinda, så haden I icke synd. Men nu sägen I: \'Vi se\', därför står eder synd kvar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 1, '»Sannerligen, sannerligen säger jag eder: Den som icke går in i fårahuset genom dörren, utan stiger in någon annan väg, han är en tjuv och en rövare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 2, 'Men den som går in genom dörren, han är fårens herde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 3, 'För honom öppnar dörrvaktaren, och fåren lyssna till hans röst, och han kallar sina får vid namn och för dem ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 4, 'Och när han har släppt ut alla sina får, går han framför dem, och fåren följa honom, ty de känna hans röst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 5, 'Men en främmande följa de alls icke, utan fly bort ifrån honom, ty de känna icke de främmandes röst.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 6, 'Så talade Jesus till dem i förtäckta ord; men de förstodo icke vad det var som han talade till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 7, 'Åter sade Jesus till dem: »Sannerligen, sannerligen säger jag eder: Jag är dörren in till fåren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 8, 'Alla de som hava kommit före mig äro tjuvar och rövare, men fåren hava icke lyssnat till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 9, 'Jag är dörren; den som går in genom mig, han skall bliva frälst, och han skall få gå ut och in och skall finna bete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 10, 'Tjuven kommer allenast för att stjäla och slakta och förgöra. Jag har kommit, för att de skola hava liv och hava över nog.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 11, 'Jag är den gode herden. En god herde giver sitt liv för fåren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 12, 'Men den som är lejd och icke är herden själv, när han, den som fåren icke tillhöra, ser ulven komma, då övergiver han fåren och flyr, och ulven rövar bort dem och förskingrar dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 13, 'Han är ju lejd och frågar icke efter fåren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 14, 'Jag är den gode herden, och jag känner mina får, och mina får känna mig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 15, 'såsom Fadern känner mig, och såsom jag känner Fadern; och jag giver mitt liv för fåren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 16, 'Jag har ock andra får, som icke höra till detta fårahus; också dem måste jag draga till mig, och de skola lyssna till min röst. Så skall det bliva en hjord och en herde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 17, 'Därför älskar Fadern mig, att jag giver mitt liv -- för att sedan taga igen det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 18, 'Ingen tager det ifrån mig, utan jag giver det av fri vilja. Jag har makt att giva det, och jag har makt att taga igen det. Det budet har jag fått av min Fader.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 19, 'För dessa ords skull uppstodo åter stridiga meningar bland judarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 20, 'Många av dem sade: »Han är besatt av en ond ande och är från sina sinnen. Varför hören I på honom?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 21, 'Andra åter sade: »Sådana ord talar icke den som är besatt. Icke kan väl en ond ande öppna blindas ögon?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 22, 'Därefter inföll tempelinvigningens högtid i Jerusalem. Det var nu vinter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 23, 'och Jesus gick fram och åter i Salomos pelargång i helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 24, 'Då samlade sig judarna omkring honom och sade till honom: »Huru länge vill du hålla oss i ovisshet? Om du är Messias, så säg oss det öppet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 25, 'Jesus svarade dem: »Jag har sagt eder det, men I tron mig icke. De gärningar som jag gör i min Faders namn, de vittna om mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 26, 'Men I tron mig icke, ty I ären icke av mina får.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 27, 'Mina får lyssna till min röst, och jag känner dem, och de följa mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 28, 'Och jag giver dem evigt liv, och de skola aldrig någonsin förgås, och ingen skall rycka dem ur min hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 29, 'Min Fader, som har givit mig dem, är större än alla, och ingen kan rycka dem ur min Faders hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 30, 'Jag och Fadern äro ett.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 31, 'Då togo judarna åter upp stenar för att stena honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 32, 'Men Jesus sade till dem: »Många goda gärningar, som komma från min Fader, har jag låtit eder se. För vilken av dessa gärningar är det som I viljen stena mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 33, 'Judarna svarade honom: »Det är icke för någon god gärnings skull som vi vilja stena dig, utan därför att du hädar och gör dig själv till Gud, du som är en människa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 34, 'Jesus svarade dem: »Det är ju så skrivet i eder lag: \'Jag har sagt att I ären gudar\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 35, 'Om han nu har kallat för gudar dem som Guds ord kom till -- och skriften kan ju icke bliva om intet --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 36, 'huru kunnen då I, på den grund att jag har sagt mig vara Guds Son, anklaga mig för hädelse, mig som Fadern har helgat och sänt i världen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 37, 'Gör jag icke min Faders gärningar, så tron mig icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 38, 'Men gör jag dem, så tron gärningarna, om I än icke tron mig; då skolen I fatta och förstå att Fadern är i mig, och att jag är i Fadern.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 39, 'Då ville de åter gripa honom, men han gick sin väg, undan deras händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 40, 'Sedan begav han sig åter bort till det ställe på andra sidan Jordan, där Johannes först hade döpt, och stannade kvar där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 41, 'Och många kommo till honom. Och de sade: »Väl gjorde Johannes intet tecken, men allt vad Johannes sade om denne var sant.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 42, 'Och många kommo där till tro på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 1, 'Och en man vid namn Lasarus låg sjuk; han var från Betania, den by där Maria och hennes syster Marta bodde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 2, 'Det var den Maria som smorde Herren med smörjelse och torkade hans fötter med sitt hår. Och nu låg hennes broder Lasarus sjuk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 3, 'Då sände systrarna bud till Jesus och läto säga: »Herre, se, han som du har så kär ligger sjuk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 4, 'När Jesus hörde detta, sade han: »Den sjukdomen är icke till döds, utan till Guds förhärligande, så att Guds Son genom den bliver förhärligad.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 5, 'Och Jesus hade Marta och hennes syster och Lasarus kära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 6, 'När han nu hörde att denne låg sjuk, stannade han först två dagar där han var;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 7, 'men därefter sade han till lärjungarna: »Låt oss gå tillbaka till Judeen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 8, 'Lärjungarna sade till honom: »Rabbi, nyligen ville judarna stena dig, och åter går du dit?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 9, 'Jesus svarade: »Dagen har ju tolv timmar; den som vandrar om dagen, han stöter sig icke, ty han ser då denna världens ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 10, 'Men den som vandrar om natten, han stöter sig, ty han har då intet som lyser honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 11, 'Sedan han hade talat detta, sade han ytterligare till dem: »Lasarus, vår vän, har somnat in; men jag går för att väcka upp honom ur sömnen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 12, 'Då sade hans lärjungar till honom: »Herre, sover han, så bliver han frisk igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 13, 'Men Jesus hade talat om hans död; de åter menade att han talade om vanlig sömn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 14, 'Då sade Jesus öppet till dem: »Lasarus är död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 15, 'Och för eder skull, för att I skolen tro, gläder jag mig över att jag icke var där. Men låt oss nu gå till honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 16, 'Då sade Tomas, som kallades Didymus, till de andra lärjungarna: »Låt oss gå med, för att vi må dö med honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 17, 'När så Jesus kom dit, fann han att den döde redan hade legat fyra dagar i graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 18, 'Nu låg Betania nära Jerusalem, vid pass femton stadier därifrån,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 19, 'och många judar hade kommit till Marta och Maria för att trösta dem i sorgen över deras broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 20, 'Då nu Maria fick höra att Jesus kom, gick hon honom till mötes; men Maria satt kvar hemma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 21, 'Och Marta sade till Jesus: »Herre, hade du varit här, så vore min broder icke död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 22, 'Men jag vet ändå att allt vad du beder Gud om, det skall Gud giva dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 23, 'Jesus sade till henne: »Din broder skall stå upp igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 24, 'Marta svarade honom: »Jag vet att han skall stå upp, vid uppståndelsen på den yttersta dagen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 25, 'Jesus svarade till henne: »Jag är uppståndelsen och livet. Den som tror på mig, han skall leva, om han än dör;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 26, 'och var och en som lever och tror på mig, han skall aldrig någonsin dö. Tror du detta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 27, 'Hon svarade honom: »Ja, Herre, jag tror att du är Messias, Guds Son, han som skulle komma i världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 28, 'När hon hade sagt detta, gick hon bort och kallade på Maria, sin syster, och sade hemligen till henne: »Mästaren är här och kallar dig till sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 29, 'När hon hörde detta, stod hon strax upp och gick åstad till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 30, 'Men Jesus hade ännu icke kommit in i byn, utan var kvar på det ställe där Marta hade mött honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 31, 'Då nu de judar, som voro inne i huset hos Maria för att trösta henne, sågo att hon så hastigt stod upp och gick ut, följde de henne, i tanke att hon gick till graven för att gråta där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 32, 'När så Maria kom till det ställe där Jesus var och fick se honom, föll hon ned för hans fötter och sade till honom: »Herre, hade du varit där, så vore min broder icke död.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 33, 'Då nu Jesus såg henne gråta och såg jämväl att de judar, som hade kommit med henne, gräto, upptändes han i sin ande och blev upprörd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 34, 'och frågade: »Var haven I lagt honom?» De svarade honom: »Herre, kom och se.» Och Jesus grät.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 35, 'Då sade judarna: »Se huru kär han hade honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 36, 'Men somliga av dem sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 37, '»Kunde icke han, som öppnade den blindes ögon, ock hava så gjort att denne icke hade dött?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 38, 'Då upptändes Jesus åter i sitt innersta och gick bort till graven. Den var urholkad i berget, och en sten låg framför ingången.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 39, 'Jesus sade: »Tagen bort stenen.» Då sade den dödes syster Marta till honom: »Herre, han luktar redan, ty han har varit död i fyra dygn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 40, 'Jesus svarade henne: »Sade jag dig icke, att om du trodde, skulle du få se Guds härlighet?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 41, 'Då togo de bort stenen. Och Jesus lyfte upp sina ögon och sade: »Fader, jag tackar dig för att du har hört mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 42, 'Jag visste ju förut att du alltid hör mig; men för folkets skull, som står här omkring, säger jag detta, för att de skola tro att det är du som har sänt mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 43, 'När han hade sagt detta, ropade han med hög röst: »Lasarus, kom ut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 44, 'Och han som hade varit död kom ut, med händer och fötter inlindade i bindlar och med ansiktet inhöljt i en duk. Jesus sade till dem: »Lösen honom, och låten honom gå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 45, 'Många judar, som hade kommit till Maria och hade sett vad Jesus hade gjort, trodde då på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 46, 'Men några av dem gingo bort till fariséerna och omtalade för dem vad Jesus hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 47, 'Då sammankallade översteprästerna och fariséerna en rådsförsamling och sade: »Vad skola vi taga oss till? Denne man gör ju många tecken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 48, 'Om vi skola låta honom så fortfara, skola alla tro på honom, och romarna komma då att taga ifrån oss både land och folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 49, 'Men en av dem, Kaifas, som var överstepräst för det året, sade till dem: »I förstån intet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 50, 'och I besinnen icke huru mycket bättre det är för eder att en man dör för folket, än att hela folket förgås.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 51, 'Detta sade han icke av sig själv, utan genom profetisk ingivelse, eftersom han var överstepräst för det året; ty Jesus skulle dö för folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 52, 'Ja, icke allenast »för folket»; han skulle dö också för att samla och förena Guds förskingrade barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 53, 'Från den dagen var deras beslut fattat att döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 54, 'Så vandrade då Jesus icke längre öppet bland judarna, utan drog sig undan till en stad som hette Efraim, på landsbygden, i närheten av öknen; där stannade han kvar med sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 55, 'Men judarnas påsk var nära, och många begåvo sig då, före påsken, från landsbygden upp till Jerusalem för att helga sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 56, 'Och de sökte efter Jesus och sade till varandra, där de stodo i helgedom: »Vad menen I? Skall han då alls icke komma till högtiden?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 57, 'Och översteprästerna och fariséerna hade utfärdat påbud om att den som finge veta var han fanns skulle giva det till känna, för att de måtte kunna gripa honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 1, 'Sex dagar före påsk kom nu Jesus till Betania, där Lasarus bodde, han som av Jesus hade blivit uppväckt från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 2, 'Där gjorde man då för honom ett gästabud, och Marta betjänade dem, men Lasarus var en av dem som lågo till bords jämte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 3, 'Då tog Maria ett skålpund smörjelse av dyrbar äkta nardus och smorde därmed Jesu fötter; sedan torkade hon hans fötter med sitt hår. Och huset uppfylldes med vällukt av smörjelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 4, 'Men Judas Iskariot, en av hans lärjungar, den som skulle förråda honom, sade då:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 5, '»Varför sålde man icke hellre denna smörjelse för tre hundra silverpenningar[1] och gav dessa åt de fattiga?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 6, 'Detta sade han, icke därför, att han frågade efter de fattiga, utan därför, att han var en tjuv och plägade taga vad som lades i penningpungen, vilken han hade om hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 7, 'Men Jesus sade: »Låt henne vara; må hon få fullgöra detta för min begravningsdag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 8, 'De fattiga haven I ju alltid ibland eder, men mig haven I icke alltid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 9, 'Nu hade det blivit känt för den stora hopen av judarna att Jesus var där, och de kommo dit, icke allenast för hans skull, utan ock för att se Lasarus, som han hade uppväckt från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 10, 'Då beslöto översteprästerna att döda också Lasarus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 11, 'Ty för hans skull gingo många judar bort och trodde på Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 12, 'När dagen därefter det myckna folk som hade kommit till högtiden fick höra att Jesus var på väg till Jerusalem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 13, 'togo de palmkvistar och gingo ut för att möta honom och ropade: »Hosianna! Välsignad vare han som kommer[2], i Herrens namn, han som är Israels konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 14, 'Och Jesus fick sig en åsnefåle och satte sig upp på den, såsom det är skrivet:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 15, '»Frukta icke, du dotter Sion. Se, din konung kommer, sittande på en åsninnas fåle.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 16, 'Detta förstodo hans lärjungar icke då strax, men när Jesus hade blivit förhärligad, då kommo de ihåg att detta var skrivet om honom, och att man hade gjort detta med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 17, 'Så gav nu folket honom sitt vittnesbörd, de som hade varit med honom, när han kallade Lasarus ut ur graven och uppväckte honom från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 18, 'Därför kom också det övriga folket emot honom, eftersom de hörde att han hade gjort det tecknet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 19, 'Då sade fariséerna till varandra: »I sen att I alls intet kunnen uträtta; hela världen löper ju efter honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 20, 'Nu voro där ock några greker, av dem som plägade fara upp för att tillbedja under högtiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 21, 'Dessa kommo till Filippus, som var från Betsaida i Galileen, och bådo honom och sade: »Herre, vi skulle vilja se Jesus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 22, 'Filippus gick och sade detta till Andreas; Andreas och Filippus gingo och sade det till Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 23, 'Jesus svarade dem och sade: »Stunden är kommen att Människosonen skall förhärligas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 24, 'Sannerligen, sannerligen säger jag eder: Om icke vetekornet faller i jorden och dör, så förbliver det ett ensamt korn; men om det dör, så bär det mycken frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 25, 'Den som älskar sitt liv, han mister det, men den som hatar sitt liv i denna världen, han skall behålla det och skall hava evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 26, 'Om någon vill tjäna mig, så följe han mig; och där jag är, där skall också min tjänare få vara. Om någon tjänar mig, så skall min Fader ära honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 27, 'Nu är min själ i ångest; vad skall jag väl säga? Fader, fräls mig undan denna stund. Dock, just därför har jag kommit till denna stund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 28, 'Fader, förhärliga ditt namn.» Då kom en röst från himmelen: »Jag har redan förhärligat det, och jag skall ytterligare förhärliga det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 29, 'Folket, som stod där och hörde detta, sade då: »Det var ett tordön.» Andra sade: »Det var en ängel som talade med honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 30, 'Då svarade Jesus och sade: »Denna röst kom icke för min skull, utan för eder skull.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 31, 'Nu går en dom över denna världen, nu skall denna världens furste utkastas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 32, 'Och när jag har blivit upphöjd från jorden, skall jag draga alla till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 33, 'Med dessa ord gav han till känna på vad sätt han skulle dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 34, 'Då svarade folket honom: »Vi hava hört av lagen att Messias skall stanna kvar för alltid. Huru kan du då säga att Människosonen måste bliva upphöjd? Vad är väl detta för en Människoson?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 35, 'Jesus sade till dem: »Ännu en liten tid är ljuset ibland eder. Vandren medan I haven ljuset, på det att mörkret icke må få makt med eder; den som vandrar i mörkret, han vet ju icke var han går.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 36, 'Tron på ljuset, medan I haven ljuset, så att I bliven ljusets barn.» Detta talade Jesus och gick sedan bort och dolde sig för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 37, 'Men fastän han hade gjort så många tecken inför dem, trodde de icke på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 38, 'Ty det ordet skulle fullbordas, som profeten Esaias säger: »Herre, vem trodde, vad som predikades för oss, och för vem var Herrens arm uppenbar?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 39, 'Alltså kunde de icke tro; Esaias säger ju ytterligare:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 40, '»Han har förblindat deras ögon och förstockat deras hjärtan, så att de icke kunna se med sina ögon eller förstå med sina hjärtan och omvända sig och bliva helade av mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 41, 'Detta kunde Esaias säga, eftersom han hade sett hans härlighet, när han talade med honom. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 42, 'Dock funnos jämväl bland rådsherrarna många som trodde på honom; men för fariséernas skulle ville de icke bekänna det, för att de icke skulle bliva utstötta ur synagogan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 43, 'Ty de skattade högre att bliva ärade av människor än att bliva ärade av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 44, 'Men Jesus sade med hög röst: »Den som tror på mig, han tror icke på mig, utan på honom som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 45, 'Och den som ser mig, han ser honom som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 46, 'Såsom ett ljus har jag kommit i världen, för att ingen av dem som tro på mig skall förbliva i mörkret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 47, 'Om någon hör mina ord, men icke håller dem, så dömer icke jag honom; ty jag har icke kommit för att döma världen, utan för att frälsa världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 48, 'Den som förkastar mig och icke tager emot mina ord, han har dock en domare över sig; det ord som jag har talat, det skall döma honom på den yttersta dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 49, 'Ty jag har icke talat av mig själv, utan Fadern, som har sänt mig, han har bjudit mig vad jag skall säga, och vad jag skall tala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 50, 'Och jag vet att hans bud är evigt liv; därför, vad jag talar, det talar jag såsom Fadern har sagt mig.» [1] Se Silverpenning i Ordförkl. [2] Se Messias i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 1, 'Före påskhögtiden hände sig detta. Jesus visste att stunden var kommen för honom att gå bort ifrån denna världen till Fadern; och såsom han allt hittills hade älskat sina egna här i världen, så gav han dem nu ett yttersta bevis på sin kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 2, 'De höllo nu aftonmåltid, och djävulen hade redan ingivit Judas Iskariot, Simons son, i hjärtat att förråda Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 3, 'Och Jesus visste att Fadern hade givit allt i hans händer, och att han hade gått ut från Gud och skulle gå till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 4, 'Men han stod upp från måltiden och lade av sig överklädnaden och tog en linneduk och band den om sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 5, 'Sedan slog han vatten i ett bäcken och begynte två lärjungarnas fötter och torkade dem med linneduken som han hade bundit om sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 6, 'Så kom han till Simon Petrus. Denne sade då till honom: »Herre, skulle du två mina fötter?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 7, 'Jesus svarade och sade till honom: »Vad jag gör förstår du icke nu, men framdeles skall du fatta det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 8, 'Petrus sade till honom: »Aldrig någonsin skall du två mina fötter!» Jesus svarade honom: »Om jag icke tvår dig, så har du ingen del med mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 9, 'Då sade Simon Petrus till honom: »Herre, icke allenast mina fötter, utan ock händer och huvud!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 10, 'Jesus svarade honom: »Den som är helt tvagen, han behöver allenast två fötterna; han är ju i övrigt hel och hållen ren. Så ären ock I rena -- dock icke alla.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 11, 'Han visste nämligen vem det var som skulle förråda honom; därför sade han att de icke alla voro rena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 12, 'Sedan han nu hade tvagit deras fötter och tagit på sig överklädnaden och åter lagt sig ned vid bordet, sade han till dem: »Förstån I vad jag har gjort med eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 13, 'I kallen mig \'Mästare\' och \'Herre\', och I säger rätt, ty jag är så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 14, 'Har nu jag, eder Herre och Mästare, tvagit edra fötter, så ären ock I pliktiga att två varandras fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 15, 'Jag har ju givit eder ett föredöme, för att I skolen göra såsom jag har gjort mot eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 16, 'Sannerligen, sannerligen säger jag eder: Tjänaren är icke förmer än sin herre, ej heller sändebudet förmer än den som har sänt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 17, 'Då I veten detta, saliga ären I, om I ock gören det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 18, 'Jag talar icke om eder alla; jag vet vilka jag har utvalt. Men detta skriftens ord skulle ju fullbordas: \'Den som åt mitt bröd, han lyfte mot mig sin häl.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 19, 'Redan nu, förrän det sker, säger jag eder det, för att I, när det har skett, skolen tro att jag är den jag är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 20, 'Sannerligen, sannerligen säger jag eder: Den som tager emot den jag sänder, han tager emot mig; och den som tager emot mig, han tager emot honom som har sänt mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 21, 'När Jesus hade sagt detta, blev han upprörd i sin ande och betygade och sade: »Sannerligen, sannerligen säger jag eder: En av eder skall förråda mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 22, 'Då sågo lärjungarna på varandra och undrade vilken han talade om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 23, 'Nu var där bland lärjungarna en som låg till bords invid Jesu bröst, den lärjunge som Jesus älskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 24, 'Åt denne gav då Simon Petrus ett tecken och sade till honom: »Säg vilken det är som han talar om.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 25, 'Han lutade sig då mot Jesu bröst och frågade honom: »Herre, vilken är det?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 26, 'Då svarade Jesus: »Det är den åt vilken jag räcker brödstycket som jag nu doppar.» Därvid doppade han brödstycket och räckte det åt Judas, Simon Iskariots son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 27, 'Då, när denne hade tagit emot brödstycket, for Satan in i honom. Och Jesus sade till honom: »Gör snart vad du gör.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 28, 'Men ingen av dem som lågo där till bords förstod varför han sade detta till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 29, 'Ty eftersom Judas hade penningpungen om hand, menade några att Jesus hade velat säga till honom: »Köp vad vi behöva till högtiden», eller ock att han hade tillsagt honom att giva något åt de fattiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 30, 'Då han nu hade tagit emot brödstycket, gick han strax ut; och det var natt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 31, 'Och när han hade gått ut, sade Jesus: »Nu är Människosonen förhärligad, och Gud är förhärligad i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 32, 'Är nu Gud förhärligad i honom, så skall ock Gud förhärliga honom i sig själv, och han skall snart förhärliga honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 33, 'Kära barn, allenast en liten tid är jag ännu hos eder; I skolen sedan söka efter mig, men det som jag sade till judarna: \'Dit jag går, dit kunnen I icke komma\', detsamma säger jag nu ock till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 34, 'Ett nytt bud giver jag eder, att I skolen älska varandra; ja, såsom jag har älskat eder, så skolen ock I älska varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 35, 'Om I haven kärlek inbördes, så skola alla därav förstå att I ären mina lärjungar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 36, 'Då frågade Simon Petrus honom: »Herre, vart går du?» Jesus svarade: »Dit jag går, dit kan du icke nu följa mig; men framdeles skall du följa mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 37, 'Petrus sade till honom: »Herre, varför kan jag icke följa dig nu? Mitt liv vill jag giva för dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 38, 'Jesus svarade: »Ditt liv vill du giva för mig? Sannerligen, sannerligen säger jag dig: Hanen skall icke gala, förrän du tre gånger har förnekat mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 1, '»Edra hjärtan vare icke oroliga. Tron på Gud; tron ock på mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 2, 'I min Faders hus äro många boningar; om så icke voro, skulle jag nu säga eder att jag går bort för att bereda eder rum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 3, 'Och om jag än går bort för att bereda eder rum, så skall jag dock komma igen och taga eder till mig; ty jag vill att där jag är, där skolen I ock vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 4, 'Och vägen som leder dit jag går, den veten I.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 5, 'Tomas sade till honom: »Herre, vi veta icke vart du går; huru kunna vi då veta vägen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 6, 'Jesus svarade honom: »Jag är vägen och sanningen och livet; ingen kommer till Fadern utom genom mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 7, 'Haden I känt mig, så haden I ock känt min Fader; nu kännen I honom och haven sett honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 8, 'Filippus sade till honom: »Herre, låt oss se Fadern, så hava vi nog.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 9, 'Jesus svarade honom: »Så lång tid har jag varit hos eder, och du har icke lärt känna mig, Filippus? Den som har sett mig, han har sett Fadern. Huru kan du då säga: \'Låt oss se Fadern\'?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 10, 'Tror du icke att jag är i Fadern, och att Fadern är i mig? De ord jag talar till eder talar jag icke av mig själv. Och gärningarna, dem gör Fadern, som bor i mig; de äro hans verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 11, 'Tron mig; jag är i Fadern, och Fadern i mig. Varom icke, så tron för själva gärningarnas skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 12, 'Sannerligen, sannerligen säger jag eder: Den som tror på mig, han skall ock själv göra de gärningar som jag gör; och ännu större än dessa skall han göra. Ty jag går till Fadern,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 13, 'och vadhelst I bedjen om i mitt namn, det skall jag göra, på det att Fadern må bliva förhärligad i Sonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 14, 'Ja, om I bedjen om något i mitt namn, så skall jag göra det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 15, 'Älsken I mig, så hållen I mina bud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 16, 'och jag skall bedja Fadern, och han skall giva eder en annan Hjälpare, som för alltid skall vara hos eder:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 17, 'sanningens Ande, som världen icke kan taga emot, ty hon ser honom icke och känner honom icke. Men I kännen honom, ty han bor hos eder och skall vara i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 18, 'Jag skall icke lämna eder faderlösa; jag skall komma till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 19, 'Ännu en liten tid, och världen ser mig icke mer, men I sen mig. Ty jag lever; I skolen ock leva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 20, 'På den dagen skolen I förstå att jag är i min Fader, och att I ären i mig, och att jag är i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 21, 'Den som har mina bud och håller dem, han är den som älskar mig; och den som älskar mig, han skall bliva älskad av min Fader, och jag skall älska honom och jag skall uppenbara mig för honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 22, 'Judas -- icke han som kallades Iskariot -- sade då till honom: »Herre, varav kommer det att du tänker uppenbara dig för oss, men icke för världen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 23, 'Jesus svarade och sade till honom: »Om någon älskar mig, så håller han mitt ord; och min Fader skall älska honom, och vi skola komma till honom och taga vår boning hos honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 24, 'Den som icke älskar mig, han håller icke mina ord; och likväl är det ord som I hören icke mitt, utan Faderns, som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 25, 'Detta har jag talat till eder, medan jag ännu är kvar hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 26, 'Men Hjälparen, den helige Ande, som Fadern skall sända i mitt namn, han skall lära eder allt och påminna eder om allt vad jag har sagt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 27, 'Frid lämnar jag efter mig åt eder, min frid giver jag eder; icke giver jag eder den såsom världen giver. Edra hjärtan vare icke oroliga eller försagda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 28, 'I hörden att jag sade till eder: \'Jag går bort, men jag kommer åter till eder.\' Om I älskaden mig, så skullen I ju glädjas över att jag går bort till Fadern, ty Fadern är större än jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 29, 'Och nu har jag sagt eder det, förrän det sker, på det att I mån tro, när det har skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 30, 'Härefter talar jag icke mycket med eder, ty denna världens furste kommer. I mig finnes intet som hör honom till;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 31, 'men detta sker, för att världen skall förstå att jag älskar Fadern och gör såsom Fadern har bjudit mig. Stån upp, låt oss gå härifrån.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 1, '»Jag är det sanna vinträdet, och min Fader är vingårdsmannen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 2, 'Var gren i mig, som icke bär frukt, den tager han bort; och var och en som bär frukt, den rensar han, för att den skall bära mer frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 3, 'I ären redan nu rena, i kraft av det ord som jag har talat till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 4, 'Förbliven i mig, så förbliver ock jag i eder. Såsom grenen icke kan bära frukt av sig själv, utan allenast om den förbliver i vinträdet, så kunnen I det ej heller, om I icke förbliven i mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 5, 'Jag är vinträdet, I ären grenarna. Om någon förbliver i mig, och jag i honom, så bär han mycken frukt; ty mig förutan kunnen I intet göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 6, 'Om någon icke förbliver i mig, så kastas han ut såsom en avbruten gren och förtorkas; och man samlar tillhopa sådana grenar och kastar dem i elden, och de brännas upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 7, 'Om I förbliven i mig, och mina ord förbliva i eder, så mån I bedja om vadhelst I viljen, och det skall vederfaras eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 8, 'Därigenom bliver min Fader förhärligad, att i bären mycken frukt och bliven mina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 9, 'Såsom Fadern har älskat mig, så har ock jag älskat eder; förbliven i min kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 10, 'Om I hållen mina bud, så förbliven I i min kärlek, likasom jag har hållit min Faders bud och förbliver i hans kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 11, 'Detta har jag talat till eder, för att min glädje skall bo i eder, och för att eder glädje skall bliva fullkomlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 12, 'Detta är mitt bud, att I skolen älska varandra, såsom jag har älskat eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 13, 'Ingen har större kärlek, än att han giver sitt liv för sina vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 14, 'I ären mina vänner, om I gören vad jag bjuder eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 15, 'Jag kallar eder nu icke längre tjänare, ty tjänaren får icke veta vad hans herre gör; vänner kallar jag eder, ty allt vad jag har hört av min Fader har jag kungjort för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 16, 'I haven icke utvalt mig, utan jag har utvalt eder; och jag har bestämt om eder att I skolen gå åstad och bära frukt, sådan frukt som bliver beståndande, på det att Fadern må giva eder vadhelst I bedjen honom om i mitt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 17, 'Ja, det bjuder jag eder, att I skolen älska varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 18, 'Om världen hatar eder, så betänken att hon har hatat mig förr än eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 19, 'Voren I av världen, så älskade ju världen vad henne tillhörde; men eftersom I icke ären av världen, utan av mig haven blivit utvalda och tagna ut ur världen, därför hatar världen eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 20, 'Kommen ihåg det ord som jag sade till eder: \'Tjänaren är icke förmer än sin herre.\' Hava de förföljt mig, så skola de ock förfölja eder; hava de hållit mitt ord, så skola de ock hålla edert.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 21, 'Men allt detta skola de göra mot eder för mitt namns skull, eftersom de icke känna honom som har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 22, 'Hade jag icke kommit och talat till dem, så skulle de icke hava haft synd; men nu hava de ingen ursäkt för sin synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 23, 'Den som hatar mig, han hatar ock min Fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 24, 'Hade jag icke bland dem gjort sådana gärningar, som ingen annan har gjort, så skulle de icke hava haft synd; men nu hava de sett dem, och hava likväl hatat både mig och min Fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 25, 'Men det ordet skulle ju fullbordas, som är skrivet i deras lag: \'De hava hatat mig utan sak.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 26, 'Dock, när Hjälparen kommer, som jag skall sända eder ifrån Fadern, sanningens Ande, som utgår ifrån Fadern, då skall han vittna om mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 27, 'Också I kunnen vittna, eftersom I haven varit med mig från begynnelsen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 1, '»Detta har jag talat till eder, för att I icke skolen komma på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 2, 'Man skall utstöta eder ur synagogorna; ja, den tid kommer, då vemhelst som dräper eder skall mena sig därmed förrätta offertjänst åt Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 3, 'Och så skola de göra, därför att de icke hava lärt känna Fadern, ej heller mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 4, 'Men detta har jag talat till eder, för att I, när den tiden är inne, skolen komma ihåg att jag har sagt eder det. Jag sade eder det icke från begynnelsen, ty jag var ju hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 5, 'Och nu går jag bort till honom som har sänt mig; och ingen av eder frågar mig vart jag går.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 6, 'Men edra hjärtan äro uppfyllda av bedrövelse, därför att jag har sagt eder detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 7, 'Dock säger jag eder sanningen: Det är nyttigt för eder att jag går bort, ty om jag icke ginge bort, så komme icke Hjälparen till eder; men då jag nu går bort, skall jag sända honom till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 8, 'Och när han kommer, skall han låta världen få veta sanningen i fråga om synd och rättfärdighet och dom:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 9, 'i fråga om synd, ty de tro icke på mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 10, 'i fråga om rättfärdighet, ty jag går till Fadern, och I sen mig icke mer;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 11, 'i fråga om dom, ty denna världens furste är nu dömd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 12, 'Jag hade ännu mycket att säga eder, men I kunnen icke nu bära det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 13, 'Men när han kommer, som är sanningens Ande, då skall han leda eder fram till hela sanningen. Ty han skall icke tala av sig själv, utan vad han hör, allt det skall han tala; och han skall förkunna för eder vad komma skall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 14, 'Han skall förhärliga mig, ty av mitt skall han taga och skall förkunna det för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 15, 'Allt vad Fadern har, det är mitt; därför sade jag att han skall taga av mitt och förkunna det för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 16, 'En liten tid, och I sen mig icke mer; och åter en liten tid, och I fån se mig[1].»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 17, 'Då sade några av hans lärjungar till varandra: »Vad är detta som han säger till oss: \'En liten tid, och I sen mig icke; och åter en liten tid, och I fån se mig\', så ock: \'Jag går till Fadern\'?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 18, 'De sade alltså: »Vad är detta som han säger: \'En liten tid\'? Vi förstå icke vad han talar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 19, 'Då märkte Jesus att de ville fråga honom, och han sade till dem: »I talen med varandra om detta som jag sade: \'En liten tid, och I sen mig icke; och åter en liten tid, och I fån se mig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 20, 'Sannerligen, sannerligen säger jag eder: I skolen bliva bedrövade, men eder bedrövelse skall vändas i glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 21, 'När en kvinna föder barn, har hon bedrövelse, ty hennes stund är kommen; men när hon har fött barnet, kommer hon icke mer ihåg sin vedermöda, ty hon gläder sig över att en människa är född till världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 22, 'Så haven ock I nu bedrövelse; men jag skall se eder åter, och då skola edra hjärtan glädja sig, och ingen skall taga eder glädje ifrån eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 23, 'Och på den dagen skolen I icke fråga mig om något. Sannerligen, sannerligen säger jag eder: Vad I bedjen Fadern om, det skall han giva eder i mitt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 24, 'Hittills haven I icke bett om något i mitt namn; bedjen, och I skolen få, för att eder glädje skall bliva fullkomlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 25, 'Detta har jag talat till eder i förtäckta ord; den tid kommer, då jag icke mer skall tala till eder i förtäckta ord, utan öppet förkunna för eder om Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 26, 'På den dagen skolen I bedja i mitt namn. Och jag säger eder icke att jag skall bedja Fadern för eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 27, 'ty Fadern själv älskar eder, eftersom I haven älskat mig och haven trott att jag är utgången från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 28, 'Ja, jag har gått ut ifrån Fadern och har kommit i världen; åter lämnar jag världen och går till Fadern.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 29, 'Då sade hans lärjungar: »Se, nu talar du öppet och brukar inga förtäckta ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 30, 'Nu veta vi att du vet allt, och att det icke är behövligt för dig att man frågar dig; därför tro vi att du är utgången från Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 31, 'Jesus svarade dem: »Nu tron I?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 32, 'Se, den stund kommer, ja, den är redan kommen, så I skolen förskingras, var och en åt sitt håll, och lämna mig allena. Dock, jag är icke allena, ty Fadern är med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 33, 'Detta har jag talat till eder, för att I skolen hava frid i mig. I världen liden i betryck; men varen vid gott mod, jag har övervunnit världen.» [1] ty jag går till Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 1, 'Sedan Jesus hade talat detta, lyfte han upp sina ögon mot himmelen och sade: »Fader, stunden är kommen; förhärliga din Son, på det att din Son må förhärliga dig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 2, 'eftersom du har givit honom makt över allt kött, för att han skall giva evigt liv åt alla dem som du har givit åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 3, 'Och detta är evigt liv, att de känna dig, den enda sanne Guden, och den du har sänt, Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 4, 'Jag har förhärligat dig på jorden, genom att fullborda det verk som du har givit mig att utföra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 5, 'Och nu, Fader, förhärliga du mig hos dig själv, med den härlighet som jag hade hos dig, förrän världen var till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 6, 'Jag har uppenbarat ditt namn för de människor som du har tagit ut ur världen och givit åt mig. De voro dina, och du har givit dem åt mig, och de hava hållit ditt ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 7, 'Nu hava de förstått att allt vad du har givit åt mig, det kommer från dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 8, 'Ty de ord som du har givit åt mig har jag givit åt dem: och de hava tagit emot dem och hava i sanning förstått att jag är utgången från dig, och de tro att du har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 9, 'Jag beder för dem; det är icke för världen jag beder, utan för dem som du har givit åt mig, ty de äro dina');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 10, '-- såsom allt mitt är ditt, och ditt är mitt -- och jag är förhärligad i dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 11, 'Jag är nu icke längre kvar i världen, men de äro kvar i världen, när jag går till dig. Helige Fader, bevara dem i ditt namn -- det som du har förtrott åt mig -- för att de må vara ett, likasom vi äro ett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 12, 'Medan jag var hos dem, bevarade jag dem i ditt namn, det som du har förtrott åt mig; jag vakade över dem, och ingen av dem gick i fördärvet, ingen utom fördärvets man, ty skriften skulle ju fullbordas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 13, 'Nu går jag till tid; dock talar jag detta, medan jag ännu är här i världen, för att de skola hava min glädje fullkomlig i sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 14, 'Jag har givit dem ditt ord; och världen har hatat dem, eftersom de icke äro av världen, likasom icke heller jag är av världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 15, 'Jag beder icke att du skall taga dem bort ur världen, utan att du skall bevara dem från det onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 16, 'De äro icke av världen, likasom icke heller jag är av världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 17, 'Helga dem i sanningen; ditt ord är sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 18, 'Såsom du har sänt mig i världen, så har ock jag sänt dem i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 19, 'Och jag helgar mig till ett offer för dem, på det att ock de må vara i sanning helgade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 20, 'Men icke för dessa allenast beder jag, utan ock för dem som genom deras ord komma till tro på mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 21, 'jag beder att de alla må vara ett, och att, såsom du, Fader, är i mig, och jag i dig, också de må vara i oss, för att världen skall tro att du har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 22, 'Och den härlighet som du har givit mig, den har jag givit åt dem, för att de skola vara ett, såsom vi äro ett');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 23, '-- jag i dem, och du i mig -- ja, för att de skola vara fullkomligt förenade till ett, så att världen kan förstå att du har sänt mig, och att du har älskat dem, såsom du har älskat mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 24, 'Fader, jag vill att där jag är, där skola ock de som du har givit mig vara med mig, så att de få se min härlighet, som du har givit mig; ty du har älskat mig före världens begynnelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 25, 'Rättfärdige Fader, världen har icke lärt känna dig, men jag känner dig, och dessa hava förstått att du har sänt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 26, 'Och jag har kungjort för dem ditt namn och skall kungöra det, på det att den kärlek, som du har älskat mig med, må vara i dem, och jag i dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 1, 'När Jesus hade sagt detta, begav han sig med sina lärjungar därifrån och gick över bäcken Kidron till andra sidan. Där var en örtagård, och i den gick han in med sina lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 2, 'Men också Judas, han som förrådde honom, kände till det stället, ty där hade Jesus och hans lärjungar ofta kommit tillsammans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 3, 'Och Judas tog nu med sig den romerska vakten, så ock några av översteprästernas och fariséernas tjänare, och kom dit med bloss och lyktor och vapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 4, 'Och Jesus, som visste allt vad som skulle övergå honom, gick fram och sade till dem: »Vem söken I?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 5, 'De svarade honom: »Jesus från Nasaret.» Jesus sade till dem: »Det är jag.» Och Judas, förrädaren, stod också där ibland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 6, 'När Jesus nu sade till dem: »Det är jag», veko de tillbaka och föllo till marken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 7, 'Åter frågade han dem då: »Vem söken I?» De svarade: »Jesus från Nasaret.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 8, 'Jesus sade: »Jag har sagt eder att det är jag; om det alltså är mig I söken, så låten dessa gå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 9, 'Ty det ordet skulle fullbordas, som han hade sagt: »Av dem som du har givit mig har jag icke förlorat någon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 10, 'Och Simon Petrus, som hade ett svärd, drog ut det och högg till översteprästens tjänare och högg så av honom högra örat; och tjänarens namn var Malkus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 11, 'Då sade Jesus till Petrus: »Stick ditt svärd i skidan. Skulle jag icke dricka den kalk som min Fader har givit mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 12, 'Den romerska vakten med sin överste och de judiska rättstjänarna grepo då Jesus och bundo honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 13, 'och förde honom bort, först till Hannas; denne var nämligen svärfader till Kaifas, som var överstepräst det året.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 14, 'Och det var Kaifas som under rådplägningen hade sagt till judarna, att det vore bäst om en man finge dö för folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 15, 'Och Simon Petrus jämte en annan lärjunge följde efter Jesus. Den lärjungen var bekant med översteprästen och gick med Jesus in på översteprästens gård;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 16, 'men Petrus stod utanför vid porten. Den andre lärjungen, den som var bekant med översteprästen, gick då ut och talade med portvakterskan och fick så föra Petrus ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 17, 'Tjänstekvinnan som vaktade porten sade därvid till Petrus: »Är icke också du en av den mannens lärjungar?» Han svarade: »Nej, det är jag icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 18, 'Men tjänarna och rättsbetjänterna hade gjort upp en koleld, ty det var kallt, och de stodo där och värmde sig; bland dem stod också Petrus och värmde sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 19, 'Översteprästen frågade nu Jesus om hans lärjungar och om hans lära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 20, 'Jesus svarade honom: »Jag har öppet talat för världen, jag har alltid undervisat i synagogan eller i helgedomen, på ställen där alla judar komma tillsammans; hemligen har jag intet talat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 21, 'Varför frågar du då mig? Dem som hava hört mig må du fråga om vad jag har talat till dem. De veta ju vad jag har sagt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 22, 'När Jesus sade detta, gav honom en av rättstjänarna, som stod där bredvid, ett slag på kinden och sade: »Skall du så svara översteprästen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 23, 'Jesus svarade honom: »Har jag talat orätt, så bevisa att det var orätt; men har jag talat rätt, varför slår du mig då?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 24, 'Och Hannas sände honom bunden till översteprästen Kaifas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 25, 'Men Simon Petrus stod och värmde sig. Då sade de till honom: »Är icke också du en av hans lärjungar?» Han nekade och sade: »Det är jag icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 26, 'Då sade en av översteprästens tjänare, en frände till den som Petrus hade huggit örat av: »Såg jag icke själv att du var med honom i örtagården?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 27, 'Då nekade Petrus åter. Och i detsamma gol hanen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 28, 'Sedan förde de Jesus från Kaifas till pretoriet; och det var nu morgon. Men själva gingo de icke in i pretoriet, för att de icke skulle bliva orenade, utan skulle kunna äta påskalammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 29, 'Då gick Pilatus ut till dem och sade: »Vad haven I för anklagelse att frambära mot denne man?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 30, 'De svarade och sade till honom: »Vore han icke en illgärningsman, så hade vi icke överlämnat honom åt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 31, 'Då sade Pilatus till dem: »Tagen I honom, och dömen honom efter eder lag.» Judarna svarade honom: »För oss är det icke lovligt att avliva någon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 32, 'Ty Jesu ord skulle fullbordas, det som han hade sagt för att giva till känna på vad sätt han skulle dö.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 33, 'Pilatus gick åter in i pretoriet och kallade Jesus till sig och sade till honom: »Är du judarnas konung?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 34, 'Jesus svarade: »Säger du detta av dig själv, eller hava andra sagt dig det om mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 35, 'Pilatus svarade: »Jag är väl icke en jude! Ditt eget folk och översteprästerna hava överlämnat dig åt mig. Vad har du gjort?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 36, 'Jesus svarade: »Mitt rike är icke av denna världen. Om mitt rike vore av denna världen, så hade väl mina tjänare kämpat för att jag icke skulle bliva överlämnad åt judarna. Men nu är mitt rike icke av denna världen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 37, 'Så sade Pilatus till honom: »Så är du dock en konung?» Jesus svarade: »Du säger det själv, att jag är en konung. Ja, därtill är jag född, och därtill har jag kommit i världen, att jag skall vittna för sanningen. Var och en som är av sanningen, han hör min röst.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 38, 'Pilatus sade till honom: »Vad är sanning?» När han hade sagt detta, gick han åter ut till judarna och sade till dem: »Jag finner honom icke skyldig till något brott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 39, 'Nu är det en sedvänja hos eder, att jag vid påsken skall giva eder en fånge lös. Viljen I då att jag skall giva eder \'judarnas konung\' lös?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 40, 'Då skriade de åter och sade: »Icke honom, utan Barabbas.» Men Barabbas var en rövare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 1, 'Så tog då Pilatus Jesus och lät gissla honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 2, 'Och krigsmännen vredo samman en krona av törnen och satte den på hans huvud och klädde på honom en purpurfärgad mantel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 3, 'Sedan trädde de fram till honom och sade: »Hell dig, du judarnas konung!» och slogo honom på kinden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 4, 'Åter gick Pilatus ut och sade till folket: »Se, jag vill föra honom ut till eder, på det att I mån förstå att jag icke finner honom skyldig till något brott.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 5, 'Och Jesus kom då ut, klädd i törnekronan och den purpurfärgade manteln. Och han sade till dem: »Se mannen!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 6, 'Då nu översteprästerna och rättstjänarna fingo se honom, skriade de: »Korsfäst! Korsfäst!» Pilatus sade till dem: »Tagen I honom, och korsfästen honom; jag finner honom icke skyldig till något brott.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 7, 'Judarna svarade honom: »Vi hava själva en lag, och efter den lagen måste han dö, ty han har gjort sig till Guds Son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 8, 'När Pilatus hörde dem tala så, blev hans fruktan ännu större.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 9, 'Och han gick åter in i pretoriet och frågade Jesus: »Varifrån är du?» Men Jesus gav honom intet svar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 10, 'Då sade Pilatus till honom: »Svarar du mig icke? Vet du då icke att jag har makt att giva dig lös och makt att korsfästa dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 11, 'Jesus svarade honom: »Du hade alls ingen makt över mig, om den icke vore dig given ovanifrån. Därför har den större synd, som har överlämnat mig åt dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 12, 'Från den stunden sökte Pilatus efter någon utväg att giva honom lös. Men judarna ropade och sade: »Giver du honom lös, så är du icke kejsarens vän. Vemhelst som gör sig till konung, han sätter sig upp mot kejsaren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 13, 'När Pilatus hörde de orden, lät han föra ut Jesus och satte sig på domarsätet, på en plats som kallades Litostroton, på hebreiska Gabbata.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 14, 'Och det var tillredelsedagen före påsken, vid sjätte timmen. Och han sade till judarna: »Se här är eder konung!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 15, 'Då skriade de: »Bort med honom! Bort med honom! Korsfäst honom!» Pilatus sade till dem: »Skall jag korsfästa eder konung?» Översteprästerna svarade: »Vi hava ingen annan konung än kejsaren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 16, 'Då gjorde han dem till viljes och bjöd att han skulle korsfästas. Och de togo Jesus med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 17, 'Och han bar själv sitt kors och kom så ut till det ställe som kallades Huvudskalleplatsen, på hebreiska Golgata.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 18, 'Där korsfäste de honom, och med honom två andra, en på vardera sidan, och Jesus i mitten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 19, 'Men Pilatus lät ock göra en överskrift och sätta upp den på korset; och den lydde så: »Jesus från Nasaret, judarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 20, 'Den överskriften läste många av judarna, ty det ställe där Jesus var korsfäst låg nära staden: och den var avfattad på hebreiska, på latin och på grekiska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 21, 'Då sade judarnas överstepräster till Pilatus: »Skriv icke: \'Judarnas konung\', utan skriv att han har sagt sig vara judarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 22, 'Pilatus svarade: »Vad jag har skrivit, det har jag skrivit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 23, 'Då nu krigsmännen hade korsfäst Jesus, togo de hans kläder och delade dem i fyra delar, en del åt var krigsman. Också livklädnaden togo de. Men livklädnaden hade inga sömmar, utan var vävd i ett stycke, uppifrån och alltigenom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 24, 'Därför sade de till varandra: »Låt oss icke skära sönder den, utan kasta lott om vilken den skall tillhöra.» Ty skriftens ord skulle fullbordas: »De delade mina kläder mellan sig och kastade lott om min klädnad.» Så gjorde nu krigsmännen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 25, 'Men vid Jesu kors stodo hans moder och hans moders syster, Maria, Klopas\' hustru, och Maria från Magdala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 26, 'När Jesus nu fick se sin moder och bredvid henne den lärjunge som han älskade, sade han till sin moder: »Moder, se din son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 27, 'Sedan sade han till lärjungen: »Se din moder.» Och från den stunden tog lärjungen henne hem till sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 28, 'Eftersom nu Jesus visste att allt annat redan var fullbordat, sade han därefter, då ju skriften skulle i allt uppfyllas: »Jag törstar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 29, 'Där stod då en kärl som var fullt av ättikvin. Med det vinet fyllde de en svamp, som de satte på en isopsstängel och förde till hans mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 30, 'Och när Jesus hade tagit emot vinet, sade han: »Det är fullbordat.» Sedan böjde han ned huvudet och gav upp andan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 31, 'Men eftersom det var tillredelsedag och judarna icke ville att kropparna skulle bliva kvar på korset över sabbaten (det var nämligen en stor sabbatsdag), bådo de Pilatus att han skulle låta sönderslå de korsfästas ben och taga bort kropparna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 32, 'Så kommo då krigsmännen och slogo sönder den förstes ben och sedan den andres som var korsfäst med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 33, 'När de därefter kommo till Jesus och sågo honom redan vara död, slogo de icke sönder hans ben;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 34, 'men en av krigsmännen stack upp han sida med ett spjut, och strax kom därifrån ut blod och vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 35, 'Och den som har sett detta, han har vittnat därom, för att ock I skolen tro; och hans vittnesbörd är sant, och han vet att han talar sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 36, 'Ty detta skedde, för att skriftens ord skulle fullbordas: »Intet ben skall sönderslås på honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 37, 'Och åter ett annat skriftens ord lyder så: »De skola se upp till honom som de hava stungit.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 38, 'Men Josef från Arimatea, som var en Jesu lärjunge -- fastän i hemlighet, av fruktan för judarna -- kom därefter och bad Pilatus att få taga Jesu kropp; och Pilatus tillstadde honom det. Då gick han åstad och tog hans kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 39, 'Och jämväl Nikodemus kom dit, han som första gången hade besökt honom om natten; denne förde med sig en blandning av myrra och aloe, vid pass hundra skålpund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 40, 'Och de togo Jesu kropp och omlindade den med linnebindlar och lade dit de välluktande kryddorna, såsom judarna hava för sed vid tillredelse till begravning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 41, 'Men invid det ställe där han hade blivit korsfäst var en örtagård, och i örtagården fanns en ny grav, som ännu ingen hade varit lagd i.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 42, 'Där lade de nu Jesus, eftersom det var judarnas tillredelsedag och graven låg nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 1, 'Men på första veckodagen, medan det ännu var mörkt, kom Maria från Magdala dit till graven och fick se stenen vara borttagen från graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 2, 'Då skyndade hon därifrån och kom till Simon Petrus och till den andre lärjungen, den som Jesus älskade, och sade till dem: »De hava tagit Herren bort ur graven, och vi veta icke var de hava lagt honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 3, 'Då begåvo sig Petrus och den andre lärjungen åstad på väg till graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 4, 'Och de sprungo båda på samma gång; men den andre lärjungen sprang fortare än Petrus och kom först fram till graven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 5, 'Och när han lutade sig ditin, så han linnebindlarna ligga där; dock gick han icke in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 6, 'Sedan, efter honom, kom ock Simon Petrus dit. Han gick in i graven och fick så se huru bindlarna lågo där,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 7, 'och huru duken som hade varit höljd över hans huvud icke låg tillsammans med bindlarna, utan för sig själv på ett särskilt ställe, hopvecklad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 8, 'Då gick ock den andre lärjungen ditin, han som först hade kommit till graven; och han såg och trodde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 9, 'De hade nämligen ännu icke förstått skriftens ord, att han skulle uppstå från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 10, 'Och lärjungarna gingo så hem till sitt igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 11, 'Men Maria stod och grät utanför graven. Och under det hon grät, lutade hon sig in i graven');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 12, 'och fick då se två änglar i vita kläder sitta där Jesu kropp hade legat, den ene vid huvudets plats, den andre vid fötternas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 13, 'Och de sade till henne: »Kvinna, varför gråter du?» Hon svarade dem: »De hava tagit bort min Herre, och jag vet icke var de hava lagt honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 14, 'Vid det hon sade detta, vände hon sig om och fick se Jesus stå där; men hon visste icke att det var Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 15, 'Jesus sade till henne: »Kvinna, varför gråter du? Vem söker du?» Hon trodde att det var örtagårdsmästaren och svarade honom: »Herre, om det är du som har burit bort honom, så säg mig var du har lagt honom, så att jag kan hämta honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 16, 'Jesus sade till henne: »Maria!» Då vände hon sig om och sade till honom på hebreiska: »Rabbuni!» (det betyder mästare).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 17, 'Jesus sade till henne: »Rör icke vid mig; jag har ju ännu icke farit upp till Fadern. Men gå till mina bröder, och säg till dem att jag far upp till min Fader och eder Fader, till min Gud och eder Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 18, 'Maria från Magdala gick då och omtalade för lärjungarna att hon hade sett Herren, och att han hade sagt detta till henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 19, 'På aftonen samma dag, den första veckodagen, medan lärjungarna av fruktan för judarna voro samlade inom stängda dörrar, kom Jesus och stod mitt ibland dem och sade till dem: »Frid vare med eder!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 20, 'Och när han hade sagt detta, visade han dem sina händer och sin sida. Och lärjungarna blevo glada, när de sågo Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 21, 'Åter sade Jesus till dem: »Frid vare med eder! Såsom Fadern har sänt mig, så sänder ock jag eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 22, 'Och när han hade sagt detta, andades han på dem och sade till dem: »Tagen emot helig ande!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 23, 'Om I förlåten någon hans synder, så äro de honom förlåtna; och om I binden någon i hans synder, så är han bunden i dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 24, 'Men Tomas, en av de tolv, han som kallades Didymus, var icke med dem, när Jesus kom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 25, 'Då nu de andra lärjungarna sade till honom att de hade sett Herren, svarade han dem: »Om jag icke ser hålen efter spikarna i hans händer och sticker mitt finger i hålen efter spikarna och sticker min hand i hans sida, så kan jag icke tro det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 26, 'Åtta dagar därefter voro hans lärjungar åter därinne, och Tomas var med bland dem. Då kom Jesus, medan dörrarna voro stängda, och stod mitt ibland de, och sade: »Frid vare med eder!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 27, 'Sedan sade han till Tomas: »Räck hit dit finger, se här äro mina händer; och räck hit din hand, och stick den i min sida. Och tvivla icke, utan tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 28, 'Tomas svarade och sade till honom: »Min Herre och min Gud!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 29, 'Jesus sade till honom: »Eftersom du har sett mig, tror du? Saliga äro de som icke se och dock tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 30, 'Ännu många andra tecken, som icke äro uppskrivna i denna bok, gjorde Jesus i sina lärjungars åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 31, 'Men dessa hava blivit uppskrivna, för att I skolen tro att Jesus är Messias, Guds Son, och för att I genom tron skolen hava liv i hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 1, 'Därefter uppenbarade sig Jesus åter för lärjungarna, vid Tiberias\' sjö; och vid den uppenbarelsen gick så till:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 2, 'Simon Petrus och Tomas, som kallades Didymus, och Natanael, han som var från Kana i Galileen, och Sebedeus\' söner voro tillsammans, och med dem två andra av hans lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 3, 'Simon Petrus sade då till dem: »Jag vill gå åstad och fiska.» De sade till honom: »Vi gå också med dig.» Så begåvo de sig åstad och stego i båten. Men den natten fingo de intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 4, 'När det sedan hade blivit morgon, stod Jesus där på stranden; dock visste lärjungarna icke att det var Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 5, 'Och Jesus sade till dem: »Mina barn, haven I något att äta?» De svarade honom: »Nej.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 6, 'Han sade till dem: »Kasten ut nätet på högra sidan om båten, så skolen I få.» Då kastade de ut; och nu fingo de en så stor hop fiskar, att de icke förmådde draga upp nätet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 7, 'Den lärjunge som Jesus älskade sade då till Petrus: »Det är Herren.» När Simon Petrus hörde att det var Herren, tog han på sig sin överklädnad -- ty han var oklädd -- och gav sig i sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 8, 'Men de andra lärjungarna kommo med båten och drogo efter sig nätet med fiskarna; de voro nämligen icke längre från land än vid pass två hundra alnar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 9, 'När de sedan hade stigit i land, sågo de glöd ligga där och fisk, som låg därpå, och bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 10, 'Jesus sade till dem: »Tagen hit av de fiskar som I nu fingen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 11, 'Då steg Simon Petrus i båten och drog nätet upp på land, och det var fullt av stora fiskar, ett hundra femtiotre stycken. Och fastän de voro så många, hade nätet icke gått sönder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 12, 'Därefter sade Jesus till dem: »Kommen hit och äten.» Och ingen av lärjungarna dristade sig att fråga honom vem han var, ty de förstodo att det var Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 13, 'Jesus gick då fram och tog brödet och gav dem, likaledes ock av fiskarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 14, 'Detta var nu tredje gången som Jesus uppenbarade sig för sina lärjungar, sedan han hade uppstått från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 15, 'När de hade ätit, sade Jesus till Simon Petrus: »Simon, Johannes\' son, älskar du mig mer än dessa göra?» Han svarade honom: »Ja, Herre; du vet att jag har dig kär.» Då sade han till honom: »Föd mina lamm.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 16, 'Åter frågade han honom, för andra gången: »Simon, Johannes\' son, älskar du mig?» Han svarade honom: »Ja, Herre; du vet att jag har dig kär.» Då sade han till honom: »Var en herde för mina får.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 17, 'För tredje gången frågade han honom: »Simon, Johannes\' son, har du mig kär?» Petrus blev bedrövad över att han för tredje gången frågade honom: »Har du mig kär?» Och han svarade honom: »Herre, du vet allting; du vet att jag har dig kär.» Då sade Jesus till honom: »Föd mina får.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 18, 'Sannerligen, sannerligen säger jag dig: När du var yngre, omgjordade du dig själv och gick vart du ville; men när du bliver gammal, skall du nödgas sträcka ut dina händer, och en annan skall omgjorda dig och föra dig dit du icke vill.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 19, 'Detta sade han för att giva till känna med hurudan död Petrus skulle förhärliga Gud. Och sedan han hade sagt detta, sade han till honom: »Följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 20, 'När Petrus vände sig om, fick han se att den lärjunge som Jesus älskade följde med, densamme som under aftonmåltiden hade lutat sig mot hans bröst och frågat honom: »Herre, vilken är det som skall förråda dig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 21, 'Då nu Petrus såg den lärjungen, frågade han Jesus: »Herre, huru bliver det då med denne?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 22, 'Jesus svarade honom: »Om jag vill att han skall leva kvar, till dess jag kommer, vad kommer det dig vid? Följ du mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 23, 'Så kom det talet ut ibland bröderna, att den lärjungen icke skulle dö. Men Jesus hade icke sagt till honom att han icke skulle dö, utan allenast: »Om jag vill att han skall leva kvar, till dess jag kommer, vad kommer det dig vid?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 24, 'Det är den lärjungen som vittnar om detta, och som har skrivit detta; och vi veta att hans vittnesbörd är sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 25, 'Ännu mycket annat var det som Jesus gjorde; och om allt detta skulle uppskrivas, det ena med det andra, så tror jag att icke ens hela världen skulle kunna rymma de böcker som då bleve skrivna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'I min förra skrift, gode Teofilus, har jag berättat om allt vad Jesus gjorde och lärde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'ända till den dag då han blev upptagen, sedan han genom helig ande hade givit sina befallningar åt apostlarna som han hade utvalt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'För dem hade han ock genom många säkra bevis tett sig såsom levande, efter utståndet lidande; ty under fyrtio dagar lät han sig ses av dem och talade med dem om Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'När han då var tillsammans med dem, bjöd han dem och sade: »Lämnen icke Jerusalem, utan förbiden där vad Fadern har utlovat, det varom I haven hört av mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Ty Johannes döpte med vatten, men få dagar härefter skolen I bliva döpta i helig ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Då de nu hade kommit tillhopa, frågade de honom och sade: »Herre, skall du nu i denna tid upprätta igen riket åt Israel?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Han svarade dem: »Det tillkommer icke eder att få veta tider eller stunder som Fadern i sin makt har fastställt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Men när den helige Ande kommer över eder, skolen I undfå kraft och bliva mina vittnen, både i Jerusalem och i hela Judeen och Samarien, och sedan intill jordens ända.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'När han hade sagt detta, lyftes han inför deras ögon upp i höjden, och en sky tog honom bort ur deras åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Och medan de skådade mot himmelen, under det han for upp, se, då stodo hos dem två män i vita kläder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Och dessa sade: »I galileiske män, varför stån I och sen mot himmelen? Denne Jesus, som har blivit upptagen från eder till himmelen, han skall komma igen på samma sätt som I haven sett honom fara upp till himmelen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Sedan vände de tillbaka till Jerusalem från det berg som kallas Oljeberget, vilket ligger nära Jerusalem, icke längre därifrån, än man får färdas på en sabbat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Och när de hade kommit dit, gingo de upp i den sal i övre våningen, där de plägade vara tillsammans: Petrus och Johannes och Jakob och Andreas, Filippus och Tomas, Bartolomeus och Matteus, Jakob, Alfeus\' son, och Simon ivraren och Judas, Jakobs son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Alla dessa höllo endräktigt ut i bön tillika med Maria, Jesu moder, och några andra kvinnor samt Jesu bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'En av de dagarna stod Petrus upp och talade bland bröderna, som då voro församlade till ett antal av omkring etthundratjugu; han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, '»Mina bröder, det skriftens ord skulle fullbordas, som den helige Ande genom Davids mun hade profetiskt talat om Judas, vilken blev vägvisare åt de män som grepo Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Han var ju räknad bland oss och hade också fått detta ämbete på sin lott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Och med de penningar han hade fått såsom lön för sin ogärning förvärvade han sig en åker. Men han störtade framstupa ned, och hans kropp brast mitt itu, så att alla hans inälvor gåvo sig ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Detta blev bekant för alla Jerusalems invånare, och så blev den åkern på deras tungomål kallad Akeldamak (det betyder Blodsåkern).');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Så är ju skrivet i Psalmernas bok: \'Hans gård blive öde, och ingen må finnas, som bor däri\'; och vidare: \'Hans ämbete tage en annan.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Därför bör nu någon av de män som följde oss under hela den tid då Herren Jesus gick ut och in bland oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'allt ifrån den dag då han döptes av Johannes ända till den dag då han blev upptagen och skildes ifrån oss -- någon av dessa män bör insättas till att jämte oss vittna om hans uppståndelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'Därefter ställde de fram två: Josef (som kallades Barsabbas och hade tillnamnet Justus) och Mattias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, 'Och de bådo och sade: »Herre, du som känner allas hjärtan, visa oss vilken av dessa två du har utvalt');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 25, 'till att få den plats såsom tjänare och apostel, vilken Judas övergav, för att gå till den plats som var hans.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 26, 'Och de drogo lott om dem, och lotten föll på Mattias. Och så blev denne, jämte de elva, räknad såsom apostel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'När sedan pingstdagen var inne, voro de alla församlade med varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Då kom plötsligt från himmelen ett dån, såsom om en våldsam storm hade dragit fram; och det uppfyllde hela huset där de sutto.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Och tungor såsom av eld visade sig för dem och fördelade sig och satte sig på dem, en på var av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Och de blevo alla uppfyllda av helig ande och begynte tala andra tungomål, efter som Anden ingav dem att tala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Nu bodde i Jerusalem fromma judiska män från allahanda folk under himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Och när dånet hördes, församlade sig hela hopen, och en stor rörelse uppstod, ty var och en hörde sitt eget tungomål talas av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Och de uppfylldes av häpnad och förundran och sade: »Äro de icke galiléer, alla dessa som här tala?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Huru kommer det då till, att var och en av oss hör sitt eget modersmål talas?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Vi må vara parter eller meder eller elamiter, vi må hava vårt hem i Mesopotamien eller Judeen eller Kappadocien, i Pontus eller provinsen Asien,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'i Frygien eller Pamfylien, i Egypten eller i Libyens bygder, åt Cyrene till, eller vara hitflyttade främlingar från Rom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'vi må vara judar eller proselyter, kretenser eller araber, alla höra vi dem på våra egna tungomål tala om Guds väldiga gärningar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Så uppfylldes de alla av häpnad och visste icke vad de skulle tänka. Och de sade, den ene till den andre: »Vad kan detta betyda?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Men somliga drevo gäck med dem och sade: »De äro fulla av sött vin.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Då trädde Petrus fram, jämte de elva, och hov upp sin röst och talade till dem: »I judiske män och I alla Jerusalems invånare, detta mån I veta, och lyssnen nu till mina ord:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Det är icke så som I menen, att dessa äro druckna; det är ju blott tredje timmen på dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Nej, här uppfylles det som är sagt genom profeten Joel:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, '\'Och det skall ske i de yttersta dagarna, säger Gud, att jag skall utgjuta av min Ande över allt kött, och edra söner och edra döttrar skola profetera, och edra ynglingar skola se syner, och edra gamla män skola hava drömmar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'ja, över mina tjänare och mina tjänarinnor skall jag i de dagarna utgjuta av min Ande, och de skola profetera.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Och jag skall låta undertecken synas uppe på himmelen och tecken nere på jorden: blod och eld och rökmoln.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Solen skall vändas i mörker och månen i blod, förrän Herrens dag kommer, den stora och härliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Och det skall ske att var och en som åkallar Herrens namn, han skall varda frälst.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'I män av Israel, hören dessa ord: Jesus från Nasaret, en man som inför eder fick vittnesbörd av Gud genom kraftgärningar och under och tecken, vilka Gud genom honom gjorde bland eder, såsom I själva veten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 23, 'denne som blev given i edert våld, enligt vad Gud i sitt rådslut och sin försyn hade bestämt, honom haven I genom män som icke veta av lagen låtit fastnagla vid korset och döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 24, 'Men Gud gjorde en ände på dödens vånda och lät honom uppstå, eftersom det icke var möjligt att han skulle kunna behållas av döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 25, 'Ty David säger med tanke på honom: \'Jag har haft Herren för mina ögon alltid, ja, han är på min högra sida, för att jag icke skall vackla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 26, 'Fördenskull gläder sig mitt hjärta, och min tunga fröjdar sig, och jämväl min kropp får vila med en förhoppning:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 27, 'den, att du icke skall lämna min själ åt dödsriket och icke låta din Helige se förgängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 28, 'Du har kungjort mig livets vägar; du skall uppfylla mig med glädje inför ditt ansikte.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 29, 'Mina bröder, jag kan väl fritt säga till eder om vår stamfader David att han är både död och begraven; hans grav finnes ju ibland oss ännu i dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 30, 'Men eftersom han var en profet och visste att Gud med ed hade lovat honom att \'av hans livs frukt sätta en konung på hans tron\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 31, 'därför förutsåg han att Messias skulle uppstå, och talade därom och sade att Messias icke skulle lämnas åt dödsriket, och att hans kropp icke skulle se förgängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 32, 'Denne -- Jesus -- har nu Gud låtit uppstå; därom kunna vi alla vittna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 33, 'Och sedan han genom Guds högra hand har blivit upphöjd och av Fadern undfått den utlovade helige Anden, har han utgjutit vad I här sen och hören.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 34, 'Ty icke har David farit upp till himmelen; fastmer säger han själv: \'Herren sade till min herre: Sätt dig på min högra sida,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 35, 'till dess jag har lagt dina fiender dig till en fotapall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 36, 'Så må nu hela Israels hus veta och vara förvissat om att denne Jesus som I haven korsfäst, honom har Gud gjort både till Herre och till Messias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 37, 'När de hörde detta, kände de ett styng i hjärtat. Och de sade till Petrus och de andra apostlarna: »Bröder, vad skola vi göra?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 38, 'Petrus svarade dem: »Gören bättring, och låten alla döpa eder i Jesu Kristi namn till edra synders förlåtelse; då skolen I såsom gåva undfå den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 39, 'Ty eder gäller löftet och edra barn, jämväl alla dem som äro i fjärran, så många som Herren, vår Gud, kallar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 40, 'Också med många andra ord bad och förmanade han dem, i det han sade: »Låten frälsa eder från detta vrånga släkte.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 41, 'De som då togo emot hans ort läto döpa sig; och så ökades församlingen på den dagen med vid pass tre tusen personer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 42, 'Och dessa höllo fast vid apostlarnas undervisning och brödragemenskapen, vid brödsbrytelsen och bönerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 43, 'Och fruktan kom över var och en; och många under och tecken gjordes genom apostlarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 44, 'Men alla de som trodde höllo sig tillsammans och hade allting gemensamt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 45, 'de sålde sina jordagods och vad de eljest ägde och delade med sig därav åt alla, eftersom var och en behövde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 46, 'Och ständigt, var dag, voro de endräktigt tillsammans i helgedomen; och hemma i husen bröto de bröd och åto med fröjd och i hjärtats enfald, och lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 47, 'Och allt folket vad dem väl bevåget. Och Herren ökade församlingen, dag efter dag, med dem som läto sig frälsas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Och Petrus och Johannes gingo upp till helgedomen, till den bön som hölls vid nionde timmen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Och där bars fram en man som hade varit ofärdig allt ifrån moderlivet, och som man var dag plägade sätta vid den port i helgedomen, som kallades Sköna porten, för att han skulle kunna begära allmosor av dem som gingo in i helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'När denne nu fick se Petrus och Johannes, då de skulle gå in i helgedomen, bad han dem om en allmosa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Då fäste Petrus och Johannes sina ögon på honom, och Petrus sade: »Se på oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'När han då gav akt på dem, i förväntan att få något av dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'sade Petrus: »Silver och guld har jag icke; men vad jag har, det giver jag dig. I Jesu Kristi, nasaréens namn: stå upp och gå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Och så fattade han honom vid högra handen och reste upp honom. Och strax fingo hans fötter och fotleder styrka,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'och han sprang upp och stod upprätt och begynte gå och följde dem in i helgedomen, alltjämt gående och springande, under det att han lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Och allt folket såg honom, där han gick omkring och lovade Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Och när de kände igen honom och sågo att det var samme man som plägade sitta och begära allmosor vid Sköna porten i helgedomen, blevo de uppfyllda av häpnad och bestörtning över det som hade vederfarits honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Då han nu höll sig till Petrus och Johannes, strömmade allt folket, utom sig av häpnad, tillsammans till dem på den plats som kallades Salomos pelargång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'När Petrus såg detta, tog han till orda och talade till folket så: »I män av Israel, varför undren I över denne man, och varför sen I så på oss, likasom hade vi genom någon vår kraft eller fromhet åstadkommit att han kan gå?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Nej, Abrahams och Isaks och Jakobs Gud, våra fäders Gud, har förhärligat sin tjänare Jesus, honom som I utlämnaden, och som I förnekaden inför Pilatus, när denne redan hade beslutit att giva honom lös.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Ja, I förnekaden honom, den helige och rättfärdige, och begärden att en dråpare skulle givas åt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Och livets furste dräpten I, men Gud uppväckte honom från de döda; därom kunna vi själva vittna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Och det är på grund av tron på hans namn som denne man, vilken I sen och kännen, har undfått styrka av hans namn; och den tro som verkas genom Jesus har, i allas eder åsyn, gjort att han nu kan bruka alla lemmar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Nu vet jag väl, mina bröder, att I såväl som edra rådsherrar haven gjort detta, därför att I icke vissten bättre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Men Gud har på detta sätt låtit det gå i fullbordan, som han förut genom alla sina profeters mun hade förkunnat, nämligen att hans Smorde skulle lida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 19, 'Gören därför bättring och omvänden eder, så att edra synder bliva utplånade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 20, 'på det att tider av vederkvickelse må komma från Herren, i det att han sänder den Messias som han har utsett åt eder, nämligen Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 21, 'vilken dock himmelen måste behålla intill de tider nå allt skall bliva upprättat igen, varom Gud har talat genom sina forntida heliga profeters mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 22, 'Moses har ju sagt: \'En profet skall Herren Gud låta uppstå åt eder, av edra bröder, en som är mig lik; honom skolen I lyssna till i allt vad han talar till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 23, 'Och det skall ske att var och en som icke lyssnar till den profeten, han skall utrotas ur folket.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 24, 'Och sedan hava alla profeterna, både Samuel och de som följde efter honom, så många som hava talat, också bebådat dessa tider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 25, 'I ären själva barn av profeterna och delaktiga i det förbund som Gud slöt med edra fäder, när han sade till Abraham: \'Och i din säd skola alla släkter på jorden varda välsignade.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 26, 'För eder först och främst har Gud låtit sin tjänare uppstå, och han har sänt honom för att välsigna eder, när I, en och var, omvänden eder från eder ondska.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Medan de ännu talade till folket, kommo prästerna och tempelvaktens befälhavare och sadducéerna över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'Ty det förtröt dem att de undervisade folket och i Jesus förkunnade uppståndelsen från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'Därför grepo de dem nu och satte dem i fängsligt förvar till följande dag, eftersom det redan var afton.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Men många av dem som hade hört vad som hade talats kommo till tro; och antalet av männen uppgick nu till vid pass fem tusen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Dagen därefter församlade sig deras rådsherrar och äldste och skriftlärde i Jerusalem;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'där voro då ock Hannas, översteprästen, och Kaifas och Johannes och Alexander och alla som voro av översteprästerlig släkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Och de läto föra fram dem inför sig och frågade dem: »Av vilken makt eller i genom vilket namn haven I gjort detta?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Då sade Petrus till dem, uppfylld av helig ande: »I folkets rådsherrar och äldste,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'eftersom vi i dag underkastas rannsakning för en god gärning mot en sjuk man och tillfrågas varigenom denne har blivit botad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'så mån I veta, I alla och hela Israels folk, att det är genom Jesu Kristi, nasaréens, namn, hans som I haven korsfäst, men som Gud har uppväckt från de döda -- att det är genom det namnet som denne man står inför eder frisk och färdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Han är \'den stenen som av byggningsmännen\' -- av eder själva -- \'aktades för intet, men som har blivit en hörnsten\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Och i ingen annan finnes frälsning; ej heller finnes under himmelen något annat namn, bland människor givet, genom vilket vi kunna bliva frälsta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'När de sågo Petrus och Johannes vara så frimodiga och förnummo att de voro olärda män ur folket, förundrade de sig. Men så kände de igen dem och påminde sig att de hade varit med Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Och när de sågo mannen som hade blivit botad stå där bredvid dem, kunde de icke säga något däremot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'De befallde dem alltså att gå ut från rådsförsamlingen. Sedan överlade de med varandra');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'och sade: »Vad skola vi göra med dessa män? Att ett märkligt tecken har blivit gjort av dem, det är ju uppenbart för alla Jerusalems invånare, och vi kunna icke förneka det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Men för att detta icke ännu mer skall komma ut bland folket, må vi strängeligen förbjuda dem att hädanefter i det namnet tala för någon människa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'Därefter kallade de in dem och förbjödo dem helt och hållet att tala eller undervisa i Jesu namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 19, 'Men Petrus och Johannes svarade och sade till dem: »Om det är rätt inför Gud att vi hörsamma eder mer är Gud, därom mån I själva döma;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 20, 'vi för vår del kunna icke underlåta att tala vad vi hava sett och hört.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 21, 'Då förbjödo de dem detsamma ännu strängare, men läto dem sedan gå. Ty eftersom alla prisade Gud för det som hade skett, kunde de, för folkets skull, icke finna någon utväg genom att straffa dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 22, 'Mannen som genom detta tecken hade blivit botad var nämligen över fyrtio år gammal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 23, 'När de alltså hade blivit lösgivna, kommo de till sina egna och omtalade för dem allt vad översteprästerna och de äldste hade sagt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 24, 'Då de hörde detta, ropade de endräktigt till Gud och sade: »Herre, det är du som har gjort himmelen och jorden och havet och allt vad i dem är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 25, 'Och du har genom vår fader Davids, din tjänares, mun sagt genom helig ande: \'Varför larmade hedningarna och tänkte folken fåfänglighet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 26, 'Jordens konungar trädde fram, och furstarna samlade sig tillhopa mot Herren och hans Smorde.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 27, 'Ja, i sanning, de församlade sig i denna stad mot din helige tjänare Jesus, mot honom som du har smort: Herodes och Pontius Pilatus med hedningarna och Israels folkstammar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 28, 'de församlade sig till att utföra allt vad din hand och ditt rådslut förut hade bestämt skola ske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 29, 'Och nu, Herre, se till deras hotelser, och giv dina tjänare att de med all frimodighet må förkunna ditt ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 30, 'i det att du uträcker din hand till att bota de sjuka, och till att låta tecken och under ske genom din helige tjänare Jesu namn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 31, 'När de hade slutat att bedja, skakades platsen där de voro församlade, och de blevo alla uppfyllda av den helige Ande, och de förkunnade Guds ord med frimodighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 32, 'Och i hela skaran av dem som trodde var ett hjärta och en själ. Ingen enda kallade något av det han ägde för sitt, utan du hade allting gemensamt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 33, 'Och med stor kraft framburo apostlarna vittnesbördet om Herren Jesu uppståndelse; och stor nåd var över dem alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 34, 'Bland dem fanns ingen som led nöd; ty alla som ägde något jordstycke eller något hus sålde detta och buro fram betalningen för det sålda');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 35, 'och lade den för apostlarnas fötter, och man delade ut därav, så att var och en fick efter som han behövde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 36, 'Josef, som av apostlarna ock kallades Barnabas (det betyder förmanaren), en levit som var bördig från Cypern,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 37, 'också han sålde en åker som han ägde och bar fram penningarna och lade dem för apostlarnas fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Men en ung man vid namn Ananias och hans hustru Safira sålde ett jordagods,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'och han tog därvid, med sin hustrus vetskap, undan något av betalningen därför; allenast en del bar han fram och lade för apostlarnas fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'Då sade Petrus: »Ananias, varför har Satan fått uppfylla ditt hjärta, så att du har velat bedraga den helige Ande och taga undan något av betalningen för jordstycket?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Detta var ju din egendom, medan du hade det kvar; och när det var sålt, voro ju penningarna i din makt. Huru kunde du få något sådant i sinnet? Du har ljugit, icke för människor, utan för Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'När Ananias hörde dessa ord, föll han ned och gav upp andan. Och stor fruktan kom över alla som hörde detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Och de yngre männen stodo upp och höljde in honom och buro ut honom och begrovo honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'Vid pass tre timmar därefter kom hans hustru in, utan att veta om, vad som hade skett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Petrus sade då till henne: »Säg mig, var det för den summan I sålden jordstycket?» Hon svarade: »Ja, för den summan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Då sade Petrus till henne: »Huru kunden I vilja komma överens om att fresta Herrens Ande? Se, härutanför dörren höras nu fotstegen av de män som hava begravt din man; och de skola bära ut också dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'Och strax föll hon ned vid hans fötter och gav upp andan; och när de unge männen kommo in, funno de henne död. De buro då ut henne och begrovo henne bredvid hennes man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Och stor fruktan kom över hela församlingen och över alla andra som hörde detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'Och genom apostlarna gjordes många tecken och under bland folket; och de höllo sig alla endräktigt tillsammans i Salomos pelargång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'Av de andra dristade sig ingen att närma sig dem, men folket höll dem i ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Och ännu flera trodde och slöto sig till Herren, hela skaror av både män och kvinnor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Ja, man bar de sjuka ut på gatorna och lade dem på bårar och i sängar, för att, när Petrus kom gående, åtminstone hans skugga måtte falla på någon av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Och jämväl från städerna runt omkring Jerusalem kom folket i skaror och förde med sig sjuka och sådana som voro plågade av orena andar; och alla blevo botade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Då stod översteprästen upp och alla som höllo med honom -- de som hörde till sadducéernas parti -- och de uppfylldes av nitälskan');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'och läto gripa apostlarna och sätta dem i allmänt häkte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'Men en Herrens ängel öppnade om natten fängelsets portar och förde ut dem och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, '»Gån åstad och träden upp i helgedomen, och talen till folket alla det sanna livets ord.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'När de hade hört detta, gingo de inemot dagbräckningen in i helgedomen och undervisade. Emellertid kommo översteprästen och de som höllo med honom och sammankallade Stora rådet, alla Israels barns äldste. Därefter sände de åstad till fängelset för att hämta dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Men när rättstjänarna kommo dit, funno de dem icke i fängelset. De vände då tillbaka och omtalade detta');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'och sade: »Fängelset funno vi stängt med all omsorg och väktarna stående utanför portarna, men då vi öppnade, funno vi ingen därinne.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'När tempelvaktens befälhavare och översteprästerna hörde detta, visst de icke vad de skulle tänka därom, eller vad som skulle bliva av detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, 'Då kom någon och berättade för den: »De män som I haven insatt i fängelset, de stå nu i helgedomen och undervisa folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 26, 'Befälhavaren gick då med rättstjänarna åstad och hämtade dem; dock brukade de icke våld, ty de fruktade att bliva stenade av folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 27, 'Och sedan de hade hämtat dem, förde de dem fram inför Stora rådet. Och översteprästen anställde förhör med dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 28, 'och sade: »Vi hava ju allvarligen förbjudit eder att undervisa i det namnet, och likväl haven I uppfyllt Jerusalem med eder undervisning, och I viljen nu låta den mannens blod komma över oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 29, 'Men Petrus och de andra apostlarna svarade och sade: »Man måste lyda Gud mer än människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 30, 'Våra fäders Gud har uppväckt Jesus, som I haden upphängt på trä och dödat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 31, 'Och Gud har med sin högra hand upphöjt honom till en hövding och frälsare, för att åt Israel förläna bättring och syndernas förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 32, 'Om allt detta kunna vi själva vittna, så ock den helige Ande, vilken Gud har givit åt dem som äro honom lydiga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 33, 'När de hörde detta, blevo de mycket förbittrade och ville döda dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 34, 'Men en farisé, en laglärare vid namn Gamaliel, som var aktad av allt folket, stod då upp i Rådet och tillsade att man för en kort stund skulle föra ut männen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 35, 'Sedan sade han till de andra: »I män av Israel, sen eder för vad I tänken göra med dessa män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 36, 'För en tid sedan uppträdde ju Teudas och gav sig ut för att något vara, och till honom slöt sig en hop av vid pass fyra hundra män. Och han blev dödad, och alla som hade trott på honom förskingrades och blevo till intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 37, 'Efter honom uppträdde Judas från Galileen, vid den tid då skattskrivningen pågick; denne förledde en hop folk till avfall, så att de följde honom. Också han förgicks, och alla som hade trott på honom blevo förskingrade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 38, 'Och nu säger jag eder: Befatten eder icke med dessa män, utan låten dem vara; ty skulle detta vara ett rådslag eller ett verk av människor, så kommer det att slås ned;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 39, 'men är det av Gud, så kunnen I icke slå ned dessa män. Sen till, att I icke mån befinnas strida mot Gud själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 40, 'Och de lydde hans råd; de kallade in apostlarna, och sedan de hade låtit gissla dem, förbjödo de dem att tala i Jesu namn och läto dem därefter gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 41, 'Och de gingo ut från rådsförsamlingen, glada över att de hade aktats värdiga att lida smälek för det namnets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 42, 'Och de upphörde icke att var dag undervisa i helgedomen och hemma i husen och förkunna evangelium om Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'Vid denna tid, då nu lärjungarnas antal förökades, begynte de grekiska judarna knorra mot de infödda hebréerna över att deras änkor blevo förbisedda vid den dagliga utdelningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Då sammankallade de tolv hela lärjungaskaran och sade: »Det är icke tillbörligt att vi försumma Guds ord för att göra tjänst vid borden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Så utsen nu bland eder, I bröder, sju män som hava gott vittnesbörd om sig och äro fulla av ande och vishet, män som vi kunna sätta till att sköta denna syssla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'Vi skola då helt få ägna oss åt bönen och åt ordets tjänst.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'Det talet behagade hela menigheten. Och de utvalde Stefanus, en man som var full av tro och helig ande, vidare Filippus och Prokorus och Nikanor och Timon och Parmenas, slutligen Nikolaus, en proselyt från Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'Dem läto de träda fram för apostlarna, och dessa bådo och lade händerna på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Och Guds ord hade framgång, och lärjungarnas antal förökades mycket i Jerusalem; och en stor hop av prästerna blevo lydiga och trodde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Och Stefanus var full av nåd och kraft och gjorde stora under och tecken bland folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'Men av dem som hörde till den synagoga som kallades »De frigivnes och cyrenéernas och alexandrinernas synagoga», så ock av dem som voro från Cilicien och provinsen Asien, stodo några upp för att disputera med Stefanus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'Dock förmådde de icke stå emot den vishet och den ande som här talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Då skaffade de några män som föregåvo att de hade hört honom tala hädiska ord mot Moses och mot Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'De uppeggade så folket och de äldste och de skriftlärde och överföllo honom och grepo honom och förde honom inför Stora rådet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Där läto de falska vittnen träda fram, vilka sade: »Denne man upphör icke att tala mot vår heliga plats och mot lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'Ty vi hava hört honom säga att Jesus, han från Nasaret, skall bryta ned denna byggnad och förändra de stadgar som Moses har givit oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'Då nu alla som sutto i Rådet fäste sina ögon på honom, syntes dem hans ansikte vara såsom en ängels ansikte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 1, 'Och översteprästen frågade: »Förhåller detta sig så?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 2, 'Då sade han: »Bröder och fäder, hören mig. Härlighetens Gud uppenbarade sig för vår fader Abraham, medan han ännu var i Mesopotamien, och förrän han bosatte sig i Karran,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 3, 'och sade till honom: \'Gå ut ur ditt land och från din släkt, och drag till det land som jag skall visa dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 4, 'Då gick han åstad ut ur kaldéernas land och bosatte sig i Karran. Sedan, efter han faders död, bjöd Gud honom att flytta därifrån till detta land, där I nu bon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 5, 'Han gav honom ingen arvedel däri, icke ens så mycket som en fotsbredd, men lovade att giva det till besittning åt honom och åt hans säd efter honom; detta var på den tid då han ännu icke hade någon son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 6, 'Och vad Gud sade var detta, att hans säd skulle leva såsom främlingar i ett land som icke tillhörde dem, och att man skulle göra dem till trälar och förtrycka dem i fyra hundra år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 7, '\'Men det folk vars trälar de bliva skall jag döma\', sade Gud; \'sedan skola de draga ut och hålla gudstjänst åt mig på denna plats.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 8, 'Och han upprättade ett omskärelsens förbund med honom. Och så födde han Isak och omskar honom på åttonde dagen, och Isak födde Jakob, och Jakob födde våra tolv stamfäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 9, 'Och våra stamfäder avundades Josef och sålde honom till Egypten. Men Gud var med honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 10, 'och frälste honom ur allt hans betryck och lät honom finna nåd och gav honom vishet inför Farao, konungen i Egypten; och denne satte honom till herre över Egypten och över hela sitt hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 11, 'Och hungersnöd kom över hela Egypten och Kanaan med stort betryck, och våra fäder kunde icke få något att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 12, 'Men när Jakob fick höra att bröd fanns i Egypten, sände han våra fäder åstad dit, en första gång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 13, 'Sedan, när de för andra gången kommo dit, blev Josef igenkänd av sina bröder, och Farao fick kunskap och Josefs släkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 14, 'Därefter sände Josef åstad och kallade till sig sin fader Jakob och hela sin släkt, sjuttiofem personer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 15, 'Och Jakob for ned till Egypten; och han dog där, han såväl som våra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 16, 'Och man förde dem därifrån till Sikem och lade dem i den grav som Abraham för en summa penningar hade köpt av Emmors barn i Sikem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 17, 'Och alltefter som tiden nalkades att det löfte skulle uppfyllas, som Gud hade givit Abraham, växte folket till och förökade sig i Egypten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 18, 'till dess en ny konung över Egypten uppstod, en som icke visste av Josef.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 19, 'Denne konung gick listigt till väga mot vårt folk och förtryckte våra fäder och drev dem till att utsätta sina späda barn, för att dessa icke skulle bliva vid liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 20, 'Vid den tiden föddes Moses, och han \'var ett vackert barn\' inför Gud. Under tre månader fostrades han i sin faders hus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 21, 'sedan, när han hade blivit utsatt, lät Faraos dotter hämta honom till sig och uppfostra honom såsom sin egen son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 22, 'Och Moses blev undervisad i all egyptiernas visdom och var mäktig i ord och gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 23, 'Men när han blev fyrtio år gammal, fick han i sinnet att besöka sina bröder, Israels barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 24, 'När han då såg att en av dem led orätt, tog han den misshandlade i försvar och hämnades honom, i det att han slog ihjäl egyptiern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 25, 'Nu menade han att hans bröder skulle förstå att Gud genom honom ville bereda dem frälsning; men de förstodo det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 26, 'Dagen därefter kom han åter fram till dem, där de tvistade, och ville förlika dem och sade: \'I män, I ären ju bröder; varför gören I då varandra orätt?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 27, 'Men den som gjorde orätt mot sin landsman stötte bort honom och sade: \'Vem har satt dig till hövding och domare över oss?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 28, 'Kanske du vill döda mig, såsom du i går dödade egyptiern?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 29, 'Vid det talet flydde Moses bort och levde sedan såsom främling i Madiams land och födde där två söner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 30, 'Och när fyrtio är äter voro förlidna, uppenbarade sig för honom, i öknen vid berget Sinai, en ängel i en brinnande törnbuske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 31, 'När Moses såg detta, förundrade han sig över synen; och då han gick fram för att se vad det var, hördes Herrens röst:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 32, '\'Jag är dina fäders Gud, Abrahams, Isaks och Jakobs Gud.\' Då greps Moses av bävan och dristade sig icke att se dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 33, 'Och Herren sade till honom: \'Lös dina skor av dina fötter, ty platsen där du står är helig mark.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 34, 'Jag har nogsamt sett mitt folks betryck i Egypten, och deras suckan har jag hört, och jag har stigit ned för att rädda dem. Därför må du nu gå åstad; jag vill sända dig till Egypten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 35, 'Denne Moses, som de hade förnekat, i det de sade: \'Vem har satt dig till hövding och domare?\', honom sände Gud att vara både en hövding och en förlossare, genom ängeln som uppenbarade sig för honom i törnbusken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 36, 'Det var han som förde ut dem, och som gjorde under och tecken i Egyptens land och i Röda havet och i öknen, under fyrtio år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 37, 'Det var samme Moses som sade till Israels barn: \'En profet skall Gud låta uppstå åt eder, av edra bröder, en som är mig lik.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 38, 'Det var och han, som under den tid då menigheten levde i öknen, både var hos ängeln, som talade med honom på berget Sinai, och tillika hos våra fäder; och han undfick levande ord för att giva dem åt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 39, 'Men våra fäder ville icke bliva honom lydiga, utan stötte bort honom och vände sig med sina hjärtan mot Egypten');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 40, 'och sade till Aron: \'Gör oss gudar, som kunna gå framför oss; ty vi veta icke vad som har vederfarits denne Moses, som förde oss ut ur Egyptens land.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 41, 'Och de gjorde i de dagarna en kalv och buro sedan fram offer åt avguden och gladde sig över sina händers verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 42, 'Då vände Gud sig bort och prisgav dem till att dyrka himmelens härskara, såsom det är skrivet i Profeternas bok: \'Framburen I väl åt mig slaktoffer och spisoffer under de fyrtio åren i öknen, I av Israels hus?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 43, 'Nej, I buren Moloks tält och guden Romfas stjärna, de bilder som I hade gjort för att tillbedja. Därför skall jag låta eder föras åstad ända bortom Babylon.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 44, 'Våra fäder hade vittnesbördets tabernakel i öknen, så inrättat, som han som talade till Moses hade förordnat att denne skulle göra det, efter den mönsterbild som han hade fått se.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 45, 'Och våra fäder togo det i arv och förde det sedan under Josua hitin, när de togo landet i besittning, efter de folk som Gud fördrev för våra fäder. Så var det ända till Davids tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 46, 'Denne fann nåd inför Gud och bad att han måtte finna \'ett rum till boning\' åt Jakobs Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 47, 'Men det var Salomo som fick bygga ett hus åt honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 48, 'Dock, den Högste bor icke i hus som äro gjorda med händer, ty det är såsom profeten säger:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 49, '\'Himmelen är min tron, och jorden är min fotapall; vad för ett hus skullen I då kunna bygga åt mig, säger Herren, och vad för en plats skulle tjäna mig till vilostad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 50, 'Min hand har ju gjort allt detta.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 51, 'I hårdnackade, med oomskurna hjärtan och öron, I stån alltid emot den helige Ande, I likaväl som edra fäder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 52, 'Vilken av profeterna hava icke edra fäder förföljt? De hava ju dräpt dem som förkunnade att den Rättfärdige skulle komma, han som I själva nu haven förrått och dräpt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 53, 'I som fingen lagen eder given genom änglars försorg, men icke haven hållit den.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 54, 'När de hörde detta, blevo de mycket förbittrade i sina hjärtan och beto sina tänder samman mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 55, 'Men han, full av helig ande, skådade upp mot himmelen och fick se Guds härlighet och såg Jesus stå på Guds högra sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 56, 'Och han sade: »Jag ser himmelen öppen och Människosonen stå på Guds högra sida.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 57, 'Då skriade de med hög röst och höllo för sina öron och stormade alla på en gång emot honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 58, 'och förde honom ut ur staden och stenade honom. Och vittnena lade av sina mantlar vid en ung mans fötter, som hette Saulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 59, 'Så stenade de Stefanus, under det att han åkallade och sade: »Herre Jesus, tag emot min ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 60, 'Och han föll ned på sina knän och ropade med hög röst: »Herre, tillräkna dem icke denna synd.» Och när han hade sagt detta, avsomnade han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 1, 'Och jämväl Saulus hade gillat att man dödade honom. Samma dag utbröt en svår förföljelse mot församlingen i Jerusalem; och alla, utom apostlarna, blevo kringspridda över Judeens och Samariens landsbygd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 2, 'Några fromma män begrovo dock Stefanus och höllo en stor dödsklagan efter honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 3, 'Saulus åter for våldsamt fram mot församlingen; han gick omkring i husen och drog fram män och kvinnor och lät sätta dem i fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 4, 'Men de som hade blivit kringspridda gingo omkring och förkunnade evangelii ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 5, 'Och Filippus kom så ned till huvudstaden i Samarien och predikade Kristus för folket där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 6, 'Och när de hörde Filippus och sågo de tecken som han gjorde, aktade de endräktigt på det som han talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 7, 'Ty från många som voro besatta av orena andar foro andarna ut under höga rop, och många lama och ofärdiga blevo botade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 8, 'Och det blev stor glädje i den staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 9, 'Nu var där i staden före honom en man vid namn Simon, som hade övat trolldom, så att han hade slagit det samaritiska folket med häpnad, och som sade sig vara något stort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 10, 'Till honom höllo sig alla, både små och stora, och sade: »Denne är vad man kallar \'Guds stora kraft.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 11, 'Och de höllo sig till honom, därför att han genom sina trollkonster under ganska lång tid hade slagit dem med häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 12, 'Men nu, då de satte tro till Filippus, som förkunnade evangelium om Guds rike och om Jesu Kristi namn, läto de döpa sig, både män och kvinnor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 13, 'Ja, Simon själv kom till tro; och sedan han hade blivit döpt, höll han sig ständigt till Filippus. Och när han såg de stora tecken och kraftgärningar som denne gjorde, betogs han av häpnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 14, 'Då nu apostlarna i Jerusalem fingo höra att Samarien hade tagit emot Guds ord, sände de dit Petrus och Johannes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 15, 'Och när dessa kommo ditned, bådo de för dem, att de måtte undfå helig ande;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 16, 'ty helig ande hade ännu icke fallit på någon av dem, utan de voro allenast döpta i Herren Jesu namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 17, 'De lade då händerna på dem, och de undfingo helig ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 18, 'När då Simon såg att det var genom apostlarnas handpåläggning som Anden blev given, bjöd han dem penningar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 19, 'och sade: »Given ock mig den makten, så att var och en som jag lägger händerna på undfår helig ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 20, 'Då sade Petrus till honom: »Må dina penningar med dig själv gå i fördärvet, eftersom du menar att Guds gåva kan köpas för penningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 21, 'Du har ingen del eller lott i det som här är fråga om, ty ditt hjärta är icke rättsinnigt inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 22, 'Gör fördenskull bättring och upphör med denna din ondska, och bed till Herren att den tanke som har uppstått i ditt hjärta må, om möjligt är, bliva dig förlåten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 23, 'Ty jag ser att du är förgiftad av ondska och fången i orättfärdighetens bojor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 24, 'Då svarade Simon och sade: »Bedjen I till Herren för mig, att intet av det som I haven sagt må komma över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 25, 'Och sedan de hade framburit sitt vittnesbörd och talat Herrens ord, begåvo de sig tillbaka till Jerusalem och förkunnade därvid evangelium i många samaritiska byar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 26, 'Men en Herrens ängel talade till Filippus och sade: »Stå upp och begiv dig vid middagstiden ut på den väg som leder ned från Jerusalem till Gasa; den är tom på folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 27, 'Då stod han upp och begav sig åstad. Och se, en etiopisk man for där fram, en hovman som var en mäktig herre hos Kandace, drottningen i Etiopien, och var satt över hela hennes skattkammare. Denne hade kommit till Jerusalem för att där tillbedja,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 28, 'men var nu stadd på hemvägen och satt i sin vagn och läste profeten Esaias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 29, 'Då sade Anden till Filippus: »Gå fram och närma dig till denna vagn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 30, 'Filippus skyndade fram och hörde att han läste profeten Esaias. Då frågade han: »Förstår du vad du läser?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 31, 'Han svarade: »Huru skulle jag väl kunna förstå det, om ingen vägleder mig?» Och han bad Filippus stiga upp och sätta sig bredvid honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 32, 'Men det ställe i skriften som han läste var detta: »Såsom ett får fördes han bort till att slaktas; och såsom ett lamm som är tyst inför den som klipper det, så öppnade han icke sin mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 33, 'Genom hans förnedring blev hans dom borttagen. Vem kan räkna hans släkte? Ty hans liv ryckes undan från jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 34, 'Och hovmannen frågade Filippus och sade: »Jag beder dig, säg mig om vilken profeten talar detta, om sig själv eller om någon annan?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 35, 'Då öppnade Filippus sin mun och begynte med detta skriftens ord och förkunnade för honom evangelium om Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 36, 'Och medan de färdades vägen fram, kommo de till ett vatten. Då sade hovmannen: »Se, här finnes vatten. Vad hindrar att jag döpes?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 37, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 38, 'Och han lät vagnen stanna; och de stego båda ned i vattnet, Filippus och hovmannen, och han döpte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 39, 'Men när de hade stigit upp ur vattnet, ryckte Herrens Ande bort Filippus, och hovmannen såg honom icke mer, då han nu glad fortsatte sin färd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 40, 'Men Filippus blev efteråt sedd i Asdod. Därefter vandrade han omkring och förkunnade evangelium i alla städer, till dess han kom till Cesarea. [1] V. 37 se Nya testamentets text i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 1, 'Men Saulus, som alltjämt andades hot och mordlust mot Herrens lärjungar, gick till översteprästen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 2, 'och utbad sig av honom brev till synagogorna i Damaskus, för att, om han funne några som voro på »den vägen»[1], vare sig män eller kvinnor, han skulle kunna föra dem bundna till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 3, 'Men när han på sin färd nalkades Damaskus, hände sig att ett sken från himmelen plötsligt kringstrålade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 4, 'Och han föll ned till jorden och hörde då en röst som sade till honom: »Saul, Saul, varför förföljer du mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 5, 'Då sade han: »Vem är du, Herre?» Han svarade: »Jag är Jesus, den som du förföljer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 6, 'Men stå nu upp och gå in i staden, så skall där bliva dig sagt vad du har att göra.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 7, 'Och männen som voro med honom på färden stodo mållösa av skräck, ty de hörde väl rösten, men sågo ingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 8, 'Och Saulus reste sig upp från jorden, men när han öppnade sina ögon, kunde han icke mer se något. De togo honom därför vid handen och ledde honom in i Damaskus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 9, 'Och under tre dagar såg han intet; och han varken åt eller drack.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 10, 'Men i Damaskus fanns en lärjunge vid namn Ananias. Till honom sade Herren i en syn: »Ananias!» Han svarade: »Här är jag, Herre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 11, 'Och Herren sade till honom: »Stå upp och gå till den gata som kallas Raka gatan och fråga i Judas\' hus efter en man vid namn Saulus, från Tarsus. Ty se, han beder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 12, 'Och i en syn har han sett huru en man vid namn Ananias kom in och lade händerna på honom, för att han skulle få sin syn igen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 13, 'Då svarade Ananias: »Herre, jag har av många hört huru mycket ont den mannen har gjort dina heliga i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 14, 'Och han har nu här med sig fullmakt ifrån översteprästerna att fängsla alla dem som åkalla ditt namn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 15, 'Men Herren sade till honom: »Gå åstad; ty denne man är mig ett utvalt redskap till att bära fram mitt namn inför hedningar och konungar och inför Israels barn;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 16, 'och jag skall visa honom huru mycket han måste lida för mitt namns skull.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 17, 'Då gick Ananias åstad och kom in i huset; och han lade sina händer på honom och sade: »Saul, min broder, Herren har sänt mig, Jesus, som visade sig för dig på vägen där du färdades; han har sänt mig, för att du skall få din syn igen och bliva uppfylld av helig ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 18, 'Då var det strax såsom om fjäll föllo ifrån hans ögon, och han fick sin syn igen. Och han stod upp och lät döpa sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 19, 'Sedan tog han sig mat och blev därav stärkt. Därefter var han någon tid tillsammans med lärjungarna i Damaskus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 20, 'Och strax begynte han i synagogorna predika om Jesus, att han var Guds Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 21, 'Och alla som hörde honom blevo uppfyllda av häpnad och sade: »Var det icke denne som i Jerusalem förgjorde dem som åkallade det namnet? Och hade han icke kommit hit, för att han skulle föra sådana människor bundna till översteprästerna?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 22, 'Men Saulus uppträdde med allt större kraft och gjorde de judar som bodde i Damaskus svarslösa, i det han bevisade att Jesus var Messias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 23, 'När så en längre tid hade förgått, rådslogo judarna om att röja honom ur vägen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 24, 'men deras anslag blev bekant för Saulus. Och då de nu, för att kunna röja honom ur vägen, till och med höllo vakt vid stadsportarna både dag och natt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 25, 'togo hans lärjungar honom en natt och släppte honom ut genom muren, i det att de sänkte ned honom i en korg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 26, 'När han sedan kom till Jerusalem, försökte han att närma sig lärjungarna; men alla fruktade för honom, ty de trodde icke att han verkligen var en lärjunge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 27, 'Då tog Barnabas sig an honom och förde honom till apostlarna och förtäljde för dem huru han på vägen hade sett Herren, som hade talat till honom, och huru han i Damaskus hade frimodigt predikat i Jesu namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 28, 'Sedan gick han fritt ut och in bland dem i Jerusalem och predikade frimodigt i Herrens namn;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 29, 'och han talade och disputerade med de grekiska judarna. Men de gjorde försök att röja honom ur vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 30, 'När bröderna förnummo detta, förde de honom ned till Cesarea och sände honom därifrån vidare till Tarsus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 31, 'Så hade nu församlingen frid i hela Judeen och Galileen och Samarien; och den blev uppbyggd och vandrade i Herrens fruktan och växte till genom den helige Andes tröst och förmaning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 32, 'Medan nu Petrus vandrade omkring bland dem alla, hände sig att han ock kom ned till de heliga som bodde i Lydda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 33, 'Där träffade han på en man vid namn Eneas, som i åtta år hade legat till sängs; han var nämligen lam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 34, 'Och Petrus sade till honom: »Eneas, Jesus Kristus botar dig. Stå upp och lägg ihop din bädd.» Då stod han strax upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 35, 'Och alla som bodde i Lydda och i Saron sågo honom; och de omvände sig till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 36, 'I Joppe bodde då en lärjunginna vid namn Tabita (det betyder detsamma som Dorkas).[2] Hon överflödade i goda gärningar och gav allmosor rikligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 37, 'Men just i de dagarna hände sig att hon blev sjuk och dog. Och man tvådde henne och lade henne i en sal i övre våningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 38, 'Då nu Lydda låg nära Joppe och lärjungarna hade hört att Petrus var där, sände de två män till honom och bådo honom att utan dröjsmål komma till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 39, 'Petrus stod då upp och följde med dem. Och när han kom dit, förde de honom upp i salen; och alla änkorna kommo där omkring honom gråtande och visade honom alla livklädnader och mantlar som Dorkas hade gjord, medan hon ännu levde ibland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 40, 'Då tillsade Petrus dem allasammans att gå ut och föll ned på sina knän och bad; sedan vände han sig mot den döda och sade: »Tabita, stå upp.» Då slog hon upp ögonen, och när hon fick se Petrus, satte hon sig upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 41, 'Och han räckte henne handen och reste upp henne och kallade sedan in de heliga, jämte änkorna, och ställde henne levande framför den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 42, 'Detta blev bekant i hela Joppe, och många kommo till tro på Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 43, 'Därefter stannade han en längre tid i Joppe hos en garvare vid namn Simon. [1] Se Väg i Ordförkl. [2] Båda namnen betyda hind; det förra är ett arameiskt ord, det senare ett grekiskt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 1, 'I Cesarea bodde en man vid namn Kornelius, en hövitsman vid den så kallade italiska krigsskaran.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 2, 'Han var en from man, som »fruktade Gud»[1] tillika med hela sitt hus; han utdelade rikligen allmosor åt folket och bad alltid till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 3, 'En dag omkring nionde timmen såg denne tydligt i en syn en Guds ängel, som kom in till honom och sade till honom: »Kornelius!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 4, 'Han betraktade honom förskräckt och frågade: »Vad är det, herre?» Då sade ängeln till honom: »Dina böner och dina allmosor hava uppstigit till Gud och äro i åminnelse hos honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 5, 'Så sänd nu några män till Joppe och låt hämta en viss Simon, som ock kallas Petrus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 6, 'Han gästar hos en garvare vid namn Simon, som har ett hus vid havet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 7, 'När ängeln som hade talat med honom var borta, kallade han till sig två av sina tjänare och en from krigsman, en av dem som hörde till hans närmaste följe,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 8, 'och förtäljde alltsammans för dem och sände dem åstad till Joppe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 9, 'Men dagen därefter, medan dessa voro på vägen och nalkades staden, gick Petrus vid sjätte timmen upp på taket för att bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 10, 'Och han blev hungrig och ville hava något att äta. Medan man nu tillredde maten, föll han i hänryckning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 11, 'Han såg himmelen öppen och någonting komma ned som liknade en stor linneduk, och som fasthölls vid de fyra hörnen och sänktes ned till jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 12, 'Och däri funnos alla slags fyrfota och krälande djur som leva på jorden, och alla slags himmelens fåglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 13, 'Och en röst kom till honom: »Stå upp, Petrus, slakta och ät.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 14, 'Men Petrus svarade: »Bort det, Herre! Jag har aldrig ätit något oheligt och orent.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 15, 'Åter, för andra gången, kom en röst till honom: »Vad Gud har förklarat för rent, det må du icke hålla för oheligt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 16, 'Detta skedde tre gånger efter varandra; sedan blev duken strax åter upptagen till Himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 17, 'Medan Petrus i sitt sinne undrade över vad den syn han hade sett skulle betyda, hade de män som voro utsända av Kornelius redan frågat sig fram till Simons hus; och de stannade nu vid porten');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 18, 'och ropade på någon för att få veta om Simon, som ock kallades Petrus, gästade där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 19, 'Men under det Petrus alltjämt begrundade synen, sade Anden till honom: »Här äro ett par män som fråga efter dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 20, 'Stå upp, och gå ditned och följ med dem, utan att tveka; ty det är jag som har sänt dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 21, 'Då steg Petrus ned till männen och sade: »Se här är jag, den som I frågen efter. Av vilken orsak haven I kommit hit?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 22, 'De svarade: »Hövitsmannen Kornelius, en rättfärdig och gudfruktig man, som har gott vittnesbörd om sig av hela det judiska folket, har i en uppenbarelse fått befallning av en helig ängel att hämta dig till sig och höra vad du har att säga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 23, 'Då bjöd han dem komma in och beredde dem härbärge. Dagen därefter stod han upp och begav sig åstad med dem; och några av bröderna i Joppe följde med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 24, 'Följande dag kommo de fram till Cesarea. Och Kornelius väntade på dem och hade kallat tillhopa sina fränder och närmaste vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 25, 'Då nu Petrus skulle träda in, gick Kornelius emot honom och betygade honom sin vördnad, i det att han föll ned för hans fötter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 26, 'Men Petrus reste upp honom och sade: »Stå upp; också jag är en människa.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 27, 'Och under samtal med honom trädde Petrus in och fann många vara där församlade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 28, 'Och han sade till dem: »I veten själva att det är en judisk man förbjudet att hava något umgänge med en utlänning eller att besöka en sådan; men mig har Gud lärt att icke räkna någon människa för ohelig eller oren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 29, 'Därför kom jag ock utan invändning hit, när jag blev hämtad. Och nu frågar jag eder av vilket skäl I haven låtit hämta mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 30, 'Då svarade Kornelius: »Det är nu fjärde dagen sedan jag, just vid denna timme, förrättade i mitt hus den bön som man beder vid nionde timmen. Då fick jag se en man i skinande klädnad stå framför mig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 31, 'och han sade: \'Kornelius, din bön är hörd, och dina allmosor hava kommit i åminnelse inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 32, 'Så sänd nu bud till Joppe och kalla till dig Simon, som ock kallas Petrus: han gästar i garvaren Simons hus vid havet.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 33, 'Då sände jag strax bud till dig, och du gjorde väl i att du kom. Och nu äro vi alla här tillstädes inför Gud för att höra allt som har blivit dig befallt av Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 34, 'Då öppnade Petrus sin mun och sade: »Nu förnimmer jag i sanning att \'Gud icke har anseende till personen\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 35, 'utan att den som fruktar honom och övar rättfärdighet, han tages emot av honom, vilket folk han än må tillhöra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 36, 'Det ord som han har sänt till Israels barn för att genom Jesus Kristus, som är allas Herre, förkunna det glada budskapet om frid, det ordet kännen I,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 37, 'den förkunnelse som gick ut över hela Judeen, sedan den hade begynt i Galileen efter den döpelse Johannes predikade --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 38, 'förkunnelsen om Jesus från Nasaret och om huru Gud hade smort honom med helig ande och kraft, honom som vandrade omkring och gjorde gott och botade alla som voro under djävulens våld; ty Gud var med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 39, 'Vi kunna själva vittna om allt vad han gjorde både på den judiska landsbygden och i Jerusalem; likväl upphängde man honom på trä och dödade honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 40, 'Men honom har Gud uppväckt på tredje dagen och låtit honom bliva uppenbar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 41, 'väl icke för allt folket, men för oss, som redan förut av Gud hade blivit utvalda till vittnen, och som åto och drucko med honom, sedan han hade uppstått från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 42, 'Och han bjöd oss predika för folket och betyga att han är den som av Gud har blivit bestämd till att vara domare över levande och döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 43, 'Om honom bära alla profeterna vittnesbörd och betyga att var och en som tror på honom skall få syndernas förlåtelse genom hans namn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 44, 'Medan Petrus ännu så talade, föll den helige Ande på alla dem som hörde hans tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 45, 'Och alla de omskurna troende män som hade kommit dit med Petrus blevo uppfyllda av häpnad över att den helige Ande hade blivit utgjuten jämväl över hedningarna, såsom en gåva åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 46, 'De hörde dem nämligen tala tungomål och storligen prisa Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 47, 'Då tog Petrus till orda och sade: »Icke kan väl någon hindra att dessa döpas med vatten, då de hava undfått den helige Ande, de likaväl som vi?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 48, 'Och så bjöd han att man skulle döpa dem i Jesu Kristi namn. Därefter bådo de honom att han skulle stanna hos dem några dagar. [1] Se Frukta Gud i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 1, 'Men apostlarna och de bröder som voro i Judeen fingo höra att också hedningarna hade tagit emot Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 2, 'När så Petrus kom upp till Jerusalem, begynte de som voro omskurna gå till rätta med honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 3, 'de sade: »Du har ju besökt oomskurna män och ätit med dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 4, 'Då begynte Petrus från början och omtalade för dem allt i följd och ordning; han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 5, '»Jag var i staden Joppe, stadd i bön; då såg jag under hänryckning i en syn någonting komma ned, som liknade en stor linneduk, vilken fasthölls vid de fyra hörnen och sänktes ned från himmelen; och det kom ända ned till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 6, 'Och jag betraktade det och gav akt därpå; då fick jag däri se fyrfota djur, sådana som leva på jorden, tama och vilda, så ock krälande djur och himmelens fåglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 7, 'Jag hörde ock en röst säga till mig: \'Stå upp, Petrus, slakta och ät.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 8, 'Men jag svarade: \'Bort det, Herre! Aldrig har något oheligt eller orent kommit i min mun.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 9, 'För andra gången talade en röst från himmelen: \'Vad Gud har förklarat för rent, det må du icke hålla för oheligt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 10, 'Detta skedde tre gånger efter varandra; sedan drogs alltsammans åter upp till himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 11, 'Och i detsamma kommo tre män, som hade blivit sända till mig från Cesarea, och stannade framför huset där vi voro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 12, 'Och Anden sade till mig att jag skulle följa med dem, utan att göra någon åtskillnad mellan folk och folk. Också de sex bröder som äro här kommo med mig; och vi gingo in i mannens hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 13, 'Och han berättade för oss huru han hade sett ängeln träda in i hans hus, och att denne hade sagt: \'Sänd åstad till Joppe och låt hämta Simon, som ock kallas Petrus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 14, 'Han skall tala till dig ord genom vilka du skall bliva frälst, du själv och hela ditt hus.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 15, 'Och när jag hade begynt tala, föll den helige Ande på dem, alldeles såsom det under den första tiden skedde med oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 16, 'Då kom jag ihåg Herrens ord, huru han hade sagt: \'Johannes döpte med vatten, men I skolen bliva döpta i helig ande.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 17, 'Då alltså Gud åt dem hade givit samma gåva som åt oss, som hava kommit till tro på Herren Jesus Kristus, huru skulle då jag hava kunnat sätta mig emot Gud?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 18, 'När de hade hört detta, gåvo de sig till freds och prisade Gud och sade: »Så har då Gud också åt hedningarna förlänat den bättring som för till liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 19, 'De som hade blivit kringspridda genom den förföljelse som utbröt för Stefanus\' skull drogo emellertid omkring ända till Fenicien och Cypern och Antiokia, men förkunnade icke ordet för andra än för judar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 20, 'Dock funnos bland dem några män från Cypern och Cyrene, som när de kommo till Antiokia, också talade till grekerna och för dem förkunnade evangelium om Herren Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 21, 'Och Herrens hand var med dem, och en stor skara kom till tro och omvände sig till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 22, 'Ryktet härom nådde församlingen i Jerusalem; och de sände då Barnabas till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 23, 'När han kom dit och fick se vad Guds nåd hade verkat, blev han glad och förmanade dem alla att med hjärtats fasta föresats stadigt hålla sig till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 24, 'Ty han var en god man och full av helig ande och tro. Och ganska mycket folk blev ytterligare fört till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 25, 'Sedan begav han sig åstad till Tarsus för att uppsöka Saulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 26, 'Och när han hade träffat honom, tog han honom med sig till Antiokia. Ett helt år hade de sedan sin umgängelse inom församlingen och undervisade ganska mycket folk. Och det var i Antiokia som lärjungarna först begynte kallas »kristna».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 27, 'Vid den tiden kommo några profeter från Jerusalem ned till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 28, 'Och en av dem, vid namn Agabus, trädde upp och gav genom Andens ingivelse till känna att en stor hungersnöd skulle komma över hela världen; den kom också på Klaudius\' tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 29, 'Då bestämde lärjungarna att de, var och en efter sin förmåga, skulle sända något till understöd åt de bröder som bodde i Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 30, 'Detta gjorde de också, och genom Barnabas och Saulus översände de det till de äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 1, 'Vid den tiden lät konung Herodes gripa och misshandla några av dem som hörde till församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 2, 'Och Jakob, Johannes\' broder, lät han avrätta med svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 3, 'När han såg att detta behagade judarna, fortsatte han och lät fasttaga också Petrus. Detta skedde under det osyrade brödets högtid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 4, 'Och sedan han hade gripit honom, satte han honom i fängelse och uppdrog åt fyra vaktavdelningar krigsmän, vardera på fyra man, att bevaka honom; och hans avsikt var att efter påsken ställa honom fram inför folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 5, 'Under tiden förvarades Petrus i fängelset, men församlingen bad enträget till Gud för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 6, 'Natten före den dag då Herodes tänkte draga honom inför rätta låg Petrus och sov mellan två krigsmän, fängslad med två kedjor; och utanför dörren voro väktare utsatta till att bevaka fängelset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 7, 'Då stod plötsligt en Herrens ängel där, och ett sken lyste i rummet. Och han stötte Petrus i sidan och väckte honom och sade: »Stå nu strax upp»; och kedjorna föllo ifrån hans händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 8, 'Ängeln sade ytterligare till honom: »Omgjorda dig, och tag på dig dina sandaler.» Och han gjorde så. därefter sade ängeln till honom: »Tag din mantel på dig och följ mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 9, 'Och Petrus gick ut och följde honom; men han förstod icke att det som skedde genom ängeln var något verkligt, utan trodde att det var en syn han såg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 10, 'När de så hade gått genom första och andra vakten, kommo de till järnporten som ledde ut till staden. Den öppnade sig för dem av sig själv, och de trädde ut och gingo en gata fram; och i detsamma försvann ängeln ifrån honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 11, 'När sedan Petrus kom till sig igen, sade han: »Nu vet jag och är förvissad om att Herren har utsänt sin ängel och räddat mig ur Herodes\' hand och undan allt det som det judiska folket hade väntat sig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 12, 'När han alltså hade förstått huru det var, gick han till det hus där Maria bodde, hon som var moder till den Johannes som ock kallades Markus; där voro ganska många församlade och bådo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 13, 'Då han nu klappade på portdörren, kom en tjänsteflicka, vid namn Rode, för att höra vem det var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 14, 'Och när hon kände igen Petrus\' röst, öppnade hon i sin glädje icke porten, utan skyndade in och berättade att Petrus stod utanför porten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 15, 'Då sade de till henne: »Du är från dina sinnen.» Men hon bedyrade att det var såsom hon hade sagt. Då sade de: »Det är väl hans ängel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 16, 'Men Petrus fortfor att klappa; och när de öppnade, sågo de med häpnad att det var han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 17, 'Och han gav tecken åt dem med handen att de skulle tiga, och förtäljde för dem huru Herren hade fört honom ut ur fängelset. Och han tillade: »Låten Jakob och de andra bröderna få veta detta.» Sedan gick han därifrån och begav sig till en annan ort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 18, 'Men när det hade blivit dag, uppstod bland krigsmännen en ganska stor oro och undran över vad som hade blivit av Petrus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 19, 'När så Herodes ville hämta honom, men icke fann honom, anställde han rannsakning med väktarna och bjöd att de skulle föras bort till bestraffning. Därefter for han ned från Judeen till Cesarea och vistades sedan där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 20, 'Men han hade fattat stor ovilja mot tyrierna och sidonierna. Dessa infunno sig nu gemensamt hos honom; och sedan de hade fått Blastus, konungens kammarherre, på sin sida, bådo de om fred, ty deras land hade sin näring av konungens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 21, 'På utsatt dag klädde sig då Herodes i konungslig skrud och satte sig på tronen och höll ett tal till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 22, 'Då ropade folket: »En guds röst är detta, och icke en människas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 23, 'Men i detsamma slog honom en Herrens ängel, därför att han icke gav Gud äran. Och han föll i en sjukdom som bestod däri att han uppfrättes av maskar, och så gav han upp andan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 24, 'Men Guds ord hade framgång och utbredde sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 25, 'Och sedan Barnabas och Saulus hade fullgjort sitt uppdrag i Jerusalem och avlämnat understödet, vände de tillbaka och togo då med sig Johannes, som ock kallades Markus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 1, 'I den församling som fanns i Antiokia verkade nu såsom profeter och lärare Barnabas och Simeon, som kallades Niger, och Lucius från Cyrene, så ock Manaen, landsfursten Herodes\' fosterbroder[1], och Saulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 2, 'När dessa förrättade Herrens tjänst och fastade, sade den helige Ande: »Avskiljen åt mig Barnabas och Saulus för det verk som jag har kallat dem till.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 3, 'Då fastade de och bådo och lade händerna på dem och läto dem begiva sig åstad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 4, 'Dessa, som så hade blivit utsända av den helige Ande, foro nu ned till Seleucia och seglade därifrån till Cypern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 5, 'Och när de hade kommit till Salamis, förkunnade de Guds ord i judarnas synagogor. De hade också med sig Johannes såsom tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 6, 'Och sedan de hade färdats över hela ön ända till Pafos, träffade de där på en judisk trollkarl och falsk profet, vid namn Barjesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 7, 'som vistades hos landshövdingen Sergius Paulus. Denne var en förståndig man. Han kallade till sig Barnabas och Saulus och begärde att få höra Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 8, 'Men Elymas (eller trollkarlen, ty namnet har den betydelsen) stod emot dem och ville hindra landshövdingen från att komma till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 9, 'Saulus, som ock kallades Paulus, uppfylldes då av helig ande och fäste ögonen på honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 10, 'och sade: »O du djävulens barn, du som är full av allt slags svek och arglistighet och en fiende till allt vad rätt är, skall du då icke upphöra att förvrida Herrens raka vägar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 11, 'Se, nu kommer Herrens hand över dig, och du skall till en tid bliva blind och icke kunna se solen.» Och strax föll töcken och mörker över honom; och han gick omkring och sökte efter någon som kunde leda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 12, 'När då landshövdingen såg vad som hade skett, häpnade han över Herrens lära och kom till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 13, 'Paulus och hans följeslagare lade sedan ut ifrån Pafos och foro till Perge i Pamfylien. Där skilde sig Johannes ifrån dem och vände tillbaka till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 14, 'Men själva foro de vidare från Perge och kommo till Antiokia i Pisidien. Och på sabbatsdagen gingo de in i synagogan och satte sig där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 15, 'Och sedan man hade föreläst ur lagen och profeterna, sände synagogföreståndarna till dem och läto säga: »Bröder, haven I något förmaningens ord att säga till folket, så sägen det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 16, 'Då stod Paulus upp och gav tecken med handen och sade: »I män av Israels hus och I som \'frukten Gud\'[2], hören mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 17, 'Detta folks, Israels, Gud utvalde våra fäder, och han upphöjde detta folk, medan de ännu bodde såsom främlingar i Egyptens land, och förde dem sedan ut därifrån \'med upplyft arm\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 18, 'Och under en tid av vid pass fyrtio år hade han fördrag med dem i öknen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 19, 'Och sedan han hade utrotat sju folk i Kanaans land, utskiftade han dessas land till arvedelar åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 20, 'Därunder förgick en tid av vid pass fyra hundra femtio år. Sedan gav han dem domare, ända till profeten Samuels tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 21, 'Därefter begärde de en konung; och Gud gav dem Saul, Kis\' son, en man av Benjamins stam, för en tid av fyrtio år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 22, 'Men denne avsatte han och gjorde David till konung över dem. Honom gav han ock sitt vittnesbörd, i det han sade: \'Jag har funnit David, Jessais son, en man efter mitt hjärta. Han skall i alla stycken göra min vilja.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 23, 'Av dennes säd har Gud efter sitt löfte låtit Jesus komma, såsom Frälsare åt Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 24, 'Men redan innan han uppträdde, hade Johannes predikat bättringens döpelse för hela Israels folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 25, 'Och när Johannes höll på att fullborda sitt lopp, sade han: \'Vad I menen mig vara, det är jag icke. Men se, efter mig kommer den vilkens skor jag icke är värdig att lösa av han fötter.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 26, 'Mina bröder, I som ären barn av Abrahams släkt, så ock I andra här, I som \'frukten Gud\', till oss har ordet om denna frälsning blivit sänt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 27, 'Ty eftersom Jerusalems invånare och deras rådsherrar icke kände honom, uppfyllde de ock genom sin dom över honom profeternas utsagor, vilka var sabbat föreläses;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 28, 'och fastän de icke funno honom skyldig till något som förtjänade döden, bådo de likväl Pilatus att han skulle låta döda honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 29, 'När de så hade fört till fullbordan allt som var skrivet om honom, togo de honom ned från korsets trä och lade honom i en grav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 30, 'Men Gud uppväckte honom från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 31, 'Sedan visade han sig under många dagar för dem som med honom hade gått upp från Galileen till Jerusalem, och som nu äro hans vittnen inför folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 32, 'Och vi förkunna för eder det glada budskapet, att det löfte som gavs åt våra fäder, det har Gud låtit gå i fullbordan för oss, deras barn, därigenom att han har låtit Jesus uppstå,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 33, 'såsom ock är skrivet i andra psalmen: \'Du är min Son, jag har i dag fött dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 34, 'Och att han har låtit honom uppstå från de döda, så att han icke mer skall vända tillbaka till förgängelsen, det har han sagt med dessa ord: \'Jag skall uppfylla åt eder de heliga löften som jag i trofasthet har givit åt David.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 35, 'Därför säger han ock i en annan psalm: \'Du skall icke låta din Helige se förgängelsen.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 36, 'När David i sin tid hade tjänat Guds vilja, avsomnade han ju och blev samlad till sina fäder och såg förgängelsen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 37, 'men den som Gud har uppväckt, han har icke sett förgängelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 38, 'Så mån I nu veta, mena bröder, att genom honom syndernas förlåtelse förkunnas för eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 39, 'och att i honom var och en som tror bliver rättfärdig och friad ifrån allt det varifrån I icke under Moses\' lag kunden bliva friade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 40, 'Sen därför till, att över eder icke må komma det som är sagt hos profeterna:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 41, '\'Sen här, I föraktare, och förundren eder, och bliven till intet; ty en gärning utför jag i edra dagar, en gärning som I alls icke skullen tro, om den förtäljdes för eder.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 42, 'När de sedan gingo därifrån, bad men dem att de nästa sabbat skulle tala för dem om samma sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 43, 'Och när församlingen åtskildes, följde många judar och gudfruktiga proselyter med Paulus och Barnabas. Dessa talade då till dem och förmanade dem att stadigt hålla sig till Guds nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 44, 'Följande sabbat kom nästan hela staden tillsammans för att höra Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 45, 'Då nu judarna sågo det myckna folket, uppfylldes de av nitälskan och foro ut i smädelser och motsade det som Paulus talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 46, 'Då togo Paulus och Barnabas mod till sig och sade: »Guds ord måste i första rummet förkunnas för eder. Men eftersom I stöten det bort ifrån eder och icke akten eder själva värdiga det eviga livet, så vända vi oss nu till hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 47, 'Ty så har Herren bjudit oss: \'Jag har satt dig till ett ljus för hednafolken, för att du skall bliva till frälsning intill jordens ända.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 48, 'När hedningarna hörde detta, blevo de glada och prisade Herrens ord; och de kommo till tro, så många det var beskärt att få evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 49, 'Och Herrens ord utbredde sig över hela landet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 50, 'Men judarna uppeggade de ansedda kvinnor som »fruktade Gud», så ock de förnämsta männen i staden, och uppväckte en förföljelse mot Paulus och Barnabas och drevo dem bort ifrån sin stads område.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 51, 'Dessa skuddade då stoftet av sina fötter mot dem och begåvo sig till Ikonium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 52, 'Och lärjungarna uppfylldes alltmer av glädje och helig ande. [1] Se Fosterbroder i Ordförkl. [2] Se Frukta Gud i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 1, 'På samma sätt tillgick det i Ikonium: de gingo in i judarnas synagoga och talade så, att en stor hop av både judar och greker kommo till tro;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 2, 'men de judar som voro ohörsamma retade upp hedningarna och väckte deras förbittring mot bröderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 3, 'Så vistades de där en längre tid och predikade frimodigt, i förtröstan på Herren, och han gav vittnesbörd åt sitt nådesord, i det att han lät tecken och under ske genom dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 4, 'Men folket i staden delade sig, så att somliga höllo med judarna, andra åter med apostlarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 5, 'Och när sedan, både ibland hedningar och ibland judar med deras föreståndare, en storm hade blivit uppväckt emot dem, och man ville misshandla och stena dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 6, 'flydde de, så snart de förstodo huru det var, till städerna Lystra och Derbe i Lykaonien och till trakten omkring dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 7, 'Och där förkunnade de evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 8, 'I Lystra fanns nu en man som satt där oförmögen att bruka sina fötter, ty allt ifrån sin moders liv hade han varit ofärdig och hade aldrig kunnat gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 9, 'Denne hörde på, när Paulus talade. Och då Paulus fäste sina ögon på honom och såg att han hade tro, så att han kunde bliva botad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 10, 'sade han med hög röst: »Res dig upp och stå på dina fötter.» Då sprang mannen upp och begynte gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 11, 'När folket såg vad Paulus hade gjort, hovo de upp sin röst och ropade på lykaoniskt tungomål: »Gudarna hava stigit ned till oss i människogestalt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 12, 'Och de kallade Barnabas för Jupiter, men Paulus kallade de för Merkurius, eftersom det var han som förde ordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 13, 'Och prästen vid det Jupiterstempel som låg utanför staden förde fram tjurar och kransar till portarna och ville jämte folket anställa ett offer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 14, 'Men när apostlarna, Barnabas och Paulus, fingo höra detta, revo de sönder sina kläder och sprungo ut bland folket och ropade');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 15, 'och sade: »I män, vad är det I gören? Också vi äro människor, av samma natur som I, och vi förkunna för eder evangelium, att I måsten omvända eder från dessa fåfängliga avgudar till den levande Guden, \'som har gjort himmelen och jorden och havet och allt vad i dem är\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 16, 'Han har under framfarna släktens tider tillstatt alla hedningar att gå sina egna vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 17, 'Dock har han icke låtit sig vara utan vittnesbörd, ty han har bevisat eder välgärningar, i det han har givit eder regn och fruktbara tider från himmelen och så vederkvickt edra hjärtan med mat och glädje.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 18, 'Genom sådana ord stillade de med knapp nöd folket, så att man icke offrade åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 19, 'Men några judar kommo dit från Antiokia och Ikonium. Dessa drogo folket över på sin sida och stenade Paulus och släpade honom ut ur staden, i tanke att han var död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 20, 'Men sedan lärjungarna hade samlat sig omkring honom, reste han sig upp och gick in i staden. Dagen därefter begav han sig med Barnabas åstad därifrån till Derbe.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 21, 'Och de förkunnade evangelium i den staden och vunno ganska många lärjungar. Sedan vände de tillbaka till Lystra och Ikonium och Antiokia');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 22, 'och styrkte lärjungarnas själar, i det de förmanade dem att stå fasta i tron och sade dem, att det är genom mycken bedrövelse som vi måste ingå i Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 23, 'Därefter utvalde de åt dem »äldste» för var särskild församling och anbefallde dem efter bön och fastor åt Herren, som de nu trodde på.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 24, 'Sedan färdades de vidare genom Pisidien och kommo till Pamfylien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 25, 'Där förkunnade de ordet i Perge och foro sedan ned till Attalia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 26, 'Därifrån avseglade de till Antiokia, samma ort varifrån de hade blivit utsända, sedan man hade anbefallt dem åt Guds nåd, för det verk som de nu hade fullbordat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 27, 'Och när de hade kommit dit, kallade de tillhopa församlingen och omtalade för dem huru stora ting Gud hade gjort med dem, och huru han för hedningarna hade öppnat en dörr till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 28, 'Sedan vistades de där hos lärjungarna en ganska lång tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 1, 'Men från Judeen kommo några män ditned och lärde bröderna så: »Om I icke låten omskära eder, såsom Moses har stadgat, så kunnen I icke bliva frälsta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 2, 'Då uppstod söndring, och Paulus och Barnabas kommo i ett ganska skarpt ordskifte med dem. Det bestämdes därför, att Paulus och Barnabas och några andra av dem skulle, för denna tvistefrågas skull, fara upp till apostlarna och de äldste i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 3, 'Och församlingen utrustade dem för resan, och de foro genom Fenicien och Samarien och förtäljde utförligt om hedningarnas omvändelse och gjorde därmed alla bröderna stor glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 4, 'När de sedan kommo fram till Jerusalem, mottogos de av församlingen och av apostlarna och de äldste och omtalade huru stora ting Gud hade gjort med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 5, 'Men några ifrån fariséernas parti, vilka hade kommit till tro, stodo upp och sade att man borde omskära dem och bjuda dem att hålla Moses\' lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 6, 'Då trädde apostlarna och de äldste tillsammans för att överlägga om denna sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 7, 'Och sedan man länge hade förhandlat därom, stod Petrus upp och sade till dem: »Mina bröder, I veten själva att Gud, för lång tid sedan, bland eder utvalde mig att vara den genom vilkens mun hedningarna skulle få höra evangelii ord och komma till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 8, 'Och Gud, som känner allas hjärtan, gav dem sitt vittnesbörd, därigenom att han lät dem, likaväl som oss, undfå den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 9, 'Och han gjorde ingen åtskillnad mellan oss och dem, i det att han genom tron renade deras hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 10, 'Varför fresten I då nu Gud, genom att på lärjungarnas hals vilja lägga ett ok som varken våra fäder eller vi hava förmått bära?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 11, 'Vi tro ju fastmer att det är genom Herren Jesu nåd som vi bliva frälsta, vi likaväl som de.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 12, 'Då teg hela menigheten, och man hörde på Barnabas och Paulus, som förtäljde om huru stora tecken och under Gud genom dem hade gjort bland hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 13, 'När de hade slutat att tala, tog Jakob till orda och sade: »Mina bröder, hören mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 14, 'Simeon har förtäljt huru Gud först så skickade, att han bland hedningarna fick ett folk som kunde kallas efter hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 15, 'Därmed stämmer ock överens vad profeterna hava talat; ty så är skrivet:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 16, '\'Därefter skall jag komma tillbaka och åter bygga upp Davids förfallna hydda; ja, dess ruiner skall jag bygga upp och så upprätta den igen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 17, 'för att ock övriga människor skola söka Herren, alla hedningar som hava uppkallats efter mitt namn. Så säger Herren, han som skall göra detta,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 18, 'såsom han ock har vetat det förut av evighet.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 19, 'Därför är min mening att man icke bör betunga sådana som hava varit hedningar, men omvänt sig till Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 20, 'utan allenast skriva till dem att de skola avhålla sig från avgudastyggelser och från otukt och från köttet av förkvävda djur och från blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 21, 'Ty Moses har av ålder sina förkunnare i alla städer, då han ju var sabbat föreläses i synagogorna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 22, 'Därefter beslöto apostlarna och de äldste, tillika med hela församlingen, att bland sig utvälja några män, som jämte Paulus och Barnabas skulle sändas till Antiokia; och de valde Judas, som kallades Barsabbas, och Silas, vilka bland bröderna voro ledande män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 23, 'Och man översände genom dem följande skrivelse: »Apostlarna och de äldste, edra bröder, hälsa eder, I bröder av hednisk börd, som bon i Antiokia, Syrien och Cilicien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 24, 'Alldenstund vi hava hört att några som hava kommit från oss hava förvirrat eder med sitt tal och väckt oro i edra själar, utan att de hava haft något uppdrag av oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 25, 'så hava vi enhälligt kommit till det beslutet att utvälja några män, som vi skulle sända till eder jämte Barnabas och Paulus, våra älskade bröder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 26, 'vilka hava vågat sina liv för vår Herres, Jesu Kristi, namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 27, 'Alltså sända vi nu Judas och Silas, vilka ock muntligen skola kungöra detsamma för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 28, 'Den helige Ande och vi hava nämligen beslutit att icke pålägga eder någon ytterligare börda, utöver följande nödvändiga föreskrifter:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 29, 'att I skolen avhålla eder från avgudaofferskött och från blod och från köttet av förkvävda djur och från otukt. Om I noga tagen eder till vara för detta, så skall det gå eder väl. Faren väl.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 30, 'De fingo så begiva sig åstad och kommo ned till Antiokia. Där kallade de tillsammans menigheten och lämnade fram brevet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 31, 'Och när menigheten läste detta, blevo de glada över det hugnesamma budskapet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 32, 'Judas och Silas, som själva voro profeter, talade därefter många förmaningens ord till bröderna och styrkte dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 33, 'Och sedan de hade uppehållit sig där någon tid, fingo de i frid fara ifrån bröderna tillbaka till dem som hade sänt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 34, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 35, 'Men Paulus och Barnabas vistades fortfarande i Antiokia, där de undervisade och, jämte många andra förkunnade evangelii ord från Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 36, 'Efter någon tid sade Paulus till Barnabas: »Låt oss nu fara tillbaka och besöka våra bröder, i alla de städer där vi hava förkunnat Herrens ord, och se till, huru det är med dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 37, 'Barnabas ville då att de skulle taga med sig Johannes, som ock kallades Markus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 38, 'Men Paulus fann icke skäligt att taga med sig en man som hade övergivit dem i Pamfylien och icke följt med dem till deras arbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 39, 'Och så skarp blev deras tvist att de skilde sig ifrån varandra; och Barnabas tog med sig Markus och avseglade till Cypern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 40, 'Men Paulus utvalde åt sig Silas; och sedan han av bröderna hade blivit anbefalld åt Herrens nåd, begav han sig åstad');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 41, 'och färdades genom Syrien och Cilicien och styrkte församlingarna. [1] V. 34 se Nya testamentets text i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 1, 'Han kom då också till Derbe och till Lystra. Där fanns en lärjunge vid namn Timoteus, som var son av en troende judisk kvinna och en grekisk fader,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 2, 'och som hade gott vittnesbörd om sig av bröderna i Lystra och Ikonium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 3, 'Paulus ville nu att denne skulle fara med honom. För de judars skull som bodde i dessa trakter tog han honom därför till sig och omskar honom, ty alla visste att hans fader var grek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 4, 'Och när de sedan foro genom städerna, meddelade de församlingarna till efterföljd de stadgar som voro fastställda av apostlarna och de äldste i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 5, 'Så styrktes nu församlingarna i tron, och brödernas antal förökades för var dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 6, 'Sedan togo de vägen genom Frygien och det galatiska landet; de förhindrades nämligen av den helige Ande att förkunna ordet i provinsen Asien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 7, 'Och när de hade kommit fram emot Mysien, försökte de att fara in i Bitynien, men Jesu Ande tillstadde dem det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 8, 'Då begåvo de sig över Mysien ned till Troas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 9, 'Här visade sig för Paulus i en syn om natten en macedonisk man, som stod där och bad honom och sade: »Far över till Macedonien och hjälp oss.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 10, 'När han hade sett denna syn, sökte vi strax någon lägenhet att fara därifrån till Macedonien, ty vi förstodo nu att Gud hade kallat oss att förkunna evangelium för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 11, 'Vi lade alltså ut från Troas och foro raka vägen till Samotrace och dagen därefter till Neapolis');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 12, 'och sedan därifrån till Filippi. Denna stad, en romersk koloni, är den första i denna del av Macedonien. I den staden vistades vi någon tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 13, 'På sabbatsdagen gingo vi utom stadsporten, längs med en flod, till en plats som gällde såsom böneställe. Där satte vi oss ned och talade med de kvinnor som hade samlats dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 14, 'Och en kvinna som »fruktade Gud»[1], en purpurkrämerska från staden Tyatira, vid namn Lydia, lyssnade till samtalet; och Herren öppnade hennes hjärta, så att hon aktade på det som Paulus talade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 15, 'Och sedan hon jämte sitt husfolk hade låtit döpa sig, bad hon oss och sade: »Eftersom I ansen mig vara en kvinna som tror på Herren, så kommen in i mitt hus och stannen där.» Och hon nödgade oss därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 16, 'Och det hände sig en gång, då vi gingo ned till bönestället, att vi mötte en tjänsteflicka, som hade en spådomsande i sig och genom sina spådomar skaffade sina herrar mycken inkomst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 17, 'Denne följde efter Paulus och oss andra och ropade och sade: »Dessa män äro Guds, den Högstes, tjänare, och de förkunna för eder frälsningens väg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 18, 'Så gjorde hon under många dagar. Men Paulus tog illa vid sig och vände sig om och sade till anden: »I Jesu Kristi namn bjuder jag dig att fara ut ur henne.» Och anden for ut i samma stund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 19, 'Men när hennes herrar sågo att det för dem var slut med allt hopp om vidare inkomst, grepo de Paulus och Silas och släpade dem till torget inför överhetspersonerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 20, 'Och sedan de hade fört dem tid fram, till domarna, sade de: »Dessa män uppväcka stor oro i vår stad; de äro judar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 21, 'och vilja införa stadgar som det för oss, såsom romerska medborgare, icke är lovligt att antaga eller hålla.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 22, 'Också folket reste sig upp emot dem, och domarna läto slita av dem deras kläder och bjödo att man skulle piska dem med spön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 23, 'Och sedan de hade låtit giva dem många slag, kastade de dem i fängelse och bjödo fångvaktaren att hålla dem i säkert förvar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 24, 'Då denne fick en så sträng befallning, satte han in dem i det innersta fängelserummet och fastgjorde deras fötter i stocken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 25, 'Vid midnattstiden voro Paulus och Silas stadda i bön och lovade Gud med sång, och de andra fångarna hörde på dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 26, 'Då kom plötsligt en stark jordstöt, så att fängelsets grundvalar skakades; och i detsamma öppnades alla dörrar, och allas bojor löstes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 27, 'Då vaknade fångvaktaren; och när han fick se fängelsets dörrar öppna, drog han sitt svärd och ville döda sig själv, i tanke att fångarna hade kommit undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 28, 'Men Paulus ropade med hög röst och sade: »Gör dig intet ont; ty vi äro alla här.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 29, 'Då lät han hämta ljus och sprang in och föll ned för Paulus och Silas, bävande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 30, 'Därefter förde han ut dem och sade: »I herrar, vad skall jag göra för att bliva frälst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 31, 'De svarade: »Tro på Herren Jesus, så bliver du med ditt hus frälst.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 32, 'Och de förkunnade Guds ord för honom och för alla dem som voro i hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 33, 'Och redan under samma timme på natten tog han dem till sig och tvådde deras sår och lät strax döpa sig med allt sitt husfolk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 34, 'Och han förde dem upp i sitt hus och dukade ett bord åt dem och fröjdade sig över att han med allt sitt hus hade kommit till tro på Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 35, 'Men när det hade blivit dag, sände domarna åstad rättstjänarna och läto säga: »Släpp ut männen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 36, 'Fångvaktaren underrättade då Paulus härom och sade: »Domarna hava sänt bud att I skolen släppas ut. Gån därför nu eder väg i frid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 37, 'Men Paulus sade till dem: »De hava offentligen låtit gissla oss, utan dom och rannsakning, oss som äro romerska medborgare, och hava kastat oss i fängelse; nu vilja de också i tysthet släppa oss ut! Nej, icke så; de måste själva komma och taga oss ut.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 38, 'Rättstjänarna inberättade detta för domarna. När dessa hörde att de voro romerska medborgare, blevo de förskräckta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 39, 'Och de gingo dit och talade goda ord till dem och togo dem ut och bådo dem lämna staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 40, 'När de så hade kommit ut ur fängelset, begåvo de sig hem till Lydia. Och sedan de där hade träffat bröderna och talat förmaningens ord till dem, drogo de vidare. [1] Se Frukta Gud i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 1, 'Och de foro över Amfipolis och Apollonia och kommo så till Tessalonika. Där hade judarna en synagoga;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 2, 'i den gick Paulus in, såsom hans sed var. Och under tre sabbater talade han där med dem, i det han utgick ifrån skrifterna');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 3, 'och utlade dem och bevisade att Messias måste lida och uppstå från de döda; och han sade: »Denne Jesus som jag förkunnar för eder är Messias.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 4, 'Och några av dem läto övertyga sig och slöto sig till Paulus och Silas; så gjorde ock en stor hop greker som »fruktade Gud»[1], likaså ganska många av de förnämsta kvinnorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 5, 'Då grepos judarna av nitälskan och togo med sig allahanda dåligt folk ifrån gatan och ställde till folkskockning och oroligheter i staden och trängde fram mot Jasons hus och ville draga dem ut inför folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 6, 'Men när de icke funno dem, släpade de Jason och några av bröderna inför stadens styresmän och ropade: »Dessa män, som hava uppviglat hela världen, hava nu också kommit hit;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 7, 'och Jason har tagit emot dem i sitt hus. De göra alla tvärtemot kejsarens påbud och säga att en annan, en som heter Jesus, är konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 8, 'Så väckte de oro bland folket och hos stadens styresmän, när de hörde detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 9, 'Dessa läto då Jason och de andra ställa borgen för sig och släppte dem därefter lösa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 10, 'Men strax om natten blevo Paulus och Silas av bröderna sända åstad till Berea. Och när de hade kommit dit, gingo de till judarnas synagoga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 11, 'Dessa voro ädlare till sinnes än judarna i Tessalonika; de togo emot ordet med all villighet och rannsakade var dag skrifterna, för att se om det förhölle sig såsom nu sades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 12, 'Många av dem kommo därigenom till tro, likaså ganska många ansedda grekiska kvinnor och jämväl män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 13, 'Men när judarna i Tessalonika fingo veta att Guds ord förkunnades av Paulus också i Berea, kommo de dit och uppviglade också där folket och väckte oro bland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 14, 'Strax sände då bröderna Paulus åstad ända ned till havet, men både Silas och Timoteus stannade kvar på platsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 15, 'De som ledsagade Paulus förde honom vidare till Aten och foro så därifrån tillbaka, med bud till Silas och Timoteus att dessa med det snaraste skulle komma till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 16, 'Men, Paulus nu väntade på dem i Aten, upprördes han i sin ande, när han såg huru uppfylld staden var med avgudabilder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 17, 'Han höll därför i synagogan samtal med judarna och med dem som »fruktade Gud», så ock på torget, var dag, med dem som han träffade där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 18, 'Också några filosofer, dels av epikuréernas skola, dels av stoikernas, gåvo sig i ordskifte med honom. Och somliga sade: »Vad kan väl denne pratmakare vilja säga?» Andra åter: »Han tyckes vara en förkunnare av främmande gudar.» De sade så, eftersom han förkunnade evangelium om Jesus och om uppståndelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 19, 'Och de grepo honom och förde honom till Areopagen och sade: »Kunna vi få veta vad det är för en ny lära som du förkunnar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 20, 'Ty det är förunderliga ting som du talar oss i öronen. Vi vilja nu veta vad detta skall betyda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 21, 'Det var nämligen så med alla atenare, likasom ock med de främlingar som hade bosatt sig bland dem, att de icke hade tid och håg för annat än att tala om eller höra på något nytt för dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 22, 'Då trädde Paulus fram mitt på Areopagen och sade: »Atenare, jag ser av allting att I ären mycket ivriga gudsdyrkare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 23, 'Ty medan jag har gått omkring och betraktat edra helgedomar, har jag ock funnit ett altare med den inskriften: \'Åt en okänd Gud.\' Om just detta väsende, som I sålunda dyrken utan att känna det, är det jag nu kommer med budskap till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 24, 'Den Gud som har gjort världen och allt vad däri är, han som är Herre över himmel och jord, han bor icke i tempel som äro gjorda med händer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 25, 'ej heller låter han betjäna sig av människohänder, såsom vore han i behov av något, han som själv åt alla giver liv, anda och allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 26, 'Och han har skapat människosläktets alla folk, alla från en enda stamfader, till att bosätta sig utöver hela jorden; och han har fastställt för dem bestämda tider och utstakat de gränser inom vilka de skola bo --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 27, 'detta för att de skola söka Gud, om de till äventyrs skulle kunna treva sig fram till honom och finna honom; fastän han ju icke är långt ifrån någon enda av oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 28, 'Ty i honom är det som vi leva och röra oss och äro till, såsom ock några av edra egna skalder hava sagt: \'Vi äro ju ock av hans släkt.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 29, 'Äro vi nu av Guds släkt, så böra vi icke mena att gudomen är lik någonting av guld eller silver eller sten, något som är danat genom mänsklig konst och uppfinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 30, 'Med sådana okunnighetens tider har Gud hittills haft fördrag, men nu bjuder han människorna att de alla allestädes skola göra bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 31, 'Ty han har fastställt en dag då han skall \'döma världen med rättfärdighet\', genom en man som han har bestämt därtill; och han har åt alla givit en bekräftelse härpå, i det att han har låtit honom uppstå från de döda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 32, 'När de hörde talas om att »uppstå från de döda», drevo somliga gäck därmed, andra åter sade: »Vi vilja höra dig tala härom ännu en gång.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 33, 'Med detta besked gick Paulus bort ifrån dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 34, 'Dock slöto sig några män till honom och kommo till tro. Bland dessa var Dionysius, han som tillhörde Areopagens domstol, så ock en kvinna vid namn Damaris och några andra jämte dem. [1] Se Frukta Gud i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 1, 'Därefter lämnade Paulus Aten och kom till Korint.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 2, 'Där träffade han en jude vid namn Akvila, bördig från Pontus, vilken nyligen hade kommit från Italien med sin hustru Priscilla. (Klaudius hade nämligen påbjudit att alla judar skulle lämna Rom) Till dessa båda slöt han sig nu,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 3, 'och eftersom han hade samma hantverk som de, stannade han kvar hos dem, och de arbetade tillsammans; de voro nämligen till yrket tältmakare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 4, 'Och i synagogan höll han var sabbat samtal och övertygade både judar och greker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 5, 'När sedan Silas och Timoteus kommo ditned från Macedonien, var Paulus helt upptagen av att förkunna ordet, i det att han betygade för judarna att Jesus var Messias.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 6, 'Men när dessa stodo emot honom och foro ut i smädelser, skakade han stoftet av sina kläder och sade till dem: »Edert blod komme över edra egna huvuden. Jag är utan skuld och går nu till hedningarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 7, 'Och han gick därifrån och tog in hos en man vid namn Titius Justus, som »fruktade Gud»[1]; denne hade sitt hus invid synagogan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 8, 'Men Krispus, synagogföreståndaren, kom med hela sitt hus till tro på Herren; också många andra korintier som hörde honom trodde och läto döpa sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 9, 'Och i en syn om natten sade Herren till Paulus: »Frukta icke, utan tala och tig icke;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 10, 'ty jag är med dig, och ingen skall komma vid dig och göra dig skada. Jag har ock mycket folk i denna stad.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 11, 'Så uppehöll han sig där bland dem ett år och sex månader och undervisade i Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 12, 'Men när Gallio var landshövding i Akaja, reste sig judarna, alla tillhopa, upp mot Paulus och förde honom inför domstolen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 13, 'och sade: »Denne man förleder människorna att dyrka Gud på ett sätt som är emot lagen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 14, 'När då Paulus ville öppna sin mun och tala, sade Gallio till judarna: »Vore något brott eller något ont och arglistigt dåd begånget, då kunde väl vara skäligt att jag tålmodigt hörde på eder, I judar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 15, 'Men är det någon tvistefråga om ord och namn eller om eder egen lag, så mån I själva avgöra saken; i sådana mål vill jag icke vara domare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 16, 'Och så visade han bort dem från domstolen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 17, 'Då grepo de alla gemensamt Sostenes, synagogföreståndaren, och slogo honom inför domstolen; och Gallio frågade alls icke därefter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 18, 'Men Paulus stannade där ännu ganska länge. Därpå tog han avsked av bröderna och avseglade till Syrien, åtföljd av Priscilla och Akvila, sedan han i Kenkrea hade låtit raka sitt huvud; han hade nämligen bundit sig genom ett löfte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 19, 'Så kommo de till Efesus, och där lämnade Paulus dem. Själv gick han in i synagogan och gav sig i samtal med judarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 20, 'Och de bådo honom att han skulle stanna där något längre; men han samtyckte icke därtill,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 21, 'utan tog avsked av dem med de orden: »Om Gud vill, skall jag vända tillbaka till eder.» Och så lämnade han Efesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 22, 'Och när han hade kommit till Cesarea, begav han sig upp och hälsade på hos församlingen och for därefter ned till Antiokia.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 23, 'Sedan han hade uppehållit sig där någon tid, for han vidare, och färdades först genom det galatiska landet och därefter genom Frygien och styrkte alla lärjungarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 24, 'Men till Efesus kom en jude vid namn Apollos, bördig från Alexandria, en lärd man, mycket förfaren i skrifterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 25, 'Denne sade blivit undervisad om »Herrens väg»[2] och talade, brinnande i anden, och undervisade grundligt om Jesus, fastän han allenast hade kunskap om Johannes\' döpelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 26, 'Han begynte ock att frimodigt tala i synagogan. När Priscilla och Akvila hörde honom, togo de honom till sig och undervisade honom grundligare om »Guds väg».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 27, 'Och då han sedan ville fara till Akaja, skrevo bröderna till lärjungarna där och uppmanade dem att taga vänligt emot honom. Och när han hade kommit fram, blev han dem som trodde till mycken hjälp, genom den nåd han hade undfått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 28, 'Ty med stor kraft vederlade han judarna offentligen och bevisade genom skrifterna att Jesus var Messias. [1] Se Frukta Gud i Ordförkl. [2] Se Väg i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 1, 'Medan Apollos var i Korint, kom Paulus, sedan han hade farit genom de övre delarna av landet, ned till Efesus. Där träffade han några lärjungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 2, 'Och han frågade dessa: »Undfingen I helig ande, när I kommen till tro?» De svarade honom: »Nej, vi hava icke ens hört att helig ande är given.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 3, 'Han frågade: »Vilken döpelse bleven I då döpta med?» De svarade: »Vi döptes med Johannes\' döpelse»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 4, 'Då sade Paulus: »Johannes\' döpelse var en döpelse till bättring; och han sade därvid till folket, att det var på den som skulle komma efter honom, det är på Jesus, som de skulle tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 5, 'Sedan de hade hört detta, läto de döpa sig i Herren Jesu namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 6, 'Och när Paulus lade händerna på dem, kom den helige Ande över dem, och de talade tungomål och profeterade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 7, 'Och tillsammans voro de vid pass tolv män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 8, 'Därefter gick han in i synagogan; och under tre månader samtalade han där, frimodigt och övertygande, med dem om Guds rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 9, 'Men när några av dem förhärdade sig och voro ohörsamma och inför menigheten talade illa om »den vägen»[1], vände han sig ifrån dem och avskilde lärjungarna och samtalade sedan dagligen med dessa i Tyrannus\' lärosal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 10, 'Så fortgick det i två år, och alla provinsen Asiens inbyggare, både judar och greker, fingo på detta sätt höra Herrens ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 11, 'Och Gud gjorde genom Paulus kraftgärningar av icke vanligt slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 12, 'Man till och med tog handkläden och förkläden, som hade varit i beröring med hans kropp, och lade dem på de sjuka; och sjukdomarna veko då ifrån dem, och de onda andarna foro ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 13, 'Men också några kringvandrande judiska besvärjare företogo sig nu att över dem som voro besatta av onda andar nämna Herren Jesu namn; de sade: »Jag besvär eder vid den Jesus som Paulus predikar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 14, 'Bland dem som så gjorde voro sju söner av en viss Skevas, en judisk överstepräst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 15, 'Men den onde anden svarade då och sade till dem: »Jesus känner jag, Paulus är mig ock väl bekant men vilka ären I?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 16, 'Och mannen som var besatt av den onde anden störtade sig på dem och övermannade både den ene och den andre; han betedde sig så våldsamt mot dem, att de måste fly ut ur huset, nakna och sargade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 17, 'Och detta blev bekant för alla Efesus\' invånare, både judar och greker, och fruktan föll över dem alla, och Herren Jesu namn blev storligen prisat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 18, 'Och många av dem som hade kommit till tro trädde fram och bekände sin synd och omtalade vad de hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 19, 'Och ganska många av dem som hade övat vidskepliga konster samlade ihop sina böcker och brände upp dem i allas åsyn. Och när man räknade tillsammans vad böckerna voro värda, fann man att värdet uppgick till femtio tusen silverpenningar[2].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 20, 'På detta sätt hade Herrens ord mäktig framgång och visade sin kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 21, 'Efter allt detta bestämde sig Paulus genom Andens tillskyndelse, att över Macedonien och Akaja fara till Jerusalem. Och han sade: »Sedan jag har varit där, måste jag ock se Rom»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 22, 'Han sände då två av sina medhjälpare, Timoteus och Erastus, åstad till Macedonien, men själv stannade han ännu någon tid i provinsen Asien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 23, 'Vid den tiden uppstod ganska mycket oväsen angående »den vägen».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 24, 'Där fanns nämligen en guldsmed, vid namn Demetrius, som förfärdigade Dianatempel av silver och därmed skaffade hantverkarna en ganska stor inkomst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 25, 'Han kallade tillhopa dessa, jämte andra som hade liknande arbete, och sade: »I man, I veten att det är detta arbete som giver oss vår goda bärgning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 26, 'men nu sen och hören I att denne Paulus icke allenast i Efesus, utan i nästan hela provinsen Asien genom sitt tal har förlett ganska mycket folk, i det han säger att de gudar som göras med människohänder icke äro gudar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 27, 'Och det är fara värt, icke allenast att denna vår hantering kommer i missaktning, utan ock att den stora gudinnan Dianas helgedom bliver räknad för intet, och att jämväl denna gudinna, som hela provinsen Asien, ja, hela världen dyrkar, kommer att lida avbräck i sitt stora anseende.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 28, 'När de hörde detta, blevo de fulla av vrede och skriade: »Stor är efesiernas Diana!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 29, 'Och hela staden kom i rörelse, och alla stormade på en gång till skådebanan och släpade med sig Gajus och Aristarkus, två macedonier som voro Paulus\' följeslagare');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 30, 'Paulus ville då gå in bland folket men lärjungarna tillstadde honom det icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 31, 'Också några asiarker, som voro hans vänner, sände bud till honom och bådo honom att han icke skulle giva sig in på skådebanan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 32, 'Och de skriade, den ene så och den andre så; ty menigheten var upprörd, och de flesta visste icke varför de hade kommit tillsammans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 33, 'Då drog man ur folkhopen fram Alexander, som judarna sköto framför sig. Och Alexander gav tecken med handen att han ville hålla ett försvarstal inför folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 34, 'Men när de märkte att han var jude, begynte de ropa, alla med en mun, och skriade under ett par timmars tid: »Stor är efesiernas Diana!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 35, 'Men stadens kansler lugnade folket och sade: »Efesier, finnes då någon människa som icke vet, att efesiernas stad är vårdare av den stora Dianas tempel och den bild av henne, som har fallit ned från himmelen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 36, 'Eftersom ju ingen kan bestrida detta, bören I hålla eder lugna och icke företaga eder något förhastat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 37, 'Emellertid haven I dragit fram dessa män, som icke äro helgerånare, ej heller smäda vår gudinna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 38, 'Om nu Demetrius och de hantverkare som hålla ihop med honom hava sak mot någon, så finnas ju domstolssammanträden och landshövdingar. Må de alltså göra upp saken med varandra inför rätta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 39, 'Och haven I något att andraga som går därutöver, så må sådant avgöras i den lagliga folkförsamlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 40, 'På grund av det som i dag har skett löpa vi ju till och med fara att bliva anklagade för upplopp, fastän vi icke hava gjort något ont; och någon giltig anledning till denna folkskockning kunna vi icke heller uppgiva.» Med dessa ord fick han menigheten att skiljas åt. [1] Se Väg i Ordförkl. [2] Se Silverpenning i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 41, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 1, 'Då nu oroligheterna voro stillade, kallade Paulus lärjungarna till sig och talade till dem förmaningens ord; och sedan han hade tagit avsked av dem, begav han sig åstad för att fara till Macedonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 2, 'Och när han hade färdats genom det landet och jämväl där talat många förmaningens ord, kom han till Grekland.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 3, 'Där uppehöll han sig i tre månader. När han sedan tänkte avsegla därifrån till Syrien, beslöt han, eftersom judarna förehade något anslag mot honom, att göra återfärden genom Macedonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 4, 'Och med honom följde Sopater, Pyrrus\' son, från Berea, och av tessalonikerna Aristarkus och Sekundus, vidare Gajus från Derbe och Timoteus, slutligen Tykikus och Trofimus från provinsen Asien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 5, 'Men dessa foro i förväg och inväntade oss i Troas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 6, 'Sedan, efter det osyrade brödets högtid, avseglade vi andra ifrån Filippi och träffade dem på femte dagen åter i Troas; och där vistades vi i sju dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 7, 'På första veckodagen voro vi församlade till brödsbrytelse, och Paulus, som tänkte fara vidare dagen därefter, samtalade med bröderna. Och samtalet drog ut ända till midnattstiden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 8, 'och ganska många lampor voro tända i den sal i övre våningen, där vi voro församlade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 9, 'Invid fönstret satt då en yngling vid namn Eutykus, och när Paulus talade så länge, föll denne i djup sömn och blev så överväldigad av sömnen, att han störtade ned från tredje våningen; och när man tog upp honom, var han död');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 10, 'Då gick Paulus ned och lade sig över honom och fattade om honom och sade: »Klagen icke så; ty livet är ännu kvar i honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 11, 'Sedan gick han åter upp, och bröt brödet och åt, och samtalade ytterligare ganska länge med dem, ända till dess att det dagades; först då begav han sig i väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 12, 'Och de förde ynglingen hem levande och kände sig nu icke litet tröstade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 13, 'Men vi andra gingo i förväg ombord på skeppet och avseglade till Assos, där vi tänkte taga Paulus ombord; ty så hade han förordnat, eftersom han själv tänkte fara land vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 14, 'Och när han sammanträffade med oss i Assos, togo vi honom ombord och kommo sedan till Mitylene.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 15, 'Därifrån seglade vi vidare och kommo följande dag mitt för Kios. Dagen därefter lade vi till vid Samos; och sedan vi hade legat över i Trogyllium, kommo vi nästföljande dag till Miletus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 16, 'Paulus hade nämligen beslutit att segla förbi Efesus, för att icke fördröja sig i provinsen Asien; ty han påskyndade sin färd, för att, om det bleve honom möjligt, till pingstdagen kunna vara i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 17, 'Men från Miletus sände han bud till Efesus och kallade till sig församlingens äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 18, 'Och när de hade kommit till honom, sade han till dem: »I veten själva på vad sätt jag hela tiden, ifrån första dagen då jag kom till provinsen Asien, har umgåtts med eder:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 19, 'huru jag har tjänat Herren i all ödmjukhet, under tårar och prövningar, som hava vållats mig genom judarnas anslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 20, 'Och I veten att jag icke har dragit mig undan, när det gällde något som kunde vara eder nyttigt, och att jag icke har försummat att offentligen och hemma i husen predika för eder och undervisa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 21, 'Ty jag har allvarligt uppmanat både judar och greker att göra bättring och vända sig till Gud och tro på vår Herre Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 22, 'Och se, bunden i anden begiver jag mig nu till Jerusalem, utan att veta vad där skall vederfaras mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 23, 'allenast det vet jag, att den helige Ande i den ene staden efter den andra betygar för mig och säger att bojor och bedrövelser vänta mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 24, 'Dock anser jag mitt liv icke vara av något värde för mig själv, om jag blott får väl fullborda mitt lopp och vad som hör till det ämbete jag har mottagit av Herren Jesus: att vittna om Guds nåds evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 25, 'Och se, jag vet nu att I icke mer skolen få se mitt ansikte, I alla bland vilka jag har gått omkring och predikat om riket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 26, 'Därför betygar jag för eder nu i dag att jag icke bär skuld för någons blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 27, 'Ty jag har icke undandragit mig att förkunna för eder allt Guds rådslut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 28, 'Så haven nu akt på eder själva och på hela den hjord i vilken den helige Ande har satt eder till föreståndare, till att vara herdar för Guds församling, som han har vunnit med sitt eget blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 29, 'Jag vet, att sedan jag har skilts från eder svåra ulvar skola komma in bland eder, och att de icke skola skona hjorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 30, 'Ja, bland eder själva skola män uppträda, som tala vad förvänt är, för att locka lärjungarna att följa sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 31, 'Vaken därför, och kommen ihåg att jag i tre års tid, natt och dag, oavlåtligen under tårar har förmanat var och en särskild av eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 32, 'Och nu anbefaller jag eder åt Gud och hans nådesord, åt honom som förmår uppbygga eder och giva åt eder eder arvedel bland alla som äro helgade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 33, 'Silver eller guld eller kläder har jag icke åstundat av någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 34, 'I veten själva att dessa mina händer hava gjort tjänst, för att skaffa nödtorftigt uppehälle åt mig och åt dem som hava varit med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 35, 'I allt har jag genom mitt föredöme visat eder att man så, under eget arbete, bör taga sig an de svaga och komma ihåg Herren Jesu ord, huru han själv sade: \'Saligare är att giva än att taga.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 36, 'När han hade sagt detta, föll han ned på sina knän och bad med dem alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 37, 'Och de begynte alla att gråta bitterligen och föllo Paulus om halsen och kysste honom innerligt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 38, 'och mest sörjde de för det ordets skull som han hade sagt, att de icke mer skulle få se hans ansikte. Och så ledsagade de honom till skeppet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 1, 'Sedan vi hade skilts ifrån dem, lade vi ut och foro raka vägen till Kos och kommo dagen därefter till Rodus och därifrån till Patara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 2, 'Där funno vi ett skepp som skulle fara över till Fenicien; på det gingo vi ombord och lade ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 3, 'Och när vi hade fått Cypern i sikte, lämnade vi denna ö på vänster hand och seglade till Syrien och landade vid Tyrus; ty där skulle skeppet lossa sin last.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 4, 'Och vi uppsökte där lärjungarna och stannade hos dem i sju dagar. Dessa sade nu genom Andens tillskyndelse till Paulus att han icke borde begiva sig till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 5, 'Men när vi hade stannat där de dagarna ut, bröto vi upp därifrån och gåvo oss i väg, ledsagade av dem alla, med hustrur och barn, ända utom staden. Och på stranden föllo vi ned på våra knän och bådo');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 6, 'och togo sedan avsked av varandra. Därefter stego vi ombord på skeppet, och de andra vände tillbaka hem igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 7, 'Från Tyrus kommo vi till Ptolemais, och därmed avslutade vi sjöresan. Och vi hälsade på hos bröderna där och stannade hos dem en dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 8, 'Men följande dag begåvo vi oss därifrån och kommo till Cesarea. Där togo vi in hos evangelisten Filippus, en av de sju, och stannade kvar hos honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 9, 'Denne hade fyra ogifta döttrar, som ägde profetisk gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 10, 'Under den tid av flera dagar, som vi stannade där, kom en profet, vid namn Agabus, dit ned från Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 11, 'När denne hade kommit till oss, tog han Paulus\' bälte och band därmed sina händer och fötter och sade: »Så säger den helige Ande: \'Den man som detta bälte tillhör, honom skola judarna så binda i Jerusalem, och sedan skola de överlämna honom i hedningarnas händer.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 12, 'När vi hörde detta, bådo såväl vi själva som bröderna i staden honom att han icke skulle begiva sig upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 13, 'Men då svarade Paulus: »Varför gråten I så och sargen mitt hjärta? Jag är ju redo icke allenast att låta mig bindas, utan ock att dö i Jerusalem, för Herren Jesu namns skull.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 14, 'Då han alltså icke lät övertala sig, gåvo vi oss till freds och sade: »Ske Herrens vilja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 15, 'Efter de dagarnas förlopp gjorde vi oss i ordning och begåvo oss upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 16, 'Från Cesarea följde också några av lärjungarna med oss, och dessa förde oss till en viss Mnason från Cypern, en gammal lärjunge, som vi skulle gästa hos.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 17, 'Och när vi kommo till Jerusalem, togo bröderna emot oss med glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 18, 'Dagen därefter gick Paulus med oss andra till Jakob; dit kommo ock alla de äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 19, 'Och sedan han hade hälsat dem förtäljde han för dem alltsammans, det ena med det andra, som Gud genom hans arbete hade gjort bland hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 20, 'När de hörde detta, prisade de Gud. Och de sade till honom: »Du ser, käre broder, huru många tusen judar det är som hava kommit till tro, och alla nitälska de för lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 21, 'Nu har det blivit dem sagt om dig, att du lär alla judar som bo spridda bland hedningarna att avfalla från Moses, i det du säger att de icke behöva omskära sina barn, ej heller i övrigt vandra efter vad stadgat är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 22, 'Vad är då att göra? Helt visst skall man få höra att du har kommit hit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 23, 'Gör därför såsom vi nu vilja säga dig. Vi hava här fyra män som hava bundit sig genom ett löfte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 24, 'Tag med dig dessa, och låt helga dig tillsammans med dem, och åtag dig omkostnaderna för dem, så att de kunna låta raka sina huvuden. Då skola alla förstå att intet av allt det som har blivit dem sagt om dig äger någon grund, utan att också du vandrar efter lagen och håller den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 25, 'Vad åter angår de hedningar som hava kommit till tro, så hava vi här beslutit och jämväl skrivit till dem, att de böra taga sig till vara för kött från avgudaoffer och för blod och för köttet av förkvävda djur och för otukt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 26, 'Så tog då Paulus männen med sig och lät följande dag helga sig tillsammans med dem; sedan gick han in i helgedomen och gav till känna när den tid skulle gå till ända, för vilken de hade låtit helga sig, den tid före vars utgång offer skulle frambäras för var och en särskild av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 27, 'När de sju dagarna nästan voro ute, fingo judarna från provinsen Asien se honom i helgedomen och uppviglade då allt folket. Och de grepo honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 28, 'och ropade: »I män av Israel, kommen till hjälp! Här är den man som allestädes lär alla sådant som är emot vårt folk och emot lagen och emot denna plats. Därtill har han nu ock fört greker in i helgedomen och oskärat denna heliga plats.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 29, 'De hade nämligen förut sett efesiern Trofimus i staden tillsammans med honom och menade att Paulus hade fört denne in i helgedomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 30, 'Och hela staden kom i rörelse, och folket skockade sig tillsammans. Och då de nu hade gripit Paulus, släpade de honom ut ur helgedomen, varefter portarna genast stängdes igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 31, 'Men just som de stodo färdiga att dräpa honom, anmäldes det hos översten för den romerska vakten att hela Jerusalem var i uppror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 32, 'Denne tog då strax med sig krigsmän och hövitsmän och skyndade ned till dem. Och när de fingo se översten och krigsmännen, upphörde de att slå Paulus');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 33, 'Översten gick då fram och tog honom i förvar och bjöd att man skulle fängsla honom med två kedjor. Och han frågade vem han var och vad han hade gjort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 34, 'Men bland folket ropade den ene så, den andre så. Då han alltså för larmets skull icke kunde få något säkert besked, bjöd han att man skulle föra honom till kasernen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 35, 'Och när han kom fram till trappan, trängde folket så våldsamt på, att han måste bäras av krigsmännen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 36, 'ty folkhopen följde efter och skriade: »Bort med honom!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 37, 'Då nu Paulus skulle föras in i kasernen, sade han till översten: »Tillstädjes det mig att säga något till dig?» Han svarade: »Kan du tala grekiska?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 38, 'Är du då icke den egyptier som för en tid sedan ställde till \'dolkmännens\'[1] uppror, de fyra tusens, och förde dem ut i öknen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 39, 'Då svarade Paulus: »Nej, jag är en judisk man från Tarsus, medborgare alltså i en betydande stad i Cilicien. Men jag beder dig, tillstäd mig att tala till folket.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 40, 'Och han tillstadde honom det. Då gav Paulus från trappan, där han stod, med handen ett tecken åt folket. Och sedan där hade blivit helt tyst, talade han till dem på hebreiska[2] och sade: [1] Se Dolkmän i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 1, '»Bröder och fäder, hören vad jag nu inför eder vill tala till mitt försvar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 2, 'När de hörde att han talade till dem på hebreiska, blevo de ännu mer stilla. Och han fortsatte:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 3, '»Jag är en judisk man, född i Tarsus i Cilicien, men uppfostrad här i staden och undervisad vid Gamaliels fötter, efter fädernas lag i all dess stränghet. Och jag var en man som nitälskade för Gud, såsom I allasammans i dag gören.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 4, 'Jag förföljde \'den vägen\'[1] ända till döds, och både män och kvinnor lät jag binda och sätta i fängelse;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 5, 'det vittnesbördet kan översteprästen och de äldstes hela råd giva mig. Också fick jag av dem brev till bröderna i Damaskus; och jag begav mig dit, för att fängsla jämväl dem som voro där och föra dem till Jerusalem, så att de kunde bliva straffade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 6, 'Men när jag var på vägen och nalkades Damaskus, hände sig vid middagstiden att ett starkt sken från himmelen plötsligt kringstrålade mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 7, 'Och jag föll ned till marken och hörde då en röst som sade till mig: \'Saul, Saul, varför förföljer du mig?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 8, 'Då svarade jag: \'Vem är du, Herre?\' Han sade till mig: \'Jag är Jesus från Nasaret, den som du förföljer.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 9, 'Och de som voro med mig sågo väl skenet, men hörde icke rösten av den som talade till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 10, 'Då frågade jag: \'Vad skall jag göra, Herre?\' Och Herren svarade mig: \'Stå upp och gå in i Damaskus; där skall allt det bliva dig sagt, som är dig förelagt att göra.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 11, 'Men eftersom jag, till följd av det starka skenet, icke mer kunde se togo mina följeslagare mig vid handen och ledde mig, så att jag kom in i Damaskus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 12, 'Där fanns en efter lagen fram man, Ananias, vilken hade gott vittnesbörd om sig av alla judar som bodde där.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 13, 'Denne kom nu och trädde fram till mig och sade: \'Saul, min broder, hav din syn igen.\' Och i samma stund fick jag min syn igen och såg upp på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 14, 'Då sade han: \'Våra fäders Gud har utsett dig till att känna hans vilja och till att se den Rättfärdige och höra ord från hans mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 15, 'Ty du skall vara hans vittne inför alla människor och vittna om vad du har sett och hört.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 16, 'Varför dröjer du då nu? Stå upp och låt döpa dig och avtvå dina synder, och åkalla därvid hans namn.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 17, 'Men när jag hade kommit tillbaka till Jerusalem, hände sig, medan jag bad i helgedomen, att jag föll i hänryckning');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 18, 'och såg honom och hörde honom säga till mig: \'Skynda dig med hast bort ifrån Jerusalem; ty de skola icke här taga emot ditt vittnesbörd om mig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 19, 'Men jag sade: \'Herre, de veta själva att det var jag som överallt i synagogorna lät fängsla och gissla dem som trodde på dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 20, 'Och när Stefanus\', ditt vittnes, blod utgöts, var ock jag tillstädes och gillade vad som skedde och vaktade de mäns kläder, som dödade honom.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 21, 'Då sade han till mig: Gå; jag vill sända dig åstad långt bort till hedningarna.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 22, 'Ända till dess att han sade detta hade de hört på honom. Men nu hovo de upp sin röst och ropade: »Bort ifrån jorden med den människan! Det är icke tillbörligt att en sådan får leva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 23, 'Då de så skriade och därvid revo av sig sina kläder och kastade stoft upp i luften,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 24, 'bjöd översten att man skulle föra in honom i kasernen, och gav befallning om att man skulle förhöra honom under gisselslag, så att han finge veta varför de så ropade mot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 25, 'Men när de redan hade sträckt ut honom till gissling, sade Paulus till den hövitsman som stod där: »Är det lovligt för eder att gissla en romersk medborgare, och det utan dom och rannsakning?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 26, 'När hövitsmannen hörde detta, gick han till översten och underrättade honom härom och sade: »Vad är det du tänker göra? Mannen är ju romersk medborgare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 27, 'Då gick översten dit och frågade honom: »Säg mig, är du verkligen romersk medborgare?» Han svarade: »Ja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 28, 'Översten sade då: Mig har det kostat en stor summa penningar att köpa den medborgarrätten.» Men Paulus sade: »Jag däremot har den redan genom födelsen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 29, 'Männen som skulle hava förhört honom drogo sig då strax undan och lämnade honom. Och när översten nu hade fått veta att han var romersk medborgare, blev också han förskräckt, vid tanken på att han hade låtit fängsla honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 30, 'Då han emellertid ville få säkert besked om varför Paulus anklagades av judarna, låt han dagen därefter taga av honom bojorna och bjöd översteprästerna och hela Stora rådet att komma tillsammans. Sedan lät han föra Paulus ditned och ställde honom inför dem. [1] Se Väg i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 1, 'Och Paulus fäste ögonen på Rådet och sade: »Mina bröder, allt intill denna dag har jag vandrat inför Gud med ett i allo gott samvete.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 2, 'Då befallde översteprästen Ananias dem som stodo bredvid honom, att de skulle slå honom på munnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 3, 'Paulus sade då till honom: »Gud skall slå dig, du vitmenade vägg. Du sitter här för att döma mig efter lagen, och ändå bjuder du, tvärtemot lagen, att man skall slå mig!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 4, 'Då sade de som stodo därbredvid: »Smädar du Guds överstepräst?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 5, 'Paulus svarade: »Jag visste icke, mina bröder, att han var överstepräst. Det är ju skrivet: \'Mot en hövding i ditt folk skall du icke tala onda ord.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 6, 'Nu hade Paulus märkt att den ena delen av dem utgjordes av sadducéer och den andra av fariséer. Därför sade han med ljudelig röst inför Rådet: »Mina bröder, jag är farisé, en avkomling av fariséer. Det är för vårt hopps skull, för de dödas uppståndelses skull, som jag står här inför rätta.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 7, 'Knappt hade han sagt detta, förrän en strid uppstod mellan fariséerna och sadducéerna, så att hopen blev delad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 8, 'Sadducéerna säga nämligen att det icke finnes någon uppståndelse, ej heller någon ängel eller ande, men fariséerna bekänna sig tro på både det ena och det andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 9, 'Och man begynte ropa och larma; och några skriftlärde som hörde till fariséernas parti stodo upp och begynte ivrigt disputera med de andra och sade: »Vi finna intet ont hos denne man. Kanhända har en ande eller en ängel verkligen talat med honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 10, 'Då nu en så häftig strid hade uppstått, fruktade översten att de skulle slita Paulus i stycken, och bjöd manskapet gå ned och rycka honom undan dem och föra honom till kasernen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 11, 'Natten därefter kom Herren och stod framför honom och sade: »Var vid gott mod; ty såsom du har vittnat om mig i Jerusalem, så måste du ock vittna i Rom»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 12, 'När det sedan hade blivit dag, sammangaddade sig judarna och förpliktade sig med dyr ed att varken äta eller dricka, förrän de hade dräpt Paulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 13, 'Och det var mer än fyrtio män som så hade sammansvurit sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 14, 'Dessa gingo till översteprästerna och de äldste och sade: »Vi hava med dyr ed förpliktat oss att ingenting smaka, förrän vi hava dräpt Paulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 15, 'Så mån I nu, tillsammans med Rådet, hemställa hos översten att han låter föra honom ned till eder, detta under föregivande att I tänken grundligare undersöka hans sak. Vi skola då vara redo att röja honom ur vägen, innan han hinner fram.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 16, 'Men Paulus\' systerson fick höra om försåtet. Han kom därför till kasernen och gick ditin och omtalade för Paulus vad han hade hört.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 17, 'Paulus bad då att en av hövitsmännen skulle komma till honom, och sade: »För denne yngling till översten; ty han har en underrättelse att lämna honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 18, 'Denne tog honom då med sig och förde honom till översten och sade: »Fången Paulus har kallat mig till sig och bett mig föra denne yngling till dig, ty han har något att säga dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 19, 'Då tog översten honom vid handen och gick avsides med honom och frågade honom: »Vad är det för en underrättelse du har att lämna mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 20, 'Han svarade: »Judarna hava kommit överens om att bedja dig att du i morgon låter föra Paulus ned till Rådet, detta under föregivande att det tänker skaffa sig grundligare kunskap om honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 21, 'Gör dem nu icke till viljes häri; ty mer än fyrtio av dem ligga i försåt för honom och hava med dyr ed förpliktat sig att varken äta eller dricka, förrän de hava röjt honom ur vägen. Och nu äro de redo och vänta allenast på att du skall bevilja deras begäran.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 22, 'Översten bjöd då ynglingen att icke för någon omtala att han hade yppat detta för honom, och lät honom sedan gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 23, 'Därefter kallade han till sig två av hövitsmännen och sade till dem: »Låten två hundra krigsmän göra sig redo att i natt vid tredje timmen avgå till Cesarea, så ock sjuttio ryttare och två hundra spjutbärare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 24, 'Och han tillsade dem att skaffa åsnor, som de skulle låta Paulus rida på så att han oskadd kunde föras till landshövdingen Felix.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 25, 'Och han skrev ett brev, så lydande:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 26, '»Klaudius Lysias hälsar den ädle landshövdingen Felix.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 27, 'Denne man blev gripen av judarna, och det var nära att han hade blivit dödad av dem. Då kom jag tillstädes med mitt manskap och tog honom ifrån dem, sedan jag hade fått veta att han var romersk medborgare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 28, 'Men då jag också ville veta vad de anklagade honom för, lät jag ställa honom inför deras Stora råd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 29, 'Jag fann då att anklagelsen mot honom gällde några tvistefrågor i deras lag, men att han icke var anklagad för något som förtjänade död eller fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 30, 'Sedan har jag fått kännedom om att något anslag förehaves mot honom, och därför sänder jag honom nu strax till dig. Jag har jämväl bjudit hans anklagare att inför dig föra sin talan mot honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 31, 'Så togo nu krigsmännen Paulus, såsom det hade blivit dem befallt, och förde honom om natten till Antipatris.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 32, 'Dagen därefter vände de själva tillbaka till kasernen och läto ryttarna färdas vidare med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 33, 'När dessa kommo till Cesarea, lämnade de fram brevet till landshövdingen och förde jämväl Paulus fram inför honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 34, 'Sedan han hade läst brevet, frågade han från vilket landskap han var; och när han hade fått veta att han var från Cilicien, sade han:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 35, '»Jag skall höra vad du har att säga, när också dina anklagare hava kommit tillstädes.» Och så bjöd han att man skulle förvara honom i Herodes\' borg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 1, 'Fem dagar därefter for översteprästen Ananias ditned med några av de äldste och en sakförare, Tertullus; dessa anmälde inför landshövdingen klagomål mot Paulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 2, 'Och sedan denne hade blivit förekallad, begynte Tertullus sitt anklagelsetal; han sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 3, '»Att vi genom dig åtnjuta mycken frid och ro, och att genom din försorg, ädle Felix, goda åtgärder hava blivit vidtagna för detta folk, det erkänna vi på allt sätt och allestädes, med många tacksägelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 4, 'Men för att icke alltför länge besvära dig beder jag att du, i din mildhet, ville höra allenast några få ord av oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 5, 'Vi hava funnit att denne är en fördärvlig man, som uppväcker strid bland alla judar i hela världen, och att han är en huvudman för nasaréernas parti.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 6, 'Han har ock försökt att oskära helgedomen; därför grepo vi honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 7, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 8, 'och du kan nu själv anställa rannsakning med honom och så skaffa dig kännedom om allt det som vi anklaga honom för.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 9, 'De andra judarna instämde häri och påstodo att det förhöll sig så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 10, 'Då landshövdingen nu gav tecken åt Paulus att han skulle tala, tog han till orda och sade: »Eftersom jag vet att du nu i många år har varit domare över detta folk, försvarar jag min sak med frimodighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 11, 'Du kan själv lätt förvissa dig om att det icke är mer än tolv dagar sedan jag kom upp till Jerusalem för att tillbedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 12, 'Och varken i helgedomen eller i synagogorna eller ute i staden har man funnit mig tvista med någon eller ställa till folkskockning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 13, 'Ej heller kunna de inför dig bevisa det som de nu anklaga mig för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 14, 'Men det bekänner jag för dig att jag, i enlighet med \'den vägen\'[2], vilken de kalla en partimening, så tjänar mina fäders Gud, att jag tror allt vad som är skrivet i lagen och i profeterna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 15, 'och att jag har samma hopp till Gud som dessa hysa, att de döda skola uppstå, både rättfärdiga och orättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 16, 'Därför lägger också jag mig vinn om att alltid hava ett okränkt samvete inför Gud och människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 17, 'Så kom jag nu, efter flera års förlopp, tillbaka för att överlämna några allmosor till mitt folk och för att frambära offer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 18, 'Därunder påträffades jag i helgedomen, sedan jag hade låtit helga mig, utan att hava vållat någon folkskockning eller något larm,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 19, 'av några judar från provinsen Asien, vilka nu borde vara här tillstädes inför dig och framställa sina klagomål, om de hava något att anklaga mig för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 20, 'Eller ock må dessa som äro här tillstädes säga vad orätt de funno mig skyldig till, när jag stod inför Stora rådet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 21, 'om det icke skulle vara i fråga om detta enda ord, som jag ljudeligen uttalade, där jag stod ibland dem: \'Det är för de dödas uppståndelses skull som jag i dag står inför rätta här bland eder.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 22, 'Men Felix, som mycket väl kände till »den vägen»[3], uppsköt målet och sade: »När översten Lysias kommer hit ned, vill jag undersöka eder sak.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 23, 'Och han befallde hövitsmannen att hålla honom i förvar, dock så, att man skulle behandla honom milt och icke hindra någon av hans närmaste från att vara honom till tjänst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 24, 'Någon tid därefter infann sig Felix tillsammans med sin hustru Drusilla, som var judinna; och han lät hämta Paulus och hörde honom om tron på Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 25, 'Men när Paulus talade med dem om rättfärdighet och återhållsamhet och om den tillstundande domen, blev Felix förskräckt och sade: »Gå din väg för denna gång; när jag får läglig tid, vill jag kalla dig till mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 26, 'Han hoppades också att han skulle få penningar av Paulus, varför han ock ganska ofta lät hämta honom och samtalade med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 27, 'När två år voro förlidna, fick Felix till efterträdare Porcius Festus. Och eftersom Felix ville göra judarna sig bevågna, lämnade han Paulus kvar i fängelset. [1] V. 7 se Nya testamentets text i Ordförkl. [2] Se Väg i Ordförkl. [3] Se Väg i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 1, 'Tre dagar efter det att Festus hade tillträtt hövdingdömet for han från Cesarea upp till Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 2, 'Översteprästerna och de förnämsta bland judarna anmälde då inför honom klagomål mot Paulus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 3, 'För att få denne i sitt våld anhöllo de hos Festus och begärde såsom en ynnest, att han skulle låta hämta honom till Jerusalem. De ville nämligen lägga försåt för honom, så att de kunde döda honom under vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 4, 'Festus svarade då att Paulus hölls i förvar i Cesarea, och att han själv tänkte inom kort fara dit tillbaka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 5, 'Och han tillade: »De bland eder som det vederbör må alltså fara dit ned med mig och framlägga sin anklagelse mot mannen, om han är skyldig till något ont.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 6, 'Sedan han hade vistats hos dem högst åtta eller tio dagar, kom han åter ned till Cesarea. Dagen därefter satte han sig på domarsätet och bjöd att Paulus skulle föras fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 7, 'När denne hade infunnit sig, omringades han av de judar som hade kommit ned från Jerusalem, och dessa framställde nu många svåra beskyllningar. Men de förmådde icke bevisa dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 8, 'ty Paulus försvarade sig och visade att han icke på något sätt hade försyndat sig, vare sig mot judarnas lag eller mot helgedomen eller mot kejsaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 9, 'Men Festus ville göra judarna sig bevågna och frågade Paulus och sade: »Vill du fara upp till Jerusalem och där stå till rätta inför mig i denna sak?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 10, 'Paulus svarade: »Jag står här inför kejserlig domstol, och av sådan domstol bör jag dömas. Mot judarna har jag intet orätt gjort, såsom du själv mycket väl vet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 11, 'Om jag nu eljest är skyldig till något orätt och har gjort något som förtjänar döden, så vill jag icke undandraga mig att dö; men om deras anklagelser mot mig äro utan grund, så kan ingen giva mig till pris åt dem. Jag vädjar till kejsaren.» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 12, 'Sedan Festus därefter hade överlagt med sitt råd, svarade han: »Till kejsaren har du vädjat, till kejsaren skall du ock få fara.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 13, 'Efter några dagars förlopp kommo konung Agrippa och Bernice till Cesarea och hälsade på hos Festus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 14, 'Medan de nu i flera dagar vistades där, framlade Festus Paulus\' sak för konungen och sade: »Felix har här lämnat efter sig en man såsom fånge;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 15, 'och när jag var i Jerusalem, anmälde judarnas överstepräster och äldste klagomål mot honom och begärde att han skulle dömas skyldig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 16, 'Men jag svarade dem att det icke var romersk sed att prisgiva någon människa, förrän den anklagade hade fått stå ansikte mot ansikte med sina anklagare och haft tillfälle att försvara sig mot anklagelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 17, 'Sedan de hade kommit med mig hit, satte jag mig alltså utan uppskov, dagen därefter, på domarsätet och bjöd att mannen skulle föras fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 18, 'Men när hans anklagare uppträdde, anförde de mot honom ingen beskyllning för sådana förbrytelser som jag hade tänkt mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 19, 'de voro allenast i tvist med honom om några frågor som rörde deras särskilda gudsdyrkan, och angående en viss Jesus, som är död, men om vilken Paulus påstod att han lever.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 20, 'Då jag var villrådig huru jag skulle göra med undersökningen härom, frågade jag om han ville fara till Jerusalem och där stå till rätta i denna sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 21, 'När Paulus då sade sig vilja vädja till kejsaren och begärde att bliva hållen i förvar, för att sedan undergå rannsakning inför honom, bjöd jag att han skulle hållas i förvar, till dess jag kunde sända honom till kejsaren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 22, 'Då sade Agrippa till Festus: »Jag skulle också själv gärna vilja höra den mannen.» Han svarade: »I morgon skall du få höra honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 23, 'Dagen därefter kommo alltså Agrippa och Bernice, med stor ståt, och gingo in i domsalen, tillika med överstarna och de förnämsta männen i staden; och på Festus\' befallning blev Paulus införd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 24, 'Då sade Festus: »Konung Agrippa, och alla I andra som ären har tillstädes med oss, I sen här den man för vilkens skull hela hopen av judar, både i Jerusalem och här, har legat över mig med sina rop att han icke borde få leva längre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 25, 'Jag för min del har kommit till insikt om att han icke har gjort något som förtjänar döden;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 26, 'men då han nu själv har vädjat till kejsaren, har jag beslutit att sända honom till denne. Jag har emellertid icke något säkert besked om honom att giva min höge herre, när jag skriver. Därför har jag fört honom fram inför eder, och först och främst inför dig, konung Agrippa, för att jag, efter det att rannsakning har; blivit hållen, skall få veta vad jag bör skriva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 27, 'Ty det synes mig vara orimligt att sända åstad en fånge, utan att på samma gång giva till känna vad han är anklagad för.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 1, 'Agrippa sade nu till Paulus: »Det tillstädjes dig att tala för din sak.» Då räckte Paulus ut handen och talade så till sitt försvar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 2, '»Jag skattar mig lycklig att jag, i fråga om allt det som judarna anklaga mig för, i dag skall försvara mig inför dig, konung Agrippa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 3, 'som så väl känner judarnas alla stadgar och tvistefrågor. Därför beder jag dig höra mig med tålamod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 4, 'Hurudant mitt liv allt ifrån ungdomen har varit, det veta alla judar, ty jag har ju från tidiga år framlevat det bland mitt folk och i Jerusalem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 5, 'Och sedan lång tid tillbaka känna de om mig -- såframt de nu vilja tillstå det -- att jag har tillhört det strängaste partiet i vår gudsdyrkan och levat såsom farisé.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 6, 'Och nu står jag här till rätta för vårt hopp om det som Gud har lovat våra fäder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 7, 'det vartill ock våra tolv stammar, under det de tjäna Gud med iver både natt och dag, hoppas att nå fram. För det hoppets skull, o konung, är jag anklagad av judarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 8, 'Varför hålles det då bland eder för otroligt att Gud uppväcker döda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 9, 'Jag för min del menade alltså att jag med all makt borde strida mot Jesu, nasaréens, namn;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 10, 'så gjorde jag ock i Jerusalem. Och många av de heliga inspärrade jag i fängelse, sedan jag av översteprästerna hade fått fullmakt därtill; och när man ville döda dem, röstade ock jag därför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 11, 'Och överallt i synagogorna försökte jag, gång på gång, att genom straff tvinga dem till hädelse. I mitt raseri mot dem gick jag så långt, att jag förföljde dem till och med ända in i utländska städer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 12, 'När jag nu i detta ärende var på väg till Damaskus, med fullmakt och uppdrag från översteprästerna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 13, 'fick jag under min färd, o konung, mitt på dagen se ett sken från himmelen, klarare än solens glans, kringstråla mig och mina följeslagare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 14, 'Och vi föllo alla ned till jorden, och jag hörde då en röst säga till mig på hebreiska: \'Saul, Saul, varför förföljer du mig\'? Det är dig svårt att spjärna mot udden.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 15, 'Då sade jag: \'Vem är du, Herre?\' Herren svarade: \'Jag är Jesus, den som du förföljer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 16, 'Men res dig upp och stå på dina fötter; ty därför har jag visat mig för dig, att jag har velat utse dig till en tjänare och ett vittne, som skall vittna både om huru du nu har sett mig, och om huru jag vidare skall uppenbara mig för dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 17, 'Och jag skall rädda dig såväl från ditt eget folk som från hedningarna. Ty till dem sänder jag dig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 18, 'för att du skall öppna deras ögon, så att de omvända sig från mörkret till ljuset, och från Satans makt till Gud, på det att de må, genom tron på mig, undfå syndernas förlåtelse och få sin lott bland dem som äro helgade.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 19, 'Så blev jag då, konung Agrippa, icke ohörsam mot den himmelska synen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 20, 'utan predikade först för dem som voro i Damaskus och i Jerusalem, och sedan över hela judiska landet och för hedningarna, att de skulle göra bättring och omvända sig till Gud och göra sådana gärningar som tillhöra bättringen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 21, 'För denna saks skull var det som judarna grepo mig i helgedomen och försökte att döda mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 22, 'Genom den hjälp som jag har undfått av Gud står jag alltså ännu i dag såsom ett vittne inför både små och stora; och jag säger intet annat, än vad profeterna och Moses hava sagt skola ske,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 23, 'nämligen att Messias skulle lida och, såsom förstlingen av dem som uppstå från de döda, bära budskap om ljuset, såväl till vårt eget folk som till hedningarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 24, 'När han på detta satt försvarade sig, utropade Festus: »Du är från dina sinnen, Paulus; den myckna lärdomen gör dig förryckt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 25, 'Men Paulus svarade: »Jag är icke från mina sinnen, ädle Festus; jag talar sanna ord med lugn besinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 26, 'Konungen känner väl till dessa ting; därför talar jag också frimodigt inför honom. Ty jag kan icke tro att något av detta är honom obekant; det har ju icke tilldragit sig i någon undangömd vrå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 27, 'Tror du profeterna, konung Agrippa? Jag vet att du tror dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 28, 'Då sade Agrippa till Paulus: »Föga fattas att du övertalar mig och gör mig till kristen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 29, 'Paulus svarade: »Vare sig det fattas litet eller fattas mycket, skulle jag önska inför Gud att icke allenast du, utan alla som i dag höra mig, måtte bliva sådana som jag är, dock med undantag av dessa bojor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 30, 'Därefter stod konungen upp, och med honom landshövdingen och Bernice och de som sutto där tillsammans med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 31, 'Och när de gingo därifrån, talade de med varandra och sade: »Den mannen har icke gjort något som förtjänar död eller fängelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 32, 'Och Agrippa sade till Festus: »Denne man hade väl kunnat frigivas, om han icke hade vädjat till kejsaren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 1, 'När det nu var beslutet att vi skulle avsegla till Italien, blev Paulus jämte några andra fångar överlämnad åt en hövitsman, vid namn Julius, som tillhörde den kejserliga vakten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 2, 'Och vi gingo ombord på ett skepp från Adramyttium, som skulle anlöpa provinsen Asiens kuststäder. Så lade vi ut, och vi hade med oss Aristarkus, en macedonier från Tessalonika.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 3, 'Dagen därefter lade vi till vid Sidon. Och Julius, som bemötte Paulus med välvilja, tillstadde honom att besöka sina vänner där och åtnjuta deras omvårdnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 4, 'När vi hade lagt ut därifrån, seglade vi under Cypern, eftersom vinden låg emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 5, 'Och sedan vi hade seglat över havet, utanför Cilicien och Pamfylien, landade vi vid Myrra i Lycien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 6, 'Där träffade hövitsmannen på ett skepp från Alexandria, som skulle segla till Italien, och på det förde han oss ombord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 7, 'Under en längre tid gick nu seglingen långsamt, och vi kommo med knapp nöd inemot Knidus. Och då vinden icke var oss gynnsam, seglade vi in under Kreta vid Salmone.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 8, 'Det var med knapp nöd som vi kommo där förbi och hunno fram till en ort som kallades Goda hamnarna, icke långt från staden Lasea.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 9, 'Härunder hade ganska lång tid hunnit förflyta, och sjöfarten begynte redan vara osäker; fastedagen[1] var nämligen redan förbi. Paulus varnade dem då');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 10, 'och sade: »I mån, jag ser att denna sjöresa kommer att medföra vedervärdigheter och stor olycka, icke allenast för last och skepp, utan ock för våra liv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 11, 'Men hövitsmannen trodde mer på styrmannen och skepparen än på det som Paulus sade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 12, 'Och då hamnen icke låg väl till för övervintring, var flertalet av den meningen att man borde lägga ut därifrån och försöka om man kunde komma fram till Fenix, en hamn på Kreta, som ligger skyddad mot sydväst och nordväst; där skulle de sedan stanna över vintern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 13, 'Och då nu en lindrig sunnanvind blåste upp, menade de sig hava målet vunnet, och lyfte ankar och foro tätt utmed Kreta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 14, 'Men icke långt därefter kom en våldsam stormvind farande ned från ön; det var den så kallade nordostorkanen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 15, 'Då skeppet av denna rycktes med och icke kunde hållas upp mot vinden, gåvo vi efter och läto det driva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 16, 'När vi kommo under en liten ö som hette Kauda, förmådde vi dock, fastän med knapp nöd, bärga skeppsbåten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 17, 'Sedan manskapet hade dragit upp den, tillgrepo de nödhjälpsmedel och slogo tåg om skeppet. Och då de fruktade att bliva kastade på Syrtenrevlarna, lade de ut drivankare och läto skeppet så driva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 18, 'Och eftersom vi alltjämt hårt ansattes av stormen, vräkte de dagen därefter en del av lasten över bord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 19, 'På tredje dagen kastade de med egna händer ut skeppsredskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 20, 'Och då under flera dagar varken sol eller stjärnor hade synts, och stormen låg ganska hårt på, hade vi icke mer något hopp om räddning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 21, 'Då nu många funnos som ingenting ville förtära, trädde Paulus upp mitt ibland dem och sade: »I män, I haden bort lyda mig och icke avsegla från Kreta; I haden då kunnat spara eder dessa vedervärdigheter och denna olycka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 22, 'Men nu uppmanar jag eder att vara vid gott mod, ty ingen av eder skall förlora sitt liv; allenast skeppet skall gå förlorat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 23, 'Ty i natt kom en ängel från den Gud som jag tillhör, och som jag också tjänar, och stod bredvid mig och sade:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 24, '\'Frukta icke, Paulus. Du skall komma att stå inför kejsaren; och se, Gud har skänkt dig alla dem som segla med dig.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 25, 'Varen därför vid gott mod, I män; ty jag har den förtröstan till Gud, att så skall ske som mig är sagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 26, 'Men på en ö måste vi bliva kastade.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 27, 'När vi nu den fjortonde natten drevo omkring på Adriatiska havet, tyckte sjömännen sig vid midnattstiden finna att de närmade sig något land.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 28, 'De lodade då och funno tjugu famnars djup. När de hade kommit ett litet stycke längre fram lodade de åter och funno femton famnars djup.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 29, 'Då fruktade de att vi skulle stöta på något skarpt grund, och kastade därför ut fyra ankaren från akterskeppet och längtade efter att det skulle dagas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 30, 'Sjömännen ville emellertid fly ifrån skeppet och firade ned skeppsbåten i havet, under föregivande att de tänkte föra ut ankaren ifrån förskeppet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 31, 'Då sade Paulus till hövitsmannen och krigsmännen: »Om icke dessa stanna kvar på skeppet, så kunnen I icke räddas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 32, 'Då höggo krigsmännen av de tåg som höllo skeppsbåten, och läto den fara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 33, 'Medan det nu höll på att dagas, uppmanade Paulus alla att taga sig mat och sade: »Det är i dag fjorton dagar som I haven väntat och förblivit fastande, utan att förtära något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 34, 'Därför uppmanar jag eder att taga eder mat; detta skall förhjälpa eder till räddning. Ty på ingen av eder skall ett huvudhår gå förlorat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 35, 'När han hade sagt detta, tog han ett bröd och tackade Gud i allas åsyn och bröt det och begynte äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 36, 'Då blevo alla de andra vid gott mod och togo sig mat, också de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 37, 'Och vi voro på skeppet tillsammans två hundra sjuttiosex personer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 38, 'Sedan de hade ätit sig mätta, lättade de skeppet genom att kasta vetelasten i havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 39, 'När det blev dag, kände de icke igen landet; men de blevo varse en vik med låg strand och beslöto då att, om möjligt, låta skeppet driva upp på denna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 40, 'De kapade så ankartågen på båda sidor och lämnade ankarna kvar i havet; tillika lösgjorde de rodren och hissade förseglet för vinden och styrde mot stranden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 41, 'De stötte då på ett rev och läto skeppet gå upp på det. Där fastnade förskeppet och blev stående orörligt, men akterskeppet begynte brytas sönder av vågsvallet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 42, 'Då ville krigsmännen döda fångarna, för att ingen skulle kunna fly undan simmande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 43, 'Men hövitsmannen ville rädda Paulus och hindrade dem därför i deras uppsåt, och bjöd att de simkunniga först skulle kasta sig i vattnet och söka komma i land,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 44, 'och att därefter de övriga skulle giva sig ut, somliga på plankor, andra på spillror av skeppet. Så lyckades det för alla att komma välbehållna i land. [1] Se Fastedagen i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 1, 'Först sedan vi hade blivit räddade, fingo vi veta att ön hette Malta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 2, 'Och infödingarna visade oss en icke vanlig välvilja; de tände upp en eld och togo oss alla med sig dit, för det påkommande regnets och för köldens skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 3, 'När Paulus då tog upp ett fång torra kvistar som han lade på elden, kom, i följd av hettan, en huggorm fram därur och högg sig fast vid hans hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 4, 'Då infödingarna fingo se ormen hänga där vid hans hand, sade de till varandra: »Helt visst är denne man en dråpare, som rättvisans gudinna icke tillstädjer att leva, om han nu ock har blivit räddad undan havet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 5, 'Men han skakade ormen ifrån sig i elden och led ingen skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 6, 'De väntade att han skulle svälla upp eller helt plötsligt falla ned död; men när de efter lång väntan fingo se att intet ont vederfors honom, ändrade de mening och sade att han var en gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 7, 'I närheten av detta ställe var en lantgård, som tillhörde den förnämste mannen på ön, en som hette Publius; denne tog välvilligt emot oss och gav oss härbärge i tre dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 8, 'Nu hände sig att Publius\' fader låg sjuk i en magsjukdom med feberanfall. Paulus gick då in till honom och bad och lade händerna på honom och gjorde honom frisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 9, 'Men när detta hade skett, kommo också de av öns övriga inbyggare som hade någon sjukdom till honom och blevo botade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 10, 'Och de bevisade oss ära på mångahanda sätt; och när vi skulle avsegla, försågo de oss med vad vi behövde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 11, 'Då tre månader voro förlidna, avseglade vi på ett skepp som hade legat vid ön över vintern; det var från Alexandria och bar Tvillinggudarnas bilder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 12, 'Och vi lade till vid Syrakusa och stannade där i tre dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 13, 'Därifrån foro vi längs kusten och kommo till Regium. Dagen därefter fingo vi sunnanvind, och vi kommo så redan på andra dagen till Puteoli.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 14, 'Där träffade vi på bröder, och hos dem stannade vi, på deras inbjudning, i sju dagar. På detta sätt kommo vi till Rom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 15, 'Så snart bröderna där fingo höra om oss, gingo de oss till mötes ända till Forum Appii och Tres Taberne. När Paulus fick se dem, tackade han Gud och fick nytt mod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 16, 'Och då vi hade kommit in i Rom, tillstaddes det Paulus att bo för sig själv, med den krigsman som skulle bevaka honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 17, 'Tre dagar därefter kallade han tillhopa de förnämsta av judarna; och när de hade kommit tillsammans, sade han till dem: »Mina bröder, fastän jag icke har gjort något mot vårt folk eller mot fädernas stadgar, blev jag likväl i Jerusalem överlämnad i romarnas händer och fördes bort därifrån såsom fånge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 18, 'Och när de hade anställt rannsakning med mig, ville de giva mig lös, eftersom jag icke hade gjort något som förtjänade döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 19, 'Men då judarna satte sig däremot, nödgades jag vädja till kejsaren; dock, icke som om jag hade någon anklagelse att göra mot mitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 20, 'Av denna orsak har jag kallat eder hit till mig, för att få se eder och tala med eder, ty det är för Israels hopps skull som jag är bunden med denna kedja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 21, 'Då svarade de honom: »Vi hava icke från Judeen mottagit någon skrivelse om dig, ej heller har någon av våra bröder kommit och berättat eller sagt något ont om dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 22, 'Men vi finna skäligt att du låter oss höra huru du tänker. Ty om det partiet är oss bekant att det allestädes mötes med gensägelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 23, 'Sedan utsatte de en viss dag för honom, och på den kommo ännu flera till honom i hans härbärge. Då vittnade han för dem om Guds rike och utlade vad därtill hör, och försökte att övertyga dem i fråga om Jesus, med bevis både ur Moses\' lag och ur profeterna; därmed höll han på från morgonen ända till aftonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 24, 'Och somliga läto övertyga sig av det som han sade, men andra trodde icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 25, 'Och då de icke kunde komma överens med varandra, gingo de sin väg, och därvid sade Paulus allenast detta ord: »Rätt talade den helige Ande genom profeten Esaias till edra fäder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 26, 'när han sade: \'Gå åstad och säg till detta folk: Med hörande öron skolen I höra, och dock alls intet förstå, och med seende ögon skolen I se, och dock alls intet förnimma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 27, 'Ty detta folks hjärta har blivit förstockat; och med öronen höra de illa, och sina ögon hava de tillslutit, så att de icke se med sina ögon eller höra med sina öron eller förstå med sina hjärtan och omvända sig och bliva helade av mig\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 28, 'Det mån I därför veta: till hedningarna bar denna Guds frälsning blivit sänd; de skola ock akta därpå.»[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 29, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 30, 'I två hela år bodde han sedan kvar i en bostad som han själv hade hyrt. Och alla som kommo till honom tog han emot;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 31, 'och han predikade om Guds rike och undervisade om Herren Jesus Kristus med all frimodighet, utan att någon hindrade honom däri. [1] 29; Och då han hade sagt detta, gingo judarna bort. Och de tvistade häftigt sinsemellan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Paulus, Jesu Kristi tjänare, kallad till apostel, avskild till att förkunna Guds evangelium,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'vilket Gud redan förut genom sina profeter hade i heliga skrifter utlovat,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'evangelium om hans Son, vilken såsom människa i köttet är född av Davids säd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'och såsom helig andevarelse är med kraft bevisad vara Guds Son, allt ifrån uppståndelsen från de döda, ja, evangelium om Jesus Kristus, vår Herre,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'genom vilken vi hava fått nåd och apostlaämbete för att, hans namn till ära, upprätta trons lydnad bland alla hednafolk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'bland vilka jämväl I ären, I som ären kallade och Jesu Kristi egna --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'jag, Paulus, hälsar alla Guds älskade som bo i Rom, dem som äro kallade och heliga. Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Först och främst tackar jag min Gud genom Jesus Kristus för eder alla, därför att man i hela världen talar om eder tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Ty Gud, som jag i min ande tjänar såsom förkunnare av evangelium om hans Son, han är mitt vittne, han vet huru oavlåtligt jag tänker på eder');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'och i mina böner alltid beder att jag dock nu omsider må få ett gynnsamt tillfälle att komma till eder, om Gud så vill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'Ty jag längtar efter att se eder, för att jag må kunna meddela eder någon andlig nådegåva till att styrka eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'jag menar: för att jag i eder krets må tillsammans med eder få hämta hugnad ur vår gemensamma tro, eder och min.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Jag vill säga eder, mina bröder, att jag ofta har haft i sinnet att komma till eder, för att också bland eder få skörda någon frukt, såsom bland övriga hednafolk; dock har jag allt hittills blivit hindrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Både mot greker och mot andra folk, både mot visa och mot ovisa har jag förpliktelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'Därför är jag villig att förkunna evangelium också för eder som bon i Rom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'Ty jag blyges icke för evangelium; ty det är en Guds kraft till frälsning för var och en som tror, först och främst för juden, så ock för greken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'Rättfärdighet från Gud uppenbaras nämligen däri, av tro till tro; så är ock skrivet: »Den rättfärdige skall leva av tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'Ty Guds vrede uppenbarar sig från himmelen över all ogudaktighet och orättfärdighet hos människor som i orättfärdighet undertrycka sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 19, 'Vad man kan känna om Gud är nämligen uppenbart bland dem; Gud har ju uppenbarat det för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 20, 'Ty hans osynliga väsen, hans eviga makt och gudomshärlighet hava ända ifrån världens skapelse varit synliga, i det att de kunna förstås genom hans verk. Så äro de då utan ursäkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 21, 'Ty fastän de hade lärt känna Gud, prisade och tackade de honom dock icke såsom Gud, utan förföllo till fåfängliga tankar; och så blevo deras oförståndiga hjärtan förmörkade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 22, 'När de berömde sig av att vara visa, blevo de dårar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 23, 'och bytte bort den oförgänglige Gudens härlighet mot beläten, som voro avbilder av förgängliga människor, ja ock av fåglar och fyrfotadjur och krälande djur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 24, 'Därför prisgav Gud dem i deras hjärtans begärelser åt orenhet, så att de med varandra skändade sina kroppar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 25, 'De hade ju bytt bort Guds sanning mot lögn och tagit sig för att dyrka och tjäna det skapade framför Skaparen, honom som är högtlovad i evighet, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 26, 'Fördenskull gav Gud dem till pris åt skamliga lustar: deras kvinnor utbytte det naturliga umgänget mot ett onaturligt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 27, 'sammalunda övergåvo ock männen det naturliga umgänget med kvinnan och upptändes i lusta till varandra och bedrevo styggelse, man med man. Så fingo de på sig själva uppbära sin villas tillbörliga lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 28, 'Och eftersom de icke hade aktat det något värt att taga vara på sin kunskap om Gud, gav Gud dem till pris åt ett ovärdigt sinnelag, till att bedriva otillbörliga ting.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 29, 'Så hava de blivit uppfyllda av allt slags orättfärdighet, ondska, girighet, elakhet; de äro fulla av avund, mordlust, trätlystnad, svek, vrångsinthet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 30, 'de äro örontasslare, förtalare, styggelser för Gud, våldsverkare, övermodiga, stortaliga, illfundiga, olydiga mot sina föräldrar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 31, 'oförståndiga, trolösa, utan kärlek till sina egna, utan barmhärtighet mot andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 32, 'Och fastän de väl veta vad Gud har stadgat såsom rätt, att nämligen de som handla så förtjäna döden, är det dem icke nog att själva så göra, de giva ock sitt bifall åt andra som handla likaså.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Därför är du utan ursäkt, du människa, vem du än är, som dömer. Ty därmed att du dömer en annan fördömer du dig själv, eftersom du, som dömer den andre, själv handlar på samma sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Och vi veta att Guds dom verkligen kommer över dem som handla så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Men du menar väl detta, att du skall kunna undfly Guds dom, du människa, som dömer dem som handla så, och dock gör detsamma som de?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Eller föraktar du hans godhets, skonsamhets och långmodighets rikedom, utan att förstå att denna Guds godhet vill föra dig till bättring?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Genom din hårdhet och ditt hjärtas obotfärdighet samlar du ju över dig vrede, som skall drabba dig på vredens dag, då när det bliver uppenbart att Gud är en rättvis domare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Ty »han skall vedergälla var och en efter hans gärningar».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Evigt liv skall han giva åt dem som med uthållighet i att göra det goda söka härlighet och ära och oförgänglighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Men över dem som äro genstridiga och icke lyda sanningen, utan lyda orättfärdigheten, över dem kommer vrede och förtörnelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Ja, bedrövelse och ångest skall komma över den människas själ, som gör det onda, först och främst över judens, så ock över grekens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Men härlighet och ära och frid skall tillfalla var och en som gör det goda, först och främst juden, så ock greken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Ty hos Gud finnes intet anseende till personen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'alla de som utan lag hava syndat skola ock utan lag förgås, och alla de som med lag hava syndat skola genom lag bliva dömda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ty icke lagens hörare äro rättfärdiga inför Gud, men lagens görare skola förklaras rättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ty då hedningarna, som icke hava lag, av naturen göra vad lagen innehåller, så äro dessa, utan att hava lag, sig själv en lag,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'då de ju sålunda visa att lagens verk äro skrivna i deras hjärtan. Därom utgöra också deras egna samveten ett vittnesbörd, så ock, i den inbördes umgängelsen, deras tankar, när dessa anklaga eller ock försvara dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Ja, så skall det befinnas vara på den dag då Gud, enligt det evangelium jag förkunnar, genom Kristus Jesus dömer över vad som är fördolt hos människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Du kallar dig jude och förlitar dig på lagen och berömmer dig av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Du känner ock hans vilja, och eftersom du har fått din undervisning ur lagen, kan du döma om vad rättast är;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'och du tilltror dig att vara en ledare för blinda, ett ljus för människor som vandra i mörker,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'en uppfostrare för oförståndiga, en lärare för enfaldiga, eftersom du i lagen har uttrycket för kunskapen och sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Du som vill lära andra, du lär icke dig själv! Du som predikar att man icke skall stjäla, du begår själv stöld!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Du som säger att man icke skall begå äktenskapsbrott, du begår själv sådant brott! Du som håller avgudarna för styggelser, du gör dig själv skyldig till tempelrån!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Du som berömmer dig av lagen, du vanärar Gud genom att överträda lagen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'ty, såsom det är skrivet, »för eder skull varder Guds namn smädat bland hedningarna».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Ty väl är omskärelse till gagn, om du håller lagen; men om du är en lagöverträdare, så är du med din omskärelse dock oomskuren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Om nu den oomskurne håller lagens stadgar, skall han då icke, fastän han är oomskuren, räknas såsom omskuren?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Jo, och han som i följd av sin härkomst är oomskuren, men ändå fullgör lagen, skall bliva dig till dom, dig som äger lagens bokstav och omskärelsen, men likväl är en lagöverträdare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Ty den är icke jude, som är det i utvärtes måtto, ej heller är det omskärelse, som sker utvärtes på köttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Nej, den är jude, som är det i invärtes måtto, och omskärelse är hjärtats omskärelse, en som sker i Anden, och icke i kraft av bokstaven; och han har sin berömmelse, icke från människor, utan från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Vilket företräde hava då judarna, eller vad gagn hava de av omskärelsen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Jo, ett stort företräde, på allt sätt; först och främst det, att de hava blivit betrodda med Guds löftesord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Ty vad betyder det, om några av dem blevo trolösa? Kan då deras trolöshet göra Guds trofasthet om intet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Bort det! Må Gud stå såsom sannfärdig, om ock »var människa är en lögnare». Så är ju skrivet: »På det att du må finnas rättfärdig i dina ord och få rätt, när man sätter sig till doms över dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Men är det nu så, att vår orättfärdighet tjänar till att bevisa Guds rättfärdighet, vad skola vi då säga? Kan väl Gud, han som låter vredesdomen drabba, vara orättfärdig? (Jag talar såsom vore det fråga om en människa.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Bort det! Huru skulle Gud då kunna döma världen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Och å andra sidan, om Guds sannfärdighet genom min lögnaktighet ännu mer har trätt i dagen, honom till ära, varför skall då jag likväl dömas såsom syndare?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Och varför skulle vi icke »göra vad ont är, för att gott måtte komma därav», såsom man, för att smäda oss, påstår att vi göra, och såsom några föregiva att vi lära? -- Sådana få med rätta sin dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Huru är det alltså? Äro vi då något förmer än de andra? Ingalunda. Redan härförut har jag ju måst anklaga både judar och greker för att allasammans vara under synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Så är ock skrivet: »Ingen rättfärdig finnes, icke en enda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Ingen förståndig finnes, ingen finnes som söker Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nej, alla hava de avvikit, allasammans hava de blivit odugliga, ingen finnes som gör vad gott är, det finnes ingen enda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'En öppen grav är deras strupe, sina tungor bruka de till svek. Huggormsgift är inom deras läppar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Deras mun är full av förbannelse och bitterhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Deras fötter äro snara, när det gäller att utgjuta blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Förödelse och elände är på deras vägar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'och fridens väg känna de icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Guds fruktan är icke för deras ögon.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Nu veta vi att allt vad lagen säger, det talar den till dem som hava lagen, för att var mun skall bliva tillstoppad och hela världen stå med skuld inför Gud;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'ty av laggärningar bliver intet kött rättfärdigt inför honom. Vad som kommer genom lagen är kännedom om synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Men nu har, utan lag, en rättfärdighet från Gud blivit uppenbarad, en som lagen och profeterna vittna om,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'en rättfärdighet från Gud genom tro på Jesus Kristus, för alla dem som tro. Ty här är ingen åtskillnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Alla hava ju syndat och äro i saknad av härligheten från Gud;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'och de bliva rättfärdiggjorda utan förskyllan, av hans nåd, genom förlossningen i Kristus Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 25, 'honom som Gud har ställt fram såsom ett försoningsmedel genom tro, i hans blod. Så ville Gud -- då han i sin skonsamhet hade haft fördrag med de synder som förut hade blivit begångna -- nu visa att han dock var rättfärdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 26, 'Ja, så ville han i den tid som nu är lämna beviset för att han är rättfärdig. Härigenom skulle han både själv befinnas vara rättfärdig och göra den rättfärdig, som låter det bero på tro på Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 27, 'Huru bliver det då med vår berömmelse? Den är utestängd. Genom vilken lag? Månne genom en gärningarnas lag? Nej, genom en trons lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 28, 'Vi hålla nämligen före att människan bliver rättfärdig genom tro, utan laggärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 29, 'Eller är Gud allenast judarnas Gud? Är han icke ock hedningarnas? Jo, förvisso också hedningarnas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 30, 'så visst som Gud är en, han som skall göra de omskurna rättfärdiga av tro, så ock de oomskurna genom tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 31, 'Göra vi då vad lag är om intet genom tron? Bort det! Vi göra tvärtom lag gällande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Vad skola vi då säga om Abraham, vår stamfader efter köttet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Om Abraham blev rättfärdig av gärningar, så har han ju något att berömma sig av. Dock icke inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Ty vad säger skriften? »Abraham trodde Gud, och det räknades honom till rättfärdighet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Den som håller sig till gärningar, honom bliver lönen tillräknad icke på grund av nåd, utan på grund av förtjänst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Men den som icke håller sig till gärningar, utan tror på honom som gör den ogudaktige rättfärdig, honom räknas hans tro till rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Så prisar ock David den människa salig, som Gud tillräknar rättfärdighet, utan gärningar:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, '»Saliga äro de vilkas överträdelser äro förlåtna, och vilkas synder äro överskylda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Salig är den man som Herren icke tillräknar synd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Gäller nu detta ordet »salig» de omskurna allenast eller ock de oomskurna? Vi säga ju att »tron räknades Abraham till rättfärdighet».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Huru blev den honom då tillräknad? Skedde det sedan han hade blivit omskuren, eller medan han ännu var oomskuren? Det skedde icke sedan han hade blivit omskuren, utan medan han ännu var oomskuren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Och han undfick omskärelsens tecken såsom ett insegel på den rättfärdighet genom tron, som han hade, medan han ännu var oomskuren. Ty så skulle han bliva en fader för alla oomskurna som tro, och så skulle rättfärdighet tillräknas dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Han skulle ock bliva en fader för omskurna, nämligen för sådana som icke allenast äro omskurna, utan ock vandra i spåren av den tro som vår fader Abraham hade, medan han ännu var oomskuren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Det var nämligen icke genom lag som Abraham och hans säd undfick det löftet att han skulle få världen till arvedel; det var genom rättfärdighet av tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Ty om de som låta det bero på lag skola få arvedelen, så är tron till intet nyttig, och löftet är gjort om intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Vad lagen kommer åstad är ju vredesdom; men där ingen lag finnes, där finnes icke heller någon överträdelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Därför måste det bero på tro, för att det skulle vara av nåd, så att löftet kunde bliva beståndande för all hans säd, icke blott för dem som hörde till lagens folk, utan ock för dem som allenast hade Abrahams tro. Han är ju allas vår fader,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'enligt detta skriftens ord: »Jag har bestämt dig till att bliva en fader till många folk»; han är detta inför den Gud som han trodde, inför honom som gör de döda levande och kallar på de ting som icke äro till, likasom voro de till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Och där ingen förhoppning fanns, där hoppades han ändå och trodde; och han kunde så bliva »en fader till många folk», efter vad som var förutsagt: »Så skall din säd bliva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Och han försvagades icke i sin tro, när han betänkte huru hans egen kropp var såsom död -- han var ju omkring hundra år gammal -- och huru jämväl Saras moderliv var såsom dött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Han tvivlade icke på Guds löfte i otro, utan blev fastmer starkare i sin tro; ty han ärade Gud');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'och var fullt viss om att vad Gud hade lovat, det var han också mäktig att hålla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Därför räknades det honom ock till rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 23, 'Men att det så tillräknades honom, det är skrivet icke såsom gällde det allenast honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 24, 'utan det skulle gälla också oss; ty det skall tillräknas jämväl oss, oss som tro på honom som från de döda uppväckte Jesus, vår Herre,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 25, 'vilken utgavs för våra synders skull och uppväcktes för vår rättfärdiggörelses skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Då vi nu hava blivit rättfärdiggjorda av tro, hava vi frid med Gud genom vår Herre Jesus Kristus[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, '-- genom vilken vi ock hava fått tillträde till den nåd vari vi nu stå -- och vi berömma oss i hoppet om Guds härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Och icke det allenast, vi till och med berömma oss av våra lidanden, eftersom vi veta att lidandet verkar ståndaktighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'och ståndaktigheten beprövad fasthet, och fastheten hopp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'och hoppet låter oss icke komma på skam; ty Guds kärlek är utgjuten i våra hjärtan genom den helige Ande, vilken har blivit oss given.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ty medan vi ännu voro svaga, led Kristus, när tiden var inne, döden för oss ogudaktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Näppeligen vill ju eljest någon dö ens för en rättfärdig man -- om nu ock till äventyrs någon kan hava mod att dö för den som har gjort honom gott --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'men Gud bevisar sin kärlek till oss däri att Kristus dog för oss, medan vi ännu voro syndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Så mycket mer skola vi därför, sedan vi nu hava blivit rättfärdiggjorda i och genom hans blod, också genom honom bliva frälsta undan vredesdomen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Ty om vi, medan vi voro Guds ovänner, blevo försonade med honom genom hans Sons död, så skola vi, sedan vi hava blivit försonade, ännu mycket mer bliva frälsta i och genom hans liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Och icke det allenast; vi berömma oss ock av Gud genom vår Herre Jesus Kristus, genom vilken vi nu hava undfått försoningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Därför är det så: Genom en enda människa har synden kommit in i världen och genom synden döden; och så har döden kommit över alla människor, eftersom de alla hava syndat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Ty synd fanns i världen redan innan lagen fanns. Men synd tillräknas icke där ingen lag finnes;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'och dock har under tiden från Adam till Moses döden haft väldet också över dem som icke hade syndat genom en överträdelse, i likhet med vad Adam gjorde, han som är en förebild till den som skulle komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Likväl är det icke så med nådegåvan, som det var med syndafallet. Ty om genom en endas fall de många hava blivit döden underlagda, så har ännu mycket mer Guds nåd och gåvan i och genom nåd -- vilken, också den, är kommen genom en enda människa, Jesus Kristus -- blivit på ett överflödande sätt de många beskärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Och med gåvan är det icke såsom det var med det som kom genom denne ene som syndade: domen kom genom en enda, och ledde till en fördömelsedom, men nådegåvan kom i följd av mångas fall, och ledde till en rättfärdiggörelsedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Och om döden på grund av en endas fall kom till konungavälde genom denne ene, så skola ännu mycket mer de som undfå den överflödande nåden och rättfärdighetsgåvan få konungsligt välde i liv, också det genom en enda, Jesus Kristus. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Alltså, likasom det, som kom genom en endas fall, för alla människor ledde till en fördömelsedom, så leder det, som kom genom rättfärdiggörelsedomen förmedelst en enda, för alla människor till en rättfärdiggörelse som medför liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Ty såsom genom en enda människas olydnad de många fingo stå såsom syndare, så skola ock genom en endas lydnad de många stå såsom rättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Men lagen har därjämte kommit in, för att fallet skulle bliva så mycket större; dock, där synden blev större, där överflödade nåden mycket mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Ty såsom synden hade utövat sitt välde i och genom döden, så skulle nu ock nåden genom rättfärdighet utöva sitt välde till evigt liv, och det genom Jesus Kristus, vår Herre. [1] Eller: Då vi nu hava blivit rättfärdiggjorda av tro, må vi hava frid osv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 1, 'Vad skola vi då säga? Skola vi förbliva i synden, för att nåden skall bliva så mycket större?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 2, 'Bort det! Vi som hava dött från synden, huru skulle vi ännu kunna leva i den?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 3, 'Veten I då icke att vi alla som hava blivit döpta till Kristus Jesus, vi hava blivit döpta till hans död?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 4, 'Och vi hava så, genom detta dop till döden, blivit begravna med honom, för att, såsom Kristus uppväcktes från de döda genom Faderns härlighet, också vi skola vandra i ett nytt väsende, i liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 5, 'Ty om vi hava vuxit samman med honom genom en lika död, så skola vi ock vara sammanvuxna med honom genom en lika uppståndelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 6, 'Vi veta ju detta, att vår gamla människa har blivit korsfäst med honom, för att syndakroppen skall göras om intet, så att vi icke mer tjäna synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 7, 'Ty den som är död, han är friad ifrån synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 8, 'Hava vi nu dött med Kristus, så tro vi att vi ock skola leva med honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 9, 'eftersom vi veta att Kristus, sedan han har uppstått från de döda, icke mer dör; döden råder icke mer över honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 10, 'Ty hans död var en död från synden en gång för alla, men hans liv är ett liv för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 11, 'Så mån ock I hålla före att I ären döda från synden och leven för Gud, i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 12, 'Låten därför icke synden hava väldet i edra dödliga kroppar, så att I lyden deras begärelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 13, 'Och ställen icke edra lemmar i syndens tjänst, att vara orättfärdighetsvapen, utan ställen eder själva i Guds tjänst, såsom de där från döden hava kommit till livet, och edra lemmar i Guds tjänst, att vara rättfärdighetsvapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 14, 'Ty synden skall icke råda över eder, eftersom I icke stån under lagen, utan under nåden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 15, 'Huru är det alltså? Skola vi synda, eftersom vi icke stå under lagen, utan under nåden? Bort det!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 16, 'I veten ju, att när I ställen eder i någons tjänst för att lyda honom, så ären I tjänare under denne, som I sålunda lyden, vare sig det är under synden, vilket leder till död, eller under lydnaden, vilket leder till rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 17, 'Men Gud vare tack för att den tid är förbi, då I voren syndens tjänare, och för att I haven blivit av hjärtat lydiga, så att I följen den lära som har givits eder till mönsterbild,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 18, 'och för att I, när I nu haven gjorts fria ifrån synden, haven blivit tjänare under rättfärdigheten --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 19, 'om jag nu får tala på människosätt, för eder köttsliga svaghets skull. Ja, likasom I förr ställden edra lemmar i orenhetens och orättfärdighetens tjänst, till orättfärdighet, så mån I nu ställa edra lemmar i rättfärdighetens tjänst, till helgelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 20, 'Medan I voren syndens tjänare, voren I ju fria ifrån rättfärdighetens tjänst;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 21, 'men vilken frukt skördaden I då därav? Jo, det som I nu blygens för; änden på sådant är ju döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 22, 'Men nu, då I haven gjorts fria ifrån synden och blivit Guds tjänare, nu skörden I frukten av detta: I varden helgade; och änden bliver att I undfån evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 23, 'Ty den lön som synden giver är döden, men den gåva som Gud av nåd giver är evigt liv, i Kristus Jesus, vår Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 1, 'Eller veten I icke, mina bröder -- jag talar ju till sådana som känna lagen -- att lagen råder över en människa för så lång tid som hon lever?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 2, 'Så är ju en gift kvinna genom lag bunden vid sin man, så länge denne lever; men om mannen dör, då är hon löst från den lag som band henne vid mannen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 3, 'Alltså, om hon giver sig åt en annan man, medan hennes man lever, så kallas hon äktenskapsbryterska; men om mannen dör, då är hon fri ifrån lagen, så att hon icke är äktenskapsbryterska, om hon giver sig åt en annan man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 4, 'Så haven ock I, mina bröder, genom Kristi kropp blivit dödade från lagen för att tillhöra en annan, nämligen honom som har uppstått från de döda, på det att vi må bära frukt åt Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 5, 'Ty medan vi ännu voro i ett köttsligt väsende, voro de syndiga lustar, som uppväcktes genom lagen, verksamma i våra lemmar till att bära frukt åt döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 6, 'Men nu äro vi lösta från lagen, i det att vi hava dött från det varunder vi förr höllos fångna; och så tjäna vi nu i Andens nya väsende, och icke i bokstavens gamla väsende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 7, 'Vad skola vi då säga? Är lagen synd? Bort det! Men synden skulle jag icke hava lärt känna, om icke genom lagen; ty jag hade icke vetat av begärelsen, om icke lagen hade sagt: »Du skall icke hava begärelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 8, 'Men då nu synden fick tillfälle, uppväckte den genom budordet allt slags begärelse i mig. Ty utan lag är synden död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 9, 'Jag levde en gång utan lag; men när budordet kom, fick synden liv,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 10, 'och jag hemföll åt döden. Så befanns det att budordet, som var givet till liv, det blev mig till död;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 11, 'ty då synden fick tillfälle, förledde den mig genom budordet och dödade mig genom det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 12, 'Alltså är visserligen lagen helig, och budordet heligt och rättfärdigt och gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 13, 'Har då verkligen det som är gott blivit mig till död? Bort det! Men synden har blivit det, för att så skulle varda uppenbart att den var synd, i det att den genom något som självt var gott drog över mig död; och så skulle synden bliva till övermått syndig, genom budordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 14, 'Vi veta ju att lagen är andlig, men jag är av köttslig natur, såld till träl under synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 15, 'Ty jag kan icke fatta att jag handlar såsom jag gör; jag gör ju icke vad jag vill, men vad jag hatar, det gör jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 16, 'Om jag nu gör det som jag icke vill, så giver jag mitt bifall åt lagen och vidgår att den är god.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 17, 'Så är det nu icke mer jag som gör sådant, utan synden, som bor i mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 18, 'Ty jag vet att i mig, det är i mitt kött, bor icke något gott; viljan är väl tillstädes hos mig, men att göra det goda förmår jag icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 19, 'Ja, det goda som jag vill gör jag icke; men det onda som jag icke vill, det gör jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 20, 'Om jag alltså gör vad jag icke vill, så är det icke mer jag som gör det, utan synden, som bor i mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 21, 'Så finner jag nu hos mig, som har viljan att göra det goda, den lagen, att det onda fastmer är tillstädes hos mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 22, 'Ty efter min invärtes människa har jag min lust i Guds lag;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 23, 'men i mina lemmar ser jag en annan lag, en som ligger i strid med den lag som är i min håg, en som gör mig till fånge under syndens lag, som är i mina lemmar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 24, 'Jag arma människa! Vem skall frälsa mig från denna dödens kropp? --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 25, 'Gud vare tack, genom Jesus Kristus, vår Herre! Alltså tjänar jag, sådan jag är i mig själv, visserligen med min håg Guds lag, men med köttet tjänar jag syndens lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 1, 'Så finnes nu ingen fördömelse för dem som äro i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 2, 'Ty livets Andes lag har i Kristus Jesus gjort mig fri ifrån syndens och dödens lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 3, 'Ty det som lagen icke kunde åstadkomma, i det den var försvagad genom köttet, det gjorde Gud, då han, för att borttaga synden, sände sin Son i syndigt kötts gestalt och fördömde synden i köttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 4, 'Så skulle lagens krav uppfyllas i oss, som vandra icke efter köttet, utan efter Anden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 5, 'Ty de som äro köttsliga, de hava sitt sinne vänt till vad köttet tillhör; men de som äro andliga, de hava sitt sinne vänt till vad Anden tillhör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 6, 'Och köttets sinne är död, medan Andens sinne är liv och frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 7, 'Köttets sinne är nämligen fiendskap mot Gud, eftersom det icke är Guds lag underdånigt, ej heller kan vara det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 8, 'Men de som äro i ett köttsligt väsende kunna icke behaga Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 9, 'I åter ären icke i ett köttsligt väsende, utan i ett andligt, om eljest Guds Ande bor i eder; men den som icke har Kristi Ande, han hör icke honom till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 10, 'Om nu Kristus är i eder, så är väl kroppen hemfallen åt döden, för syndens skull, men Anden är liv, för rättfärdighetens skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 11, 'Och om dens Ande, som uppväckte Jesus från de döda, bor i eder, så skall han som uppväckte Kristus Jesus från de döda göra också edra dödliga kroppar levande, genom sin Ande, som bor i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 12, 'Alltså, mina bröder, hava vi icke någon förpliktelse mot köttet, så att vi skola leva efter köttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 13, 'Ty om i leven efter köttet, så skolen I dö; men om I genom ande döden kroppens gärningar, så skolen I leva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 14, 'Ty alla de som drivas av Guds Ande, de äro Guds barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 15, 'I haven ju icke fått en träldomens ande, så att I åter skullen känna fruktan; I haven fått en barnaskapets ande, i vilken vi ropa: »Abba! Fader!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 16, 'Anden själv vittnar med vår ande att vi äro Guds barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 17, 'Men äro vi barn, så äro vi ock arvingar, nämligen Guds arvingar och Kristi medarvingar, om vi eljest lida med honom, för att också med honom bliva förhärligade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 18, 'Ty jag håller före att denna tidens lidanden intet betyda, i jämförelse med den härlighet som kommer att uppenbaras på oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 19, 'Ty skapelsens trängtan sträcker sig efter Guds barns uppenbarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 20, 'Skapelsen har ju blivit lagd under förgängligheten, icke av eget val, utan för dens skull, som lade den därunder; dock så, att en förhoppning skulle finnas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 21, 'att också skapelsen en gång skall bliva frigjord ifrån sin träldom under förgängelsen och komma till den frihet som tillhör Guds barns härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 22, 'Vi veta ju att ännu i denna stund hela skapelsen samfällt suckar och våndas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 23, 'Och icke den allenast; också vi själva, som hava fått Anden såsom förstlingsgåva, också vi sucka inom oss och bida efter barnaskapet, vår kropps förlossning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 24, 'Ty i hoppet äro vi frälsta. Men ett hopp som man ser fullbordat är icke mer ett hopp; huru kan någon hoppas det som han redan ser?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 25, 'Om vi nu hoppas på det som vi icke se, så bida vi därefter med ståndaktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 26, 'Så kommer ock Anden vår svaghet till hjälp; ty vad vi rätteligen böra bedja om, det veta vi icke, men Anden själv manar gott för oss med outsägliga suckar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 27, 'Och han som rannsakar hjärtan, han vet vad Anden menar, ty det är efter Guds behag som han manar gott för de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 28, 'Men vi veta att för dem som älska Gud samverkar allt till det bästa, för dem som äro kallade efter hans rådslut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 29, 'Ty dem som förut hava blivit kända av honom, dem har han ock förut bestämt till att bliva hans Sons avbilder, honom lika, så att denne skulle bliva den förstfödde bland många bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 30, 'Och dem som han har förut bestämt, dem kallar han ock, och dem som han har kallat, dem rättfärdiggör han ock, och dem som han har rättfärdiggjort, dem förhärligar han ock.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 31, 'Vad skola vi nu säga härom? Är Gud för oss, vem kan då vara emot oss?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 32, 'Han som icke har skonat sin egen Son, utan utgivit honom för oss alla, huru skulle han kunna annat än också skänka oss allt med honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 33, 'Vem vill anklaga Guds utvalda? Gud är den som rättfärdiggör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 34, 'Vem är den som vill fördöma? Kristus Jesus är den som har dött, ja, än mer, den som har uppstått; och han sitter på Guds högra sida, han manar ock gott för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 35, 'Vem skulle kunna skilja oss från Kristi kärlek? Månne bedrövelse eller ångest eller förföljelse eller hunger eller nakenhet eller fara eller svärd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 36, 'Så är ju skrivet: »För din skull varda vi dödade hela dagen; vi hava blivit aktade såsom slaktfår.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 37, 'Nej, i allt detta vinna vi en härlig seger genom honom som har älskat oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 38, 'Ty jag är viss om att varken död eller liv, varken änglar eller andefurstar, varken något som nu är eller något som skall komma,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 39, 'varken någon makt i höjden eller någon makt i djupet, ej heller något annat skapat skall kunna skilja oss från Guds kärlek i Kristus Jesus, vår Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 1, 'Jag talar sanning i Kristus, jag ljuger icke -- därom bär mitt samvete mig vittnesbörd i den helige Ande --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 2, 'när jag säger att jag har stor bedrövelse och oavlåtligt kval i mitt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 3, 'Ja, jag skulle önska att jag själv vore förbannad och bortkastad från Kristus, om detta kunde gagna mina bröder, mina fränder efter köttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 4, 'De äro ju israeliter, dem tillhöra barnaskapet och härligheten och förbunden och lagstiftningen och tempeltjänsten och löftena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 5, 'Dem tillhöra ock fäderna, och från dem är Kristus kommen efter köttet, han som är över allting, Gud, högtlovad i evighet, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 6, 'Detta säger jag icke som om Guds löftesord skulle hava blivit om intet. Ty »Israel», det är icke detsamma som alla de som härstamma från Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 7, 'Ej heller äro de alla »barn», därför att de äro Abrahams säd. Nej, det heter: »Genom Isak är det som säd skall uppkallas efter dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 8, 'Detta vill säga: Icke de äro Guds barn, som äro barn efter köttet, men de som äro barn efter löftet, de räknas för säd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 9, 'Ty ett löftesord var det ordet: »Vid denna tid skall jag komma tillbaka, och då skall Sara hava en son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 10, 'Än mer: så skedde ock, när Rebecka genom en och samme man, nämligen vår fader Isak, blev moder till sina barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 11, 'Ty förrän dessa voro födda, och innan de ännu hade gjort vare sig gott eller ont, blev det ordet henne sagt -- för att Guds utkorelse-rådslut skulle bliva beståndande, varvid det icke skulle bero på någons gärningar, utan på honom som kallar --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 12, 'det ordet: »Den äldre skall tjäna den yngre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 13, 'Så är ock skrivet: »Jakob älskade jag, men Esau hatade jag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 14, 'Vad skola vi då säga? Kan väl orättfärdighet finnas hos Gud? Bort det!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 15, 'Han säger ju till Moses: »Jag skall vara barmhärtig mot den jag vill vara barmhärtig emot, och jag skall förbarma mig över den jag vill förbarma mig över.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 16, 'Alltså beror det icke på någon människas vilja eller strävan, utan på Guds barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 17, 'Ty skriften säger till Farao: »Just därtill har jag låtit dig uppstå, att jag skall visa min makt på dig, och att mitt namn skall varda förkunnat på hela jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 18, 'Alltså är han barmhärtig mot vem han vill, och vem han vill förhärdar han.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 19, 'Nu torde du säga till mig: »Vad har han då att förebrå oss? Kan väl någon stå emot hans vilja?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 20, 'O människa, vem är då du, som vill träta med Gud? Icke skall verket säga till sin mästare: »Varför gjorde du mig så?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 21, 'Har icke krukmakaren den makten över leret, att han av samma lerklump kan göra ett kärl till hedersamt bruk, ett annat till mindre hedersamt?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 22, 'Men om nu Gud, när han ville visa sin vrede och uppenbara sin makt, likväl i stor långmodighet hade fördrag med »vredens kärl», som voro färdiga till fördärv, vad har du då att säga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 23, 'Och om han gjorde detta för att tillika få uppenbara sin härlighets rikedom på »barmhärtighetens kärl», som han förut hade berett till härlighet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 24, 'Och till att vara sådana har han ock kallat oss, icke allenast dem som äro av judisk börd, utan jämväl dem som äro av hednisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 25, 'Så säger han ock hos Oseas: »Det folk som icke var mitt folk, det skall jag kalla \'mitt folk\', och henne som jag icke älskade skall jag kalla \'min älskade\'.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 26, 'Och det skall ske att på den ort där det sades till dem: \'I ären icke mitt folk\', där skola de kallas \'den levande Gudens barn\'.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 27, 'Men Esaias utropar om Israel: »Om än Israels barn vore till antalet såsom sanden i havet, så skall dock allenast en kvarleva bliva frälst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 28, 'Ty dom skall Herren hålla på jorden, en slutdom, som avgör saken med hast.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 29, 'Och det är såsom redan Esaias har sagt: »Om Herren Sebaot icke hade lämnat en avkomma kvar åt oss, då vore vi såsom Sodom, vi vore Gomorra lika.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 30, 'Vad skola vi då säga? Jo, att hedningarna, som icke foro efter rättfärdighet, hava vunnit rättfärdighet, nämligen den rättfärdighet som kommer av tro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 31, 'under det att Israel, som for efter en rättfärdighetslag, icke har kommit till någon sådan lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 32, 'Varför? Därför att de icke sökte den på trons väg, utan såsom något som skulle vinnas på gärningarnas väg. De stötte sig mot stötestenen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 33, 'såsom det är skrivet: »Se, jag lägger i Sion en stötesten och en klippa som skall bliva dem till fall; men den som tror på den skall icke komma på skam.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 1, 'Mina bröder, mitt hjärtas åstundan och min bön till Gud för dem är att de må bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 2, 'Ty det vittnesbördet giver jag dem, att de nitälska för Gud. Dock göra de detta icke med rätt insikt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 3, 'De förstå nämligen icke rättfärdigheten från Gud, utan söka att komma åstad en sin egen rättfärdighet och hava icke givit sig under rättfärdigheten från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 4, 'Ty lagen har fått sin ände i Kristus, till rättfärdighet för var och en som tror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 5, 'Moses skriver ju om den rättfärdighet som kommer av lagen, att den människa som övar sådan rättfärdighet skall leva genom den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 6, 'Men den rättfärdighet som kommer av tro säger så: »Du behöver icke fråga i ditt hjärta: \'Vem vill fara upp till himmelen (nämligen för att hämta Kristus ned)?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 7, 'ej heller: \'Vem vill fara ned till avgrunden (nämligen för att hämta Kristus upp ifrån de döda)?\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 8, 'Vad säger den då? »Ordet är dig nära, i din mun och i ditt hjärta (nämligen ordet om tron, det som vi predika).»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 9, 'Ty om du med din mun bekänner Jesus vara Herre och i ditt hjärta tror att Gud har uppväckt honom från de döda, då bliver du frälst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 10, 'Ty genom hjärtats tro bliver man rättfärdig, och genom munnens bekännelse bliver man frälst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 11, 'Skriften säger ju: »Ingen som tror på honom skall komma på skam.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 12, 'Det är ingen åtskillnad mellan jude och grek; alla hava ju en och samme Herre, och han har rikedomar att giva åt alla som åkalla honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 13, 'Ty »var och en som åkallar Herrens namn, han skall varda frälst».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 14, 'Men huru skulle de kunna åkalla den som de icke hava kommit till tro på? Och huru skulle de kunna tro den som de icke hava hört? Och huru skulle de kunna höra, om ingen predikade?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 15, 'Och huru skulle predikare kunna komma, om de icke bleve sända? Så är och skrivet: »Huru ljuvliga äro icke fotstegen av de män som frambära gott budskap!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 16, 'Dock, icke alla hava blivit evangelium lydiga. Esaias säger ju: »Herre, vem trodde vad som predikades för oss?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 17, 'Alltså kommer tron av predikan, men predikan i kraft av Kristi ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 18, 'Jag frågar då: Hava de kanhända icke hört predikas? Jo, visserligen; det heter ju: »Deras tal har gått ut över hela jorden, och deras ord till världens ändar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 19, 'Jag frågar då vidare: Har Israel kanhända icke förstått det? Redan Moses säger: »Jag skall uppväcka eder avund mot ett folk som icke är ett folk; mot ett hednafolk utan förstånd skall jag reta eder till vrede.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 20, 'Och Esaias går så långt, att han säger: »Jag har låtit mig finnas av dem som icke sökte mig, jag har låtit mig bliva uppenbar för dem som icke frågade efter mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 21, 'Men om Israel säger han: »Hela dagen har jag uträckt mina händer till ett ohörsamt och gensträvigt folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 1, 'Så frågar jag nu: Har då Gud förskjutit sitt folk? Bort det! Jag är ju själv en israelit, av Abrahams säd och av Benjamins stam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 2, 'Gud har icke förskjutit sitt folk, som redan förut hade blivit känt av honom. Eller veten I icke vad skriften säger, där den talar om Elias, huru denne inför Gud träder upp mot Israel med dessa ord:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 3, '»Herre, de hava dräpt dina profeter och rivit ned dina altaren; jag allena är kvar, och de stå efter mitt liv»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 4, 'Och vad får han då för svar av Gud? »Jag har låtit bliva kvar åt mig sju tusen män, som icke hava böjt knä för Baal.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 5, 'Likaså finnes ock, i den tid som nu är, en kvarleva, i kraft av en utkorelse som har skett av nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 6, 'Men har den skett av nåd, så har den icke skett på grund av gärningar; annars vore nåd icke mer nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 7, 'Huru är det alltså? Vad Israel står efter, det har det icke fått; allenast de utvalda hava fått det, medan de andra hava blivit förstockade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 8, 'Så är ju skrivet: »Gud har givit dem en sömnaktighetens ande, ögon som de icke kunna se med och öron som de icke kunna höra med; så är det ännu i dag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 9, 'Och David säger: »Må deras bord bliva dem till en snara, så att de bliva fångade; må det bliva dem till ett giller, så att de få sin vedergällning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 10, 'Må deras ögon förmörkas, så att de icke se; böj deras rygg alltid.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 11, 'Så frågar jag nu: Var det då för att de skulle komma på fall som de stapplade? Bort det! Men genom deras fall har frälsningen kommit till hedningarna, för att de själva skola »uppväckas till avund».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 12, 'Och har nu redan deras fall varit till rikedom för världen, och har deras fåtalighet varit till rikedom för hedningarna, huru mycket mer skall icke deras fulltalighet så bliva!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 13, 'Men till eder, I som ären av hednisk börd, säger jag: Eftersom jag nu är en hedningarnas apostel, håller jag mitt ämbete högt --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 14, 'om jag till äventyrs så skulle kunna »uppväcka avund» hos dem som äro mitt kött och blod och frälsa några bland dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 15, 'Ty om redan deras förkastelse hade med sig världens försoning, vad skall då deras upptagande hava med sig, om icke liv från de döda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 16, 'Om förstlingsbrödet är heligt, så är ock hela degen helig; och om roten är helig, så äro ock grenarna heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 17, 'Men om nu några av grenarna hava brutits bort, och du, som är av ett vilt olivträd, har blivit inympad bland grenarna och med dem har fått delaktighet i det äkta olivträdets saftrika rot,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 18, 'så må du icke därför förhäva dig över grenarna. Nej, om du skulle vilja förhäva dig, så besinna att det icke är du som bär roten, utan att roten bär dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 19, 'Nu säger du kanhända: »Det var för att jag skulle bliva inympad som en del grenar brötos bort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 20, 'Visserligen. För sin otros skull blevo de bortbrutna, och du får vara kvar genom din tro. Hav då inga högmodiga tankar, utan lev i fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 21, 'Ty har Gud icke skonat de naturliga grenarna, så skall han icke heller skona dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 22, 'Se alltså här Guds godhet och stränghet: Guds stränghet mot dem som föllo och hans godhet mot dig, om du nämligen håller dig fast vid hans godhet; annars bliver också du borthuggen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 23, 'Men jämväl de andra skola bliva inympade, om de icke hålla fast vid sin otro; Gud är ju mäktig att åter inympa dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 24, 'Ty om du har blivit borthuggen från ditt av naturen vilda olivträd och mot naturen inympats i ett ädelt olivträd, huru mycket snarare skola då icke dessa kunna inympas i sitt eget äkta olivträd, det som de efter naturen tillhöra!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 25, 'Ty för att I, mina bröder, icke skolen hålla eder själva för kloka, vill jag yppa för eder denna hemlighet: Förstockelse har drabbat en del av Israel och skall fortfara intill dess hedningarna i fulltalig skara hava kommit in;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 26, 'och så skall hela Israel bliva frälst, såsom det är skrivet: »Från Sion skall förlossaren komma, han skall skaffa bort all ogudaktighet från Jakob.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 27, 'Och när jag borttager deras synder, då skall detta vara det förbund, som jag gör med dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 28, 'Se vi nu på evangelium, så äro de hans ovänner, för eder skull; men se vi på utkorelsen, så äro de hans älskade, för fädernas skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 29, 'Ty sina nådegåvor och sin kallelse kan Gud icke ångra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 30, 'Såsom I förut voren ohörsamma mot Gud, men nu genom dessas ohörsamhet haven fått barmhärtighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 31, 'så hava nu ock dessa varit ohörsamma, för att de, genom den barmhärtighet som har vederfarits eder, också själva skola få barmhärtighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 32, 'Ty Gud har givit dem alla till pris åt ohörsamhet, för att sedan förbarma sig över dem alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 33, 'O, vilket djup av rikedom och vishet och kunskap hos Gud! Huru outgrundliga äro icke hans domar, och huru outrannsakliga hans vägar!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 34, 'Ty »vem har lärt känna Herrens sinne, eller vem har varit hans rådgivare?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 35, 'Eller vem har först givit honom något, som han alltså bör betala igen?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 36, 'Av honom och genom honom och till honom är ju allting. Honom tillhör äran i evighet, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 1, 'Så förmanar jag nu eder, mina bröder, vid Guds barmhärtighet, att frambära edra kroppar till ett levande, heligt och Gud välbehagligt offer -- eder andliga tempeltjänst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 2, 'Och skicken eder icke efter denna tidsålders väsende, utan förvandlen eder genom edert sinnes förnyelse, så att I kunnen pröva vad som är Guds vilja, vad som är gott och välbehagligt och fullkomligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 3, 'Ty i kraft av den nåd som har blivit mig given, tillsäger jag var och en av eder att icke hava högre tankar om sig än tillbörligt är, utan tänka blygsamt, i överensstämmelse med det mått av tro som Gud har tilldelat var och en.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 4, 'Ty såsom vi i en och samma kropp hava många lemmar, men alla lemmarna icke hava samma förrättning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 5, 'så utgöra ock vi, fastän många, en enda kropp i Kristus, men var för sig äro vi lemmar, varandra till tjänst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 6, 'Och vi hava olika gåvor, alltefter den nåd som har blivit oss given. Har någon profetians gåva, så bruke han den efter måttet av sin tro;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 7, 'har någon fått en tjänst, så akte han på tjänsten; är någon satt till lärare, så akte han på sitt lärarkall;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 8, 'är någon satt till att förmana, så akte han på sin plikt att förmana. Den som delar ut gåvor, han göre det med gott hjärta; den som är satt till föreståndare, han vare det med nit; den som övar barmhärtighet, han göre det med glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 9, 'Eder kärlek vare utan skrymtan; avskyn det onda, hållen fast vid det goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 10, 'Älsken varandra av hjärtat i broderlig kärlek; söken överträffa varandra i inbördes hedersbevisning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 11, 'Varen icke tröga, där det gäller nit; varen brinnande i anden, tjänen Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 12, 'Varen glada i hoppet, tåliga i bedrövelsen, uthålliga i bönen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 13, 'Tagen del i de heligas behov. Varen angelägna om att bevisa gästvänlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 14, 'Välsignen dem som förfölja eder; välsignen, och förbannen icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 15, 'Glädjens med dem som äro glada, gråten med dem som gråta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 16, 'Varen ens till sinnes med varandra. Haven icke edert sinne vänt till vad högt är, utan hållen eder till det som är ringa. Hållen icke eder själva för kloka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 17, 'Vedergällen ingen med ont för ont. Vinnläggen eder om vad gott är inför var man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 18, 'Hållen frid med alla människor, om möjligt är, och så mycket som på eder beror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 19, 'Hämnens icke eder själva, mina älskade, utan lämnen rum för vredesdomen; ty det är skrivet: »Min är hämnden, jag skall vedergälla det, säger Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 20, 'Fastmer, »om din ovän är hungrig, så giv honom att äta, om han är törstig, så giv honom att dricka; ty om du så gör, samlar du glödande kol på hans huvud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 21, 'Låt dig icke övervinnas av det onda, utan övervinn det onda med det goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 1, 'Var och en vare underdånig den överhet som han har över sig. Ty ingen överhet finnes, som icke är av Gud; all överhet som finnes är förordnad av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 2, 'Därför, den som sätter sig upp mot överheten, han står emot vad Gud har förordnat; men de som stå emot detta, de skola få sin dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 3, 'Ty de som hava väldet äro till skräck, icke för dem som göra vad gott är, utan för dem som göra vad ont är. Vill du vara utan fruktan för överheten, så gör vad gott är; du skall då bliva prisad av den,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 4, 'ty överheten är en Guds tjänare, dig till fromma. Men gör du vad ont är, då må du frukta; ty överheten bär icke svärdet förgäves, utan är en Guds tjänare, en hämnare, till att utföra vredesdomen över den som gör vad ont är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 5, 'Därför måste man vara den underdånig, icke allenast för vredesdomens skull, utan ock för samvetets skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 6, 'Fördenskull betalen I ju ock skatt; ty överheten förrättar Guds tjänst och är just för detta ändamål ständigt verksam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 7, 'Så given åt alla vad I ären dem skyldiga; skatt åt den som skatt tillkommer, tull åt den som tull tillkommer, fruktan åt den som fruktan tillkommer, heder åt den som heder tillkommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 8, 'Varen ingen något skyldiga -- utom när det gäller kärlek till varandra; ty den som älskar sin nästa, han har uppfyllt lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 9, 'De buden: »Du skall icke begå äktenskapsbrott», »Du skall icke dräpa», »Du skall icke stjäla», »Du skall icke hava begärelse» och vilka andra bud som helst, de sammanfattas ju alla i det ordet: »Du skall älska din nästa såsom dig själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 10, 'Kärleken gör intet ont mot nästan; alltså är kärleken lagens uppfyllelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 11, 'Akten på allt detta, så mycket mer som I veten vad tiden lider, att stunden nu är inne för eder att vakna upp ur sömnen. Ty frälsningen är oss nu närmare, än då vi kommo till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 12, 'Natten är framskriden, och dagen är nära. Låtom oss därför avlägga mörkrets gärningar och ikläda oss ljusets vapenrustning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 13, 'Låtom oss föra en hövisk vandel, såsom om dagen, icke med vilt leverne och dryckenskap, icke i otukt och lösaktighet, icke i kiv och avund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 14, 'Ikläden eder fastmer Herren Jesus Kristus, och haven icke sådan omsorg om köttet, att onda begärelser därav uppväckas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 1, 'Om någon är svag i tron, så upptagen honom dock vänligt, utan att döma över andras betänkligheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 2, 'Den ene har tro till att äta vad som helst, under det att den som är svag allenast äter vad som växer på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 3, 'Den som äter må icke förakta den som icke äter. Ej heller må den som icke äter döma den som äter; ty Gud har upptagit honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 4, 'och vem är du som dömer en annans tjänare? Om han står eller faller, det kommer allenast hans egen herre vid; men han skall väl bliva stående, ty Herren är mäktig att hålla honom stående.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 5, 'Den ene gör skillnad mellan dag och dag, den andre håller alla dagar för lika; var och en vare fullt viss i sitt sinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 6, 'Om någon särskilt aktar på någon dag, så gör han detta för Herren, och om någon äter, så gör han detta för Herren; han tackar ju Gud. Så ock, om någon avhåller sig från att äta, gör han detta för Herren, och han tackar Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 7, 'Ty ingen av oss lever för sig själv, och ingen dör för sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 8, 'Leva vi, så leva vi för Herren; dö vi, så dö vi för Herren. Evad vi leva eller dö, höra vi alltså Herren till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 9, 'Ty därför har Kristus dött och åter blivit levande, att han skall vara herre över både döda och levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 10, 'Men du, varför dömer du din broder? Och du åter, varför föraktar du din broder? Vi skola ju alla en gång stå inför Guds domstol.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 11, 'Ty det är skrivet: »Så sant jag lever, säger Herren, för mig skola alla knän böja sig, och alla tungor skola prisa Gud.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 12, 'Alltså skall var och en av oss inför Gud göra räkenskap för sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 13, 'Låtom oss därför icke mer döma varandra. Dömen hellre så, att ingen må för sin broder lägga en stötesten eller något som bliver honom till fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 14, 'Jag vet väl och är i Herren Jesus viss om att intet i sig självt är orent; allenast om någon håller något för orent, så är det för honom orent.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 15, 'Om nu genom din mat bekymmer vållas din broder, så vandrar du icke mer i kärleken. Bliv icke genom din mat till fördärv för den som Kristus har lidit döden för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 16, 'Låten alltså icke det goda som I haven fått bliva utsatt för smädelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 17, 'Ty Guds rike består icke i mat och dryck, utan i rättfärdighet och frid och glädje i den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 18, 'Den som häri tjänar Kristus, han är välbehaglig för Gud och håller provet inför människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 19, 'Vi vilja alltså fara efter det som länder till frid och till inbördes uppbyggelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 20, 'Bryt icke för mats skull ned Guds verk. Väl är allting rent, men om ätandet för någon är en stötesten, så bliver det för den människan till ondo;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 21, 'du gör väl i att avhålla dig från att äta kött och dricka vin och från annat som för din broder bliver en stötesten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 22, 'Den tro du har må du hava för dig själv inför Gud. Salig är den som icke måste döma sig själv, när det gäller något som han har prövat vara rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 23, 'Men om någon hyser betänkligheter och likväl äter, då är han dömd, eftersom det icke sker av tro. Ty allt som icke sker av tro, det är synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 1, 'Vi som äro starka äro pliktiga att bära de svagas skröpligheter och att icke leva oss själva till behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 2, 'Var och en av oss må leva sin nästa till behag, honom till fromma och honom till uppbyggelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 3, 'Kristus levde ju icke sig själv till behag, utan med honom skedde såsom det är skrivet: »Dina smädares smädelser hava fallit över mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 4, 'Ty allt vad som fordom har blivit skrivet, det är skrivet oss till undervisning, för att vi, genom ståndaktighet och genom den tröst som skrifterna giva, skola bevara vårt hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 5, 'Och ståndaktighetens och tröstens Gud give eder att vara ens till sinnes med varandra i Kristi Jesu efterföljelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 6, 'så att I endräktigt och med en mun prisen vår Herres, Jesu Kristi, Gud och Fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 7, 'Därför må den ene av eder vänligt upptaga den andre, såsom Kristus, Gud till ära, har upptagit eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 8, 'Vad jag vill säga är detta: För de omskurna har Kristus blivit en tjänare, till ett vittnesbörd om Guds sannfärdighet, för att bekräfta de löften som hade givits åt fäderna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 9, 'hedningarna åter hava fått prisa Gud för hans barmhärtighets skull. Så är ock skrivet: »Fördenskull vill jag prisa dig bland hedningarna och lovsjunga ditt namn.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 10, 'Och åter heter det: »Jublen, I hedningar, med hans folk»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 11, 'så ock: »Loven Herren, alla hedningar, ja, honom prise alla folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 12, 'Så säger ock Esaias: »Telningen från Jessais rot skall komma, ja, han som skall stå upp för att råda över hedningarna; på honom skola hedningarna hoppas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 13, 'Men hoppets Gud uppfylle eder med all glädje och frid i tron, så att I haven ett överflödande hopp i den helige Andes kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 14, 'Jag är väl redan nu viss om att I, mina bröder, av eder själva ären fulla av godhet, uppfyllda med all kunskap, i stånd jämväl att förmana varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 15, 'Dock har jag, på ett delvis något dristigt sätt, skrivit till eder med ytterligare påminnelser, detta i kraft av den nåd som har blivit mig given av Gud:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 16, 'att jag nämligen skall förrätta Kristi Jesu tjänst bland hedningarna och vara en prästerlig förvaltare av Guds evangelium, så att hedningarna bliva ett honom välbehagligt offer, helgat i den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 17, 'Alltså är det i Kristus Jesus som jag har något att berömma mig av i fråga om min tjänst inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 18, 'Ty jag skall icke drista mig att orda om något annat än vad Kristus, för att göra hedningarna lydaktiga, har verkat genom mig, med ord och med gärning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 19, 'genom kraften i tecken och under, genom Andens kraft. Så har jag, från Jerusalem och runt omkring ända till Illyrien, överallt förkunnat evangelium om Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 20, 'Och jag har härvid satt min ära i att icke förkunna evangelium, där Kristi namn redan var känt, ty jag ville icke bygga på en annans grundval;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 21, 'utan så har skett, som skrivet är: »De för vilka intet har varit förkunnat om honom skola få se, och de som intet hava hört skola förstå.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 22, 'Det är också härigenom som jag så många gånger har blivit förhindrad att komma till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 23, 'Men då jag nu icke mer har något att uträtta i dessa trakter och under ganska många år har längtat efter att komma till eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 24, 'vill jag besöka eder, när jag begiver mig till Spanien. Jag hoppas nämligen att på genomresan få se eder och att därefter av eder bliva utrustad för färden dit, sedan jag först i någon mån har fått min längtan efter eder stillad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 25, 'Men nu far jag till Jerusalem med understöd åt de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 26, 'Macedonien och Akaja hava nämligen känt sig manade att göra ett sammanskott åt dem bland de heliga i Jerusalem, som leva i fattigdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 27, 'Ja, därtill hava de känt sig manade; de stå också i skuld hos dem. Ty om hedningarna hava fått del i deras andliga goda, så äro de å sin sida skyldiga att vara dem till tjänst med sitt lekamliga goda. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 28, 'När jag så har fullgjort detta och lämnat i deras händer vad som har blivit insamlat, ämnar jag därifrån begiva mig till Spanien och taga vägen genom eder stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 29, 'Och jag vet, att när jag kommer till eder, kommer jag med Kristi välsignelse i fullt mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 30, 'Och nu uppmanar jag eder, mina bröder, vid vår Herre Jesus Kristus och vid vår kärlek i Anden, att bistå mig i min kamp, genom att bedja för mig till Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 31, 'att jag må bliva frälst undan de ohörsamma i Judeen, och att det understöd som jag för med mig till Jerusalem må bliva väl mottaget av de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 32, 'Så skall jag, om Gud vill, med glädje komma till eder och vederkvicka mig tillsammans med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 33, 'Fridens Gud vare med eder alla. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 1, 'Jag anbefaller åt eder vår syster Febe, som är församlingstjänarinna i Kenkrea.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 2, 'Så mottagen då henne i Herren, såsom det höves de heliga, och bistån henne i allt vari hon kan behöva eder; ty hon har själv varit ett stöd för många och jämväl för mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 3, 'Hälsen Priska och Akvila, mina medarbetare i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 4, 'De hava ju vågat sitt liv för mig; och icke allenast jag tackar dem därför, utan också alla hednaförsamlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 5, 'Hälsen ock den församling som kommer tillhopa i deras hus. Hälsen Epenetus, min älskade broder, som är förstlingen av dem som i provinsen Asien hava kommit till Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 6, 'Hälsen Maria, som har arbetat så mycket för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 7, 'Hälsen Andronikus och Junias, mina landsmän och medfångar, som hava ett så gott anseende bland apostlarna, och som längre än jag hava varit i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 8, 'Hälsen Ampliatus, min älskade broder i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 9, 'Hälsen Urbanus, vår medarbetare i Kristus, och Stakys, min älskade broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 10, 'Hälsen Apelles, den i Kristus beprövade. Hälsen dem som höra till Aristobulus\' hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 11, 'Hälsen Herodion, min landsman. Hälsen dem av Narcissus\' hus, som äro i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 12, 'Hälsen Tryfena och Tryfosa, som arbeta i Herren. Hälsen Persis, den älskade systern, som har så mycket arbetat i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 13, 'Hälsen Rufus, den i Herren utvalde, och hans moder, som också för mig har varit en moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 14, 'Hälsen Asynkritus, Flegon, Hermes, Patrobas, Hermas och de bröder som äro tillsammans med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 15, 'Hälsen Filologus och Julia, Nereus och hans syster och Olympas och alla de heliga som äro tillsammans med dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 16, 'Hälsen varandra med en helig kyss. Alla Kristi församlingar hälsa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 17, 'Men jag förmanar eder, mina bröder, att hava akt på dem som vålla tvedräkt och kunna bliva eder till fall, i strid med den lära som I haven inhämtat; dragen eder ifrån dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 18, 'Ty sådana tjäna icke vår Herre Kristus, utan sin egen buk; och genom sina milda ord och sitt fagra tal bedraga de oskyldiga människors hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 19, 'Eder lydnad är ju känd av alla. Över eder gläder jag mig därför; men jag skulle önska att I voren visa i fråga om det goda, och menlösa i fråga om det onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 20, 'Och fridens Gud skall snart låta Satan bliva krossad under edra fötter. Vår Herres, Jesu Kristi, nåd vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 21, 'Timoteus, min medarbetare, hälsar eder: så göra ock Lucius och Jason och Sosipater, mina landsmän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 22, 'Jag, Tertius, som har nedskrivit detta brev, hälsar eder i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 23, 'Gajus, min och hela församlingens värd, hälsar eder. Erastus, stadens kamrerare, och brodern Kvartus hälsar eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 24, '[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 25, 'Men honom som förmår styrka eder, enligt det evangelium jag förkunnar och min predikan om Jesus Kristus, ja, enligt den nu avslöjade hemlighet som förut under evärdliga tider har varit outtalad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 26, 'men som nu har blivit uppenbarad och, enligt den eviga Gudens befallning, blivit, med stöd av profetiska skrifter, kungjord bland alla hedningar, för att bland dem upprätta trons lydnad --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 27, 'honom, den ende vise Guden, tillhör äran, genom Jesus Kristus, i evigheternas evigheter. Amen. [1] V. 24 se Nya testamentets text i Ordförklaringarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Paulus, genom Guds vilja kallad till Kristi Jesu apostel, så ock brodern Sostenes,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'hälsar den Guds församling som finnes i Korint, de i Kristus Jesus helgade, dem som äro kallade och heliga, jämte alla andra som åkalla vår Herres, Jesu Kristi, namn, på alla orter där de eller vi bo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Jag tackar Gud alltid för eder skull, för den Guds nåd som har blivit eder given i Kristus Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'att I haven i honom blivit rikligen begåvade i alla stycken, i fråga om allt vad tal och kunskap heter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Så har ju ock vittnesbördet om Kristus blivit befäst hos eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'så att I icke stån tillbaka i fråga om någon nådegåva, medan I vänten på vår Herres, Jesu Kristi, uppenbarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Han skall ock göra eder ståndaktiga intill änden, så att I ären ostraffliga på vår Herres, Jesu Kristi, dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Gud är trofast, han genom vilken I haven blivit kallade till gemenskap med hans Son, Jesus Kristus, vår Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Men jag förmanar eder, mina bröder, vid vår Herres, Jesu Kristi, namn, att alla vara eniga i edert tal och att icke låta söndringar finnas bland eder, utan hålla fast tillhopa i samma sinnelag och samma tänkesätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Det har nämligen av Kloes husfolk blivit mig berättat om eder, mina bröder, att tvister hava uppstått bland eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Härmed menar jag att bland eder den ene säger: »Jag håller mig till Paulus», den andre: »Jag håller mig till Apollos», en annan: »Jag håller mig till Cefas», åter en annan: »Jag håller mig till Kristus.» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Är då Kristus delad? Icke blev väl Paulus korsfäst för eder? Och icke bleven I väl döpta i Paulus\' namn?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'Jag tackar Gud för att jag icke har döpt någon bland eder utom Krispus och Gajus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'så att ingen kan säga att I haven blivit döpta i mitt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'Dock, jag har döpt också Stefanas\' husfolk; om jag eljest har döpt någon vet jag icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 17, 'Ty Kristus har icke sänt mig till att döpa, utan till att förkunna evangelium, och detta icke med en visdom som består i ord, för att Kristi kors icke skall berövas sin kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 18, 'Ty talet om korset är visserligen en dårskap för dem som gå förlorade, men för oss som bliva frälsta är det en Guds kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 19, 'Det är ju skrivet: »Jag skall göra de visas vishet om intet, och de förståndigas förstånd skall jag slå ned.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 20, 'Ja, var äro de visa? Var äro de skriftlärda? Var äro denna tidsålders klyftiga män? Har icke Gud gjort denna världens visdom till dårskap?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 21, 'Jo, eftersom världen icke genom sin visdom lärde känna Gud i hans visdom, behagade det Gud att genom den dårskap han lät predikas frälsa dem som tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 22, 'Ty judarna begära tecken, och grekerna åstunda visdom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 23, 'vi åter predika en korsfäst Kristus, en som för judarna är en stötesten och för hedningarna en dårskap,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 24, 'men som för de kallade, vare sig judar eller greker, är en Kristus som är Guds kraft och Guds visdom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 25, 'Ty Guds dårskap är visare än människor, och Guds svaghet är starkare än människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 26, 'Ty betänken, mina bröder, huru det var vid eder kallelse: icke många som voro visa efter köttet blevo kallade, icke många mäktiga, icke många av förnämlig släkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 27, 'Men det som för världen var dåraktigt, det utvalde Gud, för att han skulle låta de visa komma på skam.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 28, 'Och det som i världen var svagt, det utvalde Gud, för att han skulle låta det starka komma på skam. Och det som i världen var ringa och föraktat, det utvalde Gud -- ja, det som ingenting var -- för att han skulle göra det till intet, som någonting var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 29, 'Ty han ville icke att något kött skulle kunna berömma sig inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 30, 'Men hans verk är det, att I ären i Kristus Jesus, som för oss har blivit till visdom från Gud, till rättfärdighet och helgelse och till förlossning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 31, 'för att så skall ske, som det är skrivet: »Den som vill berömma sig, han berömme sig av Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'När jag kom till eder, mina bröder, var det också icke med höga ord eller hög visdom som jag kom och frambar för eder Guds vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'Ty jag hade beslutit mig för, att medan jag var bland eder icke veta om något annat än Jesus Kristus, och honom såsom korsfäst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'Och jag uppträdde hos eder i svaghet och med fruktan och mycken bävan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'Och mitt tal och min predikan framställdes icke med övertalande visdomsord, utan med en bevisning i ande och kraft;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'ty eder tro skulle icke vara grundad på människors visdom, utan på Guds kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Visdom tala vi dock bland dem som äro fullmogna, men en visdom som icke tillhör denna tidsålder eller denna tidsålders mäktige, vilkas makt bliver till intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'Nej, vi tala Guds hemliga visdom, den fördolda, om vilken Gud, redan före tidsåldrarnas begynnelse, har bestämt att den skall bliva oss till härlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'och som ingen av denna tidsålders mäktige har känt; ty om de hade känt den, så hade de icke korsfäst härlighetens Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'Vi tala -- såsom det heter i skriften -- »vad intet öga har sett och intet öra har hört, och vad ingen människas hjärta har kunnat tänka, vad Gud har berett åt dem som älska honom».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'Ty för oss har Gud uppenbarat det genom sin Ande. Anden utrannsakar ju allt, ja ock Guds djuphet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Ty vilken människa vet vad som är i en människa, utom den människans egen ande? Likaså känner ingen vad som är i Gud, utom Guds Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'Men vi hava icke fått världens ande, utan den Ande som är av Gud, för att vi skola veta vad som har blivit oss skänkt av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'Om detta tala vi ock, icke med sådana ord som mänsklig visdom lär oss, utan med sådana ord som Anden lär oss; vi hava ju att tyda andliga ting för andliga människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Men en »själisk»[1] människa tager icke emot vad som hör Guds Ande till. Det är henne en dårskap, och hon kan icke förstå det, ty det måste utgrundas på ett andligt sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'Den andliga människan åter kan utgrunda allt, men själv kan hon icke utgrundas av någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'Ty »vem har lärt känna Herrens sinne, så att han skulle kunna undervisa honom?» Men vi hava Kristi sinne. [1] Se Själisk i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Och jag kunde icke tala till eder, mina bröder, såsom till andliga människor, utan måste tala såsom till människor av köttslig natur, såsom till dem som ännu äro barn i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'Mjölk gav jag eder att dricka; fast föda gav jag eder icke, ty det fördrogen I då ännu icke. Ja, icke ens nu fördragen I det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'eftersom I ännu haven ett köttsligt sinne. Ty om avund och kiv finnes bland eder, haven I icke då ett köttsligt sinne, och vandren I icke då på vanligt människosätt?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'När den ene säger: »Jag håller mig till Paulus» och den andre: »Jag håller mig till Apollos», ären I icke då lika hopen av människor?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'Vad är då Apollos? Vad är Paulus? Allenast tjänare, genom vilka I haven kommit till tro; och de äro det i mån av vad Herren har beskärt åt var och en av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'Jag planterade, Apollos vattnade, men Gud gav växten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'Alltså kommer det icke an på den som planterar, ej heller på den som vattnar, utan på Gud, som giver växten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Den som planterar och den som vattnar -- den ene är såsom den andre, dock så, att var och en skall få sin särskilda lön efter sitt särskilda arbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'Ty vi äro Guds medarbetare; I ären ett Guds åkerfält, en Guds byggnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Efter den Guds nåd som blev mig given lade jag grunden såsom en förfaren byggmästare, och en annan bygger nu vidare därpå. Men var och en må se till, huru han bygger därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'Ty en annan grund kan ingen lägga, än den som är lagd, nämligen Jesus Kristus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'men om någon bygger på den grunden med guld, silver och dyrbara stenar eller med trä, hö och strå,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'så skall det en gång visa sig huru det är med vars och ens verk. »Den dagen»[1] skall göra det kunnigt; ty den skall uppenbaras i eld, och hurudant vars och ens verk är, det skall elden pröva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Om det byggnadsverk, som någon har uppfört på den grunden, bliver beståndande, så skall han undfå lön;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'men om hans verk brännes upp, så skall han gå miste om lönen. Själv skall han dock bliva frälst, men såsom igenom eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'Veten I icke att I ären ett Guds tempel och att Guds Ande bor i eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'Om nu någon fördärvar Guds tempel, så skall Gud fördärva honom; ty Guds tempel är heligt, och det templet ären I.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, 'Ingen bedrage sig själv. Om någon bland eder menar sig vara vis genom denna tidsålders visdom, så blive han en dåre, för att han skall kunna bliva vis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 19, 'Ty denna världens visdom är dårskap inför Gud. Det är ju skrivet: »Han fångar de visa i deras klokskap»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 20, 'så ock: »Herren känner de visas tankar, han vet att de äro fåfängliga.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 21, 'Så berömme sig då ingen av människor. Allt hör ju eder till;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 22, 'det må vara Paulus eller Apollos eller Cefas eller hela världen, det må vara liv eller död, vad som nu är, eller vad som skall komma, alltsammans hör eder till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 23, 'Men I hören Kristus till, och Kristus hör Gud till. [1] Se Dagen i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 1, 'Såsom Kristi tjänare och såsom förvaltare av Guds hemligheter, så må man anse oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 2, 'Vad man nu därutöver söker hos förvaltare är att en sådan må befinnas vara trogen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 3, 'För mig betyder det likväl föga att I -- eller överhuvud någon mänsklig domstol -- sätten eder till doms över mig. Ja, jag vill icke ens sätta mig till doms över mig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 4, 'Ty väl vet jag intet med mig, men därigenom är jag icke rättfärdigad; det är Herren som sitter till doms över mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 5, 'Dömen därför icke förrän tid är, icke förrän Herren kommer, han som skall draga fram i ljuset vad som är fördolt i mörker och uppenbara alla hjärtans rådslag. Och då skall var och en undfå av Gud den berömmelse som honom tillkommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 6, 'Detta, mina bröder, har jag nu för eder skull så framställt, som gällde det mig och Apollos; ty jag vill att I skolen i fråga om oss lära eder detta: »Icke utöver vad skrivet är.» Jag vill icke att I skolen stå emot varandra, uppblåsta var och en över sin lärare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 7, 'Vem säger då att du har något företräde? Och vad äger du, som du icke har fått dig givet? Men har du nu fått dig givet vad du har, huru kan du då berömma dig, såsom om du icke hade fått det dig givet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 8, 'I ären kantänka redan mätta, I haven redan blivit rika; oss förutan haven I blivit sannskyldiga konungar! Ja, jag skulle önska att I verkligen haden blivit konungar, så att vi kunde få bliva edra medkonungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 9, 'Mig tyckes nämligen att Gud har ställt oss apostlar här såsom de ringaste bland alla, såsom livdömda män; ett skådespel hava vi ju blivit för världen, för både änglar och människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 10, 'Vi äro dårar för Kristi skull, men I ären kloka i Kristus; vi äro svaga, men I ären starka; I ären ärade, men vi äro föraktade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 11, 'Ännu i denna stund lida vi både hunger och törst, vi måste gå nakna, vi få uppbära hugg och slag, vi hava intet stadigt hemvist,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 12, 'vi måste möda oss och arbeta med våra händer. Vi bliva smädade och välsigna likväl; vi lida förföljelse och härda dock ut;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 13, 'man talar illa om oss, men vi tala goda ord. Vi hava blivit såsom världens avskum, såsom var mans avskrap, och vi äro så ännu alltjämt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 14, 'Detta skriver jag, icke för att komma eder att blygas, utan såsom en förmaning till mina älskade barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 15, 'Ty om I än haden tio tusen uppfostrare i Kristus, så haven I dock icke många fäder; det var ju jag som i Kristus Jesus genom evangelium födde eder till liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 16, 'Därför förmanar jag eder: Bliven mina efterföljare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 17, 'Just för denna saks skull sänder jag nu till eder Timoteus, min älskade och trogne son i Herren; han skall påminna eder om huru jag går till väga i Kristus, i enlighet med den lära jag förkunnar allestädes, i alla församlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 18, 'Nu är det väl så, att somliga hava blivit uppblåsta, under förmenande att jag icke skulle komma till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 19, 'Men om Herren så vill, skall jag snart komma till eder; och då skall jag lära känna, icke dessa uppblåsta människors ord, utan deras kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 20, 'Ty Guds rike består icke i ord, utan i kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 21, 'Vilketdera viljen I nu: skall jag komma till eder med ris eller i kärlek och saktmods ande?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 1, 'Det förljudes såväl att överhuvud otukt bedrives bland eder, som ock att sådan otukt förekommer, som man icke ens finner bland hedningarna, nämligen att en son har sin faders hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 2, 'Och ändå ären I uppblåsta och haven icke fastmer blivit uppfyllda av sådan sorg, att I haven drivit ut ur eder krets den som har gjort detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 3, 'Jag, som väl till kroppen är frånvarande, men till anden närvarande, har för min del redan, såsom vore jag närvarande, fällt domen över den som har förövat en sådan ogärning:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 4, 'i Herren Jesu namn skola vi komma tillsammans, I och min ande, med vår Herre Jesu kraft,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 5, 'och överlämna den mannen åt Satan till köttets fördärv, för att anden skall bliva frälst på Herren Jesu dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 6, 'Det är icke väl beställt med eder berömmelse. Veten I icke att litet surdeg syrar hela degen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 7, 'Rensen bort den gamla surdegen, så att I bliven en ny deg. I ären ju osyrade; ty vi hava ock ett påskalamm, som är slaktat, nämligen Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 8, 'Låtom oss därför hålla högtid, icke med gammal surdeg, icke med elakhetens och ondskans surdeg, utan med renhetens och sanningens osyrade bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 9, 'Jag skrev till eder i mitt brev att I icke skullen hava något umgänge med otuktiga människor --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 10, 'detta icke sagt i allmänhet, om alla denna världens otuktiga människor eller om giriga och roffare eller om avgudadyrkare; annars måsten I ju rymma ur världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 11, 'Nej, då jag skrev så till eder, menade jag, att om någon som kallades broder vore en otuktig människa eller en girig eller en avgudadyrkare eller en smädare eller en drinkare eller en roffare, så skullen I icke hava något umgänge med en sådan eller äta tillsammans med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 12, 'Ty icke tillkommer det väl mig att döma dem som äro utanför? Dem som äro innanför haven I ju att döma;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 13, 'dem som äro utanför skall Gud döma. »I skolen driva ut ifrån eder den som är ond.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 1, 'Huru kan någon av eder taga sig för, att när han har sak med en annan, gå till rätta icke inför de heliga, utan inför de orättfärdiga?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 2, 'Veten I då icke att de heliga skola döma världen? Men om nu I skolen sitta till doms över världen, ären I då icke goda nog att döma i helt ringa mål?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 3, 'I veten ju att vi skola döma änglar; huru mycket mer böra vi icke då kunna döma i timliga ting?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 4, 'Och likväl, när I nu haven före något mål som gäller sådana ting, sätten I till domare just dem som äro ringa aktade i församlingen!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 5, 'Eder till blygd säger jag detta. Är det då så omöjligt att bland eder finna någon vis man, som kan bliva skiljedomare mellan sina bröder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 6, 'Måste i stället den ene brodern gå till rätta med den andre, och det inför de otrogna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 7, 'Överhuvud är redan det en brist hos eder, att I gån till rätta med varandra. Varför liden I icke hellre orätt? Varför låten I icke hellre andra göra eder skada?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 8, 'I stället gören I nu själva orätt och skada, och detta mot bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 9, 'Veten I då icke att de orättfärdiga icke skola få Guds rike till arvedel? Faren icke vilse. Varken otuktiga människor eller avgudadyrkare eller äktenskapsbrytare, varken de som låta bruka sig till synd mot naturen eller de som själva öva sådan synd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 10, 'varken tjuvar eller giriga eller drinkare eller smädare eller roffare skola få Guds rike till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 11, 'Sådana voro ock somliga bland eder, men I haven låtit två eder rena, I haven blivit helgade, I haven blivit rättfärdiggjorda i Herrens, Jesu Kristi, namn och i vår Guds Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 12, '»Allt är mig lovligt»; ja, men icke allt är nyttigt. »Allt är mig lovligt»; ja, men jag bör icke låta något få makt över mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 13, 'Maten är för buken och buken för maten, men bådadera skall Gud göra till intet. Däremot är kroppen icke för otukt, utan för Herren, och Herren för kroppen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 14, 'och Gud, som har uppväckt Herren, skall ock genom sin kraft uppväcka oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 15, 'Veten I icke att edra kroppar äro Kristi lemmar? Skall jag nu taga Kristi lemmar och göra dem till en skökas lemmar? Bort det!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 16, 'Veten I då icke att den som håller sig till en sköka, han bliver en kropp med henne? Det heter ju: »De tu skola varda ett kött.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 17, 'Men den som håller sig till Herren, han är en ande med honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 18, 'Flyn otukten. All annan synd som en människa kan begå är utom kroppen; men den som bedriver otukt, han syndar på sin egen kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 19, 'Veten I då icke att eder kropp är ett tempel åt den helige Ande, som bor i eder, och som I haven undfått av Gud, och att I icke ären edra egna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 20, 'I ären ju köpta, och betalning är given. Så förhärligen då Gud i eder kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 1, 'Vad nu angår det I haven skrivit om, så svarar jag detta: En man gör visserligen väl i att icke komma vid någon kvinna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 2, 'men för att undgå otuktssynder må var man hava sin egen hustru, och var kvinna sin egen man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 3, 'Mannen give sin hustru vad han är henne pliktig, sammalunda ock hustrun sin man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 4, 'Hustrun råder icke själv över sin kropp, utan mannen; sammalunda råder ej heller mannen över sin kropp, utan hustrun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 5, 'Dragen eder icke undan från varandra, om icke möjligen, med bådas samtycke, till en tid, för att I skolen hava ledighet till bönen. Kommen sedan åter tillsammans, så att Satan icke frestar eder, då I nu icke kunnen leva återhållsamt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 6, 'Detta säger jag likväl såsom en tillstädjelse, icke såsom en befallning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 7, 'Jag skulle dock vilja att alla människor vore såsom jag. Men var och en har fått sin särskilda nådegåva från Gud, den ene så, den andre så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 8, 'Till de ogifta åter och till änkorna säger jag att de göra väl, om de förbliva i samma ställning som jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 9, 'Men kunna de icke leva återhållsamt, så må de gifta sig; ty det är bättre att gifta sig än att vara upptänd av begär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 10, 'Men dem som äro gifta bjuder jag -- dock icke jag, utan Herren; En hustru må icke skilja sig från sin man');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 11, '(om hon likväl skulle skilja sig, så förblive hon ogift eller förlike sig åter med mannen), ej heller må en man förskjuta sin hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 12, 'Till de andra åter säger jag själv, icke Herren: Om någon som hör till bröderna har en hustru som icke är troende, och denna är villig att leva tillsammans med honom, så må han icke förskjuta henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 13, 'Likaså, om en hustru har en man som icke är troende, och denne är villig att leva tillsammans med henne, så må hon icke förskjuta mannen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 14, 'Ty den icke troende mannen är helgad i och genom sin hustru, och den icke troende hustrun är helgad i och genom sin man, då han är en broder; annars vore ju edra barn orena, men nu äro de heliga. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 15, 'Om däremot den icke troende vill skiljas, så må han få skiljas. En broder eller syster är i sådana fall intet tvång underkastad, och Gud har kallat oss till att leva i frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 16, 'Ty huru kan du veta, du hustru, om du skall frälsa din man? Eller du man, huru vet du om du skall frälsa din hustru?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 17, 'Må allenast var och en vandra den väg fram, som Herren har bestämt åt honom, var och en i den ställning vari Gud har kallat honom. Den ordningen stadgar jag för alla församlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 18, 'Har någon blivit kallad såsom omskuren, så göre han sig icke åter lik de oomskurna; har någon blivit kallad såsom oomskuren, så låte han icke omskära sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 19, 'Det kommer icke an på om någon är omskuren eller oomskuren; allt beror på huruvida han håller Guds bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 20, 'Var och en förblive i den kallelse vari han var, när han blev kallad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 21, 'Har du blivit kallad såsom träl, så låt detta icke gå dig till sinnes; dock, om du kan bliva fri, så begagna dig hellre därav[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 22, 'Ty den träl som har blivit kallad till att vara i Herren, han är en Herrens frigivne; sammalunda är ock den frie, som har blivit kallad, en Kristi livegne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 23, 'I ären köpta, och betalningen är given; bliven icke människors trälar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 24, 'Ja, mina bröder, var och en förblive inför Gud i den ställning vari han har blivit kallad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 25, 'Vad vidare angår dem som äro jungfrur, så har jag icke att åberopa någon befallning av Herren, utan giver allenast ett råd, såsom en som genom Herrens barmhärtighet har blivit förtroende värd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 26, 'Jag menar alltså, med tanke på den nöd som står för dörren, att den människa gör väl, som förbliver såsom hon är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 27, 'Är du bunden vid hustru, så sök icke att bliva lös. Är du utan hustru, så sök icke att få hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 28, 'Om du likväl skulle gifta dig, så syndar du icke därmed; ej heller syndar en jungfru, om hon gifter sig. Dock komma de som så göra att draga över sig lekamliga vedermödor; och jag skulle gärna vilja skona eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 29, 'Men det säger jag, mina bröder: Tiden är kort; därför må härefter de som hava hustrur vara såsom hade de inga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 30, 'och de som gråta såsom gräte de icke, och de som glädja sig såsom gladde de sig icke, och de som köpa något såsom finge de icke behålla det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 31, 'och de som bruka denna världen såsom gjorde de icke något bruk av den. Ty den nuvarande världsordningen går mot sitt slut;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 32, 'och jag skulle gärna vilja att I voren fria ifrån omsorger. Den man som icke är gift ägnar nämligen sin omsorg åt vad som hör Herren till, huru han skall behaga Herren;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 33, 'men den gifte mannen ägnar sin omsorg åt vad som hör världen till, huru han skall behaga sin hustru,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 34, 'och så är hans hjärta delat. Likaså ägnar den kvinna, som icke längre är gift eller som är jungfru, sin omsorg åt vad som hör Herren till, att hon må vara helig till både kropp och ande; men den gifta kvinnan ägnar sin omsorg åt vad som hör världen till, huru hon skall behaga sin man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 35, 'Detta säger jag till eder egen nytta, och icke för att lägga något band på eder, utan för att I skolen föra en hövisk vandel och stadigt förbliva vid Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 36, 'Men om någon menar sig handla otillbörligt mot sin ogifta dotter därmed att hon får bliva överårig, då må han göra såsom han vill, om det nu måste så vara; han begår därmed ingen synd. Må hon få gifta sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 37, 'Om däremot någon är fast i sitt sinne och icke bindes av något nödtvång, utan kan följa sin egen vilja, och så i sitt sinne är besluten att låta sin ogifta dotter förbliva såsom hon är, då gör denne väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 38, 'Alltså: den som gifter bort sin dotter, han gör väl; och den som icke gifter bort henne, han gör ännu bättre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 39, 'En hustru är bunden så länge hennes man lever; men när hennes man är avsomnad, står det henne fritt att gifta sig med vem hon vill, blott det sker i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 40, 'Men lyckligare är hon, om hon förbliver såsom hon är. Så är min mening, och jag tror att också jag har Guds Ande. [1] Eller: Har du blivit kallad såsom träl, så låt detta icke gå dig till sinnes; om du än kunde bliva fri, så behåll hellre din ställning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 1, 'Vad åter angår kött från avgudaoffer, så känna vi nog det talet: »Alla hava vi \'kunskap\'[1].» »Kunskapen» uppblåser, men kärleken uppbygger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 2, 'Om någon menar sig hava fått någon »kunskap», så har han ännu icke fått kunskap på sådant sätt som han borde hava.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 3, 'Men den som älskar Gud, han är känd av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 4, 'Vad alltså angår ätandet av kött från avgudaoffer, så säger jag detta: Vi veta visserligen att ingen avgud finnes till i världen, och att det icke finnes mer än en enda Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 5, 'Ty om ock några så kallade gudar skulle finnas, vare sig i himmelen eller på jorden -- och det finnes ju många »gudar» och många »herrar» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 6, 'så finnes dock för oss allenast en enda Gud: Fadern, av vilken allt är, och till vilken vi själva äro, och en enda Herre: Jesus Kristus, genom vilken allt är, och genom vilken vi själva äro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 7, 'Dock, icke alla hava denna kunskap, utan somliga, som äro vana att ännu alltjämt tänka på avguden, äta köttet såsom avgudaofferskött. Och eftersom deras samvete är svagt, bliver det härigenom befläckat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 8, 'Men maten skall icke avgöra vår ställning till Gud. Avhålla vi oss från att äta, så bliva vi icke därigenom sämre; äta vi, så bliva vi icke därigenom bättre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 9, 'Sen likväl till, att denna eder frihet icke till äventyrs bliver en stötesten för de svaga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 10, 'Ty om någon får se dig, som har undfått »kunskap», ligga till bords i ett avgudahus, skall då icke hans samvete, om han är svag, därav »bliva uppbyggt» på det sätt att han äter köttet från avgudaoffer?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 11, 'Genom din »kunskap» går ju då den svage förlorad -- han, din broder, som Kristus har lidit döden för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 12, 'Om I på sådant sätt synden mot bröderna och såren deras svaga samveten, då synden I mot Kristus själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 13, 'Därför, om maten kan bliva min broder till fall, så vill jag sannerligen hellre för alltid avstå från att äta kött, på det att jag icke må bliva min broder till fall. [1] Se Kunskap i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 1, 'Är jag icke fri? Är jag icke en apostel? Har jag icke sett Jesus, vår Herre? Ären icke I mitt verk i Herren?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 2, 'Om jag icke för andra är en apostel, så är jag det åtminstone för eder, ty I själva ären i Herren inseglet på mitt apostlaämbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 3, 'Detta är mitt försvar mot dem som sätta sig till doms över mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 4, 'Skulle vi kanhända icke hava rätt att få mat och dryck?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 5, 'Skulle vi icke hava rätt att få såsom hustru föra med oss på våra resor någon som är en syster, vi likaväl som de andra apostlarna och Herrens bröder och särskilt Cefas?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 6, 'Eller äro jag och Barnabas de enda som icke hava rätt att vara fritagna ifrån kroppsarbete?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 7, 'Vem tjänar någonsin i krig på egen sold? Vem planterar en vingård och äter icke dess frukt? Eller vem vaktar en hjord och förtär icke mjölk från hjorden?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 8, 'Icke talar jag väl detta därför att människor pläga så tala? Säger icke själva lagen detsamma?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 9, 'I Moses\' lag är ju skrivet: »Du skall icke binda munnen till på oxen som tröskar.» Månne det är om oxarna som Gud har sådan omsorg?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 10, 'Eller säger han det icke i alla händelser med tanke på oss? Jo, för vår skull blev det skrivet, att den som plöjer bör plöja med en förhoppning, och att den som tröskar bör göra det i förhoppning om att få sin del.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 11, 'Om vi hava sått åt eder ett utsäde av andligt gott, är det då för mycket, om vi få inbärga från eder en skörd av lekamligt gott?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 12, 'Om andra hava en viss rättighet över eder, skulle då icke vi än mer hava det? Och likväl hava vi icke gjort bruk av den rättigheten, utan vi fördraga allt, för att icke lägga något hinder i vägen för Kristi evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 13, 'I veten ju att de som förrätta tjänsten i helgedomen få sin föda ifrån helgedomen, och att de som äro anställda vid altaret få sin del, när altaret får sin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 14, 'Så har ock Herren förordnat att de som förkunna evangelium skola hava sitt uppehälle av evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 15, 'Men jag för min del har icke gjort bruk av någon sådan förmån. Detta skriver jag nu icke, för att jag själv skall få någon sådan; långt hellre ville jag dö. Nej, ingen skall göra min berömmelse om intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 16, 'Ty om jag förkunnar evangelium, så är detta ingen berömmelse för mig. Jag måste ju så göra; och ve mig, om jag icke förkunnade evangelium!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 17, 'Gör jag det av egen drift, så har jag rätt till lön; men då jag nu icke gör det av egen drift, så är den syssla som jag är betrodd med allenast en livegen förvaltares[1]. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 18, 'Vilken är alltså min lön? Jo, just den, att när jag förkunnar evangelium, så gör jag detta utan kostnad för någon, i det att jag avstår från att göra bruk av den rättighet jag har såsom förkunnare av evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 19, 'Ty fastän jag är fri och oberoende av alla, har jag dock gjort mig till allas tjänare, för att jag skall vinna dess flera.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 20, 'För judarna har jag blivit såsom en jude, för att kunna vinna judar; för dom som stå under lagen har jag, som själv icke står under lagen, blivit såsom stode jag under lagen, för att kunna vinna dem som stå under lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 21, 'För dem som äro utan lag har jag, som icke är utan Guds lag, men är i Kristi lag, blivit såsom vore jag utan lag, för att jag skall vinna dem som äro utan lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 22, 'För de svaga har jag blivit svag, för att kunna vinna de svaga; för alla har jag blivit allt, för att jag i alla händelser skall frälsa några.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 23, 'Men allt gör jag för evangelii skull, för att också jag skall bliva delaktig av dess goda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 24, 'I veten ju, att fastän de som löpa på tävlingsbanan allasammans löpa, så vinner allenast en segerlönen. Löpen såsom denne, för att I mån vinna lönen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 25, 'Men alla som vilja deltaga i en sådan tävlan pålägga sig återhållsamhet i alla stycken: dessa för att vinna en förgänglig segerkrans, men vi för att vinna en oförgänglig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 26, 'Jag för min del löper alltså icke såsom gällde det ett ovisst mål; jag kämpar icke likasom en man som hugger i vädret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 27, 'Fastmer tuktar jag min kropp och kuvar den, för att jag icke, när jag predikar för andra, själv skall komma till korta vid provet. [1] Se Förvaltare i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 1, 'Ty jag vill säga eder detta, mina bröder: Våra fäder voro alla under molnskyn och gingo alla genom havet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 2, 'alla blevo de i molnskyn och i havet döpta till Moses;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 3, 'alla åto de samma andliga mat,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 4, 'och alla drucko de samma andliga dryck -- de drucko nämligen ur en andlig klippa, som åtföljde dem, och den klippan var Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 5, 'Men de flesta av dem hade Gud icke behag till; de blevo ju nedgjorda i öknen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 6, 'Detta skedde oss till en varnagel, för att vi icke skulle hava begärelse till det onda, såsom de hade begärelse därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 7, 'Ej heller skolen I bliva avgudadyrkare, såsom somliga av dem blevo; så är ju skrivet: »Folket satte sig ned till att äta och dricka, och därpå stodo de upp till all leka.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 8, 'Låtom oss icke heller bedriva otukt, såsom somliga av dem gjorde, varför ock tjugutre tusen föllo på en enda dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 9, 'Låtom oss icke heller fresta Kristus, såsom somliga av dem gjorde, varför de ock blevo dödade av ormarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 10, 'Knorren icke heller, såsom somliga av dem gjorde, varför de ock blevo dödade av »Fördärvaren».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 11, 'Men detta vederfors dem för att tjäna till en varnagel, och det blev upptecknat till lärdom för oss, som hava tidernas ände inpå oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 12, 'Därför, den som menar sig stå, han må se till, att han icke faller.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 13, 'Inga andra frestelser hava mött eder än sådana som vanligen möta människor. Och Gud är trofast; han skall icke tillstädja att I bliven frestade över eder förmåga, utan när han låter frestelsen komma, skall han ock bereda en utväg därur, så att I kunnen härda ut i den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 14, 'Alltså, mina älskade, undflyn avgudadyrkan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 15, 'Jag säger detta till eder såsom till förståndiga människor; själva mån I döma om det som jag säger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 16, 'Välsignelsens kalk, över vilken vi uttala välsignelsen, är icke den en delaktighet av Kristi blod? Brödet, som vi bryta, är icke det en delaktighet av Kristi kropp?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 17, 'Eftersom det är ett enda bröd, så äro vi, fastän många, en enda kropp, ty alla få vi vår del av detta ena bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 18, 'Sen på det lekamliga Israel: äro icke de som äta av offren delaktiga i altaret?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 19, 'Vad vill jag då säga härmed? Månne att avgudaofferskött är någonting, eller att en avgud är någonting?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 20, 'Nej, det vill jag säga, att vad hedningarna offra, det offra de åt onda andar och icke åt Gud; och jag vill icke att I skolen hava någon gemenskap med de onda andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 21, 'I kunnen icke dricka Herrens kalk och tillika onda andars kalk; I kunnen icke hava del i Herrens bord och tillika i onda andars bord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 22, 'Eller vilja vi reta Herren? Äro då vi starkare än han?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 23, '»Allt är lovligt»; ja, men icke allt är nyttigt. »Allt är lovligt»; ja, men icke allt uppbygger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 24, 'Ingen söke sitt eget bästa, utan envar den andres.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 25, 'Allt som säljes i köttboden mån I äta; I behöven icke för samvetets skull göra någon undersökning därom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 26, 'Ty »jorden är Herrens, och allt vad därpå är».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 27, 'Om någon av dem som icke äro troende bjuder eder till sig och I viljen gå till honom, så mån I äta av allt som sättes fram åt eder; I behöven icke för samvetets skull göra någon undersökning därom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 28, 'Men om någon då säger till eder: »Detta är offerkött», så skolen I avhålla eder från att äta, för den mans skull, som gav saken till känna, och för samvetets skull --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 29, 'jag menar icke ditt eget samvete, utan den andres; ty varför skulle jag låta min frihet dömas av en annans samvete?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 30, 'Om jag äter därav med tacksägelse, varför skulle jag då bliva smädad för det som jag tackar Gud för?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 31, 'Alltså, vare sig I äten eller dricken, eller vadhelst annat I gören, så gören allt till Guds ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 32, 'Bliven icke för någon till en stötesten, varken för judar eller för greker eller för Guds församling;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 33, 'varen såsom jag, som i alla stycken fogar mig efter alla och icke söker min egen nytta, utan de mångas, för att de skola bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 1, 'Varen I mina efterföljare, såsom jag är Kristi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 2, 'Jag prisar eder för det att I i alla stycken haven mig i minne och hållen fast vid mina lärdomar, såsom de äro eder givna av mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 3, 'Men jag vill att I skolen inse detta, att Kristus är envar mans huvud, och att mannen är kvinnans huvud, och att Gud är Kristi huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 4, 'Var och en man som har sitt huvud betäckt, när han beder eller profeterar, han vanärar sitt huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 5, 'Men var kvinna som beder eller profeterar med ohöljt huvud, hon vanärar sitt huvud, ty det är då alldeles som om hon hade sitt hår avrakat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 6, 'Om en kvinna icke vill hölja sig, så kan hon lika väl låta skära av sitt hår; men eftersom det är en skam för en kvinna att låta skära av sitt hår eller att låta raka av det, så må hon hölja sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 7, 'En man är icke pliktig att hölja sitt huvud, eftersom han är Guds avbild och återspeglar hans härlighet, då kvinnan däremot återspeglar mannens härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 8, 'Ty mannen är icke av kvinnan, utan kvinnan av mannen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 9, 'Icke heller skapades mannen för kvinnans skull, utan kvinnan för mannens skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 10, 'Därför bör kvinnan på sitt huvud hava en »makt», för änglarnas skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 11, 'Dock är det i Herren så, att varken kvinnan är till utan mannen, eller mannen utan kvinnan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 12, 'Ty såsom kvinnan är av mannen, så är ock mannen genom kvinnan; men alltsammans är av Gud. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 13, 'Dömen själva: höves det en kvinnan att ohöljd bedja till Gud?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 14, 'Lär icke själva naturen eder att det länder en man till vanheder, om han har långt hår,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 15, 'men att det länder en kvinna till ära, om hon har långt hår? Håret är ju henne givet såsom slöja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 16, 'Om nu likväl någon vill vara genstridig, så mån han veta att vi för vår del icke hava en sådan sedvänja, ej heller andra Guds församlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 17, 'Detta bjuder jag eder nu. Men vad jag icke kan prisa är att I kommen tillsammans, icke till förbättring, utan till försämring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 18, 'Ty först och främst hör jag sägas att vid edra församlingsmöten söndringar yppa sig bland eder. Och till en del tror jag att så är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 19, 'Ty partier måste ju finnas bland eder, för att det skall bliva uppenbart vilka bland eder som hålla provet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 20, 'När I alltså kommen tillsammans med varandra, kan ingen Herrens måltid hållas;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 21, 'ty vid måltiden tager var och en i förväg själv den mat han har medfört, och så får den ene hungra, medan den andre får för mycket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 22, 'Haven I då icke edra hem, där I kunnen äta ock dricka? Eller är det så, att I förakten Guds församling och viljen komma dem att blygas, som intet hava? Vad skall jag då säga till eder? Skall jag prisa eder? Nej, i detta stycke prisar jag eder icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 23, 'Ty jag har från Herren undfått detta, som jag ock har meddelat eder: I den natt då Herren Jesus blev förrådd tog han ett bröd');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 24, 'och tackade Gud och bröt det och sade: »Detta är min lekamen, som varder utgiven för eder. Gören detta till min åminnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 25, 'Sammalunda tog han ock kalken, efter måltiden, och sade: »Denna kalk är det nya förbundet, i mitt blod. Så ofta I dricken den, så gören detta till min åminnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 26, 'Ty så ofta I äten detta bröd och dricken kalken, förkunnen I Herrens död, till dess att han kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 27, 'Den som nu på ett ovärdigt sätt äter detta bröd eller dricker Herrens kalk, han försyndar sig på Herrens lekamen och blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 28, 'Pröve då människan sig själv, och äte så av brödet och dricke av kalken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 29, 'Ty den som äter och dricker, utan att göra åtskillnad mellan Herrens lekamen och annan spis, han äter och dricker en dom över sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 30, 'Därför finnas ock bland eder många som äro svaga och sjuka, och ganska många äro avsomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 31, 'Om vi ginge till doms med oss själva, så bleve vi icke dömda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 32, 'Men då vi nu bliva dömda, så är detta en Herrens tuktan, som drabbar oss, för att vi icke skola bliva fördömda tillika med världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 33, 'Alltså, mina bröder, när I kommen tillsammans för att hålla måltid, så vänten på varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 34, 'Om någon är hungrig, då må han äta hemma, så att eder sammankomst icke bliver eder till en dom. Om det övriga skall jag förordna, när jag kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 1, 'Vad nu angår dem som hava andliga gåvor, så vill jag säga eder, mina bröder, huru med dem förhåller sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 2, 'I veten att I, medan I voren hedningar, läten eder blindvis föras bort till de stumma avgudarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 3, 'Därför vill jag nu förklara för eder, att likasom ingen som talar i Guds Ande säger: »Förbannad vare Jesus», så kan ej heller någon säga: »Jesus är Herre» annat än i den helige Ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 4, 'Nådegåvorna äro mångahanda, men Anden är en och densamme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 5, 'Tjänsterna äro mångahanda, men Herren är en och densamme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 6, 'Kraftverkningarna äro mångahanda, men Gud är en och densamme, han som verkar allt i alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 7, 'Men de gåvor i vilka Anden uppenbarar sig givas åt var och en så, att de kunna bliva till nytta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 8, 'Så gives genom Anden åt den ene att tala visdomens ord, åt en annan att efter samme Ande tala kunskapens ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 9, 'åt en annan gives tro i samme Ande, åt en annan givas helbrägdagörelsens gåvor i samme ene Ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 10, 'åt en annan gives gåvan att utföra kraftgärningar, åt en annan att profetera, åt en annan att skilja mellan andar, åt en annan att tala tungomål på olika sätt, åt en annan att uttyda, när någon talar tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 11, 'Men allt detta verkar densamme ene Anden, i det han, alltefter sin vilja, tilldelar åt var och en någon särskild gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 12, 'Ty likasom kroppen är en och likväl har många lemmar, och likasom kroppens alla lemmar, fastän de äro många, likväl utgöra en enda kropp, likaså är det med Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 13, 'Ty i en och samme Ande äro vi alla döpta till att utgöra en och samma kropp, vare sig vi äro judar eller greker, vare sig vi äro trälar eller fria; och alla hava vi fått en och samme Ande utgjuten över oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 14, 'Kroppen utgöres ju icke heller av en enda lem, utan av många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 15, 'Om foten ville säga: »Jag är icke hand, därför hör jag icke till kroppen», så skulle den icke dess mindre höra till kroppen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 16, 'Och om örat ville säga: »Jag är icke öga, därför hör jag icke till kroppen», så skulle det icke dess mindre höra till kroppen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 17, 'Om hela kroppen vore öga, var funnes då hörseln? Och om den hel och hållen vore öra, var funnes då lukten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 18, 'Men nu har Gud insatt lemmarna i kroppen, var och en av dem på det sätt som han har velat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 19, 'Om åter allasammans utgjorde en enda lem, var funnes då själva kroppen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 20, 'Men nu är det så, att lemmarna äro många, och att kroppen dock är en enda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 21, 'Ögat kan icke säga till handen: »Jag behöver dig icke», ej heller huvudet till fötterna: »Jag behöver eder icke.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 22, 'Nej, just de kroppens lemmar som tyckas vara svagast äro som mest nödvändiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 23, 'Och de delar av kroppen, som tyckas oss vara mindre hedersamma, dem bekläda vi med så mycket större heder; och dem som vi blygas för, dem skyla vi med så mycket större blygsamhet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 24, 'under det att de andra icke behöva något sådant. Men när Gud sammanfogade kroppen av olika delar och därvid lät den ringare delen få en så mycket större heder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 25, 'så skedde detta, för att söndring icke skulle uppstå i kroppen, utan alla lemmar endräktigt hava omsorg om varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 26, 'Om nu en lem lider, så lida alla de andra lemmarna med den; om åter en lem äras, så glädja sig alla de andra lemmarna med den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 27, 'Men nu ären I Kristi kropp och hans lemmar, var och en i sin mån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 28, 'Och Gud har i församlingen satt först och främst några till apostlar, för det andra några till profeter, för det tredje några till lärare, vidare några till att utföra kraftgärningar, ytterligare några till att hava helbrägdagörelsens gåvor, eller till att taga sig an de hjälplösa, eller till att vara styresmän, eller till att på olika sätt tala tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 29, 'Icke äro väl alla apostlar? Icke äro väl alla profeter? Icke äro väl alla lärare? Icke utföra väl alla kraftgärningar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 30, 'Icke hava väl alla helbrägdagörelsens gåvor? Icke tala väl alla tungomål? Icke kunna väl alla uttyda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 31, 'Men varen ivriga att undfå de nådegåvor som äro de största. Och nu vill jag ytterligare visa eder en väg, en övermåttan härlig väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 1, 'Om jag talade både människors och änglars tungomål, men icke hade kärlek, så vore jag allenast en ljudande malm eller en klingande cymbal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 2, 'Och om jag hade profetians gåva och visste alla hemligheter och ägde all kunskap, och om jag hade all tro, så att jag kunde förflytta berg, men icke hade kärlek, så vore jag intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 3, 'Och om jag gåve bort allt vad jag ägde till bröd åt de fattiga, ja, om jag offrade min kropp till att brännas upp, men icke hade kärlek, så vore detta mig till intet gagn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 4, 'Kärleken är tålig och mild. Kärleken avundas icke, kärleken förhäver sig icke, den uppblåses icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 5, 'Den skickar sig icke ohöviskt, den söker icke sitt, den förtörnas icke, den hyser icke agg för en oförrätts skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 6, 'Den gläder sig icke över orättfärdigheten, men har sin glädje i sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 7, 'Den fördrager allting, den tror allting, den hoppas allting, den uthärdar allting.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 8, 'Kärleken förgår aldrig. Men profetians gåva, den skall försvinna, och tungomålstalandet, det skall taga slut, och kunskapen, den skall försvinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 9, 'Ty vår kunskap är ett styckverk, och vårt profeterande är ett styckverk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 10, 'men när det kommer, som är fullkomligt, då skall det försvinna, som är ett styckverk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 11, 'När jag var barn, talade jag såsom ett barn, mitt sinne var såsom ett barns, jag hade barnsliga tankar; men sedan jag blev man, har jag lagt bort vad barnsligt var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 12, 'Nu se vi ju på ett dunkelt sätt, såsom i en spegel, men då skola vi se ansikte mot ansikte. Nu är min kunskap ett styckverk, men då skall jag känna till fullo, såsom jag själv har blivit till fullo känd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 13, 'Så bliva de då beståndande, tron, hoppet, kärleken, dessa tre; men störst bland dem är kärleken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 1, 'Faren efter kärleken, men varen ock ivriga att undfå de andliga gåvorna, framför allt profetians gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 2, 'Ty den som talar tungomål, han talar icke för människor, utan för Gud; ingen förstår honom ju, han talar i andehänryckning hemlighetsfulla ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 3, 'Men den som profeterar, han talar för människor, dem till uppbyggelse och förmaning och tröst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 4, 'Den som talar tungomål uppbygger allenast sig själv, men den som profeterar, han uppbygger en hel församling.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 5, 'Jag skulle väl vilja att I alla taladen tungomål, men ännu hellre ville jag att I profeteraden. Den som profeterar är förmer än den som talar tungomål, om nämligen den senare icke därjämte uttyder sitt tal, så att församlingen får någon uppbyggelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 6, 'Ja, mina bröder, om jag komme till eder och talade tungomål, vad gagn gjorde jag eder därmed, såframt jag icke därjämte genom mitt tal meddelade eder antingen någon uppenbarelse eller någon kunskap eller någon profetia eller någon undervisning?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 7, 'Gäller det icke jämväl om livlösa ting som giva ljud ifrån sig, det må nu vara en flöjt eller en harpa, att vad som spelas på dem icke kan uppfattas, om de icke giva ifrån sig toner som kunna skiljas från varandra?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 8, 'Likaså, om den signal som basunen giver är otydlig, vem gör sig då redo till strid?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 9, 'Detsamma gäller nu för eder; om I icke med edra tungor frambringen begripliga ord, huru skall man då kunna förstå vad I talen? Då bliver det ju ett tal i vädret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 10, 'Det finnes här i världen olika språk, vem vet huru många, och bland dem finnes intet vars ljud äro utan mening.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 11, 'Men om jag nu icke förstår språket, så bliver jag en främling för den som talar, och den som talar bliver en främling för mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 12, 'Detta gäller ock för eder; när I ären ivriga att undfå andliga gåvor, så må eder strävan efter att dessa hos eder skola överflöda hava församlingens uppbyggelse till mål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 13, 'Därför må den som talar tungomål bedja om att han ock må kunna uttyda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 14, 'Ty om jag talar tungomål, när jag beder, så beder visserligen min ande, men mitt förstånd kommer ingen frukt åstad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 15, 'Vad följer då härav? Jo, jag skall väl bedja med anden, men jag skall ock bedja med förståndet; jag skall väl lovsjunga med anden, men jag skall ock lovsjunga med förståndet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 16, 'Eljest, om du lovar Gud med anden, huru skola de som sitta på de olärdas plats då kunna säga sitt »amen» till din tacksägelse? De förstå ju icke vad du säger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 17, 'Om än din tacksägelse är god, så bliva de andra dock icke uppbyggda därav. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 18, 'Gud vare tack, jag talar tungomål mer än I alla;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 19, 'och dock vill jag hellre i församlingen tala fem ord med mitt förstånd, till undervisning jämväl för andra, än tio tusen ord i tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 20, 'Mina bröder, varen icke barn till förståndet; nej varen barn i ondskan, men varen fullmogna till förståndet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 21, 'Det är skrivet i lagen: »Genom människor med främmande tungomål och genom främlingars läppar skall jag tala till detta folk, men icke ens så skola de höra på mig, säger Herren.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 22, 'Alltså äro »tungomålen» ett tecken, ej för dem som tro, utan för dem som icke tro; profetian däremot är ett tecken, ej för dem som icke tro, utan för dem som tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 23, 'Om nu hela församlingen komme tillhopa till gemensamt möte, och alla där talade tungomål, och så några som vore olärda komme ditin, eller några som icke trodde, skulle då icke dessa säga att I voren ifrån edra sinnen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 24, 'Om åter alla profeterade, och så någon som icke trodde, eller som vore olärd komme ditin, då skulle denne känna sig avslöjad av alla och av alla utrannsakad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 25, 'Vad som vore fördolt i hans hjärta bleve då uppenbart, och så skulle han falla ned på sitt ansikte och tillbedja Gud och betyga att »Gud verkligen är i eder».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 26, 'Vad följer då härav, mina bröder? Jo, när I kommen tillsammans, så har var och en något särskilt att meddela: den ene har en psalm, den andre något till undervisning, en annan åter någon uppenbarelse, en talar tungomål, en annan uttyder; allt detta må nu ske så, att det länder till uppbyggelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 27, 'Vill man tala tungomål, så må för var gång två eller högst tre få tala, och av dessa en i sänder, och en må uttyda det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 28, 'Är ingen uttydare tillstädes, så må de tiga i församlingen och tala allenast för sig själva och för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 29, 'Av dem som vilja profetera må två eller tre få tala, och de andra må döma om det som talas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 30, 'Men om någon annan som sitter där får en uppenbarelse, då må den förste tiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 31, 'Ty I kunnen alla få profetera, den ene efter den andre, så att alla bliva undervisade och alla förmanade;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 32, 'och profeters andar äro profeterna underdåniga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 33, 'Gud är ju icke oordningens Gud, utan fridens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 34, 'Såsom kvinnorna tiga i alla andra de heligas församlingar, så må de ock tiga i edra församlingar. Det är dem icke tillstatt att tala, utan de böra underordna sig, såsom lagen bjuder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 35, 'Vilja de hava upplysning om något, så må de hemma fråga sina män; ty det är en skam för en kvinna att tala i församlingen. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 36, 'Eller är det från eder som Guds ord har utgått? Eller har det kommit allenast till eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 37, 'Om någon menar sig vara en profet eller en man med andegåva, så må han ock inse att vad jag skriver till eder är Herrens bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 38, 'Men vill någon icke inse detta, så vare det hans egen sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 39, 'Alltså, mina bröder, varen ivriga att undfå profetians gåva och förmenen ej heller någon att tala tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 40, 'Men låten allt tillgå på höviskt sätt och med ordning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 1, 'Mina bröder, jag vill påminna eder om det evangelium som jag förkunnade för eder, som I jämväl togen emot, och som I ännu stån kvar i,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 2, 'genom vilket I ock bliven frälsta; jag vill påminna eder om huru jag förkunnade det för eder, såframt I eljest hållen fast därvid -- om nu icke så är att I förgäves haven kommit till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 3, 'Jag meddelade eder ju såsom ett huvudstycke vad jag själv hade undfått: att Kristus dog för våra synder, enligt skrifterna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 4, 'och att han blev begraven, och att han har uppstått på tredje dagen, enligt skrifterna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 5, 'och att han visade sig för Cefas och sedan för de tolv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 6, 'Därefter visade han sig för mer än fem hundra bröder på en gång, av vilka de flesta ännu leva kvar, medan några äro avsomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 7, 'Därefter visade han sig för Jakob och sedan för alla apostlarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 8, 'Allra sist visade han sig också för mig, som är att likna vid ett ofullgånget foster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 9, 'Ty jag är den ringaste bland apostlarna, ja, icke ens värdig att kallas apostel, jag som har förföljt Guds församling.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 10, 'Men genom Guds nåd är jag vad jag är, och hans nåd mot mig har icke varit fåfäng, utan jag har arbetat mer än de alla -- dock icke jag, utan Guds nåd, som har varit med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 11, 'Det må nu vara jag eller de andra, så är det på det sättet vi predika, och på det sättet I haven kommit till tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 12, 'Om det nu predikas om Kristus att han har uppstått från de döda, huru kunna då somliga bland eder säga att det icke finnes någon uppståndelse från de döda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 13, 'Om det åter icke finnes någon uppståndelse från de döda, då har icke heller Kristus uppstått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 14, 'Men om Kristus icke har uppstått, då är ju vår predikan fåfäng, då är ock eder tro fåfäng;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 15, 'då befinnas vi ock vara falska Guds vittnen, eftersom vi hava vittnat mot Gud att han har uppväckt Kristus, som han icke har uppväckt, om det är sant att döda icke uppstå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 16, 'Ja, om döda icke uppstå, så har ej heller Kristus uppstått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 17, 'Men om Kristus icke har uppstått, så är eder tro förgäves; I ären då ännu kvar i edra synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 18, 'Då hava ju ock de gått förlorade, som hava avsomnat i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 19, 'Om vi i detta livet hava i Kristus haft vårt hopp, och därav intet bliver, då äro vi de mest ömkansvärda av alla människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 20, 'Men nu har Kristus uppstått från de döda, såsom förstlingen av de avsomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 21, 'Ty eftersom döden kom genom en människa, så kom ock genom en människa de dödas uppståndelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 22, 'Och såsom i Adam alla dö, så skola ock i Kristus alla göras levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 23, 'Men var och en i sin ordning: Kristus såsom förstlingen, därnäst, vid Kristi tillkommelse, de som höra honom till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 24, 'Därefter kommer änden, då när han överlämnar riket åt Gud och Fadern, sedan han från andevärldens alla furstar och alla väldigheter och makter har tagit all deras makt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 25, 'Ty han måste regera »till dess han har lagt alla sina fiender under sina fötter».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 26, 'Sist bland hans fiender bliver ock döden berövad all sin makt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 27, 'ty »allt har han lagt under hans fötter». Men när det heter att »allt är honom underlagt», då är uppenbarligen den undantagen, som har lagt allt under honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 28, 'Och sedan allt har blivit Sonen underlagt, då skall ock Sonen själv giva sig under den som har lagt allt under honom. Och så skall Gud bliva allt i alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 29, 'Vad kunna annars de som låta döpa sig för de dödas skull vinna därmed? Om så är att döda alls icke uppstå, varför låter man då döpa sig för deras skull?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 30, 'Och varför undsätta vi oss själva var stund för faror?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 31, 'Ty -- så sant jag i Kristus Jesus, vår Herre, kan berömma mig av eder, mina bröder -- jag lider döden dag efter dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 32, 'Om jag hade tänkt såsom människor pläga tänka, när jag i Efesus kämpade mot vilddjuren, vad gagnade mig då det jag gjorde? Om döda icke uppstå -- »låtom oss då äta och dricka, ty i morgon måste vi dö».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 33, 'Faren icke vilse: »För goda seder dåligt sällskap är fördärv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 34, 'Vaknen upp till rätt nykterhet, och synden icke. Somliga finnas ju, som leva i okunnighet om Gud; eder till blygd säger jag detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 35, 'Nu torde någon fråga: »På vad sätt uppstå då de döda, och med hurudan kropp skola de träda fram?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 36, 'Du oförståndige! Det frö du sår, det får ju icke liv, om det icke först har dött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 37, 'Och när du sår, då är det du sår icke den växt som en gång skall komma upp, utan ett naket korn, kanhända ett vetekorn, kanhända något annat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 38, 'Men Gud giver det en kropp, en sådan som han vill, och åt vart frö dess särskilda kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 39, 'Icke allt kött är av samma slag, utan människors har sin art, boskapsdjurs kött en annan art, fåglars kött åter en annan, fiskars återigen en annan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 40, 'Så finnas ock både himmelska kroppar och jordiska kroppar, men de himmelska kropparnas härlighet är av ett slag, de jordiska kropparnas av ett annat slag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 41, 'En härlighet har solen, en annan härlighet har månen, åter en annan härlighet hava stjärnorna; ja, den ena stjärnan är icke lik den andra i härlighet. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 42, 'Så är det ock med de dödas uppståndelse: vad som bliver sått förgängligt, det uppstår oförgängligt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 43, 'vad som bliver sått i ringhet, det uppstår i härlighet; vad som bliver sått i svaghet, det uppstår i kraft;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 44, 'här sås en »själisk»[1] kropp, där uppstår en andlig kropp. Så visst som det finnes en »själisk» kropp, så visst finnes det ock en andlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 45, 'Så är ock skrivet: »Den första människan, Adam, blev en levande varelse med själ.» Den siste Adam åter blev en levandegörande ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 46, 'Men icke det andliga är det första, utan det »själiska»; sedan kommer det andliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 47, 'Den första människan var av jorden och jordisk, den andra människan är av himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 48, 'Sådan som den jordiska var, sådana äro ock de jordiska; och sådan som den himmelska är, sådana äro ock de himmelska.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 49, 'Och såsom vi hava burit den jordiskas gestalt, så skola vi ock bära den himmelskas gestalt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 50, 'Mina bröder, vad jag nu vill säga är detta, att kött och blod icke kunna få Guds rike till arvedel; ej heller får förgängligheten oförgängligheten till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 51, 'Se, jag säger eder en hemlighet: Vi skola icke alla avsomna, men alla skola vi bliva förvandlade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 52, 'och det i ett nu, i ett ögonblick, vid den sista basunens ljud. Ty basunen skall ljuda, och de döda skola uppstå till oförgänglighet, och då skola vi bliva förvandlade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 53, 'Ty detta förgängliga måste ikläda sig oförgänglighet, och detta dödliga ikläda sig odödlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 54, 'Men när detta förgängliga har iklätt sig oförgänglighet, och detta dödliga har iklätt sig odödlighet, då skall det ord fullbordas, som står skrivet: »Döden är uppslukad och seger vunnen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 55, 'Du död, var är din seger? Du död, var är din udd?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 56, 'Dödens udd är synden, och syndens makt kommer av lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 57, 'Men Gud vare tack, som giver oss segern genom vår Herre Jesus Kristus!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 58, 'Alltså, mina älskade bröder, varen fasta, orubbliga, alltid överflödande i Herrens verk, eftersom I veten att edert arbete icke är fåfängt i Herren. [1] Se Själisk i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 1, 'Vad nu angår insamlingen till de heliga, så mån I förfara på samma sätt som jag har förordnat för församlingarna i Galatien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 2, 'Var och en av eder må spara ihop vad han får tillfälle till, och på första dagen i var vecka må han lägga av detta hemma hos sig, så att insamlingen icke göres först vid min ankomst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 3, 'Men när jag kommer, skall jag sända åstad de män som I själva pröven vara lämpliga, med brev till Jerusalem, för att där frambära eder kärleksgåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 4, 'Och om saken befinnes vara värd att också jag reser, så skola de få åtfölja mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 5, 'Jag tänker nämligen komma till eder, sedan jag har farit genom Macedonien. Ty Macedonien vill jag allenast fara igenom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 6, 'men hos eder skall jag kanhända stanna något, möjligen vintern över, för att I därefter mån hjälpa mig till vägs, dit jag kan vilja begiva mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 7, 'Jag vill icke besöka eder nu strax, på genomresa, ty jag hoppas att någon tid få stanna hos eder, om Herren så tillstädjer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 8, 'Men i Efesus vill jag stanna ända till pingst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 9, 'Ty en dörr till stor och fruktbärande verksamhet har öppnats för mig; jag har ock många motståndare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 10, 'Men när Timoteus kommer, så sen till, att han utan fruktan må kunna vistas hos eder. Han utför ju Herrens verk, han såväl som jag;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 11, 'må därför ingen förakta honom. Hjälpen honom sedan till vägs i frid, så att han kommer åter till mig; ty jag väntar honom med bröderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 12, 'Vad angår brodern Apollos, så har jag ivrigt uppmanat honom att med de andra bröderna begiva sig till eder. Han var dock alls icke hågad att komma just nu; men när det bliver honom lägligt, skall han komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 13, 'Vaken, stån fasta i tron, skicken eder såsom män, varen starka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 14, 'Låten allt hos eder ske i kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 15, 'Mina bröder, jag vill giva eder en förmaning: I kännen ju Stefanas\' husfolk och veten att de äro förstlingen i Akaja, och att de hava ägnat sig åt de heligas tjänst;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 16, 'därför mån I å eder sida underordna eder under dessa män och under envar som bistår dem i deras arbete och själv gör sig möda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 17, 'Jag gläder mig över att Stefanas och Fortunatus och Akaikus hava kommit hit, ty dessa hava givit mig ersättning för vad jag har måst sakna genom att vara skild från eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 18, 'de hava vederkvickt min ande såväl som eder ande. Så lären eder nu att rätt uppskatta sådana män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 19, 'Församlingarna i provinsen Asien hälsar eder. Akvila och Priska, tillika med den församling som kommer tillhopa i deras hus, hälsa eder mycket i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 20, 'Ja, alla bröderna hälsa eder. Hälsen varandra med en helig kyss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 21, 'Här skriver jag, Paulus, min hälsning med egen hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 22, 'Om någon icke har Herren kär, så vare han förbannad. Marana, ta![1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 23, 'Herren Jesu nåd vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 24, 'Min kärlek är med eder alla, i Kristus Jesus. [1] Arameiska ord, som betyda: »Du vår Herre, kom!» -- Jämför Upp 22,20.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Paulus, genom Guds vilja Kristi Jesu apostel, så ock brodern Timoteus, hälsar den Guds församling som finnes i Korint, och tillika alla de heliga som finnas i hela Akaja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Lovad vare vår Herres, Jesu Kristi, Gud och Fader, barmhärtighetens Fader och all trösts Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'han som tröstar oss i all vår nöd, så att vi genom den tröst vi själva undfå av Gud kunna trösta dem som äro stadda i allahanda nöd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Ty såsom Kristuslidanden till överflöd komma över oss, så kommer ock genom Kristus tröst till oss i överflödande mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Men drabbas vi av nöd, så sker detta till tröst och frälsning för eder. Undfå vi däremot tröst, så sker ock detta till tröst för eder, en tröst som skall visa sin kraft däri, att I ståndaktigt uthärden samma lidanden som vi utstå. Och det hopp vi hysa i fråga om eder är fast,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'ty vi veta att såsom I delen våra lidanden, så delen I ock den tröst vi undfå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Vi vilja nämligen icke lämna eder, käre bröder, i okunnighet om vilken nöd vi fingo utstå i provinsen Asien, och huru övermåttan svårt det blev oss, utöver vår förmåga, så att vi till och med misströstade om livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ja, vi hade redan i vårt inre likasom fått vår dödsdom, för att vi icke skulle förtrösta på oss själva, utan på Gud, som uppväcker de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Och ur en sådan dödsnöd frälste han oss, och han skall än vidare frälsa oss; ja, till honom hava vi satt vårt hopp att han allt framgent skall frälsa oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Också I stån oss ju bi med eder förbön. Och så skola många hembära tacksägelse för oss, för den nåd som genom mångas böner har kommit oss till del.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Ty vad vi kunna berömma oss av, och vad vårt samvete bär oss vittnesbörd om, det är att vi i denna världen hava vandrat i Guds helighet och renhet, icke ledda av köttslig vishet, utan av Guds nåd; så framför allt i vårt förhållande till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Ty i vad vi skriva till eder ligger icke något annat än just vad I läsen och väl kunnen förstå. Och jag hoppas att I skolen komma att till fullo förstå');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'vad I redan nu delvis förstån om oss: att vi äro eder berömmelse, likasom I ären vår berömmelse, på vår Herre Jesu dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Och i denna tillförsikt tänkte jag komma först till eder, för att I skullen få ännu ett kärleksbevis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'Genom eder stad ville jag alltså taga vägen till Macedonien, och jag skulle sedan från Macedonien återigen komma till eder, för att då av eder utrustas för resan till Judeen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Så tänkte jag; och icke har jag väl därför nu handlat i vankelmod? Eller plägar jag kanhända fatta mina beslut efter köttet, så att vad jag säger är på samma gång »ja, ja» och »nej, nej»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Ingalunda; så sant Gud är trofast, vad vi tala till eder är icke »ja och nej».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Guds Son, Jesus Kristus, han som bland eder har blivit predikad genom oss -- genom mig och Silvanus och Timoteus -- han kom ju icke såsom »ja och nej», utan »ja» har kommit i och genom honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'Ty Guds löften, så många de äro, hava i honom fått sitt »ja»; därför få de ock genom honom sitt »amen», på det att Gud må bliva ärad genom oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Men den som befäster oss såväl som eder i Kristus, och den som har smort oss, det är Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'han som har låtit oss undfå sitt insegel och givit oss Anden till en underpant i våra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Jag kallar Gud till vittne över min själ, att det är av skonsamhet mot eder som jag ännu icke har kommit till Korint.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, '(Detta säger jag icke, som om vi vore herrar över eder tro; fastmer äro vi edra medarbetare till att bereda eder glädje, ty i tron stån I fasta.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, 'Jag satte mig nämligen i sinnet att jag icke åter skulle komma till eder med bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'Ty om jag bedrövade eder, vem skulle då bereda mig glädje? Månne någon annan än den som genom mig hade blivit bedrövad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'Och vad jag skrev, det skrev jag, för att jag icke vid min ankomst skulle få bedrövelse från dem som jag borde få glädje av. Ty jag har den tillförsikten till eder alla, att min glädje är allas eder glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'Och det var i stor nöd och hjärteångest, under många tårar, som jag skrev till eder, icke för att I skullen bliva bedrövade, utan för att I skullen förstå den synnerliga kärlek som jag har till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'Men om en viss man har vållat bedrövelse, så är det icke särskilt mig han har bedrövat, utan eder alla, i någon mån -- för att jag nu icke skall tala för strängt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, 'Nu är det likväl nog med den näpst som han har fått mottaga från de flesta bland eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'I mån alltså nu tvärtom snarare förlåta och trösta honom, så att han icke till äventyrs går under genom sin alltför stora bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'Därför uppmanar jag eder att fatta gemensamt beslut om att bemöta honom med kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'Ty när jag skrev, var det just för att få veta huru I skullen hålla provet, huruvida I voren lydiga i allting.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'Den som I förlåten något, honom förlåter ock jag, likasom jag också förut, om jag har haft något att förlåta, har inför Kristi ansikte förlåtit det för eder skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'Jag vill nämligen icke att vi skola lida förfång av Satan; ty vad han har i sinnet, därom äro vi icke i okunnighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'Jag kom till Troas för att förkunna evangelium om Kristus, och en dörr till verksamhet i Herren öppnades för mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'men jag fick ingen ro i min ande, ty jag fann icke där min broder Titus. Jag tog då avsked av dem som voro där och begav mig till Macedonien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, 'Men Gud vare tack, som i Kristus alltid för oss fram i segertåg och genom oss allestädes utbreder hans kunskaps vällukt!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'Ty vi äro en Kristi välluktande rökelse inför Gud, både ibland dem som bliva frälsta och ibland dem som gå förlorade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 16, 'För dessa senare äro vi en lukt från död till död; för de förra äro vi en lukt från liv till liv. Vem är nu skicklig härtill?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 17, 'Jo, vi förfalska ju icke av vinningslystnad Guds ord, såsom så många andra göra; utan av rent sinne, drivna av Gud, förkunna vi ordet i Kristus, inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, 'Begynna vi nu åter att anbefalla oss själva? Eller behöva vi kanhända, såsom somliga, ett anbefallningsbrev till eder? Eller kanhända ifrån eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'Nej, I ären själva vårt brev, ett brev som är inskrivet i våra hjärtan, känt och läst av alla människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'Ty det är uppenbart att I ären ett Kristus-brev, avfattat genom oss, skrivet icke med bläck, utan med den levande Gudens Ande, icke på tavlor av sten, utan på tavlor av kött, på människohjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'En sådan tillförsikt hava vi genom Kristus till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, 'Icke som om vi av oss själva vore skickliga att tänka ut något, såsom komme det från oss själva, utan den skicklighet vi hava kommer från Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'som också har gjort oss skickliga till att vara tjänare åt ett nytt förbund, ett som icke är bokstav, utan är ande; ty bokstaven dödar, men Anden gör levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Om nu redan dödens ämbete, som var med bokstäver inristat på stenar, framträdde i härlighet, så att Israels barn icke kunde se på Moses\' ansikte för hans ansiktes härlighets skull, vilken dock var försvinnande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'huru mycket större härlighet skall då icke Andens ämbete hava!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, 'Ty om redan fördömelsens ämbete var härligt, så måste rättfärdighetens ämbete ännu mycket mer överflöda av härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, 'Ja, en så översvinnlig härlighet har detta ämbete, att vad som förr hade härlighet här visar sig vara utan all härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'Ty om redan det som var försvinnande framträdde i härlighet, så måste det som bliver beståndande hava en ännu mycket större härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Då vi nu hava ett sådant hopp, gå vi helt öppet till väga');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'och göra icke såsom Moses, vilken hängde ett täckelse för sitt ansikte, så att Israels barn icke kunde se huru det som var försvinnande tog en ände.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'Men deras sinnen blevo förstockade. När det gamla förbundets skrifter föreläsas, hänger ju ännu i denna dag samma täckelse oborttaget kvar; ty först i Kristus försvinner det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'Ja, ännu i dag hänger ett täckelse över deras hjärtan, då Moses föreläses.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, 'Men när de en gång omvända sig till Herren, tages täckelset bort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 17, 'Och Herren är Anden, och där Herrens Ande är, där är frihet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 18, 'Men vi alla som med avhöljt ansikte återspegla Herrens härlighet, vi förvandlas till hans avbilder, i det vi stiga från den ena härligheten till den andra, såsom när den Herre verkar, som själv är ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, 'Därför, då vi nu, genom den barmhärtighet som har vederfarits oss, hava detta ämbete, så fälla vi icke modet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'Nej, vi hava frånsagt oss allt skamligt hemlighetsväsen och gå icke illfundigt till väga, ej heller förfalska vi Guds ord, utan framlägga öppet sanningen och anbefalla oss så, inför Gud, hos var människas samvete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Och om vårt evangelium nu verkligen är bortskymt av ett täckelse, så finnes det täckelset hos dem som gå förlorade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'Ty de otrognas sinnen har denna tidsålders gud så förblindat, att de icke se det sken som utgår från evangelium om Kristi, Guds egen avbilds, härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'Vi predika ju icke oss själva, utan Kristus Jesus såsom Herre, och oss såsom tjänare åt eder, för Jesu skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, 'Ty den Gud som sade: »Ljus skall lysa fram ur mörkret», han är den som har låtit ljus gå upp i våra hjärtan, för att kunskapen om Guds härlighet, som strålar fram i Kristi ansikte, skall kunna sprida sitt sken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'Men denna skatt hava vi i lerkärl, för att den översvinnliga kraften skall befinnas vara Guds och icke något som kommer från oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, 'Vi äro på allt sätt i trångmål, dock icke utan utväg; vi äro rådvilla, dock icke rådlösa;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'vi äro förföljda, dock icke givna till spillo; vi äro slagna till marken, dock icke förlorade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'Alltid bära vi Jesu dödsmärken på vår kropp, för att också Jesu liv skall bliva uppenbarat i vår kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Ja, ännu medan vi leva, överlämnas vi för Jesu skull beständigt åt döden, på det att ock Jesu liv må bliva uppenbarat i vårt dödliga kött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'Så utför nu döden sitt verk i oss, men i eder verkar livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'Men såsom det är skrivet: »Jag tror, därför talar jag ock», så tro också vi, eftersom vi hava samma trons Ande; därför tala vi ock,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, 'ty vi veta att han som uppväckte Herren Jesus, han skall ock uppväcka oss med Jesus och ställa oss inför sig tillsammans med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'Allt sker nämligen för eder skull, på det att nåden, genom att komma allt flera till del, må bliva så mycket större och verka en allt mer överflödande tacksägelse, Gud till ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'Därför fälla vi icke modet; om ock vår utvärtes människa förgås, så förnyas likväl vår invärtes människa dag efter dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 17, 'Ty vår bedrövelse, som varar ett ögonblick och väger föga, bereder åt oss, i översvinnligen rikt mått, en härlighet som väger översvinnligen tungt och varar i evighet --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 18, 'åt oss som icke hava till ögonmärke de ting som synas, utan dem som icke synas; ty de ting som synas, de vara allenast en tid, med de som icke synas, de vara i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 1, 'Ty vi veta, att om vår kroppshydda, vår jordiska boning, nedbrytes, så hava vi en byggnad som kommer från Gud, en boning som icke är gjord med händer, en evig boning i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 2, 'Därför sucka vi ju ock av längtan att få överkläda oss med vår himmelska hydda;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 3, 'ty hava vi en gång iklätt oss denna, skola vi sedan icke komma att befinnas nakna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 4, 'Ja, vi som ännu leva här i kroppshyddan, vi sucka och äro betungade, eftersom vi skulle vilja undgå att avkläda oss och i stället få överkläda oss, så att det som är dödligt bleve uppslukat av livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 5, 'Och den som har berett oss till just detta, det är Gud, som till en underpant har givit oss Anden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 6, 'Så äro vi då alltid vid gott mod. Vi veta väl att vi äro borta ifrån Herren, så länge vi äro hemma i kroppen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 7, 'ty vi vandra här i tro och icke i åskådning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 8, 'Men vi äro vid gott mod och skulle helst vilja flytta bort ifrån kroppen och komma hem till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 9, 'Därför söka vi ock vår ära i att vara honom till behag, vare sig vi äro hemma eller borta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 10, 'Ty vi måste alla, sådana vi äro, träda fram inför Kristi domstol, för att var och en skall få igen sitt jordelivs gärningar, alltefter som han har handlat, vare sig han har gjort gott eller ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 11, 'Då vi alltså veta vad det är att frukta Herren, söka vi att »vinna människor», men för Gud är det uppenbart hurudana vi äro; och jag hoppas att det också är uppenbart för edra samveten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 12, 'Vi vilja nu ingalunda åter anbefalla oss själva hos eder, men vi vilja giva eder en anledning att berömma eder i fråga om oss, så att I haven något att svara dem som berömma sig av utvärtes ting och icke av vad som är i hjärtat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 13, 'Ty om vi hava varit »från våra sinnen», så har det varit i Guds tjänst; om vi åter äro vid lugn besinning, så är det eder till godo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 14, 'Ty Kristi kärlek tvingar oss, eftersom vi tänka så: en har dött för alla, alltså hava de alla dött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 15, 'Och han har dött för alla, på det att de som leva icke mer må leva för sig själva, utan leva för honom som har dött och uppstått för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 16, 'Allt ifrån denna tid veta vi därför för vår del icke av någon efter köttet. Och om vi än efter köttet hade lärt känna Kristus, så känna vi honom nu icke mer på det sättet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 17, 'Alltså, om någon är i Kristus, så är han en ny skapelse. Det gamla är förgånget; se, något nytt har kommit!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 18, 'Men alltsammans kommer från Gud, som har försonat oss med sig själv genom Kristus och givit åt oss försoningens ämbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 19, 'Ty det var Gud som i Kristus försonade världen med sig själv; han tillräknar icke människorna deras synder, och han har betrott oss med försoningens ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 20, 'Å Kristi vägnar äro vi alltså sändebud; det är Gud som förmanar genom oss. Vi bedja å Kristi vägnar: Låten försona eder med Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 21, 'Den som icke visste av någon synd, honom har han för oss gjort till synd, på det att vi i honom må bliva rättfärdighet från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 1, 'Men såsom medarbetare förmana vi eder ock att icke så mottaga Guds nåd, att det bliver utan frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 2, 'Han säger ju: »Jag bönhör dig i behaglig tid, och jag hjälper dig på frälsningens dag.» Se, nu är den välbehagliga tiden; se, nu är frälsningens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 3, 'Härvid vilja vi icke i något stycke vara till någon anstöt, på det att vårt ämbete icke må bliva smädat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 4, 'Fastmer vilja vi i allting bevisa oss såsom Guds tjänare, i mycken ståndaktighet, under bedrövelse och nöd och ångest,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 5, 'under hugg och slag, under fångenskap och upprorslarm, under mödor, vakor och svält,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 6, 'i renhet, i kunskap, i tålamod och godhet, i helig ande, i oskrymtad kärlek,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 7, 'med sanning i vårt tal, med kraft från Gud, med rättfärdighetens vapen både i högra handen och i vänstra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 8, 'under ära och smälek, under ont rykte och gott rykte, såsom villolärare, då vi dock äro sannfärdiga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 9, 'såsom okända, fastän vi äro väl kända, såsom döende, men se, vi leva, såsom tuktade, men likväl icke till döds,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 10, 'såsom bedrövade, men dock alltid glada, såsom fattiga, medan vi dock göra många rika, såsom utblottade på allt, men likväl ägande allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 11, 'Vi hava nu upplåtit vår mun och talat öppet till eder, I korintier. Vårt hjärta har vidgat sig för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 12, 'Ja, det rum I haven i vårt inre är icke litet, men i edra hjärtan är allenast litet rum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 13, 'Given oss då lika för lika -- om jag nu får tala såsom till barn -- ja, vidgen också I edra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 14, 'Gån icke i ok tillsammans med dem som icke tro; det bleve omaka par. Vad har väl rättfärdighet att skaffa med orättfärdighet, eller vilken gemenskap har ljus med mörker?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 15, 'Huru förlika sig Kristus och Beliar, eller vad delaktighet har den som tror med den som icke tror?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 16, 'Eller huru låter ett Guds tempel förena sig med avgudar? Vi äro ju ett den levande Gudens tempel, ty Gud har sagt: »Jag skall bo i dem och vandra ibland dem; jag skall vara deras Gud, och de skola vara mitt folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 17, 'Alltså: »Gån ut ifrån dem och skiljen eder ifrån dem, säger Herren; kommen icke vid det orent är. Då skall jag taga emot eder');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 18, 'och vara en Fader för eder; och I skolen vara mina söner och döttrar, säger Herren, den Allsmäktige.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 1, 'Då vi nu hava dessa löften, mina älskade, så låtom oss rena oss från allt som befläckar vare sig kött eller ande, i det vi fullborda vår helgelse i Guds fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 2, 'Bereden oss ett rum i edra hjärtan; vi hava icke handlat orätt mot någon, icke varit någon till skada, icke gjort någon något förfång. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 3, 'Jag säger icke detta för att döma eder; jag har ju redan sagt att I haven ett rum i vårt hjärta, så att vi skola både dö och leva med varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 4, 'Stor är den tillit som jag har till eder, mycket berömmer jag mig av eder; jag har fått hugnad i fullt mått och glädje i rikt överflöd, mitt i allt vårt betryck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 5, 'Ty väl fingo vi till köttet ingen ro, icke ens sedan vi hade kommit till Macedonien, utan vi voro på allt sätt i trångmål, utifrån genom strider, inom oss genom farhågor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 6, 'men Gud, som tröstar dem som äro betryckta, han tröstade oss genom Titus\' ankomst,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 7, 'och icke allenast genom hans ankomst, utan ock därigenom att han hade fått så mycken hugnad av eder. Han omtalade nämligen för oss eder längtan, eder klagan, eder iver i fråga om mig; och så gladde jag mig ännu mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 8, 'Ty om jag ock bedrövade eder genom mitt brev, så ångrar jag nu icke detta. Nej, om jag förut ångrade det -- eftersom jag ser att det brevet har bedrövat eder, låt vara allenast för en liten tid --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 9, 'så gläder jag mig nu i stället, icke därför att I bleven bedrövade, utan därför att eder bedrövelse lände eder till bättring. Det var ju efter Guds sinne som I bleven bedrövade, och I haven alltså icke genom oss lidit någon skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 10, 'Ty den bedrövelse som är efter Guds sinne kommer åstad en bättring som leder till frälsning, och som man icke ångrar; men världens bedrövelse kommer åstad död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 11, 'Se, just detta, att I bleven bedrövade efter Guds sinne, huru mycket nit har det icke framkallat hos eder, ja, huru många ursäkter, huru stor förtrytelse, huru mycken fruktan, huru mycken längtan, huru mycken iver, huru många bestraffningar! På allt sätt haven I bevisat att I viljen vara rena i den sak det här gäller. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 12, 'Om jag skrev till eder, så skedde detta alltså icke för den mans skull, som hade gjort orätt, ej heller för den mans skull, som hade lidit orätt, utan på det att edert nit för oss skulle bliva uppenbart bland eder själva inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 13, 'Så hava vi nu fått hugnad. Och till den hugnad, som vi redan för egen del fingo, kom den ännu mer överflödande glädje som bereddes oss av den glädje Titus hade fått. Ty hans ande har fått vederkvickelse genom eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 14, 'Och om jag inför honom har berömt mig något i fråga om eder, så har jag icke kommit på skam därmed; utan likasom vi eljest i allting hava talat sanning inför eder, så har också det som vi inför Titus hava sagt till eder berömmelse visat sig vara sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 15, 'Och hans hjärta överflödar ännu mer av kärlek till eder, då han nu påminner sig allas eder lydnad, huru I villigt togen emot honom, med fruktan och bävan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 16, 'Jag gläder mig över att jag, i allt vad eder angår, kan vara vid gott mod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 1, 'Vi vilja meddela eder, käre bröder, huru Guds nåd har verkat i Macedoniens församlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 2, 'Fastän de hava varit prövade av svår nöd, har deras överflödande glädje, mitt under deras djupa fattigdom, så flödat över, att de av gott hjärta hava givit rikliga gåvor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 3, 'Ty de hava givit efter sin förmåga, ja, över sin förmåga, och det självmant; därom kan jag vittna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 4, 'Mycket enträget bådo de oss om den ynnesten att få vara med om understödet åt de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 5, 'Och de gåvo icke allenast vad vi hade hoppats, utan sig själva gåvo de, först och främst åt Herren, och så åt oss, genom Guds vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 6, 'Så kunde vi uppmana Titus att han skulle fortsätta såsom han hade begynt och föra jämväl detta kärleksverk bland eder till fullbordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 7, 'Ja, då I nu utmärken eder i alla stycken: i tro, i tal, i kunskap, i allsköns nit, i kärlek, den kärlek som av eder har blivit oss bevisad, så mån I se till, att I också utmärken eder i detta kärleksverk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 8, 'Detta säger jag dock icke såsom en befallning, utan därför att jag, genom att framhålla andras nit, vill pröva om också eder kärlek är äkta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 9, 'I kännen ju vår Herres, Jesu Kristi, nåd, huru han, som var rik, likväl blev fattig för eder skull, på det att I genom hans fattigdom skullen bliva rika.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 10, 'Det är allenast ett råd som jag härmed giver. Ty detta kan vara nyttigt för eder. I voren ju före de andra -- redan under förra året -- icke allenast när det gällde att sätta saken i verket, utan till och med när det gällde att besluta sig för den.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 11, 'Fullborden nu ock edert verk, så att I, som voren så villiga att besluta det, jämväl, i mån av edra tillgångar, fören det till fullbordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 12, 'Ty om den goda viljan är för handen, så bliver den välbehaglig med de tillgångar den har och bedömes ej efter vad den icke har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 13, 'Ty meningen är icke att andra skola hava lättnad och I själva lida nöd. Nej, en utjämning skall ske,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 14, 'så att edert överflöd denna gång kommer deras brist till hjälp, för att en annan gång deras överflöd skall komma eder brist till hjälp. Så skall en utjämning ske,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 15, 'efter skriftens ord: »Den som hade samlat mycket hade intet till överlopps, och den som hade samlat litet, honom fattades intet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 16, 'Gud vare tack, som också i Titus\' hjärta ingiver samma nit för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 17, 'Ty han mottog villigt vår uppmaning; ja, han var så nitisk, att han nu självmant far åstad till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 18, 'Med honom sända vi ock här en broder som i alla våra församlingar prisas för sitt nit om evangelium;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 19, 'dessutom har han ock av församlingarna blivit utvald att vara vår följeslagare, när vi skola begiva oss åstad med den kärleksgåva som nu genom vår försorg kommer till stånd, Herren till ära och såsom ett vittnesbörd om vår goda vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 20, 'Därmed vilja vi förebygga att man talar illa om oss, i vad som rör det rikliga sammanskott som nu genom vår försorg kommer till stånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 21, 'Ty vi vinnlägga oss om vad som är gott icke allenast inför Herren, utan ock inför människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 22, 'Jämte dessa sända vi en annan av våra bröder, vilkens nit vi ofta och i många stycken hava funnit hålla provet, och som nu på grund av sin stora tillit till eder är ännu mycket mer nitisk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 23, 'Om jag nu har anbefallt Titus, så mån I besinna att han är min medbroder och min medarbetare till edert bästa; och om jag har skrivit om andra våra bröder, så mån I besinna att de äro församlingssändebud och Kristi ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 24, 'Given alltså inför församlingarna bevis på eder kärlek, och därmed också på sanningen av det som vi inför dem hava sagt till eder berömmelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 1, 'Om understödet till de heliga är det nu visserligen överflödigt att jag här skriver till eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 2, 'jag känner ju eder goda vilja, och av den plägar jag, i fråga om eder, berömma mig inför macedonierna, i det jag omtalar att Akaja ända sedan förra året har varit redo, och att det är just edert nit som har eggat så många andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 3, 'Likväl sänder jag nu åstad dessa bröder, för att det som jag har sagt till eder berömmelse icke skall i denna del befinnas hava varit tomt tal. Ty, såsom jag förut har sagt, jag vill att I skolen vara redo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 4, 'Eljest, om några macedonier komma med mig och finna eder oberedda, kunna vi -- för att icke säga I -- till äventyrs komma på skam med vår tillförsikt i denna sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 5, 'Jag har därför funnit det vara nödvändigt att uppmana bröderna att i förväg begiva sig till eder och förbereda den rikliga »välsignelsegåva» som I redan haven utlovat. De skola laga att denna är tillreds såsom en riklig gåva, och icke såsom en gåva i njugghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 6, 'Besinnen detta: den som sår sparsamt, han skall ock skörda sparsamt; men den som sår rikligt, han skall ock skörda riklig välsignelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 7, 'Var och en give efter som han har känt sig manad i sitt hjärta, icke med olust eller av tvång, ty »Gud älskar en glad givare».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 8, 'Men Gud är mäktig att i överflödande mått låta all nåd komma eder till del, så att I alltid i allo haven allt till fyllest och i överflöd kunnen giva till allt gott verk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 9, 'efter skriftens ord: »Han utströr, han giver åt de fattiga, hans rättfärdighet förbliver evinnerligen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 10, 'Och han som giver såningsmannen »säd till att så och bröd till att äta», han skall ock giva eder utsädet och låta det föröka sig och skall bereda växt åt eder rättfärdighets frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 11, 'I skolen bliva så rika på allt, att I av gott hjärta kunnen giva allahanda gåvor, vilka, när de överlämnas genom oss, skola framkalla tacksägelse till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 12, 'Ty det understöd, som kommer till stånd genom denna eder tjänst, skall icke allenast avhjälpa de heligas brist, utan verka ännu långt mer genom att framkalla många tacksägelser till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 13, 'De skola nämligen, därför att I visen eder så väl hålla provet i fråga om detta understöd, komma att prisa Gud för att I med så lydaktigt sinne bekännen eder till Kristi evangelium och av så gott hjärta visen dem och alla andra edert deltagande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 14, 'De skola ock själva bedja för eder och längta efter eder, för den Guds nåds skull, som i så översvinnligen rikt mått beskäres eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 15, 'Ja, Gud vare tack för hans outsägligt rika gåva!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 1, 'Jag Paulus själv, som »är så ödmjuk, när jag står ansikte mot ansikte med eder, men visar mig så modig mot eder, när jag är långt borta», jag förmanar eder vid Kristi saktmod och mildhet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 2, 'och beder eder se till, att jag icke, när jag en gång är hos eder, måste »visa mig modig», i det jag helt oförskräckt tänker våga mig på somliga som mena att vi »vandra efter köttet».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 3, 'Ty fastän vi vandra i köttet, föra vi dock icke en strid efter köttet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 4, 'Våra stridsvapen äro nämligen icke av köttslig art; de äro tvärtom så mäktiga inför Gud, att de kunna bryta ned fästen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 5, 'Ja, vi bryta ned tankebyggnader och alla slags höga bålverk, som uppresas mot kunskapen om Gud, och vi taga alla slags tankefunder till fånga och lägga dem under Kristi lydnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 6, 'Och när lydnaden fullt har kommit till väldet bland eder, då äro vi redo att näpsa all olydnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 7, 'Sen då vad som ligger öppet för allas ögon. Om någon i sitt sinne är viss om att han hör Kristus till, så må han ytterligare besinna inom sig, att lika visst som han själv hör Kristus till, lika visst göra också vi det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 8, 'Och om jag än något härutöver berömmer mig, då nu fråga är om vår myndighet -- den som Herren har givit oss, till att uppbygga eder och icke till att nedbryta -- så skall jag dock icke komma på skam därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 9, 'Jag vill icke att det skall se ut, som om jag med mina brev allenast tänkte skrämma eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 10, 'Ty man säger ju: »Hans brev äro väl myndiga och stränga, men när han kommer själv, uppträder han utan kraft, och på hans ord aktar ingen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 11, 'Den som säger sådant, han må emellertid göra sig beredd på att sådana som vi äro i orden, genom våra brev, när vi äro frånvarande, sådana skola vi ock visa oss i gärningarna, när vi äro närvarande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 12, 'Ty vi äro icke nog dristiga att räkna oss till eller jämföra oss med somliga som giva sig själva gott vitsord, men som äro utan förstånd, i det att de mäta sig allenast efter sig själva och jämföra sig allenast med sig själva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 13, 'Vi för vår del vilja icke berömma oss till övermått, utan allenast efter måttet av det område som Gud tillmätte åt oss, när han bestämde att vi skulle nå fram jämväl till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 14, 'Ty vi sträcka oss icke utom vårt område, såsom nådde vi icke rätteligen fram till eder; vi hava ju redan med evangelium om Kristus hunnit fram jämväl till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 15, 'När vi säga detta, berömma vi oss icke till övermått, icke av andras arbete. Men väl hava vi det hoppet, att i samma mån som eder tro växer till, vi inom det område som har tillfallit oss skola bland eder vinna framgång, i så överflödande mått,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 16, 'att vi också få förkunna evangelium i trakter som ligga bortom eder -- och detta utan att vi, inom ett område som tillhör andra, berömma oss i fråga om det som redan där är uträttat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 17, 'Men »den som vill berömma sig, han berömme sig av Herren».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 18, 'Ty icke den håller provet, som giver sig själv gott vitsord, utan den som Herren giver sådant vitsord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 1, 'Jag skulle önska att I villen hava fördrag med mig, om jag nu talar något litet efter dårars sätt. Dock, I haven helt visst fördrag med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 2, 'Ty jag nitälskar för eder såsom Gud nitälskar, och jag har trolovat eder med Kristus, och ingen annan, för att kunna ställa fram inför honom en ren jungfru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 3, 'Men jag fruktar att såsom ormen i sin illfundighet bedrog Eva, så skola till äventyrs också edra sinnen fördärvas och dragas ifrån den uppriktiga troheten mot Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 4, 'Om någon kommer och predikar en annan Jesus, än den vi hava predikat, eller om I undfån ett annat slags ande, än den I förut haven undfått, eller ett annat slags evangelium, än det I förut haven mottagit, då fördragen I ju sådant alltför väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 5, 'Jag menar nu att jag icke i något stycke står tillbaka för dessa så övermåttan höga »apostlar».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 6, 'Om jag än är oförfaren i talkonsten, så är jag det likväl icke i fråga om kunskap. Tvärtom, vi hava på allt sätt, i alla stycken, lagt vår kunskap i dagen inför eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 7, 'Eller var det väl en synd jag begick, när jag för intet förkunnade Guds evangelium för eder och sålunda ödmjukade mig, på det att I skullen bliva upphöjda?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 8, 'Andra församlingar plundrade jag, i det jag, för att kunna tjäna eder, tog lön av dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 9, 'Och när jag under min vistelse hos eder led brist, låg jag ändå ingen till last; ty den brist jag led avhjälptes av bröderna, när de kommo från Macedonien. Ja, på allt sätt aktade jag mig för att vara eder till tunga, och allt framgent skall jag akta mig därför.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 10, 'Så visst som Kristi sannfärdighet är i mig, den berömmelsen skall icke få tagas ifrån mig i Akajas bygder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 11, 'Varför? Månne därför att jag icke älskar eder? Gud vet att jag så gör.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 12, 'Och vad jag nu gör, det skall jag ock framgent göra, för att de som trakta efter tillfälle att bliva likställda med oss i fråga om berömmelse skola genom mig berövas tillfället därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 13, 'Ty de männen äro falska apostlar, oredliga arbetare, som förskapa sig till Kristi apostlar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 14, 'Och detta är icke att undra på. Satan själv förskapar sig ju till en ljusets ängel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 15, 'Det är då icke något märkligt, om jämväl hans tjänare så förskapa sig, att de likna rättfärdighetens tjänare. Men deras ände skall svara emot deras gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 16, 'Åter säger jag: Ingen må mena att jag är en dåre; men om jag vore det, så mån I ändå hålla till godo med mig -- låt vara såsom med en dåre -- så att ock jag får berömma mig något litet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 17, 'Vad jag talar, då jag nu med sådan tillförsikt berömmer mig, det talar jag icke efter Herrens sinne, utan efter dårars sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 18, 'Då så många berömma sig på köttsligt vis, vill ock jag berömma mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 19, 'I haven ju gärna fördrag med dårar, I som själva ären så kloka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 20, 'I fördragen ju, om man trälbinder eder, om man utsuger eder, om man fångar eder, om man förhäver sig över eder, om man slår eder i ansiktet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 21, 'Till vår skam måste jag tillstå att vi för vår del hava »varit för svaga» till sådant. Men eljest, vadhelst andra kunna göra sig stora med, det kan också jag göra mig stor med -- om jag nu får tala efter dårars sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 22, 'Äro de hebréer, så är jag det ock. Äro de israeliter, så är jag det ock. Äro de Abrahams säd, så är jag det ock.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 23, 'Äro de Kristi tjänare, så är jag det ännu mer -- om jag nu får tala såsom vore jag en dåre. Jag har haft mer arbete, oftare varit i fängelse, fått hugg och slag till överflöd, varit i dödsnöd många gånger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 24, 'Av judarna har jag fem gånger fått fyrtio slag, på ett när.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 25, 'Tre gånger har jag blivit piskad med spön, en gång har jag blivit stenad, tre gånger har jag lidit skeppsbrott, ett helt dygn har jag drivit omkring på djupa havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 26, 'Jag har ofta måst vara ute på resor; jag har utstått faror på floder, faror bland rövare, faror genom landsmän, faror genom hedningar, faror i städer, faror i öknar, faror på havet, faror bland falska bröder --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 27, 'allt under arbete och möda, under mångfaldiga vakor, under hunger och törst, under svält titt och ofta, under köld och nakenhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 28, 'Och till allt annat kommer det, att jag var dag är överlupen, då jag måste hava omsorg om alla församlingarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 29, 'Vem är svag, utan att också jag bliver svag? Vem kommer på fall, utan att jag bliver upptänd? --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 30, 'Om jag nu måste berömma mig, så vill jag berömma mig av min svaghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 31, 'Herren Jesu Gud och Fader, han som är högtlovad i evighet, vet att jag icke ljuger.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 32, 'I Damaskus lät konung Aretas\' ståthållare sätta ut vakt vid damaskenernas stad för att gripa mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 33, 'och jag måste i en korg släppas ned genom en öppning på muren och kom så undan hans händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 1, 'Jag måste ytterligare berömma mig. Väl är sådant icke eljest nyttigt, men jag kommer nu till syner och uppenbarelser, som hava beskärts mig av Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 2, 'Jag vet om en man som är i Kristus, att han för fjorton år sedan blev uppryckt ända till tredje himmelen; huruvida det nu var i kroppslig måtto, eller om han var skild från sin kropp, det vet jag icke, Gud allena vet det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 3, 'Ja, jag vet om denne man, att han -- huruvida det nu var i kroppslig måtto, eller om han var skild från sin kropp, det vet jag icke, Gud allena vet det --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 4, 'jag vet om honom, att han blev uppryckt till paradiset och fick höra outsägliga ord, sådana som det icke är lovligt för en människa att uttala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 5, 'I fråga om den mannen vill jag berömma mig, men i fråga om mig själv vill jag icke berömma mig, om icke av min svaghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 6, 'Visserligen skulle jag icke vara en dåre, om jag ville berömma mig själv, ty det vore sanning som jag då skulle tala; men likväl avhåller jag mig därifrån, för att ingen skall hava högre tankar om mig än skäligt är, efter vad han ser hos mig eller hör av mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 7, 'Och för att jag icke skall förhäva mig på grund av mina övermåttan höga uppenbarelser, har jag fått en törntagg i mitt kött, en Satans ängel, som skall slå mig i ansiktet, för att jag icke skall förhäva mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 8, 'Att denne måtte vika ifrån mig, därom har jag tre gånger bett till Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 9, 'Men Herren har sagt till mig; »Min nåd är dig nog, ty kraften fullkomnas i svaghet.» Därför vill jag hellre med glädje berömma mig av min svaghet, på det att Kristi kraft må komma och vila över mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 10, 'Ja, därför finner jag behag i svaghet, i misshandling, i nöd, i förföljelse, i ångest för Kristi skull; ty när jag är svag, då är jag stark.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 11, 'Så har jag nu gjort mig till en dåre; I haven själva nödgat mig därtill. Jag hade ju bort få gott vitsord av eder; ty om jag än är ett intet, så har jag dock icke i något stycke stått tillbaka för dessa så övermåttan höga »apostlar».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 12, 'De gärningar som äro en apostels kännemärken hava ock med all uthållighet blivit gjorda bland eder, genom tecken och under och kraftgärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 13, 'Och haven I väl i något stycke blivit tillbakasatta för de andra församlingarna? Dock, kanhända i det stycket, att jag för min del icke har legat eder till last? Den oförrätten mån I då förlåta mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 14, 'Se, det är nu tredje gången som jag står redo att komma till eder. Och jag skall icke ligga eder till last, ty icke edert söker jag, utan eder själva. Och barnen äro ju icke pliktiga att spara åt föräldrarna, utan föräldrarna åt barnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 15, 'Och för min del vill jag gärna för edra själar både offra vad jag äger och låta mig själv offras hel och hållen. Om jag nu så högt älskar eder, skall jag väl därför bliva mindre älskad?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 16, 'Dock, det kunde ju vara så, att jag visserligen icke själv hade betungat eder, men att jag på en listig omväg hade fångat eder, jag som är så illfundig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 17, 'Har jag då verkligen, genom någon av dem som jag har sänt till eder, berett mig någon orätt vinning av eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 18, 'Sant är att jag bad Titus fara och sände med honom den andre brodern. Men icke har väl Titus berett mig någon orätt vinning av eder? Hava vi icke båda vandrat i en och samme Ande? Hava vi icke båda gått i samma fotspår?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 19, 'Nu torden I redan länge hava menat att det är inför eder som vi försvara oss. Nej, det är inför Gud, i Kristus, som vi tala, men visserligen alltsammans för att uppbygga eder, I älskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 20, 'Ty jag fruktar att jag vid min ankomst till äventyrs icke skall finna eder sådana som jag skulle önska, och att jag själv då av eder skall befinnas vara sådan som I icke skullen önska. Jag fruktar att till äventyrs kiv, avund, vrede, genstridighet, förtal, skvaller, uppblåsthet och oordning råda bland eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 21, 'Ja, jag fruktar att min Gud skall låta mig vid min ankomst åter bliva förödmjukad genom eder, och att jag skall få sörja över många av dem som förut hava syndat, och som ännu icke hava känt ånger över den orenhet och otukt och lösaktighet som de hava övat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 1, 'Det är nu tredje gången som jag skall komma till eder; »efter två eller tre vittnens utsago skall var sak avgöras».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 2, 'Till dem som förut hava syndat och till alla de andra har jag redan i förväg sagt, och jag säger nu åter i förväg -- nu då jag är borta ifrån eder, likasom förut då jag för andra gången var hos eder -- att jag icke skall visa någon skonsamhet, när jag kommer igen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 3, 'I viljen ju hava ett bevis för att det är Kristus som talar i mig, han som icke är svag mot eder, utan är stark bland eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 4, 'Ty om han än blev korsfäst i följd av svaghet, så lever han dock av Guds kraft. Också vi äro ju svaga i honom, men av Guds kraft skola vi leva med honom och bevisa det på eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 5, 'Rannsaken eder själva, huruvida I ären i tron, ja, pröven eder själva. Eller kännen I icke med eder själva att Jesus Kristus är i eder? Varom icke, så hållen I ej provet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 6, 'Att vi för vår del icke äro av dem som ej hålla provet, det hoppas jag att I skolen få lära känna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 7, 'Men vi bedja till Gud att I icke mån göra något ont, detta icke för att vi å vår sida skola synas hålla provet, utan för att I själva verkligen skolen göra vad gott är. Sedan må vi å vår sida gärna anses icke hålla provet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 8, 'Ty icke mot sanningen, utan allenast för sanningen förmå vi något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 9, 'Och vi glädja oss, när vi äro svaga, men I ären starka. Just detta bedja vi också om, att I mån alltmer fullkomnas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 10, 'Och medan jag ännu är borta ifrån eder, skriver jag detta, för att jag icke, när jag är hos eder, skall nödgas uppträda med stränghet, i kraft av den myndighet som Herren har givit mig, till att uppbygga och icke till att nedbryta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 11, 'För övrigt, mina bröder, varen glada, låten fullkomna eder, låten förmana eder, varen ens till sinnes, hållen frid; då skall kärlekens och fridens Gud vara med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 12, 'Hälsen varandra med en helig kyss. Alla de heliga hälsa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 13, 'Herrens, Jesu Kristi, nåd och Guds kärlek och den helige Andes delaktighet vare med eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 14, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Paulus, apostel, icke från människor, ej heller genom någon människa, utan genom Jesus Kristus och genom Gud, Fadern, som har uppväckt honom från de döda --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'jag, jämte alla de bröder som äro här med mig, hälsar församlingarna i Galatien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och ifrån Herren Jesus Kristus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'som har utgivit sig själv för våra synder, för att rädda oss från den nuvarande onda tidsåldern, efter vår Guds och Faders vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Honom tillhör äran i evigheternas evigheter. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Det förundrar mig att I så hastigt avfallen från honom, som har kallat eder till att vara i Kristi nåd, och vänden eder till ett nytt evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Likväl är detta icke något annat »evangelium»; det är allenast så, att några finnas som vålla förvirring bland eder och vilja förvända Kristi evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Men om någon, vore det ock vi själva eller en ängel från himmelen, förkunnar evangelium i strid mot vad vi hava förkunnat för eder, så vare han förbannad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Ja, såsom vi förut hava sagt, så säger jag nu åter: Om någon förkunnar evangelium för eder i strid mot vad I haven undfått, så vare han förbannad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Är det då människor som jag nu söker vinna för mig, eller är det Gud? Står jag verkligen efter att »vara människor till behag»? Nej, om jag ännu ville vara människor till behag, så vore jag icke en Kristi tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ty det vill jag säga eder, mina bröder, att det evangelium som har blivit förkunnat av mig icke är någon människolära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Det är ju icke heller av någon människa som jag har undfått det eller blivit undervisad däri, utan genom en uppenbarelse från Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'I haven ju hört huru det var med mig, medan jag ännu vandrade i judiskt väsende: att jag då övermåttan våldsamt förföljde Guds församling och ville utrota den,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'ja, att jag gick längre i judiskt väsende än många av mina samtida landsmän och ännu ivrigare nitälskade för mina fäders stadgar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Men när han, som allt ifrån min moders liv har avskilt mig, och som genom sin nåd har kallat mig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'täcktes i mig uppenbara sin Son, för att jag bland hedningarna skulle förkunna evangelium om honom, då begav jag mig strax åstad; jag rådförde mig icke med någon människa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'ej heller for jag upp till Jerusalem, till dem som före mig voro apostlar. I stället for jag bort till Arabien och vände så åter tillbaka till Damaskus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Först sedan, tre år därefter, for jag upp till Jerusalem, för att lära känna Cefas, och jag stannade hos honom femton dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Men av de andra apostlarna såg jag ingen; allenast Jakob, Herrens broder, såg jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Och Gud vet att jag icke ljuger i vad jag här skriver till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Därefter for jag till Syriens och Ciliciens bygder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Men för de kristna församlingarna i Judeen var jag personligen okänd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'De hörde allenast huru man sade: »Han som förut förföljde oss, han förkunnar nu evangelium om den tro som han förr ville utrota.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Och de prisade Gud för min skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Efter fjorton års förlopp for jag sedan åter upp till Jerusalem, åtföljd av Barnabas; jag tog då också Titus med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Men det var på grund av en uppenbarelse som jag for dit. Och för bröderna där framlade jag det evangelium som jag predikar bland hedningarna; särskilt framlade jag det för de män som stodo högst i anseende -- detta av oro för att mitt strävande nu vore förgäves eller förut hade varit det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'Men icke ens Titus, min följeslagare, som var grek, blev nödgad att låta omskära sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'Det var nämligen så, att några falska bröder hade kommit att upptagas i församlingen, dit de hade smugit sig in för att bespeja vår frihet, den som vi hava i Kristus Jesus, varefter de ville trälbinda oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'Dock gåvo vi icke ens ett ögonblick vika för dem genom en sådan underkastelse; ty vi ville att evangelii sanning skulle bliva bevarad hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Och vad angår dem som ansågos något vara -- hurudana de nu voro, det kommer icke mig vid; Gud har icke anseende till personen -- så sökte icke dessa män, de som stodo högst i anseende, att pålägga mig några nya förpliktelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'Tvärtom; de sågo att jag hade blivit betrodd med att förkunna evangelium för de oomskurna, likasom Petrus hade fått de omskurna på sin del --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'ty densamme som hade stått Petrus bi vid hans apostlaverksamhet bland de omskurna, han hade ock stått mig bi bland hedningarna --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'och när de nu förnummo vilken nåd som hade blivit mig given, räckte de mig och Barnabas handen till samarbete, både Jakob och Cefas och Johannes, de män som räknades för själva stödjepelarna; vi skulle verka bland hedningarna, och de bland de omskurna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Allenast skulle vi tänka på de fattiga; och just detta har jag också vinnlagt mig om att göra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Men när Cefas kom till Antiokia, trädde jag öppet upp mot honom, ty han hade befunnits skyldig till en försyndelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'Förut hade han nämligen ätit tillsammans med hedningarna; men så kommo några män dit från Jakob, och efter deras ankomst drog han sig tillbaka och höll sig undan, av fruktan för de omskurna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'Till samma skrymteri gjorde sig också de andra judarna skyldiga, och så blev till och med Barnabas indragen i deras skrymteri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Men när jag såg att de icke vandrade med fasta steg, enligt evangelii sanning, sade jag till Cefas i allas närvaro: »Om du, som är en jude, kan leva efter hednisk sed i stället för efter judisk, varför vill du då nödga hedningarna att leva efter judiskt sätt?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'Vi för vår del äro väl på grund av vår härkomst judar och icke »hedniska syndare»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'men då vi nu veta att en människa icke bliver rättfärdig av laggärningar, utan genom tro på Kristus Jesus, hava också vi satt vår tro till Jesus Kristus, för att vi skola bliva rättfärdiga av tro på Kristus, och icke av laggärningar. Ty av laggärningar bliver intet kött rättfärdigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Men om nu jämväl vi, i det vi sökte att bliva rättfärdiga i Kristus, hava befunnits vara syndare, då är ju Kristus en syndatjänare? Bort det!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'Om så vore att jag byggde upp igen detta samma som jag redan har brutit ned, då bevisade jag därmed, att jag var en överträdare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 19, 'Ty jag för min del har genom lagen dött bort ifrån lagen, för att jag skall leva för Gud. Jag är korsfäst med Kristus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 20, 'och nu lever icke mer jag, utan Kristus lever i mig; och det liv som jag nu lever i köttet, det lever jag i tron på Guds Son, som har älskat mig och utgivit sig själv för mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 21, 'Jag förkastar icke Guds nåd. Om rättfärdighet kunde vinnas genom lagen, då hade ju Kristus icke behövt lida döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'I oförståndige galater! Vem har så dårat eder, I som dock haven fått Jesus Kristus målad för edra ögon såsom korsfäst?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'Allenast det vill jag att I skolen svara mig på: Kom det sig av laggärningar att I undfingen Anden, eller kom det sig därav att I lyssnaden i tro?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Ären I så oförståndiga? I, som haven begynt i Anden, viljen I nu sluta i köttet?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Haven I då upplevat så mycket förgäves -- om det nu verkligen har varit förgäves?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Alltså, att han som förlänade eder Anden och utförde kraftgärningar bland eder gjorde detta, kom det sig av laggärningar eller därav att I lyssnaden i tro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'i enlighet med det ordet: »Abraham trodde Gud, och det räknades honom till rättfärdighet»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'Så mån I nu veta att de som låta det bero på tro, de äro Abrahams barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'Och eftersom skriften förutsåg att det var av tro som hedningarna skulle bliva rättfärdiggjorda av Gud, så gav den i förväg åt Abraham detta glada budskap: »I dig skola alla folk varda välsignade.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Alltså bliva de som låta det bero på tro välsignade tillika med Abraham, honom som trodde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'Ty alla de som låta det bero på laggärningar, de äro under förbannelse. Det är nämligen skrivet: »Förbannad vare var och en som icke förbliver vid allt som är skrivet i lagens bok, och icke gör därefter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'Och att ingen i kraft av lag bliver rättfärdig inför Gud, det är uppenbart, eftersom det heter: »Den rättfärdige skall leva av tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Men i lagen beror det icke på tro; tvärtom heter det: »Den som gör efter dessa stadgar skall leva genom dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Kristus friköpte oss från lagens förbannelse, när han blev en förbannelse för vår skull. Det är ju skrivet: »Förbannad är var och en som är upphängd på trä.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Vi friköptes, för att den välsignelse som hade givits åt Abraham skulle i Jesus Kristus komma också hedningarna till del, så att vi genom tron skulle undfå den utlovade Anden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'Mina bröder, jag vill taga ett exempel från vad som gäller bland människor. Icke ens när fråga är om en människas testamentsförordnande, kan någon upphäva det eller lägga något därtill, sedan det en gång har vunnit gällande kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Nu gåvos löftena åt Abraham, så ock åt hans »säd». Det heter icke: »och åt dem som komma av din säd», såsom när det talas om många; utan det heter, såsom när det talas om en enda: »och åt din säd», vilken är Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Vad jag alltså vill säga är detta: Ett förordnande som Gud redan hade givit gällande kraft kan icke genom en lag, som utgavs fyra hundra trettio år därefter, hava blivit ogiltigt, så att löftet därmed har gjorts om intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Om det nämligen vore på grund av lag som arvet skulle undfås, så vore det icke på grund av löfte. Men åt Abraham har Gud skänkt det genom ett löfte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'Vartill tjänade då lagen? Jo, på det att överträdelserna skulle komma i dagen, blev den efteråt given, för att gälla till dess att »säden» skulle komma, han åt vilken löftet hade blivit givet; och den utgavs genom änglar och överlämnades i en medlares hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 20, 'Men den som är medlare är icke medlare för allenast en enda. Men Gud är en.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 21, 'Är då lagen emot Guds löften? Bort det! Om en lag hade blivit given, som kunde göra levande, då skulle rättfärdigheten verkligen komma av lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 22, 'Men nu har skriften inneslutit alltsammans under synd, för att det som var utlovat skulle, av tro på Jesus Kristus, komma dem till del som tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 23, 'Men förrän tron kom, voro vi inneslutna under lagen och höllos i förvar under den, i förbidan på den tro som en gång skulle uppenbaras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 24, 'Så har lagen blivit vår uppfostrare till Kristus, för att vi skola bliva rättfärdiga av tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 25, 'Men sedan tron har kommit, stå vi icke mer under uppfostrare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 26, 'Alla ären I Guds barn genom tron, i Kristus Jesus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 27, 'ty I alla, som haven blivit döpta till Kristus, haven iklätt eder Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 28, 'Här är icke jude eller grek, här är icke träl eller fri, här är icke man och kvinna: alla ären I ett i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 29, 'Hören I nu Kristus till, så ären I därmed ock Abrahams säd, arvingar enligt löftet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Vad jag vill säga är detta: Så länge arvingen är barn, finnes ingen skillnad mellan honom och en träl, fastän han är herre över alla ägodelarna;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'ty han står under förmyndare och förvaltare, intill den tid som fadern har bestämt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Sammalunda höllos ock vi, när vi voro barn, i träldom under världens »makter»[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'Men när tiden var fullbordad, sände Gud sin Son, född av kvinna och ställd under lagen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'för att han skulle friköpa dem som stodo under lagen, så att vi skulle få söners rätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Och eftersom I nu ären söner, har han sänt i våra hjärtan sin Sons Ande, som ropar: »Abba! Fader!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Så är du nu icke mer träl, utan son; och är du son, så är du ock arvinge, insatt därtill av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Förut, innan I ännu känden Gud, voren I trälar under gudar som till sitt väsende icke voro gudar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Men nu, sedan I haven lärt känna Gud och, vad mer är, haven blivit kända av Gud, huru kunnen I nu vända tillbaka till de svaga och arma »makter», under vilka I åter på nytt viljen bliva trälar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'I akten ju på dagar och på månader och på särskilda tider och år. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Jag är bekymrad för eder och fruktar att jag till äventyrs har arbetat förgäves för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Jag beder eder, mina bröder: Bliven såsom jag är, eftersom jag har blivit såsom I voren. I haven icke gjort mig något för när.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'I veten ju att det var på grund av kroppslig svaghet som jag första gången kom att förkunna evangelium för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Och fastän mitt kroppsliga tillstånd då väl hade kunnat innebära en frestelse för eder, så sågen I det ändå icke med ringaktning eller leda, utan togen emot mig såsom en Guds ängel, ja, såsom Kristus Jesus själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'När hör man eder nu prisa eder saliga? Det vittnesbördet kan jag nämligen giva eder, att I då, om så hade varit möjligt, skullen hava rivit ut edra ögon och givit dem åt mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Så har jag då blivit eder ovän därigenom att jag säger eder sanningen!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Man söker med iver att vinna eder för sig, men icke med en god iver; nej, del vilja avspärra eder från andra, för att I med så mycket större iver skolen hålla eder till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'Och det är nu gott att I bliven omfattade med ivrig omsorg, i en god sak, alltid, och icke allenast när jag är tillstädes hos eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 19, 'I mina barn, som jag nu åter med vånda måste föda till livet, intill dess att Kristus har tagit gestalt i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 20, 'Jag skulle önska att jag just nu vore hos eder och kunde göra min röst rätt bevekande. Ty jag vet mig knappt någon råd med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 21, 'Sägen mig, I som viljen stå under lagen: haven I icke hört vad lagen säger?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 22, 'Det är ju skrivet att Abraham fick två söner, en med sin tjänstekvinna, och en med sin fria hustru.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 23, 'Men tjänstekvinnans son är född efter köttet, då däremot den fria hustruns son är född i kraft av löftet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 24, 'Dessa ord hava en djupare mening; ty de båda kvinnorna beteckna två förbund. Av dessa kommer det ena från berget Sina och föder sina barn till träldom, och detta har sin förebild i Agar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 25, 'Berget Sina kallas nämligen i Arabien för Agar och svarar emot det nuvarande Jerusalem, ty detta lever med sina barn i träldom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 26, 'Men det Jerusalem som är därovan, det är fritt, och det är vår moder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 27, 'Så är ju skrivet: »Jubla, du ofruktsamma, du som icke föder barn; brist ut och ropa, du som icke bliver moder, Ty den ensamma skall hava många barn, flera än den som har man.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 28, 'Och I, mina bröder, ären löftets barn, likasom Isak var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 29, 'Men likasom förr i tiden den son som var född efter köttet förföljde den som var född efter Anden, så är det ock nu.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 30, 'Dock, vad säger skriften? »Driv ut tjänstekvinnan och hennes son; ty tjänstekvinnans son skall förvisso icke ärva med den fria hustruns son.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 31, 'Alltså, mina bröder, vi äro icke barn av en tjänstekvinna, utan av den fria hustrun. [1] Se Makter i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, 'För att vi skola vara fria, har Kristus frigjort oss. Stån därför fasta, och låten icke något nytt träldomsok läggas på eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'Se, jag säger eder, jag Paulus, att om I låten omskära eder, så bliver Kristus eder till intet gagn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'Och för var och en som låter omskära sig betygar jag nu åter att han är pliktig att fullgöra hela lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'I haven kommit bort ifrån Kristus, I som viljen bliva rättfärdiga i kraft av lagen; I haven fallit ur nåden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Vi vänta nämligen genom ande, av tro, den rättfärdighet som är vårt hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, 'Ty i Kristus Jesus betyder det intet huruvida någon är omskuren eller oomskuren; allt beror på huruvida han har en tro som är verksam genom kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'I begynten edert lopp väl. Vem har nu lagt hinder i eder väg, så att I icke mer lyden sanningen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'Till sådant kom ingen maning från honom som har kallat eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'Litet surdeg syrar hela degen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'För min del har jag i Herren den tillförsikten till eder, att I icke häri skolen tänka på annat sätt; men den som vållar förvirring bland eder, han skall bära sin dom, vem han än må vara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, 'Om så vore, mina bröder, att jag själv ännu predikade omskärelse, varför skulle jag då ännu alltjämt lida förföljelse? Då vore ju korsets stötesten röjd ur vägen. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Jag skulle önska att de män som uppvigla eder läte omskära sig ända till avstympning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'I ären ju kallade till frihet, mina bröder; bruken dock icke friheten så, att köttet får något tillfälle. Fastmer mån I tjäna varandra genom kärleken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'Ty hela lagens uppfyllelse ligger i ett enda budord, nämligen detta: »Du skall älska din nästa såsom dig själv.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 15, 'Men om I bitens inbördes och äten på varandra, så mån I se till, att I icke bliven uppätna av varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 16, 'Vad jag vill säga är detta: Vandren i ande, så skolen I förvisso icke göra vad köttet har begärelse till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 17, 'Ty köttet har begärelse mot Anden, och Anden mot köttet; de två ligga ju i strid med varandra, för att hindra eder att göra vad I viljen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 18, 'Men om I drivens av ande, så stån I icke under lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 19, 'Men köttets gärningar äro uppenbara: de äro otukt, orenhet, lösaktighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 20, 'avgudadyrkan, trolldom, ovänskap, kiv, avund, vrede, genstridighet, tvedräkt, partisöndring,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 21, 'missunnsamhet, mord, dryckenskap, vilt leverne och annat sådant, varom jag säger eder i förväg, såsom jag redan förut har sagt, att de som göra sådant, de skola icke få Guds rike till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 22, 'Andens frukt åter är kärlek, glädje, frid, tålamod, mildhet, godhet, trofasthet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 23, 'saktmod, återhållsamhet. Mot sådant är icke lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 24, 'Och de som höra Kristus Jesus till hava korsfäst sitt kött tillika med dess lustar och begärelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 25, 'Om vi nu hava liv genom ande, så låtom oss ock vandra i ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 26, 'Låtom oss icke söka fåfänglig ära, i det att vi utmana varandra och avundas varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, 'Mina bröder, om så händer att någon ertappas med att begå en försyndelse, då mån I, som ären andliga människor, upprätta honom i saktmods ande. Och du må hava akt på dig själv, att icke också du bliver frestad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'Bären varandras bördor; så uppfyllen I Kristi lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'Ty om någon tycker sig något vara, fastän han intet är, så bedrager han sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Må var och en pröva sina egna gärningar; han skall då tillmäta sig berömmelse allenast efter vad han själv är, och icke efter vad andra äro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'Ty var och en har sin egen börda att bära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'Den som får undervisning i ordet, han låte den som undervisar honom få del med sig i allt gott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'Faren icke vilse. Gud låter icke gäcka sig. Ty vad människan sår, det skall hon ock skörda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'Den som sår i sitt kötts åker, han skall av köttet skörda förgängelse, men den som sår i Andens åker, han skall av Anden skörda evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'Och låtom oss icke förtröttas att göra vad gott är; ty om vi icke uppgivas, så skola vi, när tiden är inne, få inbärga vår skörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'Må vi alltså, medan vi hava tillfälle, göra vad gott är mot var man, och först och främst mot dem som äro våra medbröder i tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, 'Sen här med vilka stora bokstäver jag egenhändigt skriver till eder!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'Alla de som eftersträva ett gott anseende här i köttet, de vilja nödga eder till omskärelse, detta allenast för att de själva skola undgå att bliva förföljda för Kristi kors\' skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Ty icke ens dessa omskurna själva hålla lagen. Nej, det är för att kunna berömma sig av edert kött som de vilja att I skolen låta omskära eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, 'Men vad mig angår, så vare det fjärran ifrån mig att berömma mig av något annat än av vår Herres, Jesu Kristi, kors, genom vilket världen för mig är korsfäst, och jag för världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'Ty det kommer icke an på om någon är omskuren eller oomskuren; allt beror på huruvida han är en ny skapelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Och över alla dem som komma att vandra efter detta rättesnöre, över dem vare frid och barmhärtighet, ja, över Guds Israel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, 'Må nu ingen härefter vålla mig oro; ty jag bär Jesu märken på min kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, 'Vår Herres, Jesu Kristi, nåd vare med eder ande, mina bröder. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Paulus, genom Guds vilja Kristi Jesu apostel, hälsar de heliga som bo i Efesus[1], de i Kristus Jesus troende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Välsignad vare vår Herres, Jesu Kristi, Gud och Fader, som i Kristus har välsignat oss med all den himmelska världens andliga välsignelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'såsom han ju, förrän världens grund var lagd, har utvalt oss i honom till att vara heliga och ostraffliga inför sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Ty i sin kärlek förutbestämde han oss till barnaskap hos sig, genom Jesus Kristus, efter sin viljas behag,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'den nådeshärlighet till pris, varmed han har benådat oss i den älskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'I honom hava vi förlossning genom hans blod, förlåtelse för våra synder, efter hans nåds rikedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Och denna nåd har han i överflödande mått låtit komma oss till del, med all vishet och allt förstånd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'i det att han för oss har kungjort sin viljas hemlighet, enligt det beslut som han efter sitt behag hade fattat inom sig själv,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'om en ordning som i tidernas fullbordan skulle komma till stånd, det beslutet att i Kristus sammanfatta allt som finnes i himmelen och på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'I honom hava vi ock undfått vår arvslott, vi som förut voro bestämda därtill genom dens beslut, som verkar allting efter sin egen viljas råd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Så skulle vi, hans härlighet till pris, vara de som i Kristus redan i förväg hava ägt ett hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'I honom haven jämväl I, sedan I haven fått höra sanningens ord, eder frälsnings evangelium, ja, i honom haven I, sedan I nu ock haven kommit till tron, såsom ett insegel undfått den utlovade helige Ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'vilken är en underpant på vårt arv, till förvissning om att hans egendomsfolk skall förlossas, hans härlighet till pris.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Sedan jag fick höra om eder tro i Herren Jesus och om eder kärlek till alla de heliga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'har därför jag å min sida icke upphört att tacka Gud för eder, när jag tänker på eder i mina böner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Och min bön är att vår Herres, Jesu Kristi, Gud, härlighetens Fader, må giva eder en visdomens och uppenbarelsens ande till kunskap om sig,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'och att han må upplysa edra hjärtans ögon, så att I förstån hurudant det hopp är, vartill han har kallat eder, huru rikt på härlighet hans arv är bland de heliga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'och huru översvinnligt stor hans makt är på oss som tro -- allt i enlighet med den väldiga styrkas kraft,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'varmed han har verkat i Kristus, i det att han uppväckte honom från de döda och satte honom på sin högra sida i den himmelska världen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'över alla andevärldens furstar och väldigheter och makter och herrar, ja, över allt som kan nämnas, icke allenast i denna tidsålder, utan ock i den tillkommande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, '»Allt lade han under hans fötter.» Och honom gav han åt församlingen till att vara ett huvud över allting --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'åt församlingen, ty den är hans kropp och är uppfylld av honom som uppfyller allt i alla. [1] Se Nya testamentets text i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Så har han ock gjort eder levande, eder som voren döda genom de överträdelser och synder');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'i vilka I förut vandraden, efter denna världs och tidsålders sätt, i det I följden fursten över luftens härsmakt, över den andemakt som nu är verksam i de ohörsamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Bland dessa voro förut också vi allasammans, där vi vandrade i vårt kötts begärelser och gjorde vad köttet och sinnet ville; och vi voro genom vår natur hemfallna åt vredesdomen, vi likasom de andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Men Gud, som är rik på barmhärtighet, har, för den stora kärleks skull, varmed han har älskat oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'gjort oss levande med Kristus, oss som voro döda genom våra synder. Av nåd ären I frälsta!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ja, han har uppväckt oss med honom och satt oss med honom i den himmelska världen, i Kristus Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'för att i de kommande tidsåldrarna bevisa sin nåds översvinnliga rikedom, genom godhet mot oss i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Ty av nåden ären I frälsta genom tro -- och det icke av eder själva, Guds gåva är det --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'icke av gärningar, för att ingen skall berömma sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ty hans verk äro vi, skapade i Kristus Jesus till goda gärningar, vilka Gud förut har berett, för att vi skola vandra i dem[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kommen därför ihåg att I förut, I som voren hedningar i köttet och bleven kallade oomskurna av dem som kallas omskurna, efter den omskärelse som med händer göres på köttet --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'kommen ihåg att I på den tiden, då när I voren utan Kristus, voren utestängda från medborgarskap i Israel och främmande för löftets förbund, utan hopp och utan Gud i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Nu däremot, då I ären i Kristus Jesus, haven I, som förut voren fjärran, kommit nära, i och genom Kristi blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ty han är vår frid, han som av de båda har gjort ett och brutit ned den skiljemur som stod emellan oss, nämligen ovänskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Ty i sitt kött gjorde han om intet budens stadgelag, för att han skulle av de två i sig skapa en enda ny människa och så bereda frid,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'och för att han skulle åt dem båda, förenade i en enda kropp, skaffa försoning med Gud, sedan han genom korset hade i sin person dödat ovänskapen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Och han har kommit och har förkunnat det glada budskapet om frid för eder, I som voren fjärran, och om frid för dem som voro nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Ty genom honom hava vi, de ena såväl som de andra, i en och samme Ande tillträde till Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Alltså ären I nu icke mer främlingar och gäster, utan I haven medborgarskap med de heliga och ären Guds husfolk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'uppbyggda på apostlarnas och profeternas grundval, där hörnstenen är Kristus Jesus själv,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'i vilken allt det som uppbygges bliver sammanslutet och så växer upp till ett heligt tempel i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'I honom bliven också I med de andra uppbyggda till en Guds boning, i Anden. [1] Eller: Ty hans verk äro vi, skapade i Kristus Jesus till goda gärningar; till att vandra i sådana har ju Gud förut berett oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Fördenskull böjer jag mina knän, jag Paulus, som till gagn för eder, I hedningar, är Kristi Jesu fånge.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'I haven väl hört om det nådesuppdrag av Gud, som är mig givet för eder räkning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'huru genom uppenbarelse den hemlighet blev för mig kungjord, varom jag ovan har i korthet skrivit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Och när I läsen detta, kunnen I därav förstå vilken insikt jag har i Kristi hemlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'som under förgångna släktens tider icke hade blivit kungjord för människors barn, såsom den nu genom andeingivelse har blivit uppenbarad för hans heliga apostlar och profeter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Jag menar den hemligheten, att hedningarna i Kristus Jesus äro våra medarvingar och jämte oss lemmar i en och samma kropp och jämte oss delaktiga i löftet -- detta genom evangelium,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'vars tjänare jag har blivit i följd av den Guds nåds gåva som blev mig given genom hans mäktiga kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Ja, åt mig, den ringaste bland alla heliga, blev den nåden given att för hedningarna förkunna evangelium om Kristi outrannsakliga rikedom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'och att lägga i dagen huru det rådslut har blivit utfört, som tidsåldrarna igenom hade såsom en hemlighet varit fördolt i Gud, alltings skapare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ty Gud ville att hans mångfaldiga visdom nu, i och genom församlingen, skulle bliva kunnig för furstarna och väldigheterna i den himmelska världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Sådant hade hans beslut varit från tidsåldrarnas begynnelse, det som han utförde i Kristus Jesus, vår Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Och i honom kunna vi med tillförsikt frimodigt träda fram, genom tron på honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Därför beder jag eder att icke fälla modet vid mina lidanden för eder; de lända ju eder till ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Fördenskull böjer jag mina knän för Fadern --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'honom från vilken allt vad fader heter i himmelen och på jorden har sitt namn --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'och beder att han ville efter sin härlighets rikedom förläna eder, att I genom hans Ande växen till i kraft till eder invärtes människa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'och att Kristus genom tron må bo i edra hjärtan, och att I mån vara rotade och grundade i kärleken,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'så att I, tillika med alla de heliga, till fullo förmån fatta vad bredden och längden och höjden och djupet är');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'och så lära känna Kristi kärlek, som övergår all kunskap. Ty så skolen I bliva helt uppfyllda av all Guds fullhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Men honom, som förmår göra mer, ja, långt mer än allt vad vi bedja eller tänka, efter den kraft som är verksam i oss,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'honom tillhör äran i församlingen och i Kristus Jesus alla släkten igenom i evigheternas evighet, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Så förmanar jag nu eder, jag som är en fånge i Herren, att föra en vandel som är värdig den kallelse I haven undfått,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'med all ödmjukhet och allt saktmod, med tålamod, så att I haven fördrag med varandra i kärlek');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'och vinnläggen eder om att bevara Andens enhet genom fridens band:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'en[1] kropp och en[1] Ande, likasom I ock bleven kallade till att leva i ett och samma hopp, det som tillhör eder kallelse --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'en[1] Herre, en[1] tro, ett[1] dop, en[1] Gud, som är allas Fader,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'han som är över alla, genom alla och i alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Men åt var och en särskild av oss blev nåden given, alltefter som Kristus tillmätte honom sin gåva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Därför heter det: »Han for upp i höjden, han tog fångar, han gav människorna gåvor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Men detta ord »han for upp», vad innebär det, om icke att han förut hade farit hit ned till jordens lägre rymder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Den som for ned, han är ock den som for upp över alla himlar, för att han skulle uppfylla allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Och han gav oss somliga till apostlar, somliga till profeter, somliga till evangelister, somliga till herdar och lärare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'Ty han ville göra de heliga skickliga till att utföra sitt tjänarvärv, att uppbygga Kristi kropp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'till dess att vi allasammans komma fram till enheten i tron och i kunskapen om Guds Son, till manlig mognad, och så bliva fullvuxna, intill Kristi fullhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'Så skulle vi icke mer vara barn, icke såsom havets vågor drivas omkring av vart vindkast i läran, vid människornas bedrägliga spel, när de illfundigt söka främja villfarelsens listiga anslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Nej, vi skulle då hålla oss till sanningen, och i alla stycken i kärlek växa upp till honom som är huvudet, Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'Ty från honom hämtar hela kroppen sin tillväxt, till att bliva uppbyggd i kärlek, i det att den sammanslutes och får sammanhållning genom det bistånd var led giver, med en kraft som är avmätt efter var särskild dels uppgift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Jag tillsäger eder alltså och uppmanar eder allvarligt i Herren, att icke mer vandra såsom hedningarna i sitt sinnes fåfänglighet vandra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 18, 'hedningarna, vilka, i följd av den okunnighet som råder hos dem genom deras hjärtans förstockelse, äro förmörkade till förståndet och bortkomna från det liv som är av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 19, 'Ty i sin försoffning hava de överlämnat sig åt lösaktighet, så att de i girighet bedriva alla slags orena gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 20, 'Men I haven icke fått en sådan undervisning om Kristus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 21, 'om I eljest så haven hört om honom och så blivit lärda i honom, som sanning är i Jesus:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 22, 'att I -- då detta nu krävdes på grund av eder förra vandel -- haven avlagt den gamla människan, som fördärvar sig genom att följa sina begärelsers bedrägliga lockelser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 23, 'och nu förnyens genom Anden som bor i edert sinne,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 24, 'och att I haven iklätt eder den nya människan, som är skapad till likhet med Gud i sanningens rättfärdighet och helighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 25, 'Läggen därför bort lögnen, och talen sanning med varandra, eftersom vi äro varandras lemmar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 26, '»Vredgens, men synden icke»; låten icke solen gå ned över eder vrede,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 27, 'och given icke djävulen något tillfälle.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 28, 'Den som har stulit, han stjäle icke mer, utan arbete hellre, och uträtte med sina händer vad gott är, så att han har något varav han kan dela med sig åt den som lider brist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 29, 'Låten intet ohöviskt tal utgå ur eder mun, utan allenast det som är gott, till uppbyggelse, där sådan behöves, så att det bliver till välsignelse för dem som höra det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 30, 'Och bedröven icke Guds helige Ande, vilken I haven undfått såsom ett insegel, för förlossningens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 31, 'All bitterhet och häftighet och vrede, allt skriande och smädande, ja, allt vad ondska heter vare fjärran ifrån eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 32, 'Varen i stället goda och barmhärtiga mot varandra, och förlåten varandra, såsom Gud i Kristus har förlåtit eder. [1] Ord markerade med denna fotnot är skrivna i kursiv stil i den tryckta upplagan. --Red för den elektroniska upplagan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Bliven alltså Guds efterföljare, såsom hans älskade barn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'och vandren i kärlek, såsom Kristus älskade eder och utgav sig själv för oss till en gåva och ett offer, »Gud till en välbehaglig lukt».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Men otukt och orenhet, av vad slag det vara må, och girighet skolen I, såsom det anstår heliga, icke ens låta nämnas bland eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'ej heller ohöviskt väsende och dåraktigt tal och gyckel; sådant är otillbörligt. Låten fastmer tacksägelse höras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Ty det bören I veta, och det insen I också själva, att ingen otuktig eller oren människa har arvedel i Kristi och Guds rike, ej heller någon girig, ty en sådan är en avgudadyrkare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Låten ingen bedraga eder med tomma ord; ty för sådana synder kommer Guds vrede över de ohörsamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Haven alltså ingen del i sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'I voren ju förut mörker, men nu ären I ljus i Herren; vandren då såsom ljusets barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Ty ljusets frukt består i allt vad godhet och rättfärdighet och sanning är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Ja, vandren så, i det att I pröven vad som är välbehagligt för Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Och haven ingen delaktighet i mörkrets gärningar, som icke giva någon frukt, utan avslöjen dem fastmer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Vad av sådana människor i hemlighet förövas, därom är det skamligt till och med att tala;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'men alltsammans bliver uppenbart, när det avslöjas genom ljuset. Ty varhelst något bliver uppenbart, där är ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Därför heter det: »Vakna upp, du som sover, och stå upp ifrån de döda, så skall Kristus lysa fram för dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'Sen därför noga till, huru I vandren: att I vandren icke såsom ovisa människor, utan såsom visa;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'och tagen väl i akt vart lägligt tillfälle. Ty tiden är ond.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Varen alltså icke oförståndiga, utan förstån vad som är Herrens vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Och dricken eder icke druckna av vin; ty därav kommer ett oskickligt leverne. Låten eder fastmer uppfyllas av ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'och talen till varandra i psalmer och lovsånger och andliga visor, och sjungen och spelen till Herrens ära i edra hjärtan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'och tacken alltid Gud och Fadern för allt, i vår Herres, Jesu Kristi, namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 21, 'Underordnen eder varandra i Kristi fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 22, 'I hustrur, underordnen eder edra män, såsom I underordnen eder Herren;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 23, 'ty en man är sin hustrus huvud, såsom Kristus är församlingens huvud, han som ock är denna sin kropps Frälsare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 24, 'Ja, såsom församlingen underordnar sig Kristus, så skola ock hustrurna i allt underordna sig sina män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 25, 'I män, älsken edra hustrur, såsom Kristus har älskat församlingen och utgivit sig själv för henne');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 26, 'till att helga henne, genom att rena henne medelst vattnets bad, i kraft av ordet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 27, 'Ty så ville han själv ställa fram församlingen inför sig i härlighet, utan fläck och skrynka och annat sådant; fastmer skulle hon vara helig och ostrafflig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 28, 'På samma sätt äro männen pliktiga att älska sina hustrur, då dessa ju äro deras egna kroppar; den som älskar sin hustru, han älskar sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 29, 'Ingen har någonsin hatat sitt eget kött; i stället när och omhuldar man det, såsom Kristus gör med församlingen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 30, 'eftersom vi äro lemmar av hans kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 31, '»Fördenskull skall en man övergiva sin fader och sin moder och hålla sig till sin hustru, och de tu skola varda ett kött.» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 32, 'Den hemlighet som ligger häri är stor; jag säger detta med tanke på Kristus och församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 33, 'Dock gäller också om eder att var och en skall älska sin hustru såsom sig själv; men hustrun å sin sida skall visa sin man vördnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'I barn, varen edra föräldrar lydiga i Herren, ty detta är rätt och tillbörligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, '»Hedra din fader och din moder.» Det är ju först detta bud som har ett löfte med sig:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, '»för att det må gå dig väl och du må länge leva på jorden».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Och I fäder, reten icke edra barn till vrede, utan fostren dem i Herrens tukt och förmaning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'I tjänare, varen edra jordiska herrar lydiga, med fruktan och bävan, av uppriktigt hjärta, såsom gällde det Kristus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'icke med ögontjänst, av begär att behaga människor, utan såsom Kristi tjänare, som av hjärtat göra Guds vilja;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'och gören eder tjänst med villighet, såsom tjänaden I Herren och icke människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'I veten ju att vad gott var och en gör, det skall han få igen av Herren, vare sig han är träl eller fri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Och I herrar, handlen på samma sätt mot dem, och upphören att bruka hårda ord; I veten ju att i himmelen finnes den som är Herre över både dem och eder, och att hos honom icke finnes anseende till personen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'För övrigt, bliven allt starkare i Herren och i hans väldiga kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Ikläden eder hela Guds vapenrustning, så att I kunnen hålla stånd emot djävulens listiga angrepp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Ty den kamp vi hava att utkämpa är en kamp icke mot kött och blod, utan mot furstar och väldigheter och världshärskare, som råda här i mörkret, mot ondskans andemakter i himlarymderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Tagen alltså på eder hela Guds vapenrustning, så att I kunnen stå emot på den onda dagen och, sedan I haven fullgjort allt, behålla fältet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Stån därför omgjordade kring edra länder med sanningen, och »varen iklädda rättfärdighetens pansar»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'och haven såsom skor på edra fötter den beredvillighet som fridens evangelium giver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Och tagen alltid trons sköld, varmed I skolen kunna utsläcka den ondes alla brinnande pilar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Och låten giva eder »frälsningens hjälm» och Andens svärd, som är Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 18, 'Gören detta under ständig åkallan och bön, så att I alltjämt bedjen i Anden och fördenskull vaken, under ständig uthållighet och ständig bön för alla de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 19, 'Bedjen ock för mig, att min mun må upplåtas, och att det jag skall tala må bliva mig givet, så att jag frimodigt kungör evangelii hemlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 20, 'för vars skull jag är ett sändebud i kedjor; ja, bedjen att jag må frimodigt tala därom med de rätta orden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 21, 'Men för att ock I skolen få veta något om mig, huru det går mig, kommer Tykikus, min älskade broder och trogne tjänare i Herren, att underrätta eder om allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 22, 'Honom sänder jag till eder, just för att I skolen få veta huru det är med oss, och för att han skall hugna edra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 23, 'Frid vare med bröderna och kärlek tillika med tro, från Gud, Fadern, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 24, 'Nåd vare med alla som älska vår Herre Jesus Kristus -- nåd i oförgängligt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Paulus och Timoteus, Kristi Jesu tjänare, hälsa alla de heliga i Kristus Jesus som bo i Filippi, tillika med församlingsföreståndare och församlingstjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Jag tackar min Gud, så ofta jag tänker på eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'i det jag alltid i alla mina böner med glädje beder för eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'Jag tackar honom för att I, allt ifrån första dagen intill nu, haven deltagit i arbetet för evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'Och jag har den tillförsikten, att han som i eder har begynt ett gott verk, han skall ock fullborda det, intill Kristi Jesu dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'Och det är ju rätt och tillbörligt att jag tänker så om eder alla, eftersom jag, både när jag ligger i bojor, och när jag försvarar och befäster evangelium, har eder i mitt hjärta såsom alla med mig delaktiga i nåden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'Ty Gud är mitt vittne, han vet huru jag längtar efter eder alla med Kristi Jesu kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'Och därom beder jag, att eder kärlek må allt mer och mer överflöda av kunskap och förstånd i allt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'så att I kunnen döma om vad rättast är, på det att I mån bliva rena och för ingen till stötesten, i väntan på Kristi dag,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'och bliva rika på rättfärdighetens frukt, vilken kommer genom Jesus Kristus, Gud till ära och pris.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'Jag vill att I, mina bröder, skolen veta att det som har vederfarits mig snarare har länt till evangelii framgång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'Det har nämligen så blivit uppenbart för alla i pretoriet och för alla andra, att det är i Kristus som jag bär mina bojor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'och de flesta av bröderna hava genom mina bojor blivit så frimodiga i Herren, att de med allt större dristighet våga oförskräckt förkunna Guds ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'Somliga finnas väl ock, som av avund och trätlystnad predika Kristus, men det finnes också andra som göra det av god vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'Dessa senare göra det av kärlek, eftersom de veta att jag är satt till att försvara evangelium.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'De förra åter förkunna Kristus av genstridighet, icke med rent sinne, i tanke att de skola tillskynda mig ytterligare bedrövelse i mina bojor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Vad mer? Kristus bliver dock på ena eller andra sättet förkunnad, det må nu ske för syns skull eller i uppriktighet; och däröver gläder jag mig. Ja, jag skall ock framgent få glädja mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'ty jag vet att detta skall lända mig till frälsning, genom eder förbön och därigenom att Jesu Kristi Ande förlänas mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'Det är nämligen min trängtan och mitt hopp att jag i intet skall komma på skam, utan att Kristus, nu såsom alltid, skall av mig med all frimodighet bliva förhärligad i min kropp, det må ske genom liv eller genom död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'Ty att leva, det är för mig Kristus, och att dö, det är för mig en vinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'Men om det att leva i köttet för mig är att utföra ett arbete som bär frukt, vilketdera skall jag då välja? Det kan jag icke säga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'Jag drages åt båda hållen. Ty väl åstundar jag att bryta upp och vara hos Kristus, vilket ju vore mycket bättre;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'men att jag lever kvar i köttet är för eder skull mer av nöden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'Och då jag är förvissad härom, vet jag att jag skall leva kvar och förbliva hos eder alla, eder till förkovran och glädje i tron,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 26, 'för att eder berömmelse skall överflöda i Kristus Jesus, i fråga om mig, därigenom att jag ännu en gång kommer till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 27, 'Fören allenast en sådan vandel som är värdig Kristi evangelium, så att jag -- vare sig jag kommer och besöker eder, eller jag förbliver frånvarande -- får höra om eder att I stån fasta i en och samme Ande och endräktigt kämpen tillsammans för tron på evangelium,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 28, 'utan att i något stycke låta skrämma eder av motståndarna. Ty att I så skicken eder är för dem ett vittnesbörd om att de själva gå mot fördärvet, men att I skolen bliva frälsta, och detta av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 29, 'Åt eder har ju förunnats icke allenast att tro på Kristus, utan ock att lida för hans skull,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 30, 'i det att I haven samma kamp som I förr sågen mig hava och nu hören att jag har.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Om nu förmaning i Kristus, om uppmuntran i kärlek, om gemenskap i Anden, om hjärtlig godhet och barmhärtighet betyda något,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'gören då min glädje fullkomlig, i det att I ären ens till sinnes, uppfyllda av samma kärlek, endräktiga, liksinnade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'fria ifrån genstridighet och ifrån begär efter fåfänglig ära. Fasthellre må var och en i ödmjukhet akta den andre förmer än sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'Och sen icke var och en på sitt eget bästa, utan var och en också på andras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'Varen så till sinnes som Kristus Jesus var[1],');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'han som var till i Guds-skepnad, men icke räknade jämlikheten med Gud såsom ett byte,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'utan utblottade sig själv, i det han antog tjänare-skepnad, när han kom i människogestalt. Så befanns han i utvärtes måtto vara såsom en människa');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'och ödmjukade sig och blev lydig intill döden, ja, intill döden på korset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'Därför har ock Gud upphöjt honom över allting och givit honom det namn som är över alla namn');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'för att i Jesu namn alla knän skola böja sig, deras som äro i himmelen, och deras som äro på jorden, och deras som äro under jorden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'och för att alla tungor skola bekänna, Gud, Fadern, till ära, att Jesus Kristus är Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'Därför, mina älskade, såsom I alltid förut haven varit lydiga, så mån I också nu med fruktan och bävan arbeta på eder frälsning, och det icke allenast såsom I gjorden, då jag var närvarande, utan ännu mycket mer nu, då jag är frånvarande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'Ty Gud är den som verkar i eder både vilja och gärning, för att hans goda vilja skall ske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'Gören allt utan att knorra och tveka,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'så att I bliven otadliga och rena, Guds ostraffliga barn mitt ibland »ett vrångt och avogt släkte», inom vilket I lysen såsom himlaljus i världen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'i det att I hållen fast vid livets ord. Bliven mig så till berömmelse på Kristi dag, till ett vittnesbörd om att jag icke har strävat förgäves och icke förgäves har arbetat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'Men om än mitt blod bliver utgjutet såsom ett drickoffer, när jag förrättar min tempeltjänst och därvid frambär offret av eder tro, så gläder jag mig dock och deltager i allas eder glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'Sammalunda mån ock I glädjas och deltaga i min glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'Jag hoppas nu i Herren Jesus att snart kunna sända Timoteus till eder, så att ock jag får känna hugnad genom det som jag då hör om eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'Ty jag har ingen av samma sinne som han, ingen som av så uppriktigt hjärta kommer att hava omsorg om eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'Allasammans söka de sitt eget, icke vad som hör Kristus Jesus till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'Men hans beprövade trohet kännen I; I veten huru han med mig har verkat i evangelii tjänst, såsom en son tjänar sin fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 23, 'Honom hoppas jag alltså kunna sända, så snart jag har fått se huru det går med min sak.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 24, 'Och i Herren är jag viss om att jag också själv snart skall få komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 25, 'Emellertid har jag funnit det nödvändigt att sända brodern Epafroditus, min medarbetare och medkämpe, tillbaka till eder, honom som I haven skickat hit, för att å edra vägnar överlämna åt mig vad jag kunde behöva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 26, 'Ty han längtar efter eder alla och har ingen ro, därför att I haven hört honom vara sjuk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 27, 'Han har också verkligen varit sjuk, ja, nära döden, men Gud förbarmade sig över honom; och icke allenast över honom, utan också över mig, för att jag icke skulle få bedrövelse på bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 28, 'Därför är jag så mycket mer angelägen att sända honom, både för att I skolen få glädjen att återse honom, och för att jag själv därigenom skall få lättnad i min bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 29, 'Tagen alltså emot honom i Herren, med all glädje, och hållen sådana män i ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 30, 'Ty för Kristi verks skull var han nära döden, i det han satte sitt liv på spel, för att giva mig ersättning för den tjänst som jag måste sakna från eder personligen. [1] Eller: Haven i edert förhållande till varandra samma sinne som I haven i Kristus Jesus, vilken var till osv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'För övrigt, mina bröder, glädjen eder i Herren. Att skriva till eder detsamma som förut, det räknar jag icke för något besvär, och det är för eder tryggare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'Given akt på de hundarna, given akt på de onda arbetarna, given akt på »de sönderskurna».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'Ty vi äro »de omskurna», vi som genom Guds Ande tjäna Gud och berömma oss av Kristus Jesus och icke förtrösta på köttet --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'fastän jag för min del väl också kunde hava skäl att förtrösta på köttet. Ja, om någon menar sig kunna förtrösta på köttet, så kan jag det ännu mer,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'jag som blev omskuren, när jag var åtta dagar gammal, jag som är av Israels folk och av Benjamins stam, en hebré, född av hebréer, jag som i fråga om lagen har varit en farisé,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'i fråga om nitälskan varit en församlingens förföljare, i fråga om rättfärdighet -- den som vinnes i kraft av lagen -- varit en ostrafflig man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Men allt det som var mig en vinning, det har jag för Kristi skull räknat såsom en förlust.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'Ja, jag räknar i sanning allt såsom förlust mot det som är långt mer värt: kunskapen om Kristus Jesus, min Herre. Ty det är för hans skull som jag har gått förlustig alltsammans och nu räknar det såsom avskräde, på det att jag må vinna Kristus');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'och bliva funnen i honom, icke med min egen rättfärdighet, den som kommer av lag, utan med den rättfärdighet som kommer genom tro på Kristus, rättfärdigheten av Gud, på grund av tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'Ty jag vill lära känna honom och hans uppståndelses kraft och få känna delaktighet i hans lidanden, i det jag bliver honom lik genom en död sådan som hans,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'om jag så skulle kunna nå fram till uppståndelsen från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'Icke som om jag redan hade vunnit det eller redan hade blivit fullkomlig, men jag far efter att vinna det, eftersom jag själv har blivit vunnen av Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Ja, mina bröder, jag håller icke före att jag ännu har vunnit det, men ett gör jag: jag förgäter det som är bakom mig och sträcker mig mot det som är framför mig');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'och jagar mot målet, för att få den segerlön som hålles framför oss genom Guds kallelse ovanifrån, i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Må därför vi alla som äro »fullkomliga» hava ett sådant tänkesätt. Men om så är, att I i något stycke haven andra tankar, så skall Gud också däröver giva eder klarhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'Dock, såvitt vi redan hava hunnit något framåt, så låtom oss vandra vidare på samma väg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Mina bröder, varen ock I mina efterföljare, och sen på dem som vandra på samma sätt som jag, eftersom I ju haven oss till föredöme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Ty det är såsom jag ofta har sagt eder och nu åter måste säga under tårar: många vandra såsom fiender till Kristi kors,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'och deras ände är fördärv; de hava buken till sin Gud och söka sin ära i det som är deras skam, och deras sinne är vänt till det som hör jorden till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, 'Vi åter hava vårt medborgarskap i himmelen, och därifrån vänta vi ock Herren Jesus Kristus såsom Frälsare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'vilken skall så förvandla vår förnedringskropp, att den bliver lik hans härlighetskropp -- genom den kraft varmed han ock kan underlägga sig allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, 'Därför, mina älskade och efterlängtade bröder, min glädje och min krona, stån fasta i Herren med detta sinne, I mina älskade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'Evodia förmanar jag, och Syntyke förmanar jag att de skola vara ens till sinnes i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'Ja, också till dig, min Synsygus -- du som med rätta bär det namnet[1] -- har jag en bön: Var dessa kvinnor till hjälp, ty jämte mig hava de kämpat i evangelii tjänst, de såväl som Klemens och mina andra medarbetare, vilkas namn äro skrivna i livets bok.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'Glädjen eder i Herren alltid. Åter vill jag säga: Glädjen eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'Låten edert saktmod bliva kunnigt för alla människor. Herren är nära!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'Gören eder intet bekymmer, utan låten i allting edra önskningar bliva kunniga inför Gud, genom åkallan och bön, med tacksägelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, 'Så skall Guds frid, som övergår allt förstånd, bevara edra hjärtan och edra tankar, i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'För övrigt, mina bröder, vad sant är, vad värdigt, vad rätt, vad rent är, vad som är älskligt och värt att akta, ja, allt vad dygd heter, och allt som förtjänar att prisas -- tänken på allt sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'Detta, som I haven lärt och inhämtat och haven hört av mig och sett hos mig, det skolen I göra; och så skall fridens Gud vara med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Det har varit för mig en stor glädje i Herren att I nu omsider haven kommit i en så god ställning, att I haven kunnat tänka på mitt bästa. Dock, I tänkten nog också förut därpå, men I haden icke tillfälle att göra något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Icke som om jag härmed ville säga att något har fattats mig; ty jag har lärt mig att vara nöjd med de omständigheter i vilka jag är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'Jag vet att finna mig i ringhet, jag vet ock att finna mig i överflöd. Med vilken ställning och vilka förhållanden som helst är jag förtrogen: jag kan vara mätt, och jag kan vara hungrig; jag kan hava överflöd, och jag kan lida brist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'Allt förmår jag i honom som giver mig kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'Dock gjorden I väl däri att I visaden mig deltagande i mitt betryck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'I veten ju ock själva, I filipper, att under evangelii första tid, då när jag hade dragit bort ifrån Macedonien, ingen annan församling än eder trädde i sådan förbindelse med mig, att räkning kunde föras över »utgivet och mottaget».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'Ty medan jag ännu var i Tessalonika, sänden I mig både en och två gånger vad jag behövde. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, 'Icke som om jag skulle åstunda själva gåvan; nej, vad jag åstundar är en sådan frukt därav, som rikligen kommer eder själva till godo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'Jag har nu fått ut allt, och det i överflödande mått. Jag har fullt upp, sedan jag av Epafroditus har mottagit eder gåva, »en välbehaglig lukt», ett offer som täckes Gud och behagar honom väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'Så skall ock min Gud, efter sin rikedom, i fullt mått och på ett härligt sätt i Kristus Jesus giva eder allt vad I behöven.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 20, 'Men vår Gud och Fader tillhör äran i evigheternas evigheter. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 21, 'Hälsen var och en av de heliga i Kristus Jesus. De bröder som äro här hos mig hälsa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 22, 'Alla de heliga hälsa eder, först och främst de som höra till kejsarens hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 23, 'Herrens, Jesu Kristi, nåd vare med eder ande. [1] Synsygus betyder medhjälpare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Paulus, genom Guds vilja Kristi Jesu apostel, så ock brodern Timoteus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'hälsar de heliga som bo i Kolosse, de troende bröderna i Kristus. Nåd vare med eder och frid ifrån Gud, vår Fader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Vi tacka Gud, vår Herres, Jesu Kristi, Fader, alltid för eder i våra böner,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'ty vi hava hört om eder tro i Kristus Jesus och om den kärlek som I haven till alla de heliga;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'vi tacka honom för det hopps skull, som är förvarat åt eder i himmelen. Om detta hopp haven I redan förut fått höra, genom sanningens ord i det evangelium');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'som har kommit till eder, likasom det ock är att finna överallt i världen och där bär frukt och växer till, på samma sätt som det har gjort bland eder, allt ifrån den dag, då I hörden det och lärden i sanning känna Guds nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'Det var ju en sådan undervisning I mottogen av Epafras, vår älskade medtjänare, som i vårt ställe är eder en trogen Kristi tjänare;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'det är också han som för oss har omtalat eder kärlek i Anden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'Allt ifrån den dag då vi fingo höra härom, hava vi därför, å vår sida, icke upphört att bedja för eder och bönfalla om att I mån bliva uppfyllda av kunskap om Guds vilja, i allt slags andlig vishet och andligt förstånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'Så skolen I kunna föra en vandel som är värdig Herren, honom i allt till behag, och genom kunskapen om Gud bära frukt och växa till i allt gott verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'Och genom hans härliga makt skolen I på allt sätt uppfyllas av kraft till att bevisa ståndaktighet och tålamod i allt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'och I skolen med glädje tacka Fadern, som har gjort eder skickliga till delaktighet i den arvslott som de heliga hava i ljuset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'Ty han har frälst oss från mörkrets välde och försatt oss i sin älskade Sons rike.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'I honom hava vi förlossningen, förlåtelsen för våra synder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'i honom som är den osynlige Gudens avbild och förstfödd före allt skapat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Ty i honom skapades allt i himmelen och på jorden, synligt såväl som osynligt, både tronänglar och herrar och furstar och väldigheter i andevärlden. Alltsammans har blivit skapat genom honom och till honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Ja, han är till före allt annat, och alltsammans äger bestånd i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Och han är huvudet för kroppen, det är församlingen, han som är begynnelsen, den förstfödde ifrån de döda. Så skulle han i allt vara den främste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Ty det behagade Gud att låta all fullhet taga sin boning i honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'och att genom honom försona allt med sig, sedan han genom blodet på hans kors hade berett frid. Ja, genom honom skulle så ske med allt vad på jorden och i himmelen är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'Också åt eder, som förut voren bortkomna från honom och genom edert sinnelag hans fiender, i det att I gjorden vad ont var,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 22, 'också åt eder har han nu skaffat försoning i hans jordiska kropp, genom hans död, för att kunna ställa eder fram inför sig heliga och obefläckade och ostraffliga --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 23, 'om I nämligen förbliven i tron, väl grundade och fasta, utan att låta rubba eder från det hopp som tillbjudes oss i evangelium, det evangelium som I haven hört, och som blivit predikat bland allt skapat under himmelen, det vars tjänare jag, Paulus, har blivit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 24, 'Nu gläder jag mig mitt i mina lidanden för eder; och vad som fattas i det mått av Kristus-bedrövelser som jag i mitt kött måste utstå, det uppfyller jag nu för hans kropp, som är församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 25, 'Ty dennas tjänare har jag blivit, i enlighet med det uppdrag av Gud, som har blivit mig givet, att jag nämligen överallt skall för eder förkunna Guds ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 26, 'den hemlighet som tidsåldrar och släkten igenom hade varit fördold, men som nu har blivit uppenbarad för hans heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 27, 'Ty för dem ville Gud kungöra huru rik på härlighet den är bland hedningarna, denna hemlighet, vilken är »Kristus i eder, vårt härlighetshopp».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 28, 'Och honom förkunna vi för vår del, i det vi förmana var människa och undervisa var människa med all vishet, för att kunna ställa fram var människa såsom fullkomlig i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 29, 'Och för det målet arbetar och kämpar jag, i enlighet med hans kraft, som mäktigt verkar i mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Jag vill nämligen, att I skolen veta, vilken kamp jag har att utstå för eder och för församlingen i Laodicea och för alla de andra som icke personligen hava sett mitt ansikte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'Ty jag önskar, att deras hjärtan skola få hugnad, därigenom att de slutas tillsammans i kärlek och komma till en full förståndsvisshets hela rikedom, till en rätt kunskap om Guds hemlighet, vilken är Kristus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'ty i honom finnas visdomens och kunskapens alla skatter fördolda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Detta säger jag, för att ingen skall bedraga eder med skenfagert tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Ty om jag ock till kroppen är frånvarande, så är jag dock i anden hos eder och gläder mig, när jag ser den ordning, som råder bland eder, och när jag ser fastheten i eder tro på Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'Såsom I nu haven mottagit Kristus Jesus, Herren, så vandren i honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'och varen rotade i honom och låten eder uppbyggas i honom och befästas i tron, i enlighet med den undervisning I haven fått, och överflöden i tacksägelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'Sen till, att ingen får bortföra eder såsom ett segerbyte genom sin tomma och bedrägliga »vishetslära», i det att han åberopar fäderneärvda människomeningar och håller sig till världens »makter»[1] och icke till Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Ty i honom bor gudomens hela fullhet lekamligen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'och i honom haven I blivit delaktiga av den fullheten, i honom som är huvudet för alla andevärldens furstar och väldigheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'I honom haven I ock blivit omskurna genom en omskärelse, som icke skedde med händer, en som bestod däri att I bleven avklädda eder köttsliga kropp; jag menar omskärelsen i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'I haven ju med honom blivit begravna i dopet; I haven ock i dopet blivit uppväckta med honom, genom tron på Guds kraft, hans som uppväckte honom från de döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'Ja, också eder som voren döda genom edra synder och genom edert kötts oomskurenhet, också eder har han gjort levande med honom; ty han har förlåtit oss alla våra synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'Han har nämligen utplånat den handskrift som genom sina stadgar anklagade oss och låg oss i vägen; den har han skaffat undan genom att nagla den fast vid korset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Han har avväpnat andevärldens furstar och väldigheter och låtit dem bliva till skam inför alla, i det att han i honom har triumferat över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'Låten därför ingen döma eder i fråga om mat och dryck eller angående högtid eller nymånad eller sabbat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'Sådant är allenast en skuggbild av vad som skulla komma, men verkligheten själv finnes hos Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Låten icke segerlönen tagas ifrån eder av någon som har sin lust i »ödmjukhet» och ängladyrkan och gör sig stor med sina syner, någon som utan orsak är uppblåst genom sitt köttsliga sinne');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'och icke håller sig till honom som är huvudet, honom från vilken hela kroppen vinner sin tillväxt i Gud, i det att den av sina ledgångar och senor får bistånd och sammanhållning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Om I nu haven dött med Kristus och så blivit frigjorda ifrån världens »makter», varför låten I då allahanda stadgar läggas på eder, likasom levden I ännu i världen:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, '»Det skall du icke taga i», »Det skall du icke smaka», »Det skall du icke komma vid»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'och detta när det gäller ting, som alla äro bestämda till att gå under genom förbrukning -- allt till åtlydnad av människobud och människoläror?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 23, 'Visserligen har allt detta fått namn om sig att vara »vishet», eftersom däri ligger ett självvalt gudstjänstväsende och ett slags »ödmjukhet» och en kroppens späkning; men ingalunda ligger däri »en viss heder», det tjänar allenast till att nära det köttsliga sinnet. [1] Se Makter i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Om I alltså ären uppståndna med Kristus, så söken det som är därovan, där varest Kristus är och sitter på Guds högra sida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'Ja, haven edert sinne vänt till det som är därovan, icke till det som är på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Ty I haven dött, och edert liv är fördolt med Kristus i Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'När Kristus, han som är vårt liv, bliver uppenbarad, då skolen ock I med honom bliva uppenbarade i härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'Så döden nu edra lemmar, som höra jorden till: otukt, orenhet, lusta, ond begärelse, så ock girigheten, som ju är avgudadyrkan;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'ty för sådant kommer Guds vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'I de synderna vandraden också I förut, då I ännu haden edert liv i dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Men nu skolen också I lägga bort alltsammans; vrede, häftighet, ondska, smädelse och skamligt tal ur eder mun;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'I skolen icke ljuga på varandra. I haven ju avklätt eder den gamla människan med hennes gärningar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'och iklätt eder den nya, den som förnyas till sann kunskap och så bliver en avbild av honom som har skapat henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Och därvid kommer det icke an på om någon är grek eller jude, omskuren eller oomskuren, barbar eller skyt, träl eller fri; nej, Kristus är allt och i alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'Så kläden eder nu såsom Guds utvalda, hans heliga och älskade, i hjärtlig barmhärtighet, godhet, ödmjukhet, saktmod, tålamod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Och haven fördrag med varandra och förlåten varandra, om någon har något att förebrå en annan. Såsom Herren har förlåtit eder, så skolen ock I förlåta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Men över allt detta skolen I ikläda eder kärleken, ty den är fullkomlighetens sammanhållande band.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'Och låten Kristi frid regera i edra hjärtan; ty till att äga den ären I ock kallade såsom lemmar i en och samma kropp. Och varen tacksamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Låten Kristi ord rikligen bo ibland eder; undervisen och förmanen varandra i all vishet, med psalmer och lovsånger och andliga visor, och sjungen med tacksägelse till Guds ära i edra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Och allt, vadhelst I företagen eder i ord eller gärning, gören det allt i Herren Jesu namn och tacken Gud, Fadern, genom honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'I hustrur, underordnen eder edra män, såsom tillbörligt är i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 19, 'I män, älsken edra hustrur och varen icke bittra mot dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 20, 'I barn, varen edra föräldrar lydiga i allt, ty detta är välbehagligt i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 21, 'I fäder, reten icke edra barn, på det att de icke må bliva klenmodiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 22, 'I tjänare, varen i allt edra jordiska herrar lydiga, icke med ögontjänst, av begär att behaga människor, utan av uppriktigt hjärta, i Herrens fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 23, 'Vadhelst I gören, gören det av hjärtat, såsom tjänaden I Herren och icke människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 24, 'I veten ju, att I till vedergällning skolen av Herren få eder arvedel; den herre I tjänen är Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 25, 'Den som gör orätt, han skall få igen den orätt han har gjort, utan anseende till personen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'I herrar, given edra tjänare, vad rätt och billigt är; I veten ju, att också I haven en herre i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, 'Varen uthålliga i bönen och vaken i den under tacksägelse. 3; Och bedjen jämväl för oss, att Gud må åt oss öppna en dörr för ordet, så att vi få förkunna Kristi hemlighet, den hemlighet, för vars skull jag också är en fånge;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, '');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, 'ja, bedjen, att jag må uppenbara den med de rätta orden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'Skicken eder visligt mot dem som stå utanför och tagen väl i akt vart lägligt tillfälle.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Edert tal vare alltid välbehagligt, kryddat med salt; I bören förstå, huru I skolen svara var och en.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Om allt vad mig angår skall min älskade broder Tykikus, min trogne tjänare och min medtjänare i Herren, underrätta eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, 'Honom sänder jag till eder, just för att I skolen få veta, huru det är med oss, och för att han skall hugna edra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'Tillika sänder jag Onesimus, min trogne och älskade broder, eder landsman. De skola underrätta eder om allting här.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, 'Aristarkus, min medfånge, hälsar eder; så gör ock Markus, Barnabas syskonbarn. Angående honom haven I redan fått föreskrifter; och om han kommer till eder, så tagen vänligt emot honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'Också Jesus, som kallas Justus, hälsar eder. Av de omskurna äro dessa mina enda medarbetare för Guds rike, och de hava varit mig till hugnad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Epafras, eder landsman, hälsar eder, en Kristi Jesu tjänare, som i sina böner alltid kämpar för eder, för att I skolen stå fasta och vara fullkomliga och fullt vissa i allt som är Guds vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'Ty jag giver honom det vittnesbördet, att han har stor möda för eder likasom ock för dem som bo i Laodicea och i Hierapolis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Lukas, läkaren, den älskade brodern, hälsar eder; så gör ock Demas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, 'Hälsen bröderna i Laodicea, så ock Nymfas tillika med den församling som kommer tillhopa i hans hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'Sedan detta brev har blivit uppläst hos eder, så sörjen för att det ock bliver uppläst i laodicéernas församling och att jämväl I fån läsa det brev, som kommer från Laodicea.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 17, 'Sägen ock detta till Arkippus: »Hav akt på det ämbete, som du har undfått i Herren, så att du fullgör, vad därtill hör.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 18, 'Här skriver jag, Paulus, min hälsning med egen hand. Tänken på mina bojor. Nåd vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Paulus och Silvanus och Timoteus hälsa tessalonikernas församling i Gud, Fadern, och Herren Jesus Kristus. Nåd och frid[1] vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'Vi tacka Gud alltid för eder alla, när vi tänka på eder i våra böner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'Ty oavlåtligen ihågkomma vi inför vår Gud och Fader edra gärningar i tron och edert arbete i kärleken och eder ståndaktighet i hoppet, i vår Herre Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'Vi veta ju, käre bröder, i Guds älskade, huru det var, när I bleven utvalda:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'vårt evangelium kom till eder icke med ord allenast, utan i kraft och helig ande och med full visshet. I veten ock på vad sätt vi uppträdde bland eder, till edert bästa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'Och I å eder sida bleven våra efterföljare och därmed Herrens, i det att I, mitt under stort betryck, togen emot ordet med glädje i helig ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'Så bleven I själva ett föredöme för alla de troende i Macedonien och Akaja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Ty från eder har genljudet av Herrens ord gått vidare ut; icke allenast i Macedonien och Akaja, utan allestädes har eder tro på Gud blivit känd, så att vi för vår del icke behöva tala något därom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Ty själva förkunna de om oss, med vilken framgång vi begynte vårt arbete hos eder, och huru I från avgudarna omvänden eder till Gud, till att tjäna den levande och sanne Guden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'och till att vänta hans Son från himmelen, honom som han har uppväckt från de döda, Jesus, som frälsar oss undan den kommande vredesdomen. [1] av Gud, vår Fader, och Herren Jesu Kristus');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'I veten ju själva, käre bröder, att det icke var utan kraft vi begynte vårt arbete hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'Nej, fastän vi, såsom i veten, i Filippi förut hade fått utstå lidande och misshandling, hade vi dock frimodighet i vår Gud till att förkunna för eder Guds evangelium, under mycken kamp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'Ty vad vi tala till tröst och förmaning, det har icke sin grund i villfarelse eller i orent uppsåt, ej heller sker det med svek;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'utan därför att vi av Gud hava prövats värdiga att få evangelium oss betrott, tala vi i enlighet därmed, icke för att vara människor till behag, utan för att vara Gud till behag, honom som prövar våra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Aldrig någonsin hava vi uppträtt med smickrets ord, det veten I, ej heller så, att vi skulle få en förevändning att bereda oss vinning -- Gud är vårt vittne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Ej heller hava vi sökt pris av människor, vare sig av eder eller av andra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'fastän vi såsom Kristi apostlar väl hade kunnat uppträda med myndighet. Tvärtom hava vi visat oss milda bland eder, såsom när en moder omhuldar sina späda barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'I sådan ömhet om eder ville vi gärna icke allenast göra också eder delaktiga av Guds evangelium, utan till och med offra våra liv för eder, ty I haden blivit oss kära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'I kommen ju ihåg, käre bröder, vårt arbete och vår möda, huru vi, under det att vi predikade för eder Guds evangelium, strävade natt och dag, för att icke bliva någon av eder till tunga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'I själva ären våra vittnen, och Gud är vårt vittne, I veten, och han vet huru heligt och rättfärdigt och ostraffligt vi förhöllo oss mot eder, I som tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'Likaledes veten I huru vi förmanade och uppmuntrade var och en av eder, såsom en fader sina barn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'och huru vi uppfordrade eder att föra en vandel som vore värdig Gud, honom som kallar eder till sitt rike och sin härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Därför tacka vi ock oavlåtligen Gud för att I, när I undfingen det Guds ord som vi predikade, icke mottogen det såsom människoord, utan såsom Guds ord, vilket det förvisso är, ett ord som ock är verksamt i eder som tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'I, käre bröder, haven ju blivit efterföljare till de Guds församlingar i Kristus Jesus som äro i Judeen. Ty I haven av edra egna landsmän fått lida detsamma som de hava lidit av judarna --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'av dem som dödade både Herren Jesus och profeterna och förjagade oss, och som äro misshagliga för Gud och fiender till alla människor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'i det att de söka hindra oss att tala till hedningarna, så att dessa kunna bliva frälsta. Så uppfylla de alltjämt sina synders mått. Dock, vredesdomen har kommit över dem i all sin stränghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Men då vi nu hava måst vara skilda från eder, käre bröder -- visserligen allenast för en kort tid och i utvärtes måtto, icke till hjärtat -- hava vi blivit så mycket mer angelägna att få se edra ansikten och känt stor åstundan därefter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Ty vi hava varit redo att komma till eder -- jag, Paulus, för min del både en och två gånger -- men Satan har hindrat oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Ty vem är vårt hopp och vår glädje och vår berömmelses krona inför vår Herre Jesus vid hans tillkommelse, vem, om icke just I?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'Ja, I ären vår ära och vår glädje.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Därför, när vi icke mer kunde uthärda, beslöto vi att stanna ensamma kvar i Aten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'och sände åstad Timoteus, vår broder och Guds tjänare vid förkunnandet av evangelium om Kristus, för att han skulle styrka och uppmuntra eder i eder tro,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'så att ingen bleve vacklande under dessa lidanden. Ty I veten själva att sådana äro oss förelagda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Redan när vi voro hos eder, sade vi ju eder förut att vi skulle komma att utstå lidanden. Så har nu ock skett, det veten I.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'Det var också därför som jag sände honom åstad, när jag icke mer kunde uthärda; ty jag ville veta något om eder tro, eftersom jag fruktade att frestaren till äventyrs hade så frestat eder, att vårt arbete skulle bliva utan frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'Men nu, då Timoteus har kommit till oss från eder och förkunnat för oss det glada budskapet om eder tro och kärlek, och sagt oss att I alltjämt haven oss i god hågkomst, och att I längten efter att se oss, likasom vi längta efter eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'nu hava vi i fråga om eder, käre bröder, genom eder tro fått hugnad i all vår nöd och allt vårt lidande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Ty nu leva vi, eftersom I stån fasta i Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Ja, huru skola vi nog kunna tacka Gud för eder, till gengäld för all den glädje som vi genom eder hava inför vår Gud?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Natt och dag är det vår innerligaste bön, att vi må få se edra ansikten och avhjälpa vad som kan brista i eder tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'Men vår Gud och Fader själv och vår Herre Jesus må för oss jämna vägen till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Och eder må Herren giva en allt större och mer överflödande kärlek till varandra, ja, till alla människor, en sådan kärlek som vi hava till eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'så att edra hjärtan styrkas till att vara ostraffliga i helighet inför vår Gud och Fader vid vår Herre Jesu tillkommelse, när han kommer med alla sina heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Ytterligare, käre bröder, bedja vi nu och förmana eder i Herren Jesus att allt mer förkovra eder i en sådan vandel som I haven fått lära av oss att I skolen föra, Gud till behag -- en sådan vandel som I redan fören.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'I veten ju vilka bud vi hava givit eder genom Herren Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'Ty detta är Guds vilja, detta som hör till eder helgelse, att I avhållen eder från otukt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'och att var och en av eder vet att hava sin egen maka i helgelse och ära,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'icke i begärelses lusta såsom hedningarna -- vilka icke känna Gud --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'och att ingen i sitt förhållande till sin broder kränker honom eller gör honom något förfång, ty Herren är en hämnare över allt detta, såsom vi redan förut hava sagt och betygat för eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Gud har ju icke kallat oss till orenhet, utan till att leva i helgelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Den som icke vill veta av detta, han förkastar alltså icke en människa, utan Gud, honom som giver sin helige Ande till att bo i eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'Om broderlig kärlek är det icke behövligt att skriva till eder, ty I haven själva fått lära av Gud att älska varandra;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'så handlen I ju ock mot alla bröderna i hela Macedonien. Men vi förmana eder, käre bröder, att allt mer förkovra eder häri');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'och att sätta eder ära i att leva i stillhet och sköta vad eder åligger och arbeta med edra händer, enligt vad vi hava bjudit eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'så att I skicken eder höviskt mot dem som stå utanför och icke behöven anlita någons hjälp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Vi vilja icke lämna eder, käre bröder, i okunnighet om huru det förhåller sig med dem som avsomna, för att I icke skolen sörja såsom de andra, de som icke hava något hopp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Ty lika visst som Jesus, såsom vi tro, har dött och har uppstått, lika visst skall ock Gud genom Jesus föra dem som äro avsomnade fram jämte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Såsom ett ord från Herren säga vi eder nämligen detta, att vi som leva och lämnas kvar till Herrens tillkommelse ingalunda skola komma före dem som äro avsomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'Ty Herren skall själv stiga ned från himmelen, och ett maktbud skall ljuda, en överängels röst och en Guds basun. Och först skola de i Kristus döda uppstå;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'sedan skola vi som då ännu leva och hava lämnats kvar bliva jämte dem bortryckta på skyar upp i luften, Herren till mötes; och så skola vi alltid få vara hos Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'Så trösten nu varandra med dessa ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 1, 'Vad åter angår tid och stund härför, så är det icke behövligt att därom skriva till eder, käre bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 2, 'Ty I veten själva nogsamt att Herrens dag kommer såsom en tjuv om natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 3, 'Bäst de säga: »Allt står väl till, och ingen fara är på färde», då kommer plötsligt fördärv över dem, såsom födslovåndan över en havande kvinna, och de skola förvisso icke kunna fly undan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 4, 'Men I, käre bröder, I leven icke mörker, så att den dagen kan komma över eder såsom en tjuv;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 5, 'I ären ju alla ljusets barn och dagens barn. Ja, vi höra icke natten eller mörkret till;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 6, 'låtom oss alltså icke sova såsom de andra, utan låtom oss vaka och vara nyktra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 7, 'De som sova, de sova om natten, och de som dricka sig druckna, de äro druckna om natten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 8, 'men vi som höra dagen till, vi må vara nyktra, iklädda trons och kärlekens pansar, med frälsningens hopp såsom hjälm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 9, 'Ty Gud har icke bestämt oss till att drabbas av vrede, utan till att vinna frälsning genom vår Herre, Jesus Kristus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 10, 'som har dött för oss, på det att vi må leva tillika med honom, vare sig vi ännu äro vakna eller vi äro avsomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 11, 'Trösten därför varandra, och uppbyggen varandra inbördes, såsom I ock redan gören.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 12, 'Vi bedja eder, käre bröder, att rätt uppskatta de män som arbeta bland eder, och som äro edra föreståndare i Herren och förmana eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 13, 'Låten dem vara eder övermåttan kära, för det verks skull som de utföra. Hållen frid inbördes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 14, 'Vi bjuda eder, käre bröder: Förmanen de oordentliga, uppmuntren de klenmodiga, tagen eder an de svaga, visen tålamod mot var man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 15, 'Sen till, att ingen vedergäller någon med ont för ont; faren fastmer alltid efter att göra vad gott är mot varandra och mot var man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 16, 'Varen alltid glada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 17, 'Bedjen oavlåtligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 18, 'Tacken Gud i alla livets förhållanden. Ty att I så gören är Guds vilja i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 19, 'Utsläcken icke Anden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 20, 'förakten icke profetisk tal,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 21, 'men pröven allt, behållen vad gott är,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 22, 'avhållen eder från allt ont, av vad slag det vara må.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 23, 'Men fridens Gud själv helge eder till hela eder varelse, så att hela eder ande och eder själ och eder kropp finnas bevarade ostraffliga vid vår Herres, Jesu Kristi, tillkommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 24, 'Trofast är han som kallar eder; han skall ock utföra sitt verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 25, 'Käre bröder, bedjen för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 26, 'Hälsen alla bröderna med en helig kyss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 27, 'Jag besvär eder vid Herren att låta uppläsa detta brev för alla bröderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 28, 'Vår Herres, Jesu Kristi, nåd vare med eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Paulus och Silvanus och Timoteus hälsa tessalonikernas församling i Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'Nåd vare med eder och frid ifrån Gud, Fadern, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'Vi äro pliktiga att alltid tacka Gud för eder, käre bröder, såsom tillbörligt är, därför att eder tro så mäktigt tillväxer, och den kärlek I haven till varandra mer och mer förökas hos eder alla och hos envar av eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'Därför kunna vi själva i Guds församlingar berömma oss av eder, i fråga om eder ståndaktighet och eder tro under alla edra förföljelser, och under de lidanden I måsten uthärda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'Sådant är ett vittnesbörd om att Guds dom bliver rättvis. Så skolen I aktas värdiga Guds rike; för dess skull är det ock som I liden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'Guds rättfärdighet kräver ju att de som vålla eder lidande få lidande till vedergällning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'men att I som utstån lidanden fån hugnad tillsammans med oss, när Herren Jesus uppenbarar sig från himmelen med sin makts änglar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, '»i lågande eld», och låter straffet drabba dem som icke känna Gud, och dem som icke äro vår Herre Jesu evangelium lydiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Dessa skola då bliva straffade med evigt fördärv, bort undan Herrens ansikte och hans överväldigande härlighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'när han kommer för att förhärligas i sina heliga och visa sig underbar i alla dem som hava kommit till att tro; ty det vittnesbörd vi hava framburit till eder haven I trott. Så skall ske på den dagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'Fördenskull bedja vi ock alltid för eder, att vår Gud må akta eder värdiga sin kallelse, och att han må med kraft fullborda i eder allt vad en god vilja kan åstunda, och vad tro kan verka,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'så att vår Herre Jesu namn bliver förhärligat i eder, och I i honom, efter vår Guds och Herrens, Jesu Kristi, nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, 'I fråga om vår Herres, Jesu Kristi, tillkommelse, och huru vi skola församlas till honom, bedja vi eder, käre bröder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'att I icke -- vare sig genom någon »andeingivelse» eller på grund av något ord eller något brev, som förmenas komma från oss -- så hastigt låten eder bringas ur fattningen och förloren besinningen, som om Herrens dag redan stode för dörren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Låten ingen bedraga eder om vad sätt det vara må. Ty först måste avfallet hava skett och »Laglöshetens människa», fördärvets man, hava trätt fram,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'vedersakaren, som upphäver sig över allt vad gud heter, och allt som kallas heligt, så att han tager sitt säte i Guds tempel och föregiver sig vara Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'Kommen I icke ihåg att jag sade eder detta, medan jag ännu var hos eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'Och I veten vad det är som nu håller honom tillbaka, så att han först när hans tid är inne kan träda fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'Redan är ju laglöshetens hemlighet verksam; allenast måste den som ännu håller tillbaka först skaffas ur vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'Sedan skall »den Laglöse» träda fram, och honom skall då Herren Jesus döda med sin muns anda och tillintetgöra genom sin tillkommelses uppenbarelse --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, 'honom som efter Satans tillskyndelse kommer med lögnens alla kraftgärningar och tecken och under');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'och med orättfärdighetens alla bedrägliga konster, för att bedraga dem som gå förlorade, till straff därför att de icke gåvo kärleken till sanningen rum, så att de kunde bliva frälsta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'Därför sänder ock Gud över dem villfarelsens makt, så att de sätta tro till lögnen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'för att de skola bliva dömda, alla dessa som icke hava satt tro till sanningen, utan funnit behag i orättfärdigheten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, 'Men vi för vår del äro pliktiga att alltid tacka Gud för eder käre bröder, I Herrens älskade, därför att Gud från begynnelsen har utvalt eder till frälsning, i helgelse i Anden och i tro på sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'Härtill har han ock genom vårt evangelium kallat eder, för att I skolen bliva delaktiga av vår Herres, Jesu Kristi, härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'Stån alltså fasta, käre bröder, och hållen eder vid de lärdomar som I haven mottagit av oss, vare sig muntligen eller genom brev.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 16, 'Och vår Herre Jesus Kristus själv och Gud, vår Fader, som har älskat oss och i nåd berett oss en evig hugnad och givit oss ett gott hopp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 17, 'han hugne edra hjärtan, och styrke eder till allt vad gott är, både i gärning och i ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, 'För övrigt, käre bröder, bedjen för oss, att Herrens ord må hava framgång och komma till ära hos andra likasom hos eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'så ock att vi må bliva frälsta ifrån vanartiga och onda människor. Ty tron är icke var mans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'Men Herren är trofast, och han skall styrka eder och bevara eder från det onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'Och vi hava den tillförsikten till eder i Herren, att I både nu gören och framgent skolen göra vad vi bjuda eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Ja, Herren styre edra hjärtan till Guds kärlek och Kristi ståndaktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, 'Men vi bjuda eder, käre bröder, i vår Herres, Jesu Kristi, namn, att I dragen eder ifrån var broder som för en oordentlig vandel och icke lever efter de lärdomar han har mottagit av oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'I veten ju själva huru man bör efterfölja oss. Ty vi förhöllo oss icke oordentligt bland eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'ej heller åto vi någons bröd för intet; tvärtom åto vi vårt bröd under arbete och möda, och vi strävade natt och dag, för att icke bliva någon av eder till tunga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'Icke som om vi ej hade haft rätt därtill, men vi ville låta eder i oss få ett föredöme, för att I skullen efterfölja oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Redan när vi voro hos eder, gåvo vi ju eder det budet: om någon icke vill arbeta, så skall han icke heller äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, 'Vi höra nämligen att somliga bland eder föra en oordentlig vandel och icke arbeta, utan allenast syssla med sådant som icke kommer dem vid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'Sådana människor bjuda och förmana vi i Herren Jesus Kristus, att de arbeta i stillhet, så att de kunna äta sitt eget bröd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'Och I, käre bröder, mån icke förtröttas att göra vad gott är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 14, 'Men om någon icke lyder vad vi hava sagt i detta brev, så märken ut för eder den mannen, och haven intet umgänge med honom, på det att han må blygas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 15, 'Hållen honom dock icke för en ovän, utan förmanen honom såsom en broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 16, 'Men fridens Herre själv give eder sin frid alltid och på allt sätt. Herren vare med eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 17, 'Här skriver jag, Paulus, min hälsning med egen hand. Detta är ett kännetecken i alla mina brev; så skriver jag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 18, 'Vår Herres, Jesu Kristi, nåd vare med eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Paulus, Kristi Jesu apostel, förordnad av Gud, vår Frälsare, och Kristus Jesus, vårt hopp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'hälsar Timoteus, sin sannskyldige son i tron. Nåd, barmhärtighet och frid ifrån Gud, Fadern, och Kristus Jesus, vår Herre!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Jag bjuder dig, nu såsom när jag for åstad till Macedonien, att stanna kvar i Efesus och där förmana somliga att icke förkunna främmande läror');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'eller akta på fabler och släktledningshistorier utan ände, som ju snarare vålla ordstrider än främja den Guds ordning som kommer till fullbordan i tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Och förmaningens ändamål är kärlek av ett rent hjärta och av ett gott samvete och av en oskrymtad tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'Från dessa stycken hava somliga farit vilse och vänt sin håg till fåfängligt tal --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'människor som vilja vara lärare i lagen, fastän de icke förstå ens vad de själva tala, eller vad de ting äro, som de med sådan säkerhet orda om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Men vi veta att lagen är god, om man nämligen brukar den såsom lagen bör brukas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'och om man förstår detta, att lagen är till icke för rättfärdiga människor, utan för dem som trotsa lag och myndighet, för ogudaktiga och syndare, oheliga och oandliga människor, fadermördare och modermördare, för mandråpare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'för dem som öva otukt och onaturlig vällustsynd, för dem som äro människosäljare, lögnare, menedare eller något annat som strider mot den sunda läran --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'detta i enlighet med det evangelium om den salige Gudens härlighet, varmed jag har blivit betrodd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Vår Herre Kristus Jesus, som har givit mig kraft, tackar jag för att han har tagit mig i sin tjänst och funnit mig vara förtroende värd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'mig som förut var en hädare och förföljare och våldsverkare. Men barmhärtighet vederfors mig, eftersom jag icke bättre visste, när jag i min otro handlade så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'Och vår Herres nåd blev så mycket mer överflödande, med tron och kärleken i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, 'Det är ett fast ord och i allo värt att mottagas, att Kristus Jesus har kommit i världen för att frälsa syndare, bland vilka jag är den främste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 16, 'Men att barmhärtighet vederfors mig, det skedde just för att Kristus Jesus skulle främst på mig bevisa all sin långmodighet, och låta mig bliva en förstlingsbild av dem som skulle komma att tro på honom och så vinna evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 17, 'Men evigheternas konung, den oförgänglige, osynlige, ende Guden, vare ära och pris i evigheternas evigheter! Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 18, 'Att så förmana dem, det ålägger jag dig, min son Timoteus, i enlighet med de profetord som en gång uttalades över dig. Må du i kraft av dem strida den goda striden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 19, 'rustad med tro och med ett gott samvete. Detta hava nu visserligen somliga skjutit å sido, men de hava därigenom lidit skeppsbrott i tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 20, 'Till dem höra Hymeneus och Alexander, vilka jag har överlämnat åt Satan, för att de skola bliva så tuktade, att de icke vidare smäda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 1, 'Så uppmanar jag nu framför allt därtill att man må bedja, åkalla, anropa och tacka Gud för alla människor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 2, 'för konungar och all överhet, så att vi kunna föra ett lugnt och stilla liv, på ett i allo fromt och värdigt sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 3, 'Sådant är gott och välbehagligt inför Gud, vår Frälsare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 4, 'som vill att alla människor skola bliva frälsta och komma till kunskap om sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 5, 'Ty en enda är Gud, och en enda är medlare emellan Gud och människor: en människa, Kristus Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 6, 'han som gav sig själv till lösen för alla, varom ock vittnesbördet skulle frambäras, när tiden var inne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 7, 'Och själv har jag blivit satt till att vara dess förkunnare och apostel -- det säger jag med sanning, jag ljuger icke -- ja, till att i tro och sanning vara en lärare för hedningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 8, 'Jag vill alltså att männen allestädes skola förrätta bön, i det att de, fria ifrån vrede och disputerande, upplyfta heliga händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 9, 'Likaledes vill jag att kvinnorna skola uppträda i hövisk dräkt, att de blygsamt och tuktigt pryda sig, icke med hårflätningar och guld eller pärlor eller dyrbara kläder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 10, 'utan med goda gärningar, såsom det höves kvinnor som vilja räknas för gudfruktiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 11, 'Kvinnan bör i stillhet låta sig undervisas och därvid helt underordna sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 12, 'Däremot kan jag icke tillstädja en kvinna att själv uppträda såsom lärare, ej heller att råda över sin man; fastmer må hon leva i stillhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 13, 'Adam blev ju först skapad och sedan Eva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 14, 'Och Adam blev icke bedragen, men kvinnan blev svårt bedragen och förleddes till överträdelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 15, 'Dock skall kvinnan, under det hon föder sina barn, vinna frälsning, om hon förbliver i tro och kärlek och helgelse, med ett tuktigt väsende.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 1, 'Det är ett visst ord, att om någons håg står till en församlingsföreståndares ämbete, så är det en god verksamhet han åstundar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 2, 'En församlingsföreståndare bör därför vara oförvitlig; han bör vara en enda kvinnas man, nykter och tuktig, hövisk i sitt skick, gästvänlig, väl skickad att undervisa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 3, 'icke begiven på vin, icke våldsam, utan foglig, icke stridslysten, fri ifrån penningbegär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 4, 'Han bör väl förestå sitt eget hus och hålla sina barn i lydnad, med all värdighet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 5, 'ty huru skulle dem som icke vet att förestå sitt eget hus kunna sköta Guds församling?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 6, 'Han bör icke vara nyomvänd, för att han icke skall förblindas av högmod och så hemfalla under djävulens dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 7, 'Han bör ock hava gott vittnesbörd om sig av dem som stå utanför, så att han icke utsättes för smälek och faller i djävulens snara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 8, 'Församlingstjänarna böra likaledes skicka sig värdigt, icke vara tvetaliga, icke benägna för mycket vindrickande, icke snikna efter slem vinning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 9, 'de böra äga trons hemlighet i ett rent samvete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 10, 'Men också dessa skola först prövas; därefter må de, om de befinnas oförvitliga, få tjäna församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 11, 'Är det kvinnor, så böra dessa likaledes skicka sig värdigt, icke gå omkring med förtal, men vara nyktra och trogna i allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 12, 'En församlingstjänare skall vara en enda kvinnas man; han skall hålla god ordning på sina barn och väl förestå sitt hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 13, 'Ty de som hava väl skött en församlingstjänares syssla, de vinna en aktad ställning och kunna i tron, den tro de hava i Kristus Jesus, uppträda med mycken frimodighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 14, 'Detta skriver jag till dig, fastän jag hoppas att snart få komma till dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 15, 'Jag vill nämligen, om jag likväl skulle dröja, att du skall veta huru man bör förhålla sig i Guds hus, som ju är den levande Gudens församling, sanningens stödjepelare och grundfäste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 16, 'Och erkänt stor är gudaktighetens hemlighet: »Han som blev uppenbarad i köttet, rättfärdigad i anden, sedd av änglar, predikad bland hedningarna, trodd i världen, upptagen i härligheten.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 1, 'Men Anden säger uttryckligen, att i kommande tider somliga skola avfalla från tron och hålla sig till villoandar och till onda andars läror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 2, 'Så skall ske genom lögnpredikanters skrymteri, människors som i sina egna samveten äro brännmärkta såsom brottslingar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 3, 'och som förbjuda äktenskap och vilja att man skall avhålla sig från allahanda mat, som Gud har skapat till att med tacksägelse mottagas av dem som tro och hava lärt känna sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 4, 'Ty allt vad Gud har skapat är gott, och intet är förkastligt, när det mottages med tacksägelse:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 5, 'det bliver nämligen helgat genom Guds ord och genom bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 6, 'Om du framlägger detta för bröderna, så bevisar du dig såsom en god Kristi Jesu tjänare, då du ju hämtar din näring av trons och den goda lärans ord, den läras som du troget har efterföljt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 7, 'Men de oandliga käringfablerna må du visa ifrån dig. Öva dig i stället själv i gudsfruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 8, 'Ty lekamlig övning gagnar till litet, men gudsfruktan gagnar till allt; den har med sig löfte om liv, både för denna tiden och för den tillkommande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 9, 'Detta är ett fast ord och i allo värt att mottagas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 10, 'Ja, därför arbeta och kämpa vi, då vi nu hava satt vårt hopp till den levande Guden, honom som är alla människors Frälsare, först och främst deras som tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 11, 'Så skall du bjuda och undervisa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 12, 'Låt ingen förakta dig för din ungdoms skull; fastmer må du för dem som tro bliva ett föredöme i tal och i vandel, i kärlek, i tro och i renhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 13, 'Var nitisk i att föreläsa skriften och i att förmana och undervisa, till dess jag kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 14, 'Försumma icke att vårda den nådegåva som finnes i dig, och som gavs dig i kraft av profetord, under handpåläggning av de äldste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 15, 'Tänk på detta, lev i detta, så att din förkovran bliver uppenbar för alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 16, 'Hav akt på dig själv och på din undervisning, och håll stadigt ut därmed; ty om du så gör, frälsar du både dig själv och dem som höra dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 1, 'En äldre man må du icke tillrättavisa med hårda ord; du bör tala till honom såsom till en fader. Till yngre män må du tala såsom till bröder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 2, 'till äldre kvinnor såsom till mödrar, till yngre kvinnor såsom till systrar, i all renhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 3, 'Änkor må du bevisa ära, om de äro rätta, värnlösa änkor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 4, 'Men om en änka har barn eller barnbarn, då må i första rummet dessa lära sig att med tillbörlig vördnad taga sig an sina närmaste och så återgälda sina föräldrar vad de äro dem skyldiga; ty sådant är välbehagligt inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 5, 'En rätt, värnlös änka, som sitter ensam, hon har sitt hopp i Gud och håller ut i bön och åkallan natt och dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 6, 'Men en sådan som allenast gör sig goda dagar, hon är död, fastän hon lever. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 7, 'Förehåll dem också detta, så att man icke får något att förevita dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 8, 'Men om någon icke drager försorg om sina egna, först och främst om sina närmaste, så har denne förnekat sin tro och är värre än en otrogen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 9, 'Såsom »församlingsänka» må ingen annan uppföras än den som är minst sextio år gammal, och som har varit allenast en mans hustru,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 10, 'en som har det vittnesbördet om sig, att hon har övat goda gärningar, uppfostrat barn, givit härbärge åt husvilla, tvagit heligas fötter, understött nödlidande, korteligen, beflitat sig om allt gott verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 11, 'Unga änkor skall du däremot icke antaga. Ty när de hava njutit nog av Kristus, vilja de åter gifta sig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 12, 'och de äro då hemfallna åt dom, eftersom de hava brutit sin första tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 13, 'Därtill lära de sig ock att vara lättjefulla, i det att de löpa omkring i husen; ja, icke allenast att vara lättjefulla, utan ock att vara skvalleraktiga och att syssla med sådant som icke kommer dem vid, allt medan de tala vad otillbörligt är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 14, 'Därför vill jag att unga änkor gifta sig, föda barn, förestå var och en sitt hus och icke giva någon motståndare anledning att smäda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 15, 'Redan hava ju några vikit av och följt efter Satan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 16, 'Om någon troende, vare sig man eller kvinna, har änkor att sörja för, då må han understödja dem utan att församlingen betungas, för att denna så må kunna understödja rätta, värnlösa änkor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 17, 'Sådana äldste som äro goda församlingsföreståndare må aktas dubbel heder värda, först och främst de som arbeta med predikande och undervisning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 18, 'Skriften säger ju: »Du skall icke binda munnen till på oxen som tröskar», så ock: »Arbetaren är värd sin lön.» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 19, 'Upptag intet klagomål mot någon av de äldste, om det icke styrkes av två eller tre vittnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 20, 'Men begår någon en synd, så skall du inför alla förehålla honom den, så att också de andra känna fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 21, 'Jag uppmanar dig allvarligt inför Gud och Kristus Jesus och de utvalda änglarna att iakttaga detta, utan någon förutfattad mening och utan att i något stycke förfara partiskt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 22, 'Förhasta dig icke med handpåläggning, och gör dig icke delaktig i en annans synder. Bevara dig själv ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 23, 'Drick nu icke längre allenast vatten, utan bruka något litet vin för din mages skull, eftersom du så ofta lider av svaghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 24, 'Somliga människors synder ligga i öppen dag och komma i förväg fram till dom; andras åter komma först efteråt fram.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 25, 'Sammalunda pläga ock goda gärningar ligga i öppen dag; och när så icke är, kunna de ändå icke bliva fördolda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 1, 'De som äro trälar och tjäna under andra må akta sina herrar all heder värda, så att Guds namn och läran icke bliva smädade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 2, 'Men de som hava troende herrar må icke, därför att de äro deras bröder, akta dem mindre; fastmer må de tjäna dem så mycket villigare, just därför att de äro troende och kära bröder, dessa som vinnlägga sig om att göra vad gott är. Så skall du undervisa och förmana.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 3, 'Om någon förkunnar främmande läror och icke håller sig till sunda ord -- vår Herres, Jesu Kristi, ord -- och till den lära som hör gudsfruktan till,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 4, 'då är han förblindad av högmod, och detta fastän han intet förstår, utan är såsom från vettet i sitt begär efter disputerande och ordstrider, vilka vålla avund, kiv, smädelser, ondskefulla misstankar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 5, 'och ständiga tvister mellan människor som äro fördärvade i sitt sinne och hava tappat bort sanningen, människor som mena att gudsfruktan är ett medel till vinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 6, 'Ja, gudsfruktan i förening med förnöjsamhet är verkligen en stor vinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 7, 'Vi hava ju icke fört något med oss till världen, just därför att vi icke kunna föra något med oss ut därifrån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 8, 'Hava vi föda och kläder, så må vi låta oss nöja därmed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 9, 'Men de som vilja bliva rika, de råka in i frestelser och snaror och hemfalla åt många dåraktiga och skadliga begärelser, som sänka människorna ned i fördärv och undergång.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 10, 'Ty penningbegäret är en rot till allt ont; och somliga hava låtit sig så drivas därav, att de hava villats bort ifrån tron och därigenom tillskyndat sig själva många kval.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 11, 'Men fly sådant, du gudsmänniska, och far efter rättfärdighet, gudsfruktan, tro, kärlek, ståndaktighet, saktmod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 12, 'Kämpa trons goda kamp, sök att vinna det eviga livet, vartill du har blivit kallad, du som ock inför många vittnen har avlagt den goda bekännelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 13, 'Inför Gud, som giver liv åt allt, och inför Kristus Jesus, som under Pontius Pilatus vittnade med den goda bekännelsen, manar jag dig');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 14, 'att, själv utan fläck och tadel, hålla vad jag har bjudit, intill vår Herres, Jesu Kristi, uppenbarelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 15, 'vilken den salige, ende härskaren skall låta oss se, när tiden är inne, han som är konungarnas konung och herrarnas herre,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 16, 'han som allena har odödlighet och bor i ett ljus dit ingen kan komma, han som ingen människa har sett eller kan se. Honom vare ära och evigt välde! Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 17, 'Bjud dem som äro rika i den tidsålder som nu är att icke högmodas, och att icke sätta sitt hopp till ovissa rikedomar, utan till Gud, som rikligen giver oss allt till att njuta därav;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 18, 'bjud dem att göra gott, att vara rika på goda gärningar, att vara givmilda och gärna dela med sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 19, 'Må de så lägga av åt sig skatter som kunna bliva en god grundval för det tillkommande, så att de vinna det verkliga livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 20, 'O Timoteus, bevara vad som har blivit dig betrott; och vänd dig bort ifrån de oandliga, tomma ord och gensägelser som komma från den falskeligen så kallade »kunskapen»[1],');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 21, 'vilken några föregiva sig äga, varför de ock hava farit vilse i fråga om tron. Nåd vare med eder. [1] Se Kunskap i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Paulus, genom Guds vilja Kristi Jesu apostel -- sänd enligt det löfte som gavs oss om liv, livet i Kristus Jesus --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'hälsar Timoteus, sin älskade son. Nåd, barmhärtighet och frid ifrån Gud, Fadern, och Kristus Jesus, vår Herre!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Jag tackar Gud, som jag i likhet med mina förfäder tjänar, och det med rent samvete, såsom jag ock oavlåtligen har dig i åtanke i mina böner, både natt och dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Och när jag kommer ihåg dina tårar, längtar jag efter att se dig, för att så bliva uppfylld av glädje,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'då jag erinras om din oskrymtade tro, samma tro som först bodde i din mormoder Lois och din moder Eunice, och som nu -- därom är jag förvissad -- jämväl bor i dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'Fördenskull påminner jag dig att du må uppliva den nådegåva från Gud, som i följd av min handpåläggning finnes i dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'Ty Gud har icke givit oss en försagdhetens ande, utan en kraftens och kärlekens och tuktighetens ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Blygs därför icke för vittnesbördet om vår Herre, ej heller för mig, hans fånge, utan bär också du ditt lidande för evangelium, genom den kraft som Gud giver,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'han som har frälst oss och kallat oss med en helig kallelse, icke på grund av våra gärningar, utan efter sitt eget rådslut och sin nåd, den nåd som redan för evärdliga tider sedan gavs oss i Kristus Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'men som nu har blivit uppenbar genom vår Frälsares, Kristi Jesu, uppenbarelse. Ty han har gjort dödens makt om intet och fört liv och oförgänglighet fram i ljuset genom evangelium,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'till vars förkunnare och apostel och lärare jag har blivit satt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Fördenskull lider jag också detta, men jag blyges dock icke därför. Ty jag vet på vem jag tror, och jag är viss om att han är mäktig att för »den dagen»[1] bevara vad som har blivit mig betrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'Såsom förebild i fråga om sunda ord må du, i tron och kärleken i Kristus Jesus, hava de ord som du har hört av mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Bevara genom den helige Ande, vilken bor i oss, det goda som har blivit dig betrott.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'Det vet du, att alla i provinsen Asien hava vänt sig ifrån mig, bland dem också Fygelus och Hermogenes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'Må Herren visa barmhärtighet mot Onesiforus\' hus, eftersom han ofta var mig till vederkvickelse och icke blygdes för mina kedjor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'fastmer, när han kom till Rom, sökte han efter mig med all iver, till dess han fann mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, 'Ja, Herren give att han må finna barmhärtighet hos Herren på »den dagen». Till huru stor tjänst han var i Efesus, det vet du själv bäst. [1] Se Dagen i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 1, 'Så bliv nu du, min son, allt starkare i den nåd som är i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 2, 'Och vad du har hört av mig och fått betygat av många vittnen, det må du betro åt män som äro förtroende värda, och som kunna bliva skickliga att i sin ordning undervisa andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 3, 'Bär ock du ditt lidande såsom en god Kristi Jesu stridsman.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 4, 'Ingen som tjänar i krig låter sig insnärjas i näringsomsorger, ty han vill vara den till behag, som har tagit honom i sin sold.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 5, 'Likaså, om någon deltager i en tävlingskamp, så vinner han icke segerkransen, ifall han icke kämpar efter stadgad ordning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 6, 'Åkermannen, han som gör arbetet, bör främst av alla få njuta av frukten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 7, 'Fatta rätt vad jag säger; Herren skall giva dig förstånd i allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 8, 'Tänk på Jesus Kristus, som är uppstånden från de döda, av Davids säd, enligt det evangelium som jag förkunnar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 9, 'och i vars tjänst jag jämväl utstår lidande, ja, till och med måste bära bojor såsom en ogärningsman. Men Guds ord bär icke bojor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 10, 'Därför uthärdar jag ståndaktigt allting för de utvaldas skull, på det att också de må vinna frälsningen i Kristus Jesus och därmed evig härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 11, 'Detta är ett fast ord; ty hava vi dött med honom, så skola vi ock leva med honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 12, 'äro vi ståndaktiga, så skola vi ock få regera med honom. Men förneka vi honom, så skall ock han förneka oss;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 13, 'äro vi trolösa, så står han troget fast vid sitt ord. Ty han kan icke förneka sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 14, 'Påminn dem om detta, och uppmana dem allvarligt inför Gud att icke befatta sig med ordstrider; ty sådana gagna till intet, utan äro allenast till fördärv för dem som höra därpå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 15, 'Sträva med all flit efter att själv kunna träda fram inför Gud såsom en som håller provet, en arbetare som icke behöver blygas, utan rätt förvaltar sanningens ord.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 16, 'Men undfly oandligt och tomt prat. Ty de som befatta sig med sådant komma att gå allt längre i ogudaktighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 17, 'och deras tal skall fräta omkring sig såsom ett kräftsår. Av det slaget äro Hymeneus och Filetus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 18, 'ty när dessa säga att uppståndelsen redan har skett, hava de farit vilse från sanningen, och de förvända så tron hos somliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 19, 'Dock, Guds fasta grundval förbliver beståndande och har ett insegel med dessa ord: »Herren känner de sina», och: »Var och en som åkallar Herrens namn, han vände sig bort ifrån orättfärdighet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 20, 'Men i ett stort hus finnas kärl icke allenast av guld och silver, utan ock av trä och lera; och somliga äro till hedersamt bruk, andra till mindre hedersamt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 21, 'Om nu någon håller sig ren och obesmittad av sådant folk, då bliver han ett kärl till hedersamt bruk, helgat, gagneligt för sin herre, tjänligt till allt vad gott är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 22, 'Fly ungdomens onda begärelser, och far efter rättfärdighet, tro och kärlek, och frid med dem som av rent hjärta åkalla Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 23, 'Men undvik dåraktiga och barnsliga tvistefrågor; du vet ju att de föda av sig strider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 24, 'Och en Herrens tjänare bör icke strida, utan vara mild mot alla, väl skickad att undervisa, tålig när han får lida.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 25, 'Han bör med saktmod tillrättavisa de motspänstiga, i hopp att Gud till äventyrs skall förläna dem bättring, så att de komma till kunskap om sanningen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 26, 'och i hopp att de så skola bliva nyktra och därigenom befrias ur djävulens snara; ty av honom äro de fångade, så att de göra hans vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 1, 'Men det må du veta, att i de yttersta dagarna svåra tider skola komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 2, 'Ty människorna skola då vara själviska, penningkära, stortaliga, övermodiga, smädelystna, olydiga mot sina föräldrar, otacksamma, gudlösa,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 3, 'kärlekslösa mot sina närmaste, trolösa, begivna på förtal, omåttliga, tygellösa, fientliga mot det goda,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 4, 'förrädiska, besinningslösa, förblindade av högmod; de skola älska vällust mer än Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 5, 'de skola hava ett sken av gudsfruktan, men skola icke vilja veta av dess kraft. Vänd dig bort ifrån sådana.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 6, 'Ty till dem höra de män som innästla sig i husen och fånga svaga kvinnor, som äro tyngda av synder och drivas av allahanda begärelser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 7, 'kvinnor som alltjämt hålla på med att lära, men aldrig kunna komma till kunskap om sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 8, 'Och såsom Jannes och Jambres stodo emot Moses, så stå dessa män emot sanningen; de äro människor som äro fördärvade i sitt sinne och icke hålla provet i fråga om tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 9, 'Men de skola icke tillstädjas att gå längre, ty deras galenskap skall bliva uppenbar för alla, såsom det skedde med de männens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 10, 'Du åter har blivit min efterföljare i lära, i vandel, i strävanden, i tro, i tålamod, i kärlek, i ståndaktighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 11, 'under förföljelser och lidanden, sådana som drabbade mig i Antiokia, Ikonium och Lystra. Ja, sådana förföljelser har jag fått utstå, men ur alla har Herren frälst mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 12, 'Så skola ock alla de, som vilja leva gudfruktigt i Kristus Jesus, få lida förföljelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 13, 'Men onda människor och bedragare skola gå allt längre i ondska; de skola förvilla andra och själva bliva förvillade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 14, 'Men förbliv du vid det som du har lärt, och som du har fått visshet om. Du vet ju av vilka du har lärt det,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 15, 'och du känner från barndomen de heliga skrifter som kunna giva dig vishet, så att du bliver frälst genom den tro du har i Kristus Jesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 16, 'All skrift som är ingiven av Gud är ock nyttig till undervisning, till bestraffning, till upprättelse, till fostran i rättfärdighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 17, 'så att en gudsmänniska kan bliva fullt färdig, väl skickad till allt gott verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 1, 'Jag uppmanar dig allvarligt inför Gud och Kristus Jesus, inför honom som skall döma levande och döda, jag uppmanar dig vid hans tillkommelse och hans rike:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 2, 'Predika ordet, träd upp i tid och otid, bestraffa, tillrättavisa, förmana med allt tålamod och med undervisning i alla stycken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 3, 'Ty den tid kommer, då de icke längre skola fördraga den sunda läran, utan efter sina egna begärelser skola samla åt sig lärare hoptals, alltefter som det kliar dem i öronen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 4, 'en tid då de skola vända sina öron från sanningen, och i stället vända sig till fabler.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 5, 'Men du, var nykter i allting, bär ditt lidande, utför en evangelists verk, fullgör i allo vad som tillhör ditt ämbete.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 6, 'Ty själv är jag nu på väg att offras, och tiden är inne, då jag skall bryta upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 7, 'Jag har kämpat den goda kampen, jag har fullbordat mitt lopp, jag har bevarat tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 8, 'Nu ligger rättfärdighetens segerkrans tillreds åt mig, och Herren, den rättfärdige domaren, skall giva den åt mig på »den dagen»[1], och icke åt mig allenast, utan åt alla som hava älskat hans tillkommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 9, 'Låt dig angeläget vara att snart komma till mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 10, 'Ty av kärlek till denna tidsålders väsende har Demas övergivit mig och har begivit sig till Tessalonika; Krescens har begivit sig till Galatien och Titus till Dalmatien.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 11, 'Lukas är den ende som är kvar hos mig. Tag Markus med dig hit; ty han kan i mycket vara mig till gagn och tjäna mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 12, 'Tykikus har jag sänt till Efesus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 13, 'När du kommer, så hav med dig den mantel som jag lämnade kvar hos Karpus i Troas, så ock böckerna, först och främst pergamentskrifterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 14, 'Alexander, smeden, har gjort mig mycket ont; Herren kommer att vedergälla honom efter hans gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 15, 'Också du må taga dig till vara för honom, ty han har häftigt trätt upp emot det som vi hava talat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 16, 'Vid mitt första försvar inför rätta kom ingen mig till hjälp, utan alla övergåvo mig; må det icke bliva dem tillräknat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 17, 'Men Herren stod mig bi och gav mig kraft, för att genom mig ordet överallt skulle bliva predikat, så att alla hedningar finge höra det; och så blev jag räddad ur lejonets gap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 18, 'Ja, Herren skall rädda mig från alla ondskans tilltag och frälsa mig till sitt himmelska rike. Honom tillhör äran i evigheternas evigheter. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 19, 'Hälsa Priska och Akvila, så ock Onesiforus\' hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 20, 'Erastus stannade kvar i Korint, men Trofimus lämnade jag sjuk efter mig i Miletus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 21, 'Låt dig angeläget vara att komma hit före vintern. Eubulus och Pudens och Linus och Klaudia och alla bröderna hälsa dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 22, 'Herren vare med din ande. Nåd vare med eder. [1] Se Dagen i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Paulus, Guds tjänare och Jesu Kristi apostel, sänd att verka för Guds utvaldas tro och för kunskapen om den sanning som hör gudsfruktan till,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'sänd, därför att det finnes ett hopp om evigt liv -- ty evigt liv har Gud, som icke kan ljuga, för evärdliga tider sedan utlovat,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'och när tiden var inne, uppenbarade han sitt ord i den predikan varmed jag genom Guds, vår Frälsares, befallning blev betrodd --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'jag, Paulus, hälsar Titus, min sannskyldige son på grund av gemensam tro. Nåd och frid ifrån Gud, Fadern, och Kristus Jesus, vår Frälsare!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'När jag lämnade dig kvar på Kreta, var det för att du skulle ordna vad som ännu återstod att ordna, och för att du, på det sätt som jag har ålagt dig, skulle i var särskild stad tillsätta äldste,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'varhelst någon oförvitlig man funnes, en enda kvinnas man, en som hade troende barn, vilka icke vore i vanrykte för oskickligt leverne eller vore uppstudsiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Ty en församlingsföreståndare bör vara oförvitlig, såsom det höves en Guds förvaltare, icke självgod, icke snar till vrede, icke begiven på vin, icke våldsam, icke sniken efter slem vinning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'Han bör fastmer vara gästvänlig, nitälska för vad gott är, leva tuktigt, rättfärdigt, heligt och återhållsamt;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'han bör hålla sig stadigt vid det fasta ordet, såsom han har fått lära det, så att han är mäktig både att förmana medelst den sunda läran och att vederlägga dem som säga emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'Ty många finnas som icke vilja veta av någon myndighet, många som föra fåfängligt tal och bedraga människors sinnen; så göra i synnerhet de omskurna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'På sådana bör man tysta munnen, ty de förvilla hela hus genom att för slem vinnings skull förkunna otillbörliga läror.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'En av dem, en profet av deras eget folk, har sagt: »Kreterna, lögnare jämt, äro odjur, glupska och lata.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Och det vittnesbördet är sant. Du skall därför strängt tillrättavisa dem, så att de bliva sunda i tron');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'och icke akta på judiska fabler och vad som påbjudes av människor som vända sig från sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'Allt är rent för dem som äro rena; men för de orena och otrogna är intet rent, utan hos dem äro både förstånd och samvete orenade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'De säga sig känna Gud, men med sina gärningar förneka de det; ty de äro vederstyggliga och ohörsamma människor, odugliga till allt gott verk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Du åter må tala vad som är den sunda läran värdigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Förmana de äldre männen att vara nyktra, att skicka sig värdigt och tuktigt, att vara sunda i tro, i kärlek, i ståndaktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'Förmana likaledes de äldre kvinnorna att skicka sig såsom det höves heliga kvinnor, att icke gå omkring med förtal, icke vara trälar under begäret efter vin, utan lära andra vad gott är, för att fostra dem till tuktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'Förmana de yngre kvinnorna att älska sina män och sina barn,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'att föra en tuktig och ren vandel, att vara goda husmödrar och att underordna sig sina män, så att Guds ord icke bliver smädat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Förmana likaledes de yngre männen att skicka sig tuktigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Bliv dem i allo ett föredöme i goda gärningar, och låt dem i din undervisning finna oförfalskad renhet och värdighet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'med sunt, ostraffligt tal, så att den som står oss emot måste blygas, då han nu icke har något ont att säga om oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Förmana tjänarna att i allt underordna sig sina herrar, att skicka sig dem till behag och icke vara gensvariga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'att icke begå någon oärlighet, utan på allt sätt visa dem redbar trohet, så att de i alla stycken bliva en prydnad för Guds, vår Frälsares, lära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Ty Guds nåd har uppenbarats till frälsning för alla människor;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'den fostrar oss till att avsäga oss all ogudaktighet och alla världsliga begärelser, och till att leva tuktigt och rättfärdigt och gudfruktigt i den tidsålder som nu är,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'medan vi vänta på vårt saliga hopps fullbordan och på den store Gudens och vår Frälsares, Kristi Jesu, härlighets uppenbarelse --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'hans som har utgivit sig själv för oss, till att förlossa oss från all orättfärdighet, och till att rena åt sig ett egendomsfolk, som beflitar sig om att göra vad gott är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Så skall du tala; och du skall förmana och tillrättavisa dem med all myndighet. Låt ingen förakta dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Lägg dem på minnet att de böra vara underdåniga överheten, dem som hava myndighet, att de böra visa lydnad och vara redo till allt gott verk,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'att de icke må smäda någon, icke vara stridslystna, utan vara fogliga, och att de i allt skola visa sig saktmodiga mot alla människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'Vi voro ju själva förut oförståndiga, ohörsamma och vilsefarande, vi voro trälar under allahanda begärelser och lustar, vi levde i ondska och avund, vi voro värda att avskys, och vi hatade varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Men när Guds, vår Frälsares, godhet och kärlek till människorna uppenbarades,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'då frälste han oss, icke på grund av rättfärdighetsgärningar som vi hade gjort, utan efter sin barmhärtighet, genom ett bad till ny födelse och förnyelse i helig ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'som han rikligen utgöt över oss genom Jesus Kristus, vår Frälsare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'för att vi, rättfärdiggjorda genom hans nåd, skulle, såsom vårt hopp är, få evigt liv till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Detta är ett fast ord, och jag vill att du med kraft vittnar härom, för att de som sätta tro till Gud må beflita sig om att rätt utöva goda gärningar. Sådant är gott och gagneligt för människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Men dåraktiga tvistefrågor och släktledningshistorier må du undfly, så ock trätor och strider om lagen; ty sådant är gagnlöst och fåfängligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'En man som kommer partisöndring åstad må du visa ifrån dig, sedan du en eller två gånger har förmanat honom;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'ty du vet att en sådan är förvänd och begår synd, ja, han har själv fällt domen över sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'När jag framdeles sänder Artemas eller Tykikus till dig, låt dig då angeläget vara att komma till mig i Nikopolis, ty jag har beslutit att stanna där över vintern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Senas, den lagkloke, och Apollos må du med all omsorg utrusta för deras resa, så att intet fattas dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Och må jämväl våra bröder, för att icke bliva utan frukt, lära sig att rätt utöva goda gärningar, där hjälp är av nöden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Alla som äro här hos mig hälsa dig. Hälsa dem som älska oss i tron. Nåd vare med eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, 'Paulus, Kristi Jesu fånge, och brodern Timoteus hälsa Filemon, vår älskade broder och medarbetare,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'och Appfia, vår syster, och Arkippus, vår medkämpe, och den församling som kommer tillhopa i ditt hus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'Nåd vare med eder och frid ifrån Gud, vår Fader, och Herren Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'Jag tackar min Gud alltid, när jag tänker på dig i mina böner,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, 'ty jag har hört om den kärlek och den tro som du har till Herren Jesus, och som du bevisar mot alla de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'Och min bön är att den tro du har gemensam med oss må visa sig verksam, i det att du fullt inser huru mycket gott vi hava i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'Ty jag har fått mycken glädje och hugnad av den kärlek varmed du, min broder, har vederkvickt de heligas hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'Därför, fastän jag med mycken frimodighet i Kristus kunde befalla dig att göra vad du nu bör göra,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'beder jag dig dock hellre därom för kärlekens skull -- jag, sådan jag nu är, den gamle Paulus, han som därtill nu är en Kristi Jesu fånge;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, 'ja, jag beder dig för min son, den som jag har fött i min fångenskap, för Onesimus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'som förut var ingalunda var dig till »till gagn», men som nu är både dig och mig till stort gagn[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'Denne sänder jag här tillbaka till dig; och när jag så gör, är det såsom sände jag åstad mitt eget hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Jag hade väl själv velat behålla honom hos mig, så att han å dina vägnar kunde hava betjänat mig i den fångenskap som jag utstår för evangelii skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'Men utan ditt samtycke ville jag intet göra, ty det goda du gjorde skulle ju icke ske såsom av tvång, utan göras av fri vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'När han för en liten tid blev skild från dig, skedde detta till äventyrs just för att du skulle få honom igen för alltid,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, 'nu icke längre såsom en träl, utan såsom något vida mer än en träl: såsom en älskad broder. Detta är han redan för mig i högsta måtto; huru mycket mer då för dig, han, din broder både efter köttet och i Herren!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 17, 'Om du alltså håller mig för din medbroder, så tag emot honom såsom du skulle taga emot mig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 18, 'Har han gjort dig någon orätt, eller är han dig något skyldig, så för upp det på min räkning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 19, 'Jag, Paulus, skriver här med egen hand: »Jag skall själv betala det.» Jag skulle också kunna säga: »För upp det på din räkning.» Ty du har ju en ännu större skuld till mig, nämligen -- dig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 20, 'Ja, min broder, måtte jag »få gagn» av dig i Herren! Vederkvick mitt hjärta i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 21, 'Det är därför att jag är viss om din lydaktighet som jag har skrivit detta till dig. Och jag vet att du kommer att göra ännu mer än jag begär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 22, 'Och så tillägger jag: bered dig på att giva mig härbärge. Jag hoppas nämligen att jag genom edra böner skall bliva skänkt åt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 23, 'Epafras, min medfånge i Kristus Jesus, hälsar dig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 24, 'så göra ock Markus, Aristarkus, Demas och Lukas, mina medarbetare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 25, 'Herrens, Jesu Kristi, nåd vare med eder ande. [1] Det grekiska namnet Onesimos betyder nyttig, gagnelig; på denna namnets betydelse hänsyftas också i v. 20.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, 'Sedan Gud fordom många gånger och på många sätt hade talat till fäderna genom profeterna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'har han nu, på det yttersta av denna tid, talat till oss genom sin Son, som han har insatt till arvinge av allt, genom vilken han ock har skapat världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'Och eftersom denne är hans härlighets återsken och hans väsens avbild och genom sin makts ord bär allt, har han -- sedan han hade utfört en rening från synderna -- satt sig på Majestätets högra sida i höjden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, 'Och han har blivit så mycket större än änglarna som det namn han har ärvt är förmer än deras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'Ty till vilken av änglarna har han någonsin sagt: »Du är min Son, jag har i dag fött dig»? eller: »Jag skall vara hans Fader, och han skall vara min Son»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'Likaså säger han, med tanke på den tid då han åter skall låta den förstfödde inträda i världen: »Och alla Guds änglar skola tillbedja honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'Och medan han om änglarna säger: »Han gör sina änglar till vindar och sina tjänare till eldslågor»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, 'säger han om Sonen: »Gud, din tron förbliver alltid och evinnerligen, och rättvisans spira är ditt rikes spira.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'Du har älskat rättfärdighet och hatat orättfärdighet; därför, o Gud, har din Gud smort dig med glädjens olja mer än dina medbröder»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'så ock: »Du, Herre, lade i begynnelsen jordens grund, och himlarna äro dina händers verk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'de skola förgås, men du förbliver; de skola alla nötas ut såsom en klädnad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'och såsom en mantel skall du hoprulla dem; såsom en klädnad skola de ock bytas om. Men du är densamme, och dina år skola icke hava någon ände.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'Och till vilken av änglarna har han någonsin sagt: »Sätt dig på min högra sida, till dess jag har lagt dina fiender dig till en fotapall»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'Äro de icke allasammans tjänsteandar, som sändas ut till tjänst för deras skull som skola få frälsning till arvedel?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 1, 'Därför böra vi så mycket mer akta på det som vi hava hört, så att vi icke gå förlorade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 2, 'Ty om det ord som talades genom änglar blev beståndande, och all överträdelse och olydnad fick sin rättvisa lön,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 3, 'huru skola då vi kunna undkomma, om vi icke taga vara på en sådan frälsning? -- en frälsning som ju först förkunnades genom Herren och sedan bekräftades för oss av dem som hade hört honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 4, 'varjämte Gud själv ytterligare gav sitt vittnesbörd genom tecken och under och allahanda kraftgärningar, och genom att utdela helig ande, allt efter sin vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 5, 'Ty det var icke under änglars välde som han lade den tillkommande världen, den som vi tala om.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 6, 'Däremot har någon någonstädes betygat och sagt: »Vad är en människa, att du tänker på henne, eller en människoson, att du låter dig vårda om honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 7, 'En liten tid lät du honom vara ringare än änglarna, men krönte honom sedan med härlighet och ära och satte honom till herre över dina händers verk;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 8, 'allt lade du under hans fötter.» När han underlade honom allting, undantog han nämligen intet från att bliva honom underlagt -- om vi ock ännu icke se allting vara honom underlagt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 9, 'Men honom som en liten tid hade blivit gjord »ringare än änglarna», honom, Jesus, se vi för sitt dödslidandes skull hava blivit krönt med härlighet och ära, för att det genom Guds nåd skulle komma alla till godo att han smakade döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 10, 'Ty den för vilkens skull allting är, och genom vilken allting är, honom hövdes det, att när han ville föra många sina barn till härlighet, genom lidanden fullkomna deras frälsnings hövding.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 11, 'Han som helgar och de som bliva helgade hava nämligen alla en och samme Fader. Fördenskull blyges han icke för att kalla dem bröder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 12, 'han säger ju: »Jag skall förkunna ditt namn för mina bröder, mitt i församlingen skall jag prisa dig»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 13, 'så ock: »Jag vill sätta min förtröstan till honom»; så ock: »Se här äro jag och barnen som Gud har givit mig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 14, 'Då nu barnen hade blivit delaktiga av kött och blod, blev ock han på ett liknande sätt delaktig därav, för att han genom sin död skulle göra dens makt om intet, som hade döden i sitt våld, det är djävulen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 15, 'och göra alla dem fria, som av fruktan för döden hela sitt liv igenom hade varit hemfallna till träldom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 16, 'Ty det är ju icke änglar som han tager sig an; det är Abrahams säd som han tager sig an.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 17, 'Därför måste han i allt bliva lik sina bröder, för att han skulle bliva barmhärtig och en trogen överstepräst i sin tjänst inför Gud, till att försona folkets synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 18, 'Ty därigenom att han har lidit, i det han själv blev frestad, kan han hjälpa dem som frestas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 1, 'Därför, I helige bröder, I som haven blivit delaktiga av en himmelsk kallelse, skolen I akta på vår bekännelses apostel och överstepräst, Jesus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 2, 'huru han var trogen mot den som hade insatt honom, likasom Moses var »trogen i hela hans hus».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 3, 'Ty han har blivit aktad värdig så mycket större härlighet än Moses, som uppbyggaren av ett hus åtnjuter större ära än själva huset.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 4, 'Vart och ett hus bygges ju av någon, men Gud är den som har byggt allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 5, 'Och väl var Moses »trogen i hela hans hus», såsom »tjänare», till ett vittnesbörd om vad som framdeles skulle förkunnas;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 6, 'men Kristus var trogen såsom »son», en son satt över hans hus. Och hans hus äro vi, såframt vi intill änden hålla fast vår frimodighet och vår berömmelse i hoppet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 7, 'Så säger den helige Ande: »I dag, om I fån höra hans röst,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 8, 'mån I icke förhärda edra hjärtan, såsom när de förbittrade mig på frestelsens dag i öknen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 9, 'där edra fäder frestade mig och prövade mig, fastän de hade sett mina verk i fyrtio år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 10, 'Därför blev jag förtörnad på det släktet och sade: \'Alltid fara de vilse med sina hjärtan.\' Men de ville icke veta av mina vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 11, 'Så svor jag då i min vrede: De skola icke komma in i min vila.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 12, 'Sen därför till, mina bröder, att icke hos någon bland eder finnes ett ont otroshjärta, så att han avfaller från den levande Guden,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 13, 'utan förmanen varandra alla dagar, så länge det heter »i dag», på det att ingen av eder må bliva förhärdad genom syndens makt att bedraga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 14, 'Ty vi hava blivit delaktiga av Kristus, såframt vi eljest intill änden hålla fast vår första tillförsikt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 15, 'När det nu säges: »I dag, om I fån höra hans röst, mån I icke förhärda edra hjärtan, såsom när de förbittrade mig»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 16, 'vilka voro då de som förbittrade honom, fastän de hade hört hans ord? Var det icke alla de som under Moses hade dragit ut ur Egypten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 17, 'Och vilka voro de som han var förtörnad på i fyrtio år? Var det icke de som hade syndat, de »vilkas kroppar föllo i öknen»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 18, 'Och vilka gällde den ed som han svor, att de »icke skulle komma in i hans vila», vilka, om icke dem som hade varit ohörsamma?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 19, 'Så se vi då att det var för otros skull som de icke kunde komma ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 1, 'Eftersom nu ett löfte att få komma in i hans vila ännu står kvar, må vi alltså med fruktan se till, att icke någon bland eder en gång befinnes hava blivit efter på vägen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 2, 'Ty det glada budskapet hava vi mottagit såväl som de; men för dem blev det löftesord de fingo höra till intet gagn, eftersom det icke genom tron hade blivit upptaget i dem som hörde det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 3, 'Vi som hava kommit till tro, vi få ju komma in i vilan. Det heter också: »Så svor jag då i min vrede: De skola icke komma in i min vila», och detta fastän hans verk stodo där färdiga allt ifrån den tid då världen var skapad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 4, 'Ty om den sjunde dagen heter det någonstädes så: »Och Gud vilade på sjunde dagen från alla sina verk»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 5, 'här åter heter det: »De skola icke komma in i min vila.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 6, 'Eftersom det alltså står kvar att några skola få komma in i den, och eftersom de som först mottogo det glada budskapet för sin ohörsamhets skull icke kommo ditin,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 7, 'så bestämmer han genom ordet »i dag» åter en viss dag, nu då han så lång tid därefter säger hos David, såsom förut är nämnt: »I dag, om I fån höra hans röst, mån I icke förhärda edra hjärtan.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 8, 'Ty om Josua hade fört dem in i vilan, så skulle Gud icke hava talat om en annan, senare dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 9, 'Alltså står en sabbatsvila ännu åter för Guds folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 10, 'Ty den som har kommit in i hans vila, han har funnit vila från sina verk, likasom Gud från sina.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 11, 'Så låtom oss nu med all flit sträva efter att få komma in i den vilan, för att ingen må, såsom de, falla och bliva ett varnande exempel på ohörsamhet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 12, 'Ty Guds ord är levande och kraftigt och skarpare än något tveeggat svärd, och tränger igenom, så att det åtskiljer själ och ande, märg och ben; och det är en domare över hjärtats uppsåt och tankar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 13, 'Intet skapat är fördolt för honom, utan allt ligger blottat och uppenbart för hans ögon; och inför honom skola vi göra räkenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 14, 'Eftersom vi nu hava en stor överstepräst, som har farit upp genom himlarna, nämligen Jesus, Guds Son, så låtom oss hålla fast vid bekännelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 15, 'Ty vi hava icke en sådan överstepräst som ej kan hava medlidande med våra svagheter, utan en som har varit frestad i allting, likasom vi, dock utan synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 16, 'Låtom oss därför med frimodighet gå fram till nådens tron, för att vi må undfå barmhärtighet och finna nåd, till hjälp i rätt tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 1, 'Ty var och en som skall bliva överstepräst uttages bland människor och tillsättes för att till människors bästa göra tjänst inför Gud, genom att frambära gåvor och offer för synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 2, 'Och han kan hava undseende med de okunniga och vilsefarande, just därför att han själv är behäftad med svaghet');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 3, 'och, för denna sin svaghets skull, måste offra för sina egna synder likaväl som för folkets.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 4, 'Och ingen tager sig själv denna värdighet, utan han måste, såsom Aron, kallas därtill av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 5, 'Så tog sig icke heller Kristus själv äran att bliva överstepräst, utan den äran tillföll honom genom den som sade till honom: »Du är min Son, jag har i dag fött dig»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 6, 'likasom han ock på ett annat ställe säger: »Du är en präst till evig tid, efter Melkisedeks sätt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 7, 'Och med starkt rop och tårar frambar han, under sitt kötts dagar, böner och åkallan till den som kunde frälsa honom från döden; och han blev bönhörd och tagen ur sin ångest.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 8, 'Så lärde han, fastän han var »Son», lydnad genom sitt lidande;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 9, 'och när han hade blivit fullkomnad, blev han, för alla dem som äro honom lydiga, upphovet till evig frälsning');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 10, 'och hälsades av Gud såsom överstepräst »efter Melkisedeks sätt».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 11, 'Härom hava vi mycket att säga, mycket som är svårt att göra tydligt i ord, eftersom I haven blivit så tröga till att höra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 12, 'Ty fastän det kunde vara på tiden att I själva voren lärare, behöves det snarare att man nu åter undervisar eder i de allra första grunderna av Guds ord; det har kommit därhän med eder, att I behöven mjölk i stället för stadig mat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 13, 'Men om någon är sådan att han ännu måste leva av mjölk, då är han oskicklig att förstå en undervisning om rättfärdighet; han är ju ännu ett barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 14, 'Ty den stadiga maten tillhör de fullmogna, dem som genom vanan hava sina sinnen övade till att skilja mellan gott och ont.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 1, 'Låtom oss därför lämna bakom oss de första grunderna av läran om Kristus och gå framåt mot det som hör till fullkomningen; låtom oss icke åter lägga grunden med bättring från döda gärningar och med tro på Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 2, 'med undervisning om dop och handpåläggning, om de dödas uppståndelse och en evig dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 3, 'Ja, detta vilja vi göra, såframt Gud eljest tillstädjer det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 4, 'Ty dem till vilka ljuset en gång har kommit, och som hava smakat den himmelska gåvan och blivit delaktiga av helig ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 5, 'och som hava fått smaka det goda gudsordet och den tillkommande tidsålderns krafter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 6, 'men som ändå hava avfallit -- dem är det omöjligt att återföra till ny bättring, eftersom de på nytt korsfästa Guds Son åt sig och utsätta honom för bespottelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 7, 'Det är ju så, att den jord som indricker regnet, när det titt och ofta strömmar ned däröver, och som framalstrar växter, dem till gagn för vilkas räkning den brukas, den jorden får välsignelse från Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 8, 'Den åter som bär törne och tistel, den är ingenting värd och är förbannelsen nära, och slutet bliver att den avbrännes med eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 9, 'Men i fråga om eder, I älskade, äro vi vissa om vad bättre är, och vad som länder till frälsning, om vi ock nu tala på detta sätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 10, 'Ty Gud är icke orättvis, så att han förgäter vad I haven verkat, och vilken kärlek I bevisaden mot hans namn, då I tjänaden de heliga, såsom I ännu gören.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 11, 'Men vår åstundan är att var och en av eder visar samma nit att intill änden bevara full visshet i sitt hopp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 12, 'så att I icke bliven tröga, utan bliven efterföljare åt dem som genom tro och tålamod få till arvedel vad utlovat är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 13, 'Ty när Gud gav löftet åt Abraham, svor han vid sig själv -- eftersom han icke hade någon högre att svärja vid --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 14, 'och sade: »Sannerligen, jag skall rikligen välsigna dig och storligen föröka dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 15, 'Och när denne tåligt förbidade, fick han så vad utlovat var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 16, 'Människor svärja ju vid den som är högre än de, och eden tjänar dem till bekräftelse och gör en ände på all tvist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 17, 'Därför, när Gud ville för dem som skulle få till arvedel vad löftet innebar ännu kraftigare bevisa oryggligheten av sitt rådslut, lade han därtill en ed.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 18, 'Så skulle vi genom två oryggliga utsagor, i vilka Gud omöjligen kunde ljuga, undfå en kraftig uppmuntran, vi som hava sökt vår räddning i att hålla fast vid det hopp som ligger framför oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 19, 'I det hoppet hava vi ett säkert och fast själens ankare, som når innanför förlåten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 20, 'dit Jesus, såsom vår förelöpare, har gått in för oss, i det han blev en överstepräst »efter Melkisedeks sätt, till evig tid».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 1, 'Denne Melkisedek, som var konung i Salem och präst åt Gud den Högste -- han som gick Abraham till mötes, när denne var stadd på återvägen, sedan han hade slagit konungarna, och som välsignade honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 2, 'varvid Abraham å sin sida gav honom tionde av allt; denne, som när man uttyder vad han kallas, är först och främst »rättfärdighetens konung», men därjämte ock »Salems konung», det är »fridens konung»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 3, 'denne som står där utan fader, utan moder och utan släktledning, utan begynnelse på sina dagar och utan ände på sitt liv och likställes med Guds Son -- denne förbliver en präst för beständigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 4, 'Och sen nu huru stor han är, denne åt vilken vår stamfader Abraham gav tionde av det förnämsta bytet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 5, 'Medan de av Levi söner, som undfå prästämbetet, hava befallning att enligt lagen taga tionde av folket, det är av sina bröder, fastän dessa hava utgått från Abrahams länd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 6, 'tog denne, som icke var av deras släkt, tionde av Abraham och välsignade honom, densamme som hade fått löftena.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 7, 'Nu lär ingen kunna neka att det plägar vara den ringare som mottager välsignelse av den som står högre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 8, 'Och medan det här är dödliga människor som taga tionde, är det där en som får det vittnesbördet att han förbliver levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 9, 'Genom Abraham har på visst sätt också Levi, som tager tionde, fått giva tionde;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 10, 'ty han var ännu i sin stamfaders länd, när Melkisedek gick denne till mötes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 11, 'Vore det nu så, att fullkomning kunde vinnas genom det levitiska prästadömet -- och på detta var ju folkets lagstiftning byggd -- varför hade det då behövts att en präst av annat slag, »efter Melkisedeks sätt», skulle uppstå, en som icke nämnes »efter Arons sätt»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 12, '(Om prästadömet förändras, måste ju med nödvändighet också lagen förändras.)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 13, 'Den som detta säges om hörde nämligen till en annan stam, en stam från vilken ingen har utgått, som har gjort tjänst vid altaret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 14, 'Ty det är en känd sak att han som är vår Herre har trätt fram ur Juda stam; och med avseende på den har Moses icke talat något om präster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 15, 'Och ännu mycket tydligare blir detta, då nu en präst av annat slag uppstår, lik Melkisedek däri,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 16, 'att han har blivit präst icke på grund av en lag som stadgar härstamning efter köttet, utan på grund av en kraft som kommer av oförgängligt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 17, 'Han får nämligen det vittnesbördet: »Du är en präst till evig tid, efter Melkisedeks sätt.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 18, 'Så upphäves nu visserligen en föregående stadga, därför att den var svag och gagnlös --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 19, 'eftersom lagen icke kunde åstadkomma något fullkomligt -- men ett bättre hopp sättes i stället, ett hopp genom vilket vi få nalkas Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 20, 'Och i så måtto som detta icke har kommit till stånd utan edlig bekräftelse -- det är nämligen så, att medan de andra hava blivit präster utan edlig bekräftelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 21, 'har denne blivit det med sådan bekräftelse, genom den som sade till honom: »Herren har svurit och skall icke ångra sig: \'Du är en präst till evig tid\'» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 22, 'i så måtto är också det förbund bättre, som har Jesus till löftesman.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 23, 'Och medan de förra prästerna hava måst bliva flera, därför att de genom döden hindrades från att förbliva i sin tjänst,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 24, 'har däremot denne ett oförgängligt prästadöme, eftersom han förbliver »till evig tid».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 25, 'Därför kan han ock till fullo frälsa dem som genom honom komma till Gud, ty han lever alltid för att mana gott för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 26, 'En sådan överstepräst hövdes oss också att hava, en som vore helig, oskyldig, obesmittad, skild från syndare och upphöjd över himmelen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 27, 'en som icke var dag behövde frambära offer, såsom de andra översteprästerna, först för sina egna synder och sedan för folkets; detta gjorde han nämligen en gång för alla, när han offrade sig själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 28, 'Ty lagen insätter till överstepräster människor som äro behäftade med svaghet, men det löftesord, som efter lagens utgivande gavs under edlig bekräftelse, insätter en »Son» som är fullkomnad »till evig tid».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 1, 'Men en huvudpunkt i vad vi vilja säga är detta: Vi hava en överstepräst som sitter på högra sidan om Majestätets tron i himmelen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 2, 'för att göra tjänst i det allraheligaste, i det sannskyldiga tabernaklet, vilket Herren har upprättat, och icke någon människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 3, 'Ty var och en som bliver överstepräst tillsättes för att frambära gåvor och offer; därför måste också denne hava något att frambära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 4, 'Om han nu vore på jorden, så vore han icke ens präst, då andra där finnas, som efter lagens bud hava att frambära gåvorna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 5, 'i det att de tjäna i den helgedom som är en avbild och en skugga av den himmelska. Om en sådan fick ock Moses befallning genom en uppenbarelse, när han skulle förfärdiga tabernaklet. »Se till», heter det, »att du gör allt efter den mönsterbild som har blivit dig visad på berget.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 6, 'Men nu har denne fått ett så mycket förnämligare ämbete, som han är medlare för ett bättre förbund, vars ordning vilar på bättre löften.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 7, 'Ty om det förra förbundet hade varit utan brist, så skulle väl plats icke hava sökts för ett annat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 8, 'Men nu förebrår Gud dem och säger: »Se, dagar skola komma, säger Herren, då jag skall sluta ett nytt förbund med Israels hus och med Juda hus;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 9, 'icke ett sådant förbund som det jag gjorde med deras fäder, på den dag då jag tog dem vid handen till att föra dem ut ur Egyptens land. Ty de förblevo icke i mitt förbund, och därför frågade icke heller jag efter dem, säger Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 10, 'Nej, detta är det förbund som jag skall sluta med Israels hus i kommande dagar, säger Herren: Jag skall lägga mina lagar i deras sinnen, och i deras hjärtan skall jag skriva dem, och jag skall vara deras Gud, och de skola vara mitt folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 11, 'Då skall den ene medborgaren aldrig behöva undervisa den andre, icke den ene brodern den andre och säga: \'Lär känna Herren\'; ty de skola alla känna mig, från den minste bland dem till den störste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 12, 'Ty jag skall i nåd förlåta deras missgärningar, och deras synder skall jag aldrig mer komma ihåg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 13, 'När han säger »ett nytt förbund», har han därmed givit till känna att det förra är föråldrat; men det som föråldras och bliver gammalt, det är nära att försvinna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 1, 'Nu hade visserligen också det förra förbundet sina gudstjänststadgar och sin jordiska helgedom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 2, 'Ty i tabernaklet inrättades ett främre rum, vari stodo ljusstaken och bordet med skådebröden; och detta rum kallas »det heliga».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 3, 'Men bakom den andra förlåten var ett annat rum i tabernaklet, ett som kallas »det allraheligaste»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 4, 'med ett gyllene rökelsealtare och förbundets ark, på alla sidor överdragen med guld. I denna förvarades ett gyllene ämbar med mannat, så ock Arons stav, som hade grönskat, och därtill förbundets tavlor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 5, 'Därovanpå stodo härlighetskeruber, som överskyggde nådastolen. Men om vart särskilt av dessa föremål är nu icke tillfälle att tala.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 6, 'Så blev detta inrättat. Och i det främre tabernakelrummet gå prästerna ständigt in och förrätta vad som hör till gudstjänsten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 7, 'men i det andra går allenast översteprästen in en gång om året, och då aldrig utan blod; och han frambär blodet för sig själv och för folkets ouppsåtliga synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 8, 'Därmed giver den helige Ande till känna att vägen till det allraheligaste ännu icke har blivit uppenbarad, så länge det främre tabernakelrummet fortfarande äger bestånd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 9, 'Ty detta är en sinnebild som avser den nuvarande tiden, och i enlighet härmed frambäras gåvor och offer, vilka dock icke kunna fullkomna, efter samvetets krav, den som förrättar sin gudstjänst,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 10, 'utan allenast äro utvärtes stadgar -- de såväl som föreskrifterna om mat och dryck och allahanda tvagningar -- stadgar pålagda intill dess tiden vore inne för en bättre ordning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 11, 'Men Kristus kom såsom överstepräst för det tillkommande goda; och genom det större och fullkomligare tabernakel som icke är gjort med händer, det är, som icke tillhör den skapelse som nu är,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 12, 'gick han, icke med bockars och kalvars blod, utan med sitt eget blod, en gång för alla in i det allraheligaste och vann en evig förlossning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 13, 'Ty om redan blod av bockar och tjurar och aska av en ko, stänkt på dem som hava blivit orenade, helgar till utvärtes renhet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 14, 'huru mycket mer skall icke Kristi blod -- då han nu genom evig ande har framburit sig själv såsom ett felfritt offer åt Gud -- rena våra samveten från döda gärningar till att tjäna den levande Guden!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 15, 'Så är han medlare för ett nytt förbund, på det att de som voro kallade skulle få det utlovade eviga arvet, därigenom att en led döden till förlossning ifrån överträdelserna under det förra förbundet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 16, 'Ty där ett testamente finnes, där måste det styrkas att den som har gjort testamentet är död.[1]');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 17, 'Först genom döden bliver ju ett testamente giltigt, varemot det icke äger gällande kraft, så länge den som har gjort det ännu lever.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 18, 'Därför har icke heller det förra förbundet blivit invigt utan blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 19, 'Ty sedan alla buden, såsom de lyda i lagen, hade blivit av Moses kungjorda för allt folket, tog han blod av kalvar och bockar, tillika med vatten och röd ull och isop, och bestänkte såväl själva boken som allt folket');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 20, 'och sade: »Detta är förbundets blod, det förbunds som Gud har stadgat för eder.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 21, 'Likaledes stänkte han ock blod på tabernaklet och på alla de ting som hörde till gudstjänsten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 22, 'Så renas enligt lagen nästan allting med blod, och utan att blod utgjutes gives ingen förlåtelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 23, 'Alltså var det nödvändigt att avbilderna av de himmelska tingen renades genom sådana medel; men de himmelska tingen själva måste renas genom bättre offer än dessa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 24, 'Ty Kristus har icke gått in i ett allraheligaste som är gjort med händer, och som allenast är en efterbildning av det sannskyldiga, utan han har gått in i själva himmelen, för att nu träda fram inför Guds ansikte, oss till godo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 25, 'Ej heller har han gått ditin, för att många gånger offra sig själv, såsom översteprästen år efter år går in i det allraheligaste, med blod som icke är hans eget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 26, 'Han hade annars måst lida många gånger allt ifrån världens begynnelse. I stället har han uppenbarats en enda gång, nu vid tidernas ände, för att genom offret av sig själv utplåna synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 27, 'Och såsom det är människorna förelagt att en gång dö och sedan dömas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 28, 'så skall Kristus, sedan han en gång har blivit offrad för att bära mångas synder, för andra gången, utan synd, låta sig ses av dem som bida efter honom, till frälsning. [1] Grundtexten har i v. 15 f. samma uttryck för testamente och förbund.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 1, 'Ty lagen innehåller en skugga av det tillkommande goda, men framställer icke tingen i deras verkliga gestalt; därför kan den aldrig genom de offer som ständigt frambäras, år efter år på samma sätt, fullkomna dem som framträda med sådana.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 2, 'Annars skulle man väl hava upphört att offra, då ju de som så förrättade sin gudstjänst icke mer kunde veta med sig någon synd, sedan de en gång hade blivit renade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 3, 'Men just i offren ligger en årlig påminnelse om synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 4, 'Ty omöjligt är att tjurars och bockars blod skulle kunna borttaga synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 5, 'Därför säger han vid sitt inträde i världen: »Slaktoffer och spisoffer begärde du icke, men en kropp beredde du åt mig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 6, 'i brännoffer och syndoffer fann du icke behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 7, 'Då sade jag: \'Se, jag kommer -- i bokrullen är skrivet om mig -- för att göra din vilja, o Gud.\'»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 8, 'Sedan han först har sagt: »Slaktoffer och spisoffer, brännoffer och syndoffer begärde du icke, och i sådana fann du icke behag» -- och dock frambäras de efter lagen --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 9, 'säger han vidare: »Se, jag kommer för att göra din vilja.» Så tager han bort det förra, för att sätta det andra i stället.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 10, 'Och i kraft av denna »vilja» hava vi blivit helgade, därigenom att Jesu Kristi »kropp» en gång för alla har blivit offrad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 11, 'Och alla andra präster stå dag efter dag i sin tjänst och frambära gång på gång enahanda offer, som dock aldrig kunna borttaga synder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 12, 'men sedan denne har framburit ett enda offer för synderna, sitter han för beständigt på Guds högra sida');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 13, 'och väntar nu allenast på att »hans fiender skola bliva lagda honom till en fotapall».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 14, 'Ty med ett enda offer har han för beständigt fullkomnat dem som bliva helgade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 15, 'Härom vittnar jämväl den helige Ande för oss. Ty sedan Herren hade sagt:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 16, '»Detta är det förbund som jag skall sluta med dem i kommande dagar», säger han: »Jag skall lägga mina lagar i deras hjärtan, och i deras sinnen skall jag skriva dem»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 17, 'och vidare: »Deras synder och deras orättfärdiga gärningar skall jag aldrig mer komma ihåg.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 18, 'Men där förlåtelse för dessa är given, där behöves icke mer något offer för synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 19, 'Eftersom vi nu, mina bröder, hava en fast tillförsikt att få gå in i det allraheligaste i och genom Jesu blod,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 20, 'i det att han åt oss har invigt en ny och levande väg ditin genom förlåten -- det är genom sitt kött --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 21, 'och eftersom vi hava en stor överstepräst över Guds hus,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 22, 'så låtom oss med uppriktiga hjärtan gå fram i full trosvisshet, bestänkta till våra hjärtan och därigenom renade från ett ont samvete, och till kroppen tvagna med rent vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 23, 'Låtom oss oryggligt hålla fast vid hoppets bekännelse, ty den som har givit oss löftet, han är trofast.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 24, 'Och låtom oss akta på varandra för att uppliva varandra till kärlek och goda gärningar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 25, 'låtom oss icke övergiva vår församlingsgemenskap, såsom somliga hava för sed, utan må vi förmana varandra -- detta så mycket mer som I sen huru »dagen» nalkas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 26, 'Ty om vi med berått mod synda, sedan vi hava undfått kunskapen om sanningen, så återstår icke mer något offer för våra synder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 27, 'utan allenast en förskräcklig väntan på dom och glöden av en eld som skall förtära motståndarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 28, 'Den som föraktar Moses\' lag, han skall »efter två eller tre vittnens utsago» dödas utan barmhärtighet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 29, 'huru mycket svårare straff tron I icke då att den skall anses värd, som förtrampar Guds Son och aktar förbundets blod för orent -- det i vilket han har blivit helgad -- och som smädar nådens Ande!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 30, 'Vi veta ju vem han är som sade: »Min är hämnden; jag skall vedergälla det», och åter: »Herren skall döma sitt folk.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 31, 'Det är förskräckligt att falla i den levande Gudens händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 32, 'Men kommen ihåg den förgångna tiden, då I, sedan ljuset hade kommit till eder, ståndaktigt uthärdaden mången lidandets kamp');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 33, 'och dels själva genom smälek och misshandling bleven gjorda till ett skådespel för världen, dels leden med andra som fingo genomgå sådant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 34, 'Ty I haven delat de fångnas lidanden och med glädje underkastat eder att bliva berövade edra ägodelar. I vissten nämligen att I haven en egendom som är bättre och bliver beståndande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 35, 'Så kasten nu icke bort eder frimodighet, som ju har med sig stor lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 36, 'I behöven nämligen ståndaktighet för att kunna göra Guds vilja och få vad utlovat är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 37, 'Ty »ännu en helt liten tid, så kommer den som skall komma, och han skall icke dröja;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 38, 'och min rättfärdige skall leva av tro. Men om någon drager sig undan, så finner min själ icke behag i honom».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 39, 'Dock, vi höra icke till dem som draga sig undan, sig själva till fördärv; vi höra till dem som tro och så vinna sina själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 1, 'Men tron är en fast tillförsikt om det som man hoppas, en övertygelse om ting som man icke ser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 2, 'På grund av den fingo ju de gamle sitt vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 3, 'Genom tron förstå vi att världen har blivit fullbordad genom ett ord av Gud, så att det man ser icke har blivit till av något synligt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 4, 'Genom tron frambar Abel åt Gud ett bättre offer än Kain, och genom den fick han det vittnesbördet att han var rättfärdig, i det Gud själv gav vittnesbörd om hans offergåvor; och genom tron talar han ännu, fastän han är död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 5, 'Genom tron togs Enok bort, för att han icke skulle se döden; och »man såg honom icke mer, ty Gud tog honom bort». Förrän han togs bort, fick han nämligen det vittnesbördet att han hade täckts Gud;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 6, 'men utan tro är det omöjligt att täckas Gud. Ty den som vill komma till Gud måste tro att han är till, och att han lönar dem som söka honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 7, 'Genom tron var det som Noa, sedan han hade fått uppenbarelse om något som man ännu icke såg, i from förtröstan byggde en ark för att rädda sitt hus; och genom den blev han världen till dom och fick till arvedel den rättfärdighet som hör tron till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 8, 'Genom tron var Abraham lydig, när han blev kallad, och han drog så ut till det land som han skulle få till arvedel; han drog ut, fastän han icke visste vart han skulle komma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 9, 'Genom tron bosatte han sig såsom främling i det utlovade landet, likasom i ett främmande land, och bodde i tält med Isak och Jakob, som voro hans medarvingar till samma löfte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 10, 'Ty han väntade på »staden med de fasta grundvalarna», vars byggmästare och skapare är Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 11, 'Genom tron fick jämväl Sara, fastän överårig, kraft att bliva stammoder för en avkomma, i det hon höll den för trovärdig, som hade givit löftet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 12, 'Därför föddes ock av en och samme man, en som var så gott som död, avkomlingar »så talrika som stjärnorna på himmelen och som sanden på havets strand, som man icke kan räkna».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 13, 'I tron dogo alla dessa, innan de ännu hade fått vad utlovat var; de hade allenast sett det i fjärran och hade hälsat det och bekänt sig vara »gäster och främlingar» på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 14, 'De som så tala giva ju därmed till känna att de söka efter ett fädernesland.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 15, 'Och om de hade menat det land som de hade gått ut ifrån, så hade de haft tillfälle att vända tillbaka dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 16, 'Men nu stod deras håg till ett bättre, nämligen det himmelska. Därför blyges icke Gud för att kallas deras Gud; ty han har berett åt dem en stad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 17, 'Genom tron var det som Abraham frambar Isak såsom offer, när han blev satt på prov; ja, sin ende son frambar han såsom offer, han som hade mottagit löftena,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 18, 'han till vilken det hade blivit sagt: »Genom Isak är det som säd skall uppkallas efter dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 19, 'Ty han tänkte på att Gud var mäktig att till och med uppväcka från de döda; från de döda fick han honom ock tillbaka, liknelsevis talat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 20, 'Genom tron gav jämväl Isak sin välsignelse åt Jakob och Esau för kommande tider.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 21, 'Genom tron välsignade den döende Jakob Josefs båda söner och tillbad, lutad mot ändan av sin stav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 22, 'Genom tron talade Josef, när han låg för döden, om Israels barns uttåg och gav befallning om vad som skulle göras med hans ben.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 23, 'Genom tron blev Moses vid sin födelse dold av sina föräldrar och hölls av dem gömd i tre månader, eftersom de sågo att »det var ett vackert barn»; och de läto icke förskräcka sig av konungens påbud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 24, 'Genom tron försmådde Moses, sedan han hade blivit stor, att kallas Faraos dotterson.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 25, 'Han ville hellre utstå lidande med Guds folk än för en kort tid leva i syndig njutning;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 26, 'han höll nämligen Kristi smälek för en större rikedom än Egyptens skatter, ty han hade sin blick riktad på lönen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 27, 'Genom tron övergav han Egypten, utan att låta förskräcka sig av konungens vrede; ty därigenom att han likasom såg den Osynlige kunde han härda ut.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 28, 'Genom tron har han ock förordnat om påsken och blodbestrykningen, på det att »Fördärvaren», som förgjorde allt förstfött, icke skulle komma vid dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 29, 'Genom tron drogo de fram genom Röda havet likasom på torra landet; men när egyptierna försökte gå samma väg, dränktes de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 30, 'Genom tron föllo Jerikos murar, sedan man i sju dagar hade gått runt omkring dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 31, 'Genom tron undgick skökan Rahab att förgås tillsammans med de ohörsamma, eftersom hon hade tagit emot spejarna såsom vänner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 32, 'Och vad skall jag nu vidare säga? Tiden bleve mig ju för kort, ifall jag skulle förtälja om Gideon, Barak, Simson och Jefta, om David och Samuel och profeterna,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 33, 'om dessa som genom tron besegrade konungariken, övade rättfärdighet, fingo löften uppfyllda, tillstoppade lejons gap,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 34, 'dämpade eldens kraft, undkommo svärdets egg, blevo starka från att hava varit svaga, blevo väldiga i krig och drevo främmande härar på flykten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 35, 'Kvinnor funnos som fingo igen sina döda genom deras uppståndelse. Andra läto sig läggas på sträckbänk och ville icke taga emot någon befrielse, i hopp om en så mycket bättre uppståndelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 36, 'Andra åter underkastade sig begabberi och gisselslag, därtill ock bojor och fängelse;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 37, 'de blevo stenade, marterade, söndersågade, dödade med svärd. De gingo omkring höljda i fårskinn och gethudar, nödställda, misshandlade, plågade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 38, 'dessa människor som världen icke var värdig att hysa; de irrade omkring i öknar och bergstrakter och levde i hålor och jordkulor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 39, 'Och fastän alla dessa genom tron hava fått sitt vittnesbörd, undfingo de ändå icke vad utlovat var;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 40, 'ty Gud hade åt oss utsett något bättre, på det att de icke oss förutan skulle bliva fullkomnade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 1, 'Alltså, då vi nu hava omkring oss en så stor hop av vittnen, må ock vi lägga av allt som är oss till hinder, och särskilt synden, som så hårt omsnärjer oss, och med uthållighet löpa framåt i den tävlingskamp som är oss förelagd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 2, 'Och må vi därvid se på Jesus, trons hövding och fullkomnare, på honom, som i stället för att taga den glädje som låg framför honom, utstod korsets lidande och aktade smäleken för intet, och som nu sitter på högra sidan om Guds tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 3, 'Ja, på honom, som har utstått så mycken gensägelse av syndare, på honom mån I tänka, så att I icke tröttnen och uppgivens i edra själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 4, 'Ännu haven I icke stått emot ända till blods, i eder kamp mot synden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 5, 'Och I haven alldeles förgätit den förmaningens röst som talar med eder, såsom man talar med söner: »Min son, förkasta icke Herrens aga, och giv dig icke över, när du tuktas av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 6, 'Ty den Herren älskar, den agar han, och han straffar med riset var son som han har kär.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 7, 'Det är till eder fostran som I fån utstå lidande; Gud handlar med eder såsom med söner. Ty var finnes den son som icke bliver agad av sin fader?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 8, 'Om I lämnadens utan aga, medan alla andra finge sin del därav, så voren I oäkta söner och icke äkta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 9, 'Vidare: vi hava haft köttsliga fäder, som agade oss, och vi visade försyn för dem; skola vi då icke mycket mer vara underdåniga andarnas Fader, så att vi få leva?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 10, 'De förra agade oss ju för en kort tid, såsom det syntes dem gott, men denne agar oss för vårt verkliga gagn, för att vi skola få del av hans helighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 11, 'Väl synes alla aga för tillfället vara icke till glädje, utan till sorg; men efteråt bär den, för dem som hava blivit fostrade därmed, en fridsfrukt som är rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 12, 'Alltså: »stärken maktlösa händer och vacklande knän»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 13, 'och »gören räta stigar för edra fötter», så att den fot som haltar icke vrides ur led, utan fastmer bliver botad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 14, 'Faren efter frid med alla och efter helgelse; ty utan helgelse får ingen se Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 15, 'Och sen till, att ingen går miste om Guds nåd, och att ingen giftig rot skjuter skott och bliver till fördärv, så att menigheten därigenom bliver besmittad;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 16, 'sen till, att ingen är en otuktig människa eller ohelig såsom Esau, han som för en enda maträtt sålde sin förstfödslorätt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 17, 'I veten ju att han ock sedermera blev avvisad, när han på grund av arvsrätt ville få välsignelsen; han kunde nämligen icke vinna någon ändring, fastän han med tårar sökte därefter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 18, 'Ty I haven icke kommit till ett berg som man kan taga på, ett som »brann i eld», icke till »töcken och mörker» och storm,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 19, 'icke till »basunljud» och till en »röst» som talade så, att de som hörde den bådo att intet ytterligare skulle talas till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 20, 'Ty de kunde icke härda ut med det påbud som gavs dem: »Också om det är ett djur som kommer vid berget, skall det stenas.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 21, 'Och så förskräcklig var den syn man såg, att Moses sade: »Jag är förskräckt och bävar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 22, 'Nej, I haven kommit till Sions berg och den levande Gudens stad, det himmelska Jerusalem, och till änglar i mångtusental,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 23, 'till en högtidsskara och församling av förstfödda söner som äro uppskrivna i himmelen, och till en domare som är allas Gud, och till fullkomnade rättfärdigas andar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 24, 'och till ett nytt förbunds medlare, Jesus, och till ett stänkelseblod som talar bättre än Abels blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 25, 'Sen till, att I icke visen ifrån eder honom som talar. Ty om dessa icke kunde undfly, när de visade ifrån sig honom som här på jorden kungjorde Guds vilja, huru mycket mindre skola då vi kunna det, om vi vända oss ifrån honom som kungör sin vilja från himmelen?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 26, 'Hans röst kom då jorden att bäva; men nu har han lovat och sagt: »Ännu en gång skall jag komma icke allenast jorden, utan ock himmelen att bäva.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 27, 'Dessa ord »ännu en gång» giva till känna att de ting, som kunna bäva, skola, eftersom de äro skapade, bliva förvandlade, för att de ting, som icke kunna bäva, skola bliva beståndande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 28, 'Därför, då vi nu skola undfå ett rike som icke kan bäva, så låtom oss vara tacksamma. På det sättet tjäna vi Gud, honom till behag, med helig fruktan och räddhåga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 29, 'Ty »vår Gud är en förtärande eld».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 1, 'Förbliven fasta i broderlig kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 2, 'Förgäten icke att bevisa gästvänlighet; ty genom gästvänlighet hava några, utan att veta det, fått änglar till gäster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 3, 'Tänken på dem som äro fångna, likasom voren I deras medfångar, och tänken på dem som utstå misshandling, eftersom också I själva haven en kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 4, 'Äktenskapet må hållas i ära bland alla, och äkta säng bevaras obesmittad; ty otuktiga människor och äktenskapsbrytare skall Gud döma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 5, 'Varen i eder handel och vandel fria ifrån penningbegär; låten eder nöja med vad I haven. Ty han har själv sagt: »Jag skall icke lämna dig eller övergiva dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 6, 'Alltså kunna vi dristigt säga: »Herren är min hjälpare, jag skall icke frukta; vad kunna människor göra mig?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 7, 'Tänken på edra lärare, som hava talat Guds ord till eder; sen huru de slutade sin levnad, och efterföljen deras tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 8, 'Jesus Kristus är densamme i går och i dag, så ock i evighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 9, 'Låten eder icke vilseföras av allahanda främmande läror. Ty det är gott att bliva styrkt i sitt hjärta genom nåd och icke genom offermåltider; de som hava befattat sig med sådant hava icke haft något gagn därav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 10, 'Vi hava ett altare, från vilket de som göra tjänst vid tabernaklet icke hava rätt att få något att äta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 11, 'Det är ju så, att kropparna av de djur, vilkas blod översteprästen bär in i det allraheligaste till försoning för synd, »brännas upp utanför lägret».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 12, 'Därför var det ock utanför stadsporten som Jesus utstod sitt lidande, för att han genom sitt eget blod skulle helga folket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 13, 'Låtom oss alltså gå ut till honom »utanför lägret» och bära hans smälek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 14, 'Ty vi hava här ingen varaktig stad, utan söka efter den tillkommande staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 15, 'Så låtom oss då genom honom alltid till Gud »frambära ett lovets offer», det är »en frukt ifrån läppar» som prisa hans namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 16, 'Men förgäten icke att göra gott och dela med eder, ty sådana offer har Gud behag till.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 17, 'Varen edra lärare hörsamma, och böjen eder för dem; ty de vaka över edra själar, eftersom de skola avlägga räkenskap. Må de då kunna göra det med glädje, och icke med suckan, ty detta vore eder icke nyttigt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 18, 'Bedjen för oss; ty vi tro oss hava ett gott samvete, eftersom vi söka att i alla stycken föra en god vandel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 19, 'Och jag uppmanar eder att göra detta, så mycket mer som jag hoppas att därigenom dess snarare bliva återgiven åt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 20, 'Men fridens Gud, som från de döda har återfört vår Herre Jesus, vilken genom ett evigt förbunds blod är den store herden för fåren,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 21, 'han fullkomne eder i allt vad gott är, så att I gören hans vilja; och han verke i oss vad som är välbehagligt inför honom, genom Jesus Kristus. Honom tillhör äran i evigheternas evigheter. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 22, 'Jag beder eder, mina bröder: tagen icke illa upp dessa förmaningens ord; jag har ju ock skrivit till eder helt kort.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 23, 'Veten att vår broder Timoteus har blivit lösgiven. Om han snart kommer hit, vill jag tillsammans med honom besöka eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 24, 'Hälsen alla edra lärare och alla de heliga. De italiska bröderna hälsa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 25, 'Nåd vare med eder alla.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, 'Jakob, Guds och Herrens, Jesu Kristi, tjänare, hälsar de tolv stammar som bo kringspridda bland folken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'Mina bröder, hållen det för idel glädje, när I kommen i allahanda frestelser,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'och veten, att om eder tro håller provet, så verkar detta ståndaktighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'Och låten ståndaktigheten hava med sig fullkomlighet i gärning, så att I ären fullkomliga, utan fel och utan brist i något stycke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, 'Men om någon av eder brister i vishet, så må han utbedja sig sådan från Gud, som giver åt alla villigt och utan hårda ord, och den skall bliva honom given.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'Men han bedje i tro, utan att tvivla; ty den som tvivlar är lik havets våg, som drives omkring av vinden och kastas hit och dit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'En sådan människa må icke tänka att hon skall få något från Herren --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, 'en människa med delad håg, en som går ostadigt fram på alla sina vägar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Den broder som lever i ringhet berömme sig av sin höghet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'Den åter som är rik berömme sig av sin ringhet, ty såsom gräsets blomster skall han förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 11, 'Solen går upp med sin brännande hetta och förtorkar gräset, och dess blomster faller av, och dess fägring förgår; så skall ock den rike förvissna mitt i sin ävlan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 12, 'Salig är den man som är ståndaktig i frestelsen; ty när han har bestått sitt prov, skall han få livets krona, vilken Gud har lovat åt dem som älska honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 13, 'Ingen säge, när han bliver frestad, att det är från Gud som hans frestelse kommer; ty såsom Gud icke kan frestas av något ont, så frestar han icke heller någon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 14, 'Nej, närhelst någon frestas, så är det av sin egen begärelse som han drages och lockas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 15, 'Sedan, när begärelsen har blivit havande, föder hon synd, och när synden har blivit fullmogen, framföder hon död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 16, 'Faren icke vilse, mina älskade bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 17, 'Idel goda gåvor och idel fullkomliga skänker komma ned ovanifrån, från himlaljusens Fader, hos vilken ingen förändring äger rum och ingen växling av ljus och mörker.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 18, 'Efter sitt eget beslut födde han oss till liv genom sanningens ord, för att vi skulle vara en förstling av de varelser han har skapat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 19, 'Det veten I, mina älskade bröder. Men var människa vare snar till att höra och sen till att tala och sen till vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 20, 'Ty en mans vrede kommer icke åstad vad rätt är inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 21, 'Skaffen därför bort all orenhet och all ondska som finnes kvar, och mottagen med saktmod det ord som är plantat i eder, och som kan frälsa edra själar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 22, 'Men varen ordets görare, och icke allenast dess hörare, eljest bedragen I eder själva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 23, 'Ty om någon är ordets hörare, men icke dess görare, så är han lik en man som betraktar sitt ansikte i en spegel:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 24, 'när han har betraktat sig däri, går han sin väg och förgäter strax hurudan han var.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 25, 'Men den som skådar in i den fullkomliga lagen, frihetens lag, och förbliver därvid och icke är en glömsk hörare, utan en verklig görare, han varder salig i sin gärning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 26, 'Om någon menar sig tjäna Gud och icke tyglar sin tunga, utan bedrager sitt hjärta, så är hans gudstjänst intet värd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 27, 'En gudstjänst, som är ren och obesmittad inför Gud och Fadern, är det att vårda sig om fader- och moderlösa barn och änkor i deras bedrövelse, och att hålla sig obefläckad av världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, 'Mina bröder, menen icke att tron på vår Herre Jesus Kristus, den förhärligade, kan stå tillsammans med att hava anseende till personen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Om till exempel i eder församling inträder en man med guldring på fingret och i präktiga kläder, och jämte honom inträder en fattig man i smutsiga kläder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'och I då vänden edra blickar till den som bär de präktiga kläderna och sägen till honom: »Sitt du här på denna goda plats», men däremot sägen till den fattige: »Stå du där», eller: »Sätt dig därnere vid min fotapall» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'haven I icke då kommit i strid med eder själva och blivit domare som döma efter orätta grunder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, 'Hören, mina älskade bröder: Har icke Gud utvald just dem som i världens ögon äro fattiga till att bliva rika i tro, och att få till arvedel det rike han har lovat åt dem som älska honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'I åter haven visat förakt för den fattige. Är det då icke de rika som förtrycka eder, och är det icke just de, som draga eder inför domstolarna?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Är det icke de, som smäda det goda namn som är nämnt över eder?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, 'Om I, såsom skriften bjuder, fullgören den konungsliga lagen: »Du skall älska din nästa såsom dig själv», då gören I visserligen väl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'Men om I haven anseende till personen, så begån I synd och bliven av lagen överbevisade om att vara överträdare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, 'Ty om någon håller hela lagen i övrigt, men felar i ett, så är han skyldig till allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Densamme som sade: »Du skall icke begå äktenskapsbrott», han sade ju ock: »Du skall icke dräpa.» Om du nu visserligen icke begår äktenskapsbrott, men dräper, så är du dock en lagöverträdare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, 'Talen och handlen så, som det höves människor vilka skola dömas genom frihetens lag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Ty domen skall utan barmhärtighet drabba den som icke har visat barmhärtighet; barmhärtighet åter kan frimodigt träda fram inför domen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, 'Mina bröder, vartill gagnar det, om någon säger sig hava tro, men icke har gärningar? Icke kan väl tron frälsa honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'Om någon, vare sig en broder eller en syster, saknade kläder och vore utan mat för dagen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'och någon av eder då sade till denne: »Gå i frid, kläd dig varmt, och ät dig mätt» -- vartill gagnade detta, såframt han icke därjämte gåve honom vad hans kropp behövde?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Så är ock tron i sig själv död, om den icke har med sig gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, 'Nu torde någon säga: »Du har ju tro?» -- »Ja, och jag har också gärningar; visa mig du din tro utan gärningar, så vill jag genom mina gärningar visa dig min tro.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 19, 'Du tror att Gud är en. Däri gör du rätt; också de onda andarna tro det och bäva.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 20, 'Men vill du då förstå, du fåkunniga människa, att tron utan gärningar är till intet gagn!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 21, 'Blev icke Abraham, vår fader, rättfärdig av gärningar, när han frambar sin son Isak på altaret?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 22, 'Du ser alltså att tron samverkade med hans gärningar, och av gärningarna blev tron fullkomnad,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 23, 'och så fullbordades det skriftens ord som säger: »Abraham trodde Gud, och det räknades honom till rättfärdighet»; och han blev kallad »Guds vän».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 24, 'I sen alltså att det är av gärningar som en människa bliver rättfärdig, och icke av tro allenast.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 25, 'Och var det icke på samma sätt med skökan Rahab? Blev icke hon rättfärdig av gärningar, när hon tog emot sändebuden och sedan på en annan väg släppte ut dem?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 26, 'Ja, såsom kroppen utan ande är död, så är ock tron utan gärningar död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, 'Mina bröder, icke många av eder må träda upp såsom lärare; I bören veta att vi skola få en dess strängare dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'I många stycken fela vi ju alla; om någon icke felar i sitt tal, så är denne en fullkomlig man, som förmår tygla hela sin kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'När vi lägga betsel i hästarnas mun, för att de skola lyda oss, då kunna vi därmed styra också hela deras övriga kropp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Ja, till och med skeppen, som äro så stora, och som drivas av starka vindar, styras av ett helt litet roder åt det håll dit styrmannen vill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'Så är ock tungan en liten lem och kan likväl berömma sig av stora ting. Betänken huru en liten eld kan antända en stor skog.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, 'Också tungan är en eld; såsom en värld av orättfärdighet framstår den bland våra lemmar, tungan som befläckar hela kroppen och sätter »tillvarons hjul» i brand, likasom den själv är antänd av Gehenna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, 'Ty väl är det så, att alla varelsers natur, både fyrfotadjurs och fåglars och kräldjurs och vattendjurs, låter tämja sig, och verkligen har blivit tamd, genom människors natur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'Men tungan kan ingen människa tämja; ett oroligt och ont ting är den, och full av dödande gift.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'Med den välsigna vi Herren och Fadern, och med den förbanna vi människorna, som äro skapade till att vara Gud lika.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'Ja, från en och samma mun utgå välsignelse och förbannelse. Så bör det icke vara, mina bröder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'Icke giver väl en källa från en och samma åder både sött och bittert vatten?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'Mina bröder, icke kan väl ett fikonträd bära oliver eller ett vinträd fikon? Lika litet kan en salt källa giva sött vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Finnes bland eder någon vis och förståndig man, så må han, i visligt saktmod, genom sin goda vandel låta se de gärningar som hövas en sådan man.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, 'Om I åter i edra hjärtan hysen bitter avund och ären genstridiga, då mån I icke förhäva eder och ljuga, i strid mot sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Sådan »vishet» kommer icke ned ovanifrån, utan är av jorden och tillhör de »själiska»[1] människorna, ja, de onda andarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'Ty där avund och genstridighet råda, där råder oordning och allt vad ont är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'Men den vishet som kommer ovanifrån är först och främst ren, vidare fridsam, foglig och mild, full av barmhärtighet och andra goda frukter, fri ifrån tvivel, fri ifrån skrymtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'Och rättfärdighetens frukt kommer av en sådd i frid, dem till del som hålla frid. [1] Se Själisk i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, 'Varav uppkomma strider, och varav tvister bland eder? Månne icke av de lustar som föra krig i eder lemmar?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'I ären fulla av begärelser, men haven dock intet; I dräpen och hysen avund, men kunnen dock intet vinna; och så tvisten och striden I. I haven intet, därför att I icke bedjen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'Dock, I bedjen, men I fån intet, ty I bedjen illa, nämligen för att kunna i edra lustar förslösa vad I fån.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'I trolösa avfällingar, veten I då icke att världens vänskap är Guds ovänskap? Den som vill vara världens vän, han bliver alltså Guds ovän.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'Eller menen I att detta är ett tomt ord i skriften: »Med svartsjuk kärlek trängtar den Ande som han har låtit taga sin boning i oss»?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, 'Men så mycket större är den nåd han giver; därför heter det: »Gud står emot de högmodiga, men de ödmjuka giver han nåd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'Så varen nu Gud underdåniga, men stån emot djävulen, så skall han fly bort ifrån eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Nalkens Gud, så skall han nalkas eder. Renen edra händer, I syndare, och gören edra hjärtan rena, I människor med delad håg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Kännen edert elände och sörjen och gråten. Edert löje vände sig i sorg och eder glädje i bedrövelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'Ödmjuken eder inför Herren, så skall han upphöja eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, 'Förtalen icke varandra, mina bröder. Den som förtalar en broder eller dömer sin broder, han förtalar lagen och dömer lagen. Men dömer du lagen, så är du icke en lagens görare, utan dess domare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 12, 'En är lagstiftaren och domaren, han som kan frälsa och kan förgöra. Vem är då du som dömer din nästa?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 13, 'Hören nu, I som sägen: »I dag eller i morgon vilja vi begiva oss till den och den staden, och där vilja vi uppehålla oss ett år och driva handel och skaffa oss vinning» --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 14, 'I veten ju icke vad som kan ske i morgon. Ty vad är edert liv? En rök ären I, som synes en liten stund, men sedan försvinner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 15, 'I borden fastmera säga: »Om Herren vill, och vi får leva, skola vi göra det, eller det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 16, 'Men nu talen I stora ord i eder förmätenhet. All sådan stortalighet är ond.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 17, 'Alltså, den som förstår att göra vad gott är, men icke gör det, för honom bliver detta till synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, 'Hören nu, I rike: Gråten och jämren eder över det elände som skall komma över eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'Eder rikedom multnar bort, och edra kläder frätas sönder av mal;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'edert guld och silver förrostar, och rosten därpå skall vara eder till ett vittnesbörd och skall såsom en eld förtära edert kött. I haven samlat eder skatter i de yttersta dagarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Se, den lön I haven förhållit arbetarna som hava avbärgat edra åkrar, den ropar över eder, och skördemännens rop hava kommit fram till Herren Sebaots öron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, 'I haven levat i kräslighet på jorden och gjort eder goda dagar; I haven gött eder av hjärtans lust »på eder slaktedag».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'I haven dömt den rättfärdige skyldig och haven dräpt honom; han står eder icke emot.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Så biden nu tåligt, mina bröder, intill Herrens tillkommelse. I sen huru åkermannen väntar på jordens dyrbara frukt och tåligt bidar efter den, till dess att den har fått höstregn och vårregn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'Ja, biden ock I tåligt, och styrken edra hjärtan; ty Herrens tillkommelse är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'Sucken icke mot varandra, mina bröder, på det att I icke mån bliva dömda. Se, domaren står för dörren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'Mina bröder, tagen profeterna, som talade i Herrens namn, till edert föredöme i att uthärda lidande och visa tålamod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, 'Vi prisa ju dem saliga, som hava varit ståndaktiga. Om Jobs ståndaktighet haven I hört, och I haven sett vilken utgång Herren beredde; ty Herren är nåderik och barmhärtig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'Men framför allt, mina bröder, svärjen icke, varken vid himmelen eller vid jorden, ej heller vid något annat, utan låten edert »ja» vara »ja», och edert »nej» vara »nej», så att I icke hemfallen under dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Får någon bland eder utstå lidande, så må han bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'Är någon glad, så må han sjunga lovsånger. Är någon bland eder sjuk, må han då kalla till sig församlingens äldste; och dessa må bedja över honom och i Herrens namn smörja honom med olja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 15, 'Och trons bön skall hjälpa den sjuke, och Herren skall låta honom stå upp igen; och om han har begått synder, skall detta bliva honom förlåtet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 16, 'Bekännen alltså edra synder för varandra, och bedjen för varandra, på det att I mån bliva botade. Mycket förmår en rättfärdig mans bön, när den bedes med kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 17, 'Elias var en människa, med samma natur som vi. Han bad en bön att det icke skulle regna, och det regnade icke på jorden under tre år och sex månader;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 18, 'åter bad han, och då gav himmelen regn, och jorden bar sin frukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 19, 'Mina bröder, om någon bland eder har farit vilse från sanningen, och någon omvänder honom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 20, 'så mån I veta att den som omvänder en syndare från hans villoväg, han frälsar hans själ från döden och överskyler en myckenhet av synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 1, 'Petrus, Jesu Kristi apostel, hälsar de utvalda främlingar som bo kringspridda i Pontus, Galatien, Kappadocien, provinsen Asien och Bitynien,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 2, 'utvalda enligt Guds, Faderns, försyn, i helgelse i Anden, till lydnad och till bestänkelse med Jesu Kristi blod. Nåd och frid föröke sig hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 3, 'Lovad vare vår Herres, Jesu Kristi, Gud och Fader, som efter sin stora barmhärtighet har genom Jesu Kristi uppståndelse från de döda fött oss på nytt till ett levande hopp,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 4, 'till ett oförgängligt, obesmittat och ovanskligt arv, som i himmelen är förvarat åt eder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 5, 'I som med Guds makt bliven genom tro bevarade till en frälsning som är beredd för att uppenbaras i den yttersta tiden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 6, 'Därför mån I fröjda eder, om I ock nu en liten tid, där så måste ske, liden bedrövelse under allahanda prövningar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 7, 'för att, om eder tro håller provet -- vilket är mycket mer värt än guldet, som förgås, men som dock genom eld bliver beprövat -- detta må befinnas lända eder till pris, härlighet och ära vid Jesu Kristi uppenbarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 8, 'Honom älsken I utan att hava sett honom; och fastän I ännu icke sen honom, tron I dock på honom och fröjden eder över honom med outsäglig och härlig glädje,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 9, 'då I nu ären på väg att vinna det som är målet för eder tro, nämligen edra själars frälsning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 10, 'Angående denna frälsning hava profeter ivrigt forskat och rannsakat, de som profeterade om den nåd som skulle vederfaras eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 11, 'De hava rannsakat för att finna vilken och hurudan tid det var som Kristi Ande i dem hänvisade till, när han förebådade de lidanden som skulle vederfaras Kristus, och den härlighet som därefter skulle följa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 12, 'Och det blev uppenbarat för dem att det icke var sig själva, utan eder, som de tjänade härmed. Om samma ting har nu en förkunnelse kommit till eder genom de män som i helig ande, nedsänd från himmelen, hava för eder predikat evangelium; och i de tingen åstunda jämväl änglar att skåda in.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 13, 'Omgjorden därför edert sinnes länder och varen nyktra; och sätten med full tillit edert hopp till den nåd som bjudes eder i och med Jesu Kristi uppenbarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 14, 'Då I nu haven kommit till lydnad, så följen icke de begärelser som I förut, under eder okunnighets tid, levden i,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 15, 'utan bliven heliga i all eder vandel, såsom han som har kallat eder är helig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 16, 'Det är ju skrivet: »I skolen vara heliga, ty jag är helig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 17, 'Och om I såsom Fader åkallen honom som utan anseende till personen dömer var och en efter hans gärningar, så vandren ock i fruktan under denna edert främlingsskaps tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 18, 'I veten ju att det icke är med förgängliga ting, med silver eller guld, som I haven blivit »lösköpta» från den vandel I förden i fåfänglighet, efter fädernas sätt,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 19, 'utan med Kristi dyra blod, såsom med blodet av ett felfritt lamm utan fläck.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 20, 'Så var förutsett om honom före världens begynnelse; men först nu i de yttersta tiderna har han blivit uppenbarad för eder skull,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 21, 'I som genom honom tron på Gud, vilken uppväckte honom från de döda och gav honom härlighet, så att eder tro nu ock kan vara ett hopp till Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 22, 'Renen edra själar, i lydnad för sanningen, till oskrymtad broderlig kärlek, och älsken varandra av hjärtat med uthållig kärlek,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 23, 'I som ären födda på nytt, icke av någon förgänglig säd, utan av en oförgänglig: genom Guds levande ord, som förbliver.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 24, 'Ty »allt kött är såsom gräs och all dess härlighet såsom gräsets blomster; gräset torkar bort, och blomstret faller av,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 25, 'men Herrens ord förbliver evinnerligen». Och det är detta ord som har blivit förkunnat för eder såsom ett glatt budskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 1, 'Så läggen då bort all ondska och allt svek så ock skrymteri och avund och allt förtal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 2, 'Och då I nu ären nyfödda barn, så längten efter att få den andliga oförfalskade mjölken, på det att I genom den mån växa upp till frälsning,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 3, 'om I annars haven »smakat att Herren är god».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 4, 'Och kommen till honom, den levande stenen, som väl av människor är förkastad, men inför Gud är »utvald och dyrbar»;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 5, 'och låten eder själva såsom levande stenar uppbyggas till ett andligt hus, så att I bliven ett »heligt prästerskap», som skall frambära andliga offer, vilka genom Jesus Kristus äro välbehagliga för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 6, 'Det heter nämligen på ett ställe i skriften: »Se, jag lägger i Sion en utvald, dyrbar hörnsten, och den som tror på den skall icke komma på skam.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 7, 'För eder, I som tron, är stenen alltså dyrbar, men för sådana som icke tro »har den sten som byggningsmännen förkastade blivit en hörnsten»,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 8, 'som är »en stötesten och en klippa till fall». Eftersom de icke hörsamma ordet, stöta de sig; så var det ock bestämt om dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 9, 'I åter ären »ett utvalt släkte, ett konungsligt prästerskap, ett heligt folk, ett egendomsfolk», för att I skolen förkunna hans härliga gärningar, hans som har kallat eder från mörkret till sitt underbara ljus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 10, 'I som förut »icke voren ett folk», men nu ären »ett Guds folk», I som »icke haden fått någon barmhärtighet», men nu »haven fått barmhärtighet».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 11, 'Mina älskade, jag förmanar eder såsom »gäster och främlingar» att taga eder till vara för de köttsliga begärelserna, vilka föra krig mot själen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 12, 'Och fören en god vandel bland hedningarna, på det att dessa, om de i någon sak förtala eder såsom illgärningsmän, nu i stället, när de skåda edra goda gärningar, må för dessas skull prisa Gud på den dag då han söker dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 13, 'Varen underdåniga all mänsklig ordning för Herrens skull, vare sig det är konungen, såsom den överste härskaren,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 14, 'eller det är landshövdingarna, som ju äro sända av honom för att straffa dem som göra vad ont är och för att prisa dem som göra vad gott är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 15, 'Ty så är Guds vilja, att I med goda gärningar skolen stoppa munnen till på oförståndiga och fåkunniga människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 16, 'I ären ju fria, dock icke som om I haden friheten för att därmed överskyla ondskan, utan såsom Guds tjänare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 17, 'Bevisen var man ära, älsken bröderna, »frukten Gud, ären konungen».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 18, 'I tjänare, underordnen eder edra herrar med all fruktan, icke allenast de goda och milda, utan också de obilliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 19, 'Ty det är välbehagligt för Gud, om någon, med honom för ögonen, tåligt uthärdar sina vedervärdigheter, när han får lida oförskylt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 20, 'Ty vad berömligt är däri att I bevisen tålamod, när I för edra synders skull fån uppbära hugg och slag? Men om I bevisen tålamod, när I fån lida för goda gärningars skull, då är detta välbehaglig för Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 21, 'Ty därtill ären I kallade, då ju Kristus själv led för eder och efterlämnade åt eder en förebild, på det att I skullen följa honom och vandra i hans fotspår.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 22, '»Han hade ingen synd gjort, och intet svek fanns i hans mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 23, 'När han blev smädad, smädade han icke igen, och när han led, hotade han icke, utan överlämnade sin sak åt honom som dömer rättvist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 24, 'Och »våra synder bar han» i sin kropp upp på korsets trä, för att vi skulle dö bort ifrån synderna och leva för rättfärdigheten; och »genom hans sår haven I blivit helade».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 25, 'Ty I »gingen vilse såsom får», men nu haven I vänt om till edra själars herde och vårdare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 1, 'Sammalunda, i hustrur, underordnen eder edra män, för att också de män, som till äventyrs icke hörsamma ordet; må genom sina hustrurs vandel bliva vunna utan ord,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 2, 'när de skåda den rena vandel som I fören i fruktan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 3, 'Eder prydnad vare icke den utvärtes prydnaden, den som består i hårflätningar och påhängda gyllene smycken eller i eder klädedräkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 4, 'Den vare fastmer hjärtats fördolda människa, smyckad med den saktmodiga och stilla andens oförgängliga väsende; ty detta är dyrbart inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 5, 'På sådant sätt prydde sig ju ock fordom de heliga kvinnorna, de som satte sitt hopp till Gud och underordnade sig sina män.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 6, 'Så var Sara lydig mot Abraham och kallade honom »herre»; och hennes barn haven I blivit, om I gören vad gott är, och icke låten eder förskräckas av något.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 7, 'Sammalunda skolen I ock, I män, på förståndigt sätt leva tillsammans med edra hustrur, då ju hustrun är det svagare kärlet; och eftersom de äro edra medarvingar till livets nåd, skolen I bevisa dem all ära, på det att edra böner icke må bliva förhindrade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 8, 'Varen slutligen alla endräktiga, medlidsamma, kärleksfulla mot bröderna, barmhärtiga, ödmjuka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 9, 'Vedergällen icke ont med ont, icke smädelse med smädelse, utan tvärtom välsignen; därtill ären I ju ock kallade, att I skolen få välsignelse till arvedel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 10, 'Ty »den som vill älska livet och se goda dagar, han avhålle sin tunga från det som är ont och sina läppar från att tala svek;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 11, 'han vände sig bort ifrån det som är ont, och göre vad gott är, han söke friden, och trakte därefter');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 12, 'Ty Herrens ögon äro vända till de rättfärdiga, och hans öron till deras bön. Men Herrens ansikte är emot dem som göra det onda».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 13, 'Och vem är den som kan göra eder något ont, om I nitälsken för det som är gott?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 14, 'Skullen I än få lida för rättfärdighets skull, så ären I dock saliga. »Hysen ingen fruktan för dem, och låten eder icke förskräckas;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 15, 'nej, Herren, Kristus, skolen I hålla helig i edra hjärtan.» Och I skolen alltid vara redo att svara var och en som av eder begär skäl för det hopp som är i eder, dock med saktmod och i fruktan');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 16, 'och med ett gott samvete, så att de som smäda eder goda vandel i Kristus komma på skam, i fråga om det som de förtala eder för.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 17, 'Ty det är bättre att lida för goda gärningar, om så skulle vara Guds vilja, än att lida för onda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 18, 'Kristus själv led ju en gång döden för synder; rättfärdig led han för orättfärdiga, på det att han skulle föra oss till Gud. Ja, han blev dödad till köttet, men till anden blev han gjord levande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 19, 'I anden gick han gick han ock åstad och predikade för de andar som höllos i fängelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 20, 'för sådana som fordom voro ohörsamma, när Guds långmodighet gav dem anstånd i Noas tid, då när en ark byggdes, i vilken några få -- allenast åtta personer -- blevo frälsta genom vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 21, 'Efter denna förebild bliven nu och I frälsta genom vatten -- nämligen genom ett dop som icke betyder att man avtvår kroppslig orenhet, utan betyder att man anropar Gud om ett gott samvete -- i kraft av Jesu Kristi uppståndelse,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 22, 'hans som har farit upp till himmelen, och som nu sitter på Guds högra sida, sedan änglar och väldige och makter i andevärlden hava blivit honom underlagda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 1, 'Då nu Kristus har lidit till köttet, så väpnen ock I eder med samma sinne; ty den som har lidit till köttet har icke längre något att skaffa med synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 2, 'Och leven sedan, under den tid som återstår eder här i köttet, icke mer efter människors onda begärelser, utan efter Guds vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 3, 'Ty det är nog, att I under den framfarna tiden haven gjort hedningarnas vilja och levat i lösaktighet och onda begärelser, i fylleri, vilt leverne och dryckenskap och i allahanda skamlig avgudadyrkan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 4, 'varför de ock förundra sig och smäda eder, då I nu icke löpen med till samma liderlighetens pöl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 5, 'Men de skola göra räkenskap inför honom som är redo att döma levande och döda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 6, 'Ty att evangelium blev förkunnat jämväl för döda, det skedde, för att dessa, om de än till köttet blevo dömda, såsom alla människor dömas, likväl till anden skulle få leva, så som Gud lever');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 7, 'Men änden på allting är nu nära. Varen alltså besinningsfulla och nyktra, så att I kunnen bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 8, 'Och varen framför allt uthålliga i eder kärlek till varandra, ty »kärleken överskyler en myckenhet av synder».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 9, 'Varen gästvänliga mot varandra utan knot,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 10, 'och tjänen varandra, var och en med den nådegåva han har undfått, såsom goda förvaltare av Guds mångfaldiga nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 11, 'Om någon talar, så vare hans tal i enlighet med Guds ord, om någon har en tjänst, så sköte han den efter måttet av den kraft som Gud förlänar, så att Gud i allt bliver ärad genom Jesus Kristus. Honom tillhör äran och väldet i evigheternas evigheter, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 12, 'Mina älskade, förundren eder icke över den luttringseld som är tänd bland eder, och som I till eder prövning måsten genomgå, och menen icke att därmed något förunderligt vederfares eder;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 13, 'utan ju mer I fån dela Kristi lidanden, dess mer mån I glädja eder, för att I ock mån kunna glädjas och fröjda eder vid hans härlighets uppenbarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 14, 'Saliga ären I, om I för Kristi namns skull bliven smädade, ty härlighetens Ande, Guds Ande, vilar då över eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 15, 'Det må nämligen icke ske, att någon av eder får lida såsom dråpare eller tjuv eller illgärningsman, eller därför att han blandar sig i vad honom icke vidkommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 16, 'Men om någon får lida för att han är en kristen, då må han icke blygas, utan prisa Gud för detta namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 17, 'Ty tiden är inne att domen skall begynna, och det på Guds hus; men om begynnelsen sker med oss, vad bliver då änden för dem som icke hörsamma Guds evangelium?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 18, 'Och om den rättfärdige med knapp nöd bliver frälst, »huru skall det då gå den ogudaktige och syndaren?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 19, 'Alltså, de som efter Guds vilja få lida, de må anbefalla sina själar åt sin trofaste Skapare, allt under det att de göra vad gott är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 1, 'Till de äldste bland eder ställer jag nu denna förmaning, jag som själv är en av de äldste och en som vittnar om Kristi lidanden, och som jämväl har del i den härlighet som kommer att uppenbaras:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 2, 'Varen herdar för Guds hjord, som I haven i eder vård, varen det icke av tvång, utan av fri vilja, icke för slem vinnings skull, utan med villigt hjärta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 3, 'Uppträden icke såsom herrar över edra församlingar, utan bliven föredömen för hjorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 4, 'Då skolen I, när Överherden uppenbaras, undfå härlighetens oförvissneliga segerkrans.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 5, 'Så skolen I ock, I yngre, å eder sida underordna eder de äldre. Ikläden eder alla, i umgängelsen med varandra, ödmjukheten såsom en tjänardräkt. Ty »Gud står emot de högmodiga, men de ödmjuka giver han nåd».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 6, 'Ödmjuken eder alltså under Guds mäktiga hand, för att han må upphöja eder i sinom tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 7, 'Och »kasten alla edra bekymmer på honom», ty han har omsorg om eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 8, 'Varen nyktra och vaken. Eder vedersakare, djävulen, går omkring såsom ett rytande lejon och söker vem han må uppsluka.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 9, 'Stån honom emot, fasta i tron, och veten att samma lidanden vederfaras edra bröder här i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 10, 'Men all nåds Gud, som har kallat eder till sin eviga härlighet i Kristus, sedan I en liten tid haven lidit, han skall fullkomna, stödja, styrka och stadfästa eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 11, 'Honom tillhör väldet i evigheternas evigheter. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 12, 'Genom Silvanus, eder trogne broder -- för en sådan håller jag honom nämligen -- har jag nu i korthet skrivit detta, för att förmana eder, och för att betyga att den nåd I stån i är Guds rätta nåd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 13, 'Församlingen i Babylon, utvald likasom eder församling, hälsar eder. Så gör ock min son Markus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 14, 'Hälsen varandra med en kärlekens kyss. Frid vare med eder alla som ären i Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 1, 'Förmaning till kristliga Simon Petrus, Jesu Kristi tjänare och apostel, hälsar dem som i och genom vår Guds och Frälsarens[1], Jesu Kristi, rättfärdighet hava fått sig beskärd en lika dyrbar tro som vi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 2, 'Nåd och frid föröke sig hos eder, i kunskap om Gud och vår Herre Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 3, 'Allt det som leder till liv och gudsfruktan har hans gudomliga makt skänkt oss, genom kunskapen om honom som har kallat oss medelst sin härlighet och underkraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 4, 'Genom dem har han ock skänkt oss sina dyrbara och mycket stora löften, för att I skolen, i kraft av dem, bliva delaktiga av gudomlig natur och undkomma den förgängelse som i följd av den onda begärelsen råder i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 5, 'Vinnläggen eder just därför på allt sätt om att i eder tro bevisa dygd, i dygden kunskap,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 6, 'i kunskapen återhållsamhet, i återhållsamheten ståndaktighet, i ståndaktigheten gudsfruktan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 7, 'i gudsfruktan broderlig kärlek, i den broderliga kärleken allmännelig kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 8, 'Ty om detta finnes hos eder och mer och mer förökas, så tillstädjer det eder icke att vara overksamma eller utan frukt i fråga om kunskapen om vår Herre Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 9, 'Den åter som icke har detta, han är blind och kan icke se; han har förgätit att han har blivit renad från sina förra synder,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 10, 'Vinnläggen eder därför, mina bröder, så mycket mer om att göra eder kallelse och utkorelse fast. Ty om I det gören, skolen I aldrig någonsin komma på fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 11, 'Så skall inträdet i vår Herres och Frälsares, Jesu Kristi, eviga rike förlänas eder i rikligt mått.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 12, 'Därför kommer jag alltid att påminna eder om detta, fastän I visserligen redan kännen det och ären befästa i den sanning som har kommit till eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 13, 'Och jag håller det för rätt och tillbörligt, att så länge jag ännu är i denna kroppshydda, genom mina påminnelser väcka eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 14, 'Ty jag vet att jag snart skall lämna min kroppshydda; detta har vår Herre Jesus Kristus givit till känna för mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 15, 'Men jag vill härmed sörja för, att I också efter min bortgång städse kunnen draga eder detta till minnes.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 16, 'Ty det var icke några slugt uttänkta fabler vi följde, när vi kungjorde för eder vår Herres, Jesu Kristi, makt och hans tillkommelse utan vi hade själva skådat hans härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 17, 'Ty han fick ifrån Gud, fadern, ära och pris, när från det högsta Majestätet en röst kom till honom och sade: »Denne är min älskade Son, i vilken jag har funnit behag.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 18, 'Den rösten hörde vi själva komma från himmelen, när vi voro med honom på det heliga berget.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 19, 'Så mycket fastare står nu också för oss det profetiska ordet; och I gören väl, om I akten därpå, såsom på ett ljus som lyser i en dyster vildmark, till dess att dagen gryr, och morgonstjärnan går upp i edra hjärtan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 20, 'Men det mån I framför allt veta, att ingen profetia i något skriftens ord kan av någon människas egen kraft utläggas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 21, 'Ty ingen profetia har någonsin framkommit av en människas vilja, utan därigenom att människor, drivna av den helige Ande, talade vad som gavs dem från Gud. [1] Eller:... vår Guds och Frälsares o. s. v.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 1, 'Men också falska profeter uppstodo bland folket, likasom jämväl bland eder falska lärare skola komma att finnas, vilka på smygvägar skola införa fördärvliga partimeningar och draga över sig själva plötsligt fördärv, i det att de till och med förneka den Herre som har köpt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 2, 'De skola få många efterföljare i sin lösaktighet, och för deras skull skall sanningens väg bliva smädad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 3, 'I sin girighet skola de ock med bedrägliga ord bereda sig vinning av eder. Men sedan länge är deras dom i annalkande, den dröjer icke, och deras fördärv sover icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 4, 'Ty Gud skonade ju icke de änglar som syndade, utan störtade dem ned i avgrunden och överlämnade dem åt mörkrets hålor, för att där förvaras till domen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 5, 'Ej heller skonade han den forntida världen, om han ock, när han lät floden komma över de ogudaktigas värld, bevarade Noa såsom rättfärdighetens förkunnare, jämte sju andra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 6, 'Och städerna Sodom och Gomorra lade han i aska och dömde dem till att omstörtas; han gjorde dem så till ett varnande exempel för kommande tiders ogudaktiga människor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 7, 'Men han frälste den rättfärdige Lot, som svårt pinades av de gudlösa människornas lösaktiga vandel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 8, 'Ty genom de ogärningar som han, den rättfärdige mannen, måste se och höra, där han bodde ibland dem, plågades han dag efter dag i sin rättfärdiga själ.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 9, 'Så förstår Herren att frälsa de gudfruktiga ur prövningen, men ock att under straff förvara de orättfärdiga till domens dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 10, 'Och detta gör han först och främst med dem som i oren begärelse stå efter köttslig lust och förakta andevärldens herrar. I sitt trots och sin självgodhet bäva dessa människor icke för att smäda andevärldens härlige,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 11, 'under det att änglar som stå ännu högre i starkhet och makt icke om dem uttala någon smädande dom inför Herren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 12, 'Men på samma sätt som oskäliga djur förgås, varelser som av naturen äro födda till att fångas och förgås, på samma sätt skola ock dessa förgås, eftersom de smäda vad de icke känna till;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 13, 'och de skola så bliva bedragna på den lön som de vilja vinna genom orättfärdighet. De hava sin lust i kräsligt leverne mitt på ljusa dagen. De äro skamfläckar och styggelser, där de vid gästabuden, som de få hålla med eder, frossa i sina njutningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 14, 'Deras ögon äro fulla av otuktigt begär och kunna icke få nog av synd. De locka till sig obefästa själar. De hava hjärtan övade i girighet. Förbannade äro de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 15, 'De hava övergivit den raka vägen och kommit vilse genom att efterfölja Balaam, Beors son, på hans väg. Denne åtrådde ju att vinna lön genom orättfärdighet;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 16, 'men han blev tillrättavisad för sin överträdelse: en stum arbetsåsninna begynte tala med människoröst och hindrade profeten i hans galenskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 17, 'Dessa människor äro källor utan vatten, skyar som drivas av stormvinden, och det svarta mörkret är förvarat åt dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 18, 'Ty de tala stora ord som äro idel fåfänglighet; och då de nu själva leva i köttsliga begärelser, locka de genom sin lösaktighet till sig människor som med knapp nöd rädda sig undan sådana som vandra i villfarelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 19, 'De lova dem frihet, fastän de själva äro förgängelsens trälar; ty den som har låtit sig övervinnas av någon, han har blivit dennes träl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 20, 'Och då de genom kunskapen om Herren och Frälsaren, Jesus Kristus, hava undkommit världens besmittelser, men sedan åter låta sig insnärjas och övervinnas av dem, så har det sista för dem blivit värre än det första.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 21, 'Ty det hade varit bättre för dem att icke hava lärt känna rättfärdighetens väg, än att nu, sedan de hava lärt känna den, vända tillbaka, bort ifrån det heliga bud som har blivit dem meddelat.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 22, 'Det har gått med dem såsom det riktigt heter i ordspråket: »En hund vänder åter till sina spyor», och: »Ett tvaget svin vältrar sig åter i smutsen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 1, 'Detta är nu redan det andra brevet som jag skriver till eder, mina älskade; och i båda har jag genom mina påminnelser velat uppväcka edert rena sinne,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 2, 'så att I kommen ihåg vad som har blivit förutsagt av de heliga profeterna, så ock det bud som av edra apostlar har blivit eder givet från Herren och Frälsaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 3, 'Och det mån I framför allt veta, att i de yttersta dagarna bespottare skola komma med bespottande ord, människor som vandra efter sina egna begärelser.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 4, 'De skola säga: »Huru går det med löftet om hans tillkommelse? Från den dag då våra fäder avsomnade har ju allt förblivit sig likt, ända ifrån världens begynnelse.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 5, 'Ty när de vilja påstå detta, förgäta de att i kraft av Guds ord himlar funnos till från uråldrig tid, så ock en jord som hade kommit till av vatten och genom vatten;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 6, 'och genom översvämning av vatten från dem förgicks också den värld som då fanns.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 7, 'Men de himlar och den jord som nu finnas, de hava i kraft av samma ord blivit sparade åt eld, och de förvaras nu till domens dag, då de ogudaktiga människorna skola förgås.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 8, 'Men ett vare icke fördolt för eder, mina älskade, detta, att »en dag är för Herren såsom tusen år, och tusen år såsom en dag».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 9, 'Herren fördröjer icke uppfyllelsen av sitt löfte, såsom somliga mena att han fördröjer sig. Men han är långmodig mot eder, eftersom han icke vill att någon skall förgås, utan att alla skola vända sig till bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 10, 'Men Herrens dag skall komma såsom en tjuv, och då skola himlarna med dånande hast förgås, och himlakropparna upplösas av hetta, och jorden och de verk som äro därpå brännas upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 11, 'Eftersom nu allt detta sålunda går till sin upplösning, hurudana bören icke I då vara i helig vandel och gudsfruktan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 12, 'medan I förbiden och påskynden Guds dags tillkommelse, varigenom himlar skola upplösas av eld, och himlakroppar smälta av hetta!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 13, 'Men »nya himlar och en ny jord», där rättfärdighet bor, förbida vi efter hans löfte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 14, 'Därför, mina älskade, eftersom I förbiden detta, skolen I med all flit sörja för, att I mån för honom befinnas vara obefläckade och ostraffliga, i frid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 15, 'Och I skolen hålla före, att vår Herres långmodighet länder till frälsning; såsom ock vår älskade broder Paulus har skrivit till eder efter den vishet som har blivit honom given.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 16, 'Så gör han i alla sina brev, när han i dem talar om sådant, fastän visserligen i dem finnes ett och annat som är svårt att förstå, och som okunniga och obefästa människor vrångt uttyda, såsom de ock göra med de övriga skrifterna, sig själva till fördärv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 17, 'Då I nu således, mina älskade, haven fått veta detta i förväg, så tagen eder till vara för att bliva indragna i de gudlösas villfarelse och därigenom förlora edert fäste.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 18, 'Växen i stället till i nåd och i kunskap om vår Herre och Frälsare, Jesus Kristus. Honom tillhör äran, nu och till evighetens dag. Amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 1, 'Det som var från begynnelsen, det vi hava hört, det vi med egna ögon hava sett, det vi skådade och med egna händer togo på, det förkunna vi: om livets Ord tala vi.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 2, 'Ty livet uppenbarades, och vi hava sett det; och vi vittna därom och förkunna för eder livet, det eviga, som var hos Fadern och uppenbarades för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 3, 'Ja, det vi hava sett och hört, det förkunna vi ock för eder, på det att också I mån hava gemenskap med oss; och vi hava vår gemenskap med Fadern och med hans Son, Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 4, 'Och vi skriva nu detta, för att vår glädje skall bliva fullkomlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 5, 'Och detta är det budskap som vi hava hört från honom, och som vi förkunna för eder, att Gud är ljus, och att intet mörker finnes i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 6, 'Om vi säga oss hava gemenskap med honom, och vi vandra i mörkret, så ljuga vi och göra icke sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 7, 'Men om vi vandra i ljuset, såsom han är i ljuset, så hava vi gemenskap med varandra, och Jesu, hans Sons, blod renar oss från all synd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 8, 'Om vi säga att vi icke hava någon synd, så bedraga vi oss själva, och sanningen är icke i oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 9, 'Om vi bekänna våra synder, så är han trofast och rättfärdig, så att han förlåter oss våra synder och renar oss från all orättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 10, 'Om vi säga att vi icke hava syndat, så göra vi honom till en ljugare, och hans ord är icke i oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 1, 'Mina kära barn, detta skriver jag till eder, för att I icke skolen synda. Men om någon syndar, så hava vi en förespråkare hos Fadern, Jesus Kristus, som är rättfärdig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 2, 'och han är försoningen för våra synder, ja, icke allenast för våra, utan ock för hela världens.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 3, 'Därav veta vi att vi hava lärt känna honom, därav att vi hålla hans bud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 4, 'Den som säger sig hava lärt känna honom och icke håller hans bud, han är en lögnare och i honom är icke sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 5, 'Men den som håller hans ord, i honom är förvisso Guds kärlek fullkomnad. Därav veta vi att vi äro i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 6, 'Den som säger sig förbliva i honom, han är ock pliktig att själv så vandra som Han vandrade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 7, 'Mina älskade, det är icke ett nytt bud jag skriver till eder, utan ett gammalt bud, som I haven haft från begynnelsen. Detta gamla bud är ordet som I haven fått höra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 8, 'På samma gång är det dock ett nytt bud som jag skriver till eder. Och detta är sant både i fråga om honom och i fråga om eder; ty mörkret förgår, och det sanna ljuset lyser redan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 9, 'Den som säger sig vara i ljuset och hatar sin broder, han är ännu alltjämt i mörkret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 10, 'Den som älskar sin broder, han förbliver i ljuset, och i honom är intet som länder till fall.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 11, 'Men den som hatar sin broder, han är i mörkret och vandrar i mörkret, och han vet icke vart han går; ty mörkret har förblindat hans ögon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 12, 'Jag skriver till eder, kära barn, ty synderna äro eder förlåtna för hans namns skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 13, 'Jag skriver till eder, I fäder, ty I haven lärt känna honom som är från begynnelsen. Jag skriver till eder, I ynglingar, ty I haven övervunnit den onde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 14, 'Jag har skrivit till eder, mina barn, ty I haven lärt känna Fadern. Jag har skrivit till eder, I fäder, ty I haven lärt känna honom som är från begynnelsen. Jag har skrivit till eder, I ynglingar, ty I ären starka, och Guds ord förbliver i eder, och I haven övervunnit den onde.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 15, 'Älsken icke världen, ej heller vad som är i världen. Om någon älskar världen, så är Faderns kärlek icke i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 16, 'Ty allt som är i världen, köttets begärelse och ögonens begärelse och högfärd över detta livets goda, det är icke av Fadern, utan av världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 17, 'Och världen förgår och dess begärelse, men den som gör Guds vilja, han förbliver evinnerligen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 18, 'Mina barn, nu är den yttersta tiden. I haven ju hört att en antikrist skall komma, och redan hava många antikrister uppstått; därav förstå vi att den yttersta tiden är inne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 19, 'Från oss hava de utgått, men de hörde icke till oss, ty hade de hört till oss, så hade de förblivit hos oss. Men det skulle bliva uppenbart att icke alla höra till oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 20, 'I åter haven mottagit smörjelse från den Helige, och I haven all kunskap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 21, 'Jag har skrivit till eder, icke därför att I icke kännen sanningen, utan därför att I kännen den och veten att ingen lögn kommer av sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 22, 'Vilken är »Lögnaren», om icke den som förnekar att Jesus är Kristus? Denne är Antikrist, denne som förnekar Fadern och Sonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 23, 'Var och en som förnekar Sonen, han har icke heller Fadern; den som bekänner Sonen, han har ock Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 24, 'I åter skolen låta det som I haven hört från begynnelsen förbliva i eder. Om det som I haven hört från begynnelsen förbliver i eder så skolen ock I själva förbliva i Sonen och i Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 25, 'Och detta är vad han själv har lovat oss: det eviga livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 26, 'Detta har jag skrivit till eder med tanke på dem som söka förvilla eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 27, 'Men vad eder angår, så förbliver i eder den smörjelse I haven undfått från honom, och det behöves icke att någon undervisar eder; ty vad hans smörjelse lär eder om allting, det är sant och är icke lögn. Förbliven alltså i honom, såsom den har lärt eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 28, 'Ja, kära barn, förbliven nu i honom, så att vi, när han en gång uppenbaras, kunna frimodigt träda fram, och icke med skam nödgas gå bort ifrån honom vid hans tillkommelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 29, 'Om I veten att han är rättfärdig, så kunnen I förstå att också var och en som gör vad rättfärdigt är, han är född av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 1, 'Se vilken kärlek Fadern har bevisat oss därmed att vi få kallas Guds barn, vilket vi ock äro. Därför känner världen oss icke, eftersom den icke har lärt känna honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 2, 'Mina älskade, vi äro nu Guds barn, och vad vi skola bliva, det är ännu icke uppenbart. Men det veta vi, att när han en gång uppenbaras, skola vi bliva honom lika; ty då skola vi få se honom sådan han är.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 3, 'Och var och en som har detta hopp till honom, han renar sig, likasom Han är ren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 4, 'Var och en som gör synd, han överträder ock lagen, ty synd är överträdelse av lagen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 5, 'Och i veten att Han uppenbarades, för att han skulle borttaga synderna; och synd finnes icke i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 6, 'Var och en som förbliver i honom, han syndar icke; var och en som syndar, han har icke sett honom och icke lärt känna honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 7, 'Kära barn, låten ingen förvilla eder. Den som gör vad rättfärdigt är, han är rättfärdig, likasom Han är rättfärdig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 8, 'Den som gör synd, han är av djävulen, ty djävulen har syndat från begynnelsen. Och just därför uppenbarades Guds Son, att han skulle göra om intet djävulens gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 9, 'Var och en som är född av Gud, han gör icke synd, ty Guds säd förbliver i honom; han kan icke synda, eftersom han är född av Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 10, 'Därav är uppenbart vilka som äro Guds barn, och vilka som äro djävulens barn, därav att var och en som icke gör vad rättfärdigt är, han är icke av Gud, ej heller den som icke älskar sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 11, 'Ty detta är det budskap som I haven hört från begynnelsen, att vi skola älska varandra');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 12, 'och icke likna Kain, som var av den onde och slog ihjäl sin broder. Och varför slog han ihjäl honom? Därför att hans egna gärningar voro onda och hans broders gärningar rättfärdiga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 13, 'Förundren eder icke, mina bröder, om världen hatar eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 14, 'Vi veta att vi hava övergått från döden till livet, ty vi älska bröderna. Den som icke älskar, han förbliver i döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 15, 'Var och en som hatar sin broder, han är en mandråpare; och I veten att ingen mandråpare har evigt liv förblivande i sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 16, 'Därav att Han gav sitt liv för oss hava vi lärt känna kärleken; så äro ock vi pliktiga att giva våra liv för bröderna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 17, 'Men om någon har denna världens goda och tillsluter sitt hjärta för sin broder, när han ser honom lida nöd, huru kan då Guds kärlek förbliva i honom?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 18, 'Kära barn, låtom oss älska icke med ord eller med tungan, utan i gärning och i sanning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 19, 'Därav skola vi veta att vi äro av sanningen; och så kunna vi inför honom övertyga vårt hjärta därom,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 20, 'att om vårt hjärta fördömer oss, så är Gud större än vårt hjärta och vet allt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 21, 'Mina älskade, om vårt hjärta icke fördömer oss, så hava vi frimodighet inför Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 22, 'och vadhelst vi bedja om, det få vi av honom, eftersom vi hålla hans bud och göra vad som är välbehagligt för honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 23, 'Och detta är hans bud, att vi skola tro på hans Sons, Jesu Kristi, namn och älska varandra, enligt det bud han har givit oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 24, 'Och den som håller hans bud, han förbliver i Gud, och Gud förbliver i honom. Och att han förbliver i oss, det veta vi av Anden, som han har givit oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 1, 'Mina älskade, tron icke var och en ande, utan pröven andarna, huruvida de äro av Gud; ty många falska profeter hava gått ut i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 2, 'Därpå skolen I känna igen Guds Ande: var och en ande som bekänner att Jesus är Kristus, kommen i köttet, han är av Gud;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 3, 'men var och en ande som icke så bekänner Jesus, han är icke av Gud. Den anden är Antikrists ande, om vilken I haven hört att den skulle komma, och som redan nu är i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 4, 'I, kära barn, I ären av Gud och haven övervunnit dessa; ty han som är i eder är större än den som är i världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 5, 'De äro av världen; därför tala de vad som är av världen, och världen lyssnar till dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 6, 'Vi åter äro av Gud. Den som känner Gud, han lyssnar till oss; den som icke är av Gud, han lyssnar icke till oss. Härpå känna vi igen sanningens Ande och villfarelsens ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 7, 'Mina älskade, låtom oss älska varandra; ty kärleken är av Gud, och var och en som älskar, han är född av Gud och känner Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 8, 'Den som icke älskar, han har icke lärt känna Gud, ty Gud är kärleken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 9, 'Därigenom har Guds kärlek blivit uppenbarad bland oss, att Gud har sänt sin enfödde Son i världen, för att vi skola leva genom honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 10, 'Icke däri består kärleken, att vi hava älskat Gud, utan däri, att han har älskat oss och sänt sin Son till försoning för våra synder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 11, 'Mina älskade, om Gud så har älskat oss, då äro ock vi pliktiga att älska varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 12, 'Ingen har någonsin sett Gud. Om vi älska varandra, så förbliver Gud i oss, och hans kärlek är fullkomnad i oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 13, 'Därav att han har givit oss av sin Ande veta vi att vi förbliva i honom, och att han förbliver i oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 14, 'Och vi hava själva sett, och vi vittna om att Fadern har sänt sin Son till att vara världens Frälsare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 15, 'Den som bekänner att Jesus är Guds Son, i honom förbliver Gud, och han själv förbliver i Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 16, 'Och vi hava lärt känna den kärlek som Gud har i oss, och vi hava kommit till tro på den. Gud är kärleken, och den som förbliver i kärleken, han förbliver i Gud, och Gud förbliver i honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 17, 'Därigenom är kärleken fullkomnad hos oss, att vi hava frimodighet i fråga om domens dag; ty sådan Han är, sådana äro ock vi i denna världen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 18, 'Räddhåga finnes icke i kärleken, utan fullkomlig kärlek driver ut räddhågan, ty i räddhågan ligger tanke på straff, och den som rädes är icke fullkomnad i kärleken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 19, 'Vi älska, därför att han först har älskat oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 20, 'Om någon säger sig älska Gud och hatar sin broder, så är han en lögnare. Ty den som icke älskar sin broder, som han har sett, han kan icke älska Gud, som han icke har sett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 21, 'Och det budet hava vi från honom, att den som älskar Gud, han skall ock älska sin broder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 1, 'Var och en som tror att Jesus är Kristus, han är född av Gud; och var och en som älskar honom som födde, han älskar ock den som är född av honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 2, 'Därför, när vi älska Gud och hålla hans bud, då veta vi att vi älska Guds barn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 3, 'Ty däri består kärleken till Gud, att vi hålla hans bud; och hans bud äro icke tunga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 4, 'Ty allt som är fött av Gud, det övervinner världen; och detta är den seger som har övervunnit världen: vår tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 5, 'Vilken annan kan övervinna världen, än den som tror att Jesus är Guds Son?');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 6, 'Han är den som kom genom vatten och blod, Jesus Kristus, icke med vattnet allenast, utan med vattnet och blodet. Och Anden är den som vittnar, eftersom Anden är sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 7, 'Ty tre äro de som vittna:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 8, 'Anden, vattnet och blodet; och de tre vittna ett och detsamma.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 9, 'Om vi taga människors vittnesbörd för gott, så må väl Guds vittnesbörd vara förmer. Detta är ju Guds vittnesbörd, att han har vittnat om sin Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 10, 'Den som tror på Guds Son, han har vittnesbördet inom sig själv; den som icke tror Gud, han har gjort honom till en ljugare, eftersom han icke har trott på Guds vittnesbörd om sin Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 11, 'Och detta är vittnesbördet: att Gud har givit oss evigt liv; och det livet är i hans Son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 12, 'Den som har Sonen, han har livet; den som icke har Guds Son, han har icke livet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 13, 'Detta har jag skrivit till eder, för att I skolen veta att I haven evigt liv, I som tron på Guds Sons namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 14, 'Och detta är den fasta tillförsikt vi hava till honom, att om vi bedja om något efter hans vilja, så hör han oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 15, 'Och om vi veta att han hör oss, vadhelst vi bedja om, så veta vi ock att vi redan hava det som vi hava bett honom om i vår bön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 16, 'Om någon ser sin broder begå en synd som icke är en synd till döds, då må han bedja, och så skall han giva honom liv, om nämligen synden icke är till döds. Det finnes synd till döds; för sådan säger jag icke att man skall bedja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 17, 'All orättfärdighet är synd; dock finnes det synd som icke är till döds.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 18, 'Vi veta om var och en som är född av Gud att han icke syndar, ty den som har blivit född av Gud, han tager sig till vara, och den onde kommer icke vid honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 19, 'Vi veta att vi äro av Gud, och att hela världen är i den ondes våld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 20, 'Och vi veta att Guds Son har kommit och givit oss förstånd, så att vi kunna känna den Sanne; och vi äro i den Sanne, i hans Son, Jesus Kristus. Denne är den sanne Guden och evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 21, 'Kära barn, tagen eder till vara för avgudarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 1, 'Den äldste hälsar den utvalda frun och hennes barn, vilka jag i sanning älskar, och icke jag allenast, utan ock alla andra som hava lärt känna sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 2, 'Vi älska dem för sanningens skull, som förbliver i oss, och som skall vara med oss till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 3, 'Nåd, barmhärtighet och frid ifrån Gud, Fadern, och ifrån Jesus Kristus, Faderns Son, skall vara med oss i sanning och i kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 4, 'Det har gjort mig stor glädje att jag har funnit flera av dina barn vandra i sanningen, efter det bud som vi hava fått ifrån Fadern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 5, 'Och nu har jag en bön till dig, kära fru. Icke som om jag skreve för att giva dig ett nytt bud; det gäller allenast det bud som vi hava haft från begynnelsen: att vi skola älska varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 6, 'Och däri består kärleken, att vi vandra efter de bud han har givit. Ja, detta är budet, att I skolen vandra i kärleken, enligt vad I haven hört från begynnelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 7, 'Ty många villolärare hava gått ut i världen, vilka icke bekänna att Jesus är Kristus, som skulle komma i köttet; en sådan är Villoläraren och Antikrist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 8, 'Tagen eder till vara, så att I icke förloren det som vi med vårt arbete hava kommit åstad, utan fån full lön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 9, 'Var och en som så går framåt, att han icke förbliver i Kristi lära, han har icke Gud; den som förbliver i den läran, han har både Fadern och Sonen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 10, 'Om någon kommer till eder och icke har den läran med sig, så tagen icke emot honom i edra hus, och hälsen honom icke.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 11, 'Ty den som hälsar honom, han gör sig delaktig i hans onda gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 12, 'Jag hade väl mycket annat att skriva till eder, men jag vill icke göra det med papper och bläck. Jag hoppas att i stället få komma till eder och muntligen tala med eder, för att vår glädje skall bliva fullkomlig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 13, 'Din utvalda systers barn hälsa dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 1, 'Den äldste hälsar Gajus, den älskade brodern, som jag i sanning älskar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 2, 'Min älskade, jag önskar att det i allt må stå väl till med dig, och att du må vara vid god hälsa, såsom det ock står väl till med din själ.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 3, 'Ty det gjorde mig stor glädje, då några av bröderna kommo och vittnade om den sanning som bor i dig, eftersom du ju vandrar i sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 4, 'Jag har ingen större glädje än den att få höra att mina barn vandra i sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 5, 'Min älskade, du handlar såsom en trofast man i allt vad du gör mot bröderna, och detta jämväl när de komma såsom främlingar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 6, 'Dessa hava nu inför församlingen vittnat om din kärlek. Och du gör väl, om du på ett sätt som är värdigt Gud utrustar dem också för fortsättningen av deras resa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 7, 'Ty för hans namns skull hava de dragit åstad, utan att hava tagit emot något av hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 8, 'Därför äro vi å vår sida pliktiga att taga oss an sådana män, så att vi bliva deras medarbetare till att främja sanningen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 9, 'Jag har skrivit till församlingen, men Diotrefes, som önskar att vara den främste bland dem, vill icke göra något för oss.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 10, 'Om jag kommer, skall jag därför påvisa huru illa han gör, då han skvallrar om oss med elaka ord. Och han nöjer sig icke härmed; utom det att han själv intet vill göra för bröderna, hindrar han också andra som vore villiga att göra något, ja, han driver dem ut ur församlingen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 11, 'Mina älskade, följ icke onda föredömen, utan goda. Den som gör vad gott är, han är av Gud; den som gör vad ont är, han har icke sett Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 12, 'Demetrius har fått gott vittnesbörd om sig av alla, ja, av sanningen själv. Också vi giva honom vårt vittnesbörd; och du vet att vårt vittnesbörd är sant.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 13, 'Jag hade väl mycket annat att skriva till dig, men jag vill icke skriva till dig med bläck och penna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 14, 'Ty jag hoppas att rätt snart få se dig, och då skola vi muntligen tala med varandra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 15, 'Frid vare med dig. Vännerna hälsa dig. Hälsa vännerna, var och en särskilt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 1, 'Judas, Jesu Kristi tjänare och Jakobs broder, hälsar de kallade, dem som äro upptagna i Guds, Faderns, kärlek och bevarade åt Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 2, 'Barmhärtighet och frid och kärlek föröke sig hos eder.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 3, 'Mina älskade, då jag nu med all iver har tagit mig för att skriva till eder om vår gemensamma frälsning, finner jag det nödigt att i min skrivelse förmana eder att kämpa för den tro som en gång för alla har blivit meddelad åt de heliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 4, 'Några människor hava nämligen innästlat sig hos eder -- några om vilka det för länge sedan blev skrivet att de skulle hemfalla under den domen -- ogudaktiga människor, som missbruka vår Guds nåd till lösaktighet och förneka vår ende härskare och herre, Jesus Kristus.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 5, 'Men fastän I redan en gång haven fått kunskap om alltsammans, vill jag påminna eder därom, att Herren, sedan han hade frälst sitt folk ur Egyptens land, efteråt förgjorde dem som icke trodde,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 6, 'så ock därom, att de änglar som icke behöllo sin furstehöghet, utan övergåvo sin boning, hava av honom med eviga bojor blivit förvarade i mörker till den stora dagens dom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 7, 'Likaså hava ock Sodom och Gomorra med kringliggande städer, vilka på samma sätt som de förra bedrevo otukt och stodo efter annat umgänge än det naturliga, blivit satta till ett varnande exempel, i det att de få lida straff i evig eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 8, 'Dock göra nu också dessa människor på samma sätt, förblindade av sina drömmar: köttet besmitta de, men andevärldens herrar förakta de, och dess härlige smäda de.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 9, 'Icke så Mikael, överängeln; när denne tvistade med djävulen angående Moses\' kropp, dristade han sig icke att över honom uttala någon smädande dom, utan sade allenast: »Herren näpse dig.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 10, 'Dessa åter smäda vad de icke känna till; och vad de, likasom de oskäliga djuren, med sina naturliga sinnen kunna fatta, det bruka de till sitt fördärv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 11, 'Ve dem! De hava trätt in på Kains väg, de hava för löns skull störtat sig i Balaams villfarelse och hava gått förlorade till följd av en gensträvighet lik Koras.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 12, 'Det är dessa som få hålla gästabud med eder, där de sitta såsom skamfläckar vid edra kärleksmåltider och oförsynt se sig själva till godo. De äro skyar utan vatten, skyar som drivas bort av vindarna. De äro träd som stå nakna på senhösten, ofruktbara, i dubbel måtto döda, uppryckta med rötterna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 13, 'De äro vilda havsvågor som uppkasta sina egna skändligheters skum. De äro irrande stjärnor, åt vilka det svarta mörkret är förvarat till evig tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 14, 'Om dessa var det ock som Enok, den sjunde från Adam, profeterade och sade: »Se, Herren kommer med sina mångtusen heliga,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 15, 'för att hålla dom över alla och bestraffa alla de ogudaktiga för alla de ogudaktiga gärningar som de hava övat, och för alla de förmätna ord som de i sin syndiga ogudaktighet hava talat mot honom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 16, 'De äro människor som alltid knorra och knota över sin lott, medan de likväl vandra efter sina egna begärelser. Och deras mun talar stora ord, under det att de dock av egennytta söka vara människor till behag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 17, 'Men kommen ihåg, I mina älskade, vad som har blivit förutsagt av vår Herres, Jesu Kristi, apostlar,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 18, 'huru de sade till eder: »I den yttersta tiden skola bespottare uppstå, som vandra efter sina egna ogudaktiga begärelser.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 19, 'Det är dessa människor som vålla söndringar, dessa som äro »själiska»[1] och icke hava ande.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 20, 'Men I, mina älskade, uppbyggen eder på eder allraheligaste tro, bedjen i den helige Ande,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 21, 'och bevaren eder så i Guds kärlek, under det att I vänten på vår Herres, Jesu Kristi, barmhärtighet, till evigt liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 22, 'Mot somliga av dem, sådana som äro tvivlande, mån I vara barmhärtiga');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 23, 'och frälsa dem genom att rycka dem ur elden; mot de andra mån I också vara barmhärtiga, dock med fruktan, så att I avskyn till och med deras livklädnad, den av köttet befläckade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 24, 'Men honom som förmår bevara eder ifrån fall och ställa eder inför sin härlighet ostraffliga, i fröjd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 25, 'honom som allena är Gud, och som är vår Frälsare genom Jesus Kristus, vår Herre, honom tillhör ära, majestät, välde och makt, såsom före all tid, så ock nu och i alla evigheter. Amen. [1] Se Själisk i Ordförkl');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 1, 'Detta är en uppenbarelse från Jesus Kristus, en som Gud gav honom för att visa sina tjänare, vad som snart skall ske. Och medelst ett budskap genom sin ängel gav han det till känna för sin tjänare Johannes,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 2, 'som här vittnar och frambär Guds ord och Jesu Kristi vittnesbörd, allt vad han själv har sett.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 3, 'Salig är den som får uppläsa denna profetias ord, och saliga äro de som få höra dem och som taga vara på, vad däri är skrivet; ty tiden är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 4, 'Johannes hälsar de sju församlingarna i provinsen Asien. Nåd vare med eder och frid från honom som är, och som var, och som skall komma, så ock från de sju andar, som stå inför hans tron,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 5, 'och från Jesus Kristus, det trovärdiga vittnet, den förstfödde bland de döda, den som är härskaren över konungarna på jorden. Honom som älskar oss, och som har löst oss från våra synder med sitt blod');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 6, 'och gjort oss till ett konungadöme, till präster åt sin Gud och Fader, honom tillhör äran och väldet i evigheternas evigheter, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 7, 'Se, han kommer med skyarna, och allas ögon skola se honom, ja ock deras som hava stungit honom; och alla släkter på jorden skola jämra sig vid hans åsyn. Ja, amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 8, 'Jag är A och O[1], säger Herren Gud, han som är, och som var, och som skall komma, den Allsmäktige.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 9, 'Jag, Johannes, eder broder, som med eder har del i bedrövelsen och riket och ståndaktigheten i Jesus, jag befann mig på den ö som heter Patmos, för Guds ords och Jesu vittnesbörds skull.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 10, 'Jag kom i andehänryckning på Herrens dag och fick då bakom mig höra en stark röst, lik ljudet av en basun,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 11, 'och den sade: »Skriv upp i en bok vad du får se, och sänd den till de sju församlingarna i Efesus och Smyrna och Pergamus och Tyatira och Sardes och Filadelfia och Laodicea.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 12, 'Och jag vände mig om för att se vad det var för en röst som talade till mig; och när jag vände mig om, fick jag se sju gyllene ljusstakar');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 13, 'och mitt i bland ljusstakarna någon som liknade en människoson, klädd i en fotsid klädnad och omgjordad kring bröstet med ett gyllene bälte.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 14, 'Hans huvud och hår var vitt såsom vit ull, såsom snö, och hans ögon voro såsom eldslågor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 15, 'Hans fötter liknade glänsande malm, när den har blivit glödgad i en ugn. Och hans röst var såsom bruset av stora vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 16, 'I sin högra hand hade han sju stjärnor, och från hans mun utgick ett skarpt tveeggat svärd, och hans ansikte var såsom solen, när den skiner i sin fulla kraft.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 17, 'När jag såg honom, föll jag ned för hans fötter, såsom hade jag varit död. Men han lade sin högra hand på mig och sade: »Frukta icke. Jag är den förste och den siste');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 18, 'och den levande; jag var död, men se, jag lever i evigheternas evigheter och jag har nycklarna till döden och dödsriket.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 19, 'Så skriv nu upp, vad du har sett, och skriv upp både vad som nu är, och vad som härefter skall ske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 20, 'Vad angår hemligheten med de sju stjärnorna, som du har sett i min högra hand, och de sju gyllene ljusstakarna, så må du veta att de sju stjärnorna äro de sju församlingarnas änglar, och att de sju ljusstakarna äro de sju församlingarna.» [1] Se A och O i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 1, 'Skriv till Efesus\' församlings ängel: »Så säger han som håller de sju stjärnorna i sin högra hand, han som går omkring bland de sju gyllene ljusstakarna:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 2, 'Jag känner dina gärningar och ditt arbete och din ståndaktighet, och jag vet att du icke kan lida onda människor; du har prövat dem som säga sig vara apostlar, men icke äro det, och har funnit dem vara lögnare.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 3, 'Och du är ståndaktig och har burit mycket för mitt namns skull och har icke förtröttats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 4, 'Men jag har det emot dig, att du har övergivit din första kärlek.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 5, 'Betänk då varifrån du har fallit, och bättra dig, och gör åter sådana gärningar som du gjorde under din första tid. Varom icke, så skall jag komma över dig och skall flytta din ljusstake från dess plats, såframt du icke gör bättring.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 6, 'Men den berömmelsen har du, att du hatar nikolaiternas gärningar, som också jag hatar. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 7, 'Den som har öra, han höre vad Anden säger till församlingarna. Den som vinner seger, åt honom skall jag giva att äta av livets träd, som står i Guds paradis.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 8, 'Och skriv till Smyrnas församlings ängel: »Så säger den förste och den siste, han som var död och åter har blivit levande:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 9, 'Jag känner din bedrövelse och din fattigdom -- dock, du är rik! -- och jag vet vilken försmädelse du utstår av dem som säga sig vara judar, men icke äro detta, utan äro en Satans synagoga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 10, 'Frukta icke för det som du skall få lida. Se, djävulen skall kasta somliga av eder i fängelse, för att I skolen sättas på prov; och I skolen få utstå bedrövelse i tio dagar. Var trogen intill döden, så skall jag giva dig livets krona,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 11, 'Den som har öra, han höre vad Anden säger till församlingarna. Den som vinner seger, han skall förvisso icke lida någon skada av den andra döden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 12, 'Och skriv till Pergamus\' församlings ängel: »Så säger han som har det skarpa tveeggade svärdet:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 13, 'Jag vet var du bor: där varest Satan har sin tron. Och dock håller du fast vid mitt namn; och tron på mig förnekade du icke ens på den tid då Antipas, mitt vittne, min trogne tjänare, blev dräpt hos eder -- där varest Satan bor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 14, 'Men jag har något litet emot dig: du har hos dig några som hålla fast vid Balaams lära, hans som lärde Balak huru han skulle lägga en stötesten för Israels barn, så att de skulle äta kött från avgudaoffer och bedriva otukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 15, 'Så har också du några som på lika sätt hålla sig till nikolaiternas lära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 16, 'Gör då bättring; varom icke, så skall jag snart komma över dig och skall strida mot dem med min muns svärd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 17, 'Den som har öra, han höre vad Anden säger till församlingarna. Den som vinner seger, åt honom skall jag giva av det fördolda mannat; och jag skall giva honom en vit sten och ett nytt namn skrivet på den stenen, ett namn som ingen känner, utom den som får det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 18, 'Och skriv till Tyatiras församlings ängel: »Så säger Guds Son, han som har ögon såsom eldslågor, han vilkens fötter likna glänsande malm:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 19, 'Jag känner dina gärningar och din kärlek och din tro, och jag vet huru du har tjänat och varit ståndaktig, och huru dina sista gärningar äro flera än dina första.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 20, 'Men jag har det emot dig att du är så efterlåten mot kvinnan Jesabel -- hon som säger sig vara en profetissa och uppträder såsom lärare och förleder mina tjänare till att bedriva otukt och till att äta kött från avgudaoffer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 21, 'Jag har givit henne tid till bättring, men hon vill icke göra bättring och upphöra med sin otukt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 22, 'Se, jag vill lägga henne ned på sjuksängen; och över dem som med henne begå äktenskapsbrott vill jag sända stor vedermöda, såframt de icke bättra sig och upphöra med att göra hennes gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 23, 'Och hennes barn skall jag dräpa. Och alla församlingarna skola förnimma, att jag är den som rannsakar njurar och hjärtan; och jag skall giva var och en av eder efter hans gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 24, 'Men till eder, I andra som bon i Tyatira, till eder alla som icke haven denna lära, då I ju icke »haven lärt känna djupheterna», såsom de säga -- ja, Satans djupheter! -- till eder säger jag: Jag lägger icke på eder någon ny börda;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 25, 'hållen allenast fast vid det som I haven, till dess jag kommer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 26, 'Den som vinner seger och intill änden troget gör mina gärningar, åt honom skall jag giva makt över hedningarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 27, 'och han skall styra dem med järnspira, likasom när man krossar lerkärl,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 28, 'såsom ock jag har fått den makten av min Fader; och jag skall giva honom morgonstjärnan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 29, 'Den som har öra, han höre vad Anden säger till församlingarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 1, 'Och skriv till Sardes\' församlings ängel: »Så säger han som har Guds sju andar och de sju stjärnorna: Jag känner dina gärningar; du har det namnet om dig, att du lever, men du är död.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 2, 'Vakna upp och håll dig vaken, och styrk det som ännu är kvar, det som har varit nära att dö. Ty jag har icke funnit dina gärningar vara fullkomliga inför min Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 3, 'Tänk nu på huru du undfick ordet och hörde det, och tag vara på därpå och gör bättring. Om du icke håller dig vaken, så skall jag komma såsom en tjuv, och du skall förvisso icke veta vilken stund jag kommer över dig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 4, 'Dock kunna hos dig i Sardes nämnas några få som icke hava fläckat sina kläder; och dessa skola vandra med mig i vita kläder, ty de äro värdiga därtill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 5, 'Den som vinner seger, han skall så bliva klädd i vita kläder, och jag skall aldrig utplåna hans namn ur livets bok, utan kännas vid hans namn inför min Fader och inför hans änglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 6, 'Den som har öra, han höre vad Anden säger till församlingarna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 7, 'Och skriv till Filadelfias församlings ängel: »Så säger den Helige, den Sannfärdige, han som har \'Davids nyckel\', han som \'upplåter, och ingen kan tillsluta\', han som \'tillsluter, och ingen upplåter\':');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 8, 'Jag känner dina gärningar. Se, jag har låtit dig finna en öppen dörr, som ingen kan tillsluta. Ty väl är din kraft ringa, men du har tagit vara på mitt ord och icke förnekat mitt namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 9, 'Se, jag vill överlämna åt dig några från Satans synagoga, några av dem som säga sig vara judar, men icke äro det, utan ljuga; ja, jag vill göra så, att de komma ock falla ned för dina fötter, och de skola förstå, att jag har fått dig kär.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 10, 'Eftersom du har tagit vara på mitt bud om ståndaktighet, skall ock jag taga vara på dig och frälsa dig ut ur den prövningens stund som skall komma över hela världen, för att sätta jordens inbyggare på prov.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 11, 'Jag kommer snart; håll fast det du har, så att ingen tager din krona.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 12, 'Den som vinner seger, honom skall jag göra till en pelare i min Guds tempel, och han skall aldrig mer lämna det; och jag skall skriva på honom min Guds namn och namnet på min Guds stad, det nya Jerusalem, som kommer ned från himmelen, från min Gud, så ock mitt eget nya namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 13, 'Den som har öra, han höre vad Anden säger till församlingarna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 14, 'Och skriv till Laodiceas församlings ängel: »Så säger han som är Amen[1], den trovärdiga och sannfärdiga vittnet, begynnelsen till Guds skapelse:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 15, 'Jag känner dina gärningar: du är varken kall eller varm. Jag skulle önska att du vore antingen kall eller varm.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 16, 'Men nu, då du är ljum och varken varm eller kall, skall jag utspy dig ur min mun.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 17, 'Du säger ju: \'Jag är rik, ja, jag har vunnit rikedomar och behöver intet\'; och du vet icke att du just är eländig och ömkansvärd och fattig och blind och naken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 18, 'Så råder jag dig då att du köper av mig guld som är luttrat i eld, för att du skall bliva rik, och att du köper vita kläder till att kläda dig i, för att din nakenhets skam icke skall bliva uppenbar, och att du köper ögonsalva till att smörja dina ögon med, för att du skall kunna se.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 19, '\'Alla som jag älskar, dem tuktar och agar jag.\' Så gör nu bättring med all flit.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 20, 'Se, jag står för dörren och klappar; om någon lyssnar till min röst och upplåter dörren, så skall jag gå in till honom och hålla måltid med honom och han med mig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 21, 'Den som vinner seger, honom skall jag låta sitta med mig på min tron, likasom jag själv har vunnit seger och satt mig med min Fader på hans tron.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 22, 'Den som har öra, han höre vad Anden säger till församlingarna. [1] Detta uttryck är hämtat från Jes 65,16, där det ord, som i den svenska översättningen återgives med den sannfärdige, i den hebreiska grundtexten är amen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 1, 'Sedan fick jag se en dörr vara öppnad i himmelen; och den röst, lik ljudet av en basun, som jag förut hade hört tala till mig, sade: »Kom hit upp, så skall jag visa dig, vad som skall ske härefter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 2, 'I detsamma kom jag i andehänryckning. Och jag fick se en tron vara framsatt i himmelen, och någon satt på den tronen;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 3, 'och han som satt därpå var till utseendet såsom jaspissten och karneol. Och runt omkring tronen gick en regnbåge, som till utseendet var såsom en smaragd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 4, 'Och jag såg tjugufyra andra troner runt omkring tronen, och på de tronerna sutto tjugufyra äldste, klädda i vita kläder, med gyllene kransar på sina huvuden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 5, 'Och från tronen utgingo ljungeldar och dunder och tordön; och framför tronen brunno sju eldbloss, det är Guds sju andar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 6, 'Framför tronen syntes ock likasom ett glashav, likt kristall; och runt omkring tronen stodo fyra väsenden, ett mitt för var sida av tronen och de voro fullsatta med ögon framtill och baktill.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 7, 'Och det första väsendet liknade ett lejon, det andra väsendet liknade en ung tjur, det tredje väsendet hade ett ansikte såsom en människa, det fjärde väsendet liknade en flygande örn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 8, 'Och vart och ett av de fyra väsendena hade sex vingar; runt omkring, jämväl under vingarna voro de fullsatta med ögon. Och dag och natt sade de utan uppehåll: »Helig, helig, helig är Herren Gud den Allsmäktige, han som var, och som är, och som skall komma.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 9, 'Och när väsendena hembära pris och ära och tack åt honom som sitter på tronen och tillbedja honom som lever i evigheternas evigheter,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 10, 'då falla de tjugufyra äldste ned inför honom som sitter på tronen, och tillbedja honom som lever i evigheternas evigheter, och lägga sina kransar ned inför tronen och säga;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 11, '»Du, vår Herre och Gud, är värdig att mottaga pris och ära och makt, ty du har skapat allting, och därför att så var din vilja, kom det till och blev skapat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 1, 'Och i högra handen på honom som satt på tronen såg jag en bokrulle, med skrift både på insidan och på utsidan, och förseglad med sju insegel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 2, 'Och jag såg en väldig ängel som utropade med hög röst: »Vem är värdig att öppna bokrullen och bryta dess insegel?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 3, 'Men ingen, vare sig i himmelen eller på jorden eller under jorden, kunde öppna bokrullen eller se vad som stod däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 4, 'Och jag grät bittert över att ingen befanns vara värdig att öppna bokrullen eller se, vad som stod däri.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 5, 'Men en av de äldste sade till mig: »Gråt icke. Se, lejonet av Juda stam, telningen från Davids rot, har vunnit seger, så att han kan öppna bokrullen och och bryta dess sju insegel.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 6, 'Då fick jag se att mellan tronen och de fyra väsendena och de äldste stod ett lamm, som såg ut såsom hade det varit slaktat. Det hade sju horn och sju ögon, det är Guds sju andar, vilka äro utsända över hela jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 7, 'Och det trädde fram och tog bokrullen ur högra handen på honom som satt på tronen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 8, 'Och när han tog bokrullen, föllo de fyra väsendena och de tjugufyra äldste ned inför Lammet; och de hade var och en sin harpa och hade gyllene skålar, fulla med rökelse, det är de heligas böner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 9, 'Och de sjöngo en ny sång som lydde så: »Du är värdig att taga bokrullen och att bryta dess insegel, ty du har blivit slaktad, och med ditt blod har du åt Gud köpt människor, av alla stammar och tungomål och folk och folkslag,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 10, 'och gjort dem åt vår Gud till ett konungadöme och till präster, och de skola regera på jorden»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 11, 'Och i min syn fick jag höra röster av många änglar runt omkring tronen och omkring väsendena och de äldste; och deras antal var tio tusen gånger tio tusen och tusen gånger tusen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 12, 'Och de sade med hög röst: »Lammet som blev slaktat, är värdigt att mottaga makten, så ock rikedom och vishet och starkhet och ära, och pris och lov.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 13, 'Och allt skapat, både i himmelen och på jorden och under jorden och på havet, och allt vad i dem var, hörde jag säga: »Honom, som sitter på tronen, och Lammet tillhör lovet och äran och priset och väldet i evigheternas evigheter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 14, 'Och de fyra väsendena sade »amen», och de äldste föllo ned och tillbådo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 1, 'Och jag såg Lammet bryta det första av de sju inseglen; och jag hörde ett av de fyra väsendena säga såsom med tordönsröst: »Kom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 2, 'Då fick jag se en vit häst; och mannen som satt på den hade en båge, och en segerkrans blev honom given, och han drog ut såsom segrare och för att segra.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 3, 'Och när det bröt det andra inseglet, hörde jag det andra väsendet säga »Kom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 4, 'Då kom en annan häst fram, en som var röd; och åt mannen som satt på den blev givet att taga friden bort från jorden, så att människorna skulle slakta varandra. Och ett stort svärd blev honom givet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 5, 'Och när det bröt det tredje inseglet, hörde jag det tredje väsendet säga »Kom.» Då fick jag se en svart häst; och mannen som satt på den hade en vågskål i sin hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 6, 'Och jag hörde likasom en röst mitt ibland de fyra väsendena säga: »Ett mått[1] vete för en silverpenning[1] och tre mått korn för en silverpenning! Och oljan och vinet må du icke skada.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 7, 'Och när det bröt det fjärde inseglet, hörde jag det fjärde väsendets röst säga: »Kom.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 8, 'Då fick jag se en blekgul häst; och mannen som satt på den, hans namn var Döden, och Dödsriket följde med honom. Och åt dem gavs makt över fjärdedelen av jorden, så att de skulle få dräpa med svärd och genom hungersnöd och pest och genom vilddjuren på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 9, 'Och när det bröt det femte inseglet, såg jag under altaret de människors själar, som hade blivit slaktade för Guds ords skull och för det vittnesbörds skull, som de hade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 10, 'Och de ropade med hög röst och sade: »Huru länge, du helige och sannfärdige Herre, skall du dröja att hålla dom och att utkräva vårt blod av jordens inbyggare?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 11, 'Och åt var och en av dem gavs en vit, fotsid klädnad, och åt dem blev tillsagt att de ännu en liten tid skulle giva sig till ro, till dess jämväl skaran av deras medtjänare och bröder, som skulle bliva dräpta likasom de själva, hade blivit fulltalig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 12, 'Och jag såg Lammet bryta det sjätte inseglet. Då blev det en stor jordbävning, och solen blev svart som en sorgdräkt, och månen blev hel och hållen såsom blod;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 13, 'och himmelens stjärnor föllo ned på jorden, såsom när ett fikonträd fäller sina omogna frukter, då det skakas av en stark vind.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 14, 'Och himmelen vek undan, såsom när en bokrulle rullas tillhopa; och alla berg och öar flyttades bort ifrån sin plats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 15, 'Och konungarna på jorden och stormännen och krigsöverstarna och alla de rika och de väldiga, ja, alla, både trälar och fria, dolde sig i hålor och bland bergsklippor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 16, 'Och de sade till bergen och klipporna: »Fallen över oss och döljen oss för dens ansikte, som sitter på tronen, och för Lammets vrede.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 17, 'Ty deras vredes stora dag är kommen, och vem kan bestå?» [1] Se Mått och Silverpenning i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 1, 'Sedan såg jag fyra änglar stå vid jordens fyra hörn och hålla tillbaka jordens fyra vindar, för att ingen vind skulle blåsa över jorden eller över havet eller mot något träd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 2, 'Och jag såg en annan ängel träda fram ifrån öster med den levande Gudens signet. Och han ropade med hög röst till de fyra änglar som hade fått sig givet att skada jorden och havet,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 3, 'och sade: »Gören icke jorden eller havet eller träden någon skada, förrän vi hava tecknat vår Guds tjänare med insegel på deras pannor.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 4, 'Och jag fick höra antalet av dem som voro tecknade med insegel, ett hundra fyrtiofyra tusen tecknade, av alla Israels barns stammar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 5, 'av Juda stam tolv tusen tecknade, av Rubens stam tolv tusen, av Gads stam tolv tusen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 6, 'av Asers stam tolv tusen, av Neftalims stam tolv tusen, av Manasses\' stam tolv tusen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 7, 'av Simeons stam tolv tusen, av Levi stam tolv tusen, av Isaskars stam tolv tusen,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 8, 'av Sabulons stam tolv tusen, av Josefs stam tolv tusen, av Benjamins stam tolv tusen tecknade.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 9, 'Sedan fick jag se en stor skara, som ingen kunde räkna, en skara ur alla folkslag och stammar och folk och tungomål stå inför tronen och inför Lammet; och de voro klädda i vita, fotsida kläder och hade palmer i sina händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 10, 'Och de ropade med hög röst och sade: »Frälsningen tillhör vår Gud, honom som sitter på tronen, och Lammet.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 11, 'Och alla änglar, som stodo runt omkring tronen och omkring de äldste och de fyra väsendena, föllo ned på sina ansikten inför tronen och tillbådo Gud');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 12, 'och sade: »Amen. Lovet och priset och visheten och tacksägelsen och äran och makten och starkheten tillhöra vår Gud i evigheternas evigheter. Amen.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 13, 'Och en av de äldste tog till orda och sade till mig: »Dessa som äro klädda i de vita, fotsida kläderna, vilka äro de, och varifrån hava de kommit?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 14, 'Jag svarade honom: »Min herre, du vet själv det.» Då sade han till mig: »Dessa äro de som komma ur den stora bedrövelsen, och som hava tvagit sina kläder och gjort dem vita i Lammets blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 15, 'Därför stå de inför Guds tron och tjäna honom, dag och natt, i hans tempel. Och han som sitter på tronen skall slå upp sitt tabernakel över dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 16, '\'De skola icke mer hungra och icke mer törsta, och solens hetta skall icke träffa dem, ej heller eljest någon brännande hetta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 17, 'Ty Lammet, som står mitt för tronen, skall vara deras herde och leda dem till livets vattenkällor, och \'Gud skall avtorka alla tårar från deras ögon\'.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 1, 'Och när Lammet bröt det sjunde inseglet, uppstod i himmelen en tystnad, som varade vid pass en halv timme.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 2, 'Och jag fick se de sju änglar, som stå inför Gud; åt dem gåvos sju basuner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 3, 'Och en annan ängel kom och ställde sig vid altaret, och han hade ett gyllene rökelsekar; och mycken rökelse var given åt honom, för att han skulle lägga den till alla de heligas böner på det gyllene altare som stod framför tronen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 4, 'Och ur ängelns hand steg röken av rökelsen med de heligas böner upp inför Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 5, 'Och ängeln tog rökelsekaret och fyllde det med eld från altaret och kastade elden ned på jorden. Då kommo tordön och dunder och ljungeldar och jordbävning.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 6, 'Och de sju änglarna, som hade de sju basunerna, gjorde sig redo att stöta i sina basuner.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 7, 'Och den förste stötte i sin basun. Då kom hagel och eld, blandat med blod, och det kastades ned på jorden; och tredjedelen av jorden brändes upp, och tredjedelen av träden brändes upp, och allt grönt gräs brändes upp.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 8, 'Och den andre ängeln stötte i sin basun. Då var det som om ett stort brinnande berg hade blivit kastat i havet; och tredjedelen av havet blev blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 9, 'Och tredjedelen av de levande varelser som funnos i havet omkom; och tredjedelen av skeppen förgicks.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 10, 'Och den tredje ängeln stötte i sin basun. Då föll från himmelen en stor stjärna, brinnande såsom ett bloss; och den föll ned över tredjedelen av strömmarna och över vattenkällorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 11, 'Och stjärnans namn var Malört. Och tredjedelen av vattnet blev bitter malört; och många människor omkommo genom vattnet, därför att det hade blivit så bittert.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 12, 'Och den fjärde ängeln stötte i sin basun. Då drabbade hemsökelsen tredjedelen av solen och tredjedelen av månen och tredjedelen av stjärnorna, så att tredjedelen av dem förmörkades och dagen miste tredjedelen av sitt ljus, sammalunda ock natten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 13, 'Sedan fick jag i min syn höra en örn, som flög fram uppe i himlarymden, ropa med hög röst: »Ve, ve, ve över jordens inbyggare, när de tre övriga änglar, som skola stöta i basun, låta sina basuner ljuda!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 1, 'Och den femte ängeln stötte i sin basun. Då såg jag en stjärna vara fallen ifrån himmelen ned på jorden; och åt henne gavs nyckeln till avgrundens brunn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 2, 'Och hon öppnade avgrundens brunn. Då steg en rök upp ur brunnen, lik röken från en stor ugn, och solen och luften förmörkades av röken från brunnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 3, 'Och ur röken kommo gräshoppor ut över jorden; och åt dem gavs samma makt som skorpionerna på jorden hava.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 4, 'Och dem blev tillsagt, att de icke skulle skada gräset på jorden eller något annat grönt eller något träd, utan allenast de människor som icke hade Guds insegel på sina pannor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 5, 'Och åt dem blev givet att, icke att döda dem, men att plåga dem i fem månader; och plågan, som de vållade var såsom den plåga en skorpion åstadkommer, när den stinger en människa.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 6, 'På den tiden skola människorna söka döden, men icke kunna finna den; de skola åstunda att dö, men döden skall fly undan ifrån dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 7, 'Och gräshopporna tedde sig såsom hästar, rustade till strid. På sina huvuden hade de likasom kransar, som syntes vara av guld. Deras ansikten voro såsom människors ansikten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 8, 'De hade hår såsom kvinnors hår, och deras tänder voro såsom lejons.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 9, 'De hade bröst, som liknade järnpansar; och rasslet av deras vingar var såsom vagnsrasslet, när många hästar med sina vagnar störta fram till strid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 10, 'De hade stjärtar med gaddar, såsom skorpioner hava; och i deras stjärtar låg den makt de hade fått att i fem månader skada människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 11, 'Till konung över sig hade de avgrundens ängel, vilkens namn på hebreiska är Abaddon och som på grekiska har namnet Apollyon[1].');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 12, 'Det första ve har gått till ända; se, efter detta komma ännu två andra ve.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 13, 'Och den sjätte ängeln stötte i sin basun. Då hörde jag en röst från de fyra hornen på det gyllene altare, som stod inför Guds ansikte,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 14, 'säga till den sjätte ängeln, den som hade basunen: »Lös de fyra änglar, som hållas bundna invid den stora floden Eufrat.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 15, 'Och de fyra änglarna löstes, de som just för den timmen, på den dagen, i den månaden, under det året hade hållits redo att dräpa tredjedelen av människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 16, 'Och antalet ryttare i de ridande skarorna var två gånger tio tusen gånger tio tusen; jag fick höra att de voro så många.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 17, 'Och hästarna och männen som sutto på dem tedde sig för min syn på detta sätt: männen hade eldröda och mörkblå och svavelgula pansar; och hästarna hade huvuden såsom lejon, och ur deras gap gick ut eld och rök och svavel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 18, 'Av dessa tre plågor -- av elden och röken och svavlet som gick ut ur deras gap -- dödades tredjedelen av människorna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 19, 'Ty hästarnas makt låg i deras gap och i deras svansar. Deras svansar liknade nämligen ormar, och hade huvuden, och med dem var det, som de gjorde skada.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 20, 'Men de återstående människorna, de som icke hade blivit dödade genom dessa plågor, gjorde icke bättring; de vände sig icke ifrån belätena, som de hade gjort med egna händer, och upphörde icke att tillbedja onda andar och avgudar av guld och silver och koppar och sten och trä, som varken kunna se eller höra eller gå.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 21, 'De gjorde icke bättring och upphörde icke med sina mordgärningar och trolldomskonster, sin otukt och sitt tjuveri. [1] D. ä. fördärvaren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 1, 'Och jag såg en annan väldig ängel komma ned från himmelen. Han var klädd i en sky och hade regnbågen över sitt huvud, och hans ansikte var såsom solen, och hans ben voro såsom eldpelare;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 2, 'och i sin hand hade han en öppen liten bokrulle. Och han satte sin högra fot på havet och sin vänstra på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 3, 'Och han ropade med hög röst, såsom när ett lejon ryter. Och när han hade ropat, läto de sju tordönen höra sina röster.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 4, 'Och sedan de sju tordönen hade talat, tänkte jag skriva, men jag fick då höra en röst från himmelen säga: »Göm såsom under insegel vad de sju tordönen hava talat, och skriv icke upp det.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 5, 'Och ängeln, som jag såg stå på havet och på jorden, lyfte sin högra hand upp mot himmelen');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 6, 'och svor vid honom som lever i evigheternas evigheter, vid honom som har skapat himmelen och vad däri är, och jorden och vad därpå är, och havet och vad däri är, och sade: »Ingen tid skall mer givas,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 7, 'utan i de dagar, då den sjunde ängelns röst höres, när det sker att han stöter i sin basun, då är Guds hemliga rådslut fullbordat, i enlighet med det glada budskap som han har förkunnat för sina tjänare profeterna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 8, 'Och den röst som jag hade hört från himmelen hörde jag nu åter tala till mig; den sade: »Gå och tag den öppna bokrulle som ängeln har i sin hand, han som står på havet och på jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 9, 'Då gick jag bort till ängeln och bad honom att han skulle giva mig bokrullen. Och han sade till mig: »Tag den och ät upp den; den skall vålla dig bitter plåga i din buk, men i din mun skall den vara söt såsom honung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 10, 'Då tog jag bokrullen ur ängelns hand och åt upp den; och den var i min mun söt såsom honung, men när jag hade ätit upp den, kände jag bitter plåga i min buk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 11, 'Och mig blev sagt: »Du måste än ytterligare profetera om många folk och folkslag och tungomål och konungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 1, 'Och ett rör, likt en mätstång, gavs åt mig, och mig blev sagt: »Stå upp och mät Guds tempel och altaret tillika med dem som tillbedja därinne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 2, 'Men lämna å sido templets yttre förgård och mät den icke; ty den är prisgiven åt hedningarna, och de skola under fyrtiotvå månader förtrampa den heliga staden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 3, 'Och jag skall låta mina två vittnen under ett tusen två hundra sextio dagar profetera, höljda i säcktyg.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 4, 'Dessa vittnen äro de två olivträd och de två ljusstakar som stå inför jordens Herre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 5, 'Och om någon vill göra dem skada, så går eld ut ur deras mun och förtär deras ovänner; ja, om någon vill göra dem skada, så skall han bliva dödad på det sättet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 6, 'De hava makt att tillsluta himmelen, så att intet regn faller under den tid de profetera; de hava ock makt över vattnet, att förvandla det till blod, och makt att slå jorden med alla slags plågor, så ofta de vilja.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 7, 'Och när de hava till fullo framburit sitt vittnesbörd, skall vilddjuret, det som skall stiga upp ur avgrunden, giva sig i strid med dem och skall övervinna dem och döda dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 8, 'Och deras döda kroppar skola bliva liggande på gatan i den stora staden som, andligen talat, heter Sodom och Egypten, den stad där också deras Herre blev korsfäst.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 9, 'Och människor av allahanda folk och stammar och tungomål och folkslag skola i tre och en halv dagar se deras döda kroppar ligga där, och de skola icke tillstädja att kropparna läggas i någon grav.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 10, 'Och jordens inbyggare skola glädjas över vad som har vederfarits dem och skola fröjda sig och sända varandra gåvor; ty dessa två profeter hade varit en plåga för jordens inbyggare.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 11, 'Men efter tre och en halv dagar kom livets ande från Gud in i dem, och de reste sig upp på sina fötter; och en stor fruktan föll över dem som sågo dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 12, 'Och de hörde en stark röst från himmelen, som sade till dem: »Kommen hit upp.» Då stego de i en sky upp till himmelen, i sina ovänners åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 13, 'Och i samma stund blev det en stor jordbävning, och tiondedelen av staden störtade samman, och genom jordbävningen omkommo sju tusen människor; och de övriga blevo förskräckta och gåvo ära åt Gud i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 14, 'Det andra ve har gått till ända; se, det tredje ve kommer snart.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 15, 'Och den sjunde ängeln stötte i sin basun. Då ljödo i himmelen starka röster som sade: »Väldet över världen har blivit vår Herres och hans Smordes, och han skall vara konung i evigheternas evigheter.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 16, 'Och de tjugufyra äldste, som sutto på sina troner inför Gud, föllo ned på sina ansikten och tillbådo Gud');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 17, 'och sade: »Vi tacka dig, Herre Gud, du Allsmäktige, du som är, och som var, för att du har tagit i besittning din stora makt och trätt fram såsom konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 18, 'Folken vredgades, men din vredes dag har nu kommit, och den tid då de döda skola få sin dom, och då du skall löna dina tjänare profeterna och de heliga och dem som frukta ditt namn, både små och stora, och då du skall fördärva dem som fördärva jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 19, 'Och Guds tempel i himmelen öppnades, och hans förbundsark blev synlig i hans tempel. Då kommo ljungeldar och dunder och tordön och jordbävning och starkt hagel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 1, 'Och ett stort tecken visade sig i himmelen: där syntes en kvinna, som hade solen till sin klädnad och månen under sina fötter, och en krans av tolv stjärnor på sitt huvud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 2, 'Hon var havande och ropade i barnsnöd och födslovånda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 3, 'Ännu ett annat tecken visade sig i himmelen: där syntes en stor röd drake, som hade sju huvuden och tio horn, och på sina huvuden sju kronor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 4, 'Och hans stjärt drog med sig tredjedelen av himmelens stjärnor och kastade den ned på jorden. Och draken stod framför kvinnan som skulle föda, ty han ville uppsluka hennes barn, när hon hade fött det.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 5, 'Och hon födde ett barn gossebarn, som en gång skall styra alla folk med järnspira. Men hennes barn blev uppryckt till Gud och till hans tron;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 6, 'Och kvinnan flydde ut i öknen, där hon har en plats sig beredd av Gud, och där hon skulle få sitt uppehälle under ett tusen två hundra sextio dagar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 7, 'Och en strid uppstod i himmelen: Mikael och hans änglar gåvo sig i strid med draken; och draken och hans änglar stridde mot dem,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 8, 'men de förmådde intet mot dem, och i himmelen fanns nu icke mer någon plats för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 9, 'Och den store draken, den gamle ormen, blev nedkastad, han som kallas Djävul och Satan, och som förvillar hela världen; han blev nedkastad till jorden, och hans änglar kastades ned jämte honom.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 10, 'Och jag hörde en stark röst i himmelen säga: »Nu har frälsningen och makten och riket blivit vår Guds, och väldet hans Smordes; ty våra bröders åklagare är nedkastad, han som dag och natt anklagade dem inför vår Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 11, 'De övervunno honom i kraft av Lammets blod och i kraft av sitt vittnesbörds ord: de älskade icke så sitt liv, att de drogo sig undan döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 12, 'Glädjens fördenskull, I himlar och I som bon i dem. Men ve dig, du jord, och dig, du hav! Ty djävulen har kommit ned till eder i stor vrede, eftersom han vet att den tid han har kvar är kort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 13, 'Och när draken såg att han var nedkastad på jorden, förföljde han kvinnan, som hade fött gossebarnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 14, 'Men åt kvinnan gåvos den stora örnens två vingar, för att hon skulle flyga ut i öknen till den plats där hon skulle få sitt uppehälle under en tid och tider och en halv tid, fjärran ifrån ormens åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 15, 'Då sprutade ormen ur sitt gap vatten efter kvinnan såsom en ström, för att strömmen skulle bortföra henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 16, 'Men jorden kom kvinnan till hjälp; jorden öppnade sin mun och drack upp strömmen, som draken hade sprutat ut ur sitt gap.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 17, 'Och draken vredgades än mer på kvinnan och gick åstad för att föra krig mot de övriga av hennes säd, mot dem som hålla Guds bud och hava Jesu vittnesbörd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 18, 'Och han ställde sig på sanden invid havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 1, 'Då såg jag ett vilddjur stiga upp ur havet; det hade tio horn och sju huvuden, och på sina horn hade det tio kronor och på sina huvuden hädiska namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 2, 'Och vilddjuret, som jag såg, liknade en panter, men det hade fötter såsom en björn och gap såsom ett lejon. Och draken gav det sin makt och sin tron och gav det stor myndighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 3, 'Och jag såg ett av dess huvuden vara likasom sårat till döds, men dess dödssår blev läkt. Och hela jorden såg med förundran efter vilddjuret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 4, 'Och de tillbådo draken, därför att han hade givit vilddjuret sådan myndighet; de tillbådo och vilddjuret och sade »Vem är lik vilddjuret, och vem kan strida mot det?»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 5, 'Och det fick en mun sig given, som talade stora ord och vad hädiskt var, och det fick makt att så göra under fyrtiotvå månader.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 6, 'Och den öppnade sin mun till att föra hädiskt tal mot Gud, till att häda hans namn och hans tabernakel och dem som bo i himmelen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 7, 'Och det fick makt att föra krig mot de heliga och att övervinna dem; och det fick makt över alla stammar och folk och tungomål och folkslag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 8, 'Och alla jordens inbyggare skola tillbedja det, ja, envar som icke har sitt namn från världens begynnelse skrivet i livets bok, det slaktade Lammets bok.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 9, 'Den som har öra, han höre.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 10, 'Den som för andra bort i fångenskap, han skall själv bliva bortförd i fångenskap; den som dräper andra med svärd, han skall själv bliva dräpt med svärd. Här gäller det för de heliga att hava ståndaktighet och tro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 11, 'Och jag såg ett annat vilddjur stiga upp ur jorden; det hade två horn, lika ett lamms, och det talade såsom en drake.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 12, 'Och det utövar det första vilddjurets hela myndighet, i dess åsyn. Och det kommer jorden och dem som bo därpå att tillbedja det första vilddjuret, det vars dödssår blev läkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 13, 'Och det gör stora tecken, så att det till och med låter eld i människornas åsyn falla ned från himmelen på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 14, 'Och genom de tecken, som det har fått makt att göra i vilddjurets åsyn, förvillar det jordens inbyggare; det förmår genom sitt tal jordens inbyggare att göra en bild åt vilddjuret, det som var sårat med svärd, men åter kom till liv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 15, 'Och det fick makt att giva ande åt vilddjurets bild, så att vilddjurets bild till och med kunde tala och kunde låta döda alla som icke tillbådo vilddjurets bild.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 16, 'Och det förmår alla, både små och stora, både rika och fattiga, både fria och trälar, att låta giva sig ett märke på högra handen eller på pannan,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 17, 'så att ingen får vare sig köpa eller sälja något, utom den som är märkt med vilddjurets namn eller dess namns tal.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 18, 'Här gäller det att vara vis; den som har förstånd, han räkne ut betydelsen av vilddjurets tal, ty det är en människas tal. Och dess tal är sex hundra sextiosex.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 1, 'Och jag fick se Lammet stå på Sions berg jämte det ett hundra fyrtiofyra tusen som hade dess namn och dess Faders namn skrivna på sina pannor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 2, 'Och jag hörde ett ljud från himmelen, likt bruset av stora vatten och dånet av ett starkt tordön; och ljudet som jag hörde var såsom när harpospelare spela på sina harpor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 3, 'Och de sjöngo inför tronen och inför de fyra väsendena och de äldste vad som tycktes vara en ny sång; och ingen kunde lära sig den sången, utom de ett hundra fyrtiofyra tusen som voro friköpta ifrån jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 4, 'Dessa äro de som icke hava orenat sig med kvinnor; ty de äro såsom jungfrur. Dessa äro de som följa Lammet varthelst det går. De hava blivit friköpta ifrån människorna till en förstling åt Gud och Lammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 5, 'Och i deras mun har ingen lögn blivit funnen; de äro ostraffliga.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 6, 'Och jag såg en annan ängel flyga fram uppe i himlarymden; han hade ett evigt evangelium, som han skulle förkunna för dem som bo på jorden, för alla folkslag och stammar och tungomål och folk.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 7, 'Och han sade med hög röst: »Frukten Gud och given honom ära; ty stunden är kommen, då han skall hålla dom. Ja, tillbedjen honom som har skapat himmel och jord och hav och vattenkällor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 8, 'Och ännu en annan ängel följde honom; denne sade: »Fallet, fallet är det stora Babylon, som har givit alla folk att dricka av sin otukts vredesvin.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 9, 'Och ännu en tredje ängel följde dem; denne sade med hög röst: »Om någon tillbeder vilddjuret och dess bild och tager dess märke på sin panna eller på sin hand,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 10, 'så skall ock han få dricka av Guds vredesvin, det som är iskänkt i hans vredes kalk, obemängt; och han skall bliva plågad med eld och svavel, i heliga änglars och i Lammets åsyn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 11, 'Och när de så plågas, uppstiger röken därav i evigheters evigheter, och de hava ingen ro, vaken dag eller natt, de som tillbedja vilddjuret och dess bild, eller som låta märka sig med dess namn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 12, 'Här gäller det för de heliga att hava ståndaktighet, för dem som hålla Guds bud och bevara tron på Jesus.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 13, 'Och jag hörde en röst från himmelen säga: »Skriv: Saliga äro de döda som dö i Herren härefter. Ja, säger Anden, de skola få vila sig från sitt arbete, ty deras gärningar följa dem.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 14, 'Och jag fick se en vit sky, och på skyn satt en som liknade en människoson; och han hade på sitt huvud en gyllene krans, och i sin hand en vass lie.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 15, 'Och en annan ängel kom ut ur templet och ropade med hög röst till den som satt på skyn: »Låt din lie gå, och inbärga skörden; ty skördetiden är kommen, och säden på jorden är fullt mogen till skörd.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 16, 'Den som satt på skyn högg då till med sin lie på jorden, och jorden blev avbärgad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 17, 'Och en annan ängel kom ut ur templet i himmelen, och jämväl han hade en vass lie.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 18, 'Och ännu en ängel kom fram ifrån altaret, den som hade makt över elden. Denne ropade med hög röst till den som hade den vassa lien; han sade »Låt din vassa lie gå, och skär av druvklasarna från vinträden på jorden, ty deras druvor äro fullmogna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 19, 'Och ängeln högg till med sin lie på jorden och skar av frukten ifrån vinträden på jorden och kastade den i Guds vredes stora vinpress.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 20, 'Och vinpressen trampade utanför staden, och blod gick ut från pressen och steg ända upp till betslen på hästarna, på en sträcka av ett tusen sex hundra stadier.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 1, 'Och jag såg ett annat tecken i himmelen, stort och underbart; sju änglar med de sju plågor som bliva de sista, ty med dem är Guds vredesdom fullbordad.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 2, 'Och jag fick se något som såg ut såsom ett glashav, blandat med eld. Och jag såg dem som hade vunnit seger över vilddjuret, med dess bild och dess namns tal, stå vid glashavet, med Guds harpor i sina händer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 3, 'Och de sjöngo Moses\', Guds tjänares, sång och Lammets sång: de sjöngo: »Stora och underbara äro dina verk, Herre Gud, du Allsmäktige; rättfärdiga och rätta äro dina vägar, du folkens konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 4, 'Vem skulle icke frukta dig, Herre, och prisa ditt namn? Du allena är helig, och alla folk skola komma och tillbedja inför dig. Ty dina domar hava blivit uppenbara.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 5, 'Sedan såg jag att vittnesbördets tabernakels tempel i himmelen öppnades.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 6, 'Och de sju änglarna med de sju plågorna kommo ut ur templet, klädda i rent, skinande linne, och omgjordade kring bröstet med gyllene bälten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 7, 'Och ett av de fyra väsendena gav de sju änglarna sju gyllene skålar, fulla av Guds vrede, hans som lever i evigheternas evigheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 8, 'Och templet blev uppfyllt av rök från Guds härlighet och från hans makt, och ingen kunde gå in i templet, förrän de sju änglarnas sju plågor hade fått sin fullbordan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 1, 'Och jag hörde en stark röst från templet säga till de sju änglarna: »Gån åstad och gjuten ut Guds sju vredesskålar på jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 2, 'Och den förste gick åstad och göt ut sin skål på jorden. Då kommo onda och svåra sårnader på de människor som buro vilddjurets märke och tillbådo dess bild.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 3, 'Och den andre göt ut sin skål i havet. Då förvandlades det till blod, likt blodet av en död människa, och alla levande varelser i havet dogo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 4, 'Och den tredje göt ut sin skål i strömmarna och vattenkällorna. Då förvandlades dessa till blod.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 5, 'Och jag hörde vattnens ängel säga: »Rättfärdig är du, du som är och som var, du helige, som har dömt så.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 6, 'De hava utgjutit heliga mäns och profeters blod. Därför har ock du givit dem blod att dricka; de äro det värda.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 7, 'Och jag hörde altaret säga: »Ja, Herre Gud, du Allsmäktige, rätta och rättfärdiga äro dina domar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 8, 'Och den fjärde göt ut sin skål över solen. Då fick denna makt att bränna människorna såsom med eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 9, 'Och när nu människorna blevo brända av stark hetta, hädade de Guds namn, hans som hade makten över dessa plågor; de gjorde icke bättring och gåvo honom icke ära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 10, 'Och den femte göt ut sin skål över vilddjurets tron. Då blev dess rike förmörkat, och människorna beto sönder sina tungor i sin vånda.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 11, 'Och de hädade himmelens Gud för sin våndas och sina sårnaders skull; de gjorde icke bättring och upphörde icke med sina gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 12, 'Och den sjätte göt ut sin skål över den stora floden Eufrat. Då torkade dess vatten ut, för att väg skulle beredas åt konungarna från östern.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 13, 'Och ur drakens gap och ur vilddjurets gap och ur den falske profetens mun såg jag tre orena andar utgå, lika paddor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 14, 'De äro nämligen onda andar som göra tecken, och som gå ut till konungarna i hela världen, för att samla dem till striden på Guds, den Allsmäktiges, stora dag.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 15, '(»Se, jag kommer såsom en tjuv; salig är den som vakar och bevarar sina kläder, så att han icke måste gå naken, och man får se hans skam.»)');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 16, 'Och de församlade dem till den plats som på hebreiska heter Harmagedon.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 17, 'Och den sjunde göt ut sin skål i luften. Då gick en stark röst ut från tronen i templet och sade »Det är gjort.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 18, 'Och nu kommo ljungeldar och dunder och tordön, och det blev en stor jordbävning, en jordbävning så våldsam och så stor, att dess like icke hade förekommit, alltsedan människor blevo till på jorden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 19, 'Och den stora staden rämnade sönder i tre delar, och folkens städer störtade samman; och Gud kom ihåg det stora Babylon, så att han räckte det kalken med sin stränga vredes vin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 20, 'Och alla öar flydde, och inga berg funnos mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 21, 'Och stora hagel, centnertunga, föllo ned från himmelen på människorna; och människorna hädade Gud för den plåga som haglen vållade, ty den plågan var mycket stor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 1, 'Och en av de sju änglarna med de sju skålarna kom och talade med mig och sade: »Kom hit, så skall jag visa dig, huru den stora skökan får sin dom, hon som tronar vid stora vatten,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 2, 'hon som jordens konungar hava bedrivit otukt med och av vilkens otukts vin jordens inbyggare hava druckit sig druckna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 3, 'Sedan förde han mig i anden bort till en öken. Där såg jag en kvinna som satt på ett scharlakansrött vilddjur, fulltecknat med hädiska namn; och det hade sju huvuden och tio horn.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 4, 'Och kvinnan var klädd i purpur och scharlakan och glänste av guld och ädla stenar och pärlor; och i sin hand hade hon en gyllene kalk, full av styggelser och av hennes otukts orenlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 5, 'Och på hennes panna var skrivet ett namn med hemlig betydelse: »Det stora Babylon, hon som är moder till skökorna och till styggelserna på jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 6, 'Och jag såg kvinnan vara drucken av de heligas blod och av Jesu vittnens blod. Och jag förundrade mig storligen, när jag såg henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 7, 'Och ängeln sade till mig: »Varför förundrar du dig? Jag skall säga dig hemligheten om kvinnan, och om vilddjuret som bär henne, och som har de sju huvudena och de tio hornen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 8, 'Vilddjuret som du har sett, det har varit, och är icke mer; men det skall stiga upp ur avgrunden, och det går sedan i fördärvet. Och de av jordens inbyggare, vilkas namn icke från världens begynnelse äro skrivna i livets bok, skola förundra sig, när de få se vilddjuret som har varit, och icke mer är, men dock skall komma. --');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 9, 'Här gäller det att äga ett förstånd med vishet. De sju huvudena äro sju berg, som kvinnan tronar på. De äro ock sju konungar;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 10, 'fem av dem hava fallit, en är, och den återstående har ännu icke kommit, och när han kommer, skall han bliva kvar en liten tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 11, 'Och vilddjuret som har varit, och icke mer är, det är självt den åttonde, och dock en av de sju, och det går i fördärvet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 12, 'Och de tio horn som du har sett, de äro tio konungar, som ännu icke hava kommit till konungavälde, men som för en kort tid, tillika med vilddjuret, få makt såsom konungar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 13, 'Dessa hava ett och samma sinne, och de giva sin makt och myndighet åt vilddjuret.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 14, 'De skola giva sig i strid med Lammet; men Lammet jämte de kallade och utvalda och trogna som följa det, skall övervinna dem, ty Lammet är herrarnas herre och konungarnas konung.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 15, 'Och han sade ytterligare till mig: »Vattnen som du har sett, där varest skökan tronar, äro folk och människoskaror och folkslag och tungomål.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 16, 'Och de tio horn, som du har sett, och vilddjuret, de skola hata skökan och göra henne utblottad och naken, och skola äta hennes kött och bränna upp henne i eld.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 17, 'Ty Gud har ingivit dem i hjärtat att de skola utföra vad han har i sinnet, och att de alla skola handla i ett och samma sinne, och att de skola giva sitt välde åt vilddjuret, till dess Guds utsagor hava fullbordats.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 18, 'Och kvinnan som du har sett är den stora staden, som har konungsligt välde över jordens konungar.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 1, 'Därefter såg jag en annan ängel komma ned från himmelen; han hade stor makt, och jorden upplystes av hans härlighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 2, 'Och han ropade med stark röst och sade: »Fallet, fallet är det stora Babylon; det har blivit en boning för onda andar, ett tillhåll för alla slags orena andar och ett tillhåll för alla slags orena och vederstyggliga fåglar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 3, 'Ty av hennes otukts vredesvin hava alla folk druckit; konungarna på jorden hava bedrivit otukt med henne, och köpmännen på jorden hava skaffat sig rikedom genom hennes omåttliga vällust.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 4, 'Och jag hörde en annan röst från himmelen säga: »Dragen ut ifrån henne, I mitt folk, så att I icke gören eder delaktiga i hennes synder och fån eder del av hennes plågor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 5, 'Ty hennes synder räcka ända upp till himmelen, och Gud har kommit ihåg hennes orättfärdiga gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 6, 'Vedergällen henne vad hon har gjort, ja, given henne dubbelt igen för hennes gärningar; iskänken dubbelt åt henne i den kalk vari hon har iskänkt.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 7, 'Så mycken ära och vällust som hon har berett sig, så mycken pina och sorg mån I bereda henne. Eftersom hon säger i sitt hjärta: \'Jag tronar såsom drottning och och sitter icke såsom änka, och aldrig skall jag veta av någon sorg\',');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 8, 'därför skola på en och samma dag hennes plågor komma över henne: död och sorg och hungersnöd; och hon skall brännas upp i eld. Ty stark är Herren Gud, han som har dömt henne.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 9, 'Och jordens konungar, som hava bedrivit otukt och levat i vällust med henne, skola gråta och jämra sig över henne, när de se röken av hennes brand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 10, 'De skola stå långt ifrån, av förfäran över hennes pina, och skola säga: \'Ve, ve dig, Babylon, du stora stad, du starka stad! Plötsligt har nu din dom kommit.\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 11, 'Och köpmännen på jorden gråta och sörja över henne, då nu ingen mer köper de varor som de frakta:');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 12, 'guld och silver, ädla stenar och pärlor, fint linne och purpur, siden och scharlakan, allt slags välluktande trä, alla slags arbeten av elfenben och dyrbaraste trä, av koppar och järn och marmor,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 13, 'därtill kanel och kostbar salva, rökverk, smörjelse och välluktande harts, vin och olja, fint mjöl och vete, fäkreatur och får, hästar och vagnar, livegna och trälar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 14, 'De frukter som din själ hade begär till hava försvunnit ifrån dig; allt vad kräsligt och präktigt du hade har gått förlorat för dig och skall aldrig mer bliva funnet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 15, 'De som handlade med sådant, de som skaffade sig rikedom genom henne, de skola stå långt ifrån, av förfäran över hennes pina; de skola gråta och sörja');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 16, 'och skola säga: \'Ve, ve dig, du stora stad, du som var klädd i fint linne och purpur och scharlakan, du som glänste av guld och ädla stenar och pärlor!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 17, 'I ett ögonblick har nu denna stora rikedom blivit förödd.\' Och alla skeppare och alla kustfarare och sjömän och alla andra som hava sitt arbete på havet stå långt ifrån;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 18, 'och när de ser röken av hennes brand, ropa de och säga: \'Var fanns den stora stadens like?\'');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 19, 'Och de strö stoft på sina huvuden och ropa under gråt och sorg och säga: \'Ve, ve dig, du stora stad, genom vars skatter alla de därinne, som hade skepp på havet, blevo rika! I ett ögonblick har den nu blivit förödd.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 20, 'Gläd dig över vad som har vederfarits henne, du himmel och I helige och I apostlar och profeter, då nu Gud har hållit dom över henne och utkrävt vedergällning för eder!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 21, 'Och en väldig ängel tog upp en sten, lik en stor kvarnsten, och kastade den i havet och sade: »Så skall Babylon, den stora staden, med fart störtas ned och aldrig mer bliva funnen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 22, 'Av harpospelare och sångare, av flöjtblåsare och basunblåsare skall aldrig mer något ljud bliva hört i dig; aldrig mer skall någon konstförfaren man av något slags yrke finnas i dig; bullret av en kvarn skall aldrig mer höras i dig;');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 23, 'en lampas sken skall aldrig mer lysa i dig; rop för brudgum och brud skall aldrig mer höras i dig -- du vars köpmän voro stormän på jorden, du genom vars trolldom alla folk blevo förvillade,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 24, 'och i vilken man såg profeters och heliga mäns blod, ja, alla de människors blod, som hade blivit slaktade på jorden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 1, 'Sedan hörde jag likasom starka röster av en stor skara i himmelen, som sade »Halleluja! Frälsningen och äran och makten tillhöra vår Gud.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 2, 'Ty rätta och rättfärdiga äro hans domar; han har dömt den stora skökan, som fördärvade jorden genom sin otukt, och han har utkrävt sina tjänares blod av hennes hand.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 3, 'Och åter sade de: »Halleluja!» Och röken från henne stiger upp i evigheternas evigheter!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 4, 'Och de tjugufyra äldste och de fyra väsendena föllo ned och tillbådo Gud, som satt på tronen; de sade: »Amen! Halleluja!»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 5, 'Och från tronen utgick en röst, som sade: »Loven vår Gud, alla I hans tjänare, I som frukten honom, både små och stora.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 6, 'Och jag hörde likasom röster av en stor skara, lika bruset av stora vatten och dånet av starka tordön; de sade: »Halleluja! Herren, vår Gud, den Allsmäktige, har nu trätt fram såsom konung.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 7, 'Låtom oss glädjas och fröjda oss och giva honom äran; ty tiden är inne för Lammets bröllop, och dess brud har gjort sig redo.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 8, 'Och åt henne har blivit givet att kläda sig i fint linne, skinande och rent.» Det fina linnet är de heligas rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 9, 'Och han sade till mig: »Skriv: Saliga äro de som äro bjudna till Lammets bröllopsmåltid.» Ytterligare sade han till mig: »Dessa ord äro sanna Guds ord.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 10, 'Och jag föll ned för hans fötter för att tillbedja honom, men han sade till mig: »Gör icke så. Jag är din medtjänare och dina bröders, deras som hava Jesu vittnesbörd. Gud skall du tillbedja. Ty Jesu vittnesbörd är profetians ande.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 11, 'Och jag såg himmelen öppen och fick där se en vit häst; och mannen som satt på den heter »Trofast och sannfärdig», och han dömer och strider i rättfärdighet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 12, 'Hans ögon voro såsom eldslågor, och på sitt huvud bar han många kronor och hade ett namn där skrivet, som ingen känner utom han själv.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 13, 'Och han var klädd i en mantel som var doppad i blod; och det namn han har fått är »Guds Ord».');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 14, 'Och honom följde, på vita hästar, de himmelska härskarorna, klädda i fint linne, vitt och rent.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 15, 'Och från hans mun utgick ett skarpt svärd, varmed han skulle slå folken. Och han skall styra dem med järnspira; och han trampar Guds, den Allsmäktiges, stränga vredes vinpress.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 16, 'Och på sin mantel, över sin länd, har han detta namn skrivet: »Konungarnas konung och herrarnas herre.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 17, 'Och jag såg en ängel stå i solen, och denne ropade med hög röst och sade till alla fåglar som flögo fram uppe i himlarymden: »Kommen hit, församlen eder till Guds stora gästabud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 18, 'för att äta kött av konungar och krigsöverstar och hjältar, kött av hästar och deras ryttare, ja, kött av alla, både fria och trälar, både små och stora.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 19, 'Och jag såg vilddjuret och konungarna på jorden med sina härskaror, samlade för att utkämpa sin strid mot honom som satt på hästen och mot hans härskara.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 20, 'Och vilddjuret blev gripet, därjämte ock den falske profeten, som i dess åsyn hade gjort de tecken med vilka han hade förvillat dem som hade tagit vilddjurets märke, och dem som hade tillbett dess bild. Båda blevo de levande kastade i eldsjön, som brann med svavel.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 21, 'Och de andra blevo dräpta med ryttarens svärd, det som utgick från hans mun; och alla fåglar blevo mättade av deras kött.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 1, 'Och jag såg en ängel komma ned från himmelen; han hade nyckeln till avgrunden och hade en stor kedja i sin hand.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 2, 'Och han grep draken, den gamle ormen, det är djävulen och Satan, och fängslade honom för tusen år');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 3, 'och kastade honom i avgrunden och stängde igen och satte dit ett insegel över honom på det att han icke mer skulle förvilla folken, förrän de tusen åren hade gått till ända. Därefter skall han åter komma lös för en liten tid.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 4, 'Och jag såg troner stå där, och de satte sig på dem, de åt vilka gavs makt att hålla dom. Och jag såg de människors själar, som hade blivit halshuggna för Jesu vittnesbörds och Guds Ords skull, och som icke hade tillbett vilddjuret eller dess bild, och icke heller tagit dess märke på sina pannor och sina händer; dessa blevo nu åter levande och fingo regera med Kristus i tusen år.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 5, '(De övriga döda blevo icke levande, förrän de tusen åren hade gått till ända.) Detta är den första uppståndelsen.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 6, 'Salig och helig är den som har del i den första uppståndelsen; över dem har den andra döden ingen makt, utan de skola vara Guds och Kristi präster och skola få regera med honom de tusen åren.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 7, 'Men när de tusen åren hava gått till ända, skall Satan komma lös ur sitt fängelse.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 8, 'Han skall då gå ut för att förvilla de folk som bo vid jordens fyra hörn, Gog och Magog, och samla dem till den stundande striden; och de äro till antalet såsom sanden i havet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 9, 'Och de draga fram över jordens hela vidd och omringa de heligas läger och »den älskade staden»; men eld faller ned från himmelen och förtär dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 10, 'Och djävulen, som förvillade dem, bliver kastad i samma sjö av eld och svavel, dit vilddjuret och den falske profeten hade blivit kastade; och de skola där plågas dag och natt i evigheternas evigheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 11, 'Och jag såg en stor vit tron och honom som satt därpå; och för hans ansikte flydde jord och himmel, och ingen plats blev funnen för dem.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 12, 'Och jag såg de döda, både stora och små, stå inför tronen, och böcker blevo upplåtna. Och jämväl en annan bok blev upplåten; det var livets bok. Och de döda blevo dömda efter sina gärningar, på grund av det som var upptecknat i böckerna.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 13, 'Och havet gav igen de döda som voro däri, och döden och dödsriket gåvo igen de döda som voro i dem; och dessa blev dömda, var och en efter sina gärningar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 14, 'Och döden och dödsriket blevo kastade i den brinnande sjön; detta, den brinnande sjön, är den andra döden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 15, 'Och om någon icke fanns skriven i livets bok, så blev han kastad i den brinnande sjön.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 1, 'Och jag såg en ny himmel och en ny jord; ty den förra himmelen och den förra jorden voro förgångna, och havet fanns icke mer.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 2, 'Och jag såg den heliga staden, ett nytt Jerusalem, komma ned från himmelen, från Gud, färdigsmyckad såsom en brud som är prydd för sin brudgum.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 3, 'Och jag hörde en stark röst från tronen säga: »Se, nu står Guds tabernakel bland människorna, och han skall bo ibland dem, och de skola vara hans folk; ja, Gud själv skall vara hos dem');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 4, 'och skall avtorka alla tårar från deras ögon. Och döden skall icke mer vara till, och ingen sorg eller klagan eller plåga skall vara mer; ty det som förr var är nu förgånget.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 5, 'Och han som satt på tronen sade: »Se, jag gör allting nytt.» Ytterligare sade han: »Skriv: ty dessa ord äro visa och sanna.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 6, 'Han sade vidare till mig: »Det är gjort. Jag är A och O[1], begynnelsen och änden. Åt den som törstar skall jag giva att dricka för intet ur källan med livets vatten.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 7, 'Den som vinner seger, han skall få detta till arvedel, och jag skall vara hans Gud, och han skall vara min son.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 8, 'Men de fega och de otrogna, och de som hava gjort vad styggeligt är, och dråpare och otuktiga människor och trollkarlar och avgudadyrkare och alla lögnare skola få sin del i den sjö som brinner med eld och svavel; detta är den andra döden.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 9, 'Och en av de sju änglarna med de sju skålar, som voro fulla med de sju sista plågorna, kom och talade till mig och sade: »Kom hit, så skall jag visa dig bruden, Lammets hustru.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 10, 'Och han förde mig i anden åstad upp på ett stort och högt berg och visade mig den heliga staden Jerusalem, som kom ned från himmelen, från Gud,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 11, 'med Guds härlighet. Den glänste likt den dyrbaraste ädelsten, den var såsom kristallklar jaspis.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 12, 'Den hade en stor och hög mur med tolv portar, och vid portarna stodo tolv änglar, och över portarna voro skrivna namn: namnen på Israels barns tolv stammar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 13, 'I öster voro tre portar, i norr tre portar, i söder tre portar och i väster tre portar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 14, 'Och stadsmuren hade tolv grundstenar, och på dem stodo tolv namn: namnen på Lammets tolv apostlar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 15, 'Och han som talade till mig hade en gyllene mätstång för att därmed mäta staden och dess portar och dess mur.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 16, 'Och staden utgjorde en fyrkant, och dess längd var lika stor som dess bredd. Och med stången mätte han staden: dess mått var tolv tusen stadier, dess längd och bredd och höjd voro lika.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 17, 'Och han mätte dess mur: den var ett hundra fyrtiofyra alnar efter människors mått, som ock är änglars.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 18, 'Och stadsmuren var byggd av jaspis, men staden själv var av rent guld, likt rent glas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 19, 'Stadsmurens grundstenar voro skönt lagda och utgjordes av alla slags ädelstenar. Den första grundstenen var en jaspis, den andra en safir, den tredje en kalcedon, den fjärde en smaragd,');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 20, 'den femte en sardonyx, den sjätte en karneol, den sjunde en krysolit, den åttonde den beryll, den nionde en topas, den tionde en krysopras, den elfte en hyacint, den tolfte en ametist.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 21, 'Och de tolv portarna utgjordes av tolv pärlor; var särskild port utgjordes av en enda pärla. Och stadens gata var av rent guld, likt genomskinligt glas.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 22, 'Och jag såg i den intet tempel, ty Herren Gud, den Allsmäktige, är dess tempel, han och Lammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 23, 'Och staden behöver icke sol eller måne till att lysa där, ty Guds härlighet upplyser den och dess ljus är Lammet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 24, 'Och folken skola vandra i dess ljus, och jordens konungar föra ditin, vad härligt de hava.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 25, 'Dess portar skola aldrig stängas om dagen -- natt skall icke finnas där');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 26, 'och vad härligt och dyrbart folken hava skall man föra ditin.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 27, 'Men intet orent skall någonsin komma ditin, och ingen som gör vad styggeligt är och lögn, utan allenast de som äro skrivna i livets bok, Lammets bok. [1] Se A och O i Ordförkl.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 1, 'Och han visade mig en ström med vatten, klar som kristall. Den gick ut från Guds och Lammets tron');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 2, 'och flöt fram mitt igenom stadens gata. Och på båda sidor om strömmen stodo livsträd, som gåvo tolv skördar, ty de buro frukt var månad; och trädens löv tjänade till läkedom för folken.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 3, 'Och ingen förbannelse skall vara mer. Och Guds och Lammets tron skall stå där inne, och hans tjänare skall tjäna honom');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 4, 'och skola se hans ansikte; och hans namn skall stå tecknat på deras pannor.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 5, 'Och ingen natt skall vara mer; och de behöva icke någon lampas ljus, ej heller solens ljus, ty Herren Gud skall lysa över dem, och de skola regera i evigheternas evigheter.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 6, 'Och han sade till mig: »Dessa ord äro vissa och sanna; och Herren, profeternas andars Gud, har sänt sin ängel för att visa sina tjänare, vad som snart skall ske.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 7, 'Och se, jag kommer snart. Salig är den som tager vara på de profetians ord som stå i denna bok.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 8, 'Och jag, Johannes, var den som hörde och såg detta. Och när jag hade hört och sett det, föll jag ned för att tillbedja inför ängelns fötter, hans som visade mig detta.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 9, 'Men han sade till mig: »Gör icke så. Jag är din medtjänare och dina bröders, profeternas, och deras som taga vara på denna boks ord. Gud skall du tillbedja.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 10, 'Och han sade till mig: »Göm icke under något insegel de profetians ord som stå i denna bok; ty tiden är nära.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 11, 'Må den som är orättfärdig fortfara att öva sin orättfärdighet och den som är oren att orena sig. Så ock den som är rättfärdig, han fortfare att öva sin rättfärdighet, och den som är helig att helga sig.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 12, 'Se, jag kommer snart och har med mig min lön, för att vedergälla var och en efter som hans gärningar äro.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 13, 'Jag är A och O[1], den förste och den siste, begynnelsen och änden.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 14, 'Saliga äro de som två sina kläder för att få rätt att äta av livets träd och att gå in i staden genom dess portar.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 15, 'Men de som äro hundar och trollkarlar och otuktiga och dråpare och avgudadyrkare och alla som älska och göra lögn, de måste alla stanna därutanför.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 16, 'Jag, Jesus, har sänt min ängel för att i församlingarna vittna om detta för eder. Jag är telningen från Davids rot och kommen av hans släkt, jag är den klara morgonstjärnan.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 17, 'Och Anden och bruden säga: »Kom.» Och den som hör det, han säge »Kom.» Och den som törstar, han komme; ja den som vill, han tage livets vatten för intet.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 18, 'För var och en som hör de profetians ord, som stå i denna bok betygar jag detta: »Om någon lägger något till dem, så skall Gud på honom lägga de plågor om vilka är skrivet i denna bok.');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 19, 'Och om någon tager bort något från de ord som stå i denna profetias bok, så skall Gud taga ifrån honom hans del i livets träd och i den heliga staden, om vilka är skrivet i denna bok.»');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 20, 'Han som betygar detta säger: »Ja, jag kommer snart.» Amen. Kom Herre Jesus!');
INSERT INTO `Swe1917_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 21, 'Herren Jesu nåd vare med alla. [1] Se A och O i Ordförkl.');
